(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["産業2次"]=[{"id":"00013015","register_sub_id":"101","register_pk":"368328","name":"大野家住宅主屋（旧大野組事務所兼主屋）","kana":"おおのけじゅうたくしゅおく（きゅうおおのぐみじむしょけんしゅおく）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道士別市大通西一丁目1918-5他","lat":44.17975833,"lng":142.39013333,"geo_status":"db","era":"昭和2年／昭和13年頃増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"01 － 0158","desc":"市中心部にある旧家の住宅。主屋は敷地西辺中央に西面して建つ木造平屋建で、正面中央に入母屋造の玄関を付す。内部は前後二列に三室ずつ並べ、北側に床を備えた座敷などを、南側に応接室などの洋室を配す。和風民家への洋室導入の有り様を伝える上質な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013015"},{"id":"00012673","register_sub_id":"101","register_pk":"367577","name":"旧肥田製陶工場（ＥＢＲＩ）","kana":"きゅうひだせいとうこうじょう（えぶり）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道江別市東野幌町3-3他","lat":43.09551083,"lng":141.53537694,"geo_status":"db","era":"昭和26年頃／平成27年改修、昭和28年頃増築","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"煉瓦造及び鉄筋コンクリート造平屋建、金属板葺、建築面積1300㎡","structure_material":"煉瓦造及び鉄筋コンクリート造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"01 － 153","desc":"窯業で栄えた市中心部にある旧窯業工場。切妻造鉄板葺の平屋建、Ｔ字型平面の煉瓦造にＬ字型平面の鉄筋コンクリート造の増築部を連ねた不整形な建物で、増築部の壁を煉瓦積として一体感のある外観をつくる。近代江別の象徴的存在で、地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012673"},{"id":"00005703","register_sub_id":"101","register_pk":"106691","name":"旧北炭夕張炭鉱専用鉄道高松跨線橋","kana":"きゅうほくたんゆうばりたんこうせんようてつどうたかまつこせんきょう","category":"産業2次","subcategory":"土木構造物","type_guess":"橋","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道夕張市高松","lat":43.06576431,"lng":141.98820904,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造単アーチ橋、橋長22m、幅員2.4m","structure_material":"鉄筋コンクリート造単アーチ橋","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0070","desc":"夕張鉄道に接続する旧炭鉱専用鉄道に架かる跨線橋で，中心市街地の東方に位置する。橋長２２ｍ，幅員２．４ｍ規模の開腹式鉄筋コンクリート造単アーチ橋で，地盤高の異なる地点を結ぶために橋桁を傾斜させ，特徴ある外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005703"},{"id":"00005708","register_sub_id":"101","register_pk":"106696","name":"旧北炭夕張炭鉱高松ズリ捨線拱橋","kana":"きゅうほくたんゆうばりたんこうたかまつずりすてせんこうきょう","category":"産業2次","subcategory":"土木構造物","type_guess":"橋","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道夕張市高松","lat":43.063839,"lng":141.991425,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造7連アーチ橋、橋長59m、幅員8.6m","structure_material":"鉄筋コンクリート造7連アーチ橋","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0074","desc":"天龍坑坑口より約４３０ｍ南東に位置する。橋長５９ｍ，幅員８．６ｍ規模の鉄筋コンクリート造７連アーチ橋。各アーチは半円形で，スパン６．０ｍとする。坑内や選鉱場等で生じるズリを夕張市内最大のズリ山に搬出するために築かれた高松ズリ捨線の設備。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005708"},{"id":"00005709","register_sub_id":"101","register_pk":"106697","name":"旧北炭夕張炭鉱高松ズリ捨線スキップ隧道","kana":"きゅうほくたんゆうばりたんこうたかまつずりすてせんすきっぷずいどう","category":"産業2次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道夕張市高松","lat":43.06359893,"lng":141.99933021,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"コンクリート造、延長73m","structure_material":"コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0075","desc":"高松ズリ捨線拱橋の約１４０ｍ東方に位置する。延長７３ｍ，幅５．５ｍ規模の直線状のコンクリート造隧道で，両端にはコンクリート造の坑門を構える。建設当初，スキップと呼ばれる特殊な鉄製炭車が走行したことから，今もスキップ隧道の名で親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005709"},{"id":"00005716","register_sub_id":"101","register_pk":"106704","name":"旧北炭夕張炭鉱高松ズリ捨線ベルト隧道西坑門","kana":"きゅうほくたんゆうばりたんこうたかまつずりすてせんべるとずいどうにしこうもん","category":"産業2次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道夕張市社光","lat":43.0653725,"lng":141.98647481,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"コンクリート造、幅8.9m","structure_material":"コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0076","desc":"高松ズリ捨線拱橋の約５００ｍ西方に位置する。直径２．５ｍの半円アーチ断面形状を有する隧道の西端のコンクリート造坑門で，幅８．９ｍ，高さ３．３ｍとする。内部にベルトコンベヤーが設けられていたことからベルト隧道の名で親しまれる施設の一部。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005716"},{"id":"00005705","register_sub_id":"101","register_pk":"106693","name":"旧北炭夕張炭鉱天龍坑資材斜坑坑口","kana":"きゅうほくたんゆうばりたんこうてんりゅうこうしざいしゃこうこうぐち","category":"産業2次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道夕張市高松","lat":43.06638466,"lng":141.98793634,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造、幅7.2m","structure_material":"煉瓦造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0072","desc":"人車斜坑坑口の東方に位置する。煉瓦５枚厚，スパン４ｍの半円アーチを築き，壁面にはピラスター，コーニス等や，「天龍坑」と陰刻された扁額を付ける。人車斜坑坑口と共に，北炭夕張鉱業所管内で最大級の採炭量を誇った第二鉱区における代表的遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005705"},{"id":"00005704","register_sub_id":"101","register_pk":"106692","name":"旧北炭夕張炭鉱天龍坑人車斜坑坑口","kana":"きゅうほくたんゆうばりたんこうてんりゅうこうじんしゃしゃこうこうぐち","category":"産業2次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道夕張市高松","lat":43.06630393,"lng":141.98786842,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造、幅11m","structure_material":"煉瓦造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0071","desc":"高松跨線橋の約６５ｍ北方に位置する。当初，第三斜坑と呼ばれた煉瓦造斜坑の坑口の一つ。錐形に盛り上げた石材を要石に用いた煉瓦４枚厚，スパン２．５ｍの半円アーチを築き，ピラスター，コーニス等を付けた壁面の左右に翼部を張り出す堂々とした構え。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005704"},{"id":"00005707","register_sub_id":"101","register_pk":"106695","name":"旧北炭夕張炭鉱模擬坑道","kana":"きゅうほくたんゆうばりたんこうもぎこうどう","category":"産業2次","subcategory":"土木構造物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道夕張市高松","lat":43.06641985,"lng":141.98854859,"geo_status":"db","era":"明治後期／昭和初期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造及びコンクリート造、延長180m、補強鉄骨付","structure_material":"煉瓦造及びコンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0073","desc":"資材斜坑坑口の約４０ｍ東方に位置する。天龍坑の補助的な坑道を一部利用して，見学用及び鉱員養成用に整備した施設。斜坑と水平坑道を組み合わせた，延長１８０ｍの煉瓦造アーチ坑道を，古レールを用いて一部補強したもので，今も公開施設として利用される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005707"},{"id":"00005720","register_sub_id":"101","register_pk":"106708","name":"小林酒造一番蔵","kana":"こばやししゅぞういちばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.0615049,"lng":141.76960571,"geo_status":"db","era":"明治33／大正7増築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積473㎡","structure_material":"煉瓦造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0081","desc":"敷地中央に東西棟で建つ。桁行２６間，梁間６間の規模で，煉瓦造平屋建，切妻造，鉄板葺とする。東西に各１箇所，北側に４箇所の出入口を設ける。小屋はキングポストトラスとする。酒造所最大の蔵で，軒蛇腹にデンティルを設けるが，意匠は全体に質素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005720"},{"id":"00005719","register_sub_id":"101","register_pk":"106707","name":"小林酒造旧資材庫（昔の酒道具展示館）","kana":"こばやししゅぞうきゅうしざいこ（むかしのさけどうぐてんじかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06140972,"lng":141.7703545,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積114㎡","structure_material":"煉瓦造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0080","desc":"敷地南東隅に位置し，桁行１３ｍ，梁間８．５ｍの規模で，煉瓦造２階建，切妻造，桟瓦葺とし，北東に出入口を設ける。１階内部は棟通りに２本の丸柱を立て，東端に階段室を設ける。２階は１室とする。１階には妻側に２箇所，平側に３箇所の控壁を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005719"},{"id":"00005715","register_sub_id":"101","register_pk":"106703","name":"小林酒造旧事務所（蔵元北の錦記念館）","kana":"こばやししゅぞうきゅうじむしょ（くらもときたのにしききねんかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06165394,"lng":141.7706215,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積200㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0077","desc":"敷地東隅に位置し，桁行１５ｍ，梁間１０ｍの規模で，ＲＣ造２階建，寄棟造，桟瓦葺とする。南東を正面とし，石張の玄関を構える。１階は丸柱２本を棟通りに立て，間仕切の無い広い空間とする。背面と側面に階段室を突出させ，外壁をタイル貼とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005715"},{"id":"00005718","register_sub_id":"101","register_pk":"106706","name":"小林酒造旧精米場（酒の郷なつかしホール）","kana":"こばやししゅぞうきゅうせいまいじょう（さけのさとなつかしほーる）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.061146,"lng":141.7689828,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積568㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0079","desc":"敷地南西隅に位置し，桁行４５ｍ，梁間９ｍの規模で，木造平屋建，切妻造，鉄板葺とし，北側に３．６ｍ幅の下屋を付ける。内部をホールに改造し，下屋部分を通路とする。外壁は横板張で，腰を煉瓦貼とする。妻面は梁と束を現して，特徴ある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005718"},{"id":"00005717","register_sub_id":"101","register_pk":"106705","name":"小林酒造旧ビール庫・缶詰資材庫（大正・昭和の暮らし館）","kana":"こばやししゅぞうきゅうびーるこ・かんづめしざいこ（たいしょう・しょうわのくらしかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06126865,"lng":141.77013963,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0078","desc":"敷地南辺やや東側に位置し，桁行１０間，梁間５間の規模で，木造平屋建，切妻造，鉄板葺。内部を東西２室に区切り，土間及びコンクリート床とし，倉庫として使われていた。外壁は横板張で腰を煉瓦貼とし，妻面は梁と束を現して，特徴ある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005717"},{"id":"00005724","register_sub_id":"101","register_pk":"106712","name":"小林酒造五番蔵","kana":"こばやししゅぞうごばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06169348,"lng":141.76967701,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木骨石造2階建、鉄板葺、建築面積176㎡","structure_material":"木骨石造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0085","desc":"四番蔵の西側に南北棟で建つ。桁行１２間，梁間５間の規模で，木骨石造２階建，切妻造，鉄板葺とする。１階，２階共に２列に計６本の柱を並べる。両妻側に戸口を設け，２階の平側及び北妻面に窓を開く。腰蛇腹を廻し，石材を片馬踏み目地で積み，重厚な外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005724"},{"id":"00005722","register_sub_id":"101","register_pk":"106710","name":"小林酒造三番蔵","kana":"こばやししゅぞうさんばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06171472,"lng":141.7700335,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積312㎡","structure_material":"煉瓦造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0083","desc":"二番蔵の西隣に位置し，南北棟で建つ。桁行２１間，梁間４間半の規模で，煉瓦造２階建，切妻造，鉄板葺とする。小屋をキングポストトラスとし，規模，形式等を二番蔵とほぼ同様とするが，二階床高を高くつくる。妻側は一階にも窓を設け，特徴ある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005722"},{"id":"00005726","register_sub_id":"101","register_pk":"106714","name":"小林酒造製麹室","kana":"こばやししゅぞうせいきくしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06167055,"lng":141.76936257,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積282㎡","structure_material":"煉瓦造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0087","desc":"六番蔵の西側に南北棟で建つ。桁行１５間半，梁間５間半の規模で，煉瓦造２階建，切妻造，鉄板葺とする。１階は西面南寄りに戸口を開き，北西隅を麹室とする。２階は平側に４箇所，北妻側に１箇所の窓を開く。全体に装飾性の少ない簡素なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005726"},{"id":"00005721","register_sub_id":"101","register_pk":"106709","name":"小林酒造二番蔵","kana":"こばやししゅぞうにばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06172521,"lng":141.77018894,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積382㎡","structure_material":"煉瓦造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0082","desc":"敷地北側に並ぶ蔵の東部に位置し，南北棟で建つ。桁行２１間，梁間５間半の規模で，煉瓦造２階建，切妻造，鉄板葺とする。１階は２列に計１４本の柱を並べ，南側に出入口を設ける。２階にのみ窓を開き，妻面の窓及びデンティル，鬼瓦等の意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005721"},{"id":"00005727","register_sub_id":"101","register_pk":"106715","name":"小林酒造蒸米場","kana":"こばやししゅぞうむしまいじょう","category":"産業2次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06147956,"lng":141.7691676,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積282㎡、煙突付","structure_material":"煉瓦造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0088","desc":"一番蔵の西側に南北棟で建つ。桁行１６間，梁間５間半の規模で，煉瓦造平屋建，切妻造，鉄板葺とする。基礎を石造とし，四隅に柱形を現す。北妻側に２箇所の窓を開き，妻面にも窓を開く。北妻面東寄りに煉瓦煙突を付属し，蒸米場の特徴ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005727"},{"id":"00005723","register_sub_id":"101","register_pk":"106711","name":"小林酒造四番蔵","kana":"こばやししゅぞうよんばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06170934,"lng":141.76986715,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積263㎡","structure_material":"木骨石造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0084","desc":"三番蔵の西隣に位置し，南北棟で建つ。桁行１３間半，梁間４間半の規模で，木骨石造２階建，切妻造，桟瓦葺とし，西側に煉瓦造の下屋を付ける。内部には１階，２階共に柱を立てない。石材を片馬踏み目地で積み，軒蛇腹，螻羽も石積みとし，重厚な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005723"},{"id":"00005725","register_sub_id":"101","register_pk":"106713","name":"小林酒造六番蔵","kana":"こばやししゅぞうろくばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道夕張郡栗山町錦3-109","lat":43.06166324,"lng":141.76950446,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木骨石造平屋建、鉄板葺、建築面積200㎡","structure_material":"木骨石造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"01 － 0086","desc":"五番蔵の西側に南北棟で建つ。桁行１３間半，梁間５間の規模で，木骨石造平屋建，切妻造，鉄板葺とする。１階は南側に両引戸，北側に片引戸の戸口を設け，南北平側軒下の高所にそれぞれ２箇所の窓を開く。石材を片馬踏み目地で積み，重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005725"},{"id":"00000924","register_sub_id":"101","register_pk":"101914","name":"旧河内屋橋本合名会社","kana":"きゅうかわうちやはしもとごうめいがいしゃ","category":"産業2次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"大正","pref":"青森県","address":"青森県八戸市大字八日町1","lat":40.51075778,"lng":141.49219797,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積135㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"02 － 0002","desc":"造り酒屋の事務所建築。八戸大火直後の建築で，切妻の屋根を見せ２階部分のみ外壁を白地の柱に縦板張りとし，他は下見板張りとする。一階中央部にショーウィンドーを設け，正面庇欄間にステンドグラスをはめる等斬新な意匠になる。設計は安藤安夫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000924"},{"id":"00008235","register_sub_id":"101","register_pk":"133877","name":"八戸酒造北蔵","kana":"はちのへしゅぞうきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"青森県","address":"青森県八戸市大字湊町字本町9","lat":40.52451772,"lng":141.52284575,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積240㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"02 － 0084","desc":"主屋北側に位置し、道路に東妻を見せる。桁行２５ｍ梁間９．６ｍの土蔵造２階建、切妻造桟瓦葺の置屋根形式。２ヶ所の窓を穿ち、鉢巻と窓上部の楣を黒漆喰仕上げとする伝統的な意匠の東妻面と、その前の近代的な煉瓦塀が独特の調和を生み出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008235"},{"id":"00008234","register_sub_id":"101","register_pk":"133876","name":"八戸酒造店舗兼主屋","kana":"はちのへしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市大字湊町字本町9","lat":40.5243985,"lng":141.52303151,"geo_status":"db","era":"大正後期／昭和35年・平成21年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積246㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"02 － 0083","desc":"東西に街路に挟まれた矩形敷地の東に建つ。桁行１５ｍ梁間１５ｍの木造２階建。南北棟の切妻造桟瓦葺で、２階正面は庇を出し一面に繊細な出格子を嵌める。１階は南から通り土間、店舗、座敷と内部空間に合わせた表構えを示し、老舗の風格を醸成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008234"},{"id":"00008237","register_sub_id":"101","register_pk":"133879","name":"八戸酒造西蔵","kana":"はちのへしゅぞうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"青森県","address":"青森県八戸市大字湊町字本町9","lat":40.52425849,"lng":141.52270296,"geo_status":"db","era":"大正後期／平成21年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積182㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"02 － 0086","desc":"文庫蔵の南に、川に平行して南北棟で建つ。桁行１９ｍ梁間９．６ｍの土蔵造２階建、切妻造鉄板葺の置屋根。漆喰仕上げで、鉢巻や楣を黒漆喰とし、要所に窓を穿ち、リズム感ある外観をつくる。石垣上に文庫蔵と連続して建ち、漁船が繋留される河口景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008237"},{"id":"00008236","register_sub_id":"101","register_pk":"133878","name":"八戸酒造文庫蔵","kana":"はちのへしゅぞうぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"青森県","address":"青森県八戸市大字湊町字本町9","lat":40.52442484,"lng":141.52262256,"geo_status":"db","era":"大正後期／平成21年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、銅板葺、建築面積88㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"02 － 0085","desc":"敷地の西北隅に建つ。桁行１１ｍ梁間７．９ｍの土蔵造２階建、切妻造銅板葺の置屋根形式。２階にはトコや棚、付書院などを構える数寄屋風座敷と次の間を設ける。新井田川側の西妻は、両開戸を構える窓を二ヶ所開け、鉢巻を黒漆喰仕上げとし、拝みに家紋を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008236"},{"id":"00008238","register_sub_id":"101","register_pk":"133880","name":"八戸酒造煉瓦蔵","kana":"はちのへしゅぞうれんがぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"青森県","address":"青森県八戸市大字湊町字本町9","lat":40.52416422,"lng":141.52319231,"geo_status":"db","era":"大正13年／昭和50年・平成21年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造2階地下1階建、鉄板葺、建築面積472㎡","structure_material":"煉瓦造2階地下1階建","registered":"2010.09.10(平成22.09.10)","register_no":"02 － 0087","desc":"敷地南寄りの東西棟とその東端から北に延びる南北棟がＬ字形の棟をつくる。イギリス積の煉瓦造で地上２階建地下１階、鉄板葺、建築面積４７２㎡。東西棟にはスコットランド製鉄骨梁が一間毎に架かり、根太を置き、２階床を支持する特殊な構造をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008238"},{"id":"00008239","register_sub_id":"101","register_pk":"133881","name":"八戸酒造煉瓦塀","kana":"はちのへしゅぞうれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市大字湊町字本町9","lat":40.52451495,"lng":141.52301903,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、瓦葺、延長15m","structure_material":"煉瓦造","registered":"2010.09.10(平成22.09.10)","register_no":"02 － 0088","desc":"主屋西北角から、通りに沿って北へ延びる煉瓦塀で延長１５ｍに及ぶ。フランス積とし、桟瓦葺で、棟を熨斗積とする。厚さ２４㎝高さ３．０ｍ、途中から低くなり北寄りは高さ２．５ｍとなる。基礎や柱型、上部を焼過ぎ煉瓦で造るなど、巧みな意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008239"},{"id":"00012675","register_sub_id":"101","register_pk":"367579","name":"旧東屋酒造店酒蔵","kana":"きゅうあずまやしゅぞうてんさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"岩手県","address":"岩手県宮古市本町15他","lat":39.64251889,"lng":141.95663389,"geo_status":"db","era":"江戸末期／昭和28年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建一部2階建、金属板葺、建築面積363㎡","structure_material":"土蔵造平屋建一部2階建","registered":"2019.03.29(平成31.03.29)","register_no":"03 － 108","desc":"主屋背面に建つ。土蔵造平屋建、置屋根式の切妻造、外壁中塗仕上で、西面南寄りと南面西寄りの二箇所に扉口を開く。桁行13間半梁間7間半の規模で、内部は大断面の梁や母屋桁を用いて柱を省略し、大空間を確保する。酒造施設の伝統的な構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012675"},{"id":"00012676","register_sub_id":"101","register_pk":"367580","name":"旧東屋酒造店質蔵","kana":"きゅうあずまやしゅぞうてんしちぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"岩手県","address":"岩手県宮古市本町15他","lat":39.64251889,"lng":141.95663389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、金属板葺、建築面積136㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"03 － 109","desc":"敷地西北隅に南面して建つ。切妻造の土蔵造二階建で、正面に下屋を通す。外壁は漆喰塗の腰海鼠壁で、街路に面する西妻を腰下見板張とする。内部は西を質蔵、東端を文庫蔵とし、正面東寄りに各扉口を並べて設ける。豪商の重厚な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012676"},{"id":"00012674","register_sub_id":"101","register_pk":"367578","name":"旧東屋酒造店店舗兼主屋","kana":"きゅうあずまやしゅぞうてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県宮古市本町15他","lat":39.64251889,"lng":141.95663389,"geo_status":"db","era":"明治後期／大正前期・昭和48年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、金属板葺、建築面積217㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"03 － 107","desc":"旧市街中心部のもと造り酒屋。主屋は街路に西面して建つ。入母屋造妻入の二階建で南に土間、北に2列6室を配して北列表を座敷とする。正面は北端の座敷部分を下見板張とする以外は開口を広く取り、繊細な格子を並べる。旧市街の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012674"},{"id":"00000010","register_sub_id":"101","register_pk":"101000","name":"旧東北砕石工場","kana":"きゅうとうほくさいせきこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県一関市東山町松川字滝ノ沢平117-1他","lat":38.98039655,"lng":141.2392972,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造・鉄骨造平屋建、亜鉛メッキ鋼板葺、建築面積751㎡","structure_material":"木造・鉄骨造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"03 － 0011","desc":"土壌改良剤としての石灰を製造するため，石灰岩の砕石を行う施設として建設された。トラス組の小屋組に片流れの屋根をかけた簡素な造りになるが，土壌改良等農業生産の向上に努めた宮沢賢治との関係があることでも知られる砕石工場の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000010"},{"id":"00001228","register_sub_id":"101","register_pk":"102218","name":"世嬉の一酒造場旧売場倉庫","kana":"せきのいちしゅぞうじょうきゅううりばそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県一関市田村町14","lat":38.931358,"lng":141.132797,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積201㎡","structure_material":"土蔵造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0026","desc":"街路に沿って旧店舗事務所の南に連なる南北棟、瓦葺切妻屋根、平屋建の土蔵。桁行２５ｍ、梁間８ｍの規模で、中庭側と南妻側に出入口を設ける。旧仕込蔵と同意匠になる妻螻羽の焼過煉瓦が南立面のファサードを効果的に縁取っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001228"},{"id":"00001223","register_sub_id":"101","register_pk":"102213","name":"世嬉の一酒造場旧原料米置場・精米所","kana":"せきのいちしゅぞうじょうきゅうげんりょうまいおきば・せいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県一関市田村町14","lat":38.93161804,"lng":141.13260983,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋建，瓦葺，建築面積178㎡","structure_material":"石造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0021","desc":"磐井川河畔、もと一関藩中下級武家地の一画に位置する。摺沢村出身の佐藤徳蔵が熊文酒造店を買い取って改築したもので、徳蔵の従兄弟で辰野金吾門下の小原友輔が設計にあたった。裏の旧麹室と一体的に改修されて地ビールレストランとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001223"},{"id":"00001225","register_sub_id":"101","register_pk":"102215","name":"世嬉の一酒造場旧作業場・釜場","kana":"せきのいちしゅぞうじょうきゅうさぎょうば・かまば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"岩手県","address":"岩手県一関市田村町14","lat":38.931416,"lng":141.132385,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建，スレート葺，建築面積295㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0023","desc":"旧原料米置場・精米所の南方、旧仕込蔵との間に位置する。現在は和風レストランに改造されているが、旧作業場の小屋組などは旧状をよく留める。レストランの玄関部は、もとの釜場の鉄筋コンクリート造貯水槽を改装したもので、妻の形状は旧状を踏襲している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001225"},{"id":"00001226","register_sub_id":"101","register_pk":"102216","name":"世嬉の一酒造場旧仕込蔵・酒母室","kana":"せきのいちしゅぞうじょうきゅうしこみぐら・しゅぼしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"岩手県","address":"岩手県一関市田村町14","lat":38.931217,"lng":141.132355,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造及び木造２階建，瓦葺及び鉄板葺，建築面積483㎡","structure_material":"土蔵造及び木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0024","desc":"敷地の南方に建つ土蔵造２階建、瓦葺切妻屋根、東西棟の仕込蔵で、北側に下屋を差掛けて酒母室とする。桁行２７ｍ、梁間１６ｍの大規模土蔵で、小屋組はクイーンポストトラスを採る。現在は、酒の民俗文化博物館として酒造り用具類の展示館となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001226"},{"id":"00001229","register_sub_id":"101","register_pk":"102219","name":"世嬉の一酒造場旧店舗・事務所","kana":"せきのいちしゅぞうじょうきゅうてんぽ・じむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県一関市田村町14","lat":38.931606,"lng":141.132935,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積114㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0027","desc":"敷地の東北端、やや南にひいた位置に建つ。土蔵造を基調としながらも、階下の店舗部は石貼として洋風意匠でまとめる。場内の土蔵系建築と石造系建築を上下に合体した格好の建築で、世嬉の一酒造場の顔としての建築に相応しい造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001229"},{"id":"00001224","register_sub_id":"101","register_pk":"102214","name":"世嬉の一酒造場旧びん詰貯蔵庫・麹室","kana":"せきのいちしゅぞうじょうきゅうびんづめちょぞうこ・こうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県一関市田村町14","lat":38.931648,"lng":141.132477,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造平屋建，スレート葺，建築面積138㎡","structure_material":"煉瓦造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0022","desc":"旧原料米置場・精米所の奥に接し、間仕切壁を共有する倉庫風の煉瓦造建築。麹室を含むために煉瓦壁を中空二重壁としている点に特徴がある。現在は、旧原料米置場・精米所と合棟して一体的な切妻屋根の中に収まり、地ビール工場に充てられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001224"},{"id":"00001227","register_sub_id":"101","register_pk":"102217","name":"世嬉の一酒造場旧槽場・売場倉庫","kana":"せきのいちしゅぞうじょうきゅうふなば・うりばそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県一関市田村町13-2、14","lat":38.931038,"lng":141.132614,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋建，鉄板葺，建築面積263㎡","structure_material":"石造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0025","desc":"仕込蔵の東南方に位置し、街路に沿って建つ南北棟、石造平屋建の建物。旧原料米置場・精米所と同意匠の建築で、窓回りの額縁に焼過煉瓦を用いて装飾効果を高めている。設計者・小原友輔の作風の一端を窺い知ることができることで貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001227"},{"id":"00007166","register_sub_id":"101","register_pk":"108148","name":"仙臺屋旧穀蔵","kana":"せんだいやきゅうこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岩手県","address":"岩手県遠野市中央通り501-3","lat":39.33006938,"lng":141.52954028,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"03 － 0069","desc":"主屋の後方、東寄りに位置する。桁行９．６ｍ梁間５．７ｍの土蔵造２階建、切妻造妻入の置屋根とする。壁は下方ほど厚くする特徴的な仕様を残す。南面に庇を設け、掛子塗両開戸を吊り出入口とする。外壁は白漆喰仕上げ、鉢巻や窓まわりなどを黒漆喰で仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007166"},{"id":"00007168","register_sub_id":"101","register_pk":"108150","name":"仙臺屋旧籾蔵","kana":"せんだいやきゅうもみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岩手県","address":"岩手県遠野市中央通り501-3","lat":39.33027783,"lng":141.52953473,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"03 － 0071","desc":"前の蔵の北方、作業場を挟んだ位置に建つ。桁行９．６ｍ梁間５．７ｍの土蔵造２階建で、切妻造妻入の置屋根とする。内部は南北２室に分け、南は２階床を張り、北半は吹抜けとする。外壁は白漆喰仕上げで、鉢巻を黒漆喰仕上げ、腰を海鼠壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007168"},{"id":"00007169","register_sub_id":"101","register_pk":"108151","name":"仙臺屋倉庫","kana":"せんだいやそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県遠野市中央通り501-3","lat":39.33042276,"lng":141.52965659,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積112㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"03 － 0072","desc":"敷地北奥に位置する、南北棟の切妻造平屋建で、北端の屋根を一段下げ、南から東面に庇をまわす。桁行１７ｍ梁間５．７ｍの南北に長い倉庫で、外壁を大壁造の荒壁仕上げとする。内部は３つに区分し、南室のみ中２階床を張り、他２室は吹抜けとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007169"},{"id":"00007165","register_sub_id":"101","register_pk":"108147","name":"仙臺屋店舗兼主屋","kana":"せんだいやてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県遠野市中央通り501-3","lat":39.32985866,"lng":141.52934531,"geo_status":"db","era":"明治15／昭和35改修・平成18移築","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積357㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"03 － 0068","desc":"南北に長い短冊状の敷地南端に建つ。正面間口９間半の木造２階建、切妻造鉄板葺の町家。西側５間半の主体部と東側４間の元旅館を併せて１棟とする。主体部は背面直角に棟を出し、ミセやジョウイなどの居室を１列に並べ、遠野における伝統的な町家の形態を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007165"},{"id":"00007170","register_sub_id":"101","register_pk":"108152","name":"仙臺屋便所","kana":"せんだいやべんじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岩手県","address":"岩手県遠野市中央通り501-3","lat":39.33035055,"lng":141.52959104,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積4.1㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"03 － 0073","desc":"旧籾蔵と倉庫の間に建つ。東西棟の切妻造桟瓦葺。桁行２．９ｍで梁間は北から１．４ｍを側柱筋として間仕切り、その前方を出桁造とし、小天井を張る。内部は３室に分け、南に板扉を吊る。柱は方柱で、一軒疎垂木、妻は束立とする。壁は真壁造の白漆喰仕上げ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007170"},{"id":"00007167","register_sub_id":"101","register_pk":"108149","name":"仙臺屋前の蔵","kana":"せんだいやまえのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県遠野市中央通り501-3","lat":39.33014949,"lng":141.5294459,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"03 － 0070","desc":"店舗兼主屋の北、中庭を挟む位置に建つ。桁行８．６ｍ梁間４．８ｍの土蔵造２階建で、切妻造妻入の置屋根。南に出入口と２階窓を開け、掛子塗の両開戸を吊る。外壁は白漆喰仕上げ、鉢巻と開口部、腰は黒漆喰で仕上げる。旧穀蔵と同様に下方ほど壁を厚くする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007167"},{"id":"00003036","register_sub_id":"101","register_pk":"104026","name":"横屋酒造釜場","kana":"よこやしゅぞうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方134-1","lat":38.91962324,"lng":141.33302466,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、鉄板葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0047","desc":"東の東蔵と西の造り蔵の間にあり，西は造り蔵に接続する。木造・平屋建，真壁造，屋根は切妻造・鉄板葺，トラス組の小屋とし，棟に大きい気抜を設ける。外観は簡素であるが，梁間約１１ｍと広い内部空間をつくるなど，造り酒屋に欠かせない施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003036"},{"id":"00003042","register_sub_id":"101","register_pk":"104032","name":"横屋酒造枯し場","kana":"よこやしゅぞうからしば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方137-2","lat":38.919857,"lng":141.33316,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、鉄板葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0053","desc":"東蔵の東側に平行して建つ。桁行２２ｍ，梁間７．５ｍ，丸太状の柱を両側に２間毎に立て，トラスを組み，切妻造・鉄板葺の屋根を架ける。現在はタンク置場であるが，もとは亜炭の乾燥場で，柱間はすべて吹き放しとする。伝統的な酒造りの一端を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003042"},{"id":"00003039","register_sub_id":"101","register_pk":"104029","name":"横屋酒造蔵人炊事場","kana":"よこやしゅぞうくろうどすいじば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方134-1","lat":38.91966848,"lng":141.33292076,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、鉄板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0050","desc":"西の造り蔵とこれに接する釜場の北隅にある。造り蔵の庇とこれに続く切妻造部分からなる。蔵人の炊事や休憩等に用いられている。木造・平屋建，真壁造，鉄板葺の簡素な建物であるが，酒造従事者のための生活空間であり，酒造施設に欠かせない存在である","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003039"},{"id":"00003037","register_sub_id":"101","register_pk":"104027","name":"横屋酒造麹室","kana":"よこやしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方134-1","lat":38.9199331,"lng":141.3325531,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積159㎡","structure_material":"石造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0048","desc":"敷地北側，正面蔵と平行して建つ。桁行約２２ｍ，梁間約７ｍの細長い平屋建の建物で，屋根は切妻造・桟瓦葺とし、内部は２室にわかれる。石造の外壁は腰を花崗岩の瘤出仕上げ，上部を塩竃石と呼ばれる凝灰岩切石を用い，軒蛇腹を廻して，重厚なつくりとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003037"},{"id":"00003034","register_sub_id":"101","register_pk":"104024","name":"横屋酒造正面蔵","kana":"よこやしゅぞうしょうめんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方134-1","lat":38.91988628,"lng":141.33274641,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積638㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0045","desc":"造り蔵と連携した貯蔵用施設。桁行約41ｍ、梁間約12ｍ、2階建の長大な土蔵造建築で、南側は西で造り蔵、東で東蔵に接続する。屋根は切妻造・桟瓦葺、小屋はトラス組、内部は間仕切壁で東西に分かれ、外壁は漆喰塗とする。造り蔵とともに重厚な酒蔵景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003034"},{"id":"00003038","register_sub_id":"101","register_pk":"104028","name":"横屋酒造タンク置場","kana":"よこやしゅぞうたんくおきば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方134-1","lat":38.92003924,"lng":141.33270776,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0049","desc":"桁行約１１ｍ，梁間約６ｍの平屋建の建物で，麹室の東妻に接し，正面蔵と平行して建つ。屋根はトラス組の切妻造・鉄板葺で，タンク置場として用いるため，立ちが高く天井もない。切石積基礎とした真壁造だが，外壁下見板張として，端正な洋風意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003038"},{"id":"00003033","register_sub_id":"101","register_pk":"104023","name":"横屋酒造造り蔵","kana":"よこやしゅぞうつくりぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方134-1","lat":38.91962483,"lng":141.33280431,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積525㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0044","desc":"桁行約４４ｍ，梁間約１２ｍ，切妻造・桟瓦葺，２階建の長大な土蔵造建築で，北側は正面蔵に接続する。内部は間仕切壁を設け，南約３分の１をもと場，残る北を酒造場とする。道路側の西面は，漆喰壁で腰石張とし，小窓を整然と並べ，豪壮な酒蔵景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003033"},{"id":"00003035","register_sub_id":"101","register_pk":"104025","name":"横屋酒造東蔵","kana":"よこやしゅぞうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方134-1","lat":38.91979679,"lng":141.33306914,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積360㎡","structure_material":"土蔵造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0046","desc":"桁行約４４ｍ，梁間約８ｍ，切妻造・桟瓦葺，平屋建の長大な土蔵造建築。造り蔵や正面蔵と同形式で，外壁は漆喰塗，腰を人造石洗い出し仕上げ，内部は間仕切壁で貯蔵場と濾過場に分かれる。正面蔵，造り蔵とコの字型に連続して，有機的な酒造空間を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003035"},{"id":"00003041","register_sub_id":"101","register_pk":"104031","name":"横屋酒造ビン詰工場","kana":"よこやしゅぞうびんづめこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県一関市千厩町千厩字北方137-2","lat":38.91968262,"lng":141.33338503,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積254㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"03 － 0052","desc":"東蔵南端の東方にあり，旧千厩村役場を少し移動して酒の瓶詰施設として再用した。平面は鍵型で，南北棟・入母屋造の東側に東西棟・切妻造の屋根を架け，鉄板葺（もと木羽葺）である。一部に地方の庁舎らしい痕跡を残すが，現在は酒造りに欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003041"},{"id":"00012272","register_sub_id":"101","register_pk":"531596","name":"海老喜表蔵","kana":"えびきおもてぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町22","lat":38.65415833,"lng":141.28323056,"geo_status":"db","era":"大正後期／昭和30年代改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積71㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"04-152","desc":"旧店舗の北側に隣接し、三日町通に東面して建つ蔵で、商品保管と穀蔵に使用された。内部は上下階とも二室に区分し、旧店舗側と街路側にそれぞれ戸口を開く。内外壁とも大壁、小屋組は二重梁組とする。旧店舗とともに街道の歴史的景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012272"},{"id":"00012277","register_sub_id":"101","register_pk":"531601","name":"海老喜旧酒蔵（蔵の資料館）","kana":"えびききゅうさかぐら（くらのしりょうかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町22","lat":38.65433333,"lng":141.28278333,"geo_status":"db","era":"江戸末期／昭和54年・平成24年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋一部二階建、瓦葺、建築面積153㎡","structure_material":"土蔵造平屋一部二階建","registered":"2018.05.10(平成30.05.10)","register_no":"04-157","desc":"敷地後方の北西隅に南面して建つ。明治四一年まで酒蔵に使用され、二階に酒神を祀る神棚が設けられている。東西棟の切妻造桟瓦葺、外壁漆喰塗で、腰を竪板張とする。内部は三重梁の梁組を一間ごとに配し貫で連結する。伝統的な酒造の有様を伝える長大な蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012277"},{"id":"00012278","register_sub_id":"101","register_pk":"531602","name":"海老喜旧醤油仕込蔵（海老喜ホール）","kana":"えびききゅうしょうゆしこみぐら（えびきほーる）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町22","lat":38.65418333,"lng":141.282675,"geo_status":"db","era":"明治25年／昭和54年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積110㎡","structure_material":"土蔵造平屋一部2階建","registered":"2018.05.10(平成30.05.10)","register_no":"04-158","desc":"敷地後方、南側通り沿いに東面して建つ長大な土蔵。切妻造桟瓦葺妻入、和小屋組で、大梁の上に桁行梁と三重梁を整然とかけ渡し、発達した構造をみせる。棟梁佐藤朝吉の技量が発揮された建物であり、近代における当地域の木造建築技術の水準を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012278"},{"id":"00012271","register_sub_id":"101","register_pk":"531595","name":"海老喜旧店舗","kana":"えびききゅうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町22","lat":38.65401667,"lng":141.28314167,"geo_status":"db","era":"大正後期／昭和16年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、スレート葺、建築面積80㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"04-151","desc":"登米の旧城下町に所在する商家で、一階に店の間と帳場、二階に客座敷を配する。二階は大壁で、腰の海鼠壁には四半張目地を変形させた意匠を凝らし、昭和期の隅切部にも意匠が踏襲される。屋根スレート葺で、町の出入口となる角地に建つランドマーク的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012271"},{"id":"00012275","register_sub_id":"101","register_pk":null,"name":"海老喜作業場","kana":"えびきさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町22","lat":38.65424444,"lng":141.28291111,"geo_status":"db","era":"明治前期／昭和30年代改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、金属板葺、建築面積146㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"04-155","desc":"敷地北側のほぼ中央、味噌醤油仕込蔵と旧酒蔵との間に位置する。木造平屋建、和小屋組で、東西棟の切妻屋根を南北に並べ、内部は一室として広い作業場とする。味噌醤油仕込蔵の附属施設であり、醸造工程を知る上で欠かせない建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012275"},{"id":"00012273","register_sub_id":"101","register_pk":"531597","name":"海老喜主屋","kana":"えびきしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町22","lat":38.65413611,"lng":141.28301667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、スレート葺、建築面積142㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"04-153","desc":"旧店舗背面に東西棟で直交して建つ。旧店舗側より前面に座敷二室、チャノマ、土間を配し、後方に台所と居室を設ける。たちの高い外観や、施主の茶の湯趣味を反映した数寄屋風意匠が施されたオクザシキが、近代の造形感覚の一面を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012273"},{"id":"00012276","register_sub_id":"101","register_pk":"531600","name":"海老喜文庫蔵","kana":"えびきぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町22","lat":38.65425833,"lng":141.28270278,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"04-156","desc":"敷地後方の中央部に東面して建つ。切妻造桟瓦葺妻入で、東面に下屋と扉口を設ける。外壁漆喰塗で、腰の海鼠壁を一階は芋目地、二階は四半張目地とする。窓は、庇二軒、腕木は二段で透彫の板を嵌め、持送りに繰形彫刻を施すなど凝った意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012276"},{"id":"00012274","register_sub_id":"101","register_pk":"531598","name":"海老喜味噌醤油仕込蔵","kana":"えびきみそしょうゆしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町22","lat":38.65428056,"lng":141.28298611,"geo_status":"db","era":"江戸末期／平成24年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、金属板葺、建築面積82㎡","structure_material":"土蔵造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"04-154","desc":"主屋背面に東西棟で建つ。外壁は漆喰塗で腰を海鼠壁とし、主屋と作業場への戸口二箇所を開く。柱は半間ごとに立て、小屋組は曲梁を用いた和小屋と登梁を交互にかけ、高い作業区間を確保している。敷地内で最も古い建物で、創業時の商いの様相をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012274"},{"id":"00012270","register_sub_id":"101","register_pk":"531594","name":"男山本店客座敷","kana":"おとこやまほんてんきゃくざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市入沢174他","lat":38.90781389,"lng":141.57368056,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"04-150","desc":"気仙沼港に面した谷あいに立地する酒蔵の正面角地に建つ。入母屋造平入で、正面片側に突出部、中央に玄関を設け、周囲に下屋を廻す。主体部は座敷二室を配して廊下を廻し、突出部はもと土間の控室とする。住宅風の接客施設で酒蔵の表構えに彩りを添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012270"},{"id":"00013920","register_sub_id":"101","register_pk":"508180","name":"男山本店酒造蔵","kana":"おとこやまほんてんしゅぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県気仙沼市入沢175","lat":38.90812778,"lng":141.57365,"geo_status":"db","era":"大正3年頃／同9年増築・昭和4年頃改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建及び土蔵造2階建、瓦葺、建築面積686㎡","structure_material":"木造平屋建及び土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0208","desc":"気仙沼湾最奥の内湾地区に位置し、敷地北東隅に建つ。木造一部土蔵造桟瓦葺で、南面に金属板葺の下屋を付す。内部は東から三号蔵、仕込蔵、中蔵が並び、下屋に煙突付釜場・槽場等を配す。三棟を一体化した大きな外観は、醸造施設の景観を印象付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013920"},{"id":"00014225","register_sub_id":"101","register_pk":"509615","name":"旧櫻井醸造(ヤマカノ醸造)事務所","kana":"きゅうさくらいじょうぞう(やまかのじょうぞう)じむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池金谷15","lat":38.6509,"lng":141.27938333,"geo_status":"db","era":"明治42年／昭和前期改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"04 - 0211","desc":"登米城下町南辺の角地に北面する町家で醤油醸造業の事務所。二階建、切妻造桟瓦葺平入で軒を出桁造とし、二階外壁は下見板張。一階は一室の事務所、二階は二室の座敷で西側南面に床を構える。梁と束を重ねた妻面をみせ、地域の歴史的景観を形成する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014225"},{"id":"00014227","register_sub_id":"101","register_pk":"509617","name":"旧櫻井醸造(ヤマカノ醸造)醸造蔵","kana":"きゅうさくらいじょうぞう(やまかのじょうぞう)じょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池金谷10","lat":38.65123889,"lng":141.27905,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、鉄板葺、建築面積125㎡","structure_material":"土蔵造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"04 - 0213","desc":"事務所から通りを挟んで北西に位置する醤油醸造蔵。土蔵造平屋建、切妻造鉄板葺で越屋根二箇所に設置。外壁漆喰仕上で鉢巻付、腰及び東妻を海鼠壁、通り側に窓を開く。内部は土間一室で小屋組は和小屋。角地にあり、地域の歴史的景観を形成する長大な醸造蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014227"},{"id":"00014226","register_sub_id":"101","register_pk":"509616","name":"旧櫻井醸造(ヤマカノ醸造)南蔵","kana":"きゅうさくらいじょうぞう(やまかのじょうぞう)みなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池金谷14-3","lat":38.6509,"lng":141.27905833,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積174㎡","structure_material":"土蔵造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"04 - 0212","desc":"事務所から通りを挟んで西に位置する醤油醸造蔵。土蔵造平屋建、切妻造鉄板葺、置屋根形式で鉢巻付、外壁は漆喰仕上、東面に下屋を付す。内部は一室の土間で、小屋組は斜材を用いて洋小屋を模す。角地にあり、地域の歴史的景観を形成する長大な南蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014226"},{"id":"00013676","register_sub_id":"101","register_pk":"505177","name":"旧橋平酒造店（醸室）主屋","kana":"きゅうはしへいしゅぞうてん（かむろ）おもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町1","lat":38.57584167,"lng":140.95573611,"geo_status":"db","era":"明治前期／昭和8年頃・平成17年改修、令和2年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、鉄板葺、建築面積175㎡","structure_material":"木造平屋一部2階建","registered":"2021.02.26(令和3.02.26)","register_no":"04 － 198","desc":"帳場西側に接続する東西棟の平屋部と、その北面東寄に接続する二階建部からなる。入母屋造鉄板葺で、南北面に下屋、南面中程に入母屋造玄関を付す。平屋部は南に縁、北に三室を並べ帳場側を床付の座敷とする。奥に台所を配する。落着きある屋敷景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013676"},{"id":"00013675","register_sub_id":"101","register_pk":"505175","name":"旧橋平酒造店（醸室）帳場","kana":"きゅうはしへいしゅぞうてん（かむろ）ちょうば","category":"産業2次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町1","lat":38.5758,"lng":140.95585,"geo_status":"db","era":"明治前期／平成17年改修、令和2年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"04 － 197","desc":"店舗の北に接続して建つ。土蔵造二階建、置屋根形式の鉄板葺で、正面に店舗から続く下屋を通す。外壁は白漆喰塗で黒漆喰塗の鉢巻を廻す。一階は元は店舗と接続し、土間及び板敷の帳場としたが一室の土間に改修した。店舗と共に旧街道の景観に風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013675"},{"id":"00013674","register_sub_id":"101","register_pk":"505173","name":"旧橋平酒造店（醸室）店舗","kana":"きゅうはしへいしゅぞうてん（かむろ）てんぽ","category":"産業2次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県大崎市古川七日町1","lat":38.57575556,"lng":140.95585,"geo_status":"db","era":"明治前期／大正14年頃増築改修、平成17年改修、令和2年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積76㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"04 － 196","desc":"市中心部にある酒造業等を営んだ商家。店舗は敷地東側の旧奥州街道沿いに建つ。南面入母屋、北面切妻造の二階建鉄板葺で、正面に下屋を付し、成の高い腕木で出桁造の軒を豪壮に見せる。一階に店舗、二階に床付の座敷を配する。旧街道の景観に重厚さを加える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013674"},{"id":"00013486","register_sub_id":"101","register_pk":"504854","name":"旧山田本店（角田屋）座敷蔵","kana":"きゅうやまだほんてん（かくたや）ざしきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県登米市登米町登米字寺池三日町34-1他","lat":38.65337222,"lng":141.28222778,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0191","desc":"登米町中心部の商店街の通りから奥まって建つ。桁行五間半、梁間三間、切妻造桟瓦葺、外観は上下階とも腰を海鼠壁、戸前廻りは洋風意匠とする。２階に八畳の座敷を設け、柱、床框等は欅材で透き漆塗り、良材を用い、内外観ともに優れた意匠がみられる座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013486"},{"id":"00013485","register_sub_id":"101","register_pk":"504853","name":"旧山田本店（ヤマカノ醸造）表門","kana":"きゅうやまだほんてん（やまかのじょうぞう）おもてもん","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県登米市登米町登米字寺池九日町1","lat":38.653,"lng":141.28260833,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0190","desc":"東側の通りに面し、商蔵南側に建つ。切妻造桟瓦葺、総欅造りの棟門で門扉には潜りが付く。楣上部の欄間は欅の一枚板で、腕木下持送に渦紋、柄振板に渦葉の絵様を、懸魚に雲と鶴の透彫りを付す。社寺建築風の装飾豊かな外観意匠をもつ近代和風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013485"},{"id":"00013482","register_sub_id":"101","register_pk":"504850","name":"旧山田本店（ヤマカノ醸造）北蔵","kana":"きゅうやまだほんてん（やまかのじょうぞう）きたぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池九日町1","lat":38.65313611,"lng":141.28226111,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0187","desc":"東側の通りから奥まった位置に建つ。土蔵造二階建、東西棟の切妻造桟瓦葺、柱は全て欅材で柱間は一間六尺とする。外壁腰部は海鼠壁とし、二階桁行の側に開口部を設け二重腕木の庇を付す。明治後期の建築とみられ、醸造で栄えた商家の屋敷構えの変遷を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013482"},{"id":"00013484","register_sub_id":"101","register_pk":"504852","name":"旧山田本店（ヤマカノ醸造）旧仕込み蔵","kana":"きゅうやまだほんてん（やまかのじょうぞう）きゅうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県登米市登米町登米字寺池桜小路81-1","lat":38.65382222,"lng":141.28188333,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積186㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0189","desc":"敷地北西側の最奥に建つ。山田本家が味噌醤油醸造を営んだ時期の仕込み蔵。桁行十五間、梁間四間、開口部が少なく閉鎖的で大規模な土蔵。洋小屋組風の疑似トラスで大梁と束を帯鉄、ボルトで締める。機能を重視した造りで醸造場の中核となる大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013484"},{"id":"00013480","register_sub_id":"101","register_pk":"504848","name":"旧山田本店（ヤマカノ醸造）商蔵","kana":"きゅうやまだほんてん（やまかのじょうぞう）しょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県登米市登米町登米字寺池九日町1","lat":38.65307778,"lng":141.28256389,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積76㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0185","desc":"登米町中心部の商店街の通りに東面して建つ。桁行六間、梁間三間、寄棟造桟瓦葺、一階正面一間分を下屋とし、外観は腰石張り、開口はガラス戸で鉄格子をはめ、二階正面の腰を海鼠壁とする。近代的な意匠を強調した店蔵で、老舗醸造店の重厚な表構えを作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013480"},{"id":"00013481","register_sub_id":"101","register_pk":"504849","name":"旧山田本店（ヤマカノ醸造）文庫蔵","kana":"きゅうやまだほんてん（やまかのじょうぞう）ぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県登米市登米町登米字寺池九日町1","lat":38.65298611,"lng":141.28251389,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0186","desc":"東側の通り側に建つ。土蔵造二階建、桁行三間、梁間二間、東西棟の切妻造桟瓦葺、外観意匠が商蔵と類似し一連の建築とみられる。庇部の銅板被覆、石造りの床下換気口、欅造りを主調とした内観等、近代建築の特色をもち、商蔵、表門と並び建つ景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013481"},{"id":"00013483","register_sub_id":"101","register_pk":"504851","name":"旧山田本店（ヤマカノ醸造）南蔵","kana":"きゅうやまだほんてん（やまかのじょうぞう）みなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池九日町1","lat":38.65307778,"lng":141.28223611,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0189","desc":"東側の通りから奥まった位置に建つ。東西棟の切妻造桟瓦葺。柱間は一間を六尺三寸で、梁が架かる主要柱を欅、他は杉とする。外壁は隅を高く切り上げ、鉢巻を海鼠壁風とし意匠を凝らす。内部の竪板張に角釘を使用する明治前期の建築で、敷地内で最も古い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013483"},{"id":"00012865","register_sub_id":"101","register_pk":"367975","name":"宮城野納豆製造所亜炭小屋","kana":"みやぎのなっとうせいぞうしょあたんごや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和中","pref":"宮城県","address":"宮城県仙台市宮城野区銀杏町663他","lat":38.26456389,"lng":140.90905833,"geo_status":"db","era":"昭和25年頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 173","desc":"ボイラー室南東方の敷地境に西面して建つ。片流れ屋根鉄板葺の平屋建で、正側面は開放として正面中央以外に下見板張の腰壁を設ける。街路に面する背面は搬入口で、内開きの跳上げ戸を備える。ボイラー室とともに近代食品工場の動力設備の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012865"},{"id":"00012862","register_sub_id":"101","register_pk":"367972","name":"宮城野納豆製造所石蔵及び豆小屋","kana":"みやぎのなっとうせいぞうしょいしぐらおよびまめごや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市宮城野区銀杏町663他","lat":38.264725,"lng":140.90884444,"geo_status":"db","era":"昭和9年頃／平成23年・同29年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造及び木造平屋建、金属板葺、建築面積60㎡","structure_material":"石造及び木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 170","desc":"製造棟西棟の西側に南面して建つ。石蔵は切妻造鉄板葺妻入の平屋建で、背面に木造の豆小屋を附属する。大豆貯蔵庫の石蔵は外壁秋保石積の現し、トラス小屋組。計量作業場の豆小屋は外壁下見板張、和小屋である。納豆製造に欠かせない近代食品工場の附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012862"},{"id":"00012863","register_sub_id":"101","register_pk":"367973","name":"宮城野納豆製造所休憩室","kana":"みやぎのなっとうせいぞうしょきゅうけいしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市宮城野区銀杏町663他","lat":38.26466111,"lng":140.90913333,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 171","desc":"製造所東棟の東側に接続して建つ。切妻造桟瓦葺の平屋建で、外壁下見板張とする。モルタル土間の一室で、天井と壁をベニヤ張とし、西面南端と北面西端に出入口を設け、東西両面に硝子窓を並べる。建築当初の姿をよく残し、近代食品工場の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012863"},{"id":"00012866","register_sub_id":"101","register_pk":"367976","name":"宮城野納豆製造所車庫","kana":"みやぎのなっとうせいぞうしょしゃこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市宮城野区銀杏町663他","lat":38.26479167,"lng":140.90867778,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 174","desc":"敷地西南隅に東面して建つ製品配送車用の車庫。切妻造桟瓦葺妻入の平屋建で、外壁下見板張、トラス小屋組である。モルタル土間の一室で、壁や天井は張らず、正面全面を開口として鉄製のシャッターを備える。昭和初期における食品工場の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012866"},{"id":"00012861","register_sub_id":"101","register_pk":"367971","name":"宮城野納豆製造所熟成棟","kana":"みやぎのなっとうせいぞうしょじゅくせいとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市宮城野区銀杏町663他","lat":38.26488333,"lng":140.90895833,"geo_status":"db","era":"昭和9年頃／昭和20年代増築、平成29年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 169","desc":"製造棟東棟の西側北半に接続して建つ。切妻造の平屋建で、外壁板張、トラス小屋組である。棟通りに敷設した製造棟から延びるトロッコ軌道に沿って南に発酵用の小室を並べ、北を放冷及び出荷場とする。当所開発の新式発酵室を備えた近代食品工場の基幹施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012861"},{"id":"00012860","register_sub_id":"101","register_pk":"367970","name":"宮城野納豆製造所納豆及び納豆菌製造棟","kana":"みやぎのなっとうせいぞうしょなっとうおよびなっとうきんせいぞうとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市宮城野区銀杏町663他","lat":38.26470833,"lng":140.90898333,"geo_status":"db","era":"昭和9年頃／昭和10年代増築、平成29年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋一部2階建、金属板葺、建築面積331㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 168","desc":"市街地近郊の食品工場。製造棟は敷地中央に南面して建つ。切妻造平屋建の東棟と寄棟造二階建の西棟からなり、事務所兼居室の西棟正面を出入口とする。作業場の東棟は一空間、外壁下見板張、トラス小屋組である。昭和初期の町工場の様相を伝える事務所兼工場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012860"},{"id":"00012864","register_sub_id":"101","register_pk":"367974","name":"宮城野納豆製造所ボイラー室","kana":"みやぎのなっとうせいぞうしょぼいらーしつ","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"昭和中","pref":"宮城県","address":"宮城県仙台市宮城野区銀杏町663他","lat":38.26467222,"lng":140.90906667,"geo_status":"db","era":"昭和25年頃／昭和中期増築、平成17年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 172","desc":"休憩室の南側に接続して建つ。切妻造鉄板葺の平屋建、外壁下見板張、トラス小屋組である。モルタル土間の一室で、南半に煉瓦造の亜炭式ボイラーを設置し、南面外側に煉瓦煙突、東面外側に便所を設ける。近代食品工場の動力設備の様相を伝える附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012864"},{"id":"00010717","register_sub_id":"101","register_pk":"201552","name":"森民酒造店居宅","kana":"もりたみしゅぞうてんいたく","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県大崎市岩出山字上川原町15","lat":38.656968,"lng":140.864928,"geo_status":"db","era":"大正期／昭和40頃・平成18改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋一部2階建、瓦葺、建築面積67㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"04 ‐ 0113","desc":"店舗兼主屋後方から北にのびる廊下で接続する。二階建の居室を主とした建物で、入母屋造で庇を廻らせた玄関を東向きに構える。和風意匠を基調としつつ、一階北室では上下窓やベイウィンドウを設け、天井に中心飾を飾る。大正期らしい洋間付住宅の好例となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010717"},{"id":"00010723","register_sub_id":"101","register_pk":"201558","name":"森民酒造店煙突","kana":"もりたみしゅぞうてんえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県大崎市岩出山字上川原町15","lat":38.656991,"lng":140.864835,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、面積2.1㎡、高さ16m、煉瓦造煙道付","structure_material":"煉瓦造","registered":"2015.11.17(平成27.11.17)","register_no":"04 ‐ 0119","desc":"釜屋から煙道を介して北方に建つ。高さ一六メートルの煉瓦造煙突で、正方形の基部は一辺一・五メートルを測る。躯体は煉瓦をイギリス積とし、途中で焼過煉瓦を帯状にまわして、アクセントをつけている。造酒屋を象徴する地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010723"},{"id":"00010718","register_sub_id":"101","register_pk":"201553","name":"森民酒造店奥座敷","kana":"もりたみしゅぞうてんおくざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県大崎市岩出山字上川原町15","lat":38.657036,"lng":140.864972,"geo_status":"db","era":"明治後期／昭和40頃・平成22改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"04 ‐ 0114","desc":"居宅北側に廊下を介して接続する。平屋建の建物で、十畳二室を東西に並べ、縁を廻らす。北西隅には当初の染付便器を残す便所を突出す。西室には床と違棚、平書院の座敷飾を設える。軒に細丸太と角形の化粧垂木を交互に配るなど、数寄屋意匠を加味した座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010718"},{"id":"00010720","register_sub_id":"101","register_pk":"201555","name":"森民酒造店釜屋","kana":"もりたみしゅぞうてんかまや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県大崎市岩出山字上川原町15","lat":38.656878,"lng":140.864796,"geo_status":"db","era":"明治16頃／昭和40頃・平成19改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積305㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"04 ‐ 0116","desc":"店舗兼主屋の西方に接続し、西方には酒造蔵が建つ。間口の広い東西棟の切妻造で、東妻に庇を付け、真壁造の妻に梁と束組を表す。大釜で酒米を蒸した建物で、内部には煉瓦造の焚口があり、煙道により北方の煙突へ排煙する。酒造工程の一端を伝える大型の釜屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010720"},{"id":"00010722","register_sub_id":"101","register_pk":"201557","name":"森民酒造店北土蔵","kana":"もりたみしゅぞうてんきたどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市岩出山字上川原町15","lat":38.657078,"lng":140.864895,"geo_status":"db","era":"明治後期／平成18改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、鋼板葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"04 ‐ 0118","desc":"敷地北辺中央、離れ座敷と奥座敷の間に東西棟で建ち、通りに面する。もとは一階に穀物、二階に家財道具を収納した。両妻に窓を穿ち、屋根はもと瓦葺であった。外壁は漆喰塗で鉢巻を廻らし、腰には凝灰岩の一種である塩竈石を張り、地方的特色を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010722"},{"id":"00010721","register_sub_id":"101","register_pk":"201556","name":"森民酒造店酒造蔵","kana":"もりたみしゅぞうてんしゅぞうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県大崎市岩出山字上川原町15","lat":38.656968,"lng":140.86466,"geo_status":"db","era":"明治16頃／昭和50頃・平成23改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造平屋建、鋼板葺、建築面積551㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"04 ‐ 0117","desc":"釜屋の西方に接続して東西棟で建ち、桁行三六メートルを測る。土蔵造平屋建で、南辺寄りの一部に仕込み作業用の中二階の床を張る。南東隅には酵母室を設け、小屋はキングポストトラスを組む。酒造場を特徴付ける大型の酒蔵で、周囲の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010721"},{"id":"00010716","register_sub_id":"101","register_pk":"201551","name":"森民酒造店店舗兼主屋","kana":"もりたみしゅぞうてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県大崎市岩出山字上川原町15","lat":38.656839,"lng":140.86488,"geo_status":"db","era":"明治16頃／大正期・昭和30頃・平成21改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋一部2階建、鋼板葺、建築面積184㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"04 ‐ 0112","desc":"旧有備館および庭園の東側、伏流水の豊かな敷地に位置する造酒屋。店舗兼主屋は通りに東面して建つつし二階建で、正面側に土間と板間のミセを配し、背面側を座敷とする。正面は漆喰仕上げとし、出格子と漆喰枠の窓を設けた特徴的な外観で、街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010716"},{"id":"00010719","register_sub_id":"101","register_pk":"201554","name":"森民酒造店離れ座敷","kana":"もりたみしゅぞうてんはなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県大崎市岩出山字上川原町15","lat":38.657119,"lng":140.864823,"geo_status":"db","era":"昭和10頃／平成23改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積99㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"04 ‐ 0115","desc":"敷地内北西方に独立して建つ。北向きに玄関を開く二階建で、隠居屋として建てられた。一階は南に八畳二室、北に居間と台所を配し、二階は床付の六畳とする。一階座敷は西室に床、違棚、平書院を設え、庭側に廻らす縁にガラス窓を多用し、開放的につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010719"},{"id":"00002581","register_sub_id":"101","register_pk":"103571","name":"門間箪笥店塗り工房","kana":"もんまたんすてんぬりこうぼう","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市若林区南鍛冶町143","lat":38.2475359,"lng":140.88867272,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"04 － 0037","desc":"主屋の後方，敷地奥の西側にある。桁行約１６ｍの細長い２階建の建物で，切妻造で桟瓦葺の屋根とし，外壁はモルタル塗仕上げとする。１階は塗り工房，２階は金物工房に用いている。簡素な形態だが，箪笥の製造工程上，欠かせない附属施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002581"},{"id":"00008614","register_sub_id":"101","register_pk":"149335","name":"浅舞酒造吟醸蔵及び酛場","kana":"あさまいしゅぞうぎんじょうぐらおよびもとば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県横手市平鹿町浅舞字浅舞388","lat":39.26336512,"lng":140.4890617,"geo_status":"db","era":"昭和前期／昭和後期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造及び石造平屋建、鉄板葺、建築面積165㎡","structure_material":"土蔵造及び石造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"05 － 0187","desc":"敷地の東南隅に位置する。東西棟の切妻造鉄板葺とする吟醸蔵の北面を葺き降ろして酛場を設ける。吟醸蔵は土蔵造で内部は1室、酛場は石造で東西2室に分ける。酛場北面は地元産の院内石を江戸切仕上げとして積み上げ、窓を3所穿ち、重厚な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008614"},{"id":"00008613","register_sub_id":"101","register_pk":"149334","name":"浅舞酒造仕込み蔵・貯蔵蔵及び作業場","kana":"あさまいしゅぞうしこみぐら・ちょぞうぐらおよびさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市平鹿町浅舞字浅舞388","lat":39.26342129,"lng":140.48874372,"geo_status":"db","era":"大正後期／昭和前期増築・昭和57年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋一部2階建、鉄板葺、建築面積1271㎡","structure_material":"木造平屋一部2階建","registered":"2011.07.25(平成23.07.25)","register_no":"05 － 0186","desc":"店舗東背後に接して建つ。東西棟の大規模な建築で、貯蔵蔵と仕込み蔵を南北に並立させ、その西側に釜場ほか作業場を設ける。西寄棟造、東切妻造とする鉄板葺屋根。東面北寄りには下屋や角屋を付設し、麹室や検査室とする。規模の大きい酒造施設の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008613"},{"id":"00008612","register_sub_id":"101","register_pk":"149333","name":"浅舞酒造店舗","kana":"あさまいしゅぞうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県横手市平鹿町浅舞字浅舞388","lat":39.26344889,"lng":140.48843432,"geo_status":"db","era":"昭和前期／昭和32年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"05 － 0185","desc":"通りに面する東西に長い敷地の西端に位置する。木造平屋建、建築面積119㎡。切妻造鉄板葺の妻入で、南寄りを出入口として切妻造の屋根を付け、北隅には石造の貯油場を付設する。大きな妻面上部は漆喰壁に化粧梁を六段に重ねて、特徴的な構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008612"},{"id":"00009881","register_sub_id":"101","register_pk":"196028","name":"新政酒造愛醸蔵","kana":"あらまさしゅぞうあいじょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町6-71","lat":39.71083595,"lng":140.11462189,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積116㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0202","desc":"明醸蔵北側に東西棟で建つ。土蔵造平屋建、桁行一六・二メートル梁間七・二メートル、切妻造桟瓦葺である。外壁漆喰塗で鉢巻を廻らし、両妻を出入口とする。鉢巻下半と出入口楣部分を黒漆喰仕上げとし、妻壁に「∧ウ」を表す。酒造の中核をなす仕込蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009881"},{"id":"00009883","register_sub_id":"101","register_pk":"196030","name":"新政酒造旧感恩講西籾蔵","kana":"あらまさしゅぞうきゅうかんのんこうにしもみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町6-134","lat":39.7112238,"lng":140.11439822,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積166㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0204","desc":"敷地北辺西寄りに東西棟で建ち、土蔵造平屋建、桁行二五メートル梁間六・七メートル、切妻造、置屋根式の桟瓦葺で、西妻に戸口を設けて庇を付ける。外壁漆喰塗で水切と鉢巻を廻らし、軒先を方杖で支持する。東籾蔵及び米蔵とともに、感恩講の由緒を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009883"},{"id":"00009882","register_sub_id":"101","register_pk":"196029","name":"新政酒造旧感恩講東籾蔵及び米蔵","kana":"あらまさしゅぞうきゅうかんのんこうひがしもみぐらおよびこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町6-23","lat":39.71094779,"lng":140.11496215,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積277㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0203","desc":"敷地北辺東寄りに建つ。東西棟で土蔵造平屋建の東籾蔵と米蔵を直列させ、総桁行三六メートルを測る。切妻造、置屋根式の桟瓦葺で、東妻に戸口と窓を設ける。外壁漆喰塗で水切と鉢巻を廻らし、軒先を方杖で支持する。感恩講の遺構としても価値がある大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009882"},{"id":"00009879","register_sub_id":"101","register_pk":"196026","name":"新政酒造吟醸蔵","kana":"あらまさしゅぞうぎんじょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町6-71","lat":39.71060753,"lng":140.11486935,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積94㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0200","desc":"敷地南東隅、事務所隣に東西棟で建つ。土蔵造平屋建、桁行一三・五メートル梁間七メートル、切妻造、置屋根式の桟瓦葺で、水切と鉢巻を廻らし、東面に漆喰塗の窓二所を穿つ。現在使用される酵母の中で最古品種の「協会六号酵母」発祥の由緒をもつ仕込蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009879"},{"id":"00009880","register_sub_id":"101","register_pk":"196027","name":"新政酒造明醸蔵","kana":"あらまさしゅぞうみょうじょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町6-71","lat":39.7107265,"lng":140.11470041,"geo_status":"db","era":"明治20","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"土蔵造平屋建、鋼板葺、建築面積163㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0201","desc":"吟醸蔵西側に東西棟で建つ仕込蔵。桁行二一・六メートル梁間七・五メートル、土蔵造平屋建、切妻造である。外壁漆喰塗で鉢巻を廻らし、両妻を出入口とする。二重梁で棟木を受ける、当地方に散見される小屋組をもつ仕込み蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009880"},{"id":"00002600","register_sub_id":"101","register_pk":"103590","name":"勇駒酒造本社西蔵","kana":"いさみごましゅぞうほんしゃにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町64","lat":39.20354262,"lng":140.54517025,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造平屋建、鉄板葺、建築面積174㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0088","desc":"敷地西奥，南蔵の北側にある。桁行約１９ｍの土蔵造の貯蔵蔵で，屋根は東西棟の切妻造・鉄板葺を架け，外壁は漆喰塗とする。現在は２階床を撤去しているが，もとは２階建であった。束立式の３重梁で棟木や桁を受け，高大な内部空間をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002600"},{"id":"00002599","register_sub_id":"101","register_pk":"103589","name":"勇駒酒造本社東蔵","kana":"いさみごましゅぞうほんしゃひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"秋田県","address":"秋田県横手市増田町増田字中町64","lat":39.2035268,"lng":140.54550453,"geo_status":"db","era":"江戸末期／明治末期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、鉄板葺、建築面積234㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0087","desc":"店舗の後方，敷地のほぼ中央にある。部材の表面仕上や比例から，東側部が江戸末期頃，西側部が明治末期の増築と考えられる。桁行約３３ｍに及ぶ長大な土蔵造の貯蔵蔵で，屋根は東西棟の切妻造・鉄板葺，正面に重厚な観音扉を設け，全体に丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002599"},{"id":"00002601","register_sub_id":"101","register_pk":"103591","name":"勇駒酒造本社南蔵","kana":"いさみごましゅぞうほんしゃみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町64","lat":39.20344438,"lng":140.54516074,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造平屋一部2階建、鉄板葺、建築面積81㎡","structure_material":"土蔵造平屋一部2階建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0089","desc":"敷地奥，西蔵南側にあり，棟札より明治１９年の建築で，棟梁が石田常蔵と判る。現在は２階床を撤去し，貯蔵蔵としているが，もとは蔵座敷であった。当社の中で最も規模が小さいが，手斧梁風の起り梁を用いた小屋組など，他の蔵に見られない細部も持っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002601"},{"id":"00000933","register_sub_id":"101","register_pk":"101923","name":"石孫本店内蔵","kana":"いしまごほんてんうちぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎162","lat":39.20356388,"lng":140.50871426,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積96㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"05 － 0035","desc":"石孫本店は安政２年（１８５５）創業の醤油醸造元で，各蔵は，店が急成長を遂げた２代目孫左衛門の代につくられた。いずれの蔵も斎藤彦右衛門が棟梁をつとめている。壁面の仕上げ等に特徴がある文庫蔵で，棟札から明治１６年の建築であることが知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000933"},{"id":"00000938","register_sub_id":"101","register_pk":"101928","name":"石孫本店５号蔵","kana":"いしまごほんてんごごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎162","lat":39.20356713,"lng":140.5081846,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積165㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"05 － 0040","desc":"４号蔵の南に建つ蔵で，道路に面して並んで建つ。棟札によって大正５年の建築であることが知られる。仕込み倉庫として使用されており，小屋には洋小屋が用いられている。道路に面して５棟の蔵が並ぶ姿は独特の景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000938"},{"id":"00000936","register_sub_id":"101","register_pk":"101926","name":"石孫本店３号蔵","kana":"いしまごほんてんさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎162","lat":39.20373611,"lng":140.50835844,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積165㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"05 － 0038","desc":"２号蔵の南に建つ蔵で，道路に面して並んで建つ。棟札によって明治３０年の建築であることが知られる。醸造の圧搾工程に用いられる製成庫に用いられる蔵。規模は一号蔵・二号蔵と似るが，小屋には和小屋が用いられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000936"},{"id":"00000935","register_sub_id":"101","register_pk":"101925","name":"石孫本店２号蔵","kana":"いしまごほんてんにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎162","lat":39.20377347,"lng":140.50840394,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積165㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"05 － 0037","desc":"１号蔵の南に建つ蔵で，道路に面して並んで建つ。棟札によって明治４３年の建築であることが知られる。仕込み倉庫として使われており，一号蔵と外観の意匠や規模だけでなく小屋に洋小屋を用いるなど細部の工法もよく似ている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000935"},{"id":"00000937","register_sub_id":"101","register_pk":"101927","name":"石孫本店４号蔵","kana":"いしまごほんてんよんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎162","lat":39.20365812,"lng":140.50827558,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積165㎡","structure_material":"土蔵造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"05 － 0039","desc":"３号蔵の南に建つ蔵で，道路に面して並んで建つ。棟札によって明治３３年の建築であることが知られる。内部は，速造室，仕込場，石造の麹室の三つの部分に分かれる。意匠・工法等は３号蔵とよく似ている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000937"},{"id":"00007607","register_sub_id":"101","register_pk":"108589","name":"奥田酒造店店舗兼主屋","kana":"おくだしゅぞうてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"秋田県","address":"秋田県大仙市協和境字境113","lat":39.612743,"lng":140.322357,"geo_status":"db","era":"昭和32／平成3改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積316㎡","structure_material":"木造平屋一部2階建","registered":"2009.04.28(平成21.04.28)","register_no":"05－0160","desc":"羽州街道に面して建つ。間口１５ｍ、鉄板葺の木造平屋一部２階建で、外壁はモルタルリシン仕上げを基調とし、正面は２階を竪板張、１階に格子を付け、側面に大きく開口をとる。１．５～２寸勾配の緩やかな切妻屋根を巧みに配する、軽快かつ洗練された造形をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007607"},{"id":"00000558","register_sub_id":"101","register_pk":"101548","name":"旧角館製糸工場","kana":"きゅうかくのだてせいしこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県仙北市角館町田町下丁14-3","lat":39.59068088,"lng":140.56523108,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積240㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"05 － 0015","desc":"桁行18間，梁間４間の木造平屋建製糸工場。大正５年頃と昭和40年代後半に移築され，現在では倉庫として利用されている。採光と換気のために越し屋根や壁面上部に開口部を設ける点が特徴で，角館の製糸の歴史を今に伝える建物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000558"},{"id":"00011850","register_sub_id":"101","register_pk":"354912","name":"旧小坂鉱山工作課原動室","kana":"きゅうこさかこうざんこうさくかげんどうしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県鹿角郡小坂町小坂鉱山字古館34-5","lat":40.327381,"lng":140.744639,"geo_status":"db","era":"明治37年／平成26年移築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木骨煉瓦造平屋建、銅板葺、建築面積95㎡","structure_material":"木骨煉瓦造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"05-216","desc":"機械等の製作を行う鍛冶製罐場に、動力を供給する施設。木骨煉瓦造，平屋建で，木造トラスの小屋組による寄棟屋根に換気用の越屋根を設ける。鉱山内の工場施設より明治百年通りに移築され、喫茶店として活用されている。鉱山の町小坂の歴史を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011850"},{"id":"00004900","register_sub_id":"101","register_pk":"105890","name":"國萬歳酒造北仕込蔵","kana":"くにばんざいしゅぞうきたしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋元町142他","lat":39.68439107,"lng":140.08361959,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積165㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"05 － 0127","desc":"作業場の西側に隣接する，諸味の発酵を行う土蔵。桁行９間，梁間４間の土蔵造平屋建で，切妻造，妻入，小屋組キングポストトラスとし，四周に鉢巻を廻す。観音開き土扉を備えた正面入口は，酛場と南仕込蔵の形式を踏襲した装飾的なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004900"},{"id":"00004902","register_sub_id":"101","register_pk":"105892","name":"國萬歳酒造作業場","kana":"くにばんざいしゅぞうさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市新屋元町142他","lat":39.68426017,"lng":140.08374072,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鋼板葺、建築面積303㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"05 － 0128","desc":"主屋背面の酒造工場のほぼ中央に位置する。酒造室，酛場，仕込蔵の各酒造施設と主屋等の居住部分を接続するＬ字形平面の木造平屋建で，小屋組はキングポストトラス。南側を釜場，北側を槽場として用いる複合的作業空間で，醸造過程を知る上で欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004902"},{"id":"00004899","register_sub_id":"101","register_pk":"105889","name":"國萬歳酒造南仕込蔵","kana":"くにばんざいしゅぞうみなみしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市新屋元町142他","lat":39.684315,"lng":140.083496,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積251㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"05 － 0126","desc":"酒造室の西側に位置する，諸味の発酵を行う土蔵。切妻造，妻入で，小屋組はキングポストトラス。桁行１８間，梁間４間の長大な規模を有する。正面入口は，扉廻りを掛子塗とし，周囲を門構風に盛り上げ，上部に眉形の繰形を付けるど，巧みな左官技術をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004899"},{"id":"00004901","register_sub_id":"101","register_pk":"105891","name":"國萬歳酒造室","kana":"くにばんざいしゅぞうむろ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋元町142他","lat":39.68421517,"lng":140.0838501,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、建築面積112㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"05 － 0125","desc":"主屋の中央背面に位置し，酛場と平行して建てられる。桁行７間，梁間４間規模で，真壁造漆喰塗とし，頂部にイギリス積の低い煉瓦壁を載せる。麹つくりに利用される施設で，醸造の工程を知る上で欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004901"},{"id":"00004898","register_sub_id":"101","register_pk":"105888","name":"國萬歳酒造酛場","kana":"くにばんざいしゅぞうもとば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市新屋元町142他","lat":39.684284,"lng":140.083878,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"05 － 0124","desc":"主屋の北側背面に位置する旧文庫蔵で，現在は酒母培養の蔵として利用。桁行７間，梁間３間の土蔵造２階建で，切妻造，妻入とする。観音開きの土扉を備えた正面入口は，門構風に周囲を盛り上げ，上部に眉形の繰形を付けるなど，巧みな左官技術が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004898"},{"id":"00000615","register_sub_id":"101","register_pk":"101605","name":"斎彌酒造店釜場","kana":"さいやしゅぞうてんかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39646109,"lng":140.04988958,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積122㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0021","desc":"事務所の北側に並んで建つ。木造，平屋建で，木造トラスによる小屋組で高く広大な空間を確保し，作業場とする。酒造の生産量が増加した大正期の建築で，当地の酒造業を中心とする醸造業の発展をうかがうことができる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000615"},{"id":"00000611","register_sub_id":"101","register_pk":"101601","name":"斎彌酒造店ギャラリー（旧米蔵）","kana":"さいやしゅぞうてんぎゃらりー（きゅうこめぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39618339,"lng":140.04969376,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積90㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0017","desc":"店舗の西方に壜蔵と漬物蔵の間に並んで位置する平屋建の土蔵。３棟がひとつの覆屋のなかにおさまる。内部を改修してギャラリーとして利用されており，両開き土戸のまぐさに装飾を施すなど特に豪華なつくりの蔵で，屋敷構えの主要な構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000611"},{"id":"00000614","register_sub_id":"101","register_pk":"101604","name":"斎彌酒造店事務所","kana":"さいやしゅぞうてんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39646109,"lng":140.04988958,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建，鉄板葺，建築面積68㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0020","desc":"店舗・住宅の西北方，漬物蔵の北に位置する。平屋建の土蔵の内部を改修して事務所としたもので，もと道具蔵として使われていた。社名の「斎彌」は創業者の斎藤弥太郎の名にちなんだもので，弥太郎は本荘町長を務めるなど地域の有力者であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000614"},{"id":"00000610","register_sub_id":"101","register_pk":"101600","name":"斎彌酒造店住宅・店舗","kana":"さいやしゅぞうてんじゅうたく・てんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39627595,"lng":140.04991806,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造２階建，瓦葺一部銅板葺，建築面積366㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0016","desc":"店舗は，道路に面して庇を差し出すなど基本的には大規模町家と似た構成になるが，２階に洋風のデザインを取り入れるなどその意匠は独特である。店舗の東に庭を囲うように建つ住宅の外観は和風の意匠で，店舗と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000610"},{"id":"00000612","register_sub_id":"101","register_pk":"101602","name":"斎彌酒造店漬物蔵","kana":"さいやしゅぞうてんつけものぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39646109,"lng":140.04988958,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積20㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0018","desc":"店舗の西方に壜蔵，米蔵と並んで建つ平屋建の土蔵。斎彌酒造店が所在する石脇地区は，明治・大正期に醸造業者が軒を並べて賑わったところで，明治３５年の創業時の建物が多く残る斎彌酒造店は往時の繁栄を偲ばせるものとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000612"},{"id":"00000617","register_sub_id":"101","register_pk":"101607","name":"斎彌酒造店中蔵","kana":"さいやしゅぞうてんなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39646109,"lng":140.04988958,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積189㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0023","desc":"店舗・住宅の北に庭を挟んで建つ。比較的に規模の大きな平屋建の土蔵で，内部に酒造用のタンクを並べる。東蔵と並んで建ち，２棟がひとつの覆屋のなかにおさまる。米蔵等に比較すると簡素なつくりであるが，酒造工程を知る上で欠くことのできない建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000617"},{"id":"00000616","register_sub_id":"101","register_pk":"101606","name":"斎彌酒造店西蔵","kana":"さいやしゅぞうてんにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39646109,"lng":140.04988958,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建，瓦葺，建築面積372㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0022","desc":"釜場の北に建つ南北方向に棟を向けて長大な規模を持つ土蔵。内部には酒造用のタンクを並べる。釜場とともに酒造の生産量が増加した大正期につくられた施設で，地域の産業の発展を物語る貴重な建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000616"},{"id":"00000618","register_sub_id":"101","register_pk":"101608","name":"斎彌酒造店東蔵","kana":"さいやしゅぞうてんひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39646109,"lng":140.04988958,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建，瓦葺，建築面積142㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0024","desc":"住宅の北に庭を挟んで建つ平屋建の土蔵で，中蔵と並んで建ち，２棟がひとつの覆屋のなかにおさまる。覆屋は土蔵の壁の周囲に板壁の囲いを設けた形で，簡素ながら規模が大きく，屋敷構えのなかでひときわ目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000618"},{"id":"00000613","register_sub_id":"101","register_pk":"101603","name":"斎彌酒造店壜蔵","kana":"さいやしゅぞうてんびんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39646109,"lng":140.04988958,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積17㎡","structure_material":"土蔵造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0019","desc":"店舗の西方に米蔵，漬物蔵と並んで建つ平屋建の土蔵。３棟をおさめた覆屋は，側面には板を張るが，妻側では下方を下見板張り，上方を漆喰で塗り込め土蔵風につくる。道路に面した屋敷地の境界にあり，屋敷構えをひきしめる役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000613"},{"id":"00000721","register_sub_id":"101","register_pk":"101711","name":"斎彌酒造店文庫蔵","kana":"さいやしゅぞうてんぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39622631,"lng":140.0501131,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積58㎡","structure_material":"土蔵造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0032","desc":"主屋(店舗・住宅)の東方，屋敷地東南隅に建つ２階建の土蔵で，街道に面した妻の意匠に特徴があり、下部を下見板張りにして窓に覆いをつけた気候に配慮した造りになる。西南隅にある壜蔵等の覆屋とともに屋敷構えの上で効果的な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000721"},{"id":"00000722","register_sub_id":"101","register_pk":"101712","name":"斎彌酒造店門","kana":"さいやしゅぞうてんもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇53","lat":39.39613948,"lng":140.05002626,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造棟門，銅板葺，桁行3.3m","structure_material":"木造棟門","registered":"1998.09.02(平成10.09.02)","register_no":"05 － 0033","desc":"主屋(店舗・住宅)の座敷への出入口として道路に面して主屋と文庫蔵の間につくられた小規模な門で，道路側の屋敷構えを整える役割を果たしている。両脇に潜り戸をもうけた武家屋敷風の門で，店舗の入口にある唐破風状の庇と対照的な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000722"},{"id":"00012686","register_sub_id":"101","register_pk":"504380","name":"四同舎（旧湯沢酒造会館）","kana":"しどうしゃ（きゅうゆざわしゅぞうかいかん）","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"秋田県","address":"秋田県湯沢市前森一丁目11-1他","lat":39.16740778,"lng":140.49343583,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造2階建、金属板葺、建築面積273㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"05 － 221","desc":"市中心部に建つ集会施設。鉄筋コンクリート造二階建。白井晟一の設計で、鋼板張黒塗の柱と白タイル張の壁の対比、積雪対策のための独特な形状の軒が外観を特徴づける。ホールは大判硝子を用いて充分な自然光を取込み、花崗岩製の回り階段が存在感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012686"},{"id":"00013209","register_sub_id":"101","register_pk":"366198","name":"鈴木酒造店上座敷","kana":"すずきしゅぞうてんかみのざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県大仙市長野字二日町9","lat":39.540977,"lng":140.532776,"geo_status":"geocoded","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、鉄板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"05 － 0224","desc":"事務所兼主屋の北東に接続し、東西棟で建つ。一二畳の広い一室の座敷の東・南方に、深い庇を架けて板縁と土縁を廻す。北に床、棚、書院を設ける。垂木は疎らにし、軒を軽やかに見せる。イチイや黒檀などの銘木を用いて趣向を凝らした接客空間である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013209"},{"id":"00013213","register_sub_id":"101","register_pk":"366202","name":"鈴木酒造店北蔵","kana":"すずきしゅぞうてんきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県大仙市長野字二日町9","lat":39.54117778,"lng":140.5334,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造平屋建、金属板葺、建築面積69㎡","structure_material":"土蔵造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"05 － 0228","desc":"敷地東辺中央に建つ酒造蔵。西面に出入口を設け、中蔵に通じる。桁行約一三メートルの土蔵。かつては中蔵との間に槽場が設けられ、酒類醸造のための中心的な施設であった。和小屋で組まれる桁行中央筋の大梁は、１本の曲がり材を巧みに用いたものになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013213"},{"id":"00013214","register_sub_id":"101","register_pk":"366203","name":"鈴木酒造店仕込蔵","kana":"すずきしゅぞうてんしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"秋田県","address":"秋田県大仙市長野字二日町9","lat":39.54093333,"lng":140.53334167,"geo_status":"db","era":"昭和40年／平成15年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"土蔵造平屋建、金属板葺、建築面積178㎡","structure_material":"土蔵造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"05 － 0229","desc":"敷地南端中央に建つ。北には中蔵が接続する。桁行約二二メートル、梁間約八メートルと大型の土蔵になる。軸組は柱に貫を多く通す当地の伝統工法を伝える一方、小屋組はキングポストトラスを組む洋小屋とする。造酒屋の歴史的景観を構成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013214"},{"id":"00013208","register_sub_id":"101","register_pk":"366197","name":"鈴木酒造店事務所兼主屋","kana":"すずきしゅぞうてんじむしょけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県大仙市長野字二日町9","lat":39.541475,"lng":140.53308056,"geo_status":"db","era":"明治中期／昭和10年頃・同32年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、鉄板葺、建築面積305㎡","structure_material":"木造平屋一部2階建","registered":"2020.04.03(令和2.04.03)","register_no":"05 － 0223","desc":"大曲から角館へ向かう旧角館街道に北面して妻入で建つ。正面の妻は梁を四段重ねて装飾的に見せる。西に広い通り土間を通し、東に諸室を配す。北東隅には上座敷が接続する。通り土間に面してガラス戸で明るい大開口をとり、豪雪地帯ならではの工夫がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013208"},{"id":"00013212","register_sub_id":"101","register_pk":"366201","name":"鈴木酒造店中蔵及び袖蔵","kana":"すずきしゅぞうてんなかぐらおよびそでぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県大仙市長野字二日町9","lat":39.54115556,"lng":140.53321944,"geo_status":"db","era":"大正前期／昭和10年増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階一部平屋建及び木造平屋建、鉄板葺、建築面積305㎡","structure_material":"土蔵造2階一部平屋建及び木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"05 － 0227","desc":"前蔵の南、仕込蔵の北に接続して建つ。なお西には袖蔵と称する下屋を大きく張り出す。桁行二四メートルを測る大型の土蔵。下屋の北には製法の変化や機械の導入により、枯らし場、試験室、検査場などが増築され、酒造を取り巻く歴史が垣間見える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013212"},{"id":"00013210","register_sub_id":"101","register_pk":"366199","name":"鈴木酒造店文庫蔵","kana":"すずきしゅぞうてんぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県大仙市長野字二日町9","lat":39.54134722,"lng":140.53326111,"geo_status":"db","era":"明治29年／昭和61年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"05 － 0225","desc":"事務所兼主屋の南東に接続して建つ。鈴木家の家財を納めるために建てられた。出入口や窓まわりの鳥居型は黒漆喰を用い、絵様を鏝細工で仕上げる高い左官技術を見せる。内部は平面に比して柱を稠密に立て、壁を丁寧に漆喰で仕上げる当地特有の手法を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013210"},{"id":"00013211","register_sub_id":"101","register_pk":"366200","name":"鈴木酒造店前蔵","kana":"すずきしゅぞうてんまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県大仙市長野字二日町9他","lat":39.54123056,"lng":140.53319722,"geo_status":"db","era":"明治32年","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積143㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"05 － 0226","desc":"事務所兼主屋の南、中蔵の北に接続して建つ。桁行約一九メートルを測る比較的大型の土蔵で、内部で仕込みを行う醸造のための蔵であった。出入口や窓回りの鳥居型などに黒漆喰を用い装飾性を高める。特に出入口扉の掛子塗は見ごたえがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013211"},{"id":"00002594","register_sub_id":"101","register_pk":"103584","name":"日の丸醸造本社麹蔵","kana":"ひのまるじょうぞうほんしゃこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町七日町114-2","lat":39.20225413,"lng":140.54721115,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、鉄板葺、建築面積111㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0082","desc":"中央蔵の北東にあり，現在は麹室として用いている。切妻造・鉄板葺，妻入，外壁漆喰塗の２階建の土蔵造である。桁行規模は約１６ｍであるが，梁間は狭く，太い地棟木上に束を立てて野棟木を支える。基本的に他の蔵と同じ形式で，明治初期の建築と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002594"},{"id":"00002593","register_sub_id":"101","register_pk":"103583","name":"日の丸醸造本社中央蔵","kana":"ひのまるじょうぞうほんしゃちゅうおうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町七日町114-2","lat":39.20214576,"lng":140.54702095,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、鉄板葺、建築面積172㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0081","desc":"屋敷のほぼ中央，店舗の後方にあり，貯蔵倉庫として用いている。桁行約２４ｍの規模で，社内で最も大きい。柱を密に立てて外壁を白漆喰塗とした土蔵造で，屋根は東西棟の切妻造・鉄板葺とする。束立と束なしの２種類がある梁の架構は，南蔵と同じである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002593"},{"id":"00002597","register_sub_id":"101","register_pk":"103587","name":"日の丸醸造本社西蔵","kana":"ひのまるじょうぞうほんしゃにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町七日町114-2","lat":39.20202604,"lng":140.54615174,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積133㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0085","desc":"醸造量が拡大した時期に，店舗と通りを挟んだ対面に建てられた。棟札から大正８年の建立で，棟梁は菅原儀三郎と判明する。東西棟の切妻造・鉄板葺，妻入，外壁を漆喰塗とした土蔵造で，２階床が撤去されたが，立ちの高いつくりに大正期の造形が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002597"},{"id":"00002596","register_sub_id":"101","register_pk":"103586","name":"日の丸醸造本社東後蔵","kana":"ひのまるじょうぞうほんしゃひがしあとぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町七日町114-2","lat":39.20226851,"lng":140.54742753,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造平屋一部2階建、鉄板葺、建築面積179㎡","structure_material":"土蔵造平屋一部2階建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0084","desc":"敷地奥の東側，東前蔵と一体として夫婦蔵とも称されており，桁行規模は東前蔵と同じで，その東側に並んで建つ。外観は東前蔵と同様であるが，小屋組をキングポストトラス組とし，全体に部材も細く，大正期の施設拡充期に建設されたと推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002596"},{"id":"00002595","register_sub_id":"101","register_pk":"103585","name":"日の丸醸造本社東前蔵","kana":"ひのまるじょうぞうほんしゃひがしまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町七日町114-2","lat":39.20226689,"lng":140.5473824,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋一部2階建、鉄板葺、建築面積151㎡","structure_material":"土蔵造平屋一部2階建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0083","desc":"敷地奥の東側にあり，東後蔵と一体として夫婦蔵と称されている。桁行約２２ｍの切妻造・鉄板葺の貯蔵蔵で，外壁は漆喰塗とし，妻面は雨除けの板で覆われている。小屋は豪放な重ね梁式で，太い垂木を棟木から側桁に掛け，よく明治初期の形式を保っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002595"},{"id":"00008240","register_sub_id":"101","register_pk":"133882","name":"日の丸醸造本社文庫蔵","kana":"ひのまるじょうぞうほんしゃぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字七日町109-1","lat":39.2021789,"lng":140.54675282,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積190㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0176","desc":"桁行１２ｍ梁間６．１ｍと大規模な２階建土蔵で、外壁は全面黒漆喰とする。東西棟の切妻造妻入で、鞘を設ける。１階は前後二室に分け、後室にはトコを構える。壁には狭い間隔で柱をたて、軸部は漆塗とする。欄間や障子に繊細な意匠が施され、見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008240"},{"id":"00002592","register_sub_id":"101","register_pk":"103582","name":"日の丸醸造本社南蔵","kana":"ひのまるじょうぞうほんしゃみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町七日町114-2","lat":39.20203169,"lng":140.54699413,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、鉄板葺、建築面積80㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0080","desc":"店舗の後方，南側にあり，現在は米等の材料倉庫に用いている。桁行規模約１１ｍの平屋建，妻入で，屋根は切妻造・鉄板葺，外壁は白漆喰塗である。妻面は束立の３重梁だが，棟中央は束なしの４重梁で棟木や桁を受けており，明治初期頃の形式と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002592"},{"id":"00008087","register_sub_id":"101","register_pk":"132485","name":"ひろ建築工房事務所兼主屋及び土蔵（旧高彦製麺所店舗兼主屋及び土蔵）","kana":"ひろけんちくこうぼうじむしょけんしゅおくおよびどぞう（きゅうたかひこせいめんじょてんぽけんしゅおくおよびどぞう）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県秋田市新屋元町127-1","lat":39.68539855,"lng":140.08428371,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造一部土蔵造2階一部平屋建、鉄板葺、建築面積223㎡","structure_material":"木造一部土蔵造2階一部平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"05 － 0175","desc":"商店などが建ち並ぶ、南北の旧街道に東面して、寄棟造２階建を建て、その奥に両下造の平屋建、２階建土蔵が続く、特徴的な構成をもつ。平面は正面にコミセ、南側に通り土間、北寄りに床上部を配する。コミセ下屋庇に切妻の玄関を構え、伝統的街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008087"},{"id":"00005537","register_sub_id":"101","register_pk":"106525","name":"森九商店工場","kana":"もりきゅうしょうてんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県秋田市新屋表町9-40","lat":39.68079923,"lng":140.08285051,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"05 － 0144","desc":"主屋の東側に，主屋に連続して建つ。桁行８間，梁間５間の規模で，木造平屋建，切妻造，鋼板葺とし，外壁を鉄板張りとする。小屋組を和小屋とし，梁間全長に太い梁を架け，柱の無い広い室内空間を確保する。主屋に続く規模の大きな工場で，醸造所の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005537"},{"id":"00005538","register_sub_id":"101","register_pk":"106526","name":"森九商店仕込蔵","kana":"もりきゅうしょうてんしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県秋田市新屋表町9-40","lat":39.68072195,"lng":140.0830547,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造平屋建、鋼板葺、建築面積101㎡","structure_material":"土蔵造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"05 － 0145","desc":"工場の東に，工場に連続して建つ。桁行６間，梁間３間の規模で，土蔵造平屋建，切妻造，鋼板葺とする。小屋組をトラスとし，外壁は腰を煉瓦張り，上部を鉄板張りとする。東側に両開き戸を開き，東側に奥行２間の下屋をかけ，醸造所の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005538"},{"id":"00014447","register_sub_id":"101","register_pk":"512431","name":"ヤマキチ味噌醤油醸造元主屋","kana":"やまきちみそしょうゆじょうぞうもとおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇8-1他","lat":39.39676667,"lng":140.05418611,"geo_status":"db","era":"大正5年頃／昭和56年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"05 - 0235","desc":"石脇通りに南面する味噌醤油醸造業を営む商家の主屋。平屋建、切妻造妻入鉄板葺で道より後退して建て南に庭を設ける。内部は二列六室で東に縁を付し、西面中央で店舗と接続。梁と束を重ねた豪壮な妻面を通りに見せ、醸造で栄えた地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014447"},{"id":"00014450","register_sub_id":"101","register_pk":"512434","name":"ヤマキチ味噌醤油醸造元工場西棟","kana":"やまきちみそしょうゆじょうぞうもとこうじょうにしむね","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇8-1他","lat":39.39694444,"lng":140.05411111,"geo_status":"db","era":"昭和前期／令和3年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積319㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"05 - 0238","desc":"主屋北に位置する醸造工場。平屋建切妻造妻入鉄板葺で、棟に煙出を二箇所設ける。内部は西に醤油詰場と麹室、東にボイラー室、中央は広大な作業場で上部にキングポスト・トラスを主とした変則的な小屋組を現す。長大な棟が醸造業で栄えた地域の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014450"},{"id":"00014451","register_sub_id":"101","register_pk":"512435","name":"ヤマキチ味噌醤油醸造元工場東棟","kana":"やまきちみそしょうゆじょうぞうもとこうじょうひがしむね","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇8-1他","lat":39.39700278,"lng":140.0543,"geo_status":"db","era":"昭和32年／同38年増築","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋一部コンクリートブロック造2階建、鉄板葺、建築面積305㎡","structure_material":"木造平屋一部コンクリートブロック造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"05 - 0239","desc":"主屋北に位置する醸造工場。二階建切妻造Ｌ字棟の主体部の東北側に平屋建の増築部が取付く。主体部はコンクリートブロック造で西を諸味室、東を温醸室とし二階は二室の倉庫。小屋組は挟み梁の変形トラス。増築を重ねた複雑な外観が醸造業の興隆を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014451"},{"id":"00014448","register_sub_id":"101","register_pk":"512432","name":"ヤマキチ味噌醤油醸造元店舗","kana":"やまきちみそしょうゆじょうぞうもとてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇8-1他","lat":39.3967,"lng":140.05411944,"geo_status":"db","era":"大正5年頃／昭和38年・令和3年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"05 - 0236","desc":"石脇通りに南面し、主屋の西に位置する店舗。平屋建寄棟造妻入鉄板葺で正面に小庇を付す。内部は西に受付、事務室、応接室を並べ、東を全面竿縁天井張の通り土間として、主屋と工場棟への主動線とする。通りに面して主屋と共に地域の歴史的景観をつくる店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014448"},{"id":"00014449","register_sub_id":"101","register_pk":"512433","name":"ヤマキチ味噌醤油醸造元土蔵","kana":"やまきちみそしょうゆじょうぞうもとどぞう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市石脇字石脇8-1他","lat":39.39680556,"lng":140.05429167,"geo_status":"db","era":"大正5年頃／昭和中期移築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"05 - 0237","desc":"主屋の北東に建つ家財蔵。切妻造妻入桟瓦葺の二階建南北棟で、南面に下屋を付して戸前とし、主屋と接続する。外壁は漆喰仕上鉢巻付で、戸口と二階窓に掛子塗の両開戸を吊る。内部は各階とも一室の板敷で南西に階段を設ける。敷地北東の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014449"},{"id":"00015130","register_sub_id":"101","register_pk":"530554","name":"ヤマモ味噌醤油醸造元作業場","kana":"やまもみそしょうゆじょうぞうもとさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎124","lat":39.20631111,"lng":140.51025833,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積345㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0258","desc":"敷地中央で各施設を結節し、醤油の火入れ、濾過、充填を行う作業場。Ｌ字形平面の平屋建切妻造で、外壁に下見板、竪板、鉄板を張る。内部は梁間七間半の広大な土間で、小屋組はキングポスト・トラス。醸造施設の要で採光を図る越屋根が印象的な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015130"},{"id":"00015127","register_sub_id":"101","register_pk":"530551","name":"ヤマモ味噌醤油醸造元仕込蔵","kana":"やまもみそしょうゆじょうぞうもとしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎124","lat":39.20633889,"lng":140.51002222,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積235㎡、煙突付","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0255","desc":"敷地北西部に位置する麹製造及び仕込用の蔵。二階建切妻造平入鉄板葺で、外壁は漆喰塗仕上とし、北東隅に煉瓦造煙突を建てる。各階一室で一階は土間、二階は板敷とし、小屋は太い梁を三段に重ね、母屋と棟木を受ける。長大な土蔵が醸造施設の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015127"},{"id":"00015129","register_sub_id":"101","register_pk":"530553","name":"ヤマモ味噌醤油醸造元酢蔵","kana":"やまもみそしょうゆじょうぞうもとすぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎124","lat":39.20639444,"lng":140.50990833,"geo_status":"db","era":"昭和前期／昭和中期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、鉄板葺、建築面積72㎡","structure_material":"土蔵造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0257","desc":"敷地北西隅、仕込蔵の西に建つ酢の醸造用の蔵。平屋建切妻造鉄板葺で、外壁はモルタル塗仕上とし、西妻と北の諸味蔵側の通路に戸口を設ける。内部は一室の土間で、天井裏に藁スサなどを敷詰め断熱を図る。屋根軒先を金物補強し、積雪に備える雪国らしい土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015129"},{"id":"00015123","register_sub_id":"101","register_pk":"530547","name":"ヤマモ味噌醤油醸造元店舗兼主屋","kana":"やまもみそしょうゆじょうぞうもとてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎124","lat":39.206125,"lng":140.51051111,"geo_status":"db","era":"明治中期／昭和中期・平成28年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、鉄板葺、建築面積203㎡","structure_material":"木造平屋一部2階建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0251","desc":"旧羽州街道に南面して建つ醸造業の店舗兼主屋。二階建切妻造妻入鉄板葺で、正側面に下屋を張出した店舗の北東隅から、主屋の仏間と広縁付座敷を雁行状に連ねる。通りに面した店舗二階に座敷を設える。深い螻羽や梁組を現した妻壁が、街道景観に風趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015123"},{"id":"00015126","register_sub_id":"101","register_pk":"530550","name":"ヤマモ味噌醤油醸造元彦四郎蔵（旧米蔵）","kana":"やまもみそしょうゆじょうぞうもとひこしろうぐら（きゅうこめぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎134","lat":39.20604444,"lng":140.51026111,"geo_status":"db","era":"昭和前期／昭和中期増築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、鉄板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0254","desc":"通りを隔てた西側の角地に南面して建つ旧米蔵。二階建切妻造妻入の置屋根形式で、外壁漆喰塗、腰は簓子下見板張、鉢巻は平側二段、妻側三段と変化を付ける。一階は土間、二階は板敷で、小屋組はキングポスト・トラス。醸造施設と一体で歴史的な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015126"},{"id":"00015124","register_sub_id":"101","register_pk":"530548","name":"ヤマモ味噌醤油醸造元兵助蔵（旧家財蔵）","kana":"やまもみそしょうゆじょうぞうもとへいすけぐら（きゅうかざいぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎124","lat":39.20616111,"lng":140.51035278,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積234㎡、覆屋付","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0252","desc":"店舗北側に建つ旧家財蔵。主屋から一連の鞘で覆った二階建切妻造妻入で、基礎は煉瓦長手積。外壁は黒漆喰磨仕上で、二段の鉢巻を付し、要所に白漆喰仕上を施す。内部は各階板敷で、戸口と窓に掛子塗扉を吊る。地元大工による重厚かつ洗練された意匠の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015124"},{"id":"00015125","register_sub_id":"101","register_pk":"530549","name":"ヤマモ味噌醤油醸造元茂助蔵及び妙見蔵（旧居住蔵及び旧漬物蔵）","kana":"やまもみそしょうゆじょうぞうもともすけぐらおよびみょうけんぐら（きゅうぎょじゅうぐらおよびきゅうつけものぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎124","lat":39.20632778,"lng":140.510325,"geo_status":"db","era":"明治16年","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積213㎡、覆屋付","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0253","desc":"敷地中央部に建つ、二階建切妻造妻入の土蔵。外壁は漆喰塗仕上で、腰は院内石の繰型付きの切石積とし、建物全体を鞘で覆う。一階西側は土間の旧漬物蔵、東側は板敷と畳敷の居住部とし、戸口に掛子塗扉を吊る。土蔵を数多く手がけた地元大工の技量が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015125"},{"id":"00015128","register_sub_id":"101","register_pk":"530552","name":"ヤマモ味噌醤油醸造元諸味蔵","kana":"やまもみそしょうゆじょうぞうもともろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県湯沢市岩崎字岩崎124","lat":39.20646667,"lng":140.51003611,"geo_status":"db","era":"大正前期／昭和中期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造平屋建、鉄板葺、建築面積205㎡","structure_material":"土蔵造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0256","desc":"敷地北東隅に建ち、醤油発酵及び熟成を行う蔵。平屋建切妻造妻入で、外壁はモルタル塗仕上、鉢巻は漆喰塗とし、仕込蔵と作業場の側に戸口を開く。内部は土間で、大型の醤油醸造桶を並べ、木太い梁を用いた和小屋を架ける。伝統的な醸造風景を今に伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015128"},{"id":"00000012","register_sub_id":"101","register_pk":"101002","name":"両関酒造１号蔵","kana":"りょうぜきしゅぞういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県湯沢市前森4-3-18","lat":39.17082146,"lng":140.4934845,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、屋根漆喰塗、建築面積178㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"05 － 0002","desc":"桁行21.7m，梁間7.85mの２階建土蔵建築で，複数の壁付き側柱で肘木状の横材を支え，それによって桁から上の荷重を受ける独特の構法をとる。屋根・壁は漆喰仕上げである。棟札から明治25年建造であることがわかっており，両関酒造の中で最も古い建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000012"},{"id":"00000014","register_sub_id":"101","register_pk":"101004","name":"両関酒造３号蔵","kana":"りょうぜきしゅぞうさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県湯沢市前森4-3-18","lat":39.17104249,"lng":140.49351213,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、屋根漆喰塗、建築面積224㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"05 － 0004","desc":"この蔵のみ棟札が無く年代が確定していないが，構造形式等から見て２号蔵とほぼ同時期の建築と思われる。酒蔵は全てを洋小屋の大屋根で覆っているが，これは保温・除雪に有利なためである。本館とともに酒造で知られる土地柄を今に伝える建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000014"},{"id":"00000013","register_sub_id":"101","register_pk":"101003","name":"両関酒造２号蔵","kana":"りょうぜきしゅぞうにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県湯沢市前森4-3-18","lat":39.17093951,"lng":140.49352093,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、屋根漆喰塗、建築面積416㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"05 － 0003","desc":"桁行56.04m，梁間7.86の土蔵蔵であり，構造的には１号蔵と同様であるが，規模はこちらの方が大きい。昭和39年にエポキシ樹脂製のタンクを収容するために，２階の床面を高くしている。本館とともに酒造で知られる土地柄を今に伝える建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000013"},{"id":"00000011","register_sub_id":"101","register_pk":"101001","name":"両関酒造本館","kana":"りょうぜきしゅぞうほんかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県湯沢市前森4-3-18","lat":39.17081223,"lng":140.49328143,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積215㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"05 － 0001","desc":"両関酒造の全盛期に建てられた事務所併用住宅。住宅部分は平入だが，事務所部分は大屋根をかけて妻入とし，和小屋の骨組みを妻壁に露出して見せている。老舗の風格を表す意匠で，酒所・湯沢のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000011"},{"id":"00000015","register_sub_id":"101","register_pk":"101005","name":"両関酒造４号蔵","kana":"りょうぜきしゅぞうよんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県湯沢市前森4-3-18","lat":39.17084281,"lng":140.49367917,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、屋根漆喰塗、建築面積297㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"05 － 0005","desc":"この蔵は建設当初から貯蔵蔵として設計され，使用されてきた。他の蔵と同じく土蔵蔵・和小屋であるが，梁間が広く，加工形式が若干異なっている。本館とともに酒造で知られる土地柄を今に伝える建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000015"},{"id":"00000017","register_sub_id":"101","register_pk":"101007","name":"渡辺彦兵衛商店上蔵","kana":"わたなべひこべえしょうてんかみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"秋田県","address":"秋田県南秋田郡五城目町字下夕町48","lat":39.94423303,"lng":140.11899481,"geo_status":"db","era":"18世紀末","year":1795,"year_source":"estimated","year_min":1790,"year_max":1800,"year_label":"18世紀末","structure":"土蔵造平屋建、鉄板葺、建築面積284㎡","structure_material":"土蔵造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"05 － 0007","desc":"下蔵とともに大正期の大火に焼け残った建物である。内部の立登せ柱は２間半毎，垂木は３尺間隔であり，単純にして豪快な架構法と太い部材が力強い印象を与えている。事務所・住宅棟と共に酒造りで知られた町並みのランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000017"},{"id":"00000016","register_sub_id":"101","register_pk":"101006","name":"渡辺彦兵衛商店事務所・住宅","kana":"わたなべひこべえしょうてんじむしょ・じゅうたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県南秋田郡五城目町字下夕町48","lat":39.94417482,"lng":140.11928328,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積241㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"05 － 0006","desc":"通りに面する寄棟造妻入の店舗部分と，奥の座敷部分から成る。店舗は通りニワ形式をとり，表から事務室・８畳・居間と並ぶ。座敷部は内玄関をともなう４間取りと８畳からなる平面で，特に奥座敷は庭の眺めもふくめて和風住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000016"},{"id":"00000018","register_sub_id":"101","register_pk":"101008","name":"渡辺彦兵衛商店下蔵","kana":"わたなべひこべえしょうてんしもぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"秋田県","address":"秋田県南秋田郡五城目町字下夕町48","lat":39.94450804,"lng":140.1186944,"geo_status":"db","era":"19世紀初期","year":1805,"year_source":"estimated","year_min":1801,"year_max":1810,"year_label":"19世紀初期","structure":"土蔵造平屋建、鉄板葺、建築面積254㎡","structure_material":"土蔵造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"05 － 0008","desc":"上蔵とともに大正期の大火に焼け残った建物である。規模や外壁の意匠は上蔵とほぼ同一であるが，構造的には若干の差があり，上蔵よりやや建築年代が下るものと考えられる。事務所・住宅棟と共に酒造りで知られる町並みのランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000018"},{"id":"00009428","register_sub_id":"101","register_pk":"194221","name":"井上合名会社座敷蔵","kana":"いのうえごうめいがいしゃざしきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字南町2854他","lat":37.65405298,"lng":139.88039947,"geo_status":"db","era":"大正後期／平成16年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0136","desc":"店舗蔵の北側に東西棟で建つ。土蔵造二階建、切妻造桟瓦葺で、西面を下屋とする。外観は漆喰塗で軒蛇腹を廻らす。内部は下階に座敷飾りを備えた和室を二室並べて三方に縁を廻らし、上階は洋小屋を組み、家財蔵とする。老舗醸造蔵の屋敷構えを形成する座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009428"},{"id":"00009430","register_sub_id":"101","register_pk":"194223","name":"井上合名会社醸造蔵","kana":"いのうえごうめいがいしゃじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県喜多方市字長面3055他","lat":37.65400582,"lng":139.88138866,"geo_status":"db","era":"昭和3年／昭和後期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造平屋一部2階建、鉄板葺、建築面積350㎡","structure_material":"土蔵造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0138","desc":"土蔵造平屋一部二階建、桁行三〇・六メートル梁間一一・五メートル、切妻造鉄板葺。外壁は簓子下見板を高く張り、窓廻りと軒蛇腹を漆喰塗、ほかを中塗仕上げとする。小屋はトラス組を二段重ねた独特な形式になる。醸造業の盛んな喜多方を特徴付ける大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009430"},{"id":"00009429","register_sub_id":"101","register_pk":"194222","name":"井上合名会社店舗蔵","kana":"いのうえごうめいがいしゃてんぽぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県喜多方市字南町2854他","lat":37.65396732,"lng":139.88036615,"geo_status":"db","era":"江戸末期／平成期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積71㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"07 － 0137","desc":"通りに西面して建つ。土蔵造二階建、切妻造、置屋根式の桟瓦葺で、西面と北面を下屋とする。外壁は中塗仕上げで腰にタイルを貼り、上階正面の窓には格子をはめ、鳥居形の窓枠を表す。内部は下階を店舗として上階に座敷を配する。蔵の町に相応しい風格を醸す","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009429"},{"id":"00004195","register_sub_id":"101","register_pk":"105185","name":"奥の松酒造一級蔵","kana":"おくのまつしゅぞういっきゅうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県二本松市亀谷一丁目213","lat":37.5924557,"lng":140.44273732,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造及び鉄筋コンクリート造3階建、瓦葺、建築面積207㎡","structure_material":"土蔵造及び鉄筋コンクリート造3階建","registered":"2004.07.23(平成16.07.23)","register_no":"07 － 0071","desc":"無梁版構造の鉄筋コンクリート造平屋建に，２階建土蔵を載せた仕込蔵で，１階はもと出荷場と伝える。桁行１１間梁間４間規模，南北棟，片寄棟造の桟瓦葺で，小屋組は木造のキングポストトラス。３階建のたちの高い姿は県道沿いのランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004195"},{"id":"00004199","register_sub_id":"101","register_pk":"105189","name":"奥の松酒造麹蔵","kana":"おくのまつしゅぞうこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県二本松市亀谷一丁目213","lat":37.59296267,"lng":140.44278715,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造2階建、金属板葺、建築面積114㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"07 － 0075","desc":"二級蔵の東北方に位置し，ほぼ南北棟で建つ。桁行１３．５ｍ梁間８．４ｍ規模の鉄筋コンクリート造２階建で，２階床はＲＣとし，ＲＣ柱型上に木造のキングポストトラスを組み，金属板菱葺の切妻屋根を架ける。軒廻りは土蔵造風の鉢巻きを廻している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004199"},{"id":"00004196","register_sub_id":"101","register_pk":"105186","name":"奥の松酒造二級蔵北棟","kana":"おくのまつしゅぞうにきゅうぐらきたとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県二本松市亀谷一丁目213","lat":37.59280714,"lng":140.44266713,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、金属板葺、建築面積139㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"07 － 0072","desc":"酒造場のほぼ中央，北寄りに東西棟で建つ。桁行８間半梁間４間半規模，切妻造，金属板葺の仕込蔵で，東西両妻面及び南面に出入口を設け，南面出入口近くに階段を配置する。小屋組は一級蔵と同様のキングポストトラスで，外部軒廻りに土蔵造風の鉢巻きを廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004196"},{"id":"00004197","register_sub_id":"101","register_pk":"105187","name":"奥の松酒造二級蔵中棟","kana":"おくのまつしゅぞうにきゅうぐらなかとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県二本松市亀谷一丁目213","lat":37.59280717,"lng":140.44270956,"geo_status":"db","era":"大正初期／昭和初期改造","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、金属板葺、建築面積99㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"07 － 0073","desc":"北棟の南に接して東西棟で建つ。梁間３間，切妻造，金属板葺で，もと平屋建の麹蔵とみられ，南棟建設時に２階建とするとともに，１階東側を冷蔵室にするなどの改造を行っている。基礎を石積，腰を煉瓦積としており，当醸造場施設で現存するものでは最も古い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004197"},{"id":"00004198","register_sub_id":"101","register_pk":"105188","name":"奥の松酒造二級蔵南棟","kana":"おくのまつしゅぞうにきゅうぐらみなみとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県二本松市亀谷一丁目213","lat":37.59280724,"lng":140.44275232,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造2階建、建築面積119㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"07 － 0074","desc":"中棟の南に接して建つ。桁行１６．２ｍ梁間６．９ｍ規模の鉄筋コンクリート造２階建仕込蔵であるが，２階床は木造で，階上にヒロシキを設ける。陸屋根で，東南西の３面にパラペットを廻し，南面には「奥」「の」「松」を浮き出す。醸造場のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004198"},{"id":"00004200","register_sub_id":"101","register_pk":"105190","name":"奥の松酒造槽場蔵","kana":"おくのまつしゅぞうふなばぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県二本松市亀谷一丁目213","lat":37.59265046,"lng":140.44236187,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積144㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"07 － 0076","desc":"敷地西側街路に西妻面を見せて東西棟で建ち，醸造場正面の南端を構成している。桁行１０間梁間４間規模，切妻造，桟瓦葺の土蔵造２階建で，もと仕込蔵と伝える。東西両妻面の腰は二級蔵南棟と同様の石目地を切って街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004200"},{"id":"00013932","register_sub_id":"101","register_pk":"508192","name":"旧甲斐家住宅稲荷社","kana":"きゅうかいけじゅうたくいなりしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字一丁目4611-1","lat":37.65626111,"lng":139.87185833,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、銅板葺、建築面積1.6㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0257","desc":"主屋南側の庭園南西隅に所在する屋敷神。大振りな自然石を組んだ基壇に建つ一間社流造で、銅板葺。向拝は角柱で三斗組と蟇股、身舎は丸柱で桟唐戸を構え、妻は虹梁大瓶束で飾る。二軒繁垂木の軒や絵様を凝らすなど小規模ながら正統的なつくりとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013932"},{"id":"00013934","register_sub_id":"101","register_pk":"508194","name":"旧甲斐家住宅裏門","kana":"きゅうかいけじゅうたくうらもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県喜多方市字一丁目4611-1","lat":37.65637222,"lng":139.87169722,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、間口2.0m、左右袖壁付","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0259","desc":"市町小荒井の熱塩街道から一本西の通りに面する、醸造業を営んだ商家の裏門。切妻造桟瓦葺の薬医門で両開き板扉を吊り、軒を木舞打、竪格子欄間、格天井で天井廻りの意匠を瀟洒に整える。両脇を板袖塀で塞ぎ、味噌蔵・醤油蔵と一連で屋敷裏側の構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013934"},{"id":"00013933","register_sub_id":"101","register_pk":"508193","name":"旧甲斐家住宅表門","kana":"きゅうかいけじゅうたくおもてもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県喜多方市字一丁目4611-1","lat":37.65636667,"lng":139.872175,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、瓦葺、間口2.6m、左右袖壁付","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0258","desc":"田付川西岸の熱塩街道に面する、醸造業を営んだ商家の表門。通りから引き込んで位置し、店蔵と棟通りを揃える。切妻造本瓦葺の木太い薬医門で、門扉は欅の一枚板を嵌める。潜戸付の瓦葺袖塀を左右に付属して構え、重厚な店蔵とともに歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013933"},{"id":"00013930","register_sub_id":"101","register_pk":"508190","name":"旧甲斐家住宅主屋","kana":"きゅうかいけじゅうたくおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県喜多方市字一丁目4611-1","lat":37.65644722,"lng":139.87197778,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋一部地下一階建、瓦葺、建築面積331㎡","structure_material":"木造平屋一部地下一階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0255","desc":"田付川西岸の市町の小荒井に所在する、醸造業を営んだ商家の住居・事務所棟。切妻造桟瓦葺の背の高い木造平屋建。店蔵の背後に連なり、中廊下の南側に玄関や帳場、北側に座敷を並べ、座敷蔵へ繋がって庭を囲む。地域の豪商に相応しい広壮な主屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013930"},{"id":"00002352","register_sub_id":"101","register_pk":"103342","name":"旧甲斐家住宅醤油蔵","kana":"きゅうかいけじゅうたくしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市字1-4611","lat":37.656494,"lng":139.87175,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積281㎡","structure_material":"土蔵造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"07 － 0057","desc":"醤油製造と貯蔵のための施設で，店蔵北の庭園の奥にあり，座敷蔵（平成１２年登録）に接続して建つ。土蔵造，平屋建，桟瓦葺で，南西部に煉瓦造の煙突を高く築く。内外とも丁寧な造りの大規模な土蔵で，保存状態もよく，現在は資料館として活用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002352"},{"id":"00013935","register_sub_id":"101","register_pk":"508195","name":"旧甲斐家住宅東塀及び北塀","kana":"きゅうかいけじゅうたくひがしべいおよびきたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県喜多方市字一丁目4611-1","lat":37.65668333,"lng":139.87188889,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、瓦葺、延長61m","structure_material":"煉瓦造","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0260","desc":"商家の街道沿いの煉瓦塀。店蔵北から敷地東面と北面を巡って西面の座敷蔵北まで延長六二メートルで、桟瓦葺蛇腹付、高さ四メートル、基部を石張、街道沿い煉瓦タイル張、敷地内側はドイツ壁とする。街道に面した扉口にレリーフを飾り、重厚な店構えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013935"},{"id":"00013931","register_sub_id":"101","register_pk":"508191","name":"旧甲斐家住宅味噌蔵及び麹蔵","kana":"きゅうかいけじゅうたくみそぐらおよびこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字一丁目4611-1","lat":37.6563,"lng":139.87172778,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積105㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0256","desc":"醸造業を営んだ商家の土蔵で、裏門南に連なり敷地南西の外郭となる。切妻造桟瓦葺で、東側に下屋を通して渡廊下で醤油蔵に接続する。味噌蔵は二階建で窓が多く、麹蔵は平屋建で窓は少なく越屋根を設け、両建物は柱壁を共有する。窓廻りに洋風意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013931"},{"id":"00013936","register_sub_id":"101","register_pk":"508196","name":"旧甲斐家住宅南塀","kana":"きゅうかいけじゅうたくみなみべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県喜多方市字一丁目4611-1","lat":37.65623611,"lng":139.87191667,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、瓦葺、延長45m","structure_material":"煉瓦造","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0261","desc":"商家の小路沿いの煉瓦塀。敷地南面から麹蔵に至る延長四五メートル、桟瓦葺蛇腹付、高さ二・五メートル、基部を石張とし、小路沿いは煉瓦タイル張、敷地内側はドイツ壁とする。麹蔵前の扉口は三角アーチとして東塀扉口と意匠を変え、敷地外周景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013936"},{"id":"00013943","register_sub_id":"101","register_pk":"508203","name":"笹正宗酒造稲荷社","kana":"ささまさむねしゅぞういなりしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市上三宮町上三宮字籬山675-1","lat":37.68404167,"lng":139.863875,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.5㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0268","desc":"敷地北面の塀の内側に、主屋土間大戸口に正対して位置する屋敷神。一間社流造銅板葺の小社で、二軒繁垂木、向拝は角柱で身舎は丸柱、三方の縁は腰組で支え高欄を付し、木階五級で浜縁を備える。虹梁等の彫刻や長押の金具に小規模ながら丁寧なつくりが分かる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013943"},{"id":"00013939","register_sub_id":"101","register_pk":"508199","name":"笹正宗酒造仕込蔵","kana":"ささまさむねしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市上三宮町上三宮字籬山675","lat":37.68365833,"lng":139.86421667,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積208㎡","structure_material":"土蔵造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0264","desc":"願成寺門前の造り酒屋の仕込み作業を行う建物で、敷地東寄りに位置する。南北棟の切妻造桟瓦葺、土蔵造平屋建で、クイーンポストトラスの小屋組で梁間を広く、軒も高くしてタンクを並べる。酛蔵や槽蔵と下屋で繋がり、酒造工程と酒造規模拡大に対応する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013939"},{"id":"00013944","register_sub_id":"101","register_pk":"508204","name":"笹正宗酒造正門及び塀","kana":"ささまさむねしゅぞうせいもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県喜多方市上三宮町上三宮字籬山675-1","lat":37.68409167,"lng":139.86378333,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"正門 木造、瓦葺、間口2.3m 塀 瓦葺、総延長35m","structure_material":"正門 木造","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0269","desc":"敷地北面の通りに開く門とこれに連なる塀。起りを付けた切妻造の薬医門で両開き扉を吊る。垂木は吹寄せにして瀟洒に意匠を凝らす。塀は桟瓦葺、真壁造腰板張、上部を雲形の漆喰壁とする連子付の透塀とする。伝統ある造り酒屋の表構えに相応しい景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013944"},{"id":"00013941","register_sub_id":"101","register_pk":"508201","name":"笹正宗酒造貯蔵庫","kana":"ささまさむねしゅぞうちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市上三宮町上三宮字籬山675","lat":37.68358611,"lng":139.86389167,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積263㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0266","desc":"願成寺門前の造り酒屋の貯蔵庫で、敷地南に酛蔵と並行して位置する。南北棟の切妻造桟瓦葺、土蔵造二階建、筵や布を干す二階を酛蔵と渡廊下で繋ぎ、積雪期の作業に役立つ。桁行一八間に及ぶ長大な貯蔵庫で、一階は貯蔵タンクが並び酒造量の多さを物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013941"},{"id":"00013937","register_sub_id":"101","register_pk":"508197","name":"笹正宗酒造店舗兼主屋","kana":"ささまさむねしゅぞうてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市上三宮町上三宮字籬山675","lat":37.68395833,"lng":139.86377222,"geo_status":"db","era":"明治前期／大正10年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺一部瓦葺、建築面積329㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0262","desc":"願成寺門前の上三宮で酒造業を営み、通りから門を入り北面して建つ店舗兼主屋。木造二階建、西を寄棟、東を切妻とする桟瓦葺屋根で、土間・ミセと田の字型平面の一階と、銘木趣味の二階座敷からなる。神棚を掲げるミセの吹抜けが壮大な近世以来の造り酒屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013937"},{"id":"00013940","register_sub_id":"101","register_pk":"508200","name":"笹正宗酒造槽蔵","kana":"ささまさむねしゅぞうふなぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市上三宮町上三宮字籬山675","lat":37.68382778,"lng":139.86425,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積146㎡","structure_material":"土蔵造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0265","desc":"願成寺門前の造り酒屋の絞り作業を行う建物で、敷地北の通り沿い東寄りに位置する。東西棟の切妻造金属板葺、土蔵造平屋建、水仕事を行うため各面に窓を設けて換気に配慮する。仕込蔵や洗い場と下屋で繋がるなど酒造工程に対応し、酒造りの様相をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013940"},{"id":"00013942","register_sub_id":"101","register_pk":"508202","name":"笹正宗酒造文庫蔵","kana":"ささまさむねしゅぞうぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市上三宮町上三宮字籬山675","lat":37.68408611,"lng":139.86365,"geo_status":"db","era":"大正6年／同10年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0267","desc":"願成寺門前通り南端に所在し、屋敷北西角に位置する土蔵。主屋と渡廊下で繋がり家財蔵として使う。切妻造桟瓦葺、土蔵造二階建で腰を石張とし、入口に掛子塗扉、小屋はトラス組。妻面に屋号と楣を構える長大な片開き塗戸が当家の象徴として町並みに映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013942"},{"id":"00013938","register_sub_id":"101","register_pk":"508198","name":"笹正宗酒造酛蔵","kana":"ささまさむねしゅぞうもとぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県喜多方市上三宮町上三宮字籬山675","lat":37.68351944,"lng":139.864025,"geo_status":"db","era":"大正14年頃／平成23年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積170㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0263","desc":"願成寺門前の造り酒屋の酛作りを行う建物。土蔵造二階建で敷地南側に位置する。南を寄棟、北を切妻の桟瓦葺、小屋はトラス組。次の醪工程を行う仕込蔵と下屋で繋がり、酒造用の筵や布を干す貯蔵庫二階と渡廊下で繋ぐなど、雪国の伝統的な酒造工程に対応する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013938"},{"id":"00012472","register_sub_id":"101","register_pk":"367767","name":"末廣酒造嘉永蔵壱号蔵","kana":"すえひろしゅぞうかえいぐらいちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市日新町159他","lat":37.497513,"lng":139.920593,"geo_status":"geocoded","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積365㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0187","desc":"桁行38メートルに及ぶ長大な仕込蔵で、敷地南側面の過半を占めて建つ。土蔵造二階建、東西棟の切妻造で、北面中央に扉口、東面に樽入替え用の戸口を開く。内部は一室で、二階に麹室を設ける。主屋事務所、新蔵と同じく風格ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012472"},{"id":"00012475","register_sub_id":"101","register_pk":"367770","name":"末廣酒造嘉永蔵五号蔵","kana":"すえひろしゅぞうかえいぐらごごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市日新町159他","lat":37.497513,"lng":139.920593,"geo_status":"geocoded","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積219㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0190","desc":"敷地西面全体を占めて建つ貯蔵庫で、北面が四号蔵に接続する。土蔵造二階建、南北棟の切妻造で、東面の左右二箇所に開口部を設ける。一階は酒類置場、二階は道具置場に用いる。造り酒屋の商いに欠かせない建物で、伝統的な酒造施設の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012475"},{"id":"00012473","register_sub_id":"101","register_pk":"367768","name":"末廣酒造嘉永蔵三号蔵","kana":"すえひろしゅぞうかえいぐらさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市日新町159他","lat":37.497513,"lng":139.920593,"geo_status":"geocoded","era":"明治40年／平成13年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積146㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0188","desc":"敷地北側の中央、主屋背面の街路沿いに建つ仕込蔵。土蔵造二階建、東西棟の切妻造で、西面に扉口を開く。煉瓦造現しの腰壁やトラスの小屋組など近代的な造形をみせる。内部の改変があるが外観は伝統的な酒蔵の姿を留め、城下町の街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012473"},{"id":"00012470","register_sub_id":"101","register_pk":"367765","name":"末廣酒造嘉永蔵主屋","kana":"すえひろしゅぞうかえいぐらしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市日新町159他","lat":37.497513,"lng":139.920593,"geo_status":"geocoded","era":"明治42年／大正11年増築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建及び3階建、瓦葺、建築面積414㎡","structure_material":"木造2階建及び3階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0185","desc":"若松城下の旧町人地にある造り酒屋。主屋は東と北が街路に面する敷地東北部を占め、東面して建つ。西側の切妻造三階建の居宅と東側の寄棟造二階建の事務所からなり、事務所二階には36畳の大広間を設ける。城下町の歴史的景観の核をなす大規模近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012470"},{"id":"00012478","register_sub_id":"101","register_pk":"367773","name":"末廣酒造嘉永蔵正面門","kana":"すえひろしゅぞうかえいぐらしょうめんもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市日新町159他","lat":37.497513,"lng":139.920593,"geo_status":"geocoded","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、間口2.2m、左右袖塀付","structure_material":"石造","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0193","desc":"主屋事務所と新蔵の間に東面して建つ。高さ3・3メートルの花崗岩の門柱を間口2・1メートルで立て、門柱間に灯具付鋼管アーチを渡す。両脇に煉瓦造長手積の袖塀を付し、北袖塀に石材で枠を組み、通用口を設ける。和風基調の表構えに彩りを添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012478"},{"id":"00012471","register_sub_id":"101","register_pk":"367766","name":"末廣酒造嘉永蔵新蔵","kana":"すえひろしゅぞうかえいぐらしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市日新町159他","lat":37.497513,"lng":139.920593,"geo_status":"geocoded","era":"明治25年／平成9年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0186","desc":"主屋事務所の南側に建つ蔵座敷。土蔵造二階建、東西棟の切妻造で、西南北三面に扉口、東面に窓を開く。一階は二室の続き間で改変があるが、欄間や箱階段等の造作に当初の姿を留める。主屋事務所と対となって敷地正面に並び、風格ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012471"},{"id":"00012474","register_sub_id":"101","register_pk":"367769","name":"末廣酒造嘉永蔵四号蔵","kana":"すえひろしゅぞうかえいぐらよんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市日新町159他","lat":37.497513,"lng":139.920593,"geo_status":"geocoded","era":"明治40年／平成23年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積146㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0189","desc":"敷地西北隅に三号蔵と並んで建つ土蔵で、一階を米蔵、二階を衣装蔵に用いた。土蔵造二階建、東西棟の切妻造、トラスの小屋組で、南面中央に扉口を開く。内部の改変があるが、三号蔵と同じく外観は当初の姿を留め、城下町の街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012474"},{"id":"00012476","register_sub_id":"101","register_pk":"367771","name":"末廣酒造嘉永蔵煉瓦煙突","kana":"すえひろしゅぞうかえいぐられんがえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市日新町159他","lat":39.7107265,"lng":140.11470041,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、高さ10m","structure_material":"煉瓦造","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0191","desc":"三号蔵近傍にあった釜場の蒸気を排出する施設で、敷地後方の中央部に立つ。基底部1・8メートル角、高さ10メートル、頂部に向けて窄まる形状で躯体を煉瓦のイギリス積とし、外面に山形鋼の補強枠を組む。近代に発展した会津若松の酒造業を象徴する存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012476"},{"id":"00012477","register_sub_id":"101","register_pk":"367772","name":"末廣酒造嘉永蔵煉瓦塀","kana":"すえひろしゅぞうかえいぐられんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市日新町159他","lat":37.497513,"lng":139.920593,"geo_status":"geocoded","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、延長17m","structure_material":"煉瓦造","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0192","desc":"敷地東北隅の街路境に建つ。高さ2・7メートル、躯体を煉瓦の長手積とし、基底部と笠石に花崗岩を用いる。主屋との間には前庭を設け、両端部に石材で枠を組み、通用口を設ける。煉瓦と石の量感ある意匠が、和風建築が建ち並ぶ表構えに彩りを添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012477"},{"id":"00013924","register_sub_id":"101","register_pk":"508184","name":"鈴善蔵座敷","kana":"すずぜんくらざしき","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市中央一丁目138他","lat":37.49955,"lng":139.92939722,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積147㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0249","desc":"店舗西に接して建つ南北棟の土蔵造二階建、切妻造桟瓦葺。漆喰で鉢巻まで塗込め、道路側の腰はスクラッチタイルを貼る。内部は一階の北を作業場、南を続き間座敷とし、東面に二箇所出入口を開ける。二階は倉庫。地元産の赤瓦屋根を冠し屋敷構えの中核をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013924"},{"id":"00013927","register_sub_id":"101","register_pk":"508187","name":"鈴善米炭蔵","kana":"すずぜんこめすみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市中央一丁目141","lat":37.49931389,"lng":139.92969722,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0252","desc":"敷地南東隅に建つ南北棟の土蔵造二階建、切妻造桟瓦葺で、元は米炭の貯蔵庫。漆喰で鉢巻まで塗込め、北妻面に戸前を備えた出入口を開ける。小屋はトラス組で、一階を一室、二階を二室に区画する。屋敷構えの拡張部を構成し、昭和前期の家業隆盛を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013927"},{"id":"00013926","register_sub_id":"101","register_pk":"508186","name":"鈴善貯蔵蔵","kana":"すずぜんちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市中央一丁目138他","lat":37.49935278,"lng":139.92958889,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0251","desc":"敷地南西隅の庭の東方に建つ南北棟の土蔵造二階建、切妻造桟瓦葺の元家財蔵。漆喰で鉢巻まで塗込め、西面に戸前を備えた出入口二箇所を開ける。小屋はトラス組で一、二階とも一室とする。地元産の赤瓦屋根を葺き、城下町有数の商家の屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013926"},{"id":"00013923","register_sub_id":"101","register_pk":"508183","name":"鈴善店舗","kana":"すずぜんてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市中央一丁目138他","lat":37.49956667,"lng":139.92954167,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0248","desc":"城下町の通りに北面して建つ漆器問屋の店舗兼事務所。木造二階建寄棟造桟瓦葺で、一階を店舗、二階を洋室と続き間座敷の応接室とする。外壁は人造石洗出仕上で横目地を切り石張風に見せ、軒下に幾何学模様の帯状飾りを配し、端正な洋風意匠の外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013923"},{"id":"00013925","register_sub_id":"101","register_pk":"508185","name":"鈴善中座敷","kana":"すずぜんなかざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市中央一丁目138他","lat":37.49951389,"lng":139.92954722,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0250","desc":"店舗南面及び蔵座敷東面に接する八畳と一〇畳の座敷を廻廊でつなぎ、中庭をつくる。木造平屋建、両下造桟瓦葺で東面北端に入母屋造の玄関を付し、店舗二階へ上がる階段を納める。床の間等に数寄屋意匠を取り入れ、市内有数の商家の主要棟の一画をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013925"},{"id":"00013929","register_sub_id":"101","register_pk":"508189","name":"鈴善荷造り蔵","kana":"すずぜんにづくりぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県会津若松市中央一丁目138他","lat":37.49952778,"lng":139.92977778,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積49㎡","structure_material":"土蔵造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0254","desc":"通りに面して敷地北東隅に建つ東西棟の土蔵造平屋建、切妻造桟瓦葺で元商品荷造り蔵。漆喰で鉢巻まで塗込め、腰は海鼠壁で道路側のみ人造石洗出し仕上で石張風に目地を切る。内部は１室、小屋はトラス組。地元産赤瓦を葺き、城下の歴史的景観の一角をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013929"},{"id":"00013928","register_sub_id":"101","register_pk":"508188","name":"鈴善物置蔵","kana":"すずぜんものおきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県会津若松市中央一丁目138他","lat":37.4994,"lng":139.92978889,"geo_status":"db","era":"江戸末期／昭和13年頃移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0253","desc":"敷地東端に建つ南北棟の土蔵造二階建、切妻造桟瓦葺で、元商品陳列蔵。漆喰で鉢巻まで塗込め、腰はモルタル塗で石張風に目地を切る。西面に下屋を備えて出入口を開ける。一、二階とも一室。屋敷構えの拡張部を構成し、昭和前期の家業隆盛を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013928"},{"id":"00014558","register_sub_id":"101","register_pk":"515100","name":"檜物屋酒造店旧店蔵（文庫蔵）","kana":"ひものやしゅぞうてんきゅうみせぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県二本松市松岡173","lat":37.59164722,"lng":140.43376944,"geo_status":"db","era":"明治7年頃","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"07 - 0277","desc":"二本松市街地に位置する造り酒屋の旧店蔵。二階建切妻造、置屋根形式の桟瓦葺で正面に下屋を付す。二階は二箇所窓を開け外壁は中塗仕上。内部一階の上屋柱筋に摺上戸を残し店蔵の形式を留める。軒まで塗込めた重厚な土蔵造が、奥州街道の角地の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014558"},{"id":"00014559","register_sub_id":"101","register_pk":"515101","name":"檜物屋酒造店仕込蔵","kana":"ひものやしゅぞうてんしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県二本松市松岡173","lat":37.59156111,"lng":140.43359722,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積176㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"07 - 0278","desc":"二本松市街地に位置する造り酒屋の仕込蔵。二階建の長大な南北棟で北を寄棟造、南を切妻造とする。内部一階は一室の土間で北東隅に階段を配し、二階は一室の板敷で小屋組はキングポスト・トラス。三箇所の窓がある北妻の端正な外観が奥州街道の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014559"},{"id":"00013022","register_sub_id":"101","register_pk":"368332","name":"福西本店主屋","kana":"ふくにしほんてんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49749444,"lng":139.927325,"geo_status":"db","era":"大正4年頃／平成28年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺一部金属板葺、建築面積274㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0215","desc":"店蔵東に接続し、南西の玄関に店蔵への戸口を設ける。１階はガラス障子を廻らせた帳場を中心に、北に店主室、南に水回りを配し、離座敷を経て座敷蔵東の屋外便所まで廊下を延ばす。２階は接客用の座敷３室、計３５畳を矩折れに配す。上質な造作の住居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013022"},{"id":"00013024","register_sub_id":"101","register_pk":"368334","name":"福西本店主屋蔵","kana":"ふくにしほんてんおもやぐら","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49743611,"lng":139.92745556,"geo_status":"db","era":"明治19年／平成28年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0217","desc":"主屋東寄りに取り込まれるように建つ東西棟で、外壁は漆喰塗とする。西妻は主屋廊下に、東妻は蔵前廊下に戸口を設け、漆喰塗扉を両開きとする。元は商品蔵であるが、内部は２階床の一部撤去などの改修がある。長大な母屋、棟木など豪壮な小屋組を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013024"},{"id":"00013023","register_sub_id":"101","register_pk":"368333","name":"福西本店座敷蔵","kana":"ふくにしほんてんざしきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49752222,"lng":139.92746944,"geo_status":"db","era":"明治19年／平成28年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0216","desc":"敷地北辺中央に東西棟で建つ。外壁は漆喰塗で、腰を板張とする。主屋の主人室東から延びる廊下に戸口を開き、黒漆喰塗の扉を両開きとする。１階は改修で１室としたが元は３室で、床、棚、書院は中室に設けていた。木部は透漆塗で華やかな造作の座敷蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013023"},{"id":"00013021","register_sub_id":"101","register_pk":"368331","name":"福西本店袖蔵","kana":"ふくにしほんてんそでぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49758333,"lng":139.92724167,"geo_status":"db","era":"明治19年／平成28年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0214","desc":"街路に面し店蔵の北に建つ東西棟である。外壁は黒漆喰塗で、西妻の窓上に銅板葺の小庇をつける。南の店蔵１階と東の蔵前に戸口を開き、西半は商品倉庫、東半の６畳は床棚を備えた仏間とする。２階は家財を収めた。店蔵と統一した外観が街路景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013021"},{"id":"00013025","register_sub_id":"101","register_pk":"368335","name":"福西本店離座敷","kana":"ふくにしほんてんはなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49735556,"lng":139.92752778,"geo_status":"db","era":"昭和5年頃／平成28年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺一部金属板葺、建築面積78㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0218","desc":"若夫婦用に建てたと伝わり、主屋の東に接続する。１階は６畳２室、２階は８畳と６畳の続き間座敷で、北から東へ廻らせた縁にガラス障子を建込み、東の庭を望む。１階は木部を透漆塗、２階は素木として雰囲気を異にする。丁寧な造作の数寄屋風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013025"},{"id":"00013020","register_sub_id":"101","register_pk":"368330","name":"福西本店店蔵","kana":"ふくにしほんてんみせぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49750278,"lng":139.92719167,"geo_status":"db","era":"大正3年頃／昭和60年代・平成28年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積102㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0213","desc":"街路に西面し、正面下屋に看板台を揚げる。外壁は黒漆喰塗で２階窓は銅板張の両開きとする。１階は下屋境にイオニア式円柱を立て、上がり框は隅を円弧に作り、天井など木部は透漆塗とする。２階は８畳座敷と洋間である。重厚な外観と美麗な内装の店蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013020"},{"id":"00013026","register_sub_id":"101","register_pk":"368336","name":"福西本店煉瓦塀","kana":"ふくにしほんてんれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県会津若松市中町321他","lat":37.49758333,"lng":139.92732778,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造、延長12m","structure_material":"煉瓦造","registered":"2019.12.05(令和1.12.05)","register_no":"07 － 0219","desc":"敷地の北辺、袖蔵と蔵座敷の間を隣地と仕切り、主屋北の中庭の背景となる。袖蔵の蔵前と主屋の店主室に沿う部分は高く、中庭部分は低く切り下げて造る。基礎は切石で、煉瓦のイギリス積とし、上部に瓦を葺く。延焼に備えつつ、敷地北面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013026"},{"id":"00013946","register_sub_id":"101","register_pk":"508206","name":"若喜商店作業蔵","kana":"わかきしょうてんさぎょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県喜多方市字三丁目4786","lat":37.649825,"lng":139.87160556,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積130㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0271","desc":"敷地南西の醸造場南に接する東西棟の土蔵造二階建、切妻造桟瓦葺の建物。漆喰仕上鉢巻付で軒まで塗込み、腰を板張。桁行が長く中間で仕切り、東側は瓶詰作業場で、通りに近い西側は出荷倉庫で妻面に出入口を開く。醸造業を営む商家の屋敷構えの一画をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013946"},{"id":"00013945","register_sub_id":"101","register_pk":"508205","name":"若喜商店醸造場","kana":"わかきしょうてんじょうぞうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字三丁目4786","lat":37.649925,"lng":139.87169167,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積252㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"07 - 0270","desc":"味噌醤油醸造元の主屋南東に建つ南北棟の木造二階建で、切妻造桟瓦葺、梁間五間半にトラスを架けた大空間の醸造場。内部は西寄りに高床式作業指示所や北側に二階を設ける。一連の醸造施設の中核をなし、東側に立つ煉瓦造煙突が特色ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013945"},{"id":"00015137","register_sub_id":"101","register_pk":"530561","name":"羽前絹練株式会社検査棟","kana":"うぜんけんれんかぶしきがいしゃけんさとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県鶴岡市新海町21-3","lat":38.72838333,"lng":139.81709444,"geo_status":"db","era":"昭和18年頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積357㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0227","desc":"敷地の南端に位置し、生地を目視検査した後、出荷用に分割する検査棟。平屋建切妻造桟瓦葺、外壁は下見板張。内部は一室の板間で、かつては北側に窓を開け、自然光を用いて検査した。簡素なつくりながら昭和戦前の精練の様相を伝え、敷地南辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015137"},{"id":"00015132","register_sub_id":"101","register_pk":"530556","name":"羽前絹練株式会社事務所及び仕立棟","kana":"うぜんけんれんかぶしきがいしゃじむしょおよびしたてとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72854722,"lng":139.81762778,"geo_status":"db","era":"昭和15年／昭和中期増築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積705㎡","structure_material":"木造平屋一部2階建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0222","desc":"鶴ヶ岡城跡西方にある絹織物精練工場の事務所及び仕立棟。敷地北東に建つ二階建の事務所は北に玄関を付し、南に平屋建の仕立棟を接続。仕立棟には反物を木枠に巻取り、精練用に仕立てる一四〇畳の準備室を配す。切妻屋根を重ねた外観が工場の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015132"},{"id":"00015133","register_sub_id":"101","register_pk":"530557","name":"羽前絹練株式会社精練棟","kana":"うぜんけんれんかぶしきがいしゃせいれんとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72886667,"lng":139.81744167,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺及び鉄板葺、建築面積368㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0223","desc":"仕立棟の北側に位置し、絹織物を水槽で煮て不純物を除去する作業棟。Ｌ字形平面で切妻屋根頂部の越屋根と南・北面の開口から高熱の蒸気を排出。内部は土間で、生地を水槽に移動するレールをクイーンポスト・トラス下に設える。工場の中核をなす施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015133"},{"id":"00015134","register_sub_id":"101","register_pk":"530558","name":"羽前絹練株式会社染色棟（旧染色室及び旧汽罐室）","kana":"うぜんけんれんかぶしきがいしゃせんしょくとう（きゅうせんしょくしつおよびきゅうきかんしつ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72892778,"lng":139.81719722,"geo_status":"db","era":"昭和4年／昭和8年頃・同中期増築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0224","desc":"精練棟の西側に位置し、精練後の生地を染める作業棟。桟瓦葺の旧染色室の東に、セメント瓦葺の旧汽罐室を増築し、両棟を鉄板葺で繋ぐ。各棟内部は一室の土間とし、蒸気の排気のため、棟中央にそれぞれ越屋根を設ける。増築による外観が工場の発展を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015134"},{"id":"00015135","register_sub_id":"101","register_pk":"530559","name":"羽前絹練株式会社第一仕上棟","kana":"うぜんけんれんかぶしきがいしゃだいいちしあげとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.728725,"lng":139.81739722,"geo_status":"db","era":"大正後期／昭和前期増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺及び鉄板葺、建築面積391㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0225","desc":"工場の中心部に位置し、精練・染色後にすすぎ・脱水・乾燥の仕上工程を担う棟。平屋建で西を寄棟造、東を切妻造とする桟瓦葺の東西棟で、外壁下見板張。内部は土間で上部にキングポスト・トラスを現す。棟に設けた採光・換気用の越屋根が工場景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015135"},{"id":"00015136","register_sub_id":"101","register_pk":"530560","name":"羽前絹練株式会社第二仕上棟","kana":"うぜんけんれんかぶしきがいしゃだいにしあげとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72862778,"lng":139.81717778,"geo_status":"db","era":"大正後期／昭和中期増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺及び鉄板葺、建築面積368㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0226","desc":"第一仕上棟の南に位置し、乾燥収縮した生地を整える作業棟。東西に長い平屋建切妻造桟瓦葺で外壁横板張。棟中央に換気・採光用の越屋根を設ける。内部は土間に巻取機など並べ、上部にキングポスト・トラスを現す。桁行長大で工場中央部の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015136"},{"id":"00015138","register_sub_id":"101","register_pk":"530562","name":"羽前絹練株式会社土蔵","kana":"うぜんけんれんかぶしきがいしゃどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県鶴岡市新海町21-5他","lat":38.72844167,"lng":139.81734444,"geo_status":"db","era":"大正後期／昭和15年移築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"06 - 0228","desc":"事務所及び仕立棟の南端に接続する製品保管用の蔵。桁行六間梁間三間、土蔵造二階建、切妻造妻入桟瓦葺、外壁は漆喰塗仕上。東妻に戸口を開け、内部は各階一室の板敷とし、二階上部にキングポスト・トラスを現す。戸口に掛子塗扉を吊り重厚なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015138"},{"id":"00016350","register_sub_id":"101","register_pk":"536417","name":"オリエンタルカーペット株式会社事務所棟","kana":"おりえんたるかーぺっとかぶしきがいしゃじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"山形県","address":"山形県東村山郡山辺町大字山辺字楯21-1他","lat":38.29496389,"lng":140.2662,"geo_status":"db","era":"昭和23年／昭和35年改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積177㎡","structure_material":"木造3階建","registered":"2025.11.17(令和7.11.17)","register_no":"06 - 0229","desc":"市街地の中心部に位置する絨毯製造会社の事務所。敷地入口近くに建つ、木造三階建、半切妻造鉄板葺で、1、2階の南側や西側を外に張り出す。外壁は下見板張で、一階の腰に緑色タイルを貼る。旧図案室の三階は水平に窓を連続して開く、開放的な外観の事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016350"},{"id":"00016352","register_sub_id":"101","register_pk":"536419","name":"オリエンタルカーペット株式会社染色棟","kana":"おりえんたるかーぺっとかぶしきがいしゃせんしょくとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"山形県","address":"山形県東村山郡山辺町大字山辺字楯21-1他","lat":38.29488333,"lng":140.266475,"geo_status":"db","era":"昭和23年／昭和25年・同41年・同47年増築","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積263㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"06 - 0231","desc":"緞通棟の北方に建つ絨毯の染色工場。平屋建半切妻造鉄板葺の屋根にドーマー窓を設け、棟中央に越屋根を載せる。内部はキングポスト・トラスを用いた無柱の大空間で、染色用機械を配す。外壁は下見板張と漆喰壁で、ガラス窓を多く開け、開放的な外観の染色棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016352"},{"id":"00016351","register_sub_id":"101","register_pk":"536418","name":"オリエンタルカーペット株式会社緞通棟","kana":"おりえんたるかーぺっとかぶしきがいしゃだんつうとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"山形県","address":"山形県東村山郡山辺町大字山辺字楯21-1他","lat":38.29470278,"lng":140.26639722,"geo_status":"db","era":"昭和23年／昭和37年・同47年改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積365㎡","structure_material":"木造平屋一部2階建","registered":"2025.11.17(令和7.11.17)","register_no":"06 - 0230","desc":"敷地南側中央に建つ絨毯の織工場。木造平屋建半切妻造鉄板葺を二棟連ね、外壁は下見板張と漆喰塗。柱や窓枠を桃色に塗装する。内部はキングポスト・トラスを用いた無柱の大空間に織機を配す。屋根のドーマー窓が特徴的な外観で地域産業の様相を伝える緞通棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016351"},{"id":"00016353","register_sub_id":"101","register_pk":"536420","name":"オリエンタルカーペット株式会社マーセライズ棟","kana":"おりえんたるかーぺっとかぶしきがいしゃまーせらいずとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"山形県","address":"山形県東村山郡山辺町大字山辺字東町279他","lat":38.2948,"lng":140.26681389,"geo_status":"db","era":"昭和25年／昭和中期増築","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積406㎡","structure_material":"木造平屋一部2階建","registered":"2025.11.17(令和7.11.17)","register_no":"06 - 0232","desc":"染色棟東隣に建つ、絨毯染色後の艶出加工及び洗濯を行う工場。木造平屋建、半切妻造鉄板葺で棟に三箇所の越屋根を設け、外壁に窓を並べる。西側の乾燥場と洗濯場は吹抜とし、陸梁中央を高めて繋ぐキングポスト・トラスを現す。敷地内に統一的な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016353"},{"id":"00013215","register_sub_id":"101","register_pk":"366204","name":"旧遠万織物（創匠庵）主屋","kana":"きゅうえんまんおりもの（そうしょうあん）おもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市門東町一丁目1028","lat":37.90660833,"lng":140.11109722,"geo_status":"db","era":"大正後期／平成19年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"06 － 0194","desc":"米沢城旧城下町に建つ織物業者の主屋。敷地東寄りに南面して建ち、木造平屋建、桟瓦葺で、道路側を入母屋造とする。6室からなる居室部は天井が高く上質な造りで、その西側の旧台所部は落棟としてトラス組の小屋を現しとする。米沢の織物業の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013215"},{"id":"00013217","register_sub_id":"101","register_pk":"366206","name":"旧遠万織物（創匠庵）新蔵","kana":"きゅうえんまんおりもの（そうしょうあん）しんくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県米沢市門東町一丁目1028","lat":37.90673333,"lng":140.11079167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"06 － 0196","desc":"前蔵の北西に建ち、主屋北面から廊下で蔵前と繋ぐ。東西棟の土蔵造二階建妻入で、屋根は桟瓦葺の置屋根とする。外壁は腰を赤瓦の海鼠壁とし、上部は四隅に柱形を現し、鉢巻を廻す。窓回りには雪囲いを設け、ガラス窓を穿つ。織物業者の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013217"},{"id":"00013216","register_sub_id":"101","register_pk":"366205","name":"旧遠万織物（創匠庵）前蔵","kana":"きゅうえんまんおりもの（そうしょうあん）まえのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市門東町一丁目1028","lat":37.9067,"lng":140.1109,"geo_status":"db","era":"明治6年／平成19年改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"06 － 0195","desc":"主屋の西側に接続し、主屋旧台所部に入り口を開く。東西棟の二階建妻入の土蔵で、桁行5間、梁間3間、屋根は桟瓦葺の置屋根とする。外壁は腰を赤瓦の海鼠壁とし、南面の上下階には掛子塗の両開窓を設ける。米沢大火から焼け残った希少な蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013216"},{"id":"00010727","register_sub_id":"101","register_pk":"201562","name":"旧長谷川製糸所繭蔵・糸蔵及び荷造場","kana":"きゅうはせがわせいししょまゆぐら・いとぐらおよびにづくりば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市矢来四丁目111-3","lat":38.149619,"lng":140.27846,"geo_status":"db","era":"繭蔵・荷造場 大正15 糸蔵 昭和11","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"繭蔵 土蔵造3階建、鉄板葺 糸蔵 石造平屋建、鉄板葺 荷造場 木造平屋建、鉄板葺 建築面積341㎡","structure_material":"繭蔵 土蔵造3階建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0162","desc":"土蔵造三階建の繭蔵の東に石造平屋建の糸蔵を接続し、両蔵の出入口部に木造平屋建の荷造場を附属する。繭蔵は各階一室で内壁を板張、糸蔵は板床、棹縁天井で紙貼壁とし、地階を持つ。製糸工場建築としての希少価値もある建ちの高い土蔵で街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010727"},{"id":"00014717","register_sub_id":"101","register_pk":"518975","name":"小嶋総本店一号蔵","kana":"こじまそうほんてんいちごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90117778,"lng":140.11093333,"geo_status":"db","era":"明治前期／昭和30年代改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、鉄板葺、建築面積146㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0211","desc":"敷地東辺で主屋南に接続する土蔵造の平屋建切妻造置屋根とする。折置組小屋梁に地棟や棟束なしで合掌を組み、合掌中程を受ける束を桁行貫で固め、小舞下地の屋根裏を現した独特の小屋組。東面に鉄格子入窓を並べ白漆喰塗外壁腰に赤瓦海鼠壁とした長大な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014717"},{"id":"00014727","register_sub_id":"101","register_pk":"518985","name":"小嶋総本店北板塀","kana":"こじまそうほんてんきたいたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752","lat":37.90151944,"lng":140.11101389,"geo_status":"db","era":"大正8年頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造、銅板葺、延長16m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0221","desc":"敷地の北辺東端で主屋の北庭を囲う板塀である。高さ二・二メートル。東端は南へ折れて主屋に取付く。切石基礎に土台を据え、四段の貫の表裏に縦板を大和打とする。笠木は銅板包で、北東の出隅は交差して突出し、鳥休につくる。敷地北側の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014727"},{"id":"00014721","register_sub_id":"101","register_pk":"518979","name":"小嶋総本店五号蔵","kana":"こじまそうほんてんごごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90078889,"lng":140.11051667,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積183㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0215","desc":"四号蔵の南に建つ南北棟の土蔵造二階建で、切妻造置屋根とする。北妻が戸口で、南妻は道路に向け窓を開く。高い切石基礎に土台を巡らす。外壁は漆喰塗仕上。一階は仕込蔵、二階は物置とする。小屋組はキングポスト・トラス。敷地南側の景観をつくる仕込蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014721"},{"id":"00014724","register_sub_id":"101","register_pk":"518982","name":"小嶋総本店作業場","kana":"こじまそうほんてんさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90112778,"lng":140.11066111,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積298㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0218","desc":"敷地中央に建つ東西棟の木造平屋建で切妻造の鉄板葺とする。一号蔵の西面南端から西へ延びて、南面に三号蔵と四号蔵の戸口が開き蔵前をなす。小屋組はキングポスト・トラス。北にはボイラー室や瓶詰工場が接続する通路兼作業場で敷地中央部の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014724"},{"id":"00014719","register_sub_id":"101","register_pk":"518977","name":"小嶋総本店三号蔵","kana":"こじまそうほんてんさんごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90095,"lng":140.11077222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、鉄板葺、建築面積151㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0213","desc":"二号蔵の西に並ぶ土蔵造平屋建。切妻造の置屋根は鉄板葺。北妻に漆喰塗戸両開の戸口を設け、外壁は漆喰塗仕上とする。内部は一室の土間で、小屋梁は一部を二重に架けて、合掌を組み、中程を束で受ける。西側は庇を含めて大屋根を一連で葺降した大規模な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014719"},{"id":"00014722","register_sub_id":"101","register_pk":"518980","name":"小嶋総本店倉庫","kana":"こじまそうほんてんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90071944,"lng":140.11085278,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0216","desc":"敷地東辺南端で二号蔵の南に接続する木造平屋建切妻造で鉄板葺とする。二号蔵との取合部は台形平面で東に戸口を設け、外壁は波形鉄板張とする。小屋組はキングポスト・トラスで柱と陸梁を方杖で挟む。内壁は荷摺板を打付ける。敷地南東隅の景観をつくる倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014722"},{"id":"00014716","register_sub_id":"101","register_pk":"518974","name":"小嶋総本店店舗兼主屋","kana":"こじまそうほんてんてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90140278,"lng":140.11091667,"geo_status":"db","era":"大正8年／昭和前期増築、昭和48年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積343㎡","structure_material":"木造平屋一部2階建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0210","desc":"米沢旧城下の造り酒屋で、敷地北端に通りに面して建つ。正面中央に切妻玄関を付したつし二階建。北半が床上で土間寄りの一八畳客間は天井高く、高窓を開く。北に続く座敷は八畳四室を田字に配し、欄間などに意匠を凝らす。間口長大な近代和風の店舗兼主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014716"},{"id":"00014723","register_sub_id":"101","register_pk":"518981","name":"小嶋総本店土蔵","kana":"こじまそうほんてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90152778,"lng":140.1106,"geo_status":"db","era":"明治前期／昭和49年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0217","desc":"敷地の北辺中央に建つ土蔵造二階建で、切妻造の置屋根を鉄板葺とする。東面に両開の戸口を設け、窓は敷地内側の南面の上下階に開く。外壁は白漆喰塗で、腰を赤瓦の海鼠壁とする。小屋組は敷梁に垂木を掛け渡す。造作丁寧な文庫蔵で、敷地北の景観の要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014723"},{"id":"00014718","register_sub_id":"101","register_pk":"518976","name":"小嶋総本店二号蔵","kana":"こじまそうほんてんにごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90095,"lng":140.11089722,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、鉄板葺、建築面積142㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0212","desc":"敷地の東辺で、一号蔵の南に通路を介して連なる土蔵造の平屋建で、切妻造の置屋根とする。南北両妻戸口に両開漆喰塗戸を吊る。外壁は漆喰塗で腰を赤瓦の海鼠壁とする。小屋組はキングポスト・トラスである。一号蔵と共通の意匠が整った街路景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014718"},{"id":"00014725","register_sub_id":"101","register_pk":"518983","name":"小嶋総本店三日月稲生社本殿","kana":"こじまそうほんてんみかづきいなりしゃほんでん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県米沢市本町二丁目752","lat":37.90143611,"lng":140.11056111,"geo_status":"db","era":"昭和4年／昭和49年移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.9㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0219","desc":"主屋西の中庭に東面して建つ入母屋造、向拝付の祠で銅板葺とする。基壇上に建ち、正面は格子窓とし、両脇間を板壁とする。南面戸口は片引板戸で、内部は折上格天井とする。背面に突出した神棚に切妻屋根を架ける。造り酒屋の屋敷神で木柄太く質実な祠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014725"},{"id":"00014726","register_sub_id":"101","register_pk":"518984","name":"小嶋総本店門及び板塀","kana":"こじまそうほんてんもんおよびいたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市本町二丁目752","lat":37.90143889,"lng":140.11103889,"geo_status":"db","era":"大正8年頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"門 木造、銅板葺、間口1.9m 板塀 木造、銅板葺、総延長7.8m","structure_material":"門 木造","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0220","desc":"主屋東の前庭を閉ざす門と板塀。門は一間一戸の腕木門で一軒疎垂木とする。切妻屋根は銅板葺で銅板包の大棟両端を鳥休につくる。門口には引違板戸を建込む。板塀は土台建で四段の貫の表裏に縦板を大和打とする。銅板包笠木の南端も鳥休とした丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014726"},{"id":"00014720","register_sub_id":"101","register_pk":"518978","name":"小嶋総本店四号蔵","kana":"こじまそうほんてんよんごうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県米沢市本町二丁目752他","lat":37.90098611,"lng":140.11056944,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、鉄板葺、建築面積148㎡","structure_material":"土蔵造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"06 - 0214","desc":"敷地中央、三号蔵西に並ぶ土蔵造平屋建で切妻造置屋根の鉄板葺。切石基礎に煉瓦を二段積み、切石を廻らせ柱を立て、外壁は漆喰塗仕上。内部は１室の土間で小屋組はキングポスト・トラスとし合掌中程に束を立てる。南北両妻に両開き戸口を設けた長大な仕込蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014720"},{"id":"00012094","register_sub_id":"101","register_pk":"352893","name":"佐藤繊維旧紡績工場西棟","kana":"さとうせんいきゅうぼうせきこうじょうにしとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県寒河江市元町一丁目19-3他","lat":38.372986,"lng":140.273332,"geo_status":"db","era":"昭和9年頃／昭和27年移築、平成28年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造2階建、金属板葺、建築面積434㎡","structure_material":"石造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"06-187","desc":"昭和九年頃に建てられた石造倉庫を、昭和二七年に現在地に移築したもの。桁行四五メートル、梁間九・六メートル、大谷石による総二階建で、キングポストトラスの木造の小屋組を載せ、切妻造鋼板葺とする。四周の壁面上部に石積二段を廻らし鉢巻状とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012094"},{"id":"00012093","register_sub_id":"101","register_pk":"352892","name":"佐藤繊維旧紡績工場東棟","kana":"さとうせんいきゅうぼうせきこうじょうひがしとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県寒河江市元町一丁目19-3他","lat":38.37284,"lng":140.273451,"geo_status":"db","era":"昭和9年頃／昭和24年移築、平成28年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造平屋建、金属板葺、建築面積359㎡","structure_material":"石造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"06-186","desc":"昭和九年頃に建てられた石造倉庫を、昭和二四年に現在地に移築したもの。桁行三三メートル、梁間一〇・九メートルで、大谷石を積んだ壁体にキングポストトラスの木造の小屋組を載せ、切妻造鋼板葺とする。比較的規模の大きい石造倉庫建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012093"},{"id":"00000322","register_sub_id":"101","register_pk":"101312","name":"樽平酒造主屋","kana":"たるへいしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2886","lat":38.01386633,"lng":140.04969546,"geo_status":"db","era":"元禄8頃／昭和7改装","year":1695,"year_source":"db","year_min":1695,"year_max":1695,"year_label":null,"structure":"木造2階建，茅葺，建築面積430㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0010","desc":"元禄年間創業の酒造会社の事務所兼家屋。茅葺きの民家に，２階建て長方形平面の事務所部分を接続する。街路に面した事務所部分と農家型平面の茅葺き民家のコントラストが特徴的で，街道に面した川西町への入口のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000322"},{"id":"00000328","register_sub_id":"101","register_pk":"101318","name":"樽平酒造樽蔵","kana":"たるへいしゅぞうたるぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2910-1","lat":38.01389906,"lng":140.05215674,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建，鉄板葺，建築面積142㎡","structure_material":"土蔵造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0016","desc":"前蔵の北側，土蔵の東側に建つ。妻面は後補材が付されているが，道路に面した側は当初の構成を残しており，土蔵としては比較的大きめな開口部などが特徴である。現在では間に道路が敷設されているが，樽平酒造の他の建物と連続した景観を作り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000328"},{"id":"00000326","register_sub_id":"101","register_pk":"101316","name":"樽平酒造土蔵","kana":"たるへいしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2886","lat":38.01386633,"lng":140.04969546,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建，鉄板葺，建築面積85㎡","structure_material":"土蔵造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0014","desc":"長大な中蔵等と異なり，標準的な規模の土蔵である。街路に平行して建ち，平を見せる。軽快な置屋根と壁面のコントラストが特徴。東蔵の妻面から連なる壁面が，街道沿いのランドマークとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000326"},{"id":"00000323","register_sub_id":"101","register_pk":"101313","name":"樽平酒造中蔵","kana":"たるへいしゅぞうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2961","lat":38.01326753,"lng":140.04899197,"geo_status":"db","era":"18世紀中頃","year":1750,"year_source":"estimated","year_min":1731,"year_max":1770,"year_label":"18世紀中頃","structure":"土蔵造平屋建，鉄板葺，建築面積428㎡","structure_material":"土蔵造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0011","desc":"主屋に近接して建ち，各蔵の中心部に配置されて樽平酒造の醸造施設の中核部分をなしている。蔵としては桁行の長い点が特徴的で，西側からは長大なファサードが望まれる。酒造施設としての土蔵造建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000323"},{"id":"00000325","register_sub_id":"101","register_pk":"101315","name":"樽平酒造西蔵","kana":"たるへいしゅぞうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2960","lat":38.01326753,"lng":140.04899197,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建，鉄板葺，建築面積205㎡","structure_material":"土蔵造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0013","desc":"中蔵の北端に，東蔵と相対して建つ。内部には東蔵と同じく醸造タンクを収容している。中蔵と比較するとやや建ちが低いのが相違点で，壁面には開口部を設けていない。中蔵・東蔵と並んで，土蔵造醸造施設の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000325"},{"id":"00000324","register_sub_id":"101","register_pk":"101314","name":"樽平酒造東蔵","kana":"たるへいしゅぞうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2962","lat":38.01219434,"lng":140.04913193,"geo_status":"db","era":"19世紀初期","year":1805,"year_source":"estimated","year_min":1801,"year_max":1810,"year_label":"19世紀初期","structure":"土蔵造平屋建，鉄板葺，建築面積162㎡","structure_material":"土蔵造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0012","desc":"中蔵の北端に直角に接続して建つ。現在は主に醸造タンクを収容しており，醸造施設の一端を担っている。東側の妻は街路に接し，隣接する建物と共に三角の屋根端を見せ，リズミカルな景観を形成しており，主屋と共に川西町のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000324"},{"id":"00000327","register_sub_id":"101","register_pk":"101317","name":"樽平酒造前蔵","kana":"たるへいしゅぞうまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県東置賜郡川西町大字中小松2910-1","lat":38.01389906,"lng":140.05215674,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建，鉄板葺，建築面積79㎡","structure_material":"土蔵造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"06 － 0015","desc":"国道を挟んで，主屋と相対して建つ。２階建で，大きく張り出す軒が特徴的な土蔵であり，街路側の妻に下屋を付している。反対側の建物と相まって白い壁面が連続する景観を作り出しており，道路改修前の敷地の様子を現在に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000327"},{"id":"00006986","register_sub_id":"101","register_pk":"107968","name":"長沼合名会社仕込蔵","kana":"ながぬまごうめいがいしゃしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.112816,"lng":140.036346,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、鉄板葺、建築面積142㎡","structure_material":"土蔵造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0103","desc":"敷地の西北隅、中蔵の北に位置する。土蔵造平屋建。南北棟の切妻造鉄板葺置屋根とし、南面に鉄扉をたて、東面と北面に窓を開ける。桁行１９ｍ梁間７．６ｍで、外壁は漆喰塗とする。コンクリート床で、小屋組をトラス組とするなど、中蔵と同様の仕様とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006986"},{"id":"00006985","register_sub_id":"101","register_pk":"107967","name":"長沼合名会社中蔵","kana":"ながぬまごうめいがいしゃなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.112675,"lng":140.03627,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、鉄板葺、建築面積117㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0102","desc":"主屋の西北に東西棟で建つ。桁行１６ｍ梁間７．３ｍの土蔵造２階建、切妻造鉄板葺置屋根とする。内外とも壁は漆喰仕上げで、扉を鉄扉とし、出入口まわりに地元産の石を組む。内部は１階はコンクリート床で貯蔵タンクを置き、２階は板敷で、小屋トラス組とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006985"},{"id":"00006984","register_sub_id":"101","register_pk":"107966","name":"長沼合名会社前蔵","kana":"ながぬまごうめいがいしゃまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市十日町1-652-1他","lat":38.11253793,"lng":140.03681907,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造平屋建、鉄板葺、建築面積110㎡","structure_material":"土蔵造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"06 － 0101","desc":"主屋の正面、十日町通りに妻を見せる南北に細長い土蔵。江戸末から明治に建築された３棟の土蔵を、酒造のために繋いで一体としたもので、精米やその貯蔵に使われた。切妻造鉄板葺の置屋根。土蔵造平屋建で、もとは２階床を張った。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006984"},{"id":"00007447","register_sub_id":"101","register_pk":"108429","name":"丸や芳賀醤油店穀蔵","kana":"まるやはがしょうゆてんこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県長井市栄町455","lat":38.10807014,"lng":140.03731586,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"06 － 0113","desc":"火入れ蔵の西北に、東西棟で建つ。桁行１１ｍ梁間４．６ｍの土蔵造２階建、切妻造鉄板葺の置屋根。外壁は漆喰仕上げで、腰竪板を張り、東面に両開戸を吊り、入口には地元産の石を組む。南面２ヶ所に窓を開け、１、２階通しの掛子塗戸をたてる特徴的仕様を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007447"},{"id":"00007446","register_sub_id":"101","register_pk":"108428","name":"丸や芳賀醤油店火入れ蔵","kana":"まるやはがしょうゆてんひいれぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市栄町455","lat":38.108017,"lng":140.037491,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、鉄板葺、建築面積53㎡","structure_material":"土蔵造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"06 － 0112","desc":"通りの西に占める敷地のやや奥に、東西棟で建つ。桁行９．３ｍ梁間５．６ｍの土蔵造平屋建、切妻造鉄板葺。外壁は漆喰仕上げで、腰板を張り、西面に戸口を穿つ。南面には４ヶ所に窓を開け、窓枠を丁寧に塗り上げる。内部は一室で、和小屋組とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007446"},{"id":"00008415","register_sub_id":"101","register_pk":"134811","name":"山一醤油店仕込み場","kana":"やまいちしょうゆてんしこみば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市あら町2471","lat":38.10161315,"lng":140.03892838,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"06 － 0121","desc":"醤油蔵の後方に軸線をずらして建ち、桁行二七メートル梁間六・五メートル、平屋建で、小屋はトラスを組み、切妻造鉄板葺とする。内部には水路による洗い場や煉瓦窯があり、最奥に土蔵造の味噌室と麹室をつくる。伝統的な醸造工程をよく伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008415"},{"id":"00008414","register_sub_id":"101","register_pk":"134810","name":"山一醤油店醤油蔵","kana":"やまいちしょうゆてんしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市あら町2471","lat":38.10157261,"lng":140.03867084,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"06 － 0120","desc":"店舗事務所棟背面に接続し、桁行二四メートル梁間八・八メートル、土蔵造平屋建、切妻造鉄板葺で、小屋はトラス組とする。外壁は、腰を石積風に仕上げ、掛子塗の扉や鉄扉を吊った窓を連続させて配するなど、重厚な外観をもつ大型の醤油蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008414"},{"id":"00008413","register_sub_id":"101","register_pk":"134809","name":"山一醤油店店舗","kana":"やまいちしょうゆてんてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県長井市あら町2471","lat":38.10158454,"lng":140.03825114,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺、建築面積248㎡","structure_material":"木造2階一部平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"06 － 0119","desc":"旧街道に西面する短冊形敷地前面に建ち、正面を切妻造平入の店舗棟、後方を両下造の事務所棟とし、間口九・二メートル奥行二六メートル、鉄板葺である。正面に格子を建て、内部の南側を通り土間とするなど、長井の伝統的な商家の形態をよく留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008413"},{"id":"00011263","register_sub_id":"101","register_pk":"209099","name":"足尾銅山電話資料館（旧足尾銅山電話交換所）","kana":"あしおどうざんでんわしりょうかん（きゅうあしおどうざんでんわこうかんしょ）","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"栃木県","address":"栃木県日光市足尾町2281","lat":36.642764,"lng":139.450059,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0231","desc":"足尾銅山には明治一九年に電話が架設され、国内では民間初の私設電話であった。現在の建物は昭和二六年に間藤交換所の機能を移したもので、比較的小規模なものとなる。モルタル塗の外壁に縦長窓を並べ、寄棟造の屋根を架けた文化住宅を思わせる外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011263"},{"id":"00007179","register_sub_id":"101","register_pk":"108161","name":"油伝味噌店舗兼主屋","kana":"あぶでんみそてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町438","lat":36.38934348,"lng":139.734146,"geo_status":"db","era":"明治中期／大正期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積170㎡","structure_material":"木造平屋一部2階建","registered":"2008.07.08(平成20.07.08)","register_no":"09 － 0176","desc":"旧例幣使街道に東面して建つ。切妻造桟瓦葺の２階建の東妻面に、寄棟屋根を接する特徴的な屋根構成で、正面には下屋庇を設ける。軒は出桁造で、北半部に出格子窓、南半部に引違建具をたて開放的に扱う。旧街道に面する商家の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007179"},{"id":"00003787","register_sub_id":"101","register_pk":"104777","name":"油伝味噌中蔵","kana":"あぶでんみそなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町5-26","lat":36.38946423,"lng":139.73382284,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0090","desc":"東蔵の西方に東西棟で建つ。桁行５間梁間２間半規模，切妻造，桟瓦葺の平入２階建土蔵で，東蔵と同様に北側に幅２間程の下屋を設ける。北面壁は，西方味噌土蔵の下屋の壁に連続する簓子下見板張の漆喰塗壁で，長大な醸造蔵景観を敷地北面につくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003787"},{"id":"00003786","register_sub_id":"101","register_pk":"104776","name":"油伝味噌東蔵","kana":"あぶでんみそひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町5-26","lat":36.38944762,"lng":139.73391375,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0089","desc":"文庫蔵の西側に東西棟で建つ。桁行４間梁間２間，切妻造，桟瓦葺の２階建土蔵で，南面に庇を差し掛けて戸前をとるほか，北側に２間幅規模の下屋を設ける。下屋の北面は，東方外塀と連続した凝灰岩造の壁で，敷地北面に特徴的な屋敷構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003786"},{"id":"00001405","register_sub_id":"101","register_pk":"102395","name":"アンタレススポーツクラブ（旧足利模範撚糸工場）","kana":"あんたれすすぽーつくらぶ（きゅうあしかがもはんねんしこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市田中町906-13","lat":36.330544,"lng":139.445053,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積530㎡","structure_material":"石造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"09 － 0020","desc":"明治政府の輸出絹織物振興の国策によって設立された足利模範撚糸合資会社の洋風工場建築。外壁は大谷石積，控壁付きとし，半円アーチ付きの縦長窓が連なる。鋸屋根の北面に大きな明かり窓を設ける。各地に建設された模範撚糸工場の中で唯一現存するもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001405"},{"id":"00010097","register_sub_id":"101","register_pk":"197930","name":"鹿沼市文化活動交流館石蔵（旧帝国繊維石蔵）","kana":"かぬましぶんかかつどうこうりゅうかんいしぐら（きゅうていこくせんいいしぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県鹿沼市睦町字寺ノ内1956-2","lat":36.569033,"lng":139.752488,"geo_status":"db","era":"大正初期／平成14改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造平屋建、鋼板葺、建築面積495㎡","structure_material":"石造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"09 － 0215","desc":"製麻業で栄えた当地で、黒川と木島用水が囲む地区に位置する、もと製麻工場の建築。石造平屋建、桁行五五メートルを測る長大な蔵で、下段には近隣で産する深岩石を、上部には大谷石を積み、キングポストトラスの小屋を載せる。製麻産業の最盛期を物語る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010097"},{"id":"00011264","register_sub_id":"101","register_pk":"209100","name":"旧足尾銅山鉱業事務所付属書庫","kana":"きゅうあしおどうざんこうぎょうじむしょふぞくしょこ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市足尾町2281","lat":36.642357,"lng":139.450186,"geo_status":"db","era":"明治40","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積69㎡","structure_material":"煉瓦造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0232","desc":"銅山中枢部の掛水移転にあわせて建設された書庫。煉瓦造二階建とする。イギリス積の外壁で、四隅に白い石材を帯状に配した付柱を設け、両側面と正面中央には妻壁を立ち上げて重厚な外観を持つ。銅山の中心施設の遺構として希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011264"},{"id":"00008646","register_sub_id":"101","register_pk":"149367","name":"旧新井製糸所漆喰蔵","kana":"きゅうあらいせいしじょしっくいぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡野木町大字野渡字坪ノ内328-1","lat":36.20670652,"lng":139.70156255,"geo_status":"db","era":"明治中期／平成11年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造及び土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"煉瓦造及び土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0200","desc":"事務室の西に隣接し、東面して建つ。南北棟の切妻造桟瓦葺で、東面に下屋をかける。桁行7.3ｍ梁間4.6ｍ。1階は下野煉化製造会社製煉瓦をイギリス積で1枚厚に積み上げ、2階は土蔵造とする。白漆喰と煉瓦が鮮やかなコントラストを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008646"},{"id":"00008645","register_sub_id":"101","register_pk":"149366","name":"旧新井製糸所事務室","kana":"きゅうあらいせいしじょじむしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡野木町大字野渡字坪ノ内328-1","lat":36.20670697,"lng":139.70167195,"geo_status":"db","era":"明治中期／平成3年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0199","desc":"敷地北寄りに建つ。桁行9.1ｍ梁間6.8ｍの木造平屋建。東西棟の東切妻西寄棟造とし、下屋をまわす。桟瓦葺。トコとトコ脇、平書院を構える8畳と、その東の6畳からなり、西・南・東面に縁を付ける。繊細な欄間が飾られる近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008645"},{"id":"00008647","register_sub_id":"101","register_pk":"149368","name":"旧新井製糸所煉瓦蔵","kana":"きゅうあらいせいしじょれんがぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡野木町大字野渡字坪ノ内328-1","lat":36.20656336,"lng":139.70154968,"geo_status":"db","era":"明治後期／平成3年・平成14年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積69㎡","structure_material":"煉瓦造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0201","desc":"漆喰蔵の南に東面して建つ。南北棟の切妻造桟瓦葺、桁行15ｍ梁間4.7ｍ。イギリス積で、中間に水切りを付け、鉢巻は3段の蛇腹とするなど、土蔵造風のデザインもみられる。下野煉化製造会社製の煉瓦で造られ、地域の近代化を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008647"},{"id":"00009434","register_sub_id":"101","register_pk":"194227","name":"杉田酒造大谷石蔵","kana":"すぎたしゅぞうおおやいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"栃木県","address":"栃木県小山市大字上泉字本沢237","lat":36.31671752,"lng":139.73918852,"geo_status":"db","era":"昭和22年","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"石造及び木造平屋建、鉄板葺、建築面積65㎡","structure_material":"石造及び木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"09 － 0205","desc":"敷地北側に建ち、石造及び木造平屋建、桁行一○・○メートル梁間六・五三メートル、切妻造鉄板葺である。戦後に米の代用植物であるサツマイモを原料として作成していた焼酎の室の蔵。断熱を考慮した構造が特徴的な、当時の食糧事情を反映した大谷石造の石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009434"},{"id":"00009431","register_sub_id":"101","register_pk":"194224","name":"杉田酒造仕込蔵","kana":"すぎたしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県小山市大字上泉字本沢237","lat":36.31651384,"lng":139.73910762,"geo_status":"db","era":"江戸末期／明治中期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積167㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"09 － 0202","desc":"敷地西側に建ち、土蔵造二階建、桁行一八・二メートル梁間九・一四メートル、寄棟造桟瓦葺である。漆喰塗の外壁に、腰に古色蒼然とした板羽目を張り、外観を整える。二階には大正蔵に向けて連絡路が設置される。架構は概ね創建時の姿を留める仕込蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009431"},{"id":"00009433","register_sub_id":"101","register_pk":"194226","name":"杉田酒造大正蔵","kana":"すぎたしゅぞうたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県小山市大字上泉字本沢237","lat":36.31664328,"lng":139.73904861,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積117㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"09 － 0204","desc":"敷地北辺西寄り東西棟で建つ。土蔵造二階建、桁行一四・○メートル梁間八・三四メートル、切妻造桟瓦葺である。外壁は漆喰塗で腰に板羽目を張り、軒部分に緩い勾配をもつ鉢巻を廻す。小屋組は梯子上の二重桁梁として構成するなど、重厚な構造とした土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009433"},{"id":"00009432","register_sub_id":"101","register_pk":"194225","name":"杉田酒造貯蔵蔵","kana":"すぎたしゅぞうちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県小山市大字上泉字本沢237","lat":36.31659236,"lng":139.7392423,"geo_status":"db","era":"江戸末期／明治6年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積197㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"09 － 0203","desc":"敷地中央北側に建ち、土蔵造二階建、桁行二○・九メートル梁間九・四二メートル、切妻造桟瓦葺である。二階奥に間仕切した約二・五間四方の作業場を設け、かつて杜氏が生活していたと伝えられる。敷地内で最古の建物であり、造酒屋としての歴史を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009432"},{"id":"00011259","register_sub_id":"101","register_pk":"209094","name":"第一酒造旧桶倉庫","kana":"だいいちしゅぞうきゅうおけそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.29906,"lng":139.565493,"geo_status":"db","era":"明治中期／昭和後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、金属板葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0227","desc":"敷地北東隅に東西棟で建つ。平屋建の倉庫で、北面に下屋を付し、その中ほどに入母屋造、妻入の屋根を架け裏門とし、南面へとつなぐ通路を開く。通路の東側はほぼ正方形の一室とし、西側は台形平面とする。酒蔵とともに造酒屋の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011259"},{"id":"00011260","register_sub_id":"101","register_pk":"209095","name":"第一酒造旧穀倉","kana":"だいいちしゅぞうきゅうこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.298282,"lng":139.565447,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0228","desc":"通りに面して敷地南辺を画し、表構えを成す長屋門。間口三メートルの表門の東に物置、西に穀倉を設けて、一連の切妻屋根を架ける。もとは大豆等の穀物を納めていたことから穀倉と呼ばれる。外部には下見板張を施し、旧家の格式ある表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011260"},{"id":"00011261","register_sub_id":"101","register_pk":"209097","name":"第一酒造旧米穀蔵","kana":"だいいちしゅぞうきゅうべいこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.298246,"lng":139.565242,"geo_status":"db","era":"元治元／昭和後期改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積41㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0229","desc":"旧穀倉とともに、敷地の南辺を画す土蔵。平屋建で建ちの高い土蔵であるが、当初は二階床があったと伝わる。内部には半割丸太の荷摺木を一定間隔で打ち、米蔵として用いられていた歴史を物語る。漆喰塗の腰を下見板張とする外観で、旧穀倉と一連の表構えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011261"},{"id":"00011257","register_sub_id":"101","register_pk":"209092","name":"第一酒造酒蔵","kana":"だいいちしゅぞうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.29898,"lng":139.565151,"geo_status":"db","era":"慶応4頃／昭和後期改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積818㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0225","desc":"敷地の北西隅に建つ桁行三九メートルの大型土蔵。梁間一一メートルの二階建主体部に、南北に各六メートル幅の下屋を付す構造とする。小屋は身舎柱上を和小屋とし、その間に登梁を架ける。酒造の主要な工程を行う建物で、幕末以来の敷地景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011257"},{"id":"00011258","register_sub_id":"101","register_pk":"209093","name":"第一酒造酒蔵事務所","kana":"だいいちしゅぞうさかぐらじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.298794,"lng":139.565367,"geo_status":"db","era":"明治中期／昭和後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積360㎡","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0226","desc":"酒蔵の南面東端に接続して、南北棟で建つ。切妻造、妻入で、当初は、入口側の南半を帳場として、酒蔵側の北半を釜場として用いていた。二階には杜氏のための居住空間を備える。馬車運送を行った名残として南面中央に大きな開口を設けて土間としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011258"},{"id":"00001407","register_sub_id":"101","register_pk":"102397","name":"トチセン（旧足利織物）赤レンガサラン工場","kana":"とちせん（きゅうあしかがおりもの）あかれんがさらんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市福居町1151-1他","lat":36.306335,"lng":139.457779,"geo_status":"db","era":"大正2～8","year":1913,"year_source":"converted","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積357㎡","structure_material":"煉瓦造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"09 － 0022","desc":"東西棟の長大な工場建築。煉瓦造，切妻造で，東妻側に差し掛け屋根の張り出しを設ける。北側面に大きな石材を窓枠とする窓が密に並んでいる点に特色がある。北面東半部では上部にも窓を設けて二階建ての趣を見せているが，上段の窓は後補。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001407"},{"id":"00001406","register_sub_id":"101","register_pk":"102396","name":"トチセン（旧足利織物）赤レンガ捺染工場","kana":"とちせん（きゅうあしかがおりもの）あかれんがなっせんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市福居町1151-1他","lat":36.30617212,"lng":139.45732487,"geo_status":"db","era":"大正2～8","year":1913,"year_source":"converted","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積1587㎡","structure_material":"煉瓦造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"09 － 0021","desc":"煉瓦造の外壁と木造の内部軸組からなる広大な工場建築で，６連の鋸屋根を架ける。頂部まで立ち登る柱型と重厚な軒蛇腹とで縁取る妻壁の意匠や，出入口・窓の大きな開口部を一石のまぐさ石で支える手法に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001406"},{"id":"00006782","register_sub_id":"101","register_pk":"107764","name":"トチセン（旧足利織物）汽罐室","kana":"とちせん（きゅうあしかがおりもの）きかんしつ","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市福居町字神明地1151-1他","lat":36.30617504,"lng":139.456757,"geo_status":"db","era":"大正前期／昭和16増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"煉瓦造平屋建、スレート葺、建築面積239㎡、ボイラー2基付","structure_material":"煉瓦造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"09 － 0170","desc":"工場敷地の南西隅に位置する煉瓦造平屋建で、波形スレート葺の切妻屋根を２連にかける。妻壁は北棟が山形、増築の南棟が方形である。外壁は煉瓦のイギリス積で柱形が付く。内部にはランカシャーボイラーを２基ずつ設置した。黒色迷彩塗装が残り戦時を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006782"},{"id":"00007000","register_sub_id":"101","register_pk":"107982","name":"西堀酒造煙突","kana":"にしぼりしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県小山市大字栗宮1452","lat":36.286217,"lng":139.780472,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ14m","structure_material":"煉瓦造","registered":"2008.04.18(平成20.04.18)","register_no":"09 － 0173","desc":"敷地のほぼ中央に位置する煉瓦造の煙突である。基底部は１．９ｍ角、高さは約１４ｍである。煉瓦は下野煉化製造会社の製品と伝え、イギリス積とする。四隅に山形鋼を添え、丸鋼をナット締めして補強している。地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007000"},{"id":"00006998","register_sub_id":"101","register_pk":"107980","name":"西堀酒造仕込蔵","kana":"にしぼりしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県小山市大字栗宮1452","lat":36.28595458,"lng":139.78062097,"geo_status":"db","era":"大正中期／平成7改修","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造平屋建、瓦葺、建築面積239㎡","structure_material":"土蔵造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"09 － 0171","desc":"敷地の東寄りに建つ土蔵造平屋建で店舗に改装。桁行２８ｍ梁間５．９ｍの南北棟で、屋根を切妻造桟瓦葺とし、西面に２．８ｍ幅の瓦葺庇をつける。大谷石の切石積基礎上に建ち、外壁は白漆喰塗で、腰を簓子下見板張とする。窓上の鉄板葺庇が外観に陰影を加える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006998"},{"id":"00007001","register_sub_id":"101","register_pk":"107983","name":"西堀酒造長屋門","kana":"にしぼりしゅぞうながやもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県小山市大字栗宮1452","lat":36.2860251,"lng":139.78083252,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"09 － 0174","desc":"敷地東寄りに東を正面に建つ木造平屋建で、北に瓶詰場の下屋が接続する。桁行９．１ｍ梁間４．６ｍで、切妻造桟瓦葺とする。中央の２間を門口とし、北に部屋、南に物置を設ける。外壁は真壁造漆喰塗で、腰を簓子下見板張とする。風格ある敷地構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007001"},{"id":"00006999","register_sub_id":"101","register_pk":"107981","name":"西堀酒造瓶詰場","kana":"にしぼりしゅぞうびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県小山市大字栗宮1452","lat":36.28612348,"lng":139.78086417,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積221㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"09 － 0172","desc":"敷地の北寄りに建つ土蔵造２階建である。桁行１６ｍ梁間１１ｍの東西棟で、屋根は切妻造桟瓦葺とし、東妻の桟瓦葺下屋が長屋門に接続する。切石の基礎上に建ち、外壁は白漆喰塗で鉢巻をつけ、腰を簓子下見板張とする。東妻２階の窓がアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006999"},{"id":"00005711","register_sub_id":"101","register_pk":"106699","name":"古河掛水倶楽部旧館","kana":"ふるかわかけみずくらぶきゅうかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県日光市足尾町2281","lat":36.642559,"lng":139.450546,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鉄板葺、建築面積231㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0158","desc":"新館の北西方に南面して建ち，新館と渡廊下で結ばれる。桁行２１ｍ，梁間７ｍ規模，東西棟，寄棟造，鉄板葺の木造平屋建で，南面西端に正面玄関，中央東寄りに脇玄関を設ける。外観は下見板張の洋風とし，内部は西方を畳敷の大広間，東方を洋室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005711"},{"id":"00005710","register_sub_id":"101","register_pk":"106698","name":"古河掛水倶楽部新館","kana":"ふるかわかけみずくらぶしんかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県日光市足尾町2281","lat":36.6423536,"lng":139.45070488,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階一部平屋建、鉄板葺、建築面積476㎡","structure_material":"木造2階一部平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0157","desc":"渡良瀬川の右岸段丘上に位置し，川に面した東面は石積の柱を現して懸造り風につくる。桁行１７ｍ，梁間１２ｍ規模，切妻造，鉄板葺の木造２階建で，南に厨房等，西に平屋建の球技室を張り出し，２階をハーフティンバー風にするなど変化に富んだ外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005710"},{"id":"00006552","register_sub_id":"101","register_pk":"107535","name":"若駒酒造主屋","kana":"わかこましゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市大字小薬169-1","lat":36.364044,"lng":139.778244,"geo_status":"db","era":"明治初期／昭和12増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積333㎡、煙突付","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0162","desc":"市北西部の田園地帯にある。南面して建つ主屋は木造２階建，寄棟造，桟瓦葺の平入で，前面には水路が流れる。東側と北側の平屋建は増築である。平面は東半が座敷，西半が釜場を兼ねた広い土間とする。南西隅に煙突を備えた雄大な屋根を架け，独特の外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006552"},{"id":"00006553","register_sub_id":"101","register_pk":"107536","name":"若駒酒造精米所","kana":"わかこましゅぞうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市大字小薬169-1","lat":36.36388,"lng":139.778,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積209㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0163","desc":"東西棟の切妻造，桟瓦葺，木造２階建で，正面の東妻面に庇を設け，南面に降ろした下屋を細工所とする。小屋組は和小屋で，道路側の外壁は押縁下見板張とする。醸造業に欠かせない施設であり，市道で区切られた敷地南辺西端にあって，重厚な屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006553"},{"id":"00006554","register_sub_id":"101","register_pk":"107537","name":"若駒酒造瓶詰場","kana":"わかこましゅぞうびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県小山市大字小薬169-1","lat":36.363976,"lng":139.778061,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積268㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0164","desc":"主屋の西に建つ。南北棟の切妻造，桟瓦葺，木造２階建で，１階南面の東寄りに出入口を設ける。側廻りは半間毎に柱を立てて堅牢につくり，外壁は押縁下見板張である。１階は瓶詰場と白米置場，中２階及び２階は物置とする。大規模で，醸造業に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006554"},{"id":"00011067","register_sub_id":"101","register_pk":"205174","name":"今井酒造店煙突","kana":"いまいしゅぞうてんえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314762,"lng":139.348077,"geo_status":"db","era":"明治41／昭和40頃改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造、高さ14m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0336","desc":"釜場及び瓶詰場の南に位置し、地下の煙道を介して接続する。基部寸法一・三メートル四方、高さ一三・八メートルの煉瓦造煙突であるが、上部は鋼製に改造されている。煉瓦部分はイギリス積。酒造業に欠かせない施設であり、地域のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011067"},{"id":"00011065","register_sub_id":"101","register_pk":"205172","name":"今井酒造店釜場及び瓶詰場","kana":"いまいしゅぞうてんかまばおよびびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314863,"lng":139.348123,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0334","desc":"本蔵の東に接して建つ。木造二階建、切妻屋根の妻面に深い庇を設ける。酒造工程の最初（洗米・蒸米）と、最終段階である瓶詰が行われ、内部には釜場がある。また東南角部と小屋裏を画した二階部は蔵人の休憩等に用いられた。妻面に梁組を見せるなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011065"},{"id":"00011064","register_sub_id":"101","register_pk":"205171","name":"今井酒造店新蔵","kana":"いまいしゅぞうてんしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314725,"lng":139.347861,"geo_status":"db","era":"明治42／昭和40頃改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積308㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0333","desc":"北寄りを本蔵に接する南北棟の土蔵。西面は一段切り下げ、東面は錣葺状に庇を設け、全体で桁行一〇間、梁間九・五間の広い内部を設けている。西下屋は麹室とし、東下屋区切らずに一連としているが、当初は壁で区切られていた。本蔵とともに酒造の中核をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011064"},{"id":"00011062","register_sub_id":"101","register_pk":"205169","name":"今井酒造店店舗兼主屋","kana":"いまいしゅぞうてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314684,"lng":139.348165,"geo_status":"db","era":"明治前期／明治33移築、平成15改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積223㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0331","desc":"敷地中程に建つ。近隣の農家を移築し店舗兼主屋としたもの。木造二階建、桁行一〇間、梁間六・五間の規模で、当初は東寄りに広い土間を設け、西半は田字型の平面を基本としていた。屋根は切妻造桟瓦葺で、各面に庇を設ける。農家を基本とする大規模住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011062"},{"id":"00011066","register_sub_id":"101","register_pk":"205173","name":"今井酒造店文庫蔵","kana":"いまいしゅぞうてんぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.314703,"lng":139.348013,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0335","desc":"店舗兼主屋の西北に建つ桁行三間、梁間二間の二階建土蔵で、屋根は置屋根桟瓦葺。主屋側の東に扉を設け、一階北面と二階南面に両開土戸の窓を開く。壁は内外共漆喰塗で、腰巻き上に水切りを付ける。申請書等多量の記録・書類を納める建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011066"},{"id":"00011063","register_sub_id":"101","register_pk":"205170","name":"今井酒造店本蔵","kana":"いまいしゅぞうてんほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県太田市鳥山中町746-2","lat":36.31485,"lng":139.347931,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積254㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0332","desc":"敷地の北西寄りに位置し、新蔵、釜場及び瓶詰場に接する。桁行一二間梁間五間の大規模な土蔵で、外壁は腰部をスギ下見板張とし、上部は漆喰塗籠。一階は総土間で、二階は一部床を張らず吹き抜けとする。酒母・もろみ造りなど主要機能を担っていた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011063"},{"id":"00015282","register_sub_id":"101","register_pk":"532406","name":"江原本家大庫（旧朝日町醤油醸造蔵）","kana":"えばらほんけおおぐら（きゅうあさひちょうしょうゆじょうぞうぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県前橋市富士見町赤城山字竜ノ口1825-47他","lat":36.49019722,"lng":139.11594167,"geo_status":"db","era":"明治前期／平成13年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0356","desc":"前橋市朝日町から移築した旧醸造蔵。敷地南西に北面して建つ平屋建切妻造妻入桟瓦葺で、正面中央戸口に土戸の大戸を建てる。外壁は白漆喰塗仕上で水切を一段廻らし、腰を黒漆喰塗仕上。内部は一室の土間で、三重梁を架けた豪壮な小屋組を現す桁行長大な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015282"},{"id":"00009706","register_sub_id":"101","register_pk":"195535","name":"岡直三郎商店大間々工場店舗兼主屋","kana":"おかなおさぶろうしょうてんおおままこうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県みどり市大間々町大間々1013","lat":36.43392194,"lng":139.27463141,"geo_status":"db","era":"明治中期／明治33頃増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積216㎡、門及び煙突付","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"10 － 0306","desc":"通りに東面して建ち、木造二階建、切妻造桟瓦葺。外壁漆喰塗で、二階正面の左右に横長の格子窓を配し、両端に蛇腹付の袖うだつを設ける。内部は南半を店舗、北半を事務室や座敷等とし、店舗部後方に煉瓦煙突を残す。明治二八年の大火を免れ、往時の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009706"},{"id":"00009707","register_sub_id":"101","register_pk":"195536","name":"岡直三郎商店大間々工場文庫蔵","kana":"おかなおさぶろうしょうてんおおままこうじょうぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県みどり市大間々町大間々1013","lat":36.43405519,"lng":139.2745743,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"10 － 0307","desc":"主屋の北に、東西棟で建つ。桁行九・四メートル梁間四・六メートル、土蔵造二階建、切妻造桟瓦葺。南面を戸口とし、二階南面と東面に窓を設け、掛子塗の扉を吊る。安山岩切石基礎に建ち、外壁は漆喰塗で水切を廻らす。主屋とともに、良好な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009707"},{"id":"00010103","register_sub_id":"101","register_pk":"197936","name":"金子織物株式会社旧従業員宿舎","kana":"かねこおりものかぶしきがいしゃきゅうじゅうぎょういんしゅくしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東久方町2-90","lat":36.419559,"lng":139.34741,"geo_status":"db","era":"昭和前期／昭和27移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0312","desc":"敷地北辺東寄りに建ち、西側に旧染場が接続し、背面壁は通りに面する。木造二階建、切妻造桟瓦葺で、外壁は下見板張とし、南面を広く開口し、北面は庇と格子の付いた横長窓を設ける。東妻壁にはトラス組を現す。織物会社の従業員の生活を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010103"},{"id":"00010102","register_sub_id":"101","register_pk":"197935","name":"金子織物株式会社旧鋸屋根工場","kana":"かねこおりものかぶしきがいしゃきゅうのこぎりやねこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東久方町2-73-1","lat":36.41934,"lng":139.347348,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0311","desc":"敷地南東側に建つ、切妻三連の鋸屋根の工場建築で、北西の主屋側に切妻造の事務所を附属し、屋根は桟瓦葺とする。周囲の横長窓に庇を付け、小屋組はトラス組で、屋根北面に大きな窓を設けて採光をはかる。織物産業で栄えた桐生市の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010102"},{"id":"00010100","register_sub_id":"101","register_pk":"197933","name":"金子家住宅蔵","kana":"かねこけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市東久方町2-73-1他","lat":36.419545,"lng":139.347041,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0309","desc":"南面する主屋の西端に接続して南北棟で建ち、土蔵造二階建、桁行五・六メートル梁間三・八メートル、切妻造桟瓦葺である。外壁漆喰塗で鉢巻を廻らし、東面の座敷側に出入口を開く。上下階の南面に庇付の窓を穿つ。織物会社社主住宅の屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010100"},{"id":"00010101","register_sub_id":"101","register_pk":"197934","name":"金子家住宅倉庫及び旧染場","kana":"かねこけじゅうたくそうこおよびきゅうそめば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東久方町2-90","lat":36.419636,"lng":139.347198,"geo_status":"db","era":"昭和14／昭和27頃改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0310","desc":"敷地北辺に建つ切妻造桟瓦葺で、西側を倉庫、東側を細長い旧染場とし、背面壁は外塀を兼ねる。倉庫は外壁下部に下見板を張り、小屋はトラス組。倉庫は漬物小屋や子供室に使い、旧染場は釜場で湯を沸かし、銘仙織物の糸染めを行った。往時の生活を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010101"},{"id":"00011059","register_sub_id":"101","register_pk":"205166","name":"旧大竹酒造煉瓦蔵","kana":"きゅうおおたけしゅぞうれんがぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県前橋市三河町一丁目28-23","lat":36.388833,"lng":139.076425,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造2階建、瓦葺、建築面積236㎡","structure_material":"煉瓦造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"10 - 0328","desc":"前橋の中心市街地に残る唯一の酒造蔵。昭和八年に大竹酒造が建物を取得し、四七年まで醸造を行っていた。煉瓦造を主体とするが壁厚は一枚分で内部に柱を二列八本立て、和小屋を組む。外壁は軒蛇腹、破風や柱型の一部に焼過煉瓦を配し、立体感を強調している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011059"},{"id":"00010559","register_sub_id":"101","register_pk":"201133","name":"旧金谷家住宅蔵","kana":"きゅうかなやけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市東久方町1-96-3他","lat":36.420473,"lng":139.346732,"geo_status":"db","era":"明治6年／昭和初期移築","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"10－0321","desc":"主屋背面の蔵前に接続して建つ二階建の土蔵。南北棟の切妻造桟瓦葺で、大棟の棟積を輪違とし、両端の鬼瓦に影盛りを施す。内部は板床で一階は板壁、二階は漆喰壁で、二階床中央の荷揚げ用の開口に格子を嵌め込む。主屋と並び西面通り側の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010559"},{"id":"00010558","register_sub_id":"101","register_pk":"201132","name":"旧金谷家住宅主屋","kana":"きゅうかなやけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東久方町1-96-3他","lat":36.420371,"lng":139.346694,"geo_status":"db","era":"昭和6年／昭和52年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積198㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"10－0320","desc":"織物工場を併設した住宅の主屋で、事務所西に接続して建つ。木造平屋一部二階建桟瓦葺で、内部は西寄りに廊下を矩手に廻した八畳の座敷を二室並べ、東はハーフティンバー風の洋間とする。隣接する洋風の事務所と対比的な和風建築で、桐生らしい佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010558"},{"id":"00000949","register_sub_id":"101","register_pk":"101939","name":"旧株式会社金芳織物工場事務所","kana":"きゅうかぶしきがいしゃかなよしおりものこうじょうじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東久方町1-1-55","lat":36.4203594,"lng":139.3467779,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造２階建，建築面積71㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0033","desc":"金谷芳次郎が設立した金芳織物工場の事務所建築。大正８年建造の煉瓦造工場に接続するが，スクラッチタイルの使用が建築年代を明示する。水平線の強調はライト式建築の特徴。角部の丸みや丸窓の意匠に時代の特色がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000949"},{"id":"00010560","register_sub_id":"101","register_pk":"201134","name":"旧株式会社金芳織物工場染色場","kana":"きゅうかぶしきがいしゃかなよしおりものこうじょうせんしょくば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東久方町1-96-2他","lat":36.420431,"lng":139.346884,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"10－0322","desc":"事務所の背面に隣接して建つ染色場。梁間の長い切妻造鉄板葺、東西棟の簡素な建物で、小屋をキングポストトラスとし、屋根に天窓を四所開ける。壁面にも要所にガラス窓を付す。鋸屋根工場と並び金芳織物工場創業期の建築として価値があり、桐生の繁栄を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010560"},{"id":"00000950","register_sub_id":"101","register_pk":"101940","name":"旧株式会社金芳織物工場鋸屋根工場","kana":"きゅうかぶしきがいしゃかなよしおりものこうじょうのこぎりやねこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東久方町1-1-55","lat":36.42034862,"lng":139.3469733,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造平屋建，鉄板葺，建築面積298㎡","structure_material":"煉瓦造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"10 － 0034","desc":"大正８年１２月１４日上棟の織物工場。施工は高崎市の島田組。外周壁を煉瓦造とし，木造で「鋸刃」状の屋根を架けた標準的な工場建築の造りを示す。京都西陣と並ぶ高級織物産地として知られる桐生の繁栄ぶりを今に伝えていることで貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000950"},{"id":"00005248","register_sub_id":"101","register_pk":"106236","name":"旧曽我織物工場","kana":"きゅうそがおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町一丁目甲225-1","lat":36.418739,"lng":139.343201,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木骨石造平屋建、鉄板葺、建築面積550㎡","structure_material":"木骨石造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0152","desc":"桁行８間の石造平屋建で，梁間２０尺の鋸屋根５連をかける。屋根は東西棟で，鉄板葺，アルミサッシュ建具に改修されている。小屋組は木造である。外壁は大谷石の切石整層積である。戸口と窓はまぐさを入れ，両開き鉄扉を吊り込む。西妻に円形の換気窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005248"},{"id":"00005247","register_sub_id":"101","register_pk":"106235","name":"旧堀祐織物工場（美容室アッシュキリュウ）","kana":"きゅうほりゆうおりものこうじょう（びようしつあっしゅきりゅう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市巴町1-1126","lat":36.40955714,"lng":139.33596872,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積207㎡","structure_material":"石造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0151","desc":"桁行６間半，梁間１０間の石造平屋建で，３連の鋸屋根をかける工場遺構である。内装，戸口，屋根は転用時に改修された。外壁は大谷石の切石整層積である。窓はまぐさ付き縦長矩形で両開き鉄扉を吊り込む。南面に当初の戸口を残す。建物転用の好事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005247"},{"id":"00010918","register_sub_id":"101","register_pk":"208889","name":"旧本間酒造酒蔵及び釜屋","kana":"きゅうほんましゅぞうさかぐらおよびかまや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県前橋市総社町総社字町屋敷南乙1500","lat":36.408424,"lng":139.040215,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積524㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"10-0326","desc":"敷地北寄りに建つ。洗米から仕込みまでの酒造に用いられた。中心となる酒蔵は和小屋を架けた土蔵造二階建で、仕込み等に用いるため上下階とも一室とする。東に釜屋を付属し、南にオロシと呼ばれる下屋を広く張り出す。造酒屋の往時の繁栄を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010918"},{"id":"00010917","register_sub_id":"101","register_pk":"208888","name":"旧本間酒造店舗兼主屋","kana":"きゅうほんましゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県前橋市総社町総社字町屋敷南乙1500","lat":36.408405,"lng":139.040568,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積232㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"10-0325","desc":"旧街道に東面し、入母屋造妻入となる町家。一階は南一間を通り土間とし、東に土間、西に接客用座敷などの床上部を設ける。二階は東と南に廊下を巡らせて居室を並べる。二階の軒はせがい造にして深く出し、表情を付ける。総社宿の町並みに歴史的景観を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010917"},{"id":"00005416","register_sub_id":"101","register_pk":"106404","name":"後藤織物井戸屋形","kana":"ごとうおりものいどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41119658,"lng":139.3459391,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、鉄板葺、面積8.5㎡","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0165","desc":"主屋北面増築部の西方，奥座敷１０畳の北方に位置し，南北棟で建つ。桁行３．２ｍ，梁間２．６ｍ，切妻造，鉄板葺で，柱を内転びに立て，北・西・南の三方を波形鉄板で囲う。ほぼ中央に河原石積の井戸を掘る。染色のための用水の水源を覆う小屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005416"},{"id":"00005420","register_sub_id":"101","register_pk":"106408","name":"後藤織物表門及び板塀","kana":"ごとうおりものおもてもんおよびいたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東一丁目729-2、730","lat":36.41098765,"lng":139.34597426,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"表門 木造、瓦葺、間口4.5m、板塀 木造、鉄板葺、延長23m","structure_material":"表門 木造","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0169","desc":"主屋の南方に道路から後退して建つ。門は，間口４．５ｍの中央２．１ｍを門口とした切妻造，桟瓦葺の棟門で，門口には引き分け戸を建て込む。門口の両脇には腰下見板張，上部漆喰塗の袖壁を配し，東に長１１ｍ，西に長１２ｍの板塀を延ばして正面の構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005420"},{"id":"00005415","register_sub_id":"101","register_pk":"106403","name":"後藤織物旧釜場","kana":"ごとうおりものきゅうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.411072,"lng":139.346161,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0164","desc":"主屋北東部に位置する。桁行４間半，梁間３間半，東西棟，切妻造，瓦葺の木造平屋建で，内部中央西寄りに大中小５口の煉瓦造釜を据える。小屋組はキングポストトラスで，棟中央西寄りに越屋根を載せる。外壁は下見板張り。織物工場の主要施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005415"},{"id":"00005417","register_sub_id":"101","register_pk":"106405","name":"後藤織物給水塔","kana":"ごとうおりものきゅうすいとう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41125465,"lng":139.34589056,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、高さ5.7m","structure_material":"鉄筋コンクリート造","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0166","desc":"井戸屋形の北西方に位置し，工場西南隅に接して建つ。一辺３ｍ，高さ５．７ｍで，鉄筋コンクリート造４本柱で架構を造り，上部に直径２ｍ，深さ１ｍの鉄筋コンクリート造貯水槽を載せる。染色のための用水タンクで，工場の近代化の一面を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005417"},{"id":"00005412","register_sub_id":"101","register_pk":"106400","name":"後藤織物工場","kana":"ごとうおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.411389,"lng":139.34600577,"geo_status":"db","era":"昭和23／昭和24・25増築","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積720㎡、便所付","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0161","desc":"主屋及び奥座敷の北方に東西棟で建つ。主屋寄りの桁行９間，梁間３間，キングポストトラス，切妻屋根の工場棟の北方に，桁行１３間，梁間３間の鋸屋根工場２連を増築する。外装押縁下見板張の木造織物工場で，桐生の機業界の戦後復興を物語る施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005412"},{"id":"00005418","register_sub_id":"101","register_pk":"106406","name":"後藤織物倉庫","kana":"ごとうおりものそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41099394,"lng":139.34608865,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0167","desc":"主屋の東南方，表門を入って右手に位置し，南北棟で建つ。桁行４間，梁間２間規模，切妻造，桟瓦葺の木造平屋建で，西面北寄りに戸口を開け，東面には下屋を添わす。絹糸の保管庫として建設されたもので，織物工場の主要施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005418"},{"id":"00005414","register_sub_id":"101","register_pk":"106402","name":"後藤織物西蔵","kana":"ごとうおりものにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41157226,"lng":139.34603071,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0163","desc":"工場の北方西寄りに位置し，東蔵と並び建ち，桁行６間，梁間２間と同規模で，南面全面に１間幅の下屋を設け，木造平屋建，鉄板葺とする。内部は１室で，下屋境にも間仕切りを設けない。紋紙の収蔵倉庫であり，織物工場の主要施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005414"},{"id":"00005413","register_sub_id":"101","register_pk":"106401","name":"後藤織物東蔵","kana":"ごとうおりものひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.411518,"lng":139.346191,"geo_status":"db","era":"明治前期／大正14頃曳家","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0162","desc":"工場の北方東寄りに位置し，東西棟で建つ。桁行６間，梁間２間，切妻造，桟瓦葺の木造２階建で，南面全面に１間幅の下屋を設けて蔵前とし，内部は２室に分ける。工場敷地背面側にあり，外装は押縁下見板張としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005413"},{"id":"00005419","register_sub_id":"101","register_pk":"106407","name":"後藤織物物置","kana":"ごとうおりものものおき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東一丁目730","lat":36.41128984,"lng":139.34622423,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"10 － 0168","desc":"工場の東方，敷地東辺に沿って「く」の字形に屈折して建つ。桁行全長１６間，梁間１間規模の南北に細長い平面をもち，鉄板葺の招き屋根を架ける。南半が味噌醤油等の従業員向け食料保管庫とし，北半を薪炭置き場とする。織物工場の施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005419"},{"id":"00010108","register_sub_id":"101","register_pk":"197941","name":"小林家住宅（旧小武織物有限会社）石垣","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）いしがき","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-9他","lat":36.37841132,"lng":139.35045716,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"石造、総延長82m","structure_material":"石造","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0317","desc":"敷地の南面と西面に築かれた石垣で、門の入口では折曲がりに設ける。高さ約一・五メートル、底部幅約一・二メートル、総延長八二メートルに玉石を積み、コンクリートで固めて厚く目地を盛る。台風による水害後に築かれた石垣で、工場や住宅の防災を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010108"},{"id":"00010105","register_sub_id":"101","register_pk":"197938","name":"小林家住宅（旧小武織物有限会社）工場","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）こうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-6他","lat":36.37855,"lng":139.350488,"geo_status":"db","era":"昭和23／昭和29改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積276㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0314","desc":"主屋土間部に接続し、東西にのびる工場。南北棟の切妻造建物四棟を並行させた形式で、桟瓦葺とする。外壁は簓子下見板張で、妻壁には下端を尖頭形とした竪板を張詰める。市内で多数を占める鋸屋根とは異なる屋根形式をもつ工場で、桐生の工場建築の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010105"},{"id":"00010104","register_sub_id":"101","register_pk":"197937","name":"小林家住宅（旧小武織物有限会社）主屋","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）しゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-3他","lat":36.378663,"lng":139.350319,"geo_status":"db","era":"昭和6頃／昭和中期改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積332㎡","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0313","desc":"敷地西側に東面して建つ。切妻造桟瓦葺で正面中央に入母屋玄関を構え、周囲に下屋を廻らす。外壁は腰に簓子下見板を張り、妻壁は三段の梁組を現す。北半の土間は工場と一体化し、床上部は当初部の四間取の南に座敷を増築する。座敷の造作に古式を残す住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010104"},{"id":"00010106","register_sub_id":"101","register_pk":"197939","name":"小林家住宅（旧小武織物有限会社）倉庫一","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）そうこ１","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-9他","lat":36.378449,"lng":139.350408,"geo_status":"db","era":"昭和36","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"コンクリートブロック造平屋建、瓦葺、建築面積21㎡","structure_material":"コンクリートブロック造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0315","desc":"敷地南面東寄りに開く門から西側にのびる石垣上に建つ倉庫。コンクリートブロック造、切妻造桟瓦葺で、西側の下屋に井戸と流し場を設けた。内外壁ともモルタル塗で仕上げ、小屋はトラス組とする。織物の糸の保管や、工場用水と生活用水の確保に使用した建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010106"},{"id":"00010107","register_sub_id":"101","register_pk":"197940","name":"小林家住宅（旧小武織物有限会社）倉庫二","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）そうこ２","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-9他","lat":36.378403,"lng":139.350531,"geo_status":"db","era":"昭和37","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"コンクリートブロック造平屋建、瓦葺、建築面積19㎡","structure_material":"コンクリートブロック造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0316","desc":"敷地入口の東寄りに、倉庫一と向き合って石垣上に建つ。コンクリートブロック造、切妻造桟瓦葺で、内外壁ともモルタル塗で仕上げる。不整形な平面をもち、小屋は和小屋とする。操業時は織物の紋紙を保管していた倉庫で、織物の生産工程を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010107"},{"id":"00010109","register_sub_id":"101","register_pk":"197942","name":"小林家住宅（旧小武織物有限会社）塀","kana":"こばやしけじゅうたく（きゅうこたけおりものゆうげんがいしゃ）へい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市広沢町5字福島1111-9他","lat":36.37848512,"lng":139.35024773,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造、瓦葺、総延長49m","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"10 － 0318","desc":"敷地南面の石垣上を廻る透し板塀で、門の入口では折曲がりに設け、西端は作業員宿舎に接続する。土台上の柱を貫でつなぎ、屋根に雁振瓦を伏せ、高さ約一メートルとする。壁は竪板張目板打で、欄間に横桟一本を入れる。織物工場兼社主宅の屋敷構えを引立てる塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010109"},{"id":"00003811","register_sub_id":"101","register_pk":"104801","name":"正田醤油七号蔵","kana":"しょうだしょうゆななごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24776962,"lng":139.52585355,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造平屋建、スレート葺、建築面積562㎡","structure_material":"土蔵造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0109","desc":"六号蔵の南方に軸線を揃えて建つ。桁行２０間梁間８間規模，南北棟，切妻造，波形スレート（もと桟瓦）葺の平屋建仕込蔵で，内部は六号蔵と同様のつくりとなるが，間内の柱は２間間隔（六号蔵は４間を基本）に建てる。敷地南部に八号蔵と２連の妻面を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003811"},{"id":"00003812","register_sub_id":"101","register_pk":"104802","name":"正田醤油八号蔵","kana":"しょうだしょうゆはちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24821983,"lng":139.52588138,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積1479㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0110","desc":"六号蔵及び七号蔵の西方に並び建つ。南北棟，切妻造，桟瓦葺で，桁行５２間と長大。内部は六号蔵と同様で，小屋組もトラスであるが，六号蔵南妻面通り筋と南北両妻面のみ和小屋とする点に特色がある。長大な壁面と屋根が醸造場特有の景観を敷地西面につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003812"},{"id":"00003810","register_sub_id":"101","register_pk":"104800","name":"正田醤油六号蔵","kana":"しょうだしょうゆろくごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24825963,"lng":139.52612478,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積857㎡","structure_material":"土蔵造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0108","desc":"敷地西寄りに南北棟で建つ。桁行３０間梁間８間規模の醸造仕込蔵で，内部に柱を２列配した３廊式とし，主廊部の小屋組にはキングポストトラスを採り，他の醸造蔵と異なりこの蔵のみ入母屋造の屋根を架ける。正田醤油拡張期を物語る遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003810"},{"id":"00000428","register_sub_id":"101","register_pk":"101418","name":"分福酒造店舗","kana":"ぶんぶくしゅぞうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県館林市仲町2626-1","lat":36.24743469,"lng":139.53047346,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造2階建，瓦葺，建築面積61㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"10 － 0025","desc":"旧城下の南西部に位置する酒造業を営んだ家の店舗。１階を開放的にして２階を格子にする等，町家の特徴をよく備える。館林城下に現存する数少ない本格的な町家のひとつで，使用されている木材の質も高い。保存状況がよく往時の雰囲気をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000428"},{"id":"00004800","register_sub_id":"101","register_pk":"105790","name":"MAEHARA 20th（旧合名会社飯塚織物工場）","kana":"まえはらとぅえんてぃーす（きゅうごうめいがいしゃいいづかおりものこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市広沢町6-850-5","lat":36.3719678,"lng":139.35071269,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木骨石造平屋建、スレート葺、建築面積884㎡","structure_material":"木骨石造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"10 － 0126","desc":"鋸屋根の木骨石造で飯塚織物工場として建設。南に向って桁行を減じる台形平面をもち，６連の鋸屋根を架ける。敷地傾斜に従い，北ほど基礎が高い。外壁は大谷石で，柱形を見せ，北辺両端は円柱に造る。西面北寄りにアーチを飾った戸口を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004800"},{"id":"00004930","register_sub_id":"101","register_pk":"105920","name":"無鄰館蔵（旧北川織物工場蔵）","kana":"むりんかんくら（きゅうきたがわおりものこうじょうくら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.41933727,"lng":139.34406776,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0133","desc":"事務所の背面に建つ桁行４．８メートル，梁間３．９メートル，切妻造桟瓦葺，南北棟の土蔵造２階建である。妻は大谷石の切妻壁を立上げ，外壁と共にモルタル洗出しで仕上げる。内庭からの景観を特徴づける。設計は文部省技師・山田太市。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004930"},{"id":"00004929","register_sub_id":"101","register_pk":"105919","name":"無鄰館事務所（旧北川織物工場事務所）","kana":"むりんかんじむしょ（きゅうきたがわおりものこうじょうじむしょ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.41929597,"lng":139.34400207,"geo_status":"db","era":"大正5／大正10増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積91㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0132","desc":"工場主屋南東角に取付く切妻造桟瓦葺の木造平屋建である。南を正面とし，西端は工場主屋正面増築部の東端と壁を共有する。現在は外観にモルタル塗のパラペットを立上げるが，当時は工場主屋と一体的に使われ，工場の様子を今日に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004929"},{"id":"00004928","register_sub_id":"101","register_pk":"105918","name":"無鄰館主屋（旧北川織物工場主屋）","kana":"むりんかんしゅおく（きゅうきたがわおりものこうじょうしゅおく）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.419449,"lng":139.343842,"geo_status":"db","era":"大正5／大正10増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺及び鉄板葺、建築面積597㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0131","desc":"敷地中央西寄に南面して建つ木造の工場。桁行２２メートル，梁間７メートル，東西棟の瓦及び鉄板葺屋根が鋸歯状に２列並び，それぞれの屋根南面に換気口が４つ取付く。西面，背面に増築された鋸屋根と共に，織物の町・桐生市に特徴的な歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004928"},{"id":"00004931","register_sub_id":"101","register_pk":"105921","name":"無鄰館煉瓦塀一（旧北川織物工場女工宿舎煉瓦造外壁）","kana":"むりんかんれんがべいいち（きゅうきたがわおりものこうじょうじょこうしゅくしゃれんがぞうがいへき）","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.41956212,"lng":139.34402134,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造、延長18m","structure_material":"煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0134","desc":"敷地北側境界に沿って建つ高さ６．２メートル，延長１８．３メートルの煉瓦塀。防火を目的に，工場女工宿舎の北側外壁として建てられた。煉瓦をイギリス積で積上げ，現在は鉄骨で補強する。工場主屋の鋸屋根と共に地域の歴史的景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004931"},{"id":"00004932","register_sub_id":"101","register_pk":"105922","name":"無鄰館煉瓦塀二（旧北川織物工場煉瓦塀）","kana":"むりんかんれんがべいに（きゅうきたがわおりものこうじょうれんがべい）","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市本町1-5-5","lat":36.41968202,"lng":139.34384679,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造、総延長33m","structure_material":"煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0135","desc":"女工宿舎煉瓦造外壁の両端から敷地北西隅及び北東隅まで延びる煉瓦塀。高さ２．４メートルで，東側延長１４．０メートル，西側延長１９．２メートルになる。煉瓦の寸法ならびに積方は女工宿舎煉瓦外壁と同じイギリス積で，一連の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004932"},{"id":"00005575","register_sub_id":"101","register_pk":"106563","name":"森秀織物旧釜場","kana":"もりひでおりものきゅうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410122,"lng":139.344727,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0181","desc":"旧整経場の南側に接して建つ。桁行１６．０ｍ，梁間７．５ｍの規模で，木造平屋建，切妻造，桟瓦葺とする。外壁は旧整経場と同じ形式とする。屋根に換気のための越屋根を載せ，切妻造の瓦屋根とする。往時の建物用途の特徴を残し，織物工場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005575"},{"id":"00005569","register_sub_id":"101","register_pk":"106557","name":"森秀織物旧寄宿舎一（製品加工場）","kana":"もりひでおりものきゅうきしゅくしゃいち（せいひんかこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41042918,"lng":139.34489097,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0175","desc":"旧物置の北側に建つ。桁行４間半，梁間３間半の規模で，木造平屋建，入母屋造，桟瓦葺とする。東西に１０畳間２室を並べ，西側を押入とする。南側と西側をかつては廊下としていた。切妻造の玄関を南西隅に置き，工場敷地内の居住施設の外観を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005569"},{"id":"00005570","register_sub_id":"101","register_pk":"106558","name":"森秀織物旧寄宿舎二","kana":"もりひでおりものきゅうきしゅくしゃに","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41064403,"lng":139.34484208,"geo_status":"db","era":"大正13頃／昭和56曳家","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0176","desc":"敷地北東隅に建つ。桁行６．５ｍ，梁間７．５ｍの規模で，木造平屋建，入母屋造，桟瓦葺とする。南側を旧撚糸場に接続し，それ以外の面には下屋が付く。北側以外は窓等の開口部を付けていたが，現在は西側のみに戸口を開く。少なくなった旧寄宿舎の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005570"},{"id":"00005567","register_sub_id":"101","register_pk":"106555","name":"森秀織物旧現場事務所（経糸整経場）","kana":"もりひでおりものきゅうげんばじむしょ（たていとせいけいじょう）","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41005961,"lng":139.34496995,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0173","desc":"敷地南東隅の工場の北側に建つ。桁行９．５ｍ，梁間８．５ｍの規模で，木造平屋建，切妻造，桟瓦葺とする。小屋組をトラスとし，東側に下屋を出しボイラー室としていた。真壁構造とするが，外壁一部に鉄板を張る。西面及び南面にガラス戸及び窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005567"},{"id":"00005573","register_sub_id":"101","register_pk":"106561","name":"森秀織物旧工場","kana":"もりひでおりものきゅうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.41031972,"lng":139.34471592,"geo_status":"db","era":"昭和21／昭和27頃増築","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積582㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0179","desc":"敷地の西辺に近接して，南北のほぼ中央に建つ。桁行１６ｍ，梁行２３ｍの規模で，木造平屋建，鉄板葺，３連の鋸屋根の形式で，南側が最も古い。小屋組はトラス形式であるが，桁行中央に柱を立てて補強する。桐生の織物工場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005573"},{"id":"00005574","register_sub_id":"101","register_pk":"106562","name":"森秀織物旧整経場","kana":"もりひでおりものきゅうせいけいじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410206,"lng":139.344711,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積135㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0180","desc":"旧工場の南側に接して建つ。桁行１６．０ｍ，梁間８．５ｍの規模で，木造平屋建，桟瓦葺とする。東西端部を切妻造とし，中央部を鋸屋根の形式とする。外壁は東面を竪板張り，西面を横板張りとする。妻面の竪板張りは下端を鋸歯状に切揃え意匠上の工夫をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005574"},{"id":"00005572","register_sub_id":"101","register_pk":"106560","name":"森秀織物旧土蔵","kana":"もりひでおりものきゅうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410557,"lng":139.34465605,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0178","desc":"敷地の西辺に近接して，やや北方に南北棟で建つ。桁行５間，梁間２間の規模で，木造２階建，切妻造，桟瓦葺とする。東面は１階中央に戸口を開き，１，２階面に左右対称に窓を開く。南北面の中央にも窓を開く。中規模の土蔵で，工場の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005572"},{"id":"00005571","register_sub_id":"101","register_pk":"106559","name":"森秀織物旧撚糸場","kana":"もりひでおりものきゅうねんしじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410576,"lng":139.344864,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0177","desc":"敷地北側に，旧寄宿舎二の南側に建つ。桁行１６．９ｍ，梁間７．５ｍの規模で，木造平屋建，切妻造，桟瓦葺で，小屋組はトラス組とする。内壁を漆喰塗，外壁を下見板張とし，西面に木製の格子窓を開き，その両側に戸口を開く。工場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005571"},{"id":"00005568","register_sub_id":"101","register_pk":"106556","name":"森秀織物旧物置（八丁撚糸場）","kana":"もりひでおりものきゅうものおき（はっちょうねんしじょう）","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.410213,"lng":139.34494303,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0174","desc":"敷地中央東寄りに建ち，桁行１０．８ｍ，梁間３．３ｍの建物と桁行６．６ｍ，梁間３．０ｍの建物がやや屈曲し，連続して建つ。共に木造平屋建，切妻造，桟瓦葺。小屋組を和小屋とし，東壁をＲＣ造とする。ほぼ創建時に紋紙を収蔵する物置として建設された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005568"},{"id":"00005566","register_sub_id":"101","register_pk":"106554","name":"森秀織物工場","kana":"もりひでおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県桐生市東4-2-24","lat":36.40980415,"lng":139.34494908,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積208㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"10 － 0172","desc":"南北に縦長の敷地の南東隅に建つ。桁行９ｍ，梁行２５ｍの規模で，木造平屋建，鉄板葺，３連の鋸屋根の形式とする。小屋組は木造トラスで，外壁は南側に元のモルタル塗が残るが，他は鉄板張りとなっている。鋸屋根を残し，桐生の織物工場の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005566"},{"id":"00016360","register_sub_id":"101","register_pk":"536427","name":"アトリエあずき倉庫（旧青木製餡工場倉庫）","kana":"あとりえあずきそうこ（きゅうあおきせいあんこうじょうそうこ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"埼玉県","address":"埼玉県さいたま市浦和区岸町七丁目125-1他","lat":35.8544,"lng":139.65123611,"geo_status":"db","era":"昭和26年／昭和50年・令和5年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"11 - 0238","desc":"ＪＲ浦和駅西方に位置する旧製餡工場の小豆倉庫。敷地中央に位置する切妻造妻入桟瓦葺の東西棟で、西に戸口を開け下屋を付す。外壁モルタル仕上。内部の東が旧倉庫で吹抜上部に洋小屋を現す。搬出入用貨車のレール敷を残し、往時の様相を留める小豆用倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016360"},{"id":"00011873","register_sub_id":"101","register_pk":"211149","name":"内木酒造店舗兼主屋","kana":"うちきしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県さいたま市桜区西堀六丁目905-1","lat":35.85379,"lng":139.629203,"geo_status":"db","era":"明治6年／平成20年改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"11-169","desc":"荒川左岸付近に構えた敷地中央に南面する。桁行一〇間、梁間七間で、寄棟造、桟瓦葺とし、下屋庇を廻らし正面には玄関を張出す。内部は、西半を広い土間とし、床上部は二列六室で、一〇畳奥の間は付書院を設け丁寧な造り。重厚な表構えを持つ明治初期の商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011873"},{"id":"00011874","register_sub_id":"101","register_pk":"211150","name":"内木酒造離れ","kana":"うちきしゅぞうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県さいたま市桜区西堀六丁目905-1","lat":35.85374,"lng":139.629369,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"11-170","desc":"店舗兼主屋の南東に接続する。入母屋造、桟瓦葺で、銅板葺の下屋庇を廻らす。内部は六畳と八畳を並べ、南西に矩折れに縁を廻らす。八畳は平書院を付け、欄間彫刻に凝った意匠を見せる。瀟洒な造りの離れであり、敷地内の景観を良好に形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011874"},{"id":"00007876","register_sub_id":"101","register_pk":"108856","name":"岸本家住宅主屋","kana":"きしもとけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県幸手市中2-6249-1他","lat":36.07272513,"lng":139.71846628,"geo_status":"db","era":"江戸末期／昭和後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"11-0126","desc":"旧日光街道に西面する。木造つし２階建、桟瓦葺。正面切妻造、背面寄棟造とする主体部の正面に、寄棟造屋根の平側半部のような下屋を付ける。下屋を店舗とし、主体部境には土戸構えを残す。ひときわ目をひく特異な外観で、往時の幸手宿の賑わいが偲ばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007876"},{"id":"00002521","register_sub_id":"101","register_pk":"103511","name":"旧石川組製糸西洋館別館","kana":"きゅういしかわぐみせいしせいようかんべっかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県入間市河原町13-13","lat":35.844646,"lng":139.388947,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"11 － 0038","desc":"石川組製糸は明治から昭和にかけて操業した県内屈指の製糸会社。北が正面の西洋館の東側に，少し遅れて建てられたという。木造平屋建，中廊下式の平面で，北面と南面に各室を配する。外観は軸組をあらわして壁を化粧煉瓦張とし，本館と調和が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002521"},{"id":"00002520","register_sub_id":"101","register_pk":"103510","name":"旧石川組製糸西洋館本館","kana":"きゅういしかわぐみせいしせいようかんほんかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県入間市河原町13-13","lat":35.84453047,"lng":139.38881098,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺一部銅板葺、建築面積301㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"11 － 0037","desc":"石川組製糸がアメリカの貿易商をもてなすため，設計を室岡惣七として建設した迎賓施設。木造２階建で，内部は各室毎に変化を持たせ，天井から造作まで丁寧なつくりになる。セピア色の化粧煉瓦張とした端正な外観は，当地域の近代の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002520"},{"id":"00006789","register_sub_id":"101","register_pk":"107771","name":"旧鏡山酒造昭和蔵","kana":"きゅうかがみやましゅぞうしょうわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市新富町1-10-1","lat":35.9161229,"lng":139.483887,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積231㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"11 － 0115","desc":"大正蔵の東南に東西棟で建つ。桁行２５ｍ梁間９．１ｍの切妻造桟瓦葺２階建。外壁は漆喰仕上げ腰モルタル塗とし、水切りを妻側に３段、平側に２段設け、折釘を等間隔に配する。内部は梁間中央に太い通し柱を３間ごとに建て、２階では豪壮な和小屋組を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006789"},{"id":"00006788","register_sub_id":"101","register_pk":"107770","name":"旧鏡山酒造大正蔵","kana":"きゅうかがみやましゅぞうたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県川越市新富町1-10-1","lat":35.916248,"lng":139.483688,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積304㎡","structure_material":"土蔵造2階一部平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"11 － 0114","desc":"明治蔵の東に東西棟で建つ。切妻造桟瓦葺で棟高い上屋に、規模の大きな下屋が南北に取り付き、桁行２２ｍ梁間１４ｍ規模に及ぶ。外壁は漆喰仕上げ、腰下見板張で、上屋南北面を真壁造とし、軒まわりに木部を表すなど、大規模ながら軽快な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006788"},{"id":"00006787","register_sub_id":"101","register_pk":"107769","name":"旧鏡山酒造明治蔵","kana":"きゅうかがみやましゅぞうめいじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県川越市新富町1-10-1","lat":35.916248,"lng":139.483429,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積418㎡","structure_material":"土蔵造2階一部平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"11 － 0113","desc":"西面する敷地の西寄り、通り沿いに建つ。南北棟の切妻造妻入桟瓦葺で、東・西・北面に深い下屋をまわし、桁行２１ｍ梁間２０ｍ規模とする。外壁は漆喰仕上げで、腰まわりを下見板張とする。内部は真壁造。南正面の大きな妻壁が重厚で落ち着きある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006787"},{"id":"00013689","register_sub_id":"101","register_pk":"505203","name":"旧玉成舎石蔵","kana":"きゅうぎょくせいしゃいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"埼玉県","address":"埼玉県比企郡小川町大字小川字町裏197-4","lat":36.05316389,"lng":139.26143889,"geo_status":"db","era":"昭和36年／平成30年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"石造2階建、瓦葺、建築面積41㎡","structure_material":"石造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"11 － 201","desc":"主屋西に渡廊下で接続する。桁行八メートル梁間五メートルの石造二階建切妻造桟瓦葺。大谷石積を化粧で現し、東面の開口は重厚なスチール製の開き戸とし意匠上のポイントとなる。内部は一部吹抜で小屋組は木造キングポストトラス。地域の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013689"},{"id":"00013688","register_sub_id":"101","register_pk":"505201","name":"旧玉成舎主屋","kana":"きゅうぎょくせいしゃおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県比企郡小川町大字小川字町裏197-4","lat":36.05309722,"lng":139.26155833,"geo_status":"db","era":"明治21年／昭和6年移築改修、平成30年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積90㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"11 － 200","desc":"二階建入母屋造鉄板葺で南面して建つ。明治中期の建築としては二階の建ちが高く、南縁にガラス戸を建て手摺を付す。内部は東を土間、西を二列四室としたが飲食店に改装した。二階は廊下を挟んで四室配する。もと養蚕生育法の伝習館として歴史的に重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013688"},{"id":"00012875","register_sub_id":"101","register_pk":"367983","name":"旧強谷織物工場","kana":"きゅうすねやおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市山田字上西新木1660-1他","lat":36.00861944,"lng":139.11141667,"geo_status":"db","era":"昭和5年／昭和中期改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺及び金属板葺、建築面積443㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"11 － 189","desc":"市街地東北方にある旧絹織工場。木造平屋建、四連の鋸屋根桟瓦葺、屋根北面は鉄板葺で、天窓を設ける。内部は一空間で、西南北三面に出入口を設け、各棟通りの三間毎に柱を立てる。外壁下見板張、トラス小屋組。絹産業で栄えた近代秩父の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012875"},{"id":"00012700","register_sub_id":"101","register_pk":"367603","name":"旧森龍織物工場","kana":"きゅうもりりゅうおりものこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川口市大字安行領根岸字台2219","lat":35.84291278,"lng":139.71623278,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積310㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 186","desc":"敷地前方に建つ。木造平屋建の鉄板葺で、東西棟の鋸屋根4棟を連ねる。南1棟を倉庫、北3棟を工場にあて、中央2棟の西面に出入口を設ける。内部は棟通りに柱を三間毎に立て、小屋はトラスとする。主屋とともに近代川口の工場制手工業の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012700"},{"id":"00012699","register_sub_id":"101","register_pk":"367602","name":"旧森龍織物主屋","kana":"きゅうもりりゅうおりものしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川口市大字安行領根岸字台2219","lat":35.84291278,"lng":139.71623278,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 185","desc":"市北部の工場併設住宅。主屋は敷地後方に南面して建つ寄棟造銅板葺の平屋建で、四面に下屋を付す。東に土間、西に2列4室を配して南西二面に縁を廻し、西列奧に座敷を設ける。伝統民家の形式を継承し、近代に発展した川口の工場制手工業の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012699"},{"id":"00014567","register_sub_id":"101","register_pk":"515109","name":"都築家糀屋蔵","kana":"つづきけこうじやくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷本町4696-1","lat":35.89455278,"lng":139.78448333,"geo_status":"db","era":"昭和前期／令和2年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造2階建、銅板葺、建築面積43㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"11 - 0221","desc":"日光街道越ヶ谷宿の味噌醸造業商家の土蔵風鉄筋コンクリート造倉庫。切妻造平入銅板瓦棒葺、外壁は砂利洗出仕上。各階内壁板張、天井漆喰仕上。南面に四箇所開口を設けて掛子塗形鉄扉を吊り、一階東側が戸口で他は窓とし、戸口扉はダイヤル錠で堅牢な金庫風。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014567"},{"id":"00011876","register_sub_id":"101","register_pk":"211052","name":"飯能織物協同組合事務所棟","kana":"はんのうおりものきょうどうくみあいじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県飯能市仲町（元原町分）31","lat":35.853718,"lng":139.318534,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積221㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"11-172","desc":"飯能の経済を支えた織物業の組合事務所。和洋折衷の意匠でまとめる木造二階建で、屋根は寄棟造桟瓦葺、外壁下見板張。小屋はトラス。一階廊下の漆喰内壁の鏝絵、二階大広間天井は小幅の折上天井で中央部に起りを持たせるなど、細部意匠にも特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011876"},{"id":"00004113","register_sub_id":"101","register_pk":"105103","name":"亀屋商事（旧飯島製糸）煉瓦倉庫","kana":"かめやしょうじ（きゅういいじませいし）れんがそうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県古河市東1-15-11","lat":36.19737059,"lng":139.71262386,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造平屋建、瓦葺一部亜鉛葺、建築面積192㎡","structure_material":"煉瓦造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0127","desc":"県道を隔てた向かいの敷地に南北棟で建つ。桁行１５間梁間３間規模の長大な煉瓦造２階建倉庫で，壁は１枚半厚のイギリス積，屋根は切妻造，桟瓦葺とする。１階の南北両妻壁を東方に延ばして下屋庇を架け，２戸口を設ける。製糸業の繁栄振りを物語る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004113"},{"id":"00011446","register_sub_id":"101","register_pk":"210415","name":"旧大塚酒造店舗兼主屋","kana":"きゅうおおつかしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県坂東市岩井3351-2","lat":36.050288,"lng":139.885223,"geo_status":"db","era":"明治中期／平成28年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積176㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"08-0297","desc":"敷地西北方に建つ。桁行一五メートル、梁間一○メートルの規模で、屋根は寄棟造桟瓦葺。整形四間取り平面を基本とするが、東南角に台所を突出させ、座敷背面に廊下を廻らすなど近代的な様相を示す。岩井中心地のにぎわいを今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011446"},{"id":"00011447","register_sub_id":"101","register_pk":"210416","name":"旧大塚酒造本蔵","kana":"きゅうおおつかしゅぞうほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県坂東市岩井3351-2","lat":36.050576,"lng":139.885687,"geo_status":"db","era":"明治28年／平成28年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積795㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"08-0298","desc":"切妻造桟瓦葺で、桁行一七間梁間六間の身舎の三方に三間幅の下屋が取り付き、建築面積七九〇平方メートル余を誇る大規模醸造蔵。身舎部分は全て二階建で和小屋を組み、中央二列の柱は三〇センチ角の太い柱を用いて大空間を支える。地域の歴史を今に伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011447"},{"id":"00014231","register_sub_id":"101","register_pk":"509621","name":"旧岡山酒造養浩園喜雨亭","kana":"きゅうおかやましゅぞうようこうえんきうてい","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県常陸大宮市高部字宿3970","lat":36.66263333,"lng":140.303275,"geo_status":"db","era":"明治中期／平成7年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造3階建、銅板葺、建築面積50㎡","structure_material":"木造3階建","registered":"2022.06.29(令和4.06.29)","register_no":"08 - 0315","desc":"常陸太田と那須を結ぶ街道の高部集落に所在する木造三階建座敷棟。入母屋造で当初は木羽葺。庭に面する南に入口を開く。二階に床付き座敷を構え書画を飾り接客に用いる。三階は大きく逓減させて壁面に看板と色ガラスを嵌めて広告に用い、目を引く建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014231"},{"id":"00002209","register_sub_id":"101","register_pk":"103199","name":"小田部鋳造北土蔵","kana":"こたべちゅうぞうきたどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田45","lat":36.27383,"lng":140.096466,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造平屋一部2階建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0057","desc":"主屋の東方に位置する。桁行１３間，梁行３間の長い南北棟，切妻造，桟瓦葺土蔵で，東側１間通りは下屋部とし，西側前面に１間幅の庇を架けて蔵前を造る。内部は北方３間半を物置，南方９間半分を荷蔵とし，荷蔵には２箇所の戸口を西面に開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002209"},{"id":"00002746","register_sub_id":"101","register_pk":"103736","name":"関根家住宅店舗","kana":"せきねけじゅうたくてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁390","lat":36.27923729,"lng":140.10153602,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0060","desc":"真壁町の市街地北寄にあり，明治８年の建設と伝える。通りに面して建つ店舗は，木造２階建，切妻造・桟瓦葺，平入の形式で，通り側に半間幅の下屋庇を設けている。１階はＬ字型土間と帳場からなり，開放的な下屋部分と相俟って商家らしい構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002746"},{"id":"00013677","register_sub_id":"101","register_pk":"505179","name":"立川醤油店店舗及び主屋","kana":"たちかわしょうゆてんてんぽおよびおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県常陸太田市西二町字西二西2177他","lat":36.53914722,"lng":140.52261389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積269㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"08 － 314","desc":"太田城址の南に位置。通りに東面して店舗を構え、背後に主屋が接する。店舗はつし二階建切妻造桟瓦葺で正面に下屋を通し、一階南半を土間に板間を張出した店とする。主屋は二階建切妻造桟瓦葺の主体部の南北に下屋を付す。間口の広い店舗が通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013677"},{"id":"00004911","register_sub_id":"101","register_pk":"105901","name":"府中誉釜場","kana":"ふちゅうほまれかまば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18506178,"lng":140.27506986,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積269㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"08 － 0199","desc":"仕込蔵の東側に位置する桁行１８ｍ，梁間１５ｍ規模の平屋建の土蔵。和小屋で，入母屋造とし，棟の南寄りに越屋根を付ける。平側の外装は押縁下見板張で，妻壁と内壁には漆喰を塗り込める。仕込蔵と同じく，創業後間もなくして整備されたと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004911"},{"id":"00004206","register_sub_id":"101","register_pk":"105196","name":"府中誉穀蔵","kana":"ふちゅうほまれこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18549872,"lng":140.27518897,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木骨コンクリート造2階建、瓦葺、建築面積141㎡","structure_material":"木骨コンクリート造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0139","desc":"主屋の東南方に位置し南北棟で建つ。桁行８間梁間４間規模，切妻造，桟瓦葺の木骨コンクリート造２階建酒米蔵で，西面全面に８尺幅で下屋庇を差し掛ける。外部は人造石洗い出し仕上げで，石目地を切る。昭和４年の大火後の構法を伝えるものとして貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004206"},{"id":"00004910","register_sub_id":"101","register_pk":"105900","name":"府中誉仕込蔵","kana":"ふちゅうほまれしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18522225,"lng":140.27482809,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積950㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"08 － 0198","desc":"南北に細長い敷地のほぼ中央に建つ。桁行４７．５ｍ，梁間２０ｍ規模の土蔵造２階建で，小屋組は和小屋とする。南側は切妻造，北側は入母屋造で妻面を押縁下見板張とし，両妻面に窓を開く。屋敷の中央に位置する規模の大きな酒造工場施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004910"},{"id":"00004912","register_sub_id":"101","register_pk":"105902","name":"府中誉舂屋","kana":"ふちゅうほまれつきや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18532435,"lng":140.27515018,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積132㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"08 － 0200","desc":"敷地中央の東端に建つ，米舂き精米用施設。桁行１８ｍ，梁間７．３ｍ規模の土蔵で，寄棟造，桟瓦葺とする。外装は漆喰塗，腰を押縁下見板張とし，妻側と西面に大小の窓を配し，軒裏には鉢巻を廻す。簡素ではあるが，酒造製造工場の重要な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004912"},{"id":"00008628","register_sub_id":"101","register_pk":"149349","name":"武勇煙突","kana":"ぶゆうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30337743,"lng":139.87261292,"geo_status":"db","era":"大正期／平成6年改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ11m","structure_material":"煉瓦造","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0248","desc":"脇蔵の南、仕込蔵と旧釜蔵が造る入隅に位置する。旧釜場蔵地下の釜場と接続して、現在も使用されている。煉瓦造。高さ11ｍで、東西1.2ｍ南北1.1ｍの矩形平面になる。土蔵漆喰仕上げの白と煉瓦色が好対照をなし、地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008628"},{"id":"00008627","register_sub_id":"101","register_pk":"149348","name":"武勇旧釜蔵","kana":"ぶゆうきゅうかまぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.3034124,"lng":139.87252004,"geo_status":"db","era":"明治37年／平成6年改修","year":1904,"year_source":"converted","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積60㎡、保冷室付","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0247","desc":"仕込蔵の西北に接する。桁行11ｍ梁間5.6ｍ、土蔵造平屋建、東西棟の切妻造桟瓦葺。北面西半に南北棟の切妻造、桁行8.9ｍ梁間3.6ｍ、木造平屋建の保冷室を付す。漆喰上げの妻面を大きく見せる旧釜蔵と、低い棟の真壁造の保冷室が変化ある外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008627"},{"id":"00008626","register_sub_id":"101","register_pk":"149347","name":"武勇仕込蔵","kana":"ぶゆうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30324957,"lng":139.87259872,"geo_status":"db","era":"明治42年","year":1909,"year_source":"converted","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積207㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0246","desc":"敷地のほぼ中央、脇蔵の南方、製品蔵の西に隣接する。桁行25ｍ梁間8.1ｍの土蔵造平屋建、南北棟の切妻造桟瓦葺、。漆喰仕上げで、腰高に水切りをまわす。南北両妻面に鉄製引込戸をたてる。内部には1室で、独立柱八本をたて、漆喰仕上げの真壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008626"},{"id":"00008625","register_sub_id":"101","register_pk":"149346","name":"武勇製品蔵","kana":"ぶゆうせいひんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30316734,"lng":139.87271783,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積318㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0245","desc":"見世蔵の南に隣接する。土蔵造二階建、桁行23ｍ梁間14ｍ。南北棟の切妻造桟瓦葺、西面は全体にわたり、葺き降ろす。北面に出入口を開け、見世蔵と連絡する。漆喰仕上げで、鉢巻まで高く下見板を張る。大規模な蔵で、老舗酒造の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008625"},{"id":"00008623","register_sub_id":"101","register_pk":"149344","name":"武勇見世蔵","kana":"ぶゆうみせぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30336705,"lng":139.8728181,"geo_status":"db","era":"江戸末期／昭和20年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積224㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0243","desc":"通りに北面して建つ。木造2階建、建築面積224㎡。南北棟の寄棟造を中心に、通り寄りに東へ切妻屋根を延ばす。桟瓦葺。大壁造で漆喰仕上げとし、1階は東寄りに出入口を構え、西は腰に大谷石を積み、中央上部に窓を造る。どっしりとした構えになる店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008623"},{"id":"00008624","register_sub_id":"101","register_pk":"149345","name":"武勇脇蔵","kana":"ぶゆうわきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字浦町144","lat":36.30342196,"lng":139.87276892,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0244","desc":"見世蔵の西に隣接して、通りに沿って建つ。土蔵造2階建、東西棟の切妻造桟瓦葺、桁行11ｍ梁間4.5ｍ。漆喰仕上げで、通りに面して腰に石を貼り、その上部を竪板張とする。南面に引込戸の出入口を設ける。見世蔵とともに、重厚な通り景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008624"},{"id":"00001996","register_sub_id":"101","register_pk":"102986","name":"村井醸造石蔵","kana":"むらいじょうぞういしぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁200-1","lat":36.27682193,"lng":140.10032462,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造平屋建、瓦葺、建築面積145㎡","structure_material":"石造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0046","desc":"石蔵は道路を挟んだ脇蔵の対面に建つ。桁行１２間の長大な切妻造・妻入の建物で，内部は３室に分かれ，道路側の南面と扉口のある東面に下屋庇を設ける。木造軸組にキングポストトラスを架け，外側を大谷石積とした形式で，大正期の倉庫建築の良好な事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001996"},{"id":"00004326","register_sub_id":"101","register_pk":"105316","name":"村井醸造煙突","kana":"むらいじょうぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁72","lat":36.27636083,"lng":140.10016204,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、高さ22m","structure_material":"鉄筋コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0156","desc":"店舗と土蔵の間に置かれ，基部直径１．４５ｍ，高さ２２ｍの規模を有する。当時の最新の技術を用いた鉄筋コンクリート造で，煙道口はアーチ積とし，内部には耐火煉瓦を積み，頂上付近には櫛形の装飾を施す。町の景観を特徴づける工作物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004326"},{"id":"00001995","register_sub_id":"101","register_pk":"102985","name":"村井醸造脇蔵","kana":"むらいじょうぞうわきぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁72","lat":36.27683398,"lng":140.10018366,"geo_status":"db","era":"明治35以前","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積105㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0045","desc":"村井家は江戸中期頃から醸造業を営んだ旧家で，真壁の中心部に位置する。もと穀蔵の脇蔵は，桁行７間，梁間４間の規模で，南北棟の切妻造・桟瓦葺屋根をかける。丁寧な切石積の基礎，腰の縦板壁と上部の漆喰壁が調和し，角地の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001995"},{"id":"00001551","register_sub_id":"101","register_pk":"102541","name":"結城酒造株式会社煉瓦煙突","kana":"ゆうきしゅぞうかぶしきがいしゃれんがえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城1589","lat":36.30500567,"lng":139.87183556,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"煉瓦造、高さ10m","structure_material":"煉瓦造","registered":"2000.04.28(平成12.04.28)","register_no":"08 － 0023","desc":"高さ約１０ｍの煉瓦煙突は，安政蔵の北側にあり，明治３６年の建設と伝える。安政蔵の釜場と地下の煙道で結ばれており，酒造施設の近代的な工夫がうかがえるとともに，商業都市として栄え，酒造業も盛んであった結城の景観のシンボルともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001551"},{"id":"00011884","register_sub_id":"101","register_pk":"211058","name":"飯沼本家裏門及び塀","kana":"いいぬまほんけうらもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々106-1","lat":35.709437,"lng":140.272092,"geo_status":"db","era":"昭和29年頃","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"裏門 木造、瓦葺、間口2.8m 塀 木造、銅板葺、総延長3.6m、潜戸付","structure_material":"裏門 木造","registered":"2017.10.27(平成29.10.27)","register_no":"12-242","desc":"敷地東面を画す門。間口二・八メートルの一戸薬医門で、切妻造、桟瓦葺。北側に潜戸を開き、南北袖塀付で、北側は斜めに取り付く。五平の本柱上に冠木を渡し、男梁を架けて桁を受け、棟木は束で受ける簡素な構造。通りからの景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011884"},{"id":"00011883","register_sub_id":"101","register_pk":"211057","name":"飯沼本家甲子蔵","kana":"いいぬまほんけきのえねぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々105-7他","lat":35.709279,"lng":140.27204,"geo_status":"db","era":"昭和15年頃／昭和前期移築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階一部平屋建、鉄板葺及び鋼板葺、建築面積382㎡","structure_material":"木造2階一部平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"12-241","desc":"主屋東方に西面する。桁行一六間、梁間九間、切妻造で越屋根を付け、北西角に応接室を張出す。外壁は腰を板張、上部を漆喰塗とし、小屋組はクイーンポストトラスである。応接室は、扇状に配った天井や幾何学模様の欄間など、様々な意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011883"},{"id":"00011882","register_sub_id":"101","register_pk":"211056","name":"飯沼本家明治蔵","kana":"いいぬまほんけめいじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々107-1他","lat":35.709672,"lng":140.271887,"geo_status":"db","era":"明治中期／昭和30年代改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階一部平屋建、鋼板葺、建築面積291㎡","structure_material":"土蔵造2階一部平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"12-240","desc":"敷地北東隅に南面する。桁行一六間、梁間八間、切妻造、鋼板葺で、南面に検査場を張り出す。内部は一室であり、上屋柱筋に直径一尺二寸の丸太材の柱を二間置きに立て、二階では柱上に二段に組んだ梁組をみせる。酒造施設に欠かせない大規模な蔵を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011882"},{"id":"00012104","register_sub_id":"101","register_pk":"352903","name":"石上酒造麹室","kana":"いしがみしゅぞうこうじむろ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.73263,"lng":140.842559,"geo_status":"db","era":"明治29年頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造平屋建、金属板葺、建築面積42㎡","structure_material":"石造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-249","desc":"敷地南寄り、米蔵の西に建つ。大谷石による組積造で、壁体には厚さ三〇センチメートルの大谷石を長手方向に積む。屋根は切妻造鉄板葺。内部は全面杉板張とし、壁体との間には保温のために籾殻を詰め、天井板上にも藁を敷く。酒造業に欠かせない麹室の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012104"},{"id":"00012103","register_sub_id":"101","register_pk":"352902","name":"石上酒造米蔵","kana":"いしがみしゅぞうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.73263,"lng":140.842662,"geo_status":"db","era":"明治中期／平成23年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積29㎡","structure_material":"土蔵造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-248","desc":"銚子市街の中心地に位置し、南北棟で建つ土蔵造二階建で、屋根は切妻造桟瓦葺とする。室内は一、二階とも一室とし、一階は土間叩きとする。外壁は腰海鼠壁、上部漆喰塗で軒まで塗込めるが、中層部には鋼板を張っている。敷地建物群南東端を画す土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012103"},{"id":"00012105","register_sub_id":"101","register_pk":"352904","name":"石上酒造仕込蔵（醪蔵）","kana":"いしがみしゅぞうしこみぐら（もろみぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.732641,"lng":140.842502,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"石造2階建、瓦葺、建築面積86㎡","structure_material":"石造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-250","desc":"敷地の西南隅に建つ石造蔵。大谷石を積む壁構造で、屋根は切妻造桟瓦葺。内部は一、二階とも一室とし、小屋組は一階基礎を高く設けて木造側柱を立ち上げ、クイーンポストトラスを支える。酒造業の中核をなす蔵で、地域の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012105"},{"id":"00012106","register_sub_id":"101","register_pk":"352905","name":"石上酒造貯蔵蔵","kana":"いしがみしゅぞうちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.732767,"lng":140.842518,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積146㎡","structure_material":"石造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"12-251","desc":"仕込蔵の北に接して建つ。桁行一八・五メートル、梁間七・九メートルの規模で、内部は土間の一室とし、絞り機や醸造タンクを収める。壁体は大谷石の長手積で、キングポストトラスに切妻造桟瓦葺とする。酒造の中核をなす蔵で地域の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012106"},{"id":"00012107","register_sub_id":"101","register_pk":"352906","name":"石上酒造文庫蔵","kana":"いしがみしゅぞうぶんこくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県銚子市田中町7-1","lat":35.732901,"lng":140.842514,"geo_status":"db","era":"明治35年頃／平成23年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"12-252","desc":"敷地北西隅に南北棟で建つ。桁行七・七メートル、梁間五・九メートルのほぼ正方形平面で、東面に扉口を開く。コンクリート基礎上に基礎石を置き、漆喰壁を立ち上げ、屋根は切妻造桟瓦葺とする。街路に面する北妻面二階には左右に窓を開き、アクセントとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012107"},{"id":"00007458","register_sub_id":"101","register_pk":"108440","name":"鶴泉堂菓子店石倉庫","kana":"かくせんどうかしてんいしそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県匝瑳市八日市場イ2871","lat":35.7009041,"lng":140.54844528,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"石造2階地下1階建、瓦葺、建築面積30㎡","structure_material":"石造2階地下1階建","registered":"2009.01.08(平成21.01.08)","register_no":"12 － 0117","desc":"敷地南端に建つ。桁行５．５ｍ梁間３．６ｍ、地上２階地下１階建の石蔵で、東西棟の切妻造桟瓦葺。北面に瓦葺庇を掛けて出入口を設け、上部に庇付窓を穿つ。切石を積み上げ壁面を造り、水切りや鉢巻をまわす。大谷石の柔らかい風合いが落ち着いた景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007458"},{"id":"00007457","register_sub_id":"101","register_pk":"108439","name":"鶴泉堂菓子店店舗兼主屋","kana":"かくせんどうかしてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県匝瑳市八日市場イ2871","lat":35.70112928,"lng":140.54845652,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積69㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"12 － 0116","desc":"通りに二面する南北に長い敷地の北端に建つ。間口６．６ｍ奥行１０ｍの木造２階建。寄棟造妻入桟瓦葺で、出桁造で垂木を配る。北正面から小路に面した西側に下屋庇をまわし、鉤の手にガラス戸をたて開放的に扱う。昭和前期における建ちの高い町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007457"},{"id":"00013349","register_sub_id":"101","register_pk":"368437","name":"キノエネ醤油旧火入場及び変電室","kana":"きのえねしょうゆきゅうひいればおよびへんでんしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市中野台字久保之内157他","lat":35.94756667,"lng":139.86055833,"geo_status":"db","era":"大正10年／昭和28年増築、同51年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造3階一部煉瓦造及び木造2階建、瓦葺、建築面積82㎡","structure_material":"鉄筋コンクリート造3階一部煉瓦造及び木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0299","desc":"敷地南辺東寄りの正門を入って正面に建つ。鉄筋コンクリート造三階建、切妻造セメント瓦葺の火入場と、一階煉瓦造、二階木造で、パラペットを立上げた変電室からなる。火入場の小屋はキングポストトラス組とする。野田で最初期の鉄筋コンクリート造建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013349"},{"id":"00013348","register_sub_id":"101","register_pk":"368436","name":"キノエネ醤油事務所兼主屋","kana":"きのえねしょうゆじむしょけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市中野台字久保之内157他","lat":35.9474,"lng":139.86069167,"geo_status":"db","era":"明治30年／明治36年増築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、瓦葺、建築面積167㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0298","desc":"野田市街に位置し、敷地南辺東寄りに開く正門脇に西面して建つ。切妻造桟瓦葺平入の事務所東側に入母屋造東西棟の主屋が続く。事務所正面外観にはガラス窓を配し、一階に事務室と洋風の応接室を配す。地場産業である醤油工場の施設として景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013348"},{"id":"00008259","register_sub_id":"101","register_pk":"133901","name":"旧浅子神輿店店舗兼主屋","kana":"きゅうあさこみこしてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県市川市本行徳37-2","lat":35.69043123,"lng":139.91553178,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積103㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"12 － 0149","desc":"旧行徳街道に東面する。間口６．４ｍの木造２階建、切妻造桟瓦葺で、背面に平屋建の居室が続く。１階は前寄り半間に土間を通し、板床の広い作業場とし、２階はトコや平書院を設ける。上屋は出桁造、下屋は軒桁を架け、開放とする。木太く、力強い印象の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008259"},{"id":"00007616","register_sub_id":"101","register_pk":"108598","name":"宍倉弥兵衛商店店舗兼主屋","kana":"ししくらやへえしょうてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町大多喜字下南郭60-1","lat":35.28287104,"lng":140.2454339,"geo_status":"db","era":"明治7／昭和29・昭和41・平成17改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造2階建、瓦葺、建築面積116㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"12 － 0124","desc":"夷隅神社の西北、通りに東面して建つ。木造２階建の町家で、寄棟造桟瓦葺とし、正面及び南面、背面に庇を付ける。１階に店舗、２階に居室等を配する。出桁造で疎らに垂木を配り、２階正面は南半部を真壁、北半部を出格子窓とする。伝統的な町家の佇まいを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007616"},{"id":"00002613","register_sub_id":"101","register_pk":"103603","name":"鈴木家住宅穀蔵","kana":"すずきけじゅうたくこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県鴨川市西町1139-3","lat":35.11645671,"lng":140.11482581,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積99㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0048","desc":"主屋の東南東に建つ。桁行４間，梁間３間規模の南北棟，桟瓦葺，切妻造，平入で，西面には土庇を架ける。酒米を納めた蔵で，外壁を漆喰塗とし，１階部には下見板張りを施す。東門への通路を隔てて火入れ蔵の北方に位置し，両者で造り酒屋の屋敷景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002613"},{"id":"00002612","register_sub_id":"101","register_pk":"103602","name":"鈴木家住宅火入れ蔵","kana":"すずきけじゅうたくひいれぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県鴨川市西町1139-3","lat":35.11634713,"lng":140.11486023,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積121㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"12 － 0047","desc":"主屋の東南方，敷地東辺の門の近くに建つ。桁行６間，梁間４間規模の東西棟，桟瓦葺，切妻造，妻入で，西妻面に１間半幅の下屋を差し出して検査室等とする。酒造最終工程の腐敗防止処理と出荷までの貯蔵をなす蔵であり，造り酒屋の屋敷構えを構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002612"},{"id":"00001172","register_sub_id":"101","register_pk":"102162","name":"寺田本家醸造蔵","kana":"てらだほんけじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県香取郡神崎町神崎本宿1964","lat":35.90540155,"lng":140.40153507,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"煉瓦造平屋建，瓦葺，建築面積241㎡","structure_material":"煉瓦造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0014","desc":"延宝年間（１６７３年）創業と伝える酒造家の醸造蔵。煉瓦造２階建で、瓦葺寄棟屋根の南面に切妻の屋根窓を張出す。煉瓦積はイギリス積、小屋組はクイーンポストトラスで、対束の頭部を繋ぐ水平材を挟み梁とするなど構法上にも見どころがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001172"},{"id":"00008823","register_sub_id":"101","register_pk":"162266","name":"豊乃鶴酒造煙突","kana":"とよのつるしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.2844955,"lng":140.24725389,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"煉瓦造、高さ16m","structure_material":"煉瓦造","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0159","desc":"工場の正面の西寄りに位置する。基礎部分は方1.6ｍの正方形平面で、高さ16ｍを測る。イギリス積で積み上げ、頂部は三段に迫り出す。足下には点検口を設ける。重厚な工場前にそびえ立つ煉瓦造煙突で、酒醸造所らしい景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008823"},{"id":"00008821","register_sub_id":"101","register_pk":"162264","name":"豊乃鶴酒造工場","kana":"とよのつるしゅぞうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28463378,"lng":140.24728979,"geo_status":"db","era":"明治8年頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積417㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0157","desc":"敷地北奥に位置する。建築面積417㎡と大規模な木造平屋建。南北棟の切妻造桟瓦葺2棟を東西に並べ、南面に下屋を通して入母屋造風の外観とする。外観は、妻を塗り込め、東棟をやや低くして変化を与え、内部は真壁で、天井を張らず和小屋を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008821"},{"id":"00008822","register_sub_id":"101","register_pk":"162265","name":"豊乃鶴酒造酒蔵","kana":"とよのつるしゅぞうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28474414,"lng":140.24709833,"geo_status":"db","era":"明治8年","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積213㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0158","desc":"敷地西北隅に南北棟で建ち、西面は通りに面する。桁行15ｍ梁間9.1ｍ、切妻造桟瓦葺で、東面に梁間5.5ｍの下屋を付設する。内部は下屋を間仕切り、1階は1室の大空間とする。内壁は中塗の真壁で、半間ごとに柱を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008822"},{"id":"00001408","register_sub_id":"101","register_pk":"102398","name":"豊乃鶴酒造主屋","kana":"とよのつるしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28425135,"lng":140.24728328,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造2階建、瓦葺、建築面積134㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"12 － 0034","desc":"大多喜城下の市場町として栄えた集落に位置する造り酒屋の主屋。つし二階建ての町家で，座敷飾りに銘木を用いたり，二階の軒を出桁造とするなど質が高い建築であり，出窓格子，上げ戸などからなる表構えも，往時の趣を良く伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001408"},{"id":"00008820","register_sub_id":"101","register_pk":"162263","name":"豊乃鶴酒造精米所及び貯蔵庫","kana":"とよのつるしゅぞうせいまいじょおよびちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28429473,"lng":140.24753045,"geo_status":"db","era":"明治前期／平成22年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0156","desc":"敷地東南隅に南北棟で建つ。桁行14ｍ梁間6.4ｍ、切妻造桟瓦葺で、北・西面に下屋を付設。内部は2室に分かれ、南を酒米貯蔵庫、北を精米所とする。外壁は高く下見板を張り、真壁の漆喰仕上げ。主屋とともに通りに面し敷地正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008820"},{"id":"00008819","register_sub_id":"101","register_pk":"162262","name":"豊乃鶴酒造店舗","kana":"とよのつるしゅぞうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県夷隅郡大多喜町新丁字下宿88","lat":35.28442636,"lng":140.24722863,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"12 － 0155","desc":"角地に占める敷地の中央に位置する。東面する入母屋造妻入桟瓦葺の木造2階建、建築面積66㎡。1階正面に下屋、2階に庇を付ける。正面にミセ、その奥に居室を配する。2階の主室はトコや棚などを構え、円窓を穿つなど瀟洒な座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008819"},{"id":"00010117","register_sub_id":"101","register_pk":"197950","name":"中村家住宅稲荷社","kana":"なかむらけじゅうたくいなりしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-3","lat":35.716697,"lng":139.940616,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.3㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0177","desc":"敷地の南西側に位置し、江戸切仕上げの石積基壇上に東面して鎮座する。一間社流造、銅板葺で、正側面に縁高欄を廻らし、正面に木階を設ける。良質なケヤキを主材とし、水引虹梁や妻虹梁上に蟇股を飾り、妻飾に懸魚を吊る。丁寧な造作になる稲荷社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010117"},{"id":"00010115","register_sub_id":"101","register_pk":"197948","name":"中村家住宅北蔵及び事務所","kana":"なかむらけじゅうたくきたぐらおよびじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県市川市鬼越2-200-1","lat":35.716926,"lng":139.941029,"geo_status":"db","era":"北蔵 大正後期 事務所 昭和前期","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺及び鉄板葺、建築面積55㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0175","desc":"主屋の東側に位置し、西半が木造二階建の北蔵で、その南西面に事務所を接続する。北蔵は当初より外壁鉄板張で、両妻面に窓を穿つ。事務所は洗出し仕上げで石造風に化粧目地を施し、頂部のコーニスと窓上部のアーチをアクセントとする、洋風意匠の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010115"},{"id":"00010111","register_sub_id":"101","register_pk":"197944","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-1他","lat":35.716947,"lng":139.940821,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積193㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0171","desc":"寄棟造桟瓦葺の住宅で、千葉街道側に北妻面を向け、東面に切妻造の玄関を構え、周囲に下屋を廻らせる。北面軒は黒漆喰塗込で蛇腹をつくり、他は出桁造とする。内部は北寄りを応接間とし、後方を座敷とする。並び建つ煉瓦蔵とともに重厚な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010111"},{"id":"00010116","register_sub_id":"101","register_pk":"197949","name":"中村家住宅倉庫","kana":"なかむらけじゅうたくそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-2","lat":35.716617,"lng":139.940833,"geo_status":"db","era":"南倉庫 明治中期／昭和前期移築 北倉庫 明治後期","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0176","desc":"敷地南東側に南北棟で建つ。明治後期に建てられた北倉庫の南側に、明治中期の南倉庫を曳家して一体化したとみられ、総桁行二一メートルを測る。木造平屋建で東面に下屋を設け、小屋組はキングポストトラスとする。味噌の醸造に使用した大型倉庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010116"},{"id":"00010114","register_sub_id":"101","register_pk":"197947","name":"中村家住宅土蔵","kana":"なかむらけじゅうたくどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-2","lat":35.716813,"lng":139.940922,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0174","desc":"主屋と離れの間に接続し、東西棟で建つ。土蔵造二階建、切妻造桟瓦葺で、北面に下屋を設ける。北面と西面に戸口を設け、二階東面に庇付きの窓を穿つ。外壁は鉄板張で鉢巻を廻らせるが、もとは漆喰塗及び下見板張であった。屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010114"},{"id":"00010112","register_sub_id":"101","register_pk":"197945","name":"中村家住宅離れ","kana":"なかむらけじゅうたくはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-2","lat":35.71681,"lng":139.940812,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0172","desc":"主屋南後方に接続して建つ。木造二階建、寄棟造桟瓦葺で、下屋や窓庇を設け、外壁は簓子下見板張とする。内部は上下階とも座敷飾を備えた八畳主室と六畳を並べ、一階は舟底天井の応接間を付し、二階では南東面に縁と高欄を廻らせる。落ち着いた佇まいの離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010112"},{"id":"00010118","register_sub_id":"101","register_pk":"197951","name":"中村家住宅防空壕","kana":"なかむらけじゅうたくぼうくうごう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県市川市鬼越2-200-3","lat":35.716804,"lng":139.94066,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造、建築面積11㎡","structure_material":"鉄筋コンクリート造","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0178","desc":"主体部は南北三・六メートル東西三メートルで、上部をヴォールト状とし、北側の前室に鍵型の通路を設けて出入口とする。壁厚三〇センチメートルの鉄筋コンクリート造で、内部に建設時の支保工を兼ねた軸組を現す。個人住宅の庭園に築造された堅牢な防空壕。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010118"},{"id":"00010119","register_sub_id":"101","register_pk":"197952","name":"中村家住宅門及び石塀","kana":"なかむらけじゅうたくもんおよびいしべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-1","lat":35.71699061,"lng":139.94097532,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"大門 石造、間口3.5m 車門 石造、間口3.5m 石塀 石造、総延長29m、潜戸付","structure_material":"大門 石造","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0179","desc":"敷地北面を画す石造の門塀。西寄りに主屋玄関に通じる大門、事務所横に車門を構え、折曲がりに石塀をのばす。門は二箇所とも花崗岩製で江戸切仕上げの門柱を立て、石塀は房州石を布積とし、大門脇に潜戸を吊る。重厚で高い石塀が、旧家の表構えに風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010119"},{"id":"00010113","register_sub_id":"101","register_pk":"197946","name":"中村家住宅煉瓦蔵","kana":"なかむらけじゅうたくれんがぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-1","lat":35.717009,"lng":139.940752,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積20㎡","structure_material":"煉瓦造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0173","desc":"主屋西隣の敷地角地に南北棟で建つ。煉瓦造二階建、切妻造桟瓦葺で、東面を戸口とし、両妻面にアーチを付した庇窓を穿つ。壁は焼過煉瓦をイギリス積に積み、上部に雷紋風に飾るコーニスとペディメントを表す。鬼瓦の漆喰巻や高い棟積も、重厚な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010113"},{"id":"00006519","register_sub_id":"101","register_pk":"107502","name":"宮醤油店旧米蔵","kana":"みやしょうゆてんきゅうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26181,"lng":139.88562,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0076","desc":"脇蔵の南隣に建つ。桁行５間，梁間２間半，土蔵造２階建で，平入の切妻造，桟瓦葺。小屋組はトラスの形式をとる。西側に庇を張り出し，片開塗戸の出入口を設ける。もと米蔵であるが，現在は樽を置いて醤油蔵として使用。敷地内の醸造施設の変遷を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006519"},{"id":"00006521","register_sub_id":"101","register_pk":"107504","name":"宮醤油店西蔵","kana":"みやしょうゆてんにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26172182,"lng":139.88539588,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積115㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0078","desc":"主屋の南方に中庭を介して建つ。桁行１０間半，梁間３間，土蔵造２階建，東西棟の切妻造，桟瓦葺。小屋組は和小屋。内部には木樽８つを配し，天保５年創業時のものが６つ残る。規模の大きな醤油蔵で，妻壁を白漆喰塗とした外観が敷地西辺の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006521"},{"id":"00006520","register_sub_id":"101","register_pk":"107503","name":"宮醤油店東蔵","kana":"みやしょうゆてんひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26173,"lng":139.88559,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0077","desc":"旧米蔵の南隣に建つ。桁行５間，梁間２間半，土蔵造２階建で，平入の切妻造，桟瓦葺。小屋組はトラスの形式をとる。西側北端に出入口を設け，内部には木樽を９つ配し，諸味蔵として使用。外観は簡素なつくりであるが，中規模で，敷地の奥行を感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006520"},{"id":"00007017","register_sub_id":"101","register_pk":"107999","name":"吉野酒造石塀","kana":"よしのしゅぞういしべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.15387115,"lng":140.24875789,"geo_status":"db","era":"明治末期・昭和初期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"東塀 石造、延長27m 西塀 石造、延長25m","structure_material":"東塀 石造","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0113","desc":"屋敷地の南辺を限る石塀で、門の両袖塀に接続。東石塀は明治末期の建設で、延長２７ｍ、地元の房州石の切石８段積で、上に笠石を置く。西石塀は昭和初期の建設で、延長２５ｍ、大谷石の切石８段積で、上に笠石を置く。道路に沿い、特色ある景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007017"},{"id":"00007010","register_sub_id":"101","register_pk":"107992","name":"吉野酒造煙突","kana":"よしのしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154076,"lng":140.248657,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"煉瓦造、高さ16m","structure_material":"煉瓦造","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0106","desc":"南酒蔵の西面南寄りに位置する煉瓦造の煙突である。南酒蔵の西下屋の煉瓦造釜場の排煙に用いた。基底部は方１．２ｍで、高さは１６ｍ。煉瓦はイギリス積とする。四隅に山形鋼を添え、丸鋼をナット締めして補強している。酒造業らしいランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007010"},{"id":"00007011","register_sub_id":"101","register_pk":"107993","name":"吉野酒造北酒蔵","kana":"よしのしゅぞうきたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154415,"lng":140.248764,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積486㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0107","desc":"南酒蔵の北に建つ木造平屋建である。桁行２９ｍ梁間１６ｍの南北棟で、屋根は切妻造桟瓦葺とする。小屋組はキングポスト・トラス。切石の基礎上に建ち、外壁は真壁造白漆喰塗で、腰と妻壁を押縁下見板張とする。南酒蔵と並ぶ姿は醸造業らしい景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007011"},{"id":"00007013","register_sub_id":"101","register_pk":"107995","name":"吉野酒造北土蔵","kana":"よしのしゅぞうきたどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154278,"lng":140.248337,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0109","desc":"南蔵の北に建つ土蔵造２階建である。桁行９．１ｍ梁間５．５ｍの南北棟で、屋根は切妻造桟瓦葺とし、東面全面に瓦葺庇を付けて戸口１ヶ所を設ける。小屋組は和小屋。切石基礎上に建ち、外壁は白漆喰塗で、腰を海鼠壁とするが、下部はモルタル塗としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007013"},{"id":"00007014","register_sub_id":"101","register_pk":"107996","name":"吉野酒造旧馬屋","kana":"よしのしゅぞうきゅううまや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.1545385,"lng":140.2483165,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0110","desc":"屋敷地の北西寄りに建つ木造平屋建である。桁行１１ｍ梁間５．５ｍの東西棟で、切妻造桟瓦葺とし、南正面に鉄板葺庇が付く。内部は奥から３．０ｍ位置で仕切り、桁行に３等分して馬房とする。外壁は真壁造漆喰塗で、腰と妻を押縁下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007014"},{"id":"00007008","register_sub_id":"101","register_pk":"107990","name":"吉野酒造店舗兼主屋","kana":"よしのしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154015,"lng":140.248505,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積299㎡","structure_material":"木造2階一部平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0104","desc":"道路北側の敷地南西寄りに南面して建つ木造２階建で、背面に平屋を突出する。屋根は寄棟造桟瓦葺で、瓦葺庇がまわり、正面中央に式台、その東に入母屋屋根の玄関がある。内部は東に土間、西に８畳座敷など４室を配す。出桁造の深い２階の軒が重厚な外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007008"},{"id":"00007015","register_sub_id":"101","register_pk":"107997","name":"吉野酒造松尾神社","kana":"よしのしゅぞうまつおじんじゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.15485569,"lng":140.24887331,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積10㎡、宮殿付","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0111","desc":"北酒蔵の北東に位置する。桁行３．９ｍ梁間２．１ｍの南北棟で南面する。屋根は入母屋造桟瓦葺で、正面軒は扇垂木、他は平行垂木である。正面を虹梁や蟇股で飾る。外壁は竪板壁。内部は奥から１．３ｍで床を上げ、虹梁を架けて内陣としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007015"},{"id":"00007012","register_sub_id":"101","register_pk":"107994","name":"吉野酒造南蔵","kana":"よしのしゅぞうみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.15415,"lng":140.2483185,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0108","desc":"主屋の北西に建つ木造２階建である。桁行９．１ｍ梁間６．４ｍの南北棟で、屋根は切妻造桟瓦葺とする。軒は疎垂木で、小屋組は和小屋。切石基礎上に建ち、外壁は真壁造漆喰塗で、庇下部を竪羽目板張、庇上部と妻を押縁下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007012"},{"id":"00007009","register_sub_id":"101","register_pk":"107991","name":"吉野酒造南酒蔵","kana":"よしのしゅぞうみなみさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154099,"lng":140.24881,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積788㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0105","desc":"主屋の東方に建つ木造２階建である。桁行２９ｍ梁間１０ｍの切妻造南北棟の四周に、４．５ｍから５．５ｍ幅の広い下屋を巡らせている。屋根は桟瓦葺。外壁は真壁造白漆喰塗。小屋組は梁を重ねた和小屋である。広い下屋が特徴的な外観を成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007009"},{"id":"00007016","register_sub_id":"101","register_pk":"107998","name":"吉野酒造門","kana":"よしのしゅぞうもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.15385623,"lng":140.24868915,"geo_status":"db","era":"昭和30頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"石造、間口4.0m、袖塀付","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0112","desc":"屋敷地南辺の中央に開く門。門柱は御影石の切石積で６０ｃｍ角、高さ２．４ｍで、頂部の笠石は各面の中央を縦溝で飾る。門口４．０ｍで両開の木製門扉を吊る。袖塀は切石積で壁面上部に方形の壁龕を並べ、笠石を載せ、西袖塀に潜戸が付く。敷地の正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007016"},{"id":"00003847","register_sub_id":"101","register_pk":"104837","name":"石川酒造新蔵","kana":"いしかわしゅぞうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.719269,"lng":139.332932,"geo_status":"db","era":"明治31／明治33増築","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積489㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0166","desc":"本蔵の西側，街路沿いにあり，棟札から建築年代が判る。桁行３５ｍ，梁間１３．５ｍの細長い２階建の土蔵で，屋根は一方切妻造，他方入母屋造で，置屋根式の鉄板葺とする。外壁は漆喰塗で，腰を板で覆う。本蔵とともに造り酒屋らしい景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003847"},{"id":"00003846","register_sub_id":"101","register_pk":"104836","name":"石川酒造本蔵","kana":"いしかわしゅぞうほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.71934394,"lng":139.33261097,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積734㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0165","desc":"桁行３２ｍ，梁間２３ｍ，２階建の酒造蔵。桟瓦葺の屋根は南北棟で南面切妻造，北面入母屋造，外壁は漆喰塗，妻面に観音扉付の窓を整然と配し，内部は柱が林立した宏壮な空間である。棟札から建築年代が明確。地域景観の中で，際だった存在感を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003846"},{"id":"00003848","register_sub_id":"101","register_pk":"104838","name":"石川酒造向蔵","kana":"いしかわしゅぞうむかいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.718731,"lng":139.332016,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積577㎡、東面付","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0167","desc":"敷地西寄りにあり，棟札から建築年代が判る。南北棟の切妻造，桟瓦葺，桁行３５ｍ，梁間１３．５ｍで，２階建の土蔵造である。扉口のある東面に下屋庇，窓に小庇を付け，開口部は丁寧に鳥居型に縁取る。もと石炭小屋で，明治期の屋敷構成の有様を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003848"},{"id":"00011273","register_sub_id":"101","register_pk":"209109","name":"青梅織物工業協同組合旧織物加工工場","kana":"おうめおりものこうぎょうきょうどうくみあいきゅうおりものかこうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市西分町三丁目123他","lat":35.7881,"lng":139.265465,"geo_status":"db","era":"昭和10頃／平成9・同18改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積715㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0371","desc":"原糸を織機にかける前段階のサイジングのために建てられた工場。建築面積七一五平方メートルの大規模木造平屋建で、キングポストトラスによる四連の鉄板葺鋸屋根を連ね、北側採光とする。長手方向の壁面は下見板張。地域に残るなかでも最大規模の鋸屋根工場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011273"},{"id":"00011274","register_sub_id":"101","register_pk":"209110","name":"青梅織物工業協同組合旧発券倉庫","kana":"おうめおりものこうぎょうきょうどうくみあいきゅうはっけんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市西分町三丁目127-6他","lat":35.788404,"lng":139.266366,"geo_status":"db","era":"昭和前期／平成12改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造2階建、瓦葺、建築面積159㎡","structure_material":"石造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0372","desc":"布地等を保管していた石造倉庫。内部は一・二階とも一室とし、小屋はトラス組。屋根は切妻造桟瓦葺とする。西面に扉口を開き、その二階と南北妻面一・二階に両開き金属扉の窓を設ける。大谷石積の外観で、繊維業で栄えた往時の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011274"},{"id":"00009727","register_sub_id":"101","register_pk":"195556","name":"田村酒造石垣","kana":"たむらしゅぞういしがき","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.74145029,"lng":139.32094568,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造、総延長145m","structure_material":"石造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0312","desc":"敷地東側の玉川上水に面して築かれた石垣。総延長一四五メートルで、敷地東面から南面東寄りまで矩折れにのび、東面の中央部に出入口を設ける。河原石を腰高まで丁寧に積み上げる構造で、天端石をやや迫り出す。玉川上水に面した酒造場の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009727"},{"id":"00009726","register_sub_id":"101","register_pk":"195555","name":"田村酒造旧水車小屋及び脇蔵","kana":"たむらしゅぞうきゅうすいしゃごやおよびわきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.74135396,"lng":139.32074921,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造及び土蔵造平屋建、鉄板葺、建築面積104㎡","structure_material":"木造及び土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0311","desc":"敷地東面中央、玉川上水からの導水路脇に建つ。北半を木造で四間四方の水車小屋、南半を土蔵造の脇蔵とし、全体に切妻造鉄板葺の屋根をかける。いずれも外壁の腰を板壁とし、小屋組はキングポストトラスとする。水車による動力で精米を行った様子を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009726"},{"id":"00009723","register_sub_id":"101","register_pk":"195552","name":"田村酒造酒造蔵","kana":"たむらしゅぞうしゅぞうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.7418013,"lng":139.32006392,"geo_status":"db","era":"文政5頃／大正7・大正11増築","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積912㎡、煙突付","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0308","desc":"玉川上水沿いの敷地北西に建つ酒造場の中心建物で、南より切妻造の本蔵、中蔵、新蔵が連立し、本蔵南に煉瓦煙突が建つ。外壁漆喰塗で腰を下見板張とし、庇付窓を規則的に並べる。煙突は八角形平面で帯鉄補強する。酒造蔵の拡張過程を良好に伝える大規模土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009723"},{"id":"00009725","register_sub_id":"101","register_pk":"195554","name":"田村酒造雑蔵","kana":"たむらしゅぞうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.74129448,"lng":139.32008058,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0310","desc":"前蔵の南に隣接して南北棟で建つ。土蔵造二階建、桁行一〇・八メートル梁間五・三メートル、切妻造、置屋根式の桟瓦葺で、二箇所に入口を設け、小屋は和小屋を組む。江戸末期の酒造場の様子を伝える土蔵で、前蔵と棟方向を違え、敷地景観に変化を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009725"},{"id":"00009724","register_sub_id":"101","register_pk":"195553","name":"田村酒造前蔵","kana":"たむらしゅぞうまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.74137776,"lng":139.32008534,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0309","desc":"敷地南西に東西棟で建つ旧米蔵。土蔵造二階建、桁行六・三メートル梁間四・五メートル、切妻造妻入、置屋根の桟瓦葺で、二階の東正面に、窓と両開土扉を設ける。外壁は腰高に簓子下見板を張り、内部は登り梁併用の架構とする。酒造場草創期の姿を留める土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009724"},{"id":"00011903","register_sub_id":"101","register_pk":"211068","name":"旧内野醤油店稲荷社","kana":"きゅううちのしょうゆてんいなりしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪602","lat":35.247736,"lng":139.14238,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積0.29㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0242","desc":"主屋北面の庭の石積基壇上に建つ一間社。正面入母屋造、軒唐破風付で背面寄棟造とする。正面の庇の虹梁形頭貫に華やかな絵様を彫り、獅子鼻を付す。組物は出組だが正面では枠肘木を重ねて複雑に組み上げ、軒は二軒繁垂木とする。小社ながら精緻な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011903"},{"id":"00011904","register_sub_id":"101","register_pk":"211069","name":"旧内野醤油店表塀","kana":"きゅううちのしょうゆてんおもてべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪598他","lat":35.247585,"lng":139.142239,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造、鉄板葺、延長4.9m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0243","desc":"店舗兼主屋の西にのびて新座敷前庭を画す塀で、店舗寄りに潜戸を開く。布石積基礎上の土台に柱を立て、腕木で鉄板葺の板軒を受ける。壁は漆喰塗で各間に竪格子の欄間をあけ、腰は表側は竪板を大和張とし、庭側は竪板張目板打とする。表構えに風情を添える塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011904"},{"id":"00011902","register_sub_id":"101","register_pk":"211067","name":"旧内野醤油店工場","kana":"きゅううちのしょうゆてんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪600他","lat":35.247851,"lng":139.14238,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鉄板葺、建築面積354㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0241","desc":"敷地の北西側に位置し、東西棟で南面に広い下屋を持つ主体部と、南北棟で敷地西辺を画す建物を矩折れに繋ぐ。いずれも木造で小屋はキングポストトラスを組む。外壁モルタル塗で要所に窓を配する。規模の大きな工場建築で、醸造施設としての構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011902"},{"id":"00011901","register_sub_id":"101","register_pk":"211066","name":"旧内野醤油店穀蔵","kana":"きゅううちのしょうゆてんこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪604-イ他","lat":35.247647,"lng":139.14253,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、鉄板葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0240","desc":"敷地東面に南北棟で建ち、桁行一〇メートル梁間四・五メートル、切妻造鉄板葺である。西面に戸口を開き広い下屋を設け、窓二所を穿つ。外壁モルタル塗で鉢巻を廻らし、腰を石張とする。内部は一室でキングポストトラスを組む。醸造所の一角を占める大型倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011901"},{"id":"00011897","register_sub_id":"101","register_pk":"211062","name":"旧内野醤油店店舗兼主屋","kana":"きゅううちのしょうゆてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪600他","lat":35.247642,"lng":139.142311,"geo_status":"db","era":"明治36年","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造2階建、鉄板葺及び瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0236","desc":"旧東海道に南面し、店舗部は土蔵造として正面に下屋を設け軒蛇腹を廻らす。外壁は腰を石張、上方を海鼠壁とし、東端の店舗入口にアーチをつくる。内部は二階を中心に上質な座敷をもつ。正面窓廻りに銅板を張り、袖壁を設けるなど防火も講じ、重厚な趣をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011897"},{"id":"00011900","register_sub_id":"101","register_pk":"211065","name":"旧内野醤油店文庫蔵","kana":"きゅううちのしょうゆてんぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪600","lat":35.24769,"lng":139.142305,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積21㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0239","desc":"店舗兼主屋の北側に南北棟で建つ。桁行五・五メートル梁間三・九メートル、土蔵造二階建、切妻造鉄板葺で、外壁モルタル塗で鉢巻を廻らし、二階東面に窓を設ける。一階南妻面の戸口に重厚な土戸を開き、主屋廊下と連絡する。丁寧な施工になる内蔵形式の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011900"},{"id":"00011899","register_sub_id":"101","register_pk":"211064","name":"旧内野醤油店店蔵","kana":"きゅううちのしょうゆてんみせぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪602他","lat":35.247582,"lng":139.142429,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積28㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0238","desc":"店舗兼主屋の東に東西棟で建つ。桁行七・一メートル梁間三・九メートルの土蔵造で、外壁モルタル塗で鉢巻を廻らし、正面の腰を洗出し仕上とする。北面の戸口に庇を付し、南面二階の縦長窓に掛子塗戸を両開とする。店舗兼主屋と共に重厚な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011899"},{"id":"00004217","register_sub_id":"101","register_pk":"105207","name":"旧横浜ゴム平塚製造所記念館","kana":"きゅうよこはまごむひらつかせいぞうしょきねんかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県平塚市浅間町1-1","lat":35.3338067,"lng":139.34768338,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"14 － 0086","desc":"日英合弁の日本爆発物製造株式会社の支配人室として建設。木造平屋建で，ヴェランダやベイウィンドーなどが特徴。屋根は鉄板葺で，南東に塔屋を頂き，外壁はドイツ下見板張とする。創建当初の姿を良く残し，小規模ながら明治期の木造洋風建築の佳品と言える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004217"},{"id":"00001250","register_sub_id":"101","register_pk":"102240","name":"昭和電工川崎工場本事務所","kana":"しょうわでんこうかわさきこうじょうほんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県川崎市川崎区扇町28-1","lat":35.50493206,"lng":139.72303959,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積765㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"14 － 0027","desc":"東京湾埋立株式会社が造成した扇町埋立地の北西部に位置する。ＲＣ造２階建、陸屋根の事務所建築で、正面中央に車寄を低平に突き出し、縦長の窓を並べた簡潔な外観意匠をとる。昭和初期京浜工業地帯における工場事務所建築の代表的事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001250"},{"id":"00015161","register_sub_id":"101","register_pk":"530585","name":"北條鉄工クレーンヤード","kana":"ほうじょうてっこうくれーんやーど","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目35-3他","lat":35.51291389,"lng":139.71188889,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨造平屋建、セメントスレート葺、建築面積1，704㎡","structure_material":"鉄骨造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0357","desc":"道路に面し、事務所及び工場群に囲まれた、重量鉄骨の製作組立などを行う工場。山形鋼をリベット接合した箱形ラチス梁及び柱を組合せ大空間をつくり、東・南面を波板鉄板張、内部に天井走行クレーンを三列収容する。工場景観の要をなす地域のランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015161"},{"id":"00015159","register_sub_id":"101","register_pk":"530583","name":"北條鉄工原寸工場","kana":"ほうじょうてっこうげんすんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目35-1他","lat":35.51316944,"lng":139.71193889,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄骨造3階建、セメントスレート葺、建築面積326㎡","structure_material":"鉄骨造3階建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0355","desc":"事務所奥に接続し、鉄骨の溶接及び原寸図を作成した作業棟。桁行三五メートルの鉄骨造三階建で、一階は吹放ちの溶接工場、二・三階は四周に水平窓を廻らし、採光に優れた無柱空間で、チョークなどで描く原寸図用の床が残り、昭和期の鉄骨製図を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015159"},{"id":"00015162","register_sub_id":"101","register_pk":"530586","name":"北條鉄工材料置場","kana":"ほうじょうてっこうざいりょうおきば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目34","lat":35.51343611,"lng":139.71179167,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄骨造平屋建、セメントスレート葺、建築面積820㎡","structure_material":"鉄骨造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0358","desc":"事務所の北に位置する材料保管所。鉄骨造平屋建切妻造大波セメントスレート葺。ビルトＨ形鋼と高力ボルト接合がつくり出す大空間を波板鉄板で囲い、吹放しの西妻面から天井走行クレーンの桁を張り出す独特の外観。事業の発展と工場建築の技術的変遷を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015162"},{"id":"00015158","register_sub_id":"101","register_pk":"530582","name":"北條鉄工事務所","kana":"ほうじょうてっこうじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目35-1他","lat":35.51310278,"lng":139.71162222,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄骨造及び鉄骨鉄筋コンクリート造3階建、鉄板葺、建築面積123㎡","structure_material":"鉄骨造及び鉄骨鉄筋コンクリート造3階建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0354","desc":"京浜工業地帯の一角に建つ鉄工所の事務所。一階は鉄骨鉄筋コンクリート造、二・三階は鉄骨造とし、三階の門型ラーメンに戦後隆盛した丸鋼のラチス梁を用いる。躯体は鋼材を自在に組合せ、外壁はモルタル洗出仕上とする。高度経済成長期の工場事務所の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015158"},{"id":"00015160","register_sub_id":"101","register_pk":"530584","name":"北條鉄工旧シャーリング・製缶及びロール工場","kana":"ほうじょうてっこうシャーリング・せいかんおよびロールこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目35-3他","lat":35.513025,"lng":139.71216944,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄骨造平屋建、セメントスレート葺、建築面積664㎡","structure_material":"鉄骨造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0356","desc":"敷地東面に建つ鉄骨造の作業棟。切妻造セメントスレート葺東西棟の北に南北棟を接続。外壁波板鉄板張。かつて南半西が鉄板を切断するシャーリング工場、東が溶接を行う製缶工場、北半が曲げ加工をするロール工場とした。巨大な両開扉を吊る大規模工場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015160"},{"id":"00007206","register_sub_id":"101","register_pk":"108188","name":"岩乃原葡萄園第一號石蔵","kana":"いわのはらぶどうえんだいいちごういしぐら","category":"産業2次","subcategory":"その他工作物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県上越市大字北方字上ノ原1223","lat":37.088078,"lng":138.35083,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"石造、面積93㎡、冷気隧道付","structure_material":"石造","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0307","desc":"斜面を開削し、凝灰岩切石で建設された矩形平面の石蔵で、面積９３㎡。当初２層であったが、下層が埋められ、屋根架構も取り外され、上部にＲＣ造２階建が載る。内部の山側には冷気隧道の入口アーチが開き、地下水の冷気により、醸造石蔵内の温湿度を調整する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007206"},{"id":"00013982","register_sub_id":"101","register_pk":"508242","name":"角屋社屋別館","kana":"かどやしゃおくべっかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県十日町市本町二丁目11他","lat":37.13073889,"lng":138.76039167,"geo_status":"db","era":"明治41年／昭和45年移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積206㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0563","desc":"本町通に東面する店舗で、二階建切妻造妻入である。正面妻は梁と貫を現しで飾り、側面の軒はセガイ造とする。一階は北側の通り土間に大戸が残る。吹抜けのチャノマは積雪期には高窓から採光した。二階正面側は客用座敷とする。豪雪地の町家の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013982"},{"id":"00005825","register_sub_id":"101","register_pk":"106811","name":"機那サフラン酒製造本舗土蔵","kana":"きなさふらんしゅせいぞうほんぽどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋4-6-33","lat":37.415966,"lng":138.84061239,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0237","desc":"サフラン酒の醸造で財をなした吉沢仁太郎が建設。桁行５間，梁間３間規模，切妻造，桟瓦葺の土蔵で，基礎は石積み，腰を海鼠壁とする。軒廻り，開口部の楣部と塗戸に，鳳凰，麒麟，恵比須，大黒や十二支などの極彩色鏝絵を施す。左官は地元の河上伊吉と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005825"},{"id":"00013529","register_sub_id":"101","register_pk":"504893","name":"旧機那サフラン酒製造本舗石垣","kana":"きゅうきなさふらんしゅせいぞうほんぽいしがき","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1他","lat":37.41579722,"lng":138.84070278,"geo_status":"db","era":"明治後期／大正11年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、総延長122m","structure_material":"石造","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0542","desc":"敷地の東面、南北二箇所を出入口として開けた総延長一〇四メートルに渡る石垣と、敷地内の築山際に築かれた石垣からなる。東面の石垣は自然石を亀甲形に整形して六段に積み、上部に葛石を載せる。広大な工場の敷地を区切り、前面道路からの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013529"},{"id":"00013522","register_sub_id":"101","register_pk":"504886","name":"旧機那サフラン酒製造本舗衣装蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1","lat":37.41570278,"lng":138.84051111,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0535","desc":"主屋前方南面に接続して建つ。東西棟で二階建切妻造桟瓦葺。内部は一、二階とも一室。正面妻の鉢巻に唐草やサフランの花弁、戸口や窓の扉内側に龍や動物等を色鮮やかな鏝絵で飾る。「鏝絵蔵」として地域に親しまれる土蔵同様、当施設を代表する建物の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013522"},{"id":"00013526","register_sub_id":"101","register_pk":"504890","name":"旧機那サフラン酒製造本舗一号倉","kana":"きゅうきなさふらんしゅせいぞうほんぽいちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2273-1他","lat":37.41621111,"lng":138.8405,"geo_status":"db","era":"明治中期／大正15年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0539","desc":"敷地の北寄りに独立して建つ。二階建切妻造桟瓦葺で東西棟とし西に下屋を差掛け戸口とする。漆喰仕上で腰を鉄板で養生し東妻には吉の字をかたどる。一、二階とも一室で、小屋は桁行中央間に梁を渡す。当地で醸造を開始して以来の遺構で、北辺の景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013526"},{"id":"00013520","register_sub_id":"101","register_pk":"504884","name":"旧機那サフラン酒製造本舗主屋","kana":"きゅうきなさふらんしゅせいぞうほんぽおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1他","lat":37.41585556,"lng":138.84045,"geo_status":"db","era":"明治中期／大正2年増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積469㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0533","desc":"長岡市街南方にあるサフラン酒造会社の主屋。東面し、当初の玄関と増築された主体部からなる。主体部は二階建入母屋造桟瓦葺で表に二列六室、背面に座敷及び三室を有する広大なもの。切妻造の重厚な玄関にはサフラン酒の看板を掲げて表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013520"},{"id":"00013527","register_sub_id":"101","register_pk":"504891","name":"旧機那サフラン酒製造本舗米蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目1026","lat":37.41638333,"lng":138.84039167,"geo_status":"db","era":"昭和前期／令和2年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積150㎡","structure_material":"土蔵造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0540","desc":"敷地の北方に独立して建つ。平屋建切妻造桟瓦葺で東西棟とし南に下屋を張出し戸口をつくる。下屋上部を二階窓高さで海鼠壁とし化粧とするほか東妻に漆喰で吉の字を飾る。。内部は一室で土間床とし、キングポストトラスの小屋組を現す。敷地北端の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013527"},{"id":"00013528","register_sub_id":"101","register_pk":"504892","name":"旧機那サフラン酒製造本舗シチレン蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽしちれんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目169-1","lat":37.41530278,"lng":138.83997778,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、鉄板葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0541","desc":"敷地の南西隅に独立して建つ。東西棟で二階建切妻造の鉄板葺置屋根を前室まで葺き降ろす。腰を鉄板で養生し上部は漆喰塗。北を戸口とし内部も鉄板で覆う。当蔵で花火を製造したとの伝聞があり、湿気対策とも思われるが当時の用途は不詳。敷地の一角を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013528"},{"id":"00013524","register_sub_id":"101","register_pk":"504888","name":"旧機那サフラン酒製造本舗醸造蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目1027他","lat":37.41597222,"lng":138.84018333,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積133㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0537","desc":"主屋背面に主屋と接続して建つ。東西棟で二階建切妻造桟瓦葺とし、東面に下屋を設けて戸口を建てる。内部に四本の独立柱が立ち、直接小屋梁を受ける。一階は土間を挟んで北に資材室、南に製品置場、西を製造タンクの倉庫とした。薬酒製造に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013524"},{"id":"00013523","register_sub_id":"101","register_pk":"504887","name":"旧機那サフラン酒製造本舗調整蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽちょうせいぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1他","lat":37.41601111,"lng":138.84041944,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積159㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0536","desc":"主屋北に接続して建つ。南北棟で二階建切妻造桟瓦葺。北に下屋を設け戸口とする。小屋は梁間六間にクイーンポストトラスを掛け渡す。一階は中廊下に西を生薬貯蔵室、調製場、東を瓶詰場等とし二階は検査室や資材庫等とする。薬酒製造に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013523"},{"id":"00013525","register_sub_id":"101","register_pk":"504889","name":"旧機那サフラン酒製造本舗道具蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目1027他","lat":37.41612778,"lng":138.84022222,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積219㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0538","desc":"主屋背面に醸造蔵と並んで建つ。南北棟で桁行一〇間梁間四間半と比較的規模が大きく、二階建切妻造桟瓦葺。東に大振りな下屋を張り出し戸口を建てる。内部は一、二階とも一室で、独立柱が六本立ち直接小屋梁を受け母屋を渡す。敷地西方の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013525"},{"id":"00013521","register_sub_id":"101","register_pk":"504885","name":"旧機那サフラン酒製造本舗離れ座敷","kana":"きゅうきなさふらんしゅせいぞうほんぽはなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1他","lat":37.41569444,"lng":138.84029722,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0534","desc":"主屋の南奥に接続して建つ。二階建入母屋造桟瓦葺で東面に唐破風玄関をつけ、三方に庇を廻す豪壮な外観。二階のたちが高く、庭側二面をガラス戸で開放する。一階は畳廊下を通して大座敷、次の間を並べ、二階は一二畳を三室とる。接遇の場として偉容を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013521"},{"id":"00011103","register_sub_id":"101","register_pk":"205210","name":"旧野澤豊五郎醸造下蔵","kana":"きゅうのざわとよごろうじょうぞうしたぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県村上市塩谷字高泉寺脇1146","lat":38.159948,"lng":139.418165,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0445","desc":"醤油蔵の東に接続して建つ味噌の仕込蔵。木造平屋建、切妻造、桟瓦葺の平入で醤油蔵側に出入口を開く。外壁は竪板張で、平側上部には窓を並べる。内部は前蔵同様に屋根まで伸びる柱を桁行方向に二列並べ胴差で固める。醸造蔵の統一した景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011103"},{"id":"00011101","register_sub_id":"101","register_pk":"205208","name":"旧野澤豊五郎醸造醤油蔵","kana":"きゅうのざわとよごろうじょうぞうしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市塩谷字高泉寺脇1146","lat":38.160009,"lng":139.417936,"geo_status":"db","era":"明治37頃／大正6増築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積440㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0443","desc":"塩谷の集落を貫く通りから少し東に入った通りに面して建つ醤油蔵。木造平屋建、切妻造、桟瓦葺で、通りに面して梁間の大きな下見板張の妻面を見せる。内部は広い土間の大空間で、曲がり材の梁を用いた和小屋を現しとする。当地域における醸造業の営みを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011101"},{"id":"00011102","register_sub_id":"101","register_pk":"205209","name":"旧野澤豊五郎醸造前蔵","kana":"きゅうのざわとよごろうじょうぞうまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市塩谷字高泉寺脇1146","lat":38.159838,"lng":139.417905,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積150㎡","structure_material":"土蔵造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0444","desc":"醤油蔵の南に接続して建つ醤油の仕込蔵。土蔵造平屋建、切妻造、桟瓦葺妻入で外壁を漆喰塗とし、平側上部には窓を各四所開け、南妻面にマルマスの紋を付す。内部は屋根まで伸びる柱を桁行方向に二列並べ胴差で固め、壁寄りに樽を並べ中央を通路とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011102"},{"id":"00014352","register_sub_id":"101","register_pk":"511341","name":"旧早川タンス店（越後高田樂市樂座）店舗","kana":"きゅうはやかわたんすてん（えちごたかだらくいちらくざ）てんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"新潟県","address":"新潟県上越市東本町二丁目46-1他","lat":37.11955278,"lng":138.25022778,"geo_status":"db","era":"昭和22年","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積163㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0575","desc":"城下町高田の材木屋が集まった町にある箪笥店。二階建、切妻造平入で軒を出桁造、一階に雁木が付く。内部は前土間とミセを設け、中央に土間と廊下を通し、両脇に居室。二階表側は２２坪もの広い加工場、箪笥を上げ下げした吹抜等、歴史的景観を伝える箪笥店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014352"},{"id":"00007205","register_sub_id":"101","register_pk":"108187","name":"玉川堂雁木","kana":"ぎょくせんどうがんぎ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県燕市燕字西郷3064-1他","lat":37.665005,"lng":138.92952,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0306","desc":"通りに東面して建つ。桁行９．２ｍ梁間１．３ｍの建物で、招屋根の桟瓦葺とする。道路側は礎石上に柱を建て軒桁を支持。店舗側は、礎石上に土台を設け、柱を建てて鴨居と長押で固め、棟木を載せる。壁は竪板壁、小壁は漆喰仕上げ。伝統的な街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007205"},{"id":"00007204","register_sub_id":"101","register_pk":"108186","name":"玉川堂鍛金場","kana":"ぎょくせんどうたんきんじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県燕市燕字西郷3064-1他","lat":37.66503555,"lng":138.92921853,"geo_status":"db","era":"大正期／昭和前期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積319㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0305","desc":"主屋の西方に位置する。切妻造桟瓦葺で、桁行１２ｍ梁間７．３ｍの木造平屋建。ガラス窓を大きく取り、採光に配慮。内部は北半部が土間で火炉などを備え、南半部には畳を敷き作業場とし、西方の増築部では仕上げ工程を行う。伝統産業の作業空間をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007204"},{"id":"00007202","register_sub_id":"101","register_pk":"108184","name":"玉川堂店舗","kana":"ぎょくせんどうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県燕市燕字西郷3064-1他","lat":37.665016,"lng":138.929413,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階一部平屋建、瓦葺、建築面積128㎡","structure_material":"木造2階一部平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0303","desc":"通り西側に占める短冊状の敷地前寄りに建つ。桁行８．５ｍ梁間３．６ｍ規模の木造２階建の背面に、奥行８．２ｍの平屋建を直角に付ける。内部は北側に通り土間を設け、南に和室を配し、正面南寄りにはもとは土縁と板縁を設けた。老舗の接客空間を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007202"},{"id":"00007203","register_sub_id":"101","register_pk":"108185","name":"玉川堂土蔵","kana":"ぎょくせんどうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県燕市燕字西郷3064-1他","lat":37.66495723,"lng":138.9294009,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0304","desc":"店舗の西南に軸線を違え、北を正面に建ち、蔵前を介して、店舗や主屋と繋がる。桁行５．５ｍ梁間３．６ｍ規模の土蔵造２階建、切妻造桟瓦葺の置屋根とする。外壁は白漆喰仕上げとし、掛子塗戸を出入口や窓に吊り込む。内部は壁板張で、什器等を収蔵する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007203"},{"id":"00009444","register_sub_id":"101","register_pk":"194237","name":"越のむらさき主屋","kana":"こしのむらさきしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋3-2210他","lat":37.41718145,"lng":138.84243945,"geo_status":"db","era":"明治10年頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積127㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0376","desc":"交差点に北面して建つ。木造二階建、切妻造妻入桟瓦葺で、正面に下屋を設ける。外壁は簓子下見板張で、下階出入口や上階窓にガラス戸をたてる。内部は西側の事務所の天井を吹抜けとし、東側には応接室などを配する。当地方の伝統的な住宅形態を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009444"},{"id":"00009445","register_sub_id":"101","register_pk":"194238","name":"越のむらさき土蔵","kana":"こしのむらさきどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋3-2210他","lat":37.41715052,"lng":138.84250845,"geo_status":"db","era":"明治10年","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0377","desc":"主屋の南東部に張出して付属する土蔵。土蔵造二階建、桁行四・三メートル梁間三・四メートル、切妻造、置屋根式の桟瓦葺である。外壁は漆喰塗で腰を簓子下見板張とし、窓枠や鉢巻を黒漆喰で仕上げる。醸造業が盛んな摂田屋の歴史を伝える醤油醸造所の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009445"},{"id":"00015427","register_sub_id":"101","register_pk":"533442","name":"笹祝酒造事務所棟","kana":"ささいわいしゅぞうじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西蒲区松野尾字宮林3246他","lat":37.79722222,"lng":138.87122778,"geo_status":"db","era":"明治34年頃／明治後期・大正8年増築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積285㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0604","desc":"主屋の北隣で、街道に西面して建つ事務所棟。木造二階建桟瓦葺で通り沿いに大きな切妻と半切妻の妻面を見せて下屋を付す。一階に広い店舗、検査室、事務室などを配し、コ字形平面を呈する二階は座敷を並べ杜氏部屋などにする。酒造場の雄大な表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015427"},{"id":"00015428","register_sub_id":"101","register_pk":"533443","name":"笹祝酒造煉瓦煙突","kana":"ささいわいしゅぞうれんがえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西蒲区松野尾字宮林3246","lat":37.79713611,"lng":138.87175278,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、高さ12m","structure_material":"煉瓦造","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0605","desc":"事務所棟の東方に建つ高さ約一二メートルの煉瓦造の煙突。六角形平面の躯体をイギリス積とし、上部の径を逓減させる。下部に迫出しを設けて雁木を付し、頂部にも蛇腹を一段を設けてアクセントとする。酒造場の特徴をよく示し、地域のランドマークとなる煙突。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015428"},{"id":"00013531","register_sub_id":"101","register_pk":"504898","name":"新日本電工株式会社妙高工場赤煉瓦建屋","kana":"しんにっぽんでんこうかぶしきがいしゃみょうこうこうじょうあかれんがたてや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県妙高市大字田口字南258-4","lat":36.87426389,"lng":138.21302778,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積376㎡","structure_material":"煉瓦造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0544","desc":"妙高高原駅に近接する敷地に南面して建つ元カーバイト工場。桁行三三メートル、梁間九・六メートルの煉瓦造平屋建一部二階建で、正面妻壁に東京電化工業時代の社章を付ける。関川水系の電源開発に伴い上越で発展した電気化学工業の歴史を物語る貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013531"},{"id":"00014348","register_sub_id":"101","register_pk":"511337","name":"高野醤油味噌醸造店店舗兼主屋","kana":"たかのしょうゆみそじょうぞうてんてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市北本町一丁目48-3","lat":37.11979722,"lng":138.244,"geo_status":"db","era":"昭和7年／同３０年代増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造２階建、鉄板葺、建築面積223㎡","structure_material":"木造２階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0571","desc":"雁木が連なる高田市街の醸造業店舗兼住居。雁木を付す東正面一階はガラス障子を建込む。内部は前土間から奥へ通り土間とし、北の茶の間は吹抜け、土間南を作業室とする。背後の井戸まで突出した屋根を土蔵の蔵前とする。雪国の伝統的な市街地建築の姿を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014348"},{"id":"00014349","register_sub_id":"101","register_pk":"511338","name":"高野醤油味噌醸造店土蔵及び作業場","kana":"たかのしょうゆみそじょうぞうてんどぞうおよびさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市北本町一丁目48-3","lat":37.11979167,"lng":138.24380556,"geo_status":"db","era":"明治39年／昭和７年頃増築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積103㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0572","desc":"醸造店主屋の背後、井戸流し場に接続する家財蔵。鞘を掛けて北側を作業場通路とした内蔵形式で、西の増築部は窯場やムロなど醸造用作業場とする。土蔵の小屋組は曲材の梁で地棟を受け登梁を掛ける。戸口は煙返しと塗戸を黒漆喰で飾り、漆塗の格子戸を建てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014349"},{"id":"00005996","register_sub_id":"101","register_pk":"106981","name":"高橋酒造煙突","kana":"たかはししゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市地蔵1-8-2","lat":37.45523262,"lng":138.86528642,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造、高さ20m","structure_material":"煉瓦造","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0236","desc":"新蔵主体部の東南隅近くに独立して建つ。１辺１．２ｍの六角形平面をもつ煉瓦造煙突で，高さは約２０ｍ。頂部近くには煉瓦を持ち出して装飾的なリングを廻し，出隅には役物の鼻黒煉瓦を用いるなど丁寧なつくりで，地域のシンボルにもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005996"},{"id":"00005952","register_sub_id":"101","register_pk":"106937","name":"高橋酒造新蔵","kana":"たかはししゅぞうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市地蔵1-8-2","lat":37.455418,"lng":138.865128,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木骨煉瓦造3階建、瓦葺、建築面積1278㎡","structure_material":"木骨煉瓦造3階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0235","desc":"主体部は桁行３０ｍ，梁間１８ｍ規模，東西棟，切妻造，桟瓦葺，木骨煉瓦造３階建の酒蔵で，東面に越屋根を上げた釜場が取り付き，周囲に下屋を回した大規模で複雑なつくり。長大でたちの高い赤煉瓦の外観は栖吉川左岸にあって際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005952"},{"id":"00011104","register_sub_id":"101","register_pk":"205211","name":"野澤食品工業株式会社店舗兼主屋","kana":"のざわしょくひんこうぎょうかぶしきがいしゃてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市塩谷字上町1227","lat":38.156933,"lng":139.415014,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積216㎡","structure_material":"木造平屋一部2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0446","desc":"塩屋集落の通りに西面して建つ。木造二階建切妻造桟瓦葺で、妻面を通りに向け正面に下屋を付しせがいで軒を支えるなど当地域の特徴を良く示す。内部は南を通り土間とし二列三室に部屋を並べ、前列に帳場と床、違棚付きの奥座敷を置くなど、店舗の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011104"},{"id":"00009446","register_sub_id":"101","register_pk":"194239","name":"長谷川酒造主屋","kana":"はせがわしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋2-1831-1","lat":37.41248966,"lng":138.84491458,"geo_status":"db","era":"明治19年／大正13年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0378","desc":"酒造施設の南端に位置する。木造二階建、切妻造桟瓦葺で、東正面北寄りに切妻造のツメバを突出す。床上部は田字形四室で南面の庭側を座敷とする。外壁は簓子下見板張で上部漆喰塗とし、妻壁に二重の梁組を表すなど、風格ある構えを見せる老舗造酒屋の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009446"},{"id":"00001576","register_sub_id":"101","register_pk":"102566","name":"樋木酒造店舗兼主屋","kana":"ひきしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西区内野町582","lat":37.85754724,"lng":138.93876607,"geo_status":"db","era":"明治末期／昭和30移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積340㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0048","desc":"樋木酒造は天保７年，西蒲原郡巻町前田に創業したが，安政年間に現在の新潟市西部に移ったと伝える。主屋は昭和３０年に新津市柄目木の民家を移築した。前面右端に店舗を設けるが，大型の寄棟造・桟瓦葺の民家で，当地方の六間取平面をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001576"},{"id":"00001577","register_sub_id":"101","register_pk":"102567","name":"樋木酒造西酒蔵","kana":"ひきしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市西区内野町582","lat":37.85778887,"lng":138.93844845,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積183㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0049","desc":"樋木酒造は南北に長い敷地を持ち，南正面に建つ主屋の奥に，仕込蔵などの酒造施設が並ぶ。南北に細長い切妻造・桟瓦葺の西酒蔵は明治２６年の建築である。外壁を漆喰塗と腰縦板張とし，内部は一階が貯蔵庫，二階が作業場になる伝統的な酒造蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001577"},{"id":"00001578","register_sub_id":"101","register_pk":"102568","name":"樋木酒造東酒蔵","kana":"ひきしゅぞうひがしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市西区内野町582","lat":37.85792035,"lng":138.93873196,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積280㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0050","desc":"敷地東の東酒蔵は，南北棟・切妻造・桟瓦葺で西酒蔵とほぼ同形式であるが，ひとまわり大きく，東面に２間下屋庇の増設がある。明治４５年の建築で，小屋組は杉丸太の陸梁を用いたキングポストトラスとする。近代工法を取り入れた大規模な酒造蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001578"},{"id":"00001333","register_sub_id":"101","register_pk":"102323","name":"平田大六家住宅煙突","kana":"ひらただいろくけじゅうたくえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10400545,"lng":139.55063766,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦積み、1.2m四方、高さ3.6m","structure_material":"煉瓦積み","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0039","desc":"主屋と酒母蔵に挟まれた位置に建ち，もとはここに洗米，蒸米，酒しぼりなどを行う建物があった。羊羹を用いたイギリス積み煉瓦造煙突で，高さ約３．６ｍ。現在は屋敷の一点景となっているが，酒造業を営んだ当時の様相を知る上で，欠かせない構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001333"},{"id":"00001331","register_sub_id":"101","register_pk":"102321","name":"平田大六家住宅酒蔵","kana":"ひらただいろくけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10417824,"lng":139.55056476,"geo_status":"db","era":"弘化2／明治初期頃増築","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"土蔵造平屋建一部2階建、瓦葺、建築面積119㎡","structure_material":"土蔵造平屋建一部2階建","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0037","desc":"主屋の真北に並行して建つ。桁行９間・梁間４間の東西棟の建物であるが，東側５間分が棟札より弘化２年の建築，西側４間分は明治初期頃の増築とされる。酒造業を営んでいた時期，酒を仕込み貯蔵する施設で，内部梁間２間分には２階床組が設けられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001331"},{"id":"00001330","register_sub_id":"101","register_pk":"102320","name":"平田大六家住宅酒母蔵","kana":"ひらただいろくけじゅうたくもとぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10411238,"lng":139.55073262,"geo_status":"db","era":"明治初期以前","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積54㎡","structure_material":"土蔵造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0036","desc":"屋敷地の北，主屋の北東に建つ。桁行６間半・梁間２間の細長平面で，酒造業を営んでいた時期，酒母を仕込み育成する施設として使われていた。荒壁仕上げの外壁を保護するため，周囲を縦板壁で囲んだ外観は，特色ある意匠として景観になじんでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001330"},{"id":"00002760","register_sub_id":"101","register_pk":"103750","name":"星名家住宅雪穴","kana":"ほしなけじゅうたくゆきあな","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲822-3","lat":37.179237,"lng":138.749985,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"石造、面積36㎡、深さ3m","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"15 － 0117","desc":"市東部，国道２５２号に隣接する雑木林の中にある石造構造物。雪季の積雪を保存し，主に酒造関連の冷蔵所として利用された。法面勾配３分程の玉石乱積壁面を一辺５ｍ程の正方形平面に築き，西壁面に階段を付ける。かつての酒造システムを今に伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002760"},{"id":"00009447","register_sub_id":"101","register_pk":"194240","name":"星野本店三階蔵","kana":"ほしのほんてんさんかいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋2-1812-1他","lat":37.41314639,"lng":138.84438158,"geo_status":"db","era":"明治15年／大正期増築・平成20年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積59㎡","structure_material":"土蔵造3階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0379","desc":"敷地南端に北面し、土蔵造三階建、桁行八・二メートル梁間四・六メートル、切妻造桟瓦葺である。一階正面に蔵前を設け、外壁漆喰塗で腰を簓子下見板張とする。三階は大正期の増築で、小屋はキングポストトラスを組む。特徴的な外観をもつ、醤油醸造所の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009447"},{"id":"00009448","register_sub_id":"101","register_pk":"194241","name":"星六土蔵","kana":"ほしろくどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋4-2340-1","lat":37.41487374,"lng":138.84084512,"geo_status":"db","era":"明治中期／明治後期移築・大正7年曳家","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0380","desc":"店舗兼主屋の南東側に接続する。土蔵造二階建、桁行七・三メートル梁間七・九メートル、切妻造、置屋根式の鉄板葺である。外壁は漆喰塗で腰を簓子下見板張とし、軒蛇腹や窓枠の一部を黒漆喰塗としてアクセントとする。星野本店から移築した味噌醸造用の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009448"},{"id":"00003079","register_sub_id":"101","register_pk":"104069","name":"益甚酒店主屋及び酒蔵","kana":"ますじんさけてんしゅおくおよびさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町194","lat":38.22414475,"lng":139.47890762,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積386㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0140","desc":"店舗奥１２畳間の東方に続く主屋と，その東方に建つ酒造場及び北方の麹室から成る。主屋は棟札から棟梁は稲垣源太郎で，明治２５年の大火直後の建築であることが知られる。店舗脇から望見される間口９間半の西妻面は大火後大町の復興景観の一端を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003079"},{"id":"00013980","register_sub_id":"101","register_pk":"508240","name":"山重仲町通店店舗（旧加茂錦酒造主屋）","kana":"やまじゅうなかまちとおりてんてんぽ（きゅうかもにしきしゅぞうおもや）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県加茂市仲町669-1他","lat":37.65750833,"lng":139.055275,"geo_status":"db","era":"昭和5年／平成20年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造二階建、瓦葺一部鉄板葺、建築面積215㎡","structure_material":"木造二階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0561","desc":"もと造り酒屋の住宅として建築された。道路に近い北寄りが切妻造の平屋建、南が寄棟造の二階建で一連の土間が南北に貫く。平屋の一〇畳二室は小壁が高く西の土間から採光する近代的な造作で、二階座敷は端正な書院座敷である。近代の上質な市街地住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013980"},{"id":"00013981","register_sub_id":"101","register_pk":"508241","name":"山重山の蔵（旧加茂錦酒造酒蔵）","kana":"やまじゅうやまのくら（きゅうかもにしきしゅぞうさかぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県加茂市仲町669-1他","lat":37.65753889,"lng":139.05521667,"geo_status":"db","era":"明治後期／平成20年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積178㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0562","desc":"もと造り酒屋の醸造蔵で旧主屋の南に接続する南北棟。桁行二〇メートルに及ぶ土蔵造二階建で、置屋根を切妻造桟瓦葺とする。外壁は鉢巻付の漆喰塗とし、腰を竪板張とする。妻入で引分けの塗戸を備え、内部は一室、二階は酒造用の床で仕込蔵の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013981"},{"id":"00013984","register_sub_id":"101","register_pk":"508244","name":"旧藺製品作業場","kana":"きゅういせいひんさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和中","pref":"富山県","address":"富山県氷見市朝日本町907-7","lat":36.85303056,"lng":136.985925,"geo_status":"db","era":"昭和32年／同中期、平成29年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積86㎡","structure_material":"木造2階一部平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0156","desc":"湊川沿いの旧藺製品倉庫の西側に建つ作業場。道路に西面して建つ木造二階建、切妻造桟瓦葺妻入で、外壁を下見板張とし、西面に戸口と換気口を設ける。内部は一階に一室、二階に二室を設け、一階を旧藺製品倉庫戸前と接続する。藺製品製造の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013984"},{"id":"00013983","register_sub_id":"101","register_pk":"508243","name":"旧藺製品倉庫","kana":"きゅういせいひんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県氷見市朝日本町907-7","lat":36.85297222,"lng":136.98615278,"geo_status":"db","era":"大正後期／昭和中期、平成29年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造平屋建、瓦葺、建築面積192㎡","structure_material":"土蔵造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0155","desc":"氷見市街地の湊川左岸に建つ南面平入の東西棟。土蔵造もと二階建、切妻造桟瓦葺で、南面に戸前を設けて東端に川からの荷揚口を設ける。川に面した東面を下見板張とし、北面に額縁付の窓を穿つ。内部は一室で、独立柱で棟を支える。湊川水運の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013983"},{"id":"00002375","register_sub_id":"101","register_pk":"103365","name":"旧南部鋳造所煙突","kana":"きゅうなんぶちゅうぞうしょえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県高岡市金屋本町3-45","lat":36.75199236,"lng":137.0068573,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造、高さ15m","structure_material":"煉瓦造","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0061","desc":"炉の約７ｍ南方の地点，石造煙道の南端に接して建つ。基部の平面は１．７８ｍ角で，高さは１４．５ｍ。煉瓦造，イギリス積で，アングル材等で補強され，基部上と頭部に装飾的な帯状部を設ける。高岡鋳物の近代を物語るシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002375"},{"id":"00002374","register_sub_id":"101","register_pk":"103364","name":"旧南部鋳造所キュポラ","kana":"きゅうなんぶちゅうぞうしょきゅぽら","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"富山県","address":"富山県高岡市金屋本町3-45","lat":36.7520445,"lng":137.00689173,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄製キュポラ及び煉瓦・石造煙道よりなる、鉄製吸気管付","structure_material":"鉄製キュポラ及び煉瓦・石造煙道よりなる","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0060","desc":"高岡鋳物発祥地である金屋町の一画に所在。高３．３ｍの鉄製炉，１．５ｍ角・高２．５ｍの角形煙道と０．６ｍ×１．３ｍ断面，長５．６ｍの石造煙道から成る。熱効率を高めるよう石造煙道内には送風鉄管が配置されおり，キューポラ改良の跡が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002374"},{"id":"00013090","register_sub_id":"101","register_pk":"368258","name":"旧伏木港右岸三号岸壁水平引込式クレーン","kana":"きゅうふしきこううがんさんごうがんぺきすいへいひきこみしきくれーん","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"富山県","address":"富山県射水市庄西町二丁目2573","lat":36.79159722,"lng":137.06455833,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨造、高さ43m","structure_material":"鉄骨造","registered":"2019.12.05(令和1.12.05)","register_no":"16 － 0152","desc":"伏木港右岸に設置されたバラ物貨物荷役用クレーン。軌道上移動型のダブルリンク式の水平引込み式で、最大旋回半径三一・五メートル、吊上げ荷重八トン、全揚程二五メートルを測る。設置当時、日本海沿岸最大規模であった、伏木港のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013090"},{"id":"00008112","register_sub_id":"101","register_pk":"132510","name":"旧宮崎酒造衣装蔵","kana":"きゅうみやざきしゅぞういしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1860-1他","lat":36.76327655,"lng":137.33520046,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造3階建、瓦葺、建築面積49㎡","structure_material":"土蔵造3階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0089","desc":"中庭を介して主屋の北、酒蔵の東に位置する。桁行９．６ｍ梁間５．９ｍの３階建土蔵、東西棟の切妻造桟瓦葺で、正面に深い庇を出し、戸前とする。掛子塗の両開扉には鏝による家紋を飾り、開口上部に鳥居状のまぐさを有す。酒蔵等とともに重厚な敷地景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008112"},{"id":"00008111","register_sub_id":"101","register_pk":"132509","name":"旧宮崎酒造麹蔵","kana":"きゅうみやざきしゅぞうこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1860-1他","lat":36.76308917,"lng":137.33513666,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0088","desc":"酒蔵と正面を並べて建つ。桁行８．２ｍ梁間５．４ｍの土蔵造２階建。酒蔵の屋根を葺き下ろし、置屋根とする。正面は１階に掛子塗の両開を吊り、扉内側に家紋をあしらい、２階に窓二ヶ所を穿ち、片開の掛子塗戸を装置するなど、存在感のある外観構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008111"},{"id":"00008110","register_sub_id":"101","register_pk":"132508","name":"旧宮崎酒造酒蔵","kana":"きゅうみやざきしゅぞうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1860-1他","lat":36.76323194,"lng":137.33498051,"geo_status":"db","era":"明治中期／昭和40年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積277㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0087","desc":"南北に長い短冊状の敷地北端に位置する。起りのある切妻造桟瓦葺で、Ｌ字形平面になる土蔵造２階建、建築面積２７７㎡。南妻面２階外壁を焼杉板張とし、深い庇を架けて戸前とする。外壁は漆喰壁で、正面腰壁を黒漆喰仕上げとするなど重厚な佇まいをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008110"},{"id":"00008109","register_sub_id":"101","register_pk":"132507","name":"旧宮崎酒造店舗兼主屋","kana":"きゅうみやざきしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県滑川市瀬羽町1860-1他","lat":36.76304678,"lng":137.335341,"geo_status":"db","era":"江戸末期／明治前期・昭和前期・平成21年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積376㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0086","desc":"旧北陸街道に南面してたつ、間口１４ｍの平入町家。木造２階建、東西棟の切妻造桟瓦葺で、正面に下屋や庇を付ける。西にトオリニワ、東にミセや座敷などを二列に配し、ワクノウチと称する架構をオエなどに残す。当地域における大規模な商家の特徴をよく備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008109"},{"id":"00015435","register_sub_id":"101","register_pk":"533450","name":"三郎丸蒸留所","kana":"さぶろうまるじょうりゅうじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県砺波市三郎丸字川田島188-1他","lat":36.65671944,"lng":136.97011944,"geo_status":"db","era":"昭和前期／昭和29年頃移築、平成29年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積803㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"16 - 0177","desc":"敷地の西北に建つ蒸留施設。桁行三六メートル、梁間二二メートルの木造二階建切妻造、外壁モルタル吹付とする。棟の中央に越屋根を設け、各階連続窓とし、内部はキングポスト・トラスを現す。工場建築を転用し、戦後に開業した北陸最古のウイスキー蒸留施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015435"},{"id":"00002032","register_sub_id":"101","register_pk":"103022","name":"城端織物組合事務棟","kana":"じょうはなおりものくみあいじむとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市城端648-1","lat":36.51427262,"lng":136.90290916,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積274㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0059","desc":"城端は近世より絹織物を主産業とし，近代には著しく発展した。この建物は組合事務や出荷のための検査及び乾燥を目的として建てられた。木造・総２階建だが，木骨モルタル・タイル貼で煉瓦造風とした正面は，地方における洋風意匠の一端を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002032"},{"id":"00016660","register_sub_id":"101","register_pk":"579144","name":"若鶴酒造昭和蔵鶴庫","kana":"わかつるしゅぞうしょうわぐらつるこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和後","pref":"富山県","address":"富山県砺波市三郎丸字川田島207-1他","lat":36.655768,"lng":136.969364,"geo_status":"db","era":"昭和48年","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積587㎡、屋上塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2026.07.09(令和8.07.09)","register_no":"16 - 0179","desc":"ＪＲ油田駅西側の広大な敷地に昭和蔵松庫と並び東面して建つ醸造施設。三階建鉄筋コンクリート造のラーメン構造で柱形を外に現す。内部は階高が高い大空間で一・二階は仕込・貯蔵用の樽、三階に糀室などを配する。清酒需要の増大に対応した大規模な醸造施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016660"},{"id":"00015434","register_sub_id":"101","register_pk":"533449","name":"若鶴酒造昭和蔵松庫","kana":"わかつるしゅぞうしょうわぐらまつこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"富山県","address":"富山県砺波市三郎丸字六反島401-2他","lat":36.65596667,"lng":136.96959167,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積692㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"16 - 0176","desc":"大正蔵の北方に位置する醸造施設。二階建鉄筋コンクリート造のラーメン構造で、柱形を外に現す。内部は各階大空間で、一階は仕込庫や貯蔵庫、二階は麹室や酒母室を配する。戦後の清酒需要の増大に対応した近代的な醸造施設で、二本の塔屋が外観を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015434"},{"id":"00015433","register_sub_id":"101","register_pk":"533448","name":"若鶴酒造大正蔵","kana":"わかつるしゅぞうたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"富山県","address":"富山県砺波市三郎丸字川田島188-1他","lat":36.65530556,"lng":136.96931389,"geo_status":"db","era":"大正9年／昭和34年増築・平成7年・同24年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積754㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"16 - 0175","desc":"ＪＲ城端線油田駅西側の広大な敷地の南西角に建つ旧醸造蔵。桁行三三メートル、梁間１１メートルの東西に下屋を付し、全体に桟瓦葺屋根を葺降ろす大規模な土蔵。外壁漆喰塗、腰竪板張。二段の額縁を廻らす小庇付の窓の連続が、印象的な歴史的景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015433"},{"id":"00010281","register_sub_id":"101","register_pk":"199054","name":"大崎家住宅主屋","kana":"おおさきけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県輪島市鳳至町上町28","lat":37.396301,"lng":136.897243,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"17-0248","desc":"通りに東面し、正面に下屋を設け、下階に格子、上階にガラス窓をたてる。南端に、後方の塗蔵に続く幅一間の土間を通し、北側に居室を二列並べる。居室の北列に中庭を設けて採光し、二階に瀟洒な座敷を配して接客に供する。輪島塗の塗師住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010281"},{"id":"00011940","register_sub_id":"101","register_pk":"211088","name":"小山屋醤油店表土蔵","kana":"おやまやしょうゆてんおもてどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市相生町41-1","lat":37.04464,"lng":136.96608,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"17-274","desc":"通りに面して店舗の西に接続する。桁行四間、梁間三間、切妻造、桟瓦葺で、店舗側妻面の扉口に観音扉を開き、内格子戸を片引きで建て込む。内部は一、二階とも一室である。外壁は二階軒下まで板張とし、建ちの高い土蔵で、通りからの景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011940"},{"id":"00011942","register_sub_id":"101","register_pk":"211090","name":"小山屋醤油店醤油蔵","kana":"おやまやしょうゆてんしょうゆくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県七尾市相生町41-1","lat":37.044454,"lng":136.966075,"geo_status":"db","era":"明治前期／平成19年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積142㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"17-276","desc":"敷地南東隅に建つ醤油蔵。桁行六間、梁間七間、切妻造、妻入で、西半の小屋組の棟木に登梁を載せて大屋根を架ける。外壁は軒下まで下見板張とし、鉢巻を廻らし、軒出は小さい。窓を連続して穿ち、敷地後方において堂々たる外観を持つ大型の醤油蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011942"},{"id":"00011939","register_sub_id":"101","register_pk":"211087","name":"小山屋醤油店店舗兼主屋","kana":"おやまやしょうゆてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市相生町41-1","lat":37.044598,"lng":136.966158,"geo_status":"db","era":"明治後期／昭和後期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積290㎡","structure_material":"木造2階一部平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"17-273","desc":"七尾市中心部で通りに北面する。間口七間、奥行三間の店舗は二階建で正面に奥行一間の下屋を付す。中央の通り土間を挟み、東に作業場、西奥に居室を設ける。正面は土戸を納める戸袋や軒裏を塗込め、二階軒裏は歯飾り状の洋風意匠を見せる、特徴的な外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011939"},{"id":"00011941","register_sub_id":"101","register_pk":"211089","name":"小山屋醤油店ムロ","kana":"おやまやしょうゆてんむろ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県七尾市相生町41-1","lat":37.044586,"lng":136.966053,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造及び木造平屋建、瓦葺、建築面積44㎡","structure_material":"煉瓦造及び木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"17-275","desc":"敷地西に表土蔵と直行して建つ。ムロは桁行一〇メートル、梁間三・一メートルの細長い平面で壁を煉瓦で積み、板天井を張り、南側に木造の前室を付け、それぞれ切妻造、桟瓦葺の屋根を架ける。二度の大火を経た七尾市において防火を意識して建てられたムロ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011941"},{"id":"00009264","register_sub_id":"101","register_pk":"194057","name":"金沢市民芸術村事務所棟","kana":"かなざわしみんげいじゅつむらじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市大和町1-21","lat":36.56789142,"lng":136.63982834,"geo_status":"db","era":"大正8年／平成8年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積381㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0241","desc":"紡績工場の事務所棟として建設。木造二階建、建築面積三八一平方メートル、寄棟造桟瓦葺でＬ字形平面の東角を隅切して玄関を構える。北面を吹放しの廊下とし、南面に階段室と便所を配する。外壁は下見板張で欄間付上下窓を連ねる。簡潔な意匠の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009264"},{"id":"00000041","register_sub_id":"101","register_pk":"101031","name":"金沢市立玉川図書館別館（旧専売公社C-1号工場）","kana":"かなざわしりつたまがわとしょかんべっかん（きゅうせんばいこうしゃしーいちごうこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市玉川町２-20","lat":36.57004075,"lng":136.65159661,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積691㎡","structure_material":"煉瓦造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"17 － 0001","desc":"大蔵省臨時建築部によって建設された煙草工場で，設計は建築部長妻木頼黄の下で矢橋賢吉が手がけたと推定されている。１・２階を一体に扱う窓廻りのアーチの構成と煉瓦造の外観に特徴があり，明治の大蔵省臨時建築部の作風を示す標準となる好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000041"},{"id":"00011285","register_sub_id":"101","register_pk":"209121","name":"旧北森酒店店舗兼主屋","kana":"きゅうきたもりさけてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県小松市粟津町カ8-5","lat":36.332625,"lng":136.446941,"geo_status":"db","era":"明治33頃／平成25改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0262","desc":"粟津温泉街の中心部に所在するもと造酒屋で、近隣の旅館に日本酒を卸していた。二階建で平面は前広間型を基本とし、屋根はやや起りのある切妻造妻入で桟瓦葺とし、妻面に小屋束と貫、梁を現し、左右に片流の下屋を付けるなど、当地域の民家の特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011285"},{"id":"00003227","register_sub_id":"101","register_pk":"104217","name":"旧山長織物会社石蔵","kana":"きゅうやまちょうおりものがいしゃいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺番場町18-2","lat":36.309517,"lng":136.3108339,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積64㎡","structure_material":"木骨石造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0067","desc":"事務所の東方，旧大聖寺川沿い道路際に南北棟で建つ。桁行４間梁間３間規模，越前瓦葺，切妻造の２階建で，西面全面に１間半幅の下屋を差掛けて蔵前をとる。生糸の保管蔵で，地元産の凝灰岩を用いた木骨石造とし，入口に金庫風の観音扉，窓には鉄扉を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003227"},{"id":"00003226","register_sub_id":"101","register_pk":"104216","name":"旧山長織物会社事務所","kana":"きゅうやまちょうおりものがいしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺番場町18-2","lat":36.309654,"lng":136.310608,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0066","desc":"旧大聖寺川沿岸に位置し，南面して建つ。桁行８間梁間３間規模，越前瓦葺，寄棟造の木造総２階建の南面に寄棟の車寄を突出し，背面に１間幅の下屋を付ける。外壁をイギリス下見板張とした洋館風の事務所建築で，開口部を大きくとっている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003226"},{"id":"00003228","register_sub_id":"101","register_pk":"104218","name":"旧山長織物会社門","kana":"きゅうやまちょうおりものがいしゃもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺番場町18-2","lat":36.30953106,"lng":136.31057943,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、間口6m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0068","desc":"事務所玄関車寄の東南方に位置し，道路からやや退いて建つ。切妻造，越前瓦葺の腕木門で，１間１戸として両開戸を付け，背後に控柱を建てる。左右両脇には半間幅の通用口を設け，越前瓦葺，切妻造の小屋根を架けて織物会社正面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003228"},{"id":"00012899","register_sub_id":"101","register_pk":"368002","name":"小松市立錦窯展示館石蔵","kana":"こまつしりつにしきがまてんじかんいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県小松市大文字町95-2他","lat":36.40325556,"lng":136.44836389,"geo_status":"db","era":"昭和40年頃／平成10年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積9.6㎡","structure_material":"石造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 288","desc":"敷地東南隅に西面して建つ完成品の旧収蔵庫。切妻造桟瓦葺妻入の平屋建で、外壁を観音下石積とする。正面は出入口に鳥居枠を組んで鉄扉を備え、石材表面に縦溝や面取を施すなど丁寧につくる。内部は大壁造の一室で、和小屋を現す。屋敷奥の構えを引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012899"},{"id":"00012898","register_sub_id":"101","register_pk":"368001","name":"小松市立錦窯展示館窯納屋","kana":"こまつしりつにしきがまてんじかんかまなや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県小松市大文字町95-2他","lat":36.40325833,"lng":136.44803889,"geo_status":"db","era":"昭和8年頃／平成10年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 287","desc":"主屋の南側に建つ切妻造桟瓦葺の木造二階建で、西面を通りに面する。外壁は一階を簓子下見板張の腰石張、二階を漆喰塗とする。内部は石敷土間で、東を吹抜けとして大小二基の錦窯を備え、西は一階を薪置場、二階を倉庫とする。九谷焼窯納屋の希少な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012898"},{"id":"00012897","register_sub_id":"101","register_pk":"368000","name":"小松市立錦窯展示館主屋","kana":"こまつしりつにしきがまてんじかんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県小松市大文字町95-2他","lat":36.40332222,"lng":136.44808889,"geo_status":"db","era":"昭和8年頃／平成10年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 286","desc":"小松旧市街にある陶工・徳田八十吉の旧居兼陶房。主屋は前庭を介して通りに西面して建つ木造二階建、切妻造桟瓦葺。1階南側を土間とし、北側にミセや座敷等四室を並べる。二階は7室を配し、上絵付の作業場とする。九谷焼窯元の暮らしを伝える近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012897"},{"id":"00005130","register_sub_id":"101","register_pk":"106120","name":"橋本酒造釜場及び白米庫","kana":"はしもとしゅぞうかまばおよびはくまいこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32757914,"lng":136.38605911,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄骨石造平屋建、瓦葺、建築面積171㎡","structure_material":"鉄骨石造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0141","desc":"清酒蔵の南方に東西棟で建つ。桁行１１間，梁間５間，切妻造，桟瓦葺の平屋建で，仕込蔵として建設。構造は外周に鉄骨柱を建て，外側に凝灰岩を積んだ鉄骨石造で，小屋組は鉄骨のフィンクトラスとする。ＲＣ造へ移行する過渡期の構造の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005130"},{"id":"00005128","register_sub_id":"101","register_pk":"106118","name":"橋本酒造清酒蔵","kana":"はしもとしゅぞうせいしゅぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32770677,"lng":136.38604138,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積159㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0139","desc":"槽場の西方，貯蔵庫の南西方に位置し，東西棟で建つ。規模は桁行７間半，梁間６間で，切妻造，桟瓦葺，妻入の２階建酒蔵で，１階内部の２列の柱６本が２階床を支持し，２階中央２本の柱で地棟を支える整然とした構造で，外周の壁内側に凝灰岩を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005128"},{"id":"00005127","register_sub_id":"101","register_pk":"106117","name":"橋本酒造貯蔵庫","kana":"はしもとしゅぞうちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32782094,"lng":136.38613475,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0138","desc":"槽場の北面西寄りに接続して南北棟で建つ。桁行９間，梁間４間半規模，切妻造，桟瓦葺，妻入の２階建酒蔵で，南西隅に階段を設け，内部棟通りの２本の柱と妻面の棟持柱が地棟を支持する。槽場と同様に，外周の壁内側に凝灰岩を張り，大棟には笏谷石を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005127"},{"id":"00005126","register_sub_id":"101","register_pk":"106116","name":"橋本酒造槽場","kana":"はしもとしゅぞうふなば","category":"産業2次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.3276718,"lng":136.38621413,"geo_status":"db","era":"文化5","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0137","desc":"石蔵の南方，主屋通り庭の西側に接して東西棟で建つ。桁行１０間半，梁間４間規模，切妻造，桟瓦葺で，主屋側土扉金具に「文化五年辰七月吉日」と記す。外周は半間毎に柱を建て，外側に凝灰岩を張り，さらに外側に土壁層を設けて漆喰塗り仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005126"},{"id":"00007477","register_sub_id":"101","register_pk":"108459","name":"東酒造場大門","kana":"ひがししゅぞうじょうおおもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432186,"lng":136.480576,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0203","desc":"敷地東辺の中央、通りから入った所に蔵に挟まれて建つ。両下造桟瓦葺の長屋門で、南半部は作業場と一体の空間をつくる。北側の門口４．７ｍに両開の大戸と潜りを設け、正面南寄りは石積基礎に漆喰壁で高く腰板を張り出格子窓を付け、屋敷構えに風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007477"},{"id":"00007478","register_sub_id":"101","register_pk":"108460","name":"東酒造場勝手口","kana":"ひがししゅぞうじょうかってぐち","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432346,"lng":136.480423,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造、瓦葺、間口1.7m、左右塀付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0204","desc":"敷地北辺の中央、主屋と道具蔵の間に建つ。間口１．７ｍと小規模な薬医門で、東西棟の切妻造桟瓦葺。洋風を加味したの道具蔵と対照的に軽やかな和風意匠とする。両脇に続く袖塀は、切石を高く積み上げ、その上に東側は土塀、西側は板塀を造り、総延長８．６ｍ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007478"},{"id":"00007474","register_sub_id":"101","register_pk":"108456","name":"東酒造場桂松庵","kana":"ひがししゅぞうじょうけいしょうあん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432198,"lng":136.480133,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0200","desc":"麹室の北に接し、主屋西側の庭園に面する四畳半茶室。南北棟の入母屋造で、軒先を銅板とする桟瓦葺とし、北・東面に銅板葺庇を付ける。網代組や筵を組み合わせた天井をもち、障子窓や貴人口から光を採り込み、明るく軽快な茶室に仕上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007474"},{"id":"00007472","register_sub_id":"101","register_pk":"108454","name":"東酒造場検査室","kana":"ひがししゅぞうじょうけんさしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43211948,"lng":136.48015686,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積59㎡","structure_material":"木造2階一部平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0198","desc":"西蔵と中蔵の間に建つ。桁行３．６ｍ梁間３．２ｍの木造２階建で、切妻造桟瓦葺とし、北側に広い下屋を付ける。内部は白漆喰仕上げ大壁造で、天井まで塗り上げる。南面外壁は石積基礎上に下見板張とし、ベイウィンドウを設け、窓にはステンドグラスを入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007472"},{"id":"00007473","register_sub_id":"101","register_pk":"108455","name":"東酒造場麹室","kana":"ひがししゅぞうじょうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43215348,"lng":136.48010128,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積62㎡","structure_material":"石造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0199","desc":"敷地西辺、西蔵の北側に隣接する。桁行７．４ｍ梁間８．３ｍの規模の小さい石造平屋建で、切妻造桟瓦葺とする。観音下石を軒まで積み上げ、妻壁の上部は真壁に小屋架構を現す。石積の重厚な外壁上に掛かる、軽快な屋根が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007473"},{"id":"00007470","register_sub_id":"101","register_pk":"108452","name":"東酒造場作業場","kana":"ひがししゅぞうじょうさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43215659,"lng":136.48038269,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び鉄板葺、建築面積178㎡、煙突付","structure_material":"木造平屋一部2階建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0196","desc":"東蔵と中蔵の間にある切妻造２階建の酒母室と休憩室や、東蔵や中蔵の北面に一連で続く釜場などの作業空間からなる。北面は下見板張の真壁や出格子窓、煉瓦造の煙突、複雑に架かる屋根など変化に富む外観をつくり、通りの酒母室南面は石積で街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007470"},{"id":"00007467","register_sub_id":"101","register_pk":"108449","name":"東酒造場店舗兼主屋","kana":"ひがししゅぞうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43224783,"lng":136.480255,"geo_status":"db","era":"昭和11／昭和57頃改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積232㎡","structure_material":"木造2階一部平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0193","desc":"敷地の中央北寄りに東面する。正面に入母屋造桟瓦葺の２階建、背面に直交する入母屋造平屋建を設ける。内部は前方南半に土間、北にオイ、後方に田の字型に４室を配し、彫刻欄間を飾る。伝統的な間取を受け継ぎながら、外観や平面ほかに近代性を反映する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007467"},{"id":"00007476","register_sub_id":"101","register_pk":"108458","name":"東酒造場道具蔵","kana":"ひがししゅぞうじょうどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43227317,"lng":136.48034938,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積84㎡","structure_material":"木造2階一部平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0202","desc":"敷地北辺、主屋の東方に建つ。桁行７．７ｍ梁間５．９ｍ規模の切妻造桟瓦葺で、南面に蔵前を設ける。木造２階建で、外壁に切石を積み上げ、開口部に半円アーチなどの洋風意匠を取り入れ、上下の窓の間には竜虎の彫刻を施す。丁寧な装飾が施された石蔵の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007476"},{"id":"00007469","register_sub_id":"101","register_pk":"108451","name":"東酒造場中蔵","kana":"ひがししゅぞうじょうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432098,"lng":136.48031672,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積178㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0195","desc":"敷地南辺、東蔵の西方に建つ。桁行１９ｍ梁間９．５ｍの切妻造桟瓦葺。木造２階建で、柱外側に観音下石を積み上げ、内部を白漆喰で仕上げる。東蔵と共通する外観であるが、鉢巻を簡略にし、出入口の外側楣上に半円アーチと楔石の装飾をするなど、違いを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007469"},{"id":"00007471","register_sub_id":"101","register_pk":"108453","name":"東酒造場西蔵","kana":"ひがししゅぞうじょうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432083,"lng":136.480103,"geo_status":"db","era":"慶応4／明治35移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0197","desc":"敷地の南辺西端に建つ土蔵造２階建。桁行９．５ｍ梁間５．９ｍの切妻造妻入桟瓦葺。東面に出入口、南・西面に窓を開け、窓枠等に石材を用いる。江戸切仕上げの石積基礎上に、高く下見板張とし、軒まわりにも石材をまわす。石蔵が連続する景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007471"},{"id":"00007468","register_sub_id":"101","register_pk":"108450","name":"東酒造場東蔵","kana":"ひがししゅぞうじょうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43211,"lng":136.48056,"geo_status":"db","era":"昭和21","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積139㎡","structure_material":"石造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0194","desc":"敷地の南辺東端に建つ。桁行１５ｍ梁間９．４ｍの石造平屋建。切妻造妻入桟瓦葺とし、西面の酒母室側に入口を設け引分け戸をたてる。内部は一室で、漆喰仕上げ、トラス組とする。地元産の観音下石を積み上げ、腰部を江戸切仕上げとする。重厚で趣のある石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007468"},{"id":"00007475","register_sub_id":"101","register_pk":"108457","name":"東酒造場緑寿庵","kana":"ひがししゅぞうじょうりょくじゅあん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.4322891,"lng":136.48009652,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0201","desc":"敷地の北西隅に位置する。南北棟の入母屋造桟瓦葺で、庭側の南から東面に深い土庇、東面北寄りに入母屋造の玄関を設ける。庭園に面する主座敷には、大きくトコとトコ脇を構え、花頭形に開ける付書院を備え、緩やかな折上格天井を張り、格式のある空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007475"},{"id":"00002919","register_sub_id":"101","register_pk":"103909","name":"やちや酒造酒蔵","kana":"やちやしゅぞうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市大樋町232","lat":36.585922,"lng":136.675613,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積132㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"17 － 0061","desc":"金沢城北方に所在する老舗の造り酒屋。南北に長い敷地中央に建つ道具蔵の北側にあり，主屋とほぼ同時期のものと思われ，伝統的な酒造産業に欠かせない施設。東西棟で桟瓦葺，桁行約約１９ｍで２階建の細長い建物で，酒蔵らしい空間構成をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002919"},{"id":"00002917","register_sub_id":"101","register_pk":"103907","name":"やちや酒造主屋","kana":"やちやしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市大樋町232","lat":36.585617,"lng":136.675751,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"17 － 0059","desc":"金沢城北方に所在する老舗の造り酒屋。南北に長い敷地で，南側街路に面して建つ主屋は，間口７間の２階建で，屋根は切妻造・桟瓦葺，幅広の下屋庇をつける。改造はあるのもの，伝統的な外観を保ち，内部も豪快な梁組をみせるなど，商家のつくりをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002917"},{"id":"00002918","register_sub_id":"101","register_pk":"103908","name":"やちや酒造道具蔵","kana":"やちやしゅぞうどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市大樋町232","lat":36.585812,"lng":136.675583,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"17 － 0060","desc":"金沢城北方に所在する老舗の造り酒屋。南側の主屋後方，南北に長い敷地中央に建ち，主屋とほぼ同時期のものと思われる。製造業の屋敷構成に欠かせない施設。木造・２階建の土蔵造で，戸口に黒漆喰塗の観音扉を用いるなど，重厚で丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002918"},{"id":"00013246","register_sub_id":"101","register_pk":"366235","name":"青木蘭麝堂酒蔵","kana":"あおきらんじゃどうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県福井市脇三ケ町25字谷口19","lat":36.01871111,"lng":136.29104444,"geo_status":"db","era":"寛政12年(1800)／明治後期増築、昭和37年頃改修","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積218㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"18 － 0201","desc":"敷地中央に位置し、主屋の東側に続く土蔵造東西棟の中蔵、その東側に隣接する土蔵造南北棟の酒蔵、それらの南側に架かる下屋からなる。外壁は白漆喰塗で、腰を簓子下見板張とし、内部には仕込室、薬酒製造室、保管室等を配す。薬酒製造の中心施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013246"},{"id":"00013244","register_sub_id":"101","register_pk":"366233","name":"青木蘭麝堂新座敷","kana":"あおきらんじゃどうしんざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市脇三ケ町25字谷口19","lat":36.01881667,"lng":136.290925,"geo_status":"db","era":"明治前期／昭和前期・同44年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、金属板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"18 － 0199","desc":"市東部の御茸山山裾に位置し、南面する敷地北寄りに建つ主屋北側に接続する。木造平屋建で東側の庭園鑑賞のために建てた。外壁は白漆喰塗を基本とし、一部下見板張とする。内部は床付の六畳間一室で、全体的に面皮材や丸太を多用し、数奇屋風意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013244"},{"id":"00013245","register_sub_id":"101","register_pk":"366234","name":"青木蘭麝堂離れ","kana":"あおきらんじゃどうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県福井市脇三ケ町25字谷口19","lat":36.01877778,"lng":136.29078611,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、金属板葺、建築面積15㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"18 － 0200","desc":"新座敷の西側に位置し、南東部が主屋の北側に接続する。木造二階建、入母屋造金属板葺で、外壁は黄漆喰塗、一部下見板張とする。二階に三畳の前室と四畳半の床付の座敷を設け、手摺越しに南西に広がる庭園を望む。敷地北西隅の中庭周囲の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013245"},{"id":"00013719","register_sub_id":"101","register_pk":"505253","name":"岩野平三郎製紙所主屋","kana":"いわのへいざぶろうせいししょおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市大滝町27字岩上4他","lat":35.90448333,"lng":136.24981667,"geo_status":"db","era":"明治元年／大正後期増築、昭和8年頃・同30年頃改修、同中期増築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積218㎡","structure_material":"木造2階一部平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 221","desc":"事務所北西に接続し、東面して建つ。二階建切妻造桟瓦葺の北棟と棟を直行させた南棟を平屋で接続し東・北面に深い下屋を付す。外壁は真壁造で腰は下見板一部竪板張。北棟を居室部、平屋を内玄関とし、南棟は台所や和室とする。風格ある屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013719"},{"id":"00013726","register_sub_id":"101","register_pk":"504975","name":"岩野平三郎製紙所旧大工小屋","kana":"いわのへいざぶろうせいししょきゅうだいくごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.9044,"lng":136.25000556,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 228","desc":"コグラの北に近接し西面して建つ。もと和紙出荷用の梱包木箱の製作所と伝える。木造平屋建、切妻造桟瓦葺で、西面に下屋を架ける。外壁は下見板張で上部を土壁とする。内部は一室で土間床に竪板張の壁とし、束立の和小屋を現す。敷地中ほどの一点景をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013726"},{"id":"00013725","register_sub_id":"101","register_pk":"504974","name":"岩野平三郎製紙所コグラ","kana":"いわのへいざぶろうせいししょこぐら","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90433611,"lng":136.25,"geo_status":"db","era":"昭和24年","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積41㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 227","desc":"事務所の東方、街路に沿って南面して建つ。もと大判和紙の乾燥場。土蔵造二階建、桟瓦葺で背面に下屋を付す。外壁は漆喰で軒先まで塗込め腰をモルタル塗とする。内部は上下階とも一室で一階は土壁、二階は竪板張。煮釜場と共に敷地東辺の沿道景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013725"},{"id":"00013718","register_sub_id":"101","register_pk":"504971","name":"岩野平三郎製紙所事務所","kana":"いわのへいざぶろうせいししょじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市大滝町27字岩上4他","lat":35.90436111,"lng":136.24988333,"geo_status":"db","era":"明治元年／昭和中期","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 220","desc":"越前和紙の産地、旧今立町にある製紙所。事務所は谷間の南北に長い敷地中央北寄に南面して建つ。木造二階建、切妻造桟瓦葺で正面に下屋を付す。外壁は下見板一部竪板張で、上部は真壁造。内部一階は事務室、二階は和室を配する。敷地北半の屋敷景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013718"},{"id":"00013723","register_sub_id":"101","register_pk":"504973","name":"岩野平三郎製紙所漉き場及び圧搾場","kana":"いわのへいざぶろうせいししょすきばおよびあっさくば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90390556,"lng":136.24998889,"geo_status":"db","era":"大正後期／昭和28年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋一部2階建、瓦葺、建築面積407㎡","structure_material":"木造平屋一部2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 225","desc":"ビーター場の北に接続して建つ紙漉き、脱水用施設。切妻造のＬ字型平面で、東西棟の漉き場と南北棟で東面に下屋を付した圧搾場からなる。漉き場内部は天井が高く、南東面は上下二段に窓を開いて採光を図る。狭隘な敷地なりに建つ広大な施設が存在感を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013723"},{"id":"00013720","register_sub_id":"101","register_pk":"505255","name":"岩野平三郎製紙所土蔵及び繋ぎ屋","kana":"いわのへいざぶろうせいししょどぞうおよびつなぎや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市大滝町27字岩上4他","lat":35.90463889,"lng":136.24993056,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階及び木造平屋建、瓦葺、建築面積125㎡","structure_material":"土蔵造2階及び木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 222","desc":"敷地北端に南面して建つ二階建の土蔵。正面に下屋を付し、外壁は漆喰で軒先まで塗込めて腰を下見板張とする。二階東側には床付の座敷を配する。土蔵南西に伸びて主屋に接続する繋ぎ屋は内部に風呂等を備える。丁寧なつくりで、北辺の屋敷景観を引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013720"},{"id":"00013721","register_sub_id":"101","register_pk":"505257","name":"岩野平三郎製紙所煮釜場","kana":"いわのへいざぶろうせいししょにがまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90417222,"lng":136.25001667,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 223","desc":"敷地中程東辺に西面して建つ原材料の繊維の煮沸、洗浄用の施設。片流れ鉄板葺の南北に長い平面で、敷地の高低なりに北半を一段低くつくる。外壁は竪板張とする。北半の二室と南半一室に区分し、南半に釜場と洗い場を設ける。和紙製造施設の沿道景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013721"},{"id":"00013724","register_sub_id":"101","register_pk":"505259","name":"岩野平三郎製紙所張り場及び乾燥場","kana":"いわのへいざぶろうせいししょはりばおよびかんそうば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90417222,"lng":136.24989167,"geo_status":"db","era":"昭和28年／同40年頃増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 226","desc":"圧搾場の北に接続し、東面して建つ。南北棟の木造二階建、切妻造桟瓦葺で、正面北寄出入口に庇を架ける。外壁は下見板一部竪板張とする。東側にトラスで大スパンをとばした大部屋の作業空間をつくり、西側に小部屋の乾燥室を配す。敷地中央の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013724"},{"id":"00013722","register_sub_id":"101","register_pk":"504972","name":"岩野平三郎製紙所ビーター場","kana":"いわのへいざぶろうせいししょびーたーば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90374444,"lng":136.25013889,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 224","desc":"敷地南端に建つ原材料の繊維の塵取り、叩き解し用の施設。木造平屋建切妻造桟瓦葺で、南に下屋、北東に落棟の突出部を付す。外壁は下見板張で、連続した横長窓で開口を広くとる。内部はキングポストトラスの小屋組を現す大空間。一連の施設景観の南端を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013722"},{"id":"00007208","register_sub_id":"101","register_pk":"108190","name":"越前和紙の里卯立の工芸館（旧西野家住宅主屋及び紙漉場）","kana":"えちぜんわしのさとうだつのこうげいかん（きゅうにしのけじゅうたくしゅおくおよびかみすきば）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県越前市新在家町9字畔之内18他","lat":35.911171,"lng":136.244812,"geo_status":"db","era":"寛延元／平成9移築","year":1748,"year_source":"db","year_min":1748,"year_max":1748,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積244㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"18 － 0063","desc":"木造つし２階建、南北棟の妻入主屋の東に、木造つし２階建の南北棟の紙漉場が並ぶ。屋根は桟瓦葺で、主体部の両妻にウダツを立ち上げて特徴的な外観を呈する。内部は前半を土間と板間、後半を整形四間取の居室とする。２階への階段は移築時の後補である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007208"},{"id":"00007484","register_sub_id":"101","register_pk":"108466","name":"加藤吉平商店表門","kana":"かとうきちべいしょうてんおもてもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市吉江町1字一ノ割14","lat":35.98627814,"lng":136.17014769,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0076","desc":"七曲りに東面して建つ。一間棟門で両側に板塀が続く。布基礎上に土台を置き、方柱を建て、腕木を出し、一軒疎垂木を支持。屋根は石置棟の切妻造桟瓦葺で、緩やかな起りをもつ。板塀は延長１５ｍ、竪板張で、屋根に桟瓦を葺く。伝統的な街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007484"},{"id":"00007483","register_sub_id":"101","register_pk":"108465","name":"加藤吉平商店土蔵","kana":"かとうきちべいしょうてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市吉江町1字一ノ割14","lat":35.98640807,"lng":136.16991559,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0075","desc":"七曲りの西に占める屋敷地のほぼ中央に位置する。切石積基礎上に建つ土蔵造２階建。桁行９．５ｍ梁間５．７ｍ規模で、１、２階とも広い１室とする。切妻造妻入桟瓦葺とし、正面に庇を付け、その下に出入口を設け、両脇に分銅形の文様を施す腰板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007483"},{"id":"00001697","register_sub_id":"101","register_pk":"102687","name":"旧鯖江地方織物検査所","kana":"きゅうさばえちほうおりものけんさじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県鯖江市旭町1-6-6","lat":35.9446189,"lng":136.1862299,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積312㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"18 － 0013","desc":"人絹織物の検反所として建設。総二階建で、一階腰をドイツ下見縦板張とするほかは南京下見板張とし、軒下に白漆喰塗小壁を廻す。典型的な下見板張洋風建築。福井県下近代産業の中心を担った繊維関係事務所の数少ない遺構。さばえ現代美術センターとして活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001697"},{"id":"00007479","register_sub_id":"101","register_pk":"108461","name":"旧紐育スタンダード石油会社倉庫北棟","kana":"きゅうにゅーよーくすたんだーどせきゆがいしゃそうこきたとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県敦賀市金ヶ崎町16-1","lat":35.66200521,"lng":136.07460786,"geo_status":"db","era":"明治38／昭和56・昭和58改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積513㎡","structure_material":"煉瓦造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0071","desc":"敦賀港の東部、金ヶ崎突堤の付け根に位置する敷地の北寄りに、西妻面を海側に向けて建つ。桁行３５ｍ梁間１５ｍ規模の煉瓦造平屋建、切妻造桟瓦葺とする。外壁に柱型を現して内壁を平滑にし、貯蔵の便に供した。近代敦賀港の面影を残す数少ない産業遺産である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007479"},{"id":"00007480","register_sub_id":"101","register_pk":"108462","name":"旧紐育スタンダード石油会社倉庫南棟","kana":"きゅうにゅーよーくすたんだーどせきゆがいしゃそうこみなみとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県敦賀市金ヶ崎町16-1","lat":35.66186183,"lng":136.074539,"geo_status":"db","era":"明治38／昭和56・昭和58改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積513㎡","structure_material":"煉瓦造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0072","desc":"北棟と３ｍ隔てて平行して建ち、規模や形態を同じくする。煉瓦はイギリス積で、妻面上部の窓や平側中央の出入口まわりの装飾、鉄扉は当初のものである。内部に柱がなく、クィーンポストトラスが広い内部空間を実現する。北棟とともに県下最大規模の煉瓦造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007480"},{"id":"00007481","register_sub_id":"101","register_pk":"108463","name":"旧紐育スタンダード石油会社倉庫煉瓦塀","kana":"きゅうにゅーよーくすたんだーどせきゆがいしゃそうこれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県敦賀市金ヶ崎町16-1","lat":35.66174183,"lng":136.07470862,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造、総延長92m","structure_material":"煉瓦造","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0073","desc":"道路で囲まれる敷地の北・東・南辺に設けられた煉瓦塀。イギリス積とし、高さ２．５ｍで、上部３段は迫り出し、天端をモルタルで仕上げる。総延長９２ｍに及び、１０～１５ｍ間隔に控えを付け、各面中央に開口を設ける。倉庫と一体で往時の港湾景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007481"},{"id":"00008679","register_sub_id":"101","register_pk":"149400","name":"黒龍酒造店舗兼主屋","kana":"こくりゅうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町松岡春日1-38他","lat":36.09121338,"lng":136.29901113,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積195㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0100","desc":"本町通りに南面して建つ。間口15ｍ奥行12ｍの木造つし2階建、切妻造桟瓦葺とし、正・背面に下屋を付ける。出入口を挟んで、左右に平格子と出格子、上屋には太い格子を中央6間に構え、両端間を黒漆喰で仕上げ、袖ウダツを付ける。風格ある大型町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008679"},{"id":"00008680","register_sub_id":"101","register_pk":"149401","name":"黒龍酒造離れ","kana":"こくりゅうしゅぞうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町松岡春日1-38他","lat":36.09131693,"lng":136.29912264,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0101","desc":"店舗兼主屋の東面寄りに接する。東西棟の入母屋造桟瓦葺。木造平屋建で、建築面積54㎡。8畳の1室で、東面にトコと違棚を構える。南北に縁を設け、南庭側には室境に欄間を飾る。トコに銘木を用い、天井は黒漆塗の棹縁天井とするなど、良質な離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008680"},{"id":"00008681","register_sub_id":"101","register_pk":"149402","name":"黒龍酒造東門","kana":"こくりゅうしゅぞうひがしもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町松岡春日1-38他","lat":36.09121032,"lng":136.29915818,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0102","desc":"離れ南庭を挟み、通りに面して建つ。間口2.7ｍの腕木門。中央1.6ｍを門口として、両開板戸を吊り、両脇に腰板張の黒漆喰とする袖壁を造る。切妻造桟瓦葺。軒桁と冠木間に軒天井を張り、疎垂木を配る。基礎の笏谷石、黒壁、木部の弁柄の対比が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008681"},{"id":"00013382","register_sub_id":"101","register_pk":"368468","name":"信洋舎製紙所旧休憩場及び張場棟","kana":"しんようしゃせいしじょきゅうきゅうけいばおよびはりばとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市定友町五字相生12他","lat":35.91436389,"lng":136.24763611,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0212","desc":"漉場棟の南、ボイラー及び旧ロール場棟の東に接続して東西棟で建つ。二階を張場とし、一階はかつて休憩場として使った。張場は、張り板に張った紙を乾燥させるための場所で、乾燥機を用いた専用の乾燥部屋も持つ。二階は採光通風のためガラス窓を大きく取る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013382"},{"id":"00013384","register_sub_id":"101","register_pk":"368470","name":"信洋舎製紙所旧塵取場及び仕上場棟","kana":"しんようしゃせいしじょきゅうちりとりばおよびしあげばとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市定友町五字相生12他","lat":35.91456111,"lng":136.24759444,"geo_status":"db","era":"明治32年","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0214","desc":"ボイラー及び旧ロール場棟の北に接続して建つ。桁行約一八メートル、梁間約５・５メートルで、二階を仕上場、一階を塵取場に使った。内部は広い一室空間とし、上下階ともガラス窓を連続させて採光通風に工夫する。地場産業である製紙の最終工程を担う建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013384"},{"id":"00013381","register_sub_id":"101","register_pk":"368467","name":"信洋舎製紙所漉場棟","kana":"しんようしゃせいしじょすきばとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市定友町五字相生12他","lat":35.91444722,"lng":136.24771667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0211","desc":"大徳山麓の越前和紙の工房が並ぶ中に敷地を構える。桁行約一九メートル、梁間約6・5メートル、南北棟の工場建築で、内部を広い一室とする。紙を漉くための漉場として用いられる。採光通風のため、連続したガラス窓が内外の意匠を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013381"},{"id":"00013383","register_sub_id":"101","register_pk":"368469","name":"信洋舎製紙所ボイラー及び旧ロール場棟","kana":"しんようしゃせいしじょぼいらーおよびきゅうろーるばとう","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市定友町五字相生12他","lat":35.91441944,"lng":136.24755,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0213","desc":"旧休憩場及び張場棟の西、旧塵取場及び仕上場棟の南に接続して南北棟で建つ。一階をボイラー室とし、二階を艶付けのためのロール場として使った。簡素な建物であるが、内部には明治期の艶付ロール機器も残され、製紙業の手工業からの近代化の過程を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013383"},{"id":"00008856","register_sub_id":"101","register_pk":"162299","name":"鳥浜酒造煙突","kana":"とりはましゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県三方上中郡若狭町鳥浜59天田30","lat":35.55310419,"lng":135.904289,"geo_status":"db","era":"昭和前期／昭和49年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、高さ13m","structure_material":"煉瓦造","registered":"2011.10.28(平成23.10.28)","register_no":"18 － 0110","desc":"店舗兼醸造所の中央南側道路際に位置し、地中の煙道を通じて蔵前の蒸釜につながる煉瓦造の煙突である。基礎部分は方１．２ｍの正方形平面で、高さ１３ｍを測り、躯体はイギリス積で積み上げる。地域のシンボルとして親しまれる煉瓦煙突。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008856"},{"id":"00008855","register_sub_id":"101","register_pk":"162298","name":"鳥浜酒造店舗兼醸造所","kana":"とりはましゅぞうてんぽけんじょうぞうしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県三方上中郡若狭町鳥浜59天田30","lat":35.55322033,"lng":135.90416241,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積395㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"18 － 0109","desc":"敷地中央に南面して建つ。建築面積３９５㎡で、主体部を土蔵造二階建、寄棟造桟瓦葺の醸造所とし、南側に店舗兼作業所、西側に事務所を下屋として附属する。錣葺形式の大屋根が、通り沿いに建つ煙突とともに造り酒屋の風情ある景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008855"},{"id":"00002538","register_sub_id":"101","register_pk":"103528","name":"南部酒造場旧酒蔵大蔵","kana":"なんぶしゅぞうじょうきゅうさかぐらおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.984638,"lng":136.489777,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積152㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0019","desc":"前蔵の南方に建つ。前蔵とは棟方向を直交させた東西棟，切妻造，桟瓦葺，２階建の醸造蔵で，前蔵側と西面に入口を設ける。東妻面は１階部分を簓子下見，その上部を白漆喰塗とし，軒下の木製方杖や窓両脇の袖板などにより変化ある外観を四番通り側につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002538"},{"id":"00002537","register_sub_id":"101","register_pk":"103527","name":"南部酒造場旧酒蔵前蔵","kana":"なんぶしゅぞうじょうきゅうさかぐらまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.98474734,"lng":136.489822,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積146㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0018","desc":"南部家は明治から「茶木屋」の屋号で造り酒屋を営む。前蔵は店舗の南方に建つ。南北棟，切妻造，桟瓦葺，妻入の２階建酒蔵で，桁行９間，梁間４間規模を有す。当地方にみられる簓子下見の外壁，軒下に方杖を廻した土蔵で，方杖を鉄製とする点に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002537"},{"id":"00002540","register_sub_id":"101","register_pk":"103530","name":"南部酒造場米蔵","kana":"なんぶしゅぞうじょうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.9848373,"lng":136.4895927,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0021","desc":"西蔵の北方に建つ。西蔵とは棟方向を直交させた東西棟，切妻造，鉄板葺，妻入の２階建土蔵で，規模は桁行５間，梁間２間と西蔵よりも一回り小さい。外観は軒下に方杖をつけた当地方に広くみられる形式を持ち，敷地西辺に沿った背割下水側にも入口を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002540"},{"id":"00002536","register_sub_id":"101","register_pk":"103526","name":"南部酒造場店舗","kana":"なんぶしゅぞうじょうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.98502,"lng":136.489853,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積398㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0017","desc":"大野城下の中心地である七間通りと四番通りとが交差する南西角に北面して建つ。桁行５間半，梁間７間規模，切妻造，平入で，明治後期に西隣建物を購入しその東半を内部一体化する。当地方特有の袖壁を有した町家で，塔屋風越屋根がランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002536"},{"id":"00000727","register_sub_id":"101","register_pk":"101717","name":"平成大野屋本店二階蔵","kana":"へいせいおおのやほんてんにかいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県大野市元町1-1","lat":35.98530711,"lng":136.48720864,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造２階建，瓦葺，建築面積164㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"18 － 0008","desc":"敷地の北奥に位置する２階建の土蔵で，外壁を簓子下見貼とする。もと大七銀行所有の土蔵で，内部は欅材を用いた質実な造りとし，隣接する戦後の福井大地震後のブレース入り土蔵と対照をなす。織物検査場設備の一翼を担う建物として重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000727"},{"id":"00012524","register_sub_id":"101","register_pk":"367819","name":"平成大野屋本店平蔵","kana":"へいせいおおのやほんてんひらぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県大野市元町1-1","lat":35.985008,"lng":136.48703,"geo_status":"geocoded","era":"昭和28年／平成12年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積133㎡","structure_material":"土蔵造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"18 － 0194","desc":"敷地西北隅に南北棟で建つ。土蔵造平屋建、切妻造妻入で、南北二面に戸口を開く。鉄筋コンクリート造基礎に土台を据え、半間毎に立てた柱を胴差と筋交で固め、キングポストトラスの小屋組は方杖や火打梁で補強する。福井地震後の堅牢な構造技法の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012524"},{"id":"00000726","register_sub_id":"101","register_pk":"101716","name":"平成大野屋本店洋館","kana":"へいせいおおのやほんてんようかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県大野市元町1-1","lat":35.98506643,"lng":136.48722095,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造２階建，瓦葺，建築面積426㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"18 － 0007","desc":"大野織物工業協同組合の織物検査場として建設。絹織物の生産地として栄えた大野の町を象徴する建造物として親しまれている。織物検査室を真北に向け，北面に大きな連続窓を設けている点に特徴がある。設計は福井市の今藤仁三郎，施工は地元の山形甚吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000726"},{"id":"00015436","register_sub_id":"101","register_pk":"533451","name":"マタイチ醤油醸造場店舗兼主屋","kana":"またいちしょうゆじょうぞうじょうてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市南二丁目22","lat":35.89212778,"lng":136.16609167,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0261","desc":"北陸道に東面する醤油醸造業の店舗兼主屋。２階建切妻造平入桟瓦葺で一階は平格子を建て、二階外壁はモルタル塗仕上で軒を塗込め蛇腹を付す。一階は土間沿いに部屋を一列に並べ、二階西端は一五畳の座敷。土間内に井戸などを残し、醸造業の様相を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015436"},{"id":"00010448","register_sub_id":"101","register_pk":"199407","name":"安本酒造煙突","kana":"やすもとしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015656,"lng":136.27683,"geo_status":"db","era":"昭和前期／昭和中期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、高さ4.7m、面積1.1㎡","structure_material":"煉瓦造","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0131","desc":"仕込蔵一の北方に建つ煉瓦造煙突。焚口は仕込蔵内の蒸し場にあった。基部の外法が一辺約一メートルの正方形平面を持ち、イギリス積とする。昭和二三年の福井地震で被災し、現在は高さ約四・七メートルが残されている。酒造場の仕込み場の様子を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010448"},{"id":"00010449","register_sub_id":"101","register_pk":"199408","name":"安本酒造表門","kana":"やすもとしゅぞうおもてもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.01567487,"lng":136.27686891,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口3.8m、左右袖塀付","structure_material":"木造","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0132","desc":"店舗兼主屋の東側に、街道に面して建つ。腕木門で左右に袖塀を廻らす。間口が約三・八メートルと広く、繰形のついた女梁で男梁を差出し、軒の出は約九〇センチメートルと深めである。吹寄垂木の軒先に菱形の地紋彫を施した淀を取り付ける手の込んだ意匠の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010449"},{"id":"00010442","register_sub_id":"101","register_pk":"199401","name":"安本酒造米蔵","kana":"やすもとしゅぞうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015595,"lng":136.276602,"geo_status":"db","era":"明治21／明治後期改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0125","desc":"街道へ面する敷地の西北隅、主屋の西隣に並び建つ。二階建土蔵と、平屋建の倉庫からなる。土蔵は南北棟で上部を漆喰で仕上げて小窓をあけ、小屋を登梁とする。倉庫は東側に接続して建ち、切妻造桟瓦葺とし、越屋根を設ける。街道の歴史的な景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010442"},{"id":"00010444","register_sub_id":"101","register_pk":"199403","name":"安本酒造仕込蔵一","kana":"やすもとしゅぞうしこみぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015595,"lng":136.276859,"geo_status":"db","era":"明治22／昭和12改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造及び土蔵造平屋建並びに土蔵造2階建、瓦葺、建築面積205㎡","structure_material":"木造及び土蔵造平屋建並びに土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0127","desc":"主屋の東方、表門から煙突を挟んで南北に建つ長大な土蔵。北から旧精米所、旧酒米蒸し場と仕込場を配する。南側の仕込場は二階建土蔵で、一階に貯蔵タンクを並べ、二階に麹室を置く。外壁は漆喰塗で、腰を下見板張とする。酒造場の景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010444"},{"id":"00010445","register_sub_id":"101","register_pk":"199404","name":"安本酒造仕込蔵二","kana":"やすもとしゅぞうしこみぐらに","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015317,"lng":136.277023,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積102㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0128","desc":"上槽場の東に作業場を介して建つ。南北棟の二階建土蔵で、漆喰塗とし、軒下まで簓子下見板張とする。小屋組は登梁としており、内部は一本の独立柱のみで支える発達した構造を見せ、一階には仕込みに用いるタンクを並べる。造酒屋の歴史的な景観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010445"},{"id":"00010446","register_sub_id":"101","register_pk":"199405","name":"安本酒造上槽場","kana":"やすもとしゅぞうじょうそうば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015342,"lng":136.276866,"geo_status":"db","era":"大正7／昭和2改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造及び土蔵造平屋一部2階建、金属板葺及び瓦葺、建築面積197㎡","structure_material":"木造及び土蔵造平屋一部2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0129","desc":"仕込蔵一の南方に接続して建つ。上槽場は、上槽場及び作業場、冷蔵倉庫、旧酛場からなる。上槽場及び作業場は、木造平屋建で搾りなどを行う場所である。外観に現れる旧酛場は平屋建土蔵と下屋からなり、中塗仕上げの外壁が素朴な味わいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010446"},{"id":"00010441","register_sub_id":"101","register_pk":"199400","name":"安本酒造店舗兼主屋","kana":"やすもとしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.01559,"lng":136.276755,"geo_status":"db","era":"明治22／明治後期改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、金属板葺、建築面積156㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0124","desc":"一乗谷へ向かう旧街道沿いに北面する酒造所。店舗兼主屋は二階建の町家で、前後に下屋を付す。中央を玄関と店舗とし、西方に応接間、背面側に十畳座敷二室を配する。座敷は床と付書院を持ち、欄間などには繊細な組子細工を施しており、上質な飾りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010441"},{"id":"00010443","register_sub_id":"101","register_pk":"199402","name":"安本酒造土蔵","kana":"やすもとしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015349,"lng":136.276681,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0126","desc":"敷地西辺中央に位置する。南北棟の二階建土蔵、切妻造桟瓦葺で、妻壁の拝み部分に扇形の蔵印を施す。小屋組は登梁を地棟に架けている。二階に六箇所の窓が設けられ、漆喰塗の窓枠を外壁に張り出して、外観上のアクセントとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010443"},{"id":"00010447","register_sub_id":"101","register_pk":"199406","name":"安本酒造瓶詰め工場","kana":"やすもとしゅぞうびんづめこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015245,"lng":136.276859,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0130","desc":"敷地の南端に東西棟で建つ、平屋建の長い切妻造の建物である。南側外壁は真壁として腰に簓子下見板を張り、水平に連続する窓を設ける。内部は無柱の一室で、キングポストトラスの小屋組を架ける。南塀と一連の意匠になり、敷地背面の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010447"},{"id":"00010450","register_sub_id":"101","register_pk":"199409","name":"安本酒造南塀","kana":"やすもとしゅぞうみなみべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.01519155,"lng":136.27671858,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長12m","structure_material":"木造","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0133","desc":"敷地南辺、瓶詰め工場の西側に続く土塀。延長約一二メートルを測り、笏谷石の基礎の上に土台を廻して建つ。下部に簓子下見板を張り、中間部を土壁として、上部を開放する。東寄りに片引きの板戸、西寄りに竪格子の窓二所を開く。洗練された意匠で境界を画す塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010450"},{"id":"00004752","register_sub_id":"101","register_pk":"105742","name":"風間酒造酒造蔵","kana":"かざましゅぞうしゅぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山下於曽910","lat":35.69755666,"lng":138.72696383,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積250㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"19 － 0052","desc":"主屋背後に北面を道に接して建つ。桁行１２間，梁間６間，土蔵造２階建，桟瓦葺の置き屋根で，南面に下屋（オダレ）を掛ける。内部は独立柱を立て壁際を除き２階床を張り，中央桁行きに太い通し柱を並べ棟木を受ける。大規模で内外とも良質な酒造蔵の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004752"},{"id":"00013093","register_sub_id":"101","register_pk":"368366","name":"勝沼醸造主屋兼事務所","kana":"かつぬまじょうぞうしゅおくけんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎371","lat":35.65613889,"lng":138.71581111,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0142","desc":"旧甲州街道の南の県道に北面して建つ、ワイン醸造会社の主屋兼事務所。木造二階建、切妻造平入で東に土間を取り、西寄りの床上部は北から西に矩折に縁を廻らす。北西隅の座敷から縁を介して前庭を望む。北面二階に取付く縁と手摺が街路からの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013093"},{"id":"00013094","register_sub_id":"101","register_pk":"368367","name":"勝沼醸造樽貯蔵庫","kana":"かつぬまじょうぞうたるちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎371他","lat":35.65613889,"lng":138.7159,"geo_status":"db","era":"昭和24年頃／平成12年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0143","desc":"主屋の東に建つ樽貯蔵庫。桁行一三メートル梁間三･六メートルの南北に長い土蔵造二階建。外壁は漆喰仕上で腰壁を人造石洗出しとし、西面に二箇所の扉口を開く。内部は一階二階とも一室で、二階は和小屋を現しとする。主屋兼事務所と並び良質な景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013094"},{"id":"00008859","register_sub_id":"101","register_pk":"162302","name":"旧二葉屋酒造店舗兼主屋","kana":"きゅうふたばやしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県西八代郡市川三郷町市川大門1170","lat":35.68902778,"lng":138.6885,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"19 － 0066","desc":"市川大門の市街地、通りから少し入った位置に北面して建つ。木造二階建、寄棟造桟瓦葺、建築面積１７１㎡。東端に土間を通し、中央前方にミセ、後方に台所、西端及び二階に座敷を配し、二階座敷は数寄屋風意匠になる。近代店舗建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008859"},{"id":"00013095","register_sub_id":"101","register_pk":"368261","name":"くらむぼんワイン旧主屋","kana":"くらむぼんわいんきゅうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎字田中835他","lat":35.65551111,"lng":138.723225,"geo_status":"db","era":"明治後期／大正9年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0144","desc":"敷地中央に南面して建つ。木造二階建、切妻造の東西棟で中央に越屋根を載せる。一階は東に土間を取り、西寄り床上部は二列六室とする。南西隅の座敷には床、棚、付書院を置く。二階は西寄り四室を畳敷とする。養蚕農家の趣を残すワイン醸造家の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013095"},{"id":"00013096","register_sub_id":"101","register_pk":"368262","name":"くらむぼんワインワインセラー","kana":"くらむぼんわいんわいんせらー","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎字田中835他","lat":35.65562222,"lng":138.723125,"geo_status":"db","era":"明治後期／昭和前期増築、同48年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建一部地階付、金属板葺、建築面積97㎡","structure_material":"木造2階建一部地階付","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0145","desc":"旧主屋の北に東面して建つ。木造二階建の上屋の直下に地下室があり、北寄りの階段を下りて北から入る。建物外の西側にも、もとはブドウ冷蔵庫の地下室があり、周囲の川から水を引き込み上屋の地下に溜めて冷却した。市内でも希少なブドウ冷蔵庫の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013096"},{"id":"00000044","register_sub_id":"101","register_pk":"101034","name":"葡萄酒貯蔵庫（龍憲セラー）","kana":"ぶどうしゅちょぞうこ（りゅうけんせらー）","category":"産業2次","subcategory":"その他工作物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎1856","lat":35.65855909,"lng":138.72111101,"geo_status":"db","era":"明治32頃／大正14改造","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"半地下式、前室割石積庫内煉瓦積、建築面積57㎡","structure_material":"半地下式","registered":"1996.12.20(平成8.12.20)","register_no":"19 － 0003","desc":"ヨーロッパの貯蔵技術を導入してつくった我が国最初期の煉瓦造の半地下式葡萄酒貯蔵庫。建設に尽力した土屋龍憲の名をとって「龍憲セラー」の通称をもつ。明治の堅牢な煉瓦積みの技術を用いた建造物で，同様のものを建設することは困難である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000044"},{"id":"00013091","register_sub_id":"101","register_pk":"368259","name":"丸藤葡萄酒工業旧醸造蔵","kana":"まるふじぶどうしゅこうぎょうきゅうじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町藤井字三口神776他","lat":35.65002222,"lng":138.71495833,"geo_status":"db","era":"明治前期／大正後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0140","desc":"敷地中央に南面して建つ旧醸造蔵。土蔵造二階建、切妻造平入の屋根は置屋根形式とし、北面増築部分にかけて葺下ろす。外壁は漆喰塗で腰を竪羽目板張とする。内部は板敷で壁を漆喰塗とし、小屋組は登梁とする。ワイン醸造の中心施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013091"},{"id":"00013092","register_sub_id":"101","register_pk":"368260","name":"丸藤葡萄酒工業瓶貯蔵庫","kana":"まるふじぶどうしゅこうぎょうびんちょぞうこ","category":"産業2次","subcategory":"その他工作物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"山梨県","address":"山梨県甲州市勝沼町藤井字三口神776他","lat":35.65005556,"lng":138.71509444,"geo_status":"db","era":"昭和33年／昭和35年増築・平成6年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造、面積52㎡","structure_material":"鉄筋コンクリート造","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0141","desc":"敷地東辺に沿って建つ。鉄筋コンクリート造のもとワイン発酵用の貯蔵タンクで、現在は瓶貯蔵庫。細長い折曲がり平面で、内部は南半を五区画、北半を六区画に隔て、各区画の上部に液投入口、下部に排出口を穿つ。当時の醸造過程を伝える希少な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013092"},{"id":"00011132","register_sub_id":"101","register_pk":"205239","name":"横山酒造店店舗","kana":"よこやましゅぞうてんてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県南巨摩郡南部町南部8255","lat":35.28971,"lng":138.45565,"geo_status":"db","era":"大正5頃／昭和28頃・同30増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造3階建、瓦葺、建築面積103㎡","structure_material":"木造3階建","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0082","desc":"街路に挟まれた三角形敷地に建つ店舗兼住宅。当初は二階建であったが道路拡張に伴う縮小や増築を経て三階建となる。外壁は擬石仕上で石造風に見せる。内部造作は和風でまとめるが、天井など一部に洋風の要素を取り入れる。特異な外観が特徴のいわゆる看板建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011132"},{"id":"00000534","register_sub_id":"101","register_pk":"101524","name":"ルミエール旧地下発酵槽","kana":"るみえーるきゅうちかはっこうそう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県笛吹市一宮町南野呂624","lat":35.65455898,"lng":138.71129343,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"石造，建築面積203㎡","structure_material":"石造","registered":"1998.04.21(平成10.04.21)","register_no":"19 － 0025","desc":"葡萄酒の発酵タンク及び貯蔵タンクとして作られた。石造半地下式で，幅1.9m，奥行6.6m，高さ2.7mの発酵槽を10基備え，前面を地下通路でつないでいる。現在は上部をコンクリートで塞ぎ，工場が建てられているが，躯体部は堅固で現在も一部が使用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000534"},{"id":"00005174","register_sub_id":"101","register_pk":"106164","name":"飯田家住宅米蔵","kana":"いいだけじゅうたくこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.269344,"lng":137.920776,"geo_status":"db","era":"安政6／明治33増築","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積119㎡","structure_material":"土蔵造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0242","desc":"敷地の西辺，酛蔵の南に並ぶ土蔵造平屋建である。桁行９間，梁間３間，南北棟で建ち，切妻造，置屋根の桟瓦葺とする。東面の瓦葺庇も垂木を塗上げて置屋根とする。北から４間位置で間仕切り，東面に２箇所の戸口を設ける。西方からの屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005174"},{"id":"00005175","register_sub_id":"101","register_pk":"106165","name":"飯田家住宅醸造蔵一","kana":"いいだけじゅうたくじょうぞうぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26949059,"lng":137.92106455,"geo_status":"db","era":"明治後期／昭和初期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積405㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0243","desc":"敷地の北辺中央，酛蔵の東に接続する木造平屋建である。東西棟で，桁行２０間，梁間５間，切妻造，桟瓦葺とする。外壁は大壁造の白漆喰塗で，腰を下見板張とし，北面には竪格子入の窓を配す。小屋組は洋風トラスとする。北方からの屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005175"},{"id":"00005176","register_sub_id":"101","register_pk":"106166","name":"飯田家住宅醸造蔵二","kana":"いいだけじゅうたくじょうぞうぐらに","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26937806,"lng":137.92104479,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、鉄板葺、建築面積317㎡、煙突付","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0244","desc":"醸造蔵一の南に並ぶ木造平屋建の醸造蔵である。桁行１６間，梁間６間の東西棟で，勾配の緩い切妻屋根は鉄板葺とする。小屋組は和小屋である。外壁は大壁造の白漆喰塗で，腰を下見板張とし，竪格子入小窓を開く。煙突を併設し，東方からの屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005176"},{"id":"00005173","register_sub_id":"101","register_pk":"106163","name":"飯田家住宅酛蔵","kana":"いいだけじゅうたくもとぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.2695199,"lng":137.92080296,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0241","desc":"敷地の北西隅に位置する木造２階建で，東に醸造蔵一が接続する。桁行１０間，梁間５間の南北棟。切妻造，桟瓦葺で東面南半に瓦葺庇がつく。北端３間半を麹室とする。外壁は大壁造の白漆喰塗。小屋組は洋風トラスを採用する。北方からの屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005173"},{"id":"00005177","register_sub_id":"101","register_pk":"106167","name":"飯田家住宅物置一","kana":"いいだけじゅうたくものおきいち","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26919124,"lng":137.92071434,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0245","desc":"敷地西辺の中央，米蔵の南に建つ木造平屋建で，もとは酒米の精米に用いられた。桁行７間半，梁間４間で，屋根は切妻造，桟瓦葺とし，小屋組は洋風トラスとする。外壁は真壁造の白漆喰塗で，腰と南妻壁を下見板張りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005177"},{"id":"00012903","register_sub_id":"101","register_pk":"368006","name":"旧昭和興業製糸場","kana":"きゅうしょうわこうぎょうせいしじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市大字島立字新切2196-1他","lat":36.23153056,"lng":137.93308611,"geo_status":"db","era":"大正14年頃／平成8年移築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"20 － 540","desc":"松本市歴史の里に移築保存した製糸場繰糸所。北正面の木造平屋建、切妻造鉄板葺で、東から揚返場、繰糸場を並べ、正面西端の突出部に煮繭場を設ける。正背面の腰高の連続硝子窓や棟全体に通した越屋根など、近代製糸業の主流であった座繰工場の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012903"},{"id":"00004540","register_sub_id":"101","register_pk":"105530","name":"旧山一林組製糸事務所","kana":"きゅうやまいちばやしぐみせいしじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県岡谷市中央町1-13-17","lat":36.061237,"lng":138.04685193,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺一部亜鉛メッキ鋼板葺、建築面積316㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"20 － 0184","desc":"正面２４ｍ奥行１３ｍ規模，寄棟造，桟瓦葺の木造２階建で，正面中央西寄りに玄関車寄，２階軒に切妻破風を付ける。外装は大オーダー風の柱型を除いて煉瓦タイル張とし，上げ下げ窓を規則的に穿つ。岡谷を代表する製糸会社の本社事務所建築の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004540"},{"id":"00004541","register_sub_id":"101","register_pk":"105531","name":"旧山一林組製糸守衛所","kana":"きゅうやまいちばやしぐみせいししゅえいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県岡谷市中央町1-13-17","lat":36.06144542,"lng":138.04687017,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、亜鉛メッキ鋼板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"20 － 0185","desc":"事務所玄関車寄の北方に位置する正門の東脇に東西棟で建つ。下見板張の木造平屋建で，屋根は鉄板葺で，東を寄棟造，西を半寄棟造とし，南面に戸口を設け，西妻面に受付窓口を開ける。事務所とともに，岡谷における生糸生産施設の最盛期の面影を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004541"},{"id":"00013544","register_sub_id":"101","register_pk":"504911","name":"小泉家住宅店舗兼主屋","kana":"こいずみけじゅうたくてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県上田市中央四丁目6716-イ他","lat":36.40706944,"lng":138.25114722,"geo_status":"db","era":"明治前期／平成28年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"20 － 0568","desc":"上田城北東の染物業などを営んだ商家。道路に南面して建つ二階建切妻造に越屋根を掲げ、正面に下屋を付す。外壁は漆喰塗で、二階はたちが高く開口を大きくとる。内部は東を土間、西を居室とし、西端にも細い通り土間を通す。旧城下の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013544"},{"id":"00003095","register_sub_id":"101","register_pk":"104085","name":"坂井銘醸寛政蔵","kana":"さかいめいじょうかんせいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491219,"lng":138.150513,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積185㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0115","desc":"主屋の西方に位置し，屋敷地のほぼ中央に南北棟で建つ。桁行１２間規模の長大な切妻造，桟瓦葺の２階建土蔵で，中央に通路を開けた長屋門風の外観を呈する。階下はもと米蔵で，階高を高くとっていることが西面の２段の窓配置からも窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003095"},{"id":"00003096","register_sub_id":"101","register_pk":"104086","name":"坂井銘醸慶応蔵","kana":"さかいめいじょうけいおうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491405,"lng":138.150696,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積165㎡","structure_material":"土蔵造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0116","desc":"主屋の西方に位置し，宝暦蔵と寛政蔵との間に東西棟で建つ。切妻造，桟瓦葺の平屋建土蔵で，西半を麹室とし，主屋寄りの東半を釜場に充てる。釜場部は麹室部より棟を一段落としたつくりとし，棟中央に越屋根を載せ，東妻面近くに煙突を建てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003096"},{"id":"00003099","register_sub_id":"101","register_pk":"104089","name":"坂井銘醸昭和蔵","kana":"さかいめいじょうしょうわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491405,"lng":138.150452,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積242㎡","structure_material":"土蔵造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0119","desc":"宝暦蔵の西方，酒造場の西北隅部に南北棟で建つ。桁行１２間梁間６間規模，切妻造，桟瓦葺の平屋建仕込蔵で，内部は板張，小屋組はキングポストトラスとする。外部腰は人造石仕上げとし，高い位置の窓には鉄製持送り付きの小庇をつけて外観意匠を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003099"},{"id":"00003098","register_sub_id":"101","register_pk":"104088","name":"坂井銘醸大正蔵","kana":"さかいめいじょうたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.49148491,"lng":138.15089908,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積116㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0118","desc":"主屋の西方，宝暦蔵の南に接して建つ。東西棟，切妻造，桟瓦葺の木造２階建で，西面は慶応蔵釜場部の東北隅に食い込んだつくりとなる。杜氏，職方，奉公人等の宿泊居住棟で「広敷」と呼ばれる。造り酒屋の屋敷構えをつくる主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003098"},{"id":"00003094","register_sub_id":"101","register_pk":"104084","name":"坂井銘醸宝暦蔵","kana":"さかいめいじょうほうれきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491505,"lng":138.150696,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積377㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0114","desc":"文庫蔵の西方に続く，東西棟，切妻造，桟瓦葺の長大な２階建土蔵で，江戸時代以来の仕込蔵（酒造蔵）とされ，南方の釜場・麹室と並んで建つ。北面の低い位置に開けられた窓配置に特徴があり，昭和蔵とともに駅前通りに造り酒屋特有の景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003094"},{"id":"00003097","register_sub_id":"101","register_pk":"104087","name":"坂井銘醸明治蔵","kana":"さかいめいじょうめいじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県千曲市大字戸倉1855-1","lat":36.491245,"lng":138.150955,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積93㎡","structure_material":"土蔵造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"20 － 0117","desc":"主屋の西南方，寛政蔵の東方に位置する。桁行７間規模，東西棟，切妻造，桟瓦葺，平入の平屋建土蔵で，主屋背面裏庭に続く作業場に面して建つ。もと精米所で，北面屋根を葺き下ろして北面側に細長の作業スペースをつくっている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003097"},{"id":"00006228","register_sub_id":"101","register_pk":"107212","name":"塩屋醸造うわみせ","kana":"しおやじょうぞううわみせ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655876,"lng":138.315659,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積35㎡、門付","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0304","desc":"主屋の西隣に位置し，市道に沿い北面して建つ。桁行３間，梁間３間半規模，塗屋造２階建，平入の切妻造，桟瓦葺。１階は土間と板の間を配して店とし，２階はもと隠居部屋で，６畳の座敷２室を配する。２階正面軒を出桁造とし，主屋と趣の異なる外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006228"},{"id":"00006231","register_sub_id":"101","register_pk":"107215","name":"塩屋醸造穀蔵","kana":"しおやじょうぞうこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655571,"lng":138.315643,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積59㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0307","desc":"敷地の西端，手造蔵南隣に東面して建つ。桁行４間半，梁間４間，土蔵造平屋建，切妻造，桟瓦葺。内部は真壁造で，小屋組を和小屋とし，長大な梁を用いる。正面外観は間口幅に庇を付け，上部に窓を２つ並べる。全体に丁寧なつくりとし，敷地景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006231"},{"id":"00006229","register_sub_id":"101","register_pk":"107213","name":"塩屋醸造醤油蔵","kana":"しおやじょうぞうしょゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.65583,"lng":138.315582,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積162㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0305","desc":"うわみせ西側に接して，市道沿いに建つ。桁行１１間半，梁間４間規模，土蔵造平屋建，切妻造，桟瓦葺，東面，平入りとする。街路側に大きな妻を見せ，外壁中央に格子付の大きな窓を開き，楣部を虹梁形に整える等，街路沿いに堂々とした外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006229"},{"id":"00006230","register_sub_id":"101","register_pk":"107214","name":"塩屋醸造手造蔵","kana":"しおやじょうぞうてづくりぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655666,"lng":138.315643,"geo_status":"db","era":"江戸後期／昭和60改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積122㎡、煉瓦造室付","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0306","desc":"敷地の西端，醤油蔵南隣に東面して建つ。桁行６間，梁間６間規模，木造２階建，切妻造，桟瓦葺。内部に明治後期に造られた煉瓦造の麹室を２室設ける。外壁は中塗仕上げで，正面に庇を付けた戸口を設ける。規模が大きく，醸造施設の景観を形成する要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006230"},{"id":"00006234","register_sub_id":"101","register_pk":"107218","name":"塩屋醸造文庫蔵","kana":"しおやじょうぞうぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655716,"lng":138.31585544,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0310","desc":"主屋の南方に位置し，北面して建つ。桁行３間半，梁間２間半，土蔵造２階建，切妻造，桟瓦葺。外壁は漆喰塗，腰壁は正面を海鼠壁とし，他３面は下見板張。戸口は楣部を虹梁形に整え，掛子塗戸を吊り込む。窓枠や鉢巻等に黒漆喰を用い，風格ある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006234"},{"id":"00006233","register_sub_id":"101","register_pk":"107217","name":"塩屋醸造味噌蔵","kana":"しおやじょうぞうみそぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655464,"lng":138.315872,"geo_status":"db","era":"江戸後／明治初期増築・平成5改修","year":1790,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後","structure":"土蔵造平屋建、瓦葺、建築面積185㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0309","desc":"敷地の南端に位置し北面して建つ。桁行１４間，梁間４間，土蔵造平屋建。屋根は桟瓦葺の切妻造で，西側５間は明治初期に増築したものである。外壁は漆喰塗で，内部を２室に分け，それぞれの正面に戸口を設ける。規模が大きく，景観の要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006233"},{"id":"00006232","register_sub_id":"101","register_pk":"107216","name":"塩屋醸造諸味蔵","kana":"しおやじょうぞうもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県須坂市大字須坂537","lat":36.655445,"lng":138.315674,"geo_status":"db","era":"江戸後期／平成6改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積93㎡","structure_material":"土蔵造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"20 － 0308","desc":"敷地の南西隅に位置し，東面して建つ。桁行７間，梁間４間，土蔵造平屋建，切妻造，桟瓦葺。内部は真壁造，小屋組を和小屋とし，長大な梁を用いる。外壁は中塗仕上げで，腰を下見板張とする。簡素なつくりであるが，規模が大きく，醸造施設景観の要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006232"},{"id":"00007628","register_sub_id":"101","register_pk":"108610","name":"笑亀酒造穀蔵","kana":"しょうきしゅぞうこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県塩尻市大字塩尻町字町141-1","lat":36.103798,"lng":137.9743159,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積123㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0345","desc":"店舗兼主屋の西側に建つ。桁行１８ｍ梁間７．３ｍ規模の２階建土蔵。切妻造で、置屋根式の桟瓦葺とし、東面北寄りに下屋を付ける。１・２階境の高さまで海鼠壁とし、妻面に大小の窓を穿ち、格子を入れる。旧中山道沿いに面して建つ、重厚な構えの大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007628"},{"id":"00007629","register_sub_id":"101","register_pk":"108611","name":"笑亀酒造造蔵","kana":"しょうきしゅぞうつくりぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県塩尻市大字塩尻町字町141-1他","lat":36.10329489,"lng":137.974304,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積1011㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0346","desc":"敷地の南半を占める大型土蔵。桁行３８ｍ梁間１６ｍ、土蔵造２階建、切妻造で、置屋根式の桟瓦葺とし、北・西面に梁間６ｍ前後の広い下屋を張り出す。南・東面の１、２階に窓を規則的に配し、リズム感を与える。周辺環境の中において、際立った量感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007629"},{"id":"00007627","register_sub_id":"101","register_pk":"108609","name":"笑亀酒造店舗兼主屋","kana":"しょうきしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字塩尻町字町141-1他","lat":36.103703,"lng":137.974472,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積250㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"20 － 0344","desc":"旧中山道に北面して建つ。桁行１９ｍ梁間１１ｍ規模の木造２階建、切妻造桟瓦葺。１階外壁の両端を海鼠壁とし、庇上に波頭紋の役物瓦をあしらう。また中央の玄関両側にはスクラッチタイルを貼り、明治と昭和初めの意匠を融合した、重厚で特徴的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007627"},{"id":"00002035","register_sub_id":"101","register_pk":"103025","name":"巣山家住宅主屋","kana":"すやまけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県塩尻市大字木曽平沢字西町1561-1","lat":35.97926628,"lng":137.83019986,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積143㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"20 － 0089","desc":"木曽路にある平沢は奈良井宿の北に続く集落で，巣山家は代々漆器製造に携わってきた。主屋は通りに面した平入・２階建で，棟札より昭和８年の上棟である。正面は出桁で２階を前に持ち出し，両端に袖壁を設けるなど，伝統的なつくりをよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002035"},{"id":"00002037","register_sub_id":"101","register_pk":"103027","name":"巣山家住宅西土蔵","kana":"すやまけじゅうたくにしどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県塩尻市大字木曽平沢字西町1561-1","lat":35.97939852,"lng":137.83012869,"geo_status":"db","era":"明治32／昭和初期移築","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"20 － 0091","desc":"カミノクラと呼ばれ，もとは穀物を収蔵していたが，現在は工房に用いられている。棟木に明治３２年上棟の墨書があるが，昭和初期に現在地に移された。切妻造・２階建で，外壁は腰部を海鼠壁するが，上部の漆喰壁を上塗しないところは東土蔵と異なる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002037"},{"id":"00014484","register_sub_id":"101","register_pk":"513898","name":"セイコーエプソン創業記念館（旧大和工業事務所）","kana":"せいこーえぷそんそうぎょうきねんかん（だいわこうぎょうじむしょ）","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪市大和三丁目287-3","lat":36.05465,"lng":138.11534722,"geo_status":"db","era":"昭和20年／同43年頃増築、平成23年改修","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造2階建、瓦葺、建築面積193㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"20 - 0629","desc":"諏訪湖東岸に位置する時計部品製造会社の旧事務所。2階建寄棟造桟瓦葺で西に玄関ポーチを付す。外壁は下見板張とし、1、2階に連窓を多く配した開放的な外観。内部一階は西に寄せた片廊下、二階は中廊下式の平面。諏訪の時計製造の基点となった洋風事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014484"},{"id":"00001799","register_sub_id":"101","register_pk":"102789","name":"武重本家酒造及び武重家住宅一号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくいちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27379665,"lng":138.33922542,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積505㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0063","desc":"武重家が酒造業を開始した明治元年創業時の建物で，のちに南屋根面を延ばした形で釜場を増築している。越屋根付，桟瓦葺，切妻屋根，土蔵造の長大な建屋になり，南屋根面に三つの切妻造の大型屋根窓を突き出す。事務室を含む中心的酒造施設になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001799"},{"id":"00001795","register_sub_id":"101","register_pk":"102785","name":"武重本家酒造及び武重家住宅井戸小屋","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくいどごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27365579,"lng":138.33884111,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、鉄板葺、建築面積8.4㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0068","desc":"西蔵の北方，離れ石積擁壁の下に位置する桁行１間半，梁行２間規模の東西棟，鉄板葺切妻屋根，真壁造の簡素な建屋で，創業来の丸井戸の覆屋となる。現在，井戸水は深井戸ポンプにより離れ石積擁壁上の煉瓦造水槽に送られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001795"},{"id":"00001806","register_sub_id":"101","register_pk":"102796","name":"武重本家酒造及び武重家住宅奥穀ビツ","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくおくこくびつ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27404948,"lng":138.33884566,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0071","desc":"前穀ビツの北妻面側から北方に延び，北端で東方に折れ曲がるＬ字型平面の穀ビツ。桟瓦葺，切妻造で，前穀ビツと同様な造りとなるが，折れ曲がりの部分は物置とする。原料貯蔵の施設であるとともに，造り酒屋の発展過程を物語る施設でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001806"},{"id":"00001807","register_sub_id":"101","register_pk":"102797","name":"武重本家酒造及び武重家住宅枯倉","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくかれぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字用水尻2925-2","lat":36.27427362,"lng":138.33940842,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積210㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0072","desc":"屋敷地の北端に位置する桁行１７間，梁行４間規模のたちの高い建屋で，酒樽の用材を乾燥させておく施設。東西棟，桟瓦葺，切妻造で，内部を二層とし，南面全面に庇を差し掛ける。屋敷地拡張の過程を物語るとともに，造り酒屋としての構えの一構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001807"},{"id":"00001804","register_sub_id":"101","register_pk":"102794","name":"武重本家酒造及び武重家住宅旧細工小屋","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくきゅうさいくごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27374023,"lng":138.33876894,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0069","desc":"離れ北辺の石積擁壁の北に位置し，屋敷地西辺沿って建つ南北棟，桟瓦葺，切妻屋根，土蔵造の建屋で，東面に長く庇をさしだして平入とする。もと酒樽の製作場で，現在は資材置場となっている。造り酒屋の構えを構成する一要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001804"},{"id":"00001811","register_sub_id":"101","register_pk":"102801","name":"武重本家酒造及び武重家住宅旧精米所","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくきゅうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字東町2188-3","lat":36.27333151,"lng":138.33844959,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0076","desc":"離れ敷地の斜向かい，水路が交わる地点の角地に旧中山道に大きな妻面を見せて建つ。桁行５間，梁行５間規模の南北棟，桟瓦葺，切妻屋根，真壁造のもと精米所で，水車を旧中山道沿いの水路に設置していたものとみられる。造り酒屋関連施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001811"},{"id":"00001803","register_sub_id":"101","register_pk":"102793","name":"武重本家酒造及び武重家住宅五号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくごごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27401454,"lng":138.33900739,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積121㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0067","desc":"三号蔵の北に増築された桁行７間半規模の桟瓦葺，切妻屋根，土蔵造の酒蔵で，外観上は三号蔵と一体的につくり，さらに北へ糟場を増築している。東側面で四号蔵西妻面に連絡する。地棟下面の墨書から大正１１年３月上棟が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001803"},{"id":"00001801","register_sub_id":"101","register_pk":"102791","name":"武重本家酒造及び武重家住宅三号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27384655,"lng":138.33899404,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積164㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0065","desc":"一号蔵・二号蔵の西に建つ南北棟，桟瓦葺，切妻屋根，土蔵造の仕込蔵で，北に同一梁間の五号蔵が延長されている。内部の間内柱は厚板材を組立て，ボルト締めした特異な仕様をとる。酒蔵建築における構造技法の多様性を知るうえで興味深い事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001801"},{"id":"00001808","register_sub_id":"101","register_pk":"102798","name":"武重本家酒造及び武重家住宅炭小屋","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくすみごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県佐久市茂田井字東町2177-1","lat":36.27389074,"lng":138.33966021,"geo_status":"db","era":"江戸後期／明治42移築改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0073","desc":"二号蔵の東方，道路を隔てた敷地に建つ。道路に妻面を見せている木造２階建，桁行２間半梁行６間の真壁造建屋に桁行２間半梁行３間半の下見板張りの平屋を南に棟を直交させて張り出す。住宅主屋の改築の際に旧主屋の一部を移築したものと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001808"},{"id":"00001800","register_sub_id":"101","register_pk":"102790","name":"武重本家酒造及び武重家住宅二号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179他","lat":36.27387896,"lng":138.33923091,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積244㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0064","desc":"一号蔵の北方背後に，一号蔵と並列して建つ。東西棟，桟瓦葺，切妻屋根，土蔵造の仕込蔵で，一号蔵との間の西寄りに階段室，東端に洋風仕様の検査室を設ける。階上の東側を麹室に充てる。造り酒屋としての発展を物語る建物のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001800"},{"id":"00001805","register_sub_id":"101","register_pk":"102795","name":"武重本家酒造及び武重家住宅前穀ビツ","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくまえこくびつ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県佐久市茂田井字東町2179","lat":36.27397575,"lng":138.33882042,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0070","desc":"旧細工小屋の北方，屋敷地西辺に沿って建つ桟瓦葺，切妻造の細長い建屋。東面は出桁の造りとし，前面に低い切目縁を付ける。梁行１間で，片開戸口５戸前と横板を１２段に落込んだ戸口８戸前から成る。造り酒屋の原料貯蔵の様子を伝える施設として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001805"},{"id":"00001791","register_sub_id":"101","register_pk":"102781","name":"武重本家酒造及び武重家住宅もみ蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくもみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県佐久市茂田井字前田2140-2","lat":36.27302575,"lng":138.33903911,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0075","desc":"南蔵の南方に位置し，旧中山道に向かう道路に東妻面を見せて建つ東西棟，桟瓦葺，切妻屋根，置屋根形式の土蔵。桁行４間，梁行２間半の規模で，北面に下屋を差し掛けて蔵前をつくる。南蔵と同様に腰を押縁下見として旧中山道に向かう街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001791"},{"id":"00001802","register_sub_id":"101","register_pk":"102792","name":"武重本家酒造及び武重家住宅四号蔵","kana":"たけしげほんけしゅぞうおよびたけしげけじゅうたくよんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県佐久市茂田井字東町2179他","lat":36.27399782,"lng":138.33923646,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積185㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"20 － 0066","desc":"二号蔵の北方背後に並び建つ東西棟，桟瓦葺，切妻屋根，土蔵造の仕込蔵で，桁行１２間半，梁行４間半の規模を有し，一号蔵・二号蔵と同様に，二号蔵との間に階段室を納める。地棟下面の墨書により大正６年４月３０日の上棟が明らか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001802"},{"id":"00010294","register_sub_id":"101","register_pk":"199067","name":"長野銘醸粕蔵","kana":"ながのめいじょうかすぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1他","lat":36.516834,"lng":138.075672,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積67㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0471","desc":"敷地中央、酒蔵の北方に南北棟で建つ。桁行一一メートル梁間六・一メートル、土蔵造平屋建で、内部では酒粕の熟成を行っている。外壁は中塗仕上げとし、西面は腰に下見板を張る。もと南北に二棟であったものを、明治中期に壁を撤去し一体化したと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010294"},{"id":"00010293","register_sub_id":"101","register_pk":"199066","name":"長野銘醸米蔵","kana":"ながのめいじょうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-5他","lat":36.516668,"lng":138.075352,"geo_status":"db","era":"江戸末期／大正5年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、鉄板葺、建築面積149㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0470","desc":"敷地中央、酒蔵の西方に南北棟で建つ土蔵造平屋建。玄米や精米後の白米を貯蔵していた蔵で、古絵図から明治中期には南に水車小屋を併設してここで精米を行っていたと考えられる。現在は床を張らないが、大引の痕跡が確認できる。酒造工程の一端を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010293"},{"id":"00010290","register_sub_id":"101","register_pk":"199063","name":"長野銘醸酒蔵","kana":"ながのめいじょうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-5","lat":36.516549,"lng":138.075571,"geo_status":"db","era":"江戸末期／明治期・大正期・昭和20年・昭和42年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積529㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0467","desc":"敷地中央に南北棟で建つ。土蔵造二階建で、平面は大きく南北に分けられる。北半では洗米と絞り、南半では仕込みが行われる。二階はもと麹室や酒母室として使われ、酒造神である松尾社を祀る。酒造場の中心建物となる大型土蔵で、杜氏の営みを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010290"},{"id":"00010289","register_sub_id":"101","register_pk":"199062","name":"長野銘醸事務所","kana":"ながのめいじょうじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県千曲市大字八幡字中原272-5他","lat":36.516877,"lng":138.075842,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積198㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0466","desc":"敷地東寄りに南面して建つ木造二階建で、正面に起りのある切妻破風の式台を構える。一階は事務所や店舗などを配する。二階の内壁は鼠漆喰仕上げを基本とし、室境に筬欄間を入れ、大振りなトコにケヤキの一枚板を使うなど、贅沢な造作になる近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010289"},{"id":"00010291","register_sub_id":"101","register_pk":"199064","name":"長野銘醸貯蔵蔵","kana":"ながのめいじょうちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-5","lat":36.516572,"lng":138.075833,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積68㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0468","desc":"酒蔵の東方に南北棟で建ち、桁行九・七メートル梁間七・〇メートル、土蔵造平屋建である。登梁形式の小屋組を駆使して建ちの高い空間を実現し、外観は二層に見せる。たたき土間の内部には清酒の貯蔵タンクを並べる。作業庭に面し、酒造場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010291"},{"id":"00010300","register_sub_id":"101","register_pk":"199073","name":"長野銘醸長屋門","kana":"ながのめいじょうながやもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1","lat":36.51718765,"lng":138.07565004,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0477","desc":"敷地北辺東寄りに建ち、北国西脇往還に開かれた門。西半を門、東半を居室とし、かつては居室に門番が詰めたという。土蔵造二階建で、門の正面及び居室部分を漆喰塗仕上げとし、腰に下見板を張る。東土蔵とともに通り沿いの歴史的景観をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010300"},{"id":"00010298","register_sub_id":"101","register_pk":"199071","name":"長野銘醸西土蔵","kana":"ながのめいじょうにしどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1","lat":36.51706,"lng":138.075268,"geo_status":"db","era":"江戸末期／大正15年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0475","desc":"敷地北辺西寄り、北国西脇往還に面して建つ土蔵造二階建。外壁漆喰塗仕上げで水切と軒蛇腹を廻らし、通り沿いは腰を簓子下見板張とする。かつて旧主屋の座敷部が隣接して建っていた頃から家財道具を納めるための蔵として使われており、屋敷地の変遷を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010298"},{"id":"00010296","register_sub_id":"101","register_pk":"199069","name":"長野銘醸西納屋","kana":"ながのめいじょうにしなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1他","lat":36.516903,"lng":138.075647,"geo_status":"db","era":"江戸末期／明治30年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0473","desc":"敷地中央に位置し、粕蔵の北方に接続して建つ。長屋門から訪れた際に正面に位置する建物で、かつては店舗として使われたという。土蔵造平屋建で、外壁は中塗仕上げと簓子下見板張で整え、内部は床板張とする。南に連なる粕蔵とともに酒造場の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010296"},{"id":"00010297","register_sub_id":"101","register_pk":"199070","name":"長野銘醸東土蔵","kana":"ながのめいじょうひがしどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1","lat":36.517132,"lng":138.07556,"geo_status":"db","era":"江戸末期／大正15年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積30㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0474","desc":"敷地北辺、北国西脇往還に面して長屋門の西隣に建つ。桁行梁間とも五・五メートル、土蔵造平屋建で通り側を入母屋造とする。当初は大工小屋として使われ、酒蔵に使う木桶の修繕を行っていたとされる。通りに面して屋敷構えの景観をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010297"},{"id":"00010295","register_sub_id":"101","register_pk":"199068","name":"長野銘醸東納屋","kana":"ながのめいじょうひがしなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県千曲市大字八幡字中原274他","lat":36.516801,"lng":138.076095,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積87㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0472","desc":"敷地東辺中央に南北棟で建つ。土蔵造二階建で西面に吹放しの下屋を設ける。北半を物置、南半を居室とするが、かつて物置は味噌部屋、居室部は隠居部屋もしくは女中部屋として使われたという。小屋は他と異なり洋小屋である。敷地東面の景観を引き締める土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010295"},{"id":"00010299","register_sub_id":"101","register_pk":"199072","name":"長野銘醸文庫蔵","kana":"ながのめいじょうぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県千曲市大字八幡字中原272-1","lat":36.516939,"lng":138.075146,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0476","desc":"敷地の北西に位置し、庭部分に面して南北棟で建つ。土蔵造二階建で外壁を黒漆喰で仕上げ、水切と鉢巻を廻らす。東面の戸口のほか小窓を穿つが、比較的閉鎖的な外観とする。掛子塗を施した観音開の扉や窓庇の持送りなどに、高い左官技術を見せる家財蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010299"},{"id":"00010292","register_sub_id":"101","register_pk":"199065","name":"長野銘醸南蔵","kana":"ながのめいじょうみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県千曲市大字八幡字中原275-1他","lat":36.516382,"lng":138.075914,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積298㎡、煉瓦造煙突付","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0469","desc":"敷地南東方、貯蔵蔵の東に建つ。煉瓦造の煙突を囲むように矩折の平面を持つ土蔵造二階建で、屋根は置き屋根式である。丸太材の柱や梁を用いた和小屋と登梁形式を併用して大スパンを実現する。当初は瓶詰の工程を担った土蔵で、近代の酒造業の発展を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010292"},{"id":"00009165","register_sub_id":"101","register_pk":"164718","name":"東飯田酒造店酒蔵","kana":"ひがしいいだしゅぞうてんさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市篠ノ井小松原1724","lat":36.62010707,"lng":138.13286862,"geo_status":"db","era":"明治6年","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び鉄板葺、建築面積357㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地北辺に建つ。桁行35.0メートル梁間9.7メートル、土蔵造平屋1部2階建、切妻造妻入桟瓦葺及び鉄板葺で、東妻の出入口上部に虫籠窓を穿つ。内部は貯蔵蔵、舟場、酛部屋を備える。通り沿いにのびる大規模な土蔵で、犀川畔の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009165"},{"id":"00009167","register_sub_id":"101","register_pk":"164720","name":"東飯田酒造店漬物蔵","kana":"ひがしいいだしゅぞうてんつけものぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原1724","lat":36.61978584,"lng":138.1330566,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"土蔵の西側に並び建ち、桁行5.4メートル梁間3.6メートル、土蔵造2階建、切妻造桟瓦葺で、北面に下屋を設ける。外壁は漆喰塗で、扉廻りを黒漆喰で縁取り、軒裏は波形に塗籠めるなど丁寧な左官仕事になる。酒蔵とともに、創業期の様相を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009167"},{"id":"00009166","register_sub_id":"101","register_pk":"164719","name":"東飯田酒造店土蔵","kana":"ひがしいいだしゅぞうてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市篠ノ井小松原1724","lat":36.61978108,"lng":138.13315654,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"松の間の南側に北面して建つ。桁行10.9メートル梁間5.5メートル、土蔵造1部2階建、切妻造桟瓦葺で、北面に下屋を設ける。内部は東西に2分し、各々出入口を設けて米蔵とした。軸部は丸太柱を使い、下階床を煉瓦敷とする。造酒屋の施設構成を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009166"},{"id":"00003544","register_sub_id":"101","register_pk":"104534","name":"ふれあい館まゆぐら（旧田尻製糸）","kana":"ふれあいかんまゆぐら（きゅうたじりせいし）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂387-2","lat":36.65468593,"lng":138.30968724,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造3階建、瓦葺、建築面積145㎡","structure_material":"土蔵造3階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0148","desc":"地元の田尻製糸の繭蔵として建てられた３階建の土蔵で，現在地より約１８０ｍ南東の地から曳家し，体験や展示等の施設として活用されている。切妻造，桟瓦葺，桁行１０間と長大な規模で，外壁白漆喰塗，各面とも整然と各階の窓を並べた繭蔵らしい外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003544"},{"id":"00005149","register_sub_id":"101","register_pk":"106139","name":"松下家住宅作業所","kana":"まつしたけじゅうたくさぎょうしょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市松代町松代946","lat":36.56389766,"lng":138.20304987,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、鉄板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0217","desc":"敷地北側に位置し，主屋の背後に建つ。桁行８間半，梁間２間規模の木造平屋建で，鉄板葺の片流屋根を置く。北側外壁は外構を兼ね，南側は庭に向かい全面開口部となる。染物業の作業所として使われ，染物業を営む商家の屋敷の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005149"},{"id":"00008997","register_sub_id":"101","register_pk":"162357","name":"丸高蔵鰍沢蔵","kana":"まるたかぐらかじかざわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県諏訪市高島1-2952-1","lat":36.04123753,"lng":138.11327056,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵2階建、鉄板葺、建築面積272㎡","structure_material":"土蔵2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0394","desc":"吉沢蔵の南隣、通り沿いに建つ。桁行２６ｍ梁間１０ｍ、土蔵造二階建、切妻造鉄板葺で、東面に出入口を開く。外壁は漆喰仕上げで、鉢巻下まで高く竪板を張る。北から店舗、吉沢蔵と並び建ち、歴史的な景観を残す通りの主要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008997"},{"id":"00008996","register_sub_id":"101","register_pk":"162356","name":"丸高蔵吉沢蔵","kana":"まるたかぐらきっさわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県諏訪市高島1-2952-1","lat":36.04154955,"lng":138.1134143,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、鉄板葺、建築面積710㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0393","desc":"店舗の南隣に建つ。桁行３１ｍ梁間１０ｍ、土蔵造二階建、南北棟の寄棟造鉄板葺である。東面に出入口を開き、外壁は漆喰仕上げで腰高に竪板を張る。正背面に下屋を張り出し、北面に平屋建の棟を付属する。老舗醸造所の風格を示す大規模な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008996"},{"id":"00008995","register_sub_id":"101","register_pk":"162355","name":"丸高蔵店舗","kana":"まるたかぐらてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県諏訪市高島1-2952-1","lat":36.04180897,"lng":138.11351947,"geo_status":"db","era":"大正前期／平成18年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積262㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0392","desc":"上諏訪市街の通りに西面して建つ。桁行１０ｍ梁間１６ｍ、木造二階建、切妻造妻入鉄板葺で、伝統的な民家形式である本棟造の建物である。一階の正背面に深い庇を設け、二階の中央に出窓を設けるなど、本棟造独特の陰影のある外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008995"},{"id":"00003236","register_sub_id":"101","register_pk":"104226","name":"三原屋商店中蔵","kana":"みはらやしょうてんなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字長野字桜枝町879-1","lat":36.65845467,"lng":138.18342853,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積67㎡","structure_material":"土蔵造3階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0123","desc":"店舗南方に位置し，東面を「うちわや小路」に見せて建つ。桁行５間梁間４間規模の２階建土蔵に桁行３間半梁間２間，東西棟，寄棟造の３階部を載せ，南面で東蔵に連絡する。店舗裏口部の海鼠壁東面に連なり，小路沿い土蔵群景観に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003236"},{"id":"00003239","register_sub_id":"101","register_pk":"104229","name":"三原屋商店西蔵","kana":"みはらやしょうてんにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字長野字御殿1151-1","lat":36.65821067,"lng":138.18327257,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0126","desc":"南蔵の西方，屋敷地西辺沿いに位置し南北棟で建つ。桁行６間梁間２間半規模，桟瓦葺，切妻造の２階建土蔵で，平側東面のほぼ中央に出入口をとり，２階には南蔵との連絡口を設ける。醸造場南部土蔵群を構成する主要素のひとつで，味噌貯蔵庫として使用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003239"},{"id":"00003237","register_sub_id":"101","register_pk":"104227","name":"三原屋商店東蔵","kana":"みはらやしょうてんひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字長野字桜枝町879-1","lat":36.65825233,"lng":138.18338767,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積140㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0124","desc":"中蔵の南面に接して南北棟で建つ。桁行１０間梁間４間規模，桟瓦葺，切妻造の長大な２階建醤油醸造蔵で，東面は中蔵と同様に腰を簓子下見とし，南妻面には重厚な観音扉をもつ窓を左右対称に配置する。小路沿い土蔵群景観の構成要素中最も存在感のある土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003237"},{"id":"00003238","register_sub_id":"101","register_pk":"104228","name":"三原屋商店南蔵","kana":"みはらやしょうてんみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市大字長野字桜枝町879-1・字御殿1151-1","lat":36.65822486,"lng":138.18332591,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"20 － 0125","desc":"屋敷地南方，住居部との境界際に位置し，東蔵と西蔵に挟まれて建つ。桁行５間梁間２間半規模，東西棟，桟瓦葺，切妻造のたちの低い２階建土蔵で，もとは東半を麹室に充てる。平側南面のほぼ中央に出入口を設け，中庭側への物資の搬入にも重要な役割を果たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003238"},{"id":"00006535","register_sub_id":"101","register_pk":"107518","name":"蒲酒造場仕込蔵一","kana":"かばしゅぞうじょうしこみぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町6-6","lat":36.235146,"lng":137.186951,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積139㎡","structure_material":"土蔵造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0133","desc":"屋敷地の北西方に位置し，瀬戸川用水沿いに東西棟で建つ。桁行７間，梁間６間規模，切妻造，鉄板葺の平屋建土蔵で，用水側の北面に３箇所の小窓のほか，東寄りに搬出入用の戸口を開ける。瀬戸川用水の流れと白壁土蔵群がつくる景観の構成要素のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006535"},{"id":"00006533","register_sub_id":"101","register_pk":"107516","name":"蒲酒造場袖蔵","kana":"かばしゅぞうじょうそでぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町6-6","lat":36.23489122,"lng":137.18711906,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積106㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"21 － 0131","desc":"屋敷地の南東隅に位置し東西棟で建つ。桁行４間，梁行８間規模，切妻造，鉄板葺の２階建酒蔵で，主屋土間に面する西面北寄りに戸口を開ける。押縁下見板張に白漆喰塗の外観は維持管理が極めて良好で，主屋とともに壱之町通りのシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006533"},{"id":"00006189","register_sub_id":"101","register_pk":"107173","name":"菊川酒造一号・二号倉庫","kana":"きくかわしゅぞういちごう・にごうそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-543","lat":35.404125,"lng":136.93718,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積118㎡","structure_material":"土蔵造2階一部平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0113","desc":"敷地東端に南北棟で建ち，桁行１０間半，梁間３間の規模で，土蔵造２階一部平屋建，切妻造，桟瓦葺である。北側の一号倉庫は小屋組にキングポストトラスを用い，二号倉庫は登梁の和小屋を用いる。外壁は漆喰塗で，下半を下見板で養生し，酒造場の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006189"},{"id":"00006184","register_sub_id":"101","register_pk":"107168","name":"菊川酒造本蔵","kana":"きくかわしゅぞうほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県各務原市鵜沼西町1-543","lat":35.404503,"lng":136.936722,"geo_status":"db","era":"大正9頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積335㎡","structure_material":"土蔵造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"21 － 0111","desc":"旧鵜沼宿の中山道に面して建つ酒造蔵である。桁行１１間半，梁間７間半の規模で，土蔵造２階建，切妻造，桟瓦葺とする。南面に下屋を張り出す。外壁は漆喰塗で，外側に鉄板を張る。和小屋で登梁を使用する。規模が大きく，大きな梁を用い，架構技術に優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006184"},{"id":"00009962","register_sub_id":"101","register_pk":"196109","name":"玉泉堂酒造北酒蔵","kana":"ぎょくせんどうしゅぞうきたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30836112,"lng":136.55643272,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積246㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0227","desc":"南蔵と接続して、東西棟で建つ。桁行一〇間梁間六間、土蔵造二階建である。もとは仕込蔵として酒の仕込みを行っていた。二階にはもと麹室があり、別棟で蒸した米を二階で広げて温度調整を行っていた。樽を多数並べるため、大空間を実現した大型の蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009962"},{"id":"00009963","register_sub_id":"101","register_pk":"196110","name":"玉泉堂酒造検査室及び税務事務室","kana":"ぎょくせんどうしゅぞうけんさしつおよびぜいむじむしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30839615,"lng":136.55656862,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積43㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0228","desc":"北酒蔵の北正面東端に接続して建ち、南側を検査室、北側を税務事務室とする。検査室内部は真壁造、棹縁天井の和風とするのに対し、税務事務室は天井まで漆喰塗仕上げとして天井蛇腹を廻らし、腰を擬石塗とする洋風意匠である。当時の酒税事務を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009963"},{"id":"00009959","register_sub_id":"101","register_pk":"196106","name":"玉泉堂酒造小売り場","kana":"ぎょくせんどうしゅぞうこうりば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30853441,"lng":136.5567439,"geo_status":"db","era":"大正13／昭和中期改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0224","desc":"主屋の東側に並び建つ間口五・八メートルの二階建建物で、正面二階を黒漆喰塗として店舗兼主屋と調和させる。一階北半を小売り場とし、南半を物置とする。軸部は柱を半間毎に建て、隅には火打梁を設ける。戦前期の酒類小売りの様相を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009959"},{"id":"00009964","register_sub_id":"101","register_pk":"196111","name":"玉泉堂酒造洗米所","kana":"ぎょくせんどうしゅぞうせんまいじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30848717,"lng":136.55645796,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0229","desc":"主屋背面、北酒蔵の北西側下屋の先に位置する。切妻造の比較的小規模な建物で、もとは洗米と蒸米を行った。南面と東面には壁を設けず開放的にし、キングポストトラス組の陸梁の上にベルトを掛けたプーリーが残る。酒類の製造工程を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009964"},{"id":"00009958","register_sub_id":"101","register_pk":"196105","name":"玉泉堂酒造店舗兼主屋","kana":"ぎょくせんどうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126","lat":35.30859769,"lng":136.55660813,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、瓦葺、建築面積262㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0223","desc":"街道沿いに北面して建つ。間口一九メートルを測る大型の店舗兼主屋で、東寄りに土間を通し、西側に三室を三列に並べる。正面は一階に出格子をたて、二階は黒漆喰塗で柱形を表し、格子窓を並べ、両端に袖壁を設ける。外観や軸部構成ともに重厚で良質な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009958"},{"id":"00009960","register_sub_id":"101","register_pk":"196107","name":"玉泉堂酒造土蔵","kana":"ぎょくせんどうしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126","lat":35.30840235,"lng":136.55666284,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0225","desc":"主屋の東背面に位置する。内向きの家財道具のための蔵で、南北棟で北を正面とする。基礎は切石を三段積む。外壁は黒漆喰で塗り込め、正面出入口扉脇の腰壁を蜀江文様風の意匠に仕上げ、正面扉や二階の窓は掛子塗戸とするなど、高い左官技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009960"},{"id":"00009961","register_sub_id":"101","register_pk":"196108","name":"玉泉堂酒造南酒蔵","kana":"ぎょくせんどうしゅぞうみなみさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県養老郡養老町高田字町126他","lat":35.30822157,"lng":136.55628538,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積308㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0226","desc":"敷地南側に南北棟で建ち、北妻面は北酒蔵と接続する。桁行一二間梁間六間、土蔵造二階建である。貯蔵蔵で、もとは北酒蔵で作られた醪を、酒粕と清酒に分け、精製して熟成させ、瓶詰めする作業が行われていた。二重梁の和小屋を架けて広い梁間を確保する大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009961"},{"id":"00010302","register_sub_id":"101","register_pk":"199075","name":"日下部味噌醤油醸造煉瓦館","kana":"くさかべみそしょうゆじょうぞうれんがかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市上一之町93-1","lat":36.141094,"lng":137.261097,"geo_status":"db","era":"大正11年／昭和50年頃・平成2年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積86㎡","structure_material":"煉瓦造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"21-0236","desc":"醤油醸造所の醤油蔵として建てられた。煉瓦造二階建、妻入りで、軒蛇腹を廻らしてデンティルを飾り、西正面にコーニスを設け、水平アーチ窓を三所穿ち鉄扉を開く。町家主体の街並み景観に変化を与える存在で、市内で数少ない煉瓦造建築としても価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010302"},{"id":"00007036","register_sub_id":"101","register_pk":"108018","name":"小町酒造通用門","kana":"こまちしゅぞうつうようもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.4221053,"lng":136.86183893,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、瓦葺、間口4.1m","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0164","desc":"敷地東面の中央に位置し、北は本蔵、南は便所に取り付く。両下造桟瓦葺。間口４．１ｍで、中央戸口２．３ｍに両開板戸をたて、南に袖塀、北に潜りを設ける。主柱は小平柱で、腕木により軒を持ち出す。大きく開く入八双金物が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007036"},{"id":"00007032","register_sub_id":"101","register_pk":"108014","name":"小町酒造店舗兼主屋","kana":"こまちしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.42205793,"lng":136.86174635,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0160","desc":"３方を道路に囲まれた敷地南側に南面して建つ。木造２階建、切妻造桟瓦葺とし、建築面積は１５４㎡。東側を土間の店舗などとし、西側を４間取の床上部とする。外壁は黒漆喰仕上げとし、軒は出桁造。重厚な外観に杉玉を飾り、酒造業としての風格を醸し出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007032"},{"id":"00007034","register_sub_id":"101","register_pk":"108016","name":"小町酒造土蔵","kana":"こまちしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.421986,"lng":136.861801,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0162","desc":"敷地南東隅に通りに面して建ち、店舗兼主屋に接する。土蔵造２階建、切妻造桟瓦葺で、桁行６．６ｍ梁間３．８ｍ。丸石積基礎とし、外壁は漆喰仕上げで黒塗の板を張る。南側各階の窓に持送り付の庇を付け、外観に変化を与える。落ち着きのある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007034"},{"id":"00007033","register_sub_id":"101","register_pk":"108015","name":"小町酒造離れ","kana":"こまちしゅぞうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.42203903,"lng":136.86157438,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0161","desc":"敷地の南西、店舗兼主屋の西側に建つ。木造平屋建、入母屋造桟瓦葺で、南北に８畳２室を並べ、東に畳廊下、南・北に榑縁、３方に落縁を設ける。主座敷はトコと違棚、付書院を構え、その南を庭園とする。数寄屋風意匠を採り入れた近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007033"},{"id":"00007035","register_sub_id":"101","register_pk":"108017","name":"小町酒造門及び塀","kana":"こまちしゅぞうもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市蘇原伊吹町2-15","lat":35.42193556,"lng":136.86159073,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.2m 塀 木造、瓦葺、延長21m","structure_material":"門 木造","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0163","desc":"店舗兼主屋から離れまで、庭園を囲むようにコの字状に配された総延長２１ｍの塀。東面には切妻造桟瓦葺の腕木門を構える。丸石を亀甲状に積み石垣とし、通り側には黒漆喰に腰板張、庭園側を弁柄色の色壁とする。丸石積が印象的な屋敷構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007035"},{"id":"00011135","register_sub_id":"101","register_pk":"205242","name":"天領酒造店舗兼主屋","kana":"てんりょうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県下呂市萩原町萩原字町頭1289-1","lat":35.875935,"lng":137.209079,"geo_status":"db","era":"明治44頃／大正4頃増築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積237㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"21 - 0243","desc":"益田街道に面して建つ。店舗兼主屋は明治四四年の大火後に再建された。街路側南半を土間のチョウバとし、その奥にトオリドウジ（土間廊下）を通して居室を配する一方、オモテ北半の北東側にもオクノマ、ブツマを張出すなど、当地方の標準的な平面になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011135"},{"id":"00009954","register_sub_id":"101","register_pk":"196101","name":"美濃窯業株式会社瑞浪工場角型煙突","kana":"みのようぎょうかぶしきがいしゃみずなみこうじょうかくがたえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県瑞浪市寺河戸町字上門田921-4他","lat":35.36588634,"lng":137.24954597,"geo_status":"db","era":"大正9／昭和7・平成17改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造、高さ26m","structure_material":"煉瓦造","registered":"2014.04.25(平成26.04.25)","register_no":"21 － 0219","desc":"煉瓦造、イギリス積で、基部の平面は二・三メートル角の正方形とし、高さは二六メートルを測る。腰部に装飾的な帯状部を設け、現在は鉄製アングル材で補強している。窯業が盛んな東濃地方に残るものとして最大級の煉瓦煙突であり、当地の近代産業史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009954"},{"id":"00010596","register_sub_id":"101","register_pk":"201170","name":"美濃窯業株式会社瑞浪工場丸型煙突","kana":"みのようぎょうかぶしきがいしゃみずなみこうじょうまるがたえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県瑞浪市寺河戸町字上門田924-1","lat":35.365371,"lng":137.249942,"geo_status":"db","era":"昭和10年／昭和62年・平成16年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"煉瓦造、高さ24m","structure_material":"煉瓦造","registered":"2015.08.04(平成27.08.04)","register_no":"21－0238","desc":"工場建物の南東寄りに位置する。小口積の煉瓦造で、基部平面は直径三メートルの円形とし、高さは二四メートルを測る。現在は鉄製アングル材で補強される。窯業が盛んな当地の歴史を物語る遺構として価値があり、同工場の角形煙突とともにランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010596"},{"id":"00008459","register_sub_id":"101","register_pk":"134855","name":"三輪酒造北蔵","kana":"みわしゅぞうきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県大垣市南切石町1-45-1","lat":35.35498842,"lng":136.6104572,"geo_status":"db","era":"明治21年","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積398㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"21 － 0192","desc":"運河を埋め立てた街路の南に占める敷地の中央南寄りに位置する。桁行二二メートル梁間一四メートル、南北棟の切妻造桟瓦葺の西側に、梁間四・六メートルの招屋根を付ける。土蔵造二階建で、外壁は下見板張、内壁は漆喰仕上げとする。大規模な醸造蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008459"},{"id":"00008460","register_sub_id":"101","register_pk":"134856","name":"三輪酒造南蔵","kana":"みわしゅぞうみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県大垣市南切石町1-45-1","lat":35.35478029,"lng":136.6105345,"geo_status":"db","era":"明治20年","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積361㎡","structure_material":"土蔵造3階建","registered":"2011.01.26(平成23.01.26)","register_no":"21 － 0193","desc":"敷地南端、小路に面する。東西棟で、棟高や梁間等が異なる三部分に分かれる。総桁行三三メートル梁間最大一四メートル、土蔵造三階建で、西端部のみ二階建。切妻造桟瓦葺とし、川石を積み上げた基礎上、鉢巻まで高く下見板を張り、重厚な街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008460"},{"id":"00004972","register_sub_id":"101","register_pk":"105962","name":"渡邉家住宅酒蔵","kana":"わたなべけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県飛騨市古川町壱之町7-3","lat":36.23556276,"lng":137.18624021,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積133㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"21 － 0065","desc":"敷地後方北端の瀬戸川沿いにあり，古川を特長づける土蔵群の町並景観の構成要素である。土蔵造２階建で，南面１階に観音開扉を構え，東面と南面に窓を設ける。小屋は登梁式，屋根は置屋根式鉄板葺で，外壁は漆喰塗とする。造酒屋の屋敷構成に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004972"},{"id":"00009965","register_sub_id":"101","register_pk":"196112","name":"旧片岡醸造所酒蔵","kana":"きゅうかたおかじょうぞうしょさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県島田市横岡新田字新宿193","lat":34.84517787,"lng":138.11452343,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積397㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"22 － 0193","desc":"大井川右岸の敷地後方に東西棟で建ち、土蔵造二階建、桁行二八メートル梁間一五メートル、寄棟造桟瓦葺である。外壁は漆喰塗で各階の上部に窓を並べる。主構造は側柱と三本の丸太の独立柱で構成し、広大な内部空間をつくる。造酒屋の盛期を伝える大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009965"},{"id":"00009608","register_sub_id":"101","register_pk":"194604","name":"旧丸四織物合名会社倉庫（ドルチェ倉庫）","kana":"きゅうまるしおりものごうめいがいしゃそうこ（どるちぇそうこ）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市福田字村前東4447-2他","lat":34.67502148,"lng":137.87889028,"geo_status":"db","era":"昭和前期／平成9改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、建築面積129㎡","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"22 － 0192","desc":"敷地の南東に建つもと織物工場の木造倉庫。切妻造桟瓦葺で、北面に下屋を設けて中央を入口とする。外壁は下見板張で、東、南、西の各面二箇所に両開窓、両妻に高窓を開く。小屋裏二階の床は撤去し、二重梁和小屋の小屋組を現す。地場産業の名残を伝える倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009608"},{"id":"00014833","register_sub_id":"101","register_pk":"519093","name":"匂阪家住宅（鶴屋本店）隠居部屋","kana":"さぎさかけじゅうたく（つるやほんてん）いんきょべや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県磐田市見付3497","lat":34.72690556,"lng":137.85553889,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0328","desc":"見付宿の中ほど、通りに東面して建つ味噌醤油醸造元の隠居屋。北側に文庫蔵が接続する。二階建桟瓦葺の南北棟で東面南寄りに玄関を設ける。内部は上下階とも続き間座敷とし各階南西に縁を廻らす。座敷は平書院の下地窓など瀟洒な意匠を取入れた近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014833"},{"id":"00014834","register_sub_id":"101","register_pk":"519094","name":"匂阪家住宅（鶴屋本店）文庫蔵","kana":"さぎさかけじゅうたく（つるやほんてん）ぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県磐田市見付3498","lat":34.72695,"lng":137.85550833,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造3階建、瓦葺、建築面積45㎡","structure_material":"木造3階建","registered":"2024.03.06(令和6.03.06)","register_no":"22 - 0329","desc":"隠居部屋の北に接続して東西棟で建つ。土蔵造三階建切妻造桟瓦葺で、東面を戸口として下屋を付す。伊豆石の布積基礎に建ち、外壁漆喰塗で水切二段を付し、二、三階の両妻に窓を開け、掛子塗の扉を両開きとする。見付宿の歴史的な景観に寄与する三階建土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014834"},{"id":"00009607","register_sub_id":"101","register_pk":"194603","name":"寺田家住宅主屋（旧丸四織物合名会社事務所兼主屋）","kana":"てらだけじゅうたくしゅおく（きゅうまるしおりものごうめいがいしゃじむしょけんしゅおく）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市福田字村前東4447-2他","lat":34.67526894,"lng":137.87871658,"geo_status":"db","era":"昭和12／昭和42改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"22 － 0191","desc":"綿織物工場主の住宅で、木造二階建、切妻造桟瓦葺である。寄棟造の南東突出部は下見板張で、上下階に二つずつ並ぶ上下窓が外観を特徴づける。内部は一階南東室が洋室、一階八畳、二階一〇畳の座敷に座敷飾を備え、南面に広縁がつく。洋間付の良質な近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009607"},{"id":"00011506","register_sub_id":"101","register_pk":"210535","name":"明治屋醤油醸造所","kana":"めいじやしょうゆじょうぞうじょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市浜北区小松2276","lat":34.79055,"lng":137.77480889,"geo_status":"db","era":"明治前期／大正前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階一部平屋建、醪蔵部鉄筋コンクリート造平屋建、瓦葺一部銅板葺、建築面積774㎡","structure_material":"木造2階一部平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"22-0233","desc":"敷地東北寄りに建つ。南東隅部分が当初で、その後増築を繰り返して複雑な構成を取るが、東側街路寄りに香辛料倉庫・穀物倉庫、南方に圧搾等の機能を配し、北西側には鉄筋コンクリート造の醪蔵があり、中央部分に麹室を配する。醸造業の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011506"},{"id":"00011504","register_sub_id":"101","register_pk":"210533","name":"明治屋醤油店舗兼主屋","kana":"めいじやしょうゆてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市浜北区小松2276","lat":34.79027806,"lng":137.77467194,"geo_status":"db","era":"明治前期／大正6年増築、平成27年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"22-0231","desc":"浜松市街地の北方に位置する。敷地東寄りに街路に面して建ち、切妻造桟瓦葺の木造平屋建を二棟並べた構成をとるが、東棟は大正六年の増築。平面は三列構成となり、街路側は店舗、敷地内側は居室を配する。特徴的な構造をとる店舗兼主屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011504"},{"id":"00011505","register_sub_id":"101","register_pk":"210534","name":"明治屋醤油離れ","kana":"めいじやしょうゆはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市浜北区小松2276","lat":34.79023111,"lng":137.77452,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"22-0232","desc":"主屋の南西側に雁行して建つ。切妻造の二階建部分の東・南に下屋を張出し、北には玄関、西には浴室を張出す。一階は八畳座敷と六畳次の間の三方に広縁を廻らし、二階も八畳座敷、六畳次の間の二室構成とする。建ちの高い外観が特徴的な近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011505"},{"id":"00012377","register_sub_id":"101","register_pk":"531701","name":"愛知製鋼刈谷工場旧試作工場西棟（旧豊田自動織機製作所自動車部試作工場）","kana":"あいちせいこうかりやこうじょうきゅうしさくこうじょうにしとう（きゅうとよだじどうしょっきせいさくしょじどうしゃぶしさくこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県刈谷市豊田町三丁目6","lat":34.99086111,"lng":136.9977,"geo_status":"db","era":"昭和9年／昭和20年代改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積758㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"23-516","desc":"豊田自動織機製作所に建設された自動車の試作工場の西半部。東西棟の木造平屋建で、小屋組はキングポストトラス。外壁は亜鉛鉄板張で、内部の独立柱にも亜鉛鉄板を巻く。方杖を用いて柱と小屋組を緊結し、耐震性能を確保するため工夫がみられる工場建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012377"},{"id":"00012376","register_sub_id":"101","register_pk":"531700","name":"愛知製鋼刈谷工場旧試作工場東棟（旧豊田自動織機製作所自動車部試作工場）","kana":"あいちせいこうかりやこうじょうきゅうしさくこうじょうひがしとう（きゅうとよだじどうしょっきせいさくしょじどうしゃぶしさくこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県刈谷市豊田町三丁目6","lat":34.99076944,"lng":136.9982,"geo_status":"db","era":"昭和9年／昭和20年代改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積934㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"23-515","desc":"豊田自動織機製作所に建設された自動車の試作工場の東半部。東西棟の木造平屋建で、小屋組はキングポストトラス。内部は中央柱筋に独立柱が並んだ一つの空間とする。トヨタ自動車のＡ１型試作乗用車が誕生した工場として我が国の自動車産業史に名を残す建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012376"},{"id":"00004137","register_sub_id":"101","register_pk":"105127","name":"旭サナック本館（旧旭兵器製造本社事務棟）","kana":"あさひさなっくほんかん（きゅうあさひへいきせいぞうほんしゃじむとう）","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県尾張旭市旭前町新田洞5050","lat":35.217331,"lng":137.020401,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積338㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"23 － 0133","desc":"木造２階建で，屋根は寄棟造，鉄板葺。当初は外壁を下見板張としていたが，現状はモルタル吹付である。内部は１階を主に事務室とし，２階には応接間等を配するが，２階主要室は木部と漆喰による質の高い内装を持つ。洋風を基調とする事務所建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004137"},{"id":"00000215","register_sub_id":"101","register_pk":"101205","name":"窯のある広場・資料館（倒焔式角窯）","kana":"かまのあるひろば・しりょうかん（とうえんしきかくがま）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県常滑市奥栄町一丁目112","lat":34.88194628,"lng":136.8486342,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建，瓦葺，建築面積373㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0006","desc":"煉瓦造の倒焔式角窯を含む、木造２階建の上屋である。昭和46年まで土管、焼酎瓶、クリンカタイル等を製造していたが、その後資料館として整備された。独特のテクスチャーを持つ角窯と、黒い外壁の上屋で、焼物の町常滑のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000215"},{"id":"00000216","register_sub_id":"101","register_pk":"101206","name":"窯のある広場・資料館煙突","kana":"かまのあるひろば・しりょうかんえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県常滑市奥栄町一丁目112","lat":34.88186981,"lng":136.84855652,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造，高さ21m","structure_material":"煉瓦造","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0007","desc":"土管焼成用の窯に付属する煉瓦造の煙突である。根本の部分は2.2メートル四方であり、上部に向かってやや逓減する。かつては常滑市内に同様の煙突が数多くあったが、現在ではその多くが失われており、常滑市のランドマークの一つとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000216"},{"id":"00004982","register_sub_id":"101","register_pk":"105972","name":"甘強味淋工場","kana":"かんきょうみりんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県海部郡蟹江町城4-1","lat":35.13130593,"lng":136.79012156,"geo_status":"db","era":"明治10／明治39・大正2増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積759㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"23 － 0206","desc":"敷地東にコの字型平面で建つ。北辺が古く，次に西辺が増築，これより東に延びた南辺が増築，現在の形となった。土蔵造２階建を基本とするが，一部煉瓦壁を用い，外壁の高い位置に窓を整然と並べる。伝統産業の発展過程を示す施設で，独特の景観を創っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004982"},{"id":"00011730","register_sub_id":"101","register_pk":"210746","name":"旧中七木綿本店北蔵","kana":"きゅうなかしちもめんほんてんきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28","lat":34.966809,"lng":136.865742,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23 - 0500","desc":"敷地の西端で南蔵の北に建つ。桁行九・一メートル、梁間五・五メートル、切妻造桟瓦葺で、正面に南蔵から一連に続く蔵前を付ける。内部は一・二階とも一室とし、北面に窓を開く。南蔵とともに重厚な外観を見せ、街路からの景観を形成する大型の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011730"},{"id":"00011729","register_sub_id":"101","register_pk":"210745","name":"旧中七木綿本店作業所・寄宿舎","kana":"きゅうなかしちもめんほんてんさぎょうしょ・きしゅくしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28","lat":34.966662,"lng":136.865918,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積190㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23 - 0499","desc":"主屋（旧事務所）の背後の敷地北側に建つ。平屋建の作業所と二階建の寄宿舎を東西に接続させる。作業所は、木綿製品を梱包する作業を行っていたが、黒漆喰塗の主屋と揃えた外観を持つ。寄宿舎は後に住居として転用されたが、二階には往時の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011729"},{"id":"00011725","register_sub_id":"101","register_pk":"210741","name":"旧中七木綿本店主屋（旧事務所）","kana":"きゅうなかしちもめんほんてんしゅおく（きゅうじむしょ）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28-1","lat":34.966587,"lng":136.865775,"geo_status":"db","era":"大正3年／昭和20年移築","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0495","desc":"知多半島西海岸北部に位置する。木造二階建、入母屋造桟瓦葺。中央東寄りに玄関を開き、西に旧事務所を配置し、二階にはかつて接客のために用いられた二室を配す。やや起りのある屋根には屋号が入った鬼瓦を用い、外壁は黒漆喰塗とし、重厚な外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011725"},{"id":"00011727","register_sub_id":"101","register_pk":"210743","name":"旧中七木綿本店長屋門","kana":"きゅうなかしちもめんほんてんながやもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28-1","lat":34.966421,"lng":136.865777,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0497","desc":"敷地の南・東面を画す矩折れ平面の寄棟造桟瓦葺。東西棟は間口一九メートルでやや東寄りに門口を開き、両脇は納屋。南北棟は旧食事室や浴室、賄い部屋などを配し、社員の生活に必要な設備を備える。外壁は漆喰塗腰板張とし、重厚な表構えで街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011727"},{"id":"00011728","register_sub_id":"101","register_pk":"210744","name":"旧中七木綿本店塀","kana":"きゅうなかしちもめんほんてんへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28-1","lat":34.96648306,"lng":136.8659,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、延長6.2m","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"23-0498","desc":"長屋門から敷地東面を画す。敷地の高低差に応じて、棟を三段に下げながら続く。下見板張の上部を漆喰塗とし、要所に格子窓を開く。切妻屋根上には屋号入りの鬼瓦を載せる。長屋門と一体となり、地域の歴史的景観を形成する塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011728"},{"id":"00011726","register_sub_id":"101","register_pk":"210742","name":"旧中七木綿本店南蔵","kana":"きゅうなかしちもめんほんてんみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県知多市岡田字開戸28-1","lat":34.966731,"lng":136.865666,"geo_status":"db","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積107㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0496","desc":"敷地の西端に東面する。桁行九・一メートル、梁間五・四メートル、切妻造桟瓦葺で、正面に奥行二間の蔵前を付ける。内部は中央北寄りに通し柱を立て、小屋は牛梁に登梁を架ける。外壁は鉢巻まで下見板を張り、二階南面のみ窓を開く。木綿製品を貯蔵するための蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011726"},{"id":"00013404","register_sub_id":"101","register_pk":"368489","name":"葛利毛織工業株式会社主屋","kana":"くずりけおりこうぎょうかぶしきがいしゃおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33523056,"lng":136.75968611,"geo_status":"db","era":"昭和24年頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積186㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0551","desc":"敷地南端中央の門を入って東側に建つ。木造二階建、寄棟造桟瓦葺で、東西棟の住居と南北棟の倉庫を、Ｌ字形に繋ぐ。外壁は下見板張、ペンキ塗仕上を基本とし、一階下屋部分は真壁、漆喰仕上、腰を竪板張とする。職住一体の工場施設の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013404"},{"id":"00013407","register_sub_id":"101","register_pk":"368492","name":"葛利毛織工業株式会社旧浴場及び便所","kana":"くずりけおりこうぎょうかぶしきがいしゃきゅうよくじょうおよびべんじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33536389,"lng":136.75969444,"geo_status":"db","era":"昭和30年頃／昭和30年代増築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0554","desc":"工場の南東、男子寮の東に建つ、木造平屋建、切妻造桟瓦葺。外壁は漆喰塗仕上げで、腰はモルタル塗仕上とする。西側の浴場は、更に東西に分かれ、東を男性、西を女性の浴室とする。通路を挟んで東側に便所を南北に並べる。工場を構成するの附属施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013407"},{"id":"00013409","register_sub_id":"101","register_pk":"368494","name":"葛利毛織工業株式会社原糸倉庫","kana":"くずりけおりこうぎょうかぶしきがいしゃげんしそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33537222,"lng":136.75931111,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0556","desc":"敷地西端中央で倉庫と工場の間に建つ。木造平屋建、切妻造セメント瓦葺で、外壁は下見板張、小屋はキングポストトラス組とする。内部は床板張の一室で、棚を整然と配し、現在も原糸を収納する。鋸形の屋根の工場と並び、敷地西側の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013409"},{"id":"00013402","register_sub_id":"101","register_pk":"368487","name":"葛利毛織工業株式会社工場","kana":"くずりけおりこうぎょうかぶしきがいしゃこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33546667,"lng":136.75948889,"geo_status":"db","era":"昭和7年頃／昭和20年頃・同30年代増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積563㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0549","desc":"一宮市の中西部、木曽川左岸の玉ノ井地区に位置し、敷地北側に建つ、毛織物の生産工場。木造平屋建、桟瓦葺で、鋸形の屋根形状で四スパンから成り、小屋はトラス組。内部は一室で高窓から採光し、独立柱を避け織機を配す。織物業の隆盛を伝える工場施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013402"},{"id":"00013403","register_sub_id":"101","register_pk":"368488","name":"葛利毛織工業株式会社事務所","kana":"くずりけおりこうぎょうかぶしきがいしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33515,"lng":136.75946111,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0550","desc":"敷地南端中央の門を入って西側に建つ。木造二階建、寄棟造桟瓦葺で、西側の廊下から離れに続く。小屋はキングポストトラス組、外壁は下見板張。一階は一室で、二階は十畳二室を南北に並べ、主座敷に床、棚を備える。和風の座敷を備えた、外観洋風の事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013403"},{"id":"00013410","register_sub_id":"101","register_pk":"368495","name":"葛利毛織工業株式会社倉庫","kana":"くずりけおりこうぎょうかぶしきがいしゃそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33528333,"lng":136.75926667,"geo_status":"db","era":"昭和32年頃","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0557","desc":"原糸倉庫の南側に連続して建つ。木造平屋建、切妻造セメント瓦葺で、外壁は下見板張とする。南北に長い長方形平面の内部は、東西の二室に分ける。内部には棚を並べ、工場の倉庫として使用する。工場や原糸倉庫と共に敷地西側の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013410"},{"id":"00013406","register_sub_id":"101","register_pk":"368491","name":"葛利毛織工業株式会社男子寮","kana":"くずりけおりこうぎょうかぶしきがいしゃだんしりょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1","lat":35.33538056,"lng":136.75962222,"geo_status":"db","era":"昭和27年頃／昭和32年頃増築","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積43㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0553","desc":"工場の南東に建つ。木造二階建、桟瓦葺で、寄棟造で南北棟の主体部北寄りに東西棟の増築部が接続する。外壁は竪板張のペンキ塗仕上で、一階を倉庫と吹放しの通路とし、二階に男子寮の居室を三室配す。住込みで働いていた時代の様相を伝える工場の附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013406"},{"id":"00013408","register_sub_id":"101","register_pk":"368493","name":"葛利毛織工業株式会社土蔵","kana":"くずりけおりこうぎょうかぶしきがいしゃどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前114他","lat":35.33531667,"lng":136.75936389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0555","desc":"敷地中央西寄りで工場と離れの間に建つ。土蔵造二階建、切妻造桟瓦葺で、北、東面に下屋を廻す。内部は一、二階とも一室で、内壁には竪板を張る。本体部分は家財蔵、下屋は工場の倉庫として使用する。敷地内で最も古く、近代産業施設の景観に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013408"},{"id":"00013405","register_sub_id":"101","register_pk":"368490","name":"葛利毛織工業株式会社離れ","kana":"くずりけおりこうぎょうかぶしきがいしゃはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県一宮市木曽川町玉ノ井字宮前1他","lat":35.33525278,"lng":136.75939167,"geo_status":"db","era":"昭和7年頃／昭和25年頃・同50年頃増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積97㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0552","desc":"事務所の北西に接続して建つ、経営者家族の住居。木造二階建、入母屋造桟瓦葺で、四周に下屋を廻す。外壁は漆喰塗で、一階は腰壁を、二階は内法高までを竪板張とする。内部は上下階に計八室の座敷を配し、一階主座敷に床と平書院を備える。端正な造りの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013405"},{"id":"00004680","register_sub_id":"101","register_pk":"105670","name":"九重味淋大蔵","kana":"ここのえみりんおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県碧南市浜寺町二丁目11","lat":34.874172,"lng":136.98082,"geo_status":"db","era":"宝永3／天明7移築改造","year":1706,"year_source":"db","year_min":1706,"year_max":1706,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積384㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0163","desc":"味淋の基となる酒造のための蔵。土蔵造，２階建，切妻造，桟瓦葺で，東西棟の主体部の南面西端に鈎の手に突出部を設ける。内部は東端部を仕切る以外は１，２階とも広い空間で，外壁は黒塗の押縁下見板で囲う。北面を接道する大型の蔵で味淋工場の象徴的建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004680"},{"id":"00004572","register_sub_id":"101","register_pk":"105562","name":"小島家住宅北酒蔵及び北蔵","kana":"こじまけじゅうたくきたさかぐらおよびきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38315132,"lng":136.94022292,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積150㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0176","desc":"敷地北端部に建つ。北酒蔵主体部，北蔵とも，土蔵造２階建，切妻造，桟瓦葺で，東西棟北酒蔵と南北棟北蔵が隣接して建ち，北酒蔵南面西半に下屋（絞り場）を葺下ろし一体化した形式となる。複雑で変化に富んだ外観を呈し，敷地北半の作業空間を象徴する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004572"},{"id":"00004573","register_sub_id":"101","register_pk":"105563","name":"小島家住宅西酒蔵及び仕込場","kana":"こじまけじゅうたくにしさかぐらおよびしこみば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券633","lat":35.38296676,"lng":136.94012933,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造及び木造3階一部平屋建、瓦葺、建築面積307㎡","structure_material":"土蔵造及び木造3階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0177","desc":"主屋の西背後に平屋，切妻造，桟瓦葺の仕込場を配し，その奥に土蔵造３階建，切妻造，桟瓦葺の西酒蔵が接続する。仕込場は全体が吹放しで洗場，釜場をとり，西酒蔵は１階を麹室，熟成場，２階以上を原料，道具置場とする。大規模で醸造業独特の構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004573"},{"id":"00007215","register_sub_id":"101","register_pk":"108197","name":"墨会館","kana":"すみかいかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県一宮市小信中島字南九反11-1","lat":35.312874,"lng":136.745605,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積2089㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2008.07.08(平成20.07.08)","register_no":"23 － 0308","desc":"丹下健三設計のＲＣ造事務所建築。台形敷地北辺の２階建事務室棟と南半の平屋建ホール棟を玄関車寄で接続する。１階外壁は非構造体で、上端にスリットを入れて採光とする。ダブルビームの大梁、打放しコンクリートなど、丹下の初期作品の特徴が見られる佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007215"},{"id":"00011325","register_sub_id":"101","register_pk":"209162","name":"中定商店昭三蔵","kana":"なかさだしょうてんしょうさんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県知多郡武豊町字小迎51","lat":34.855225,"lng":136.922712,"geo_status":"db","era":"昭和3頃／昭和20頃・同63・平成12改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積202㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"23－0470","desc":"敷地南東隅に建つ平屋建、切妻造妻入の土蔵。もとは仕込、圧搾場として建てられたもので、大きな仕込桶を多数並べるために、小屋はキングポストトラスを用いて梁間約一一メートルの大スパンを飛ばす。窓は小庇を付けた高窓として、町の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011325"},{"id":"00011324","register_sub_id":"101","register_pk":"209161","name":"中定商店昭二蔵","kana":"なかさだしょうてんしょうにぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県知多郡武豊町字小迎51","lat":34.855341,"lng":136.92262,"geo_status":"db","era":"昭和2頃／昭和中期・同60改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積87㎡","structure_material":"土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"23－0469","desc":"敷地南寄りに建つ平屋建の土蔵。もとは仕込、圧搾場として建てられたもので、キングポストトラスを用いた洋小屋とする。外壁には黒色の簓子下見板を張り、開口には白漆喰で窓枠を打って、コントラストを付ける。醸造業で栄えた武豊の町並み景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011324"},{"id":"00011323","register_sub_id":"101","register_pk":"209160","name":"中定商店大五蔵","kana":"なかさだしょうてんだいごぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県知多郡武豊町字小迎51","lat":34.855483,"lng":136.922424,"geo_status":"db","era":"大正5／昭和41・同48・同62改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積106㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"23－0468","desc":"中定商店は、味噌・溜を専業とする醸造家。大五蔵は変形敷地にあわせた台形平面を持つ。もとは仕込蔵として建てられた。二階建ながら、二階は建ちが低く「二階麹」と呼ばれ、味噌玉に麹菌を繁殖させる部屋とする。黒色の壁面が特色ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011323"},{"id":"00010164","register_sub_id":"101","register_pk":"197997","name":"西駒屋田村家住宅主屋","kana":"にしこまやたむらけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊橋市二川町字中町147-1","lat":34.724,"lng":137.449851,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積195㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0412","desc":"東海道二川宿に位置する町家で、醸造業を営んでいた。街道に南面して建ち、床上部を二列六室とする。東列はミセ、ナカノマ、ダイドコロ、西列はオクミセ、ブツマ、オクノマとする。床上部正面に出格子をたて、上下階とも軒を出桁造とする。宿場の風情を醸す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010164"},{"id":"00010165","register_sub_id":"101","register_pk":"197998","name":"西駒屋田村家住宅土蔵","kana":"にしこまやたむらけじゅうたくどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊橋市二川町字中町147-1","lat":34.724187,"lng":137.449901,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0413","desc":"主屋の北方に南北棟で建つ。桁行六間、梁間三間の二階建土蔵。中央の柱で桁行梁を受け、小屋は登梁とする。家財道具を納める蔵で、東に出入口を開く。東正面の上部を漆喰、腰下を黒漆喰で塗り分け、側背面三方を簓子下見板張とする。屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010165"},{"id":"00000051","register_sub_id":"101","register_pk":"101041","name":"八丁味噌本社蔵（史料館）","kana":"はっちょうみそほんしゃくら（しりょうかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県岡崎市八帖町字往還通69","lat":34.9578185,"lng":137.15256494,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積463㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"23 － 0002","desc":"「カクキュウ」の商号で知られる大規模な総２階の土蔵建築で，昭和16年まで味噌仕込み用の蔵として使用されていた。石垣の基壇上に黒塗りの下見板貼りとし，２層目は白漆喰塗りである。壁面に開けられた格子窓が連続するさまが特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000051"},{"id":"00000050","register_sub_id":"101","register_pk":"101040","name":"八丁味噌本社事務所","kana":"はっちょうみそほんしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県岡崎市八帖町字往還通69","lat":34.95786976,"lng":137.1530007,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、トタン葺、建築面積339㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"23 － 0001","desc":"「カクキュウ」の商号で知られる八丁味噌製造業者の本社社屋。南北の２つの棟が中庭と土間をはさんで接続している。教会堂風の構成と，白い柱型と壁面の下見板の濃茶色とを対照させた意匠が特徴的である。内部は洋風の意匠でまとめられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000050"},{"id":"00006586","register_sub_id":"101","register_pk":"107569","name":"萬乗醸造内井戸","kana":"ばんじょうじょうぞううちいど","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.064716,"lng":136.933243,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、面積4.9㎡2基よりなる","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0243","desc":"元蔵の南面近くに位置し，南北方向に２本が並んで掘られている。石造の円形井戸枠の外径はともに２．５ｍ，深さは約８ｍ。創業期以来の井戸であり，元蔵井戸とも称される。良質な水を必要とする醸造業に不可欠な設備である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006586"},{"id":"00006587","register_sub_id":"101","register_pk":"107570","name":"萬乗醸造旧仕込蔵及び樽修理場","kana":"ばんじょうじょうぞうきゅうしこみぐらおよびたるしゅうりば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田3-2他","lat":35.06484509,"lng":136.93395579,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0244","desc":"土蔵の東面沿い道路を挟んだ向かいの敷地に南北棟で建つ。桁行８間，梁間３間規模，切妻造，桟瓦葺の２階建土蔵で，道路側西面全面に１間半幅の下屋を差し掛ける。戸口は南面西寄りと西面北寄りに開く。新町通りの突き当たりに位置し，アイストップになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006587"},{"id":"00006582","register_sub_id":"101","register_pk":"107565","name":"萬乗醸造旧精米作業場","kana":"ばんじょうじょうぞうきゅうせいまいさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.06485,"lng":136.93367,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積125㎡、門及び煙突付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0235","desc":"土蔵の南方に南北棟で建つ。桁行６間半，梁間３間半，切妻造，桟瓦葺の木造平屋建で，南側を旧精米所とし，北側を中庭への通路とする。西面北半に下屋を，南半に切妻屋根を掛けて共に倉庫とする。東面には萬乗醸造のシンボルである煉瓦造煙突を添わす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006582"},{"id":"00006579","register_sub_id":"101","register_pk":"107562","name":"萬乗醸造新蔵","kana":"ばんじょうじょうぞうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.065182,"lng":136.933517,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積298㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0239","desc":"主屋の西方，中蔵の北面に接して南北棟で建つ。桁行１５間，梁間６間，切妻造，桟瓦葺，２階建の長大な仕込蔵で，内部に２列８本の通し柱を立てる。外部は縦板張，２階は生子鉄板張とする。北妻面を新町通りに見せ，主屋・土蔵とともに重厚な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006579"},{"id":"00006588","register_sub_id":"101","register_pk":"107571","name":"萬乗醸造外井戸","kana":"ばんじょうじょうぞうそといど","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字土廻間8他","lat":35.06437796,"lng":136.93360423,"geo_status":"db","era":"明治初期／昭和初期増設","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"陶製及びコンクリート造、面積4.9㎡1基及び面積1.8㎡5基よりなる","structure_material":"陶製及びコンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0245","desc":"醸造場敷地の南方，土蔵東面道路に面する飛地に所在する。６本が掘られ，うち北側の５本は径１．５ｍ，深さ５ｍ，南方の１本は径２．５ｍ，深さ８ｍであり，井戸枠は４基がコンクリート製，２基が常滑焼製になる。醸造場の拡張，発展を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006588"},{"id":"00006578","register_sub_id":"101","register_pk":"107561","name":"萬乗醸造中蔵","kana":"ばんじょうじょうぞうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.064972,"lng":136.933243,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積343㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0238","desc":"敷地の南西部，元蔵の西に南北棟で建つ。桁行１４間，梁間４間，切妻造，桟瓦葺，２階建の長大な仕込蔵。中央棟通りに３本の通し柱を立てる。西面には２間半幅の下屋を差し掛けて１階の平面規模を梁行６間半とする。創業期の仕込蔵で，蔵３棟のうち最も古い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006578"},{"id":"00006580","register_sub_id":"101","register_pk":"107563","name":"萬乗醸造白米倉庫","kana":"ばんじょうじょうぞうはくまいそうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.065048,"lng":136.933502,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積46㎡、検査室付","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0240","desc":"離れの南方，新蔵の東に位置し，東西棟で建つ。桁行４間，梁間２間半，切妻造，桟瓦葺の２階建土蔵で，南面に戸口を開け，東妻面には奥行１間半，梁間２間半，入母屋造，桟瓦葺の検査室が取り付く。旧精米作業場，元蔵米蒸し室とともに主屋南方の中庭を囲う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006580"},{"id":"00006581","register_sub_id":"101","register_pk":"107564","name":"萬乗醸造瓶詰作業場","kana":"ばんじょうじょうぞうびんづめさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.064697,"lng":136.933487,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鉄板葺、建築面積147㎡、物置付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0236","desc":"旧精米作業場の南方に東西棟で建つ。桁行９間，梁間４間規模，切妻造，鉄板葺の木造平屋建で，北面東端から敷地境界沿いに北へ桁行６間，梁間１間の物置を延ばし，物置前に広い作業場をとる。真壁造で，小屋組は旧精米作業場と同様キングポストトラスとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006581"},{"id":"00006577","register_sub_id":"101","register_pk":"107560","name":"萬乗醸造元蔵","kana":"ばんじょうじょうぞうもとぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西門田41","lat":35.064804,"lng":136.933319,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積338㎡、米蒸し室及び試験室付","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"23 － 0237","desc":"主屋の南方に位置し，瓶詰作業場の西に接して建つ。桁行９間，梁間８間，切妻造，桟瓦葺，２階建の仕込蔵で，北面東寄りに桁行６間半，梁間４間，南北棟の米蒸し室が取り付き，米蒸し室の西に試験室を配する。外部は簓子下見板張。醸造場の中心をなす施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006577"},{"id":"00004241","register_sub_id":"101","register_pk":"105231","name":"半田赤レンガ建物（旧カブトビール工場）創建時主棟","kana":"はんだあかれんがたてもの（きゅうかぶとびーるこうじょう）そうけんじしゅとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市榎下町8","lat":34.90141497,"lng":136.92849585,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"煉瓦造2階建一部5階建、鉄板葺、建築面積636㎡","structure_material":"煉瓦造2階建一部5階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0134","desc":"煉瓦造２階建の発酵室・貯蔵室に同５階建の事務室・技師室が接続する。屋根は切妻造鉄板葺。窓は櫛形アーチに要石，５階窓は半円アーチに迫元石・要石付で飾る。発酵室・貯蔵室の２階床と天井はＩ形鉄梁に煉瓦アーチを充填した耐火床とする。設計は妻木頼黄。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004241"},{"id":"00004243","register_sub_id":"101","register_pk":"105233","name":"半田赤レンガ建物（旧カブトビール工場）貯蔵庫棟","kana":"はんだあかれんがたてもの（きゅうかぶとびーるこうじょう）ちょぞうことう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市榎下町8","lat":34.90159351,"lng":136.92845179,"geo_status":"db","era":"明治41／大正7・大正10増築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積1359㎡","structure_material":"煉瓦造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0136","desc":"主棟の北辺から西辺に接続する増築部で，発酵室・貯蔵室に用いられた。煉瓦造２階建，切妻造，鉄板葺の南北棟３棟が，主棟北から反時計回りに順次増築された。壁体はイギリス積。妻壁上部はペディメントに造り，円窓を飾る。窓は要石付の櫛形アーチとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004243"},{"id":"00004242","register_sub_id":"101","register_pk":"105232","name":"半田赤レンガ建物（旧カブトビール工場）ハーフティンバー棟","kana":"はんだあかれんがたてもの（きゅうかぶとびーるこうじょう）はーふてぃんばーとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県半田市榎下町8","lat":34.90183658,"lng":136.92834089,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積784㎡","structure_material":"木骨煉瓦造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"23 － 0135","desc":"主棟南に接続する木骨煉瓦造の平屋建で，東辺部は胴差を入れて高窓を開いて切妻屋根とし，南側は主棟から片流の屋根で，鉄板葺とする。瓶洗・瓶詰・荷造等の出荷作業を行った。戸口は両開板扉とし，当初の窓は上下げ窓であったが閉鎖した。設計は妻木頼黄。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004242"},{"id":"00003884","register_sub_id":"101","register_pk":"104874","name":"明治村菊の世酒蔵","kana":"めいじむらきくのよさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34548286,"lng":136.98896159,"geo_status":"db","era":"明治28／昭和58移築","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積654㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0118","desc":"桁行１８間，梁行９間の土蔵造２階建。切妻造，桟瓦葺で片側に庇がつく。外壁は押縁下見板で保護し，小庇付の窓を多数開く。小屋組は梁行を３等分して柱を立てて鳥居形に組み，両側から登り梁を渡して和小屋とする。移築時，北半にＲＣ造展示室を組み込んだ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003884"},{"id":"00003663","register_sub_id":"101","register_pk":"104653","name":"明治村京都中井酒造","kana":"めいじむらきょうとなかいしゅぞう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34165366,"lng":136.98996542,"geo_status":"db","era":"明治3／平成5移築","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0076","desc":"切妻造，平入の木造つし２階建町家。屋根は起りのある桟瓦葺で，右手を落棟とする。正面１階は太い格子と無双窓，２階は虫籠窓である。内部は通り土間の左が居室，右に穀物置場，井戸と洗米所，煉瓦造蒸し竈などがあり，当時の酒造業の様子を示す遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003663"},{"id":"00003866","register_sub_id":"101","register_pk":"104856","name":"明治村工部省品川硝子製造所","kana":"めいじむらこうぶしょうしながわがらすせいぞうしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34435065,"lng":136.99032426,"geo_status":"db","era":"明治10頃／昭和44移築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積123㎡","structure_material":"煉瓦造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0100","desc":"煉瓦造，一部中２階付き。木造キングポストトラス小屋組による切妻屋根に，換気用の越屋根を載せる。外壁はイギリス積で軒蛇腹が巡る。開口部は半円アーチのファンライト付と，まぐさ石形式の２種を用い，石材がアクセントとなる。明治初期官営工場の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003866"},{"id":"00003659","register_sub_id":"101","register_pk":"104649","name":"明治村鉄道局新橋工場","kana":"めいじむらてつどうきょくしんばしこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34036954,"lng":136.98932477,"geo_status":"db","era":"明治22／昭和41移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"鉄造平屋建、銅板葺、建築面積463㎡","structure_material":"鉄造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0072","desc":"鉄造平屋建，越屋根付き切妻屋根を銅板葺とする。妻には半円のファンライトを飾り，半円アーチの扉口に両開き戸を吊り込む。鋳鉄柱，キングポストトラスの小屋組材，鉄製下見板，サッシ類の鉄材は全て国産で，当時の工業技術を示す貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003659"},{"id":"00008295","register_sub_id":"101","register_pk":"133937","name":"アミカン本社事務所","kana":"あみかんほんしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市富田浜元町1867","lat":35.00120405,"lng":136.6536299,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木骨コンクリート造2階建、塔屋付、建築面積100㎡","structure_material":"木骨コンクリート造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0092","desc":"旧東海道に面する敷地に建ち、建築面積１００㎡、木骨コンクリート造２階建塔屋付である。南西隅を四分一円弧とし、外壁はスクラッチタイル貼とモルタル洗出しとし、縦長窓を連続的に配置する。大小の矩形を取り混ぜた変化のある立面意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008295"},{"id":"00008296","register_sub_id":"101","register_pk":"133938","name":"アミカン本社正門","kana":"あみかんほんしゃせいもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市富田浜元町1867","lat":35.00117137,"lng":136.65348428,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"コンクリート造、間口2.7m","structure_material":"コンクリート造","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0093","desc":"敷地西辺の中央南寄りに、やや後退して建ち、南北に煉瓦塀を延ばす。間口を５．８ｍとし、門柱は、高さ３．１ｍのコンクリート造、洗出し仕上げで頂部をドーム状につくり、ボーダーをまわす。かつては左右に脇門を開いていたが、南側は煉瓦で閉ざされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008296"},{"id":"00008297","register_sub_id":"101","register_pk":"133939","name":"アミカン本社煉瓦塀","kana":"あみかんほんしゃれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市富田浜元町1867","lat":35.00130487,"lng":136.65355721,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、総延長46m","structure_material":"煉瓦造","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0094","desc":"敷地西面に建ち、本館正面に構えた正門の両側に折れ曲がりに延びる。煉瓦造で、総延長４６ｍを測る。２．２ｍ毎に柱型を現し、各間を長手積煉瓦で充たし、頂部は柱と同幅の臥梁形に積んだ煉瓦で繋ぐ。重厚な外観で、近代産業による発展の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008297"},{"id":"00009491","register_sub_id":"101","register_pk":"194284","name":"石川酒造井戸屋形","kana":"いしかわしゅぞういどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99427696,"lng":136.53973462,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、面積6.8㎡、井戸付","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0143","desc":"敷地中央の中庭から南西寄り、主屋北側に建つ。木造、切妻造桟瓦葺、内ころびの４本柱の上部を頭貫と方杖とにより固める。四方吹放しで、中央部に石積で井桁が組まれた井戸がある。伏流水が多く自噴する造酒屋における敷地内の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009491"},{"id":"00009486","register_sub_id":"101","register_pk":"194279","name":"石川酒造大蔵","kana":"いしかわしゅぞうおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99474239,"lng":136.53974462,"geo_status":"db","era":"大正5年／昭和21年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積566㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0138","desc":"敷地北端に建つ。土蔵造二階建、切妻造桟瓦葺、桁行三二・八メートル梁間一四・六メートル。高さ一〇メートルを超える大規模な酒造施設で、黒い下見板を軒下まで張った外観は地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009486"},{"id":"00009487","register_sub_id":"101","register_pk":"194280","name":"石川酒造釜場","kana":"いしかわしゅぞうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.9945537,"lng":136.53975758,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積166㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0139","desc":"北側に大蔵、西側に槽場に接して建つ。木造平屋建、切妻造桟瓦葺、桁行一八・二メートル梁間九・一メートル。南東部に中二階を設ける。小屋組は和小屋、天井を表しとする。大棟に越屋根を設け、換気を促す。洗米、蒸しなど酒造の行程を担う大型の酒造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009487"},{"id":"00009482","register_sub_id":"101","register_pk":"194275","name":"石川酒造北文庫蔵","kana":"いしかわしゅぞうきたぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99433609,"lng":136.53956021,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0134","desc":"南文庫蔵の北東側に建つ。土蔵造二階建、切妻造桟瓦葺、桁行五・四メートル梁間四・七メートル、東面に出入口を開け、下屋を設ける。外壁は白漆喰仕上で鉢巻きを廻し、腰は東面を洗い出し仕上げ、他三方は下見板を張る。南文庫蔵と並び当家の繁栄ぶりを表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009482"},{"id":"00009484","register_sub_id":"101","register_pk":"194277","name":"石川酒造旧米庫","kana":"いしかわしゅぞうきゅうこめこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99428672,"lng":136.54001825,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積49㎡","structure_material":"土蔵造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0136","desc":"旧精米場の北側に建つ。木造平屋建、切妻造桟瓦葺、桁行七・三メートル梁間五・五メートル。西面に下屋を付け、人造石研ぎ出しと黒漆喰で縁取られた出入口を開ける。小屋組は和小屋、天井は表しとし内部空間を広く取る。老舗造酒屋を構成する建築群のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009484"},{"id":"00009483","register_sub_id":"101","register_pk":"194276","name":"石川酒造旧精米場","kana":"いしかわしゅぞうきゅうせいまいじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99419392,"lng":136.54003015,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積98㎡、門付","structure_material":"土蔵造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0135","desc":"敷地南東隅に建つ。切妻造桟瓦葺、桁行一〇・九メートル梁間五・五メートル。人造石研ぎ出しと黒漆喰で縁取られた出入口を西面に二箇所開け下屋が付く。外壁は白漆喰塗、腰高に下見板を張る。正門を介して主屋と並び、大規模な地酒屋の南面の構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009483"},{"id":"00009492","register_sub_id":"101","register_pk":"194285","name":"石川酒造自噴井戸","kana":"いしかわしゅぞうじふんいど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99451919,"lng":136.53988548,"geo_status":"db","era":"大正5年／昭和29年増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造及びコンクリート造、面積7.5㎡","structure_material":"煉瓦造及びコンクリート造","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0144","desc":"敷地中央の中庭に位置する。煉瓦造の貯水槽を基とし、北側にコンクリート造の貯水槽二基及びポンプを増設する。筒状を呈した高位の貯水槽を取り囲むように低位の貯水槽が逆コの字形に配される。潤沢に伏流水が湧くことを物語る、造酒屋にふさわしい工作物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009492"},{"id":"00009479","register_sub_id":"101","register_pk":"194272","name":"石川酒造主屋","kana":"いしかわしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99416061,"lng":136.53981005,"geo_status":"db","era":"明治24年／昭和元年増築・昭和23年・平成元年改修","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積296㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0131","desc":"敷地南側に建つ。木造平屋建、入母屋造桟瓦葺。建築面積二九六平方メートル。南側に大戸口を開け、通り土間を設ける。その西側に六室を配し、三方に広く縁を廻す。外壁は黒漆喰塗で腰は下見板張とする。明治期の造酒屋を構成する重厚な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009479"},{"id":"00009490","register_sub_id":"101","register_pk":"194283","name":"石川酒造貯蔵庫及び事務所","kana":"いしかわしゅぞうちょぞうこおよびじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.9944283,"lng":136.53973153,"geo_status":"db","era":"明治後期／昭和23年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積155㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0142","desc":"敷地のほぼ中央に建つ。土蔵造一部木造二階建、切妻造桟瓦葺、建築面積一五五平方メートル。東側に下屋を設け、二箇所出入口を開ける。外壁は白漆喰塗、腰は竪板張だが、事務所前のみ竪窓を嵌め込み漆喰で意匠的に縁取りし、特徴的な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009490"},{"id":"00009485","register_sub_id":"101","register_pk":"194278","name":"石川酒造納屋","kana":"いしかわしゅぞうなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.9944283,"lng":136.54002301,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0137","desc":"敷地東側、旧米庫の北側に建つ。木造二階建、切妻造桟瓦葺、桁行一三・六メートル梁間四・五メートル。西側に小部屋が張り出し、北側に下屋を付設する。旧精米場、旧米庫と並び、通りから腰高に下見板を張る外壁を連続させ、重厚な造酒屋の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009485"},{"id":"00009493","register_sub_id":"101","register_pk":"194286","name":"石川酒造西土塀","kana":"いしかわしゅぞうにしどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99413807,"lng":136.5395022,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長19m","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0145","desc":"敷地南西角から延び、南文庫蔵につながる。木造、高さ三・一メートル、桟瓦を葺く。外壁は腰高に下見板を張り、小壁を白漆喰仕上げの真壁とし、腕木が出桁を支持する。内側は杉板張とする。広大な老舗の造酒屋を構成する要素として、景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009493"},{"id":"00009480","register_sub_id":"101","register_pk":"194273","name":"石川酒造西の座敷","kana":"いしかわしゅぞうにしのざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99415466,"lng":136.539584,"geo_status":"db","era":"明治31年／平成22年改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0132","desc":"敷地南端、主屋の西側に建ち、渡り廊下で繋がる。木造平屋建、片入母屋造桟瓦葺、建築面積七二平方メートル。田の字型に四室を配し、いずれも竿縁天井とする。トコのある主室と次の間を南側に設け、濡れ縁を介して前庭を望む。接客用の良質な和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009480"},{"id":"00009489","register_sub_id":"101","register_pk":"194282","name":"石川酒造壜詰場","kana":"いしかわしゅぞうびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99446518,"lng":136.5395959,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積280㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0141","desc":"敷地西端、槽場の南側に建つ。木造二階建、切妻造桟瓦葺、桁行二一・八メートル梁間一○・九メートル。東側北寄りに下屋が付くが釜場に覆われる。外壁の下部は竪板張、上部は下見板張とし、上下二つの窓を等間隔に穿つ。老舗造酒屋にふさわしい景観を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009489"},{"id":"00009488","register_sub_id":"101","register_pk":"194281","name":"石川酒造槽場","kana":"いしかわしゅぞうふなば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99461794,"lng":136.53962398,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積141㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0140","desc":"敷地の西端に建つ。木造二階建、切妻造桟瓦葺、建築面積一四一平方メートル。東側に下屋が付くが釜場に覆われる。北西隅を掘り込み、モザイクタイル貼の槽場とし、搾りの行程が行われた。外壁は下見板張で覆われ、重厚な酒造施設の一群を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009488"},{"id":"00009481","register_sub_id":"101","register_pk":"194274","name":"石川酒造南文庫蔵","kana":"いしかわしゅぞうみなみぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市桜町字南垣内128他","lat":34.99425876,"lng":136.53952749,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0133","desc":"敷地西側、西の座敷の北側に建つ。土蔵造二階建、切妻造桟瓦葺、桁行七・二メートル梁間五・八メートル。東面に出入口を二箇所開け、下屋を設ける。基礎は切石積とし、外壁は白漆喰仕上で鉢巻きを廻し、腰は東面を洗い出し仕上げ、他三方は下見板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009481"},{"id":"00002547","register_sub_id":"101","register_pk":"103537","name":"伊勢河崎商人館応接室及び前室","kana":"いせかわさきしょうにんかんおうせつしつおよびぜんしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496506,"lng":136.71756,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積9.0㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"24 － 0038","desc":"旧小川酒店主屋西側の門を入って左手に位置する。応接室は桁行２間，梁間１間半規模，南北棟，切妻造，桟瓦葺の１室洋館で，室内西面に暖炉を備える。前室は主屋土間に連絡する渡廊下の西半部にあたり，門・洋館とともに酒店の洋風接客空間を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002547"},{"id":"00002268","register_sub_id":"101","register_pk":"103258","name":"伊勢河崎商人館サイダー検査室","kana":"いせかわさきしょうにんかんさいだーけんさしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49674172,"lng":136.71748926,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造平屋建、建築面積12㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0037","desc":"小川酒店では昭和期に入り，酒卸業に加え，サイダー工場を併設して生産販売していた。サイダー検査室は，鉄筋コンクリート造，平屋建，陸屋根でパラペットに瓦を載せ，外壁下部は洗い出し仕上げとする。小規模だが，近代における製造業の証左となる建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002268"},{"id":"00002548","register_sub_id":"101","register_pk":"103538","name":"伊勢河崎商人館サイダーろ過施設","kana":"いせかわさきしょうにんかんさいだーろかしせつ","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496574,"lng":136.717529,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造、鋼板葺、建築面積3.0㎡","structure_material":"鉄筋コンクリート造","registered":"2001.11.20(平成13.11.20)","register_no":"24 － 0039","desc":"旧小川酒店の西裏門近くに建つ。正面間口２．５ｍ，奥行１．２ｍ規模，高さ６ｍほどの鉄筋コンクリート造構造物で，下部は正面に２連の欠円アーチによる開口をとり，上部を水槽状に造る。サイダー検査室とともにサイダー製造を偲ばせる数少ない施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002548"},{"id":"00014394","register_sub_id":"101","register_pk":"511383","name":"於茂千也函（伊藤家住宅土蔵）","kana":"おもちゃばこ（いとうけじゅうたくどぞう)","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県四日市市富田一丁目983-1","lat":35.00420556,"lng":136.65203889,"geo_status":"db","era":"江戸末期／明治前期・昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積120㎡","structure_material":"土蔵造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"24 - 0321","desc":"旧富田町に所在し、個人が収集した郷土玩具を収納・展示する蔵。土蔵造平屋建、切妻造桟瓦葺で南に葺降ろして戸前とする。壁は漆喰塗で腰は海鼠壁。東半を土間、西半を床上２室とし、数寄屋風天井の次の間、書院付の奥座敷とする。趣味人の数寄屋風座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014394"},{"id":"00015465","register_sub_id":"101","register_pk":"533480","name":"神楽酒造酒蔵兼釜場","kana":"かぐらしゅぞうさかぐらけんかまば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県四日市市室山町326","lat":34.95519444,"lng":136.57867778,"geo_status":"db","era":"安政5年(1858)／大正後期増築、平成19年改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"土蔵造2階一部平屋建、瓦葺、建築面積557㎡、煙突付","structure_material":"土蔵造2階一部平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"24 - 0334","desc":"市街地西部に位置する酒造業の酒蔵兼釜場。２階建切妻造桟瓦葺東西棟で、北・南面に下屋を付し、南面西寄りに切妻造南北棟の釜場を突出し、煉瓦造煙突を取込む。一階は土間で蒸米場など、二階は板敷で物置などとする。地域の酒造業の歴史を伝える貴重な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015465"},{"id":"00015466","register_sub_id":"101","register_pk":"533481","name":"神楽酒造西酒蔵","kana":"かぐらしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県四日市市室山町326","lat":34.95524722,"lng":136.57841111,"geo_status":"db","era":"明治中期／平成19年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積406㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"24 - 0335","desc":"酒蔵兼釜場の西に位置する仕込蔵。二階建切妻造桟瓦葺東西棟の長大な土蔵を南北に並べ、棟境には壁を設けず、内部を一体として利用する。一階は土間の仕込場、二階は板敷の倉庫などとし、棟境上部に軒樋を現す。２棟を連結させた特徴的な外観の大規模な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015466"},{"id":"00014395","register_sub_id":"101","register_pk":"511384","name":"かつおの天ぱく主屋","kana":"かつおのてんぱくおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県志摩市大王町波切字石干谷393","lat":34.27724444,"lng":136.89475833,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"24 - 0322","desc":"太平洋を望む大王崎に建つ鰹節製造業の住宅である。東の崖と南の道路から一段低く敷地を構え、木造平屋建の切妻造桟瓦葺、竪板張の外壁で風に耐える。現在は一階南西の四畳間で商品陳列し、他は物置とする。波切漁港の水揚げを直ちに加工できる好立地にある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014395"},{"id":"00014396","register_sub_id":"101","register_pk":"511385","name":"かつおの天ぱく作業場","kana":"かつおのてんぱくさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県志摩市大王町波切字石干谷393","lat":34.27717778,"lng":136.89471389,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階一部平屋建、瓦葺及び鉄板葺、建築面積148㎡","structure_material":"木造2階一部平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"24 - 0323","desc":"二階建の燻し小屋と黴付小屋で、北の主屋との間の大屋根が作業場を覆う。湾曲した海側外壁は腰モルタル塗、上部竪板張で、桟瓦葺の切妻屋根が独特の外観を呈す。焙乾窯は火床を地下に設け、セイロを並べて積む。閉鎖的な黴付小屋に棲む菌が鰹節の味を決める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014396"},{"id":"00009494","register_sub_id":"101","register_pk":"194287","name":"木屋正酒造店舗兼主屋","kana":"きやしょうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市本町314-1","lat":34.61933412,"lng":136.08808113,"geo_status":"db","era":"明治22年／大正2年増築・昭和63年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積250㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0146","desc":"初瀬街道に面して建つ。間口一五・八メートルの木造つし二階建、切妻造桟瓦葺で、正面に下屋を設ける。正面左手を出入口及びミセノマとし、右手の床上部前面の張出しは腰を簓子下見板張とする。上部は漆喰塗で虫籠窓を穿ち、老舗造酒屋らしい佇まいを呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009494"},{"id":"00016675","register_sub_id":"101","register_pk":"579159","name":"旧伊賀焼陶磁器工業協同組合事務所","kana":"きゅういがやきとうじきこうぎょうきょうどうくみあいじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊賀市丸柱字長谷474-5他","lat":34.839978,"lng":136.129265,"geo_status":"db","era":"昭和14年／令和3年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"24 - 0345","desc":"市街地北方の山間に所在する伊賀焼の旧協同組合事務所。平屋建寄棟造桟瓦葺、北面切妻造玄関ポーチ付き。外壁下見板張、北・南面にガラス窓を連続して建てる。内部は和風で、南東隅の部屋は床を構え長押を廻す。窯元が多く所在する地域を象徴する旧事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016675"},{"id":"00001712","register_sub_id":"101","register_pk":"102702","name":"旧東洋紡績株式会社富田工場原綿倉庫","kana":"きゅうとうようぼうせきかぶしきがいしゃとみだこうじょうげんめんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県四日市市富州原町221-2","lat":35.00677659,"lng":136.65688221,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積1072㎡","structure_material":"煉瓦造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"24 － 0024","desc":"東洋紡績施設のなかで最大規模を有した工場の原綿倉庫で、敷地東南辺に沿って５つの妻面を並べる。桁行約１８メートル梁間約９メートル規模、切妻造の庫室５棟が一体となった形態をもち、煉瓦造壁体四周の要所にはバットレスをあらわす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001712"},{"id":"00013561","register_sub_id":"101","register_pk":"504928","name":"糀屋太郎兵衛商店奥蔵及び米蔵","kana":"こうじやたろべえしょうてんおくぐらおよびこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市魚町1773","lat":34.57528056,"lng":136.53120833,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"24 － 0284","desc":"道具蔵北側に南面して建ち、西側の糀原料の米を収めた米蔵と、東側の糀製造の道具類を収めた奥蔵から成る。本瓦葺の土蔵造二階建で、平入の正面下屋を蔵前とする。外壁は漆喰で軒先まで塗込めて鉢巻を廻し、敷地外側面は下見板張とする。糀製造を支えた施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013561"},{"id":"00013562","register_sub_id":"101","register_pk":"504929","name":"糀屋太郎兵衛商店糀室","kana":"こうじやたろべえしょうてんこうじむろ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市魚町1773","lat":34.57525833,"lng":136.53114444,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、屋根漆喰塗込、建築面積16㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"24 － 0285","desc":"奥蔵及び米蔵の西側に南面して建つ糀室。緩勾配屋根の土蔵造で、屋根を含めて全体を漆喰で塗込め、正面右上方に黒漆喰塗の眉を描く。内部は半地下で、登梁形式の小屋とし、床、壁はモルタル塗で、南東に糀製造用の筵を置く立上りを設ける。糀製造の中核施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013562"},{"id":"00013559","register_sub_id":"101","register_pk":"504926","name":"糀屋太郎兵衛商店店舗兼主屋","kana":"こうじやたろべえしょうてんてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市魚町1773","lat":34.57520556,"lng":136.53102222,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"24 － 0282","desc":"旧松坂城下東方にある代々糀製造販売を営む商家。道路に西面して建つ二階建切妻造で、正面に下屋、両端に袖壁を付す。外壁は黒漆喰塗で、一階に出格子、二階に出窓と虫籠窓を並べる。内部は南に土間、北に一列四室を配す。大火後の旧城下の町家の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013559"},{"id":"00013560","register_sub_id":"101","register_pk":"504927","name":"糀屋太郎兵衛商店道具蔵","kana":"こうじやたろべえしょうてんどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県松阪市魚町1773他","lat":34.57521667,"lng":136.531225,"geo_status":"db","era":"安政2年(1855)／明治26年頃増築","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"24 － 0283","desc":"敷地南東に西面して建つ家財蔵。本瓦葺の土蔵造二階建で、妻入の正面下屋を蔵前とする。外壁は漆喰で軒先まで塗込めて鉢巻を廻し、敷地外側面は下見板張とする。内部は板敷で壁を竪板張とし、登梁形式の小屋とする。大火を逃れた近世の屋敷構えを伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013560"},{"id":"00010468","register_sub_id":"101","register_pk":"199424","name":"長谷園奥の蔵","kana":"ながたにえんおくのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837587,"lng":136.129553,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0194","desc":"離れの西に接して東西棟で建ち、桁行四・九メートル梁間三・九メートル、土蔵造二階建、切妻造桟瓦葺で、南面に物置を附属する。外壁漆喰塗で鉢巻を廻らし、南東面は腰を海鼠壁、背面は竪板張とする。離れや蔵とともに屋敷北面の歴史的景観の形成に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010468"},{"id":"00010467","register_sub_id":"101","register_pk":"199423","name":"長谷園蔵","kana":"ながたにえんくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837564,"lng":136.129739,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0193","desc":"主屋背面に南面し、桁行四・九メートル梁間三メートル、土蔵造二階建、切妻造桟瓦葺で、正面の下屋で離れと接続する。腰高に竪板を張り、鉢巻を廻らす。小屋はアーチ状の梁で棟束と母屋を受ける。かつて帳簿蔵として使われた蔵で、主屋裏庭の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010467"},{"id":"00010472","register_sub_id":"101","register_pk":"199428","name":"長谷園工房一","kana":"ながたにえんこうぼういち","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱568-4","lat":34.83728,"lng":136.129669,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0198","desc":"敷地内通路沿いに東西棟で建つ平屋建の工房で、切妻造桟瓦葺である。外壁に竪板を張り、妻壁を漆喰塗とする。内部は一室で南面各間を窓として採光を図り、棹縁天井を張る。かつて轆轤に動力を伝えた機械の一部も残されており、陶器の製作工程を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010472"},{"id":"00010473","register_sub_id":"101","register_pk":"199429","name":"長谷園工房二","kana":"ながたにえんこうぼうに","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱568-4","lat":34.837073,"lng":136.129598,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積233㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0199","desc":"工房部の奥寄りに建つ木造平屋建で、Ｌ字形平面の工房である。工房一と同様に外壁竪板張とし、南面に窓を並べて採光を図る。内部は五室に区画して作業場や物置とする。小屋はキングポストトラスを採用して方杖や火打梁で固め、広い梁間を支持する大型の工房。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010473"},{"id":"00010464","register_sub_id":"101","register_pk":"199421","name":"長谷園主屋","kana":"ながたにえんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837468,"lng":136.129779,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、茅葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0190","desc":"住宅部の敷地東寄りに南面して建つ寄棟造茅葺で、棟と下屋に桟瓦を葺く。東寄りが土間で、床上部は前後に三室ずつ並べて縁を廻らし、南西隅の主座敷は庭に面した十畳で、大振りな床と床脇を備え、組子欄間を飾る。老舗窯元の、風格を備えた上質な住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010464"},{"id":"00010474","register_sub_id":"101","register_pk":"199430","name":"長谷園体験工房","kana":"ながたにえんたいけんこうぼう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱585","lat":34.837015,"lng":136.130085,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0200","desc":"通りの東側に南北棟で建つ、桁行二五メートルを測る長い建物で、傍らに築いた登り窯のための薪置場や釉薬の試験等に使われた。木造平屋建、南面切妻造北面寄棟造、桟瓦葺で、外壁竪板張とし、内壁の一部に荷摺木を残す。往時の製陶情景を偲ばせる施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010474"},{"id":"00009028","register_sub_id":"101","register_pk":"162388","name":"長谷園大正館","kana":"ながたにえんたいしょうかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱字長谷569","lat":34.83741469,"lng":136.13030464,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0118","desc":"山裾の敷地西寄りに位置し、高く積み上げた石垣に建つ木造平屋建。南北棟の半切妻造桟瓦葺、桁行８．９ｍ梁間７．９ｍ。下見板張で上部漆喰仕上げとし、大きく窓を開く開放的な事務所。南正面入口上部に印象的な意匠のアーチ型庇を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009028"},{"id":"00010469","register_sub_id":"101","register_pk":"199425","name":"長谷園展示室一","kana":"ながたにえんてんじしついち","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837409,"lng":136.129927,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0195","desc":"通り沿いで、主屋の東隣に棟を直交させて建つ。木造二階建、切妻造桟瓦葺で、南妻を出入口として下屋を設ける。一階外部を竪板張とし、二階は漆喰仕上げで南妻に窓を開ける。当初は味噌蔵などに使われた、施設内最大の展示室で、風情のある街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010469"},{"id":"00010471","register_sub_id":"101","register_pk":"199427","name":"長谷園展示室三","kana":"ながたにえんてんじしつさん","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱568-4","lat":34.83714,"lng":136.12988,"geo_status":"db","era":"明治期／平成15改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0197","desc":"展示室二の南側に平行して建つ展示室。木造二階建、切妻造桟瓦葺で、周囲に下屋を設ける。外壁は真壁漆喰塗で柱や梁の軸組を意匠的に現し、各面に窓を配する。内部は上下階とも一室である。もと米蔵などに使った建物で、建ちが高く、街路景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010471"},{"id":"00010470","register_sub_id":"101","register_pk":"199426","name":"長谷園展示室二","kana":"ながたにえんてんじしつに","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱568-4","lat":34.837218,"lng":136.129891,"geo_status":"db","era":"明治期／昭和49・平成15改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0196","desc":"展示室一の南側に向き合い、東西棟で建つ展示室。木造平屋建、東面切妻造西面入母屋造、桟瓦葺で、外壁に竪板を張る。内部は土間の一室で、小屋は和小屋を組む。当初は馬小屋に使われたとされ、一部に床板張であった痕跡も残す。往時の操業様態の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010470"},{"id":"00009029","register_sub_id":"101","register_pk":"162389","name":"長谷園登り窯","kana":"ながたにえんのぼりがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊賀市丸柱字長谷569","lat":34.83702494,"lng":136.13052735,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"連房式登り窯、奥行34m、幅6.7m、石垣付","structure_material":"連房式登り窯","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0119","desc":"大正館の東南に位置する。南に高くなる傾斜地に設けられた登窯。幅４．５～６．７ｍ、高低差９．６ｍに設けられ、全長３４ｍを測る。直線上に一五の燃焼室が並ぶ連房式登り窯で、北に主焚き口を開ける。近世以来の伊賀焼の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009029"},{"id":"00010466","register_sub_id":"101","register_pk":"202516","name":"長谷園離れ","kana":"ながたにえんはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市丸柱569","lat":34.837573,"lng":136.129646,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0192","desc":"主屋の北西側に渡廊下を介して東西棟で建つ客間で、別荘へ渡るための機能も併せ持つ。木造平屋建、切妻造桟瓦葺で、下屋を廻らす。八畳二室を並べて三方を縁とし、西の主室に座敷飾を備える。庭側は開放するが、背面は左右の土蔵と外観の統一が図られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010466"},{"id":"00010465","register_sub_id":"101","register_pk":"199422","name":"長谷園別荘","kana":"ながたにえんべっそう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱569他","lat":34.837564,"lng":136.129403,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0191","desc":"敷地の西端に建つ、もと隠居部屋。主体部は二階建入母屋造で、上下階とも洗練された造作の和室二室をもつ。入母屋造の玄関脇に附属する洋間はパラペットに洋瓦を葺き、ベイウィンドウを開く。時代性をよく表す洋間付住宅で、茅葺屋根の主屋と好対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010465"},{"id":"00010475","register_sub_id":"101","register_pk":"202517","name":"長谷園門及び塀","kana":"ながたにえんもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市丸柱569他","lat":34.83739069,"lng":136.12948926,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"表門 木造、瓦葺、間口1.8m 西門 木造、瓦葺、間口1.7m 中庭門 木造、銅板葺、間口1.3m 塀 土塀、総延長106m","structure_material":"表門 木造","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0201","desc":"主屋正面の表門、別荘正面の西門、主屋と表門の間に建つ中庭門と、各門の間及び屋敷地背面を画す塀。表門は風格を備えた四脚門で、西門は隠居所入口らしく瀟洒な意匠の腕木門である。腰を竪板張とするなど敷地内建物との景観調和と格式の表徴が図られた門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010475"},{"id":"00009476","register_sub_id":"101","register_pk":"194269","name":"八太正太夫酒店蔵及び蔵前","kana":"はったしょうだゆうさけてんくらおよびくらまえ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市香良洲町1094","lat":34.64777802,"lng":136.53452287,"geo_status":"db","era":"明治中期／平成22年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造一部木造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造一部木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0128","desc":"敷地西側に建つ。土蔵造二階建、切妻造桟瓦葺の店蔵と木造二階建、寄棟造桟瓦葺の蔵前からなり、建築面積四六平方メートル。蔵前二階に数寄屋風の小座敷を設け、望楼風の外観を呈する。白漆喰塗大壁と腰に下見板を張る外壁と併せて、香良洲の景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009476"},{"id":"00009475","register_sub_id":"101","register_pk":"194268","name":"八太正太夫酒店主屋","kana":"はったしょうだゆうさけてんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市香良洲町1094","lat":34.64777599,"lng":136.53466682,"geo_status":"db","era":"明治前期／明治後期増築・昭和後期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0127","desc":"敷地の北東に建ち、当初の主屋と北側に増築した新座敷、新座敷の東側へ突き出す角屋からなる。木造平屋建、当初主屋の西妻面は切妻造、東妻面は入母屋造、新座敷と角屋は切妻造で桟瓦葺、建築面積一七一平方メートル。歴代続く酒造業・地主の豪壮な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009475"},{"id":"00009478","register_sub_id":"101","register_pk":"194271","name":"八太正太夫酒店角蔵及び化粧室","kana":"はったしょうだゆうさけてんすみくらおよびけしょうしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県津市香良洲町1094","lat":34.64782596,"lng":136.53451894,"geo_status":"db","era":"明治17年／平成22年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺一部鉄板葺、建築面積8.5㎡","structure_material":"土蔵造及び木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0130","desc":"敷地北西隅に建つ。角蔵は土蔵造平屋建、切妻造桟瓦葺、西妻面に出入口を開き、木造平屋建、切妻造鉄板葺一部桟瓦葺の化粧室が蔵前となる。建築面積八平方メートル。基礎は玉石積とし下見板を腰高に張って鉢巻を廻し、外周する道路からの景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009478"},{"id":"00009477","register_sub_id":"101","register_pk":"194270","name":"八太正太夫酒店向い座敷及び下の蔵","kana":"はったしょうだゆうさけてんむかいざしきおよびしものくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県津市香良洲町1094","lat":34.64760991,"lng":136.53456463,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建及び土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"木造平屋建及び土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"24 － 0129","desc":"敷地西側に建つ。木造二階建の向かい座敷の北側に土蔵造二階建の下の蔵が接して建ち、西面に土庇を設ける。建築面積五九平方メートル。南から下の蔵、向かい座敷、蔵前、店蔵、角蔵と建ち、白漆喰塗に下見板を腰高に張る外壁を連続させ良好な景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009477"},{"id":"00000536","register_sub_id":"101","register_pk":"101526","name":"福岡醤油店","kana":"ふくおかしょうゆてん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市島ヶ原1330","lat":34.78104581,"lng":136.05354834,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積204㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"24 － 0015","desc":"醤油醸造のための建物で，麹室やボイラー室を含む。付近は昭和28年に大きな水害を受けたが，この建物は難を逃れている。室内に設置されている醤油を絞るための「キリン圧搾機」はおそらく現役としては他に例を見ない貴重なものであり，広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000536"},{"id":"00010463","register_sub_id":"101","register_pk":"202515","name":"保田家住宅蔵","kana":"ほだけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市上本町21","lat":34.619924,"lng":136.090188,"geo_status":"db","era":"明治9頃／明治中期改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0189","desc":"敷地奥、主屋後方の突出部と連結している。桁行、梁間とも二間の二階建が当初部で、二階東妻に桁行一間半分を拡張している。切妻造桟瓦葺で、正面と東側面の腰は海鼠壁とするが、ほかは漆喰塗である。小規模だが、商家の屋敷構えを引き立てる土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010463"},{"id":"00010462","register_sub_id":"101","register_pk":"202514","name":"保田家住宅主屋","kana":"ほだけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県名張市上本町21","lat":34.619986,"lng":136.090286,"geo_status":"db","era":"明治9頃／昭和43改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積206㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"24 － 0188","desc":"名張城下、神社参道の角地に位置する間口六間のつし二階建で、切妻造桟瓦葺。正面に竪格子構えの下屋を付け、内部は土間と板の間からなる広い吹抜の作業場をもつ特異な平面とする。正面外観は虫籠窓や格子窓、両端に袖壁を設け、城下の景観の重要な核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010462"},{"id":"00002773","register_sub_id":"101","register_pk":"103763","name":"松阪市文化財センター（旧カネボウ綿糸松阪工場綿糸倉庫）","kana":"まつさかしぶんかざいせんたー（きゅうかねぼうめんしまつさかこうじょうめんしそうこ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県松阪市外五曲町1","lat":34.57789675,"lng":136.520538,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"煉瓦造平屋建、鋼板葺、建築面積1044㎡","structure_material":"煉瓦造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"24 － 0044","desc":"鐘淵紡績松阪支店原綿倉庫として建設された。桁行約７４ｍ，梁間１０．６ｍの主体部の内部は桁行きに４室に区画し，正面には片流れの庇を付ける。煉瓦造イギリス積みで柱型を現した長大な外観を良くとどめるとともに，内部はギャラリーとして公開されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002773"},{"id":"00000053","register_sub_id":"101","register_pk":"101043","name":"宮崎本店事務所","kana":"みやざきほんてんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90975405,"lng":136.63386922,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0002","desc":"この地は，古くから鈴鹿川の伏流水を用いた酒造業が盛んであったが，宮崎本店は老舗酒造の一つである。木造モルタル塗，２階建の事務所は，２階外壁の一部をタイル張りとする住宅風の建物で，工場内唯一の洋風建築。正面妻壁上部のモチーフに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000053"},{"id":"00000056","register_sub_id":"101","register_pk":"101046","name":"宮崎本店第８倉庫","kana":"みやざきほんてんだいはちそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90988317,"lng":136.63334316,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0006","desc":"貯蔵庫Ａ棟の北隣にある木造２階建ての倉庫で，近年背面（北）側に併設された。外壁は土壁であるが，現在は亜鉛引き鉄板で覆われる。搬入口は新しく改修されているが，軸部の保存はよい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000056"},{"id":"00000055","register_sub_id":"101","register_pk":"101045","name":"宮崎本店第４倉庫","kana":"みやざきほんてんだいよんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90918973,"lng":136.63433311,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積655㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0005","desc":"貯蔵庫Ｂ棟の東隣にあるＬ型の木造２階建の大型倉庫で，元は酒蔵として造られたといわれる。構造的には３連の倉庫で，北側に搬入口を開き，１・２階とも窓を大きく開く点は他の倉庫群と異なる。整然とした外観は，酒造倉庫群の景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000055"},{"id":"00000057","register_sub_id":"101","register_pk":"101047","name":"宮崎本店貯蔵庫","kana":"みやざきほんてんちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90971818,"lng":136.63352728,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積480㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0007","desc":"本店事務所の向かいに建つ複合建物で，並列する２棟の２階建倉庫をＨ型に連結した形式になり，各面に庇が取り付く。北側の道に面して茶色の煉瓦造の煙突が付属し，黒壁を基調とする周囲の景観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000057"},{"id":"00000054","register_sub_id":"101","register_pk":"101044","name":"宮崎本店貯蔵庫Ａ棟","kana":"みやざきほんてんちょぞうこえーとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県四日市市楠町南五味塚慶応950","lat":34.90969427,"lng":136.63319969,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積278㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"24 － 0003","desc":"木造２階建，切妻造の重厚な構えになる大型の倉庫で，妻壁に亀甲宮の商標が描かれる。外壁の仕様は，他の倉庫群の仕様と異り，腰下が羽目板張りで，上部は下見板張りになって，一連の建物群のなかで中心的な存在であったことを示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000054"},{"id":"00014172","register_sub_id":"101","register_pk":"508802","name":"岩根醤油醸造店主屋","kana":"いわねしょうゆじょうぞうてんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字八木屋町910他","lat":35.50335278,"lng":136.22665833,"geo_status":"db","era":"江戸末期／大正13年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0498","desc":"北国街道木之本宿の醤油醸造業を営む町家。街道に西面し、二階建切妻造平入桟瓦葺で一階は出格子構え、二階は両端に袖壁を設けて四箇所の窓を開け、軒は腕木で支持する。外壁は真壁造漆喰塗仕上。内部は南に土間、北に二列五室を配す。宿場の発展を示す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014172"},{"id":"00001425","register_sub_id":"101","register_pk":"102415","name":"旧正野薬店店舗","kana":"きゅうしょうのやくてんてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字村井1283、1284","lat":35.01249231,"lng":136.25386555,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"25 － 0119","desc":"甲賀地方と並ぶ近江薬業の二大中心地である日野の薬店舗。平入り，つし二階建ての伝統的な町屋の形式からなる。二階は塗籠めとし，代表的な製薬「萬病感應丸」の看板を掲げる。地域の歴史的町並みの中核的な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001425"},{"id":"00001426","register_sub_id":"101","register_pk":"102416","name":"旧正野薬店東蔵","kana":"きゅうしょうのやくてんひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県蒲生郡日野町大字村井1284","lat":35.01247797,"lng":136.25398372,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"25 － 0120","desc":"店舗の東に隣接する二階建ての土蔵。屋根は切妻造，桟瓦葺で，平入りとする。道路に面する南妻の各階に窓，店舗に面する西面に入口を設け，北妻側に平屋建ての納戸が附属する。生薬を収納していた蔵であり，機能的にも景観的にも店舗と一体の施設として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001426"},{"id":"00004988","register_sub_id":"101","register_pk":"105978","name":"旧中川煉瓦製造所機械場","kana":"きゅうなかがわれんがせいそうじょきかいば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市船木町字東澤田59-1","lat":35.13866795,"lng":136.08092204,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造平屋建、建築面積112㎡","structure_material":"煉瓦造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"25 － 0235","desc":"事務所の南西に位置する。桁行１２ｍ，梁間１０ｍの煉瓦造平屋建で切妻造とする。壁面はイギリス積で，東面と南面に欠円アーチ形の出入口，西面に広い開口部をとる。コーニスにはデンティルを廻らし，外観にアクセントを与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004988"},{"id":"00004987","register_sub_id":"101","register_pk":"105977","name":"旧中川煉瓦製造所事務所","kana":"きゅうなかがわれんがせいぞうしょじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市船木町字東澤田59-1","lat":35.13885774,"lng":136.08100474,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造平屋建、建築面積50㎡","structure_material":"煉瓦造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"25 － 0234","desc":"敷地北東部，かつての正門近くに建つ。桁行６．２ｍ，梁間８．０ｍの煉瓦造平屋建で，切妻造，平入とする。イギリス積壁面に覆輪目地を用い，コーニスには鋸歯飾をあしらい，正面のピラスターやキーストン等に色合いの異なる煉瓦を使用するなど装飾的外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004987"},{"id":"00004989","register_sub_id":"101","register_pk":"105979","name":"旧中川煉瓦製造所縄縫工場","kana":"きゅうなかがわれんがせいぞうじょなわぬいこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市孫平治町1-1","lat":35.1377798,"lng":136.08404355,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積131㎡、門柱及び袖塀付","structure_material":"煉瓦造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"25 － 0236","desc":"工場敷地の約３００ｍ東方の角地に建つ。桁行２２ｍ，梁間６ｍの切妻造，妻入の煉瓦造平屋建で，壁面は小口積，基礎部イギリス積とする。コーニスとペディメントにデンティル，袖塀には煉瓦の屋根形をあしらうなど丁寧なつくりで，街路景観に彩りを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004989"},{"id":"00004986","register_sub_id":"101","register_pk":"105976","name":"旧中川煉瓦製造所ホフマン窯","kana":"きゅうなかがわれんがせいぞうしょほふまんがま","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市船木町字東澤田59-1","lat":35.13820275,"lng":136.08054156,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造、長径55m、短径14m、煙突1基付","structure_material":"煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"25 － 0233","desc":"市街地北部の八幡堀と接する敷地に建つ。長辺５５ｍ，短辺１４ｍの南北に長い平面で，南寄りに約３０ｍ高の煙突を建てる。中央煙道の周囲にアーチ構造体をほぼ環状に廻らし，イギリス積の外壁にはアーチ形開口部を設ける。残存例少ないホフマン窯の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004986"},{"id":"00007373","register_sub_id":"101","register_pk":"108355","name":"蔵元丸中醤油大蔵","kana":"くらもとまるなかしょうゆおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県愛知郡愛荘町東出229","lat":35.178631,"lng":136.254929,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積220㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0272","desc":"主屋後方に接して建つＬ字形平面の大型土蔵である。建築面積２２０㎡、土蔵造平屋建、切妻造桟瓦葺。外壁は土壁で、内法高まで竪板を張る。内部は店舗寄りを作業場とし、後方を醸造蔵として使用する。登梁を用いた和小屋が広い作業空間を造り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007373"},{"id":"00007375","register_sub_id":"101","register_pk":"108357","name":"蔵元丸中醤油奥醸造蔵","kana":"くらもとまるなかしょうゆおくじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県愛知郡愛荘町東出229","lat":35.178631,"lng":136.254791,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0274","desc":"敷地の西面中央、前醸造蔵と大蔵の間に建つ。桁行６．９ｍ梁間６．８ｍの木造２階建、南北棟の切妻造桟瓦葺。外壁は土壁で鉄板張とする。内部は梁上に束を建てて母屋を支える和小屋で、広い空間をつくる。もとは麹蔵と伝え、現在はカクオケを備えて醸造を行う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007375"},{"id":"00007372","register_sub_id":"101","register_pk":"108354","name":"蔵元丸中醤油店舗","kana":"くらもとまるなかしょうゆてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県愛知郡愛荘町東出229","lat":35.178505,"lng":136.254822,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0271","desc":"敷地南側の通りに面して建つ。間口８．８ｍ奥行７．１ｍ規模の木造２階建。切妻造桟瓦葺で、正面に深く下屋庇を設ける。真壁造で腰に竪板を張り、入口を１ｍほど後退させる。窓を２ヶ所開けた２階は高さを抑えており、落ち着いた佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007372"},{"id":"00007374","register_sub_id":"101","register_pk":"108356","name":"蔵元丸中醤油前醸造蔵","kana":"くらもとまるなかしょうゆまえじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県愛知郡愛荘町東出229","lat":35.178551,"lng":136.25473,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0273","desc":"通りに面して、主屋西側に並び建つ。桁行９．８ｍ梁間６．９ｍ、切妻造妻入桟瓦葺で東面を葺き降ろす。正面は妻を漆喰仕上げとし、竪板を高く張り、入口と窓を開ける。内部は方形のカクオケを備えて醸造を行い、葺き降ろし部分は土間で、荷捌きなどに使用する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007374"},{"id":"00001626","register_sub_id":"101","register_pk":"102616","name":"珠玖家住宅主屋","kana":"しくけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市西中野町3-14","lat":35.1076018,"lng":136.19436838,"geo_status":"db","era":"文政12以前","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0131","desc":"珠玖家は，代々醤油屋を営んだ灰谷家の分家で，明治２５年からマルハチの商標を継承する。主屋は御代参街道に東面する厨子二階建町家で，店舗及び作業場からなる広い土間と，居室２列を設け，上手１列を落棟とする。格子や摺上戸などの表構えも良く残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001626"},{"id":"00013126","register_sub_id":"101","register_pk":"368377","name":"白木屋醤油店主屋","kana":"しろきやしょうゆてんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本932","lat":35.50459722,"lng":136.22598651,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0440","desc":"旧北国街道木之本宿にあり、街道に西面して建つ。木造二階建平入で当地区では標準的な規模の町家である。一階平面は南側の通り土間に沿って三室を並べる一列三室型の構成で、二階は正面側に居室を設ける。木之本宿で旧街道沿いの歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013126"},{"id":"00012940","register_sub_id":"101","register_pk":"368020","name":"ダイコウ醤油主屋","kana":"だいこうしょうゆしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字八木屋町1137他","lat":35.50278056,"lng":136.22665,"geo_status":"db","era":"江戸末期／明治中期増築・改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 423","desc":"旧木之本宿南端で醸造業を営む商家。街道に東面して建つ切妻造桟瓦葺の二階建で、正面は上下階に平格子を入れ、出桁造とし、二階両端に袖壁を付す。内部は南に土間、北に2列6室を配し、上手奥を座敷とする。醸造業でも栄えた宿場町の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012940"},{"id":"00012939","register_sub_id":"101","register_pk":"368113","name":"冨田酒造主屋","kana":"とみたしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本1107","lat":35.50503889,"lng":136.22550833,"geo_status":"db","era":"延享元年（1744）／天保3年（1832）増築、江戸末期・昭和24年頃改修","year":1744,"year_source":"db","year_min":1744,"year_max":1744,"year_label":null,"structure":"木造2階建、瓦葺、建築面積270㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 422","desc":"旧木之本宿中心部の造り酒屋。街道に東面して建つ切妻造桟瓦葺つし二階建、大屋根前面を二段に重ねて南を落棟とし、北側に平屋棟を付す。落棟を含む南の広い土間沿いに3室を並べ、平屋棟に座敷等4室を配する。輻輳する屋根が街道景観に威容を誇る大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012939"},{"id":"00001197","register_sub_id":"101","register_pk":"102187","name":"中村商家保存館酒蔵","kana":"なかむらしょうかほぞんかんさけぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市旭町5","lat":35.27417335,"lng":136.2610881,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積109㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"25 － 0114","desc":"敷地の西端、主屋の背後に建つ南北棟、２階建、瓦葺切妻屋根の土蔵で、桁行約１５ｍ、梁間約７ｍの規模を有する。当家が酒醸業を営んでいた時代の酒蔵で、外部は改装されているが、内部はよく旧状を留めており、現在は資料展示室として保存公開されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001197"},{"id":"00001196","register_sub_id":"101","register_pk":"102186","name":"中村商家保存館文庫蔵","kana":"なかむらしょうかほぞんかんぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市旭町5","lat":35.2742058,"lng":136.261261,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造２階建，瓦葺，建築面積28㎡","structure_material":"土蔵造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"25 － 0113","desc":"敷地の北側中央、主屋座敷北前面の内庭に平の面をみせて建つ南北棟、２階建、瓦葺切妻屋根の土蔵。桁行７ｍ、梁間４ｍの規模で、南妻面に入口を設ける。扉や額縁回りの漆喰装飾に見どころがある丁寧な造りの蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001196"},{"id":"00007362","register_sub_id":"101","register_pk":"108344","name":"西澤家住宅洋館（旧伊藤製材所社屋）","kana":"にしざわけじゅうたくようかん（きゅういとうせいざいしょしゃおく）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県愛知郡愛荘町市878-10","lat":35.17573601,"lng":136.21261702,"geo_status":"db","era":"昭和前期／平成3移築改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0261","desc":"愛知川駅前の敷地に北面して建つ。桁行９．９ｍ梁間６．０ｍ、半切妻造平入の木造２階建。１階は事務室、２階は職人用の部屋であった。腰竪板張の下見板張とするスティックスタイルの建築で、正面は玄関を中心に縦長窓等を左右対称に配する。事務所建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007362"},{"id":"00001278","register_sub_id":"101","register_pk":"102268","name":"福井三四郎家住宅主屋（びれっじ２号館）","kana":"ふくいさんしろうけじゅうたくしゅおく（びれっじにごうかん）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県高島市勝野1320","lat":35.29633297,"lng":136.01218883,"geo_status":"db","era":"18世紀後期","year":1780,"year_source":"estimated","year_min":1761,"year_max":1800,"year_label":"18世紀後期","structure":"木造２階建，瓦葺，建築面積248㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"25 － 0115","desc":"桁行八間、梁間七間半、平入りの町屋で、かつての大溝城下町の町人地である本町通りの中央に位置する。つし二階建を設け、両妻には一段高く桟瓦葺きのうだつをのせる。かつては醤油の醸造販売に用いられていたが、現在は町並み保存の核施設とされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001278"},{"id":"00001280","register_sub_id":"101","register_pk":"102270","name":"福井三四郎家住宅室","kana":"ふくいさんしろうけじゅうたくむろ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県高島市勝野1320","lat":35.296341,"lng":136.01197417,"geo_status":"db","era":"19世紀前期","year":1820,"year_source":"estimated","year_min":1801,"year_max":1840,"year_label":"19世紀前期","structure":"土蔵造平屋建，瓦葺，建築面積29㎡","structure_material":"土蔵造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"25 － 0117","desc":"糀をねかせるための恒温の蔵である。二間半四方の規模を持ち、前面と北側面に吹き放しの作業場を設けている。屋根には切妻造の換気口が設けられ、前側に長く流れる屋根であたかも流造神社本殿のような外観を持ち、敷地の中でののアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001280"},{"id":"00007371","register_sub_id":"101","register_pk":"108353","name":"藤居本家東蔵煙突","kana":"ふじいほんけひがしぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町長野601","lat":35.18481483,"lng":136.20869342,"geo_status":"db","era":"大正12頃／昭和前期改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"煉瓦造、高さ11m","structure_material":"煉瓦造","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0270","desc":"敷地の北辺、仕込蔵と清酒蔵の間に建ち、清酒蔵の釜場に接続する。方１．３ｍの矩形平面になる煉瓦造煙突で、高さ１１ｍを測る。イギリス積。並び建つ土蔵の長大な白壁や屋根瓦の風合いと好対照をなす外観をもち、酒造場に相応しい歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007371"},{"id":"00007370","register_sub_id":"101","register_pk":"108352","name":"藤居本家東蔵試験室及び受検室","kana":"ふじいほんけひがしぐらしけんしつおよびじゅけんしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町長野601","lat":35.18449,"lng":136.208588,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0269","desc":"清酒蔵の西面南寄りに接続して建つ。建築面積９０㎡、木造平屋建、入母屋造妻入桟瓦葺。酒の製品検査を行う部屋などに内部を間仕切る。西正面は、真壁造で白漆喰仕上げとして腰板を張り、入母屋屋根の妻を塗り込めて虫籠窓を穿つなど、重厚な構えになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007370"},{"id":"00007368","register_sub_id":"101","register_pk":"108350","name":"藤居本家東蔵仕込蔵","kana":"ふじいほんけひがしぐらしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町長野601","lat":35.184719,"lng":136.208771,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積380㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0267","desc":"敷地北辺中央、道路脇の水路に面して、清酒蔵と並び建つ。桁行３２ｍ梁間１２ｍ、土蔵造２階建、寄棟造桟瓦葺。内部は柱を建て登らせて梁を受ける。外部は漆喰仕上げで、水路側の妻面に戸をたて、矩形の窓を配する。水路の石積などとともに歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007368"},{"id":"00007369","register_sub_id":"101","register_pk":"108351","name":"藤居本家東蔵清酒蔵","kana":"ふじいほんけひがしぐらせいしゅぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町長野601","lat":35.184631,"lng":136.208572,"geo_status":"db","era":"大正12頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積728㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"25 － 0268","desc":"敷地北西に仕込蔵と並び建つ。建築面積７２８㎡、土蔵造２階建、切妻造桟瓦葺。Ｌ字形平面の大規模土蔵で、試験室及び受検室を西面南寄りに接続、北側に酒米を蒸す釜場を設ける。外壁を軒裏まで漆喰で塗り込め、西壁の腰を竪板張とするなど、重厚な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007369"},{"id":"00014176","register_sub_id":"101","register_pk":"508806","name":"まちや倶楽部（旧西勝酒造）洗場","kana":"まちやくらぶ（きゅうにしかつしゅぞう）あらいば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.13825278,"lng":136.0921,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0502","desc":"醸造家の文庫蔵の西に建つ切妻造妻入桟瓦葺の東西棟で、かつての洗米及び米蒸の作業場。外壁は板張で南面西半に窓を二箇所開ける。内部は一室の土間で、東半に二階を設けて物置とし、上部は小屋組を現す。棟東半部に越屋根を設け、敷地中央部の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014176"},{"id":"00014173","register_sub_id":"101","register_pk":"508803","name":"まちや倶楽部（旧西勝酒造）主屋","kana":"まちやくらぶ（きゅうにしかつしゅぞう）おもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.13837222,"lng":136.09239444,"geo_status":"db","era":"明治前期／昭和47年・平成28年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0499","desc":"仲屋町通りの旧醸造家の主屋で二階建切妻造平入桟瓦葺。東正面は庇を付し、二階は虫篭窓を開け、北妻に卯建を備える。内部は南に土間、北に一列三室を並べ、東に庭を設けて一列二室の座敷を落棟で接続する。間口が大きく近江八幡の町人地の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014173"},{"id":"00014180","register_sub_id":"101","register_pk":"508810","name":"まちや倶楽部（旧西勝酒蔵）北仕込蔵","kana":"まちやくらぶ（きゅうにしかつしゅぞう）きたしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.13845556,"lng":136.09188333,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造及び木造2階建、瓦葺、建築面積163㎡","structure_material":"鉄筋コンクリート造及び木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0506","desc":"南仕込蔵及び通り蔵の北に建つ、二階建切妻造平入桟瓦葺の東西棟の仕込蔵。かつての酒の仕込み作業場で外壁はモルタル仕上。一階は鉄筋コンクリート造、二階は木造とした混構造で、小屋組はクイーンポスト・トラスとする。敷地北部の景観をつくる大規模な蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014180"},{"id":"00014178","register_sub_id":"101","register_pk":"508808","name":"まちや倶楽部（旧西勝酒造）麹蔵","kana":"まちやくらぶ（きゅうにしかつしゅぞう）こうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.13829444,"lng":136.09197778,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"土蔵造平屋建、瓦葺、建築面積41㎡","structure_material":"土蔵造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0504","desc":"醸造家の酛蔵の西に建つ、切妻造平入桟瓦葺の南北棟の麹蔵。かつて麹造りをした蔵で、外壁は軒裏まで漆喰で塗込め、腰は縦板張とする。東面に戸口、西面に窓を一箇所開ける。内部は一室の板敷とし、壁及び天井を板張として密封する。酒造工程を示す土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014178"},{"id":"00014174","register_sub_id":"101","register_pk":"508804","name":"まちや倶楽部（旧西勝酒造）中央蔵","kana":"まちやくらぶ（きゅうにしかつしゅぞう）ちゅうおうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.13823889,"lng":136.09223333,"geo_status":"db","era":"明治前期／昭和中期増築・令和2年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積139㎡","structure_material":"土蔵造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0500","desc":"主屋南西に建つ、切妻造妻入桟瓦葺の東西棟の土蔵。かつての瓶詰所で、主体部西側に棟が低い中棟と西棟が続き長大な蔵となる。東西妻に戸口を設け、南面西半に下屋を付す。内部は一室の土間で東端に二階を設け、上部は小屋組を現す。酒造業の構成を示す土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014174"},{"id":"00014181","register_sub_id":"101","register_pk":"508811","name":"まちや倶楽部（旧西勝酒蔵）槽蔵","kana":"まちやくらぶ（きゅうにしかつしゅぞう）ふなぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.138575,"lng":136.09183056,"geo_status":"db","era":"明治44年／昭和34年増築・平成25年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積132㎡","structure_material":"土蔵造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0507","desc":"北仕込蔵の北に建つ切妻造平入桟瓦葺の東西棟の槽蔵。かつての酒絞りの作業場で、南面に下屋を付し、仕込蔵との間に渡廊下を設ける。内部は土間一室で、小屋組はキングポスト・トラス。外壁は漆喰で軒まで塗込め重厚にみせ、敷地北辺の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014181"},{"id":"00014175","register_sub_id":"101","register_pk":"508805","name":"まちや倶楽部（旧西勝酒造）文庫蔵","kana":"まちやくらぶ（きゅうにしかつしゅぞう）ぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.13831667,"lng":136.09221389,"geo_status":"db","era":"寛保元年(1741)／昭和中期・令和二年改修","year":1741,"year_source":"db","year_min":1741,"year_max":1741,"year_label":null,"structure":"土蔵造2階建、鉄板葺及び瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0501","desc":"旧造り酒屋の主屋北西に建つ切妻造妻入鉄板葺の文庫蔵。東西棟の両妻に戸口を設け、東妻に下屋を付す。外壁は軒裏まで漆喰で塗込めて重厚にみせる。内部一階は一室で南西隅に階段を設けて、二階は三室に間仕切る。主屋南西部の景観をつくる敷地内最古の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014175"},{"id":"00014179","register_sub_id":"101","register_pk":"508809","name":"まちや倶楽部（旧西勝酒蔵）南仕込蔵及び通り蔵","kana":"まちやくらぶ（きゅうにしかつしゅぞう）みなみしこみぐらおよびとおりぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.13837778,"lng":136.09195833,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積100㎡","structure_material":"土蔵造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0505","desc":"醸造家の麹蔵北に建つ、切妻造妻入桟瓦葺の南北棟の仕込蔵。東に切妻造平入桟葺の東西棟の通り蔵を付す。かつての酒の仕込み作業場で、外壁は軒裏まで漆喰で塗込める。仕込蔵の内部は一室の土間で、中央に独立柱を立てて地棟を支える。酒造工程を示す土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014179"},{"id":"00014177","register_sub_id":"101","register_pk":"508807","name":"まちや倶楽部（旧西勝酒造）酛蔵","kana":"まちやくらぶ（きゅうにしかつしゅぞう）もとぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市仲屋町中15-1","lat":35.13832778,"lng":136.09205278,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"25-0503","desc":"醸造家の洗場北に建つ二階建切妻造平入桟瓦葺の東西棟の酛蔵。かつて酒母造りをした蔵で、外壁は軒裏まで漆喰で塗込め、北壁以外の三面に格子窓を開ける。一階は一室の土間で三箇所の吹抜があり、二階は一室の板敷で上部は小屋組を現す。酒造工程を示す土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014177"},{"id":"00013740","register_sub_id":"101","register_pk":"505287","name":"山路酒造主屋","kana":"やまじしゅぞうおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字中ノ町990","lat":35.50736389,"lng":136.22443889,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積383㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 471","desc":"北国街道に西面し長大な間口を構えて酒造業を営む。二階建入母屋造平入の南側に、平屋建の座敷棟を道から控えて接続する。北棟は北を土間、南を二列六室とし、座敷棟は二列四室を並べて、南に続き間の座敷を配する。木之本宿を代表する昭和初期の大規模町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013740"},{"id":"00001289","register_sub_id":"101","register_pk":"102279","name":"池田家住宅","kana":"いけだけじゅうたく","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市住吉区住吉1-9-22","lat":34.61220042,"lng":135.496063,"geo_status":"db","era":"明治25頃","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造２階建，瓦葺，建築面積100㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"27 － 0073","desc":"旧熊野街道と旧住吉街道が交差する角地に建つ店舗兼住宅。元禄年間に酒造業をはじめ後に味噌醸造を行ったと伝える家で，住宅は旧熊野街道に面した土蔵造，２階建で２階に虫籠窓を開く標準的な平入町家である。｢住之江味噌｣の製造元として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001289"},{"id":"00007089","register_sub_id":"101","register_pk":"108071","name":"岩根家住宅酒蔵","kana":"いわねけじゅうたくさけぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府富田林市五軒家2-1525-1","lat":34.510769,"lng":135.56242878,"geo_status":"db","era":"明治中期／平成9改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鋼板葺、建築面積476㎡、煙突付","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0464","desc":"奥座敷の北、敷地の北西寄りに建つ。建築面積４７６㎡、土蔵造２階建、切妻造スレート葺。内部に広く高い空間を造る。麹室は煉瓦造で、その上には煉瓦造煙突を立ち上げ、醸造蔵の面影を伝える。大きな切妻屋根が特徴的な酒蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007089"},{"id":"00002561","register_sub_id":"101","register_pk":"103551","name":"大阪セルロイド会館","kana":"おおさかせるろいどかいかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区大今里西2-5-12","lat":34.669701,"lng":135.54007,"geo_status":"db","era":"昭和6／昭和12移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積313㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.11.20(平成13.11.20)","register_no":"27 － 0163","desc":"Ｌ型平面の北半部に南側を増築。表現派風の卵頭形断面の列柱を配した北東面と，町家風の窓と庇の意匠をとる南東面は時代差を反映して対照的であるが，１階の庇，２階のアーチ窓，３階の軒のスペイン瓦とが統一的な一体感ある表情をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002561"},{"id":"00004598","register_sub_id":"101","register_pk":"105588","name":"カタシモワインフード貯蔵庫","kana":"かたしもわいんふーどちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府柏原市太平寺2-9-14","lat":34.583607,"lng":135.632584,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造及び鉄筋コンクリート造2階建、鉄板葺、建築面積48㎡","structure_material":"木造及び鉄筋コンクリート造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"27 － 0311","desc":"堅下ワインの醸造に係わる貯蔵施設で，１階をワイン貯蔵室，２階を資料室とする。陸屋根の２階建で，柱や梁は木造軸組，外壁と床を鉄筋コンクリート造とした，混構造の初期事例。全体に簡素であるが，数少ない地場産業施設であり，地域の景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004598"},{"id":"00002157","register_sub_id":"101","register_pk":"103147","name":"佐竹ガラス作業場","kana":"さたけがらすさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府和泉市幸2-11-30","lat":34.502716,"lng":135.438248,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積495㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"27 － 0138","desc":"敷地奥，溶解場の東面と接する。木造平屋建，桟瓦葺でＬ字形平面を持つ。棒ガラスを製造する作業棟として使われる。内部では，他の工場同様，四方に方杖を付ける柱がキングポストトラス形式の小屋組を受ける。全体と調和した外観で屋敷構の内向部を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002157"},{"id":"00002155","register_sub_id":"101","register_pk":"103145","name":"佐竹ガラス事務所","kana":"さたけがらすじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市幸2-11-30","lat":34.502556,"lng":135.438202,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"27 － 0136","desc":"主屋の北西面に接続する。木造平屋建，寄棟造，桟瓦葺で，主屋と棟方向を合わせる。通り側に庇を出し，反対側の増築部分との間に約３ｍ幅の通路を設ける。街路に面した屋敷の景観構成要素として欠かせない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002155"},{"id":"00002158","register_sub_id":"101","register_pk":"103148","name":"佐竹ガラス調合場","kana":"さたけがらすちょうごうじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府和泉市幸2-11-30","lat":34.50279217,"lng":135.43801655,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋一部2階建、瓦葺、建築面積39㎡","structure_material":"木造平屋一部2階建","registered":"2001.04.24(平成13.04.24)","register_no":"27 － 0139","desc":"溶解場の北面と接し，ほぼ東西方向に棟を通す。木造平屋建，切妻造，桟瓦葺で，棟の東側に越屋根を載せる。腰を竪板貼，上部を白漆喰とし下庇を廻した西棟と，外装下見板貼とした東棟から成る。材料の調合棟として用いられ，当初従業員の宿舎棟も兼ねていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002158"},{"id":"00002156","register_sub_id":"101","register_pk":"103146","name":"佐竹ガラス溶解場","kana":"さたけがらすようかいじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府和泉市幸2-11-30","lat":34.5026709,"lng":135.43807214,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積295㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"27 － 0137","desc":"事務所の北西に位置する木造平屋建，入母屋造，桟瓦葺の工場。内部にガラス溶解炉が備えつけられる。棟のほぼ中央部に気抜用の越屋根を載せ，通り側に下見板を貼った大きな妻面を見せる。町工場らしい外観で市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002156"},{"id":"00002423","register_sub_id":"101","register_pk":"103413","name":"成子家住宅酒蔵一","kana":"なるこけじゅうたくさかぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.3638407,"lng":135.24157986,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"土蔵造2階建、瓦葺、建築面積148㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0148","desc":"敷地北東，土蔵二と棟を直行させ，北西にはしる裏通りに並行して建つ酒蔵。桁行８間，梁間５間半規模の木造，切妻２階建で，焼板を縦に軒まで貼上げ本瓦を葺く。主屋や離れといった居室部分を取り囲むようにして建つ４つの酒蔵のうち規模としては最も小さい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002423"},{"id":"00002425","register_sub_id":"101","register_pk":"103415","name":"成子家住宅酒蔵三","kana":"なるこけじゅうたくさかぐらさん","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.36414845,"lng":135.24141908,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"土蔵造2階建、瓦葺、建築面積257㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0150","desc":"敷地の北西を区切る，木造２階建切妻本瓦葺の酒蔵。桁行１２間，梁間６間半規模の身舎部分に，現状では北面に附属蔵を連ね，下屋を張り出す。小屋組は，側から２間通りに柱をたて，桁を渡し，側柱から登り梁，中央部に水平梁を架け，長大な内部空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002425"},{"id":"00002424","register_sub_id":"101","register_pk":"103414","name":"成子家住宅酒蔵二","kana":"なるこけじゅうたくさかぐらに","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.363998,"lng":135.24165519,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"土蔵造2階建、瓦葺、建築面積193㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0149","desc":"敷地北，酒蔵一と同じく北西にはしる裏通りに並行して建つ酒蔵。桁行９間，梁間６間半規模の木造，切妻造２階建で，焼板を縦に軒まで貼り上げ本瓦を葺く。酒蔵一と軒を連ねて建ち，その偉容は尾崎の歴史的町並みの景観形成上重要な要素のひとつとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002424"},{"id":"00002426","register_sub_id":"101","register_pk":"103416","name":"成子家住宅酒蔵四","kana":"なるこけじゅうたくさかぐらよん","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.363964,"lng":135.24118,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"土蔵造2階建、瓦葺、建築面積227㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0151","desc":"妻面を表通りに面し，敷地南西を区切って建つ，木造切妻２階建の酒蔵。桁行１６間，梁間４間半の大規模な構えで，焼板を縦に軒まで貼り上げ桟瓦を葺く。西側面は軒下を漆喰仕上げとする。小屋組は，水平梁，投げかけ梁を２間ごとに架ける豪壮なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002426"},{"id":"00013602","register_sub_id":"101","register_pk":"504599","name":"久金属工業技術室","kana":"ひさきんぞくこうぎょうぎじゅつしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.65186667,"lng":135.48250833,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0806","desc":"工場敷地の北側、東門脇に建つ工場移転当時の旧事務所兼住宅。木造二階建、入母屋造桟瓦葺で西面と南面に半間の下屋を回す。一階は入口脇を執務室とし、北東隅に応接室を置く。二階は神棚や仏壇を備えた座敷等を配す。創業時の様相をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013602"},{"id":"00013600","register_sub_id":"101","register_pk":"504597","name":"久金属工業旧社長室","kana":"ひさきんぞくこうぎょうきゅうしゃちょうしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.65179167,"lng":135.48251944,"geo_status":"db","era":"昭和12年頃／令和元年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0804","desc":"技術室の南隣に建つ。正面に旧社長室を構え、奥に旧食堂が繋がる。旧社長室は小規模だが丁寧なつくりで内装や家具も良く残る。正面はスクラッチタイル貼、腰は鉄平石張、軒高にスペイン瓦の小庇を廻し、上げ下げ窓を左右対称に配した格調ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013600"},{"id":"00013605","register_sub_id":"101","register_pk":"504602","name":"久金属工業旧倉庫","kana":"ひさきんぞくこうぎょうきゅうそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.65179167,"lng":135.48233056,"geo_status":"db","era":"昭和9年頃／昭和12年頃改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造一部2階建、鉄板葺、建築面積207㎡","structure_material":"木造一部2階建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0809","desc":"事務所の東に正門を挟んで建つ。桁行一九メートル、梁間一一メートルの原材料を保管していた大型倉庫で、木造二階建切妻造鉄板葺とし、南の一部は平屋建越屋根付の屋根とする。南面は下見板張や小庇付引違窓などで、品質管理室と統一的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013605"},{"id":"00013604","register_sub_id":"101","register_pk":"504601","name":"久金属工業旧第一工場","kana":"ひさきんぞくこうぎょうきゅうだいいちこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.6516,"lng":135.48257222,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積309㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0808","desc":"工場敷地の南東側に位置する。木造平屋建、桁行二四メートル、梁間一三メートルの工場で、屋根は切妻造鉄板葺である。小屋組は和小屋とトラスを組み合わせた特異な構造で、採光のため幅広の越屋根を付す。金属工場の主要施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013604"},{"id":"00013606","register_sub_id":"101","register_pk":"504603","name":"久金属工業旧防空壕","kana":"ひさきんぞくこうぎょうきゅうぼうくうごう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.65171111,"lng":135.48225278,"geo_status":"db","era":"昭和9年頃／昭和42年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、陸屋根、建築面積9.4㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0810","desc":"正門を入った正面にある築山の裏手に位置。鉄筋コンクリート造平屋建の元防空壕との伝承を持つ。北面は築山に接し、南面に格子窓を左右対称に配置する。戦後に便所として改修され、地下壕は浄化槽に転用されたとみられるが、外観は往事の姿を良好に留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013606"},{"id":"00013599","register_sub_id":"101","register_pk":"504596","name":"久金属工業事務所","kana":"ひさきんぞくこうぎょうじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.65177222,"lng":135.4821,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積280㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0803","desc":"正門西脇に建つ金属工場の事務所棟。東を寄棟造、西を切妻造とした木造二階建で、南に倉庫が接続する。外観は北・東面及び南面の一部をタイル貼とし手摺を付けた引違い窓を並べる。北面道路側にフランス瓦葺の小庇を付け、工場の表構えと街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013599"},{"id":"00013603","register_sub_id":"101","register_pk":"504600","name":"久金属工業守衛室","kana":"ひさきんぞくこうぎょうしゅえいしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.65185,"lng":135.48240556,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0807","desc":"東門（旧正門）の小規模な守衛室。屋根は寄棟造鉄板葺で、外壁は下見板張とする。正面の窓枠両端を円弧とし、北面窓も半円アーチとして外観のアクセントとする。室内は畳敷で、受付のため、小物入等を備えたカウンターを造り付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013603"},{"id":"00013607","register_sub_id":"101","register_pk":"504604","name":"久金属工業正門","kana":"ひさきんぞくこうぎょうせいもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.65185278,"lng":135.48223333,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造門柱、間口3.3m、左右袖塀付","structure_material":"鉄筋コンクリート造門柱","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0811","desc":"敷地南側接道部分のほぼ中央に建つ。門柱は鉄筋コンクリート造で、洗い出し仕上とし、柱頭に楕円形の庇をのせる。柱の上部には照明のための障子形の枠を嵌め、乳白ガラスに「久」の字をアレンジした社章をあしらう。独特な意匠で工場の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013607"},{"id":"00013601","register_sub_id":"101","register_pk":"504598","name":"久金属工業品質管理室","kana":"ひさきんぞくこうぎょうひんしつかんりしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西成区北津守三丁目52","lat":34.65174444,"lng":135.48253611,"geo_status":"db","era":"昭和12年頃／令和元年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0805","desc":"旧社長室の南側に接して建つ。桁行九・一メートル、梁間五・四メートルの木造平屋建の建物。屋根は半切妻造スレート葺で外壁は下見板張とし、正面と南面に持送付きの小庇を付けた引違い窓が並ぶ。小規模ながらも左右対称の整った外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013601"},{"id":"00003119","register_sub_id":"101","register_pk":"104109","name":"山野家住宅酒蔵一","kana":"やまのけじゅうたくさかぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府交野市私部7-11-2","lat":34.789055,"lng":135.684219,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積194㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0208","desc":"主屋の背後に並ぶ酒造用の蔵の１つで屋敷北西隅に建つ。土蔵造，２階建，切妻造，桟瓦葺で，外部は漆喰塗とし高く腰板を張る。建築年代が最も遡る蔵で，小屋組は和小屋を組む。すぐ南の酒蔵，主屋北の住宅蔵とともに大小の妻面を通りに見せ独特の景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003119"},{"id":"00003120","register_sub_id":"101","register_pk":"104110","name":"山野家住宅酒蔵四","kana":"やまのけじゅうたくさかぐらよん","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府交野市私部7-11-2","lat":34.78891407,"lng":135.68428943,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積128㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0209","desc":"北西隅の酒蔵一の南に接して建つ。２階建，切妻造，桟瓦葺で，梁間に比して桁行に長い平面を持つ。麹をつくるための施設で，東妻に出入口，小窓を開ける以外は開口部を設けず，内部は全面板張りとする。酒蔵一，南の住宅蔵と並び屋敷北西部の構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003120"},{"id":"00011782","register_sub_id":"101","register_pk":"210798","name":"阿江ハンカチーフ旧寄宿舎","kana":"あえはんかちーふきゅうきしゅくしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野字安井593-3他","lat":34.936748,"lng":134.955731,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0669","desc":"検反場二の北に南北棟で建つ。桁行二二メートル、梁間五メートル二階建、切妻造。西面中央に玄関を付ける。内部は一、二階とも一〇畳を四室並べる。外壁はモルタル仕上げとし、玄関は円柱とする。織物産業を支えた工員の生活が窺える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011782"},{"id":"00011779","register_sub_id":"101","register_pk":"210795","name":"阿江ハンカチーフ旧工場","kana":"あえはんかちーふきゅうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加東市下滝野字安井593-3他","lat":34.936565,"lng":134.955421,"geo_status":"db","era":"明治44年／昭和62年頃改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積451㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0666","desc":"力織機の導入に伴い建設された六連片流屋根の工場。西を正面とし、桁行一五メートル、梁間二九メートルの規模は一間毎に配置する織機の大きさに合わせたもの。桁行半間毎にトラスを架け片流屋根で採光窓も残る。明治創業時の工場の様相を今に伝える建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011779"},{"id":"00011783","register_sub_id":"101","register_pk":"210799","name":"阿江ハンカチーフ旧食堂","kana":"あえはんかちーふきゅうしょくどう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野字安井593-3他","lat":34.936769,"lng":134.955589,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0670","desc":"旧寄宿舎の北西に東西棟で建つ。桁行一一メートル、梁間六メートル、切妻造桟瓦葺。外壁は下見板張でペンキ塗とする。内部は現在改装されているが、瓦材など外観はよく残る。旧寄宿舎とともに、織物産業の従業員の生活様式を垣間見ることのできる施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011783"},{"id":"00011784","register_sub_id":"101","register_pk":"210800","name":"阿江ハンカチーフ旧製品倉庫","kana":"あえはんかちーふきゅうせいひんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野字安井593-3他","lat":34.936918,"lng":134.955806,"geo_status":"db","era":"昭和23年頃","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0671","desc":"東側敷地の北西角で道路に面して建つ。桁行九・九メートル、梁間五・九メートル、木造二階建、切妻造で、正面に下屋を付す。両開扉は鉄板張とし、二階南北面に各二所ずつ鉄格子入窓を開く。小屋はキングポストトラス。織物産業の関連施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011784"},{"id":"00011780","register_sub_id":"101","register_pk":"210796","name":"阿江ハンカチーフ検反場一","kana":"あえはんかちーふけんたんばいち","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加東市下滝野字安井593-3他","lat":34.936539,"lng":134.955018,"geo_status":"db","era":"明治44年／昭和62年頃改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積347㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0667","desc":"旧工場の北西に建つ。桁行一五メートル、梁間二五メートル、南東隅方一間を欠込み、その東面を出入口とする。屋根は三連片流、桟瓦葺。外壁は鉄板で覆い、内部は一室とする。旧工場とともに明治創業時の工場の様相を今に伝える遺構の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011780"},{"id":"00011781","register_sub_id":"101","register_pk":"210797","name":"阿江ハンカチーフ検反場二","kana":"あえはんかちーふけんたんばに","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県加東市下滝野字安井593-3他","lat":34.936607,"lng":134.955832,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0668","desc":"西側敷地の東面中央に開く門の北側に位置する。桁行八・九メートル、梁間三・八メートルで南面し、小屋はトラス組で屋根は片流桟瓦葺とする。外壁は下見板張で、内壁はペンキ塗とし、採光窓など良く残る。織物産業の生産工程を伝える施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011781"},{"id":"00016568","register_sub_id":"101","register_pk":"574930","name":"稲見酒造煙突","kana":"いなみしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和後","pref":"兵庫県","address":"兵庫県三木市芝町375-1他","lat":34.80042194,"lng":134.99315889,"geo_status":"db","era":"昭和41年頃","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"コンクリート造、高さ18m","structure_material":"コンクリート造","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0855","desc":"敷地の中央、瓶場兼貯酒庫の北側に立つ、かつての米蒸釜用の丸型煙突。鉄筋コンクリート造、高さ約18メートル、基底部は直径約1・４メートルで、下方のみ内壁に沿って煉瓦を積み上げる。上方に向けて窄まる形状で高く聳え、酒造業の象徴的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016568"},{"id":"00016570","register_sub_id":"101","register_pk":"574932","name":"稲見酒造黒塀","kana":"いなみしゅぞうくろべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市芝町375-1他","lat":34.80042194,"lng":134.99315889,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、延長32m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0857","desc":"敷地東辺の北半を画す塀。木造、折曲り延長三二メートル、高さ二・一メートル。石積基礎上に半間毎に柱を立て、上部の腕木で桁を支持し、屋根は桟瓦葺とする。壁は真壁の漆喰塗仕上とし、外側に焼杉板を高く張る。通り沿いに造酒屋の歴史的景観をつくる黒塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016570"},{"id":"00016566","register_sub_id":"101","register_pk":"574928","name":"稲見酒造熟成蔵","kana":"いなみしゅぞうじゅくせいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県三木市芝町513他","lat":34.80042194,"lng":134.99315889,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積97㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0853","desc":"敷地中央の西寄りに建つ酒の熟成用の蔵。二階建切妻造桟瓦葺の東西棟で漆喰塗で軒まで塗込め、焼杉板を高く張る。一階は南北２室の土間で北・東に戸口を開ける。北半はかつて精米場で上部を吹抜とし、小屋組は登梁形式の和小屋。敷地北西の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016566"},{"id":"00016569","register_sub_id":"101","register_pk":"574931","name":"稲見酒造巽塀","kana":"いなみしゅぞうたつみべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県三木市芝町513","lat":34.80042194,"lng":134.99315889,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"コンクリート造、総延長21m、木戸付","structure_material":"コンクリート造","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0856","desc":"敷地東辺の南半を画し、南西に折れ曲がる塀。折曲り延長２１メートル、高さ２・2メートル、鉄筋コンクリート造で柱型をみせ、頂部を笠石状につくり、外壁はモルタル洗出仕上とする。中央部に妻壁風の目隠壁を立上げた独特な外観が、通りの景観に異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016569"},{"id":"00016564","register_sub_id":"101","register_pk":"574926","name":"稲見酒造店舗兼主屋","kana":"いなみしゅぞうてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県三木市芝町513他","lat":34.80042194,"lng":134.99315889,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺及び銅板葺、建築面積206㎡、南西高塀付","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0851","desc":"湯の山街道に南面して建つ造酒屋の店舗兼主屋。二階建入母屋造平入桟瓦葺で、外壁は黒漆喰塗で軒まで塗込め、正面隅に鏝絵で飾った持送を付す。一階東は土間、西は六室を配し、南西を主座敷とする。間口長大で重厚な外観が、地域の歴史的景観の核となる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016564"},{"id":"00016565","register_sub_id":"101","register_pk":"574927","name":"稲見酒造土蔵","kana":"いなみしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県三木市芝町513他","lat":34.80042194,"lng":134.99315889,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺及び銅板葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0852","desc":"主屋の北西に位置する内蔵。二階建切妻造平入桟瓦葺で、東面南寄りに戸口を開け、南東隅に矩折に下屋を付す。外壁は黒漆喰塗で頂部に鉢巻を廻らし腰は竪板張。各階一室の板敷で、小屋組は束立の和小屋。二階の各窓庇の持送を鏝絵で飾るなど外観華やかな土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016565"},{"id":"00016567","register_sub_id":"101","register_pk":"574929","name":"稲見酒造瓶場兼貯酒庫","kana":"いなみしゅぞうびんばけんちょしゅこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県三木市芝町513他","lat":34.80042194,"lng":134.99315889,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺及び銅板葺、建築面積91㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0854","desc":"敷地中央に建つ生酒の火入や瓶詰作業用の倉庫。二階建切妻造桟瓦葺の南北棟で西に下屋を付し、北に便所棟を突出する。北・東に戸口を開け、１階は土間の作業場、二階は倉庫と畳敷の部屋を配する。南面はモルタル洗出仕上とし、石造風の重厚な外観とした倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016567"},{"id":"00013614","register_sub_id":"101","register_pk":"504985","name":"今村家住宅陶々菴","kana":"いまむらけじゅうたくとうとうあん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県丹波篠山市西町字柚ノ木64-4他","lat":35.07535,"lng":135.21051111,"geo_status":"db","era":"明治38年／明治41年・昭和14年移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"28 － 0744","desc":"篠山城北西の旧街道角地にある元製陶工房。陶々菴は東側道路沿いに南面して建つ主屋で、工房時代の元店舗。切妻造で四周に下屋を廻し、外壁は漆喰で軒先まで塗込める。内部は東を土間、西を二列四室とし、北西座敷に床を付す。旧城下の町家の様相を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013614"},{"id":"00013616","register_sub_id":"101","register_pk":"504987","name":"今村家住宅土蔵","kana":"いまむらけじゅうたくどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県丹波篠山市西町字柚ノ木64-4他","lat":35.07537222,"lng":135.21043611,"geo_status":"db","era":"明治38年／明治41年・昭和14年移築","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"28 － 0746","desc":"陶々菴西側に南面して建つ。置屋根形式の土蔵造桟瓦葺で、正面下屋を陶々菴に繋がる濡縁とする。外壁は漆喰で軒先まで塗込め、軒裏は繰形を付けた垂木形を現し、腰は竪板張。内部は一階は竪板張で二階は漆喰塗。陶々菴と共に、敷地中央の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013616"},{"id":"00016574","register_sub_id":"101","register_pk":"574936","name":"梶間家住宅内蔵","kana":"かじまけじゅうたくうちくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字伊澤町375","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積28㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0861","desc":"主屋の北東に中庭を介して建つ家財蔵。二階建切妻造平入桟瓦葺の南北棟で、西面南寄りに戸口を開け下屋を付す。外壁漆喰塗で正面腰は海鼠壁とモルタル洗出仕上。各階１室で小屋組は登梁形式。小規模ながら戸口に重厚な掛子塗扉を吊るなど丁寧なつくりの内蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016574"},{"id":"00016572","register_sub_id":"101","register_pk":"574934","name":"梶間家住宅主屋","kana":"かじまけじゅうたくおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字伊澤町375","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"明治25年／昭和45年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積272㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0859","desc":"伊澤町通りに西面する旧造酒屋の主屋。つし二階建切妻造平入桟瓦葺で正面下屋を付し、二階は木瓜形の虫籠窓を開け袖壁を付す。内部は３列９室を配し、正面中央に慶弔時の出入口を設け、土間南西に旧ウシヤを配す。間口長大で地域の歴史的景観の核となる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016572"},{"id":"00016578","register_sub_id":"101","register_pk":"574940","name":"梶間家住宅旧酒蔵","kana":"かじまけじゅうたくきゅうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字富士野町470-2","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"明治31年／昭和24年・同38年改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造2階建、瓦葺、建築面積402㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0865","desc":"敷地中央に建つ酒蔵を転用した製材作業場。２階建切妻造桟瓦葺東西棟で南・北面に下屋を付す。１階は広大な土間の作業場で棟筋と本屋筋に独立柱を立て、本屋のみ二階床を張る。小屋組は登梁を頬杖で支える堅牢なつくり。大型の旧酒蔵が酒造業の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016578"},{"id":"00016580","register_sub_id":"101","register_pk":"574942","name":"梶間家住宅隣屋敷内蔵","kana":"かじまけじゅうたくとなりやしきうちくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字伊澤町375","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0867","desc":"隣屋敷の主屋東側に中庭を介して建つ家財蔵。二階建切妻造平入桟瓦葺で西・南に下屋を付す。外壁は漆喰塗で軒は垂木形に塗込め、正面腰は海鼠壁仕上とする。各階一室の板敷で小屋組は束立の和小屋。戸口に重厚な掛子塗戸を吊り、全体に丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016580"},{"id":"00016579","register_sub_id":"101","register_pk":"574941","name":"梶間家住宅隣屋敷主屋","kana":"かじまけじゅうたくとなりやしきおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字伊澤町375","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0866","desc":"主屋の北隣に位置する接客用屋敷の主屋。二階建切妻造平入桟瓦葺で、１階は細格子の出格子構え、二階外壁は黒漆喰塗仕上で袖壁を付す。一階は一列２室、二階は田の字に４室を配す。二階座敷は床脇に天袋と違棚、琵琶台を備え、数寄屋風意匠の瀟洒なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016579"},{"id":"00016576","register_sub_id":"101","register_pk":"574938","name":"梶間家住宅中蔵","kana":"かじまけじゅうたくなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字伊澤町375他","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"明治前期／平成10年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0863","desc":"敷地南辺中央部に建つ醤油や味噌などの収納蔵。二階建切妻造平入桟瓦葺で北面に下屋を付し、西寄りに戸口を開く。外壁漆喰塗で側面の腰は海鼠壁仕上。各階一室の板敷で小屋組は束立の和小屋。全体に丁寧なつくりの土蔵で、下屋の木瓜形窓が外観のアクセント。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016576"},{"id":"00016575","register_sub_id":"101","register_pk":"574937","name":"梶間家住宅西蔵","kana":"かじまけじゅうたくにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字伊澤町375他","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"明治後期／平成10年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0862","desc":"敷地の南東隅に建つ酒造用具を収納した蔵。通りに西面する二階建入母屋造妻入桟瓦葺、外壁は漆喰塗で焼杉板を高く張り、正面に戸口と窓を設ける。一階は土間、二階は板敷で曲がりの強い梁を用いた和小屋を現す。主屋と並び建ち、通りの歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016575"},{"id":"00016573","register_sub_id":"101","register_pk":"574935","name":"梶間家住宅離れ","kana":"かじまけじゅうたくはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字伊澤町375","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"昭和6年／平成18年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0860","desc":"主屋の東側に渡り廊下で接続する隠居屋。平屋建切妻造桟瓦葺の東西棟で、南面に土庇を付し、外壁は漆喰塗仕上とする。内部は廊下の南に部屋を配し、東側は水回り、西側は座敷とし、奥行の浅い大床と平書院を構える。造作丁寧で庭に面して開放的な外観の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016573"},{"id":"00016577","register_sub_id":"101","register_pk":"574939","name":"梶間家住宅東蔵","kana":"かじまけじゅうたくひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字伊澤町375他","lat":35.00592583,"lng":134.53675,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0864","desc":"敷地南辺の中央部に建つ衣類や漆器などの収納蔵。二階建切妻造妻入桟瓦葺で北面に戸口を開け下屋を付す。外壁漆喰塗で軒まで塗込め、腰はモルタル塗で目地を切って石造風。小屋組は束立の和小屋。戸口楣の端部を反上げ、妻壁の鏝絵の屋号など凝ったつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016577"},{"id":"00016690","register_sub_id":"101","register_pk":"579174","name":"旧尼崎紡績本社事務所","kana":"きゅうあまがさきぼうせきほんしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県尼崎市東本町一丁目50","lat":34.712792,"lng":135.427936,"geo_status":"db","era":"明治33年／明治後期増築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造2階一部平屋建、瓦葺、建築面積358㎡","structure_material":"煉瓦造2階一部平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"28 - 0874","desc":"阪神大物駅から南東に位置する旧紡績会社の本社事務所。煉瓦造二階一部平屋建、寄棟造桟瓦葺で南面に玄関ポーチを付す。各階は中廊下を通し、二階北西角にマントルピースを備えた鉄板張天井の貴賓室が残る。尼崎の紡績業の隆盛を伝えるランドマーク的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016690"},{"id":"00010870","register_sub_id":"101","register_pk":"201705","name":"旧木村酒造場裏門","kana":"きゅうきむらしゅぞうじょううらもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市和田山町竹田字上町西側363","lat":35.297544,"lng":134.834838,"geo_status":"db","era":"明治後期／平成25改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0640","desc":"敷地西辺、舟蔵と酒造所の間に建ち、両棟よりも棟を高く上げ、象徴的な構えの裏門。木造二階建、切妻造桟瓦葺で、一階南半を、板戸を開く門口と通路して前後に庇を付ける。二階は杜氏や蔵人の宿泊や休憩所として使われた建物で、往時の酒造場の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010870"},{"id":"00010867","register_sub_id":"101","register_pk":"201702","name":"旧木村酒造場米蔵","kana":"きゅうきむらしゅぞうじょうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県朝来市和田山町竹田字上町西側363","lat":35.297233,"lng":134.83512,"geo_status":"db","era":"明治後期／平成25改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積96㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0637","desc":"店舗兼主屋の土間側と対向して建つ。土蔵造平屋建、切妻造妻入、置屋根式で桟瓦葺の玄米蔵と白米蔵を並べ、前面に一連の下屋を通す。外壁は漆喰塗で鉢巻を廻らし、腰は通り側を海鼠壁、敷地内側を人造石洗出し仕上げとする。旧竹田城下の街路景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010867"},{"id":"00010869","register_sub_id":"101","register_pk":"201704","name":"旧木村酒造場貯蔵所","kana":"きゅうきむらしゅぞうじょうちょぞうしょ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県朝来市和田山町竹田字上町西側363","lat":35.297447,"lng":134.834787,"geo_status":"db","era":"明治後期／平成25改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積116㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0639","desc":"敷地西辺の南寄りに建つ土蔵。桁行二一メートル梁間五・七メートル、切妻造桟瓦葺で、外壁漆喰塗で腰を竪板張とし、東面に格子窓を並べる。小屋はキングポストトラスを組む。酒の熟成に用いた建物で、舟蔵や裏門と一連で酒造施設の敷地構えを特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010869"},{"id":"00010866","register_sub_id":"101","register_pk":"201701","name":"旧木村酒造場店舗兼主屋","kana":"きゅうきむらしゅぞうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市和田山町竹田字上町西側363","lat":35.297452,"lng":134.835225,"geo_status":"db","era":"明治後期／平成25改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積309㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0636","desc":"竹田城跡東麓で通りに面して建つ。正面に下屋を設けて格子をたて、上部は大壁で格子窓を並べる。屋根は土間上に越屋根を載せ、両端にうだつを立上げる。床上部は二列構成で、正面右手に上座敷を張出す。軸部重厚かつ上質な大型町家で、町並み景観の核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010866"},{"id":"00010868","register_sub_id":"101","register_pk":"201703","name":"旧木村酒造場舟蔵","kana":"きゅうきむらしゅぞうじょうふなぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県朝来市和田山町竹田字上町西側363","lat":35.297647,"lng":134.834922,"geo_status":"db","era":"明治後期／平成25改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積173㎡","structure_material":"土蔵造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0638","desc":"敷地西辺の北半を占める大型土蔵。桁行二五メートル梁間六・九メートル、切妻造桟瓦葺。外壁漆喰塗で腰を竪板張とし、東面に格子窓を並べる。小屋は和小屋と登梁を併用する。かつて麹室を備え、絞りなどを行った。竹田城跡に臨む敷地背面の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010868"},{"id":"00010871","register_sub_id":"101","register_pk":"201706","name":"旧木村酒造場門及び塀","kana":"きゅうきむらしゅぞうじょうもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市和田山町竹田字上町西側363","lat":35.297549,"lng":134.835373,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 木造、瓦葺、間口1.4m 塀 木造、瓦葺、総延長9.7m","structure_material":"門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0641","desc":"店舗兼主屋の上座敷角から敷地隅にのびる塀と、途中に構える門。門は間口一・四メートルの腕木門、切妻造桟瓦葺で、欄間に吹寄の襷桟を入れる。塀も桟瓦葺で通り側を大壁中塗仕上げ、腰を簓子下見板張とし、上座敷と外観の調和を図る。良好な佇まいを醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010871"},{"id":"00011169","register_sub_id":"101","register_pk":"205276","name":"旧龍野醤油同業組合事務所","kana":"きゅうたつのしょうゆどうぎょうくみあいじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県たつの市龍野町上霞城126","lat":34.868022,"lng":134.546334,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、銅板葺、建築面積184㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0652","desc":"木造二階建で、外壁は煉瓦タイルと人造石張を組み合わせたセセッション風意匠の事務所建築。柱頭部の植物渦巻模様の装飾、モザイクタイルの床、各室毎に天井を変えるなど意匠を凝らす。内部には事務所、会議室の他、恒温室等の試験場機能も有していた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011169"},{"id":"00011170","register_sub_id":"101","register_pk":"205277","name":"旧龍野醤油同業組合醸造工場","kana":"きゅうたつのしょうゆどうぎょうくみあいじょうぞうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県たつの市龍野町上霞城126","lat":34.867919,"lng":134.546078,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積165㎡、煙突付","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0653","desc":"敷地形状に合わせた不整形平面を持つ。当初は外壁総板張であったが、現在は上部を漆喰仕上とする。小屋はトラス。内部は醸造場、仕込蔵、後補の下屋部（物置）からなる。前面側には煉瓦造煙突が付属する。醤油生産にかかる龍野の歴史を物語る建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011170"},{"id":"00013427","register_sub_id":"101","register_pk":"368512","name":"旧東洋リノリユーム本館事務所棟（東リインテリア歴史館）","kana":"きゅうとうようりのりゆーむほんかんじむしょとう（とうりいんてりあれきしかん）","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県伊丹市東有岡五丁目125","lat":34.77111111,"lng":135.42304167,"geo_status":"db","era":"大正9年／昭和56年移築、平成31年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、スレート葺、建築面積99㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"28 － 0743","desc":"伊丹駅南方の敷地中央に西面して建つ。渡辺節が設計し、会社設立と同時期に竣工した旧事務所棟。木造二階建、半切妻造で、妻面をハーフティンバーで飾る。外壁は下見板張で、窓枠を伸ばし縦線を強調する。小規模ながらも独立初期の渡辺作品を知る上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013427"},{"id":"00012439","register_sub_id":"101","register_pk":"531763","name":"旧難波酒造醸造蔵","kana":"きゅうなんばしゅぞうじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県神崎郡神河町中村砂山161","lat":35.07058889,"lng":134.7783,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺一部金属板葺、建築面積417㎡","structure_material":"木造平屋一部2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-696","desc":"主屋の背面に建つ。桁行三〇メートル梁間一〇メートル、切妻造の南北棟で、西面に下屋を設ける。小屋組は登梁形式である。内部は一室で、大径の梁をかけ渡し、一部二階を設ける。酒造業に欠かせない施設で、店舗兼主屋とともに近世の酒造施設の構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012439"},{"id":"00012438","register_sub_id":"101","register_pk":"531762","name":"旧難波酒造茶室","kana":"きゅうなんばしゅぞうちゃしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神崎郡神河町中村砂山161","lat":35.07059167,"lng":134.77791389,"geo_status":"db","era":"明治前期／大正期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"28-695","desc":"土蔵の北に建つ。南北棟の切妻造桟瓦葺で、西面に下屋を設ける。浴室として建てられたが、大正期に茶室に改修された。内部は三畳の茶室と水屋からなり、茶室は床の間と地袋付の棚を備える。杉の良材を用いた端正なつくりで、商家の暮らしぶりの一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012438"},{"id":"00012436","register_sub_id":"101","register_pk":"531760","name":"旧難波酒造店舗兼主屋","kana":"きゅうなんばしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県神崎郡神河町中村砂山161","lat":35.07048611,"lng":134.77795556,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積293㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-693","desc":"旧但馬街道の宿場町に西面して建つ。大規模な二階建入母屋造平入で、四周に下屋を廻す。南を土間、北を三列構成の床上部とし、上手の座敷二室には上質な座敷飾を備える。正面の出格子や虫籠窓など町家の意匠をよく残し、旧街道の歴史的景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012436"},{"id":"00012437","register_sub_id":"101","register_pk":"531761","name":"旧難波酒造土蔵","kana":"きゅうなんばしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神崎郡神河町中村砂山161","lat":35.07059167,"lng":134.77791389,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、金属板葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"28-694","desc":"主屋の北西に廊下で接続する。土蔵造二階建、東西棟の切妻造で、外壁は土壁、上部竪板張である。南面の戸口に観音開きの土戸、裏白戸、板戸、網戸を建込む堅牢な構えで、丁寧な左官仕事で仕上げる。貴重品を収蔵した、商家の暮らしに欠かせない土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012437"},{"id":"00013162","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店内蔵","kana":"くろだせいうえもんしょうてんうちくら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79808056,"lng":134.98251389,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0729","desc":"敷地の北西隅、離れの北に並ぶ土蔵造で、東面に板戸引分けの戸口を開き、銅板葺の庇を付す。外壁は漆喰塗で腰を竪板張とする。２階に鉄扉片開きの窓を付す。２階は板間で棹縁天井を張る。商品蔵で、現在は家財と文書を収める。屋敷の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013162"},{"id":"00013154","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店座敷棟","kana":"くろだせいうえもんしょうてんざしきとう","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79798611,"lng":134.9827,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0721","desc":"主屋南西に斜めに取付く座敷棟。屋根は切妻造桟瓦葺で、広い妻壁を漆喰で塗込める。南北に八畳を並べ、南を床、棚、書院付の座敷、北を次の間とする。南北に縁を付し、南縁から庭を望み、北縁から主屋に通う。北西に便所を置く。上質な商家の接客座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013154"},{"id":"00013159","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店西南隅蔵","kana":"くろだせいうえもんしょうてんせいなんすみくら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79784167,"lng":134.98278056,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0726","desc":"敷地の南西隅にあり、南蔵の西に接続する。土蔵造二階建の大規模な建物である。敷地形状に合わせた台形平面で、外壁は漆喰塗で、腰を海鼠壁とし、北面に桟瓦葺の庇を付す。２階窓に鉄格子を入れる。１階は土間で商品蔵兼加工場とし、２階は家財蔵とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013159"},{"id":"00013163","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店外塀","kana":"くろだせいうえもんしょうてんそとべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79811389,"lng":134.98258333,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造、瓦葺一部銅板葺、延長6.5m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0730","desc":"敷地北辺、店舗と内蔵の間を塞ぐ土塀で、長さ８・０メートル、高さ３・３メートルである。屋根は桟瓦葺で、半間毎に柱を立て、壁は上部を真壁黒漆喰塗、腰を竪板張とし、西から第３間に外開の板戸を設ける。内側には銅板葺の庇を設け内蔵に通じる通路とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013163"},{"id":"00013153","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店店舗兼主屋","kana":"くろだせいうえもんしょうてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79808611,"lng":134.98269722,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0720","desc":"街路に北面して建つ金物問屋の店舗兼主屋。本瓦葺の屋根は正面側を中途から一段下げ、下屋と共に軒を三段に見せる。下屋の屋根中央に大鋸の看板を据える。一階は東に土間、西は北に店ノ間と茶室、南に二列四室、二階は北に物置、南に八畳座敷など四室を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013153"},{"id":"00013157","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店東南隅蔵","kana":"くろだせいうえもんしょうてんとうなんすみくら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79793611,"lng":134.982925,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0724","desc":"敷地南東隅にあり、東蔵の南に接続する。切妻造で、東蔵と棟を西へずらし東蔵越しに北妻壁を見せる。北面に桟瓦葺の庇を付す。外壁は漆喰塗で腰を竪板張とする。内部は板間で商品蔵、家財蔵とし、小屋組は登り梁に束立で母屋を受ける。北妻窓に小庇を付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013157"},{"id":"00013160","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店西蔵","kana":"くろだせいうえもんしょうてんにしくら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79792222,"lng":134.982675,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0727","desc":"敷地西辺にあり、西南隅蔵の北に接続する。桁行１８・３メートルの長大な土蔵で、東面に桟瓦葺の庇を付す。一階は土間の四室を並べ、南端一室を吹放ち、北から二室の正面を開放し、二階は三室の板間とする。商品蔵、家財蔵で、敷地西辺を構成する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013160"},{"id":"00013161","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店離れ","kana":"くろだせいうえもんしょうてんはなれ","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79803333,"lng":134.98253611,"geo_status":"db","era":"大正後期／昭和２年頃増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階一部平屋建、瓦葺、建築面積41㎡、塀付","structure_material":"木造2階一部平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0728","desc":"敷地西辺北寄りに建ち、切妻造二階建の接客棟と南に平屋建の書斎が付く。１階は８畳で北面に床、棚を設け、２階は６畳で西面に床、棚、書院を設ける。いずれも南から東へ縁を廻らす。書斎は４畳で西面に床と本棚を設け、南妻に長円形の丸窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013161"},{"id":"00013156","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店東蔵","kana":"くろだせいうえもんしょうてんひがしくら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.798,"lng":134.98286667,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0723","desc":"味噌蔵南に連続して建つ、桁行１０・９メートルの土蔵造で、西面に桟瓦葺の庇を付す。外壁は漆喰塗で腰を竪板張とする。内部は板間で１、２階とも中央やや北寄りで二室に間仕切り、それぞれ大戸口と二階に鉄格子窓を付ける。商品蔵、家財蔵として使用した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013156"},{"id":"00013155","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店味噌蔵","kana":"くろだせいうえもんしょうてんみそくら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79805278,"lng":134.98281667,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積14㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0722","desc":"主屋の南面東端に取付く。土蔵造二階建で、外壁は漆喰塗で腰を竪板張とする。西面に鉄板葺の庇を付し、中央の太い腕木二段で桁を受ける。一階は一間半四方の土間の味噌蔵と一間の便所に分かれ、二階は一室の板間である。敷地東辺を構成する土蔵の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013155"},{"id":"00013158","register_sub_id":"101","register_pk":null,"name":"黒田清右衛門商店南蔵","kana":"くろだせいうえもんしょうてんみなみくら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町二丁目980他","lat":34.79788889,"lng":134.98286667,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0725","desc":"東南隅蔵の西に接続する。桁行９・０メートルの土蔵造二階建で、北面に桟瓦葺の庇を付す。外壁は漆喰塗で腰を竪板張とする。１階は二室に間仕切り、東から家財蔵、文庫蔵、薪炭蔵とし、２階は一室で家財蔵とする。敷地の南辺を構成する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013158"},{"id":"00014072","register_sub_id":"101","register_pk":"508332","name":"中門前屋主屋","kana":"なかもんぜんやおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字西新町10-1","lat":35.00575278,"lng":134.53711389,"geo_status":"db","era":"嘉永4年(1851)／令和元年改修","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"28 - 0777","desc":"城下町山崎の通りに南面する商家主屋。切妻造平入桟瓦葺、東に通り土間、西に二列六室を配し、背後に平屋の台所棟を突出する。正面は下屋を付し戸口両脇を出格子構え、二階は窓三箇所に平格子を入れる。間口が大きく軒裏まで漆喰塗で仕上げ重厚にみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014072"},{"id":"00004283","register_sub_id":"101","register_pk":"105273","name":"西尾家住宅水車・牛・鶏小屋","kana":"にしおけじゅうたくすいしゃ・うし・とりごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県篠山市大山上694","lat":35.09729636,"lng":135.13829519,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0185","desc":"旧山陰道を隔てた北向かいの敷地に建つ。桁行６間半，切妻造，桟瓦葺，平入，平屋建の建屋で，東側を水車小屋とし東端に水車を設置していた。西側の牛・鶏小屋は棟を高くつくり，南面に下屋を差し掛ける。屋敷の全体構成を知る上で欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004283"},{"id":"00004284","register_sub_id":"101","register_pk":"105274","name":"西尾家住宅水車・牛・鶏小屋門及び塀","kana":"にしおけじゅうたくすいしゃ・うし・とりごやもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県篠山市大山上694","lat":35.09721283,"lng":135.13827303,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.4m、塀延長13m","structure_material":"木造","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0186","desc":"水車・牛・鶏小屋の敷地の南辺に建つ。折曲がり約５０尺長の規模で，西側部は失われている。石積基礎，腰を縦板張とした真壁造，桟瓦葺の塀で，東寄りに棟を高くして門を設ける。向かいの前庭塀と同様のつくりで，旧山陰道の街道景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004284"},{"id":"00009812","register_sub_id":"101","register_pk":"195641","name":"ヒガシマル醤油元本社工場原料庫及び仕込蔵","kana":"ひがしまるしょうゆもとほんしゃこうじょうげんりょうこおよびしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県たつの市龍野町大手54-1他","lat":34.86663926,"lng":134.54594482,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺一部鉄板葺、建築面積678㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0570","desc":"南側敷地の北東隅に位置する。東に並ぶ土蔵造の原料庫の西に二階建の食塩溶解場を接続し、南に、醤油仕込みに係る仕込蔵、仕込室、作業場を接続する複合建築。水路に面する東面外壁は、上部漆喰塗で腰を竪板張とし、換気用の小窓を連ね、街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009812"},{"id":"00009813","register_sub_id":"101","register_pk":"195642","name":"ヒガシマル醤油元本社工場仕込蔵一","kana":"ひがしまるしょうゆもとほんしゃこうじょうしこみぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県たつの市龍野町大手54-1他","lat":34.86660476,"lng":134.54588295,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積264㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0571","desc":"南敷地の南東に位置し、切妻造の二棟の蔵を南北に並列させた外観になる。南棟は麹室として使用され、内壁を断熱層を持つ二重の煉瓦壁とし、屋根大棟には換気用の越屋根を付ける。北棟は麹室の前室として使用された。醤油製造のうち製麹過程の特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009813"},{"id":"00009816","register_sub_id":"101","register_pk":"195645","name":"ヒガシマル醤油元本社工場仕込蔵及び雑品庫","kana":"ひがしまるしょうゆもとほんしゃこうじょうしこみぐらおよびざっぴんこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県たつの市龍野町大手61他","lat":34.86664759,"lng":134.54557838,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積323㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0574","desc":"北側敷地の西端に位置し、南面して建つ。Ｌ字形平面を持ち、通りに面した東西棟を雑品庫、北奥にのびる南北棟を仕込蔵とする。いずれも土蔵造平屋建で、雑品庫は東端を入母屋造とし、腰高に黒色の竪板を張り、格子窓を並べる。醸造元の敷地景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009816"},{"id":"00009815","register_sub_id":"101","register_pk":"195644","name":"ヒガシマル醤油元本社工場仕込蔵三","kana":"ひがしまるしょうゆもとほんしゃこうじょうしこみぐらさん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県たつの市龍野町大手61他","lat":34.86667852,"lng":134.54570687,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺一部鉄板葺、建築面積202㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0573","desc":"北側敷地の事務所及び圧搾場の西に位置する仕込蔵で、内部には醸造用の仕込樽を並べる。土蔵造平屋建、本瓦葺で、南正面の中段に庇を付け、壁は漆喰塗で腰を簓子下見板張とし、格子窓を穿つ。町家風の外観をもつ仕込蔵で、隣り合う事務所と調和した景観を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009815"},{"id":"00009814","register_sub_id":"101","register_pk":"195643","name":"ヒガシマル醤油元本社工場仕込蔵二","kana":"ひがしまるしょうゆもとほんしゃこうじょうしこみぐらに","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県たつの市龍野町大手54-1他","lat":34.86653576,"lng":134.54564501,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、瓦葺、建築面積269㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0572","desc":"南側敷地の南西隅に位置し、南北棟の土蔵二棟を並立させて接続した形式になる。内部には直径二メートル前後の醤油の仕込樽が隙間なく配置される。登り梁と和小屋を併用した特徴的な小屋組で広い空間を確保する。雄大な本瓦葺の屋根が、醤油工場の景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009814"},{"id":"00009811","register_sub_id":"101","register_pk":"195640","name":"ヒガシマル醤油元本社工場事務所及び圧搾場","kana":"ひがしまるしょうゆもとほんしゃこうじょうじむしょおよびあっさくじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県たつの市龍野町大手61他","lat":34.86671897,"lng":134.5457854,"geo_status":"db","era":"事務所 江戸後期 圧搾場 明治中期","year":1751,"year_source":"db","year_min":1751,"year_max":1751,"year_label":null,"structure":"土蔵造平屋建、瓦葺一部鉄板葺、建築面積862㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"28 － 0569","desc":"通りの北側敷地に南面して建つ。切妻造本瓦葺の町家を基本とする事務所と、背面に増築された圧搾場よりなる。内部に圧搾機や生汁槽、煉瓦煙突など醤油製造に関連する施設を残す。外観は建ちの低いつし二階で、外壁は漆喰で軒先まで塗り込め、正面に虫籠窓を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009811"},{"id":"00003580","register_sub_id":"101","register_pk":"104570","name":"鳳鳴酒造釜場及び洗米場","kana":"ほうめいしゅぞうかまばおよびせんまいじょう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市呉服町46","lat":35.07638745,"lng":135.22037414,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積96㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0132","desc":"土蔵二の南側，敷地東寄りに建つ。土蔵造，平屋建，切妻造，桟瓦葺，建築面積９６㎡で，南西隅にやや張り出して小室を設け，検査室と物入とする。内部は土間敷とし，酒造のための空間として活用されている。造り酒屋の作業空間としての土蔵の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003580"},{"id":"00003581","register_sub_id":"101","register_pk":"104571","name":"鳳鳴酒造仕込蔵","kana":"ほうめいしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市呉服町73-2","lat":35.07628521,"lng":135.22041942,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積246㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0133","desc":"釜場及び洗米場の南側に建つ。東西に棟を通す，切妻造，桟瓦葺の土蔵造２階建で，壁面は上部を漆喰塗，腰部を縦板張とする。内部に仕込樽を並べるための桁行２０ｍにも及ぶ大規模な建築であり，造り酒屋の景観を伝える欠くことのできない建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003581"},{"id":"00003583","register_sub_id":"101","register_pk":"104573","name":"鳳鳴酒造事務室二","kana":"ほうめいしゅぞうじむしつに","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県篠山市呉服町73-7","lat":35.07613383,"lng":135.22028552,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0135","desc":"仕込蔵の南西方に建つ。南北棟の長方形平面をもつ木造平屋建，入母屋造，桟瓦葺の建物で，南面に玄関を開き，内部は一室の事務室とする。敷地南側道路からの入口近くに位置し，敷地中央から南寄りにかけての醸造所作業空間の核となる施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003583"},{"id":"00003582","register_sub_id":"101","register_pk":"104572","name":"鳳鳴酒造槽場及び麹室","kana":"ほうめいしゅぞうふなばおよびこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市呉服町73-3","lat":35.07615621,"lng":135.22050017,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積127㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"28 － 0134","desc":"仕込蔵の南側に接続して建つ。土蔵造平屋建で，屋根は桟瓦葺。南端部には，２重に壁面を立てた麹室を設けている。槽場は一室の土間大空間で，内部に柱を建てない構造である。酒造業に欠かせない大規模建築の好例であり，篠山の江戸期の姿を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003582"},{"id":"00015064","register_sub_id":"101","register_pk":"529342","name":"前野家住宅（本家門前屋）店舗兼主屋","kana":"まえのけじゅうたく（ほんけもんぜんや）てんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字西新町50-7他","lat":35.00559167,"lng":134.53700556,"geo_status":"db","era":"江戸末期／平成22年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積399㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"28 - 0818","desc":"山崎旧城下の酒蔵通りの角地に建つかつて酒造業を営んだ商家の主屋。つし二階建入母屋造平入桟瓦葺。外壁は軒まで漆喰で塗込める。内部は東を土間、西に居室を並べ、南西隅が床、違棚、書院を備えた座敷。長大な間口で出桁の持送を並べた賑やかな外観の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015064"},{"id":"00015065","register_sub_id":"101","register_pk":"529343","name":"前野家住宅（本家門前屋）土蔵","kana":"まえのけじゅうたく（ほんけもんぜんや）どぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字西新町50-7他","lat":35.00562222,"lng":134.53682778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"28 - 0819","desc":"主屋西隣に建ち、通りに面する道具蔵。二階建切妻造平入桟瓦葺で東面北寄りに戸口を設け、主屋に接続する。外壁は漆喰塗で腰は竪板張。各階板敷の一室で北に階段を設け、小屋はヘの字状で一材の登梁を用いる。主屋と一体で続き長大な間口の屋敷景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015065"},{"id":"00015066","register_sub_id":"101","register_pk":"529344","name":"前野家住宅（本家門前屋）西蔵","kana":"まえのけじゅうたく（ほんけもんぜんや）にしぐら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県宍粟市山崎町山崎字西新町50-11","lat":35.00535278,"lng":134.53666111,"geo_status":"db","era":"大正9年／昭和中期改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積310㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"28 - 0820","desc":"主屋南側に建つかつての仕込蔵。2階建半切妻造桟瓦葺の南北棟で南妻に戸口を開け、東面北寄りに木製スロープを付し二階に至る。一階は土間でかつては一室、二階は一室の板敷で、中央南寄りに荷揚口を開ける。梁間大きく長大な土蔵で酒造業の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015066"},{"id":"00010022","register_sub_id":"101","register_pk":"196169","name":"三寿ゞ刃物製作所店舗兼主屋","kana":"みすずはものせいさくしょてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町2-1217","lat":34.79862999,"lng":134.98504873,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡、渡廊下付","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0587","desc":"商店街の入口付近に南面して建つ町家で、切妻造桟瓦葺とし正面に下屋を設ける。つしは建ちが低く漆喰で塗込め格子窓と虫籠窓を付す。平面は右土間の奥を作業場とし、上手は手前から六畳、八畳を並べ八畳にトコと仏壇を置く。往時の通りの風情を残す町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010022"},{"id":"00010023","register_sub_id":"101","register_pk":"196170","name":"三寿ゞ刃物製作所離れ","kana":"みすずはものせいさくしょはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県三木市本町2-1217","lat":34.79873842,"lng":134.98506693,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0588","desc":"店舗兼主屋の背面に中庭を挟んで位置し、渡廊下にて接続する。木造二階建、切妻造桟瓦葺で、南半は上下階とも東を納屋、西を座敷とする。北半は土蔵で、一階は二室に分かれ、二階は一室とする。主屋とともに、明治前期の町家の宅地構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010023"},{"id":"00007100","register_sub_id":"101","register_pk":"108082","name":"うすくち龍野醤油資料館","kana":null,"category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県たつの市龍野町大手54-2他","lat":34.86625962,"lng":134.54573373,"geo_status":"db","era":"昭和7／昭和54改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積687㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0356","desc":"通りに北面する木造２階建。２階建の主体部と、両脇の平屋からなる。主体部は柱型で大きく２分し、１階にアーチを架け、２階は小柱により３分する。柱型をタイル貼とし、腰や頂部などを石貼とする。醸造蔵や町家が並ぶ城下町の景観を彩る遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007100"},{"id":"00006351","register_sub_id":"101","register_pk":"107334","name":"小田垣商店旧酒蔵","kana":null,"category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市立町19-5","lat":35.07239972,"lng":135.22360199,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積72㎡、井戸付","structure_material":"土蔵造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"28 － 0285","desc":"作業場の東方に位置する旧酒蔵で、作業場と一連の屋根を架ける。桁行６．８ｍ、梁間１１ｍ規模で、作業場側の西面は土蔵造の壁面を残す。内部は間中に独立柱を南北に２本建て、登梁を架ける。作業場等とともに造酒屋時代の中核施設を継承。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006351"},{"id":"00006350","register_sub_id":"101","register_pk":"107333","name":"小田垣商店作業場","kana":null,"category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県篠山市立町19-5他","lat":35.07239983,"lng":135.22349751,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋一部2階建、瓦葺、建築面積122㎡","structure_material":"木造平屋一部2階建","registered":"2007.10.02(平成19.10.02)","register_no":"28 － 0284","desc":"店舗の東方、店舗土間の背後に東西棟で建つ。桁行９．７ｍ、梁間８．８ｍ規模、切妻造、桟瓦葺の木造平屋建。たちの高い架構をつくり、西側の一部に２階を設ける。南面西端から南に突出部を付け、屋根南面に屋根窓をのせる。店舗から一連の空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006350"},{"id":"00005982","register_sub_id":"101","register_pk":"106967","name":"赤膚山元窯大型窯","kana":"あかはだやまもとがまおおがたがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市赤膚町1049他","lat":34.67366934,"lng":135.764191,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"煉瓦造、奥行18m、幅5.4m","structure_material":"煉瓦造","registered":"2007.07.31(平成19.07.31)","register_no":"29 － 0116","desc":"敷地北側の傾斜地を利用して南北方向に築かれる。２連の胴木間と８房の焼成室が連なり最上部に煙道を設ける連房式登窯。奥行１８ｍ，幅５．４ｍ，高さ６ｍ規模で，煉瓦造とし，表面を塗土で仕上げる。勾配は３寸，上部で緩勾配に変化。近世に遡る大規模な登窯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005982"},{"id":"00005983","register_sub_id":"101","register_pk":"106968","name":"赤膚山元窯中型窯","kana":"あかはだやまもとがまちゅうがたがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県奈良市赤膚町1049他","lat":34.67367494,"lng":135.76409706,"geo_status":"db","era":"昭和26頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"煉瓦造、奥行9.7m、幅3.3m","structure_material":"煉瓦造","registered":"2007.07.31(平成19.07.31)","register_no":"29 － 0117","desc":"大型窯とほぼ並列して築かれる。焚き口となる胴木間と５房の焼成室が連なる連房式登窯で，奥行９．７ｍ，幅３．３ｍ，高さ４．４ｍ規模。煉瓦造とし，表面は塗土で仕上げる。規模は異なるが，近世に築かれた大型窯と同様の構法を用いて築かれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005983"},{"id":"00005984","register_sub_id":"101","register_pk":"106969","name":"赤膚山元窯展示室及び旧作業場","kana":"あかはだやまもとがまてんじしつおよびきゅうさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市赤膚町1049他","lat":34.67351147,"lng":135.76421317,"geo_status":"db","era":"明治後期／昭和17増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積215㎡","structure_material":"木造平屋一部2階建","registered":"2007.07.31(平成19.07.31)","register_no":"29 － 0115","desc":"市西部の丘陵地に位置する。桁行１２間，梁間３間規模の切妻造，東西棟で，東南隅に茶室を突出し，南面及び西面には庇を架ける。真壁造とし，当初作業場として使われた西半部分には格子窓を設ける。居住空間と窯を結ぶ敷地の要となる建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005984"},{"id":"00002173","register_sub_id":"101","register_pk":"103163","name":"太田酒造主屋","kana":"おおたしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県生駒郡斑鳩町龍田3-3120他","lat":34.6076169,"lng":135.719559,"geo_status":"db","era":"文政12","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造2階建、瓦葺、建築面積203㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0058","desc":"龍田の西端近くに位置し，南に折れて国道に出会う街道に南面して建つ。本瓦葺，つし２階の町家で，土間の東に下ミセ，西に３室と５室を配し，カミテ５室は棟を落として桟瓦の錣葺とする。瓦銘から年代は明らかで，当地方における年代上の指標的町家になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002173"},{"id":"00002178","register_sub_id":"101","register_pk":"103168","name":"太田酒造西大蔵","kana":"おおたしゅぞうにしおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県生駒郡斑鳩町龍田3-3120他","lat":34.6080059,"lng":135.71928472,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積178㎡","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0063","desc":"敷地西辺に沿って石積基礎の上に長大な壁面を見せて建つ。梁行６間規模，南北棟，切妻造，本瓦葺の仕込蔵で，東面に蔵前を設けて平入とするが，南妻面の東端で南大蔵に接続する。敷地北面の長屋や南大蔵とともに醸造所ならではの特色ある景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002178"},{"id":"00002177","register_sub_id":"101","register_pk":"103167","name":"太田酒造南大蔵","kana":"おおたしゅぞうみなみおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県生駒郡斑鳩町龍田3-3120他","lat":34.60786242,"lng":135.71940607,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積109㎡","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0062","desc":"主屋の所在する店舗及び居住ブロックと醸造関連施設の所在する北西ブロックを繋ぐ位置に建つ。東西に長い，東西棟，切妻造，本瓦葺の醸造蔵で，北面東端で東長屋に，西端で西大蔵に接し，中庭に向いた北面中央に入口を設ける。醸造の核となる施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002177"},{"id":"00014521","register_sub_id":"101","register_pk":"513935","name":"北岡本店酒蔵西棟","kana":"きたおかほんてんさかぐらにしとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県吉野郡吉野町大字立野349","lat":34.39578333,"lng":135.85945833,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積277㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0352","desc":"北岡本店敷地を東西に分かつ千股川の東岸沿いに増築した戦前期の希少な鉄筋コンクリート造酒蔵。建物北東辺を東棟に接し、高低差により二階部分が東棟一階と接続する。主に貯酒を担い、柱と梁の架構がルール化され、東棟より改良された構造となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014521"},{"id":"00014520","register_sub_id":"101","register_pk":"513934","name":"北岡本店酒蔵東棟","kana":"きたおかほんてんさかぐらひがしとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県吉野郡吉野町大字立野349","lat":34.39591111,"lng":135.85975,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積629㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0351","desc":"吉野川の河岸段丘に敷地を構え、酒造業を営む北岡本店が類焼した木造酒蔵跡に建築した戦前期の希少な鉄筋コンクリート造酒蔵。主に貯酒を担い、敷地に合わせて十二角形をなす複雑な平面形状で架構も自由。桶を上げるペントハウスを設け屋上を作業場とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014520"},{"id":"00013298","register_sub_id":"101","register_pk":"366287","name":"旧長壽會細菌研究所工場","kana":"きゅうちょうじゅかいさいきんけんきゅうしょこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市芝辻町543-11","lat":34.68948333,"lng":135.83587222,"geo_status":"db","era":"昭和前期／昭和前期増築、平成21年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋一部2階建、瓦葺、建築面積331㎡、門柱付","structure_material":"木造平屋一部2階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0280","desc":"東大寺旧境内西部にある元乳酸菌製品の研究及び製造所。工場は切妻造の４棟をコの字形に連ね、外壁を一連で下見板張とする。内部はキングポストトラスの小屋組を現す工場の一角に、事務室や研究室などを設ける。近代の食品製造施設の一連の形態をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013298"},{"id":"00013299","register_sub_id":"101","register_pk":"366288","name":"旧長壽會細菌研究所製品庫","kana":"きゅうちょうじゅかいさいきんけんきゅうしょせいひんこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市芝辻町543-11","lat":34.689475,"lng":135.83562778,"geo_status":"db","era":"昭和前期／平成17年頃・同26年頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積66㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0281","desc":"工場の西方に建つ製品庫。切妻造桟瓦葺で、外壁は上部を漆喰塗、腰を竪板張とし、妻壁を工場や敷地内の主屋と同様の意匠とする。内部は１階を土間敷、２階を板敷とし、小屋をキングポストトラス組みとする。工場と共に当時の食品製造施設の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013299"},{"id":"00000466","register_sub_id":"101","register_pk":"101456","name":"古梅園乾蔵","kana":"こばいえんいぬいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県奈良市椿井町8-2他","lat":34.68078598,"lng":135.82651762,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建，瓦葺，建築面積33㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0018","desc":"敷地の西北隅に建つ平入の土蔵で，南北棟になり，東面に蔵前を構える。元内向きの蔵として建てられた。現在は，墨の木型を保管している。大壁造，漆喰仕上げで腰板貼りとし，北妻は軒蛇腹位置まで板貼りとして，歴史的な町並みに変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000466"},{"id":"00000477","register_sub_id":"101","register_pk":"101467","name":"古梅園内蔵北塀","kana":"こばいえんうちぐらきたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68083373,"lng":135.82711403,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造，瓦葺，延長14.3m","structure_material":"木造","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0029","desc":"敷地北側の路地に面して建つ大壁造の屋根付の高塀。離れ座敷から磨き作業所間を中内蔵を挟んで建つ。軒下は上部まで延びる腰板を貼り，屋根は塗込の軒蛇腹で支える。路地からは西内蔵の軒線と高塀の軒線が２段に望見され，町並みを飾り立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000477"},{"id":"00000473","register_sub_id":"101","register_pk":"101463","name":"古梅園釜屋兼井戸屋形","kana":"こばいえんかまやけんいどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68065609,"lng":135.82729458,"geo_status":"db","era":"昭和初","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積34㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0025","desc":"台所の西側に位置する真壁造，漆喰仕上げの簡素な造りになる切妻造の建物で，立ちは高く内部は土間とする。北側の通路部分に背の低い腰板を貼る。元の釜場で，西北隅に切石井桁組の井戸があるが，この部分のみ開放として利用の便を図っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000473"},{"id":"00000465","register_sub_id":"101","register_pk":"101455","name":"古梅園北灰替所（北乾燥倉）兼倉庫","kana":"こばいえんきたはいがえしょ（きたかんそうぐら）けんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７他","lat":34.68080577,"lng":135.82663467,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建，瓦葺，建築面積123㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0017","desc":"敷地北側の路地に沿って建つ細長い建物。大壁造，漆喰仕上げとなり，南側には土庇を張り出す。型入れ後の墨を自然乾燥させる施設として使用される。つし２階部分は南面は格子窓とするが，北面は円形の小窓として，換気に工夫が見られる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000465"},{"id":"00000474","register_sub_id":"101","register_pk":"101464","name":"古梅園更衣室兼物置","kana":"こばいえんこういしつけんものおき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68064682,"lng":135.82722831,"geo_status":"db","era":"昭和初","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建一部2階建，瓦葺，建築面積64㎡","structure_material":"木造平屋建一部2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0026","desc":"商品蔵の北側に建てられた木造一部２階建の建物である。２階屋を挟んで，２回ほど増築されて現在の構えとなった。元は住み込み従業員のための部屋があったが，現在は更衣室や物置として使用している。製墨従業員のための時代相応の施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000474"},{"id":"00000469","register_sub_id":"101","register_pk":"101459","name":"古梅園細工場","kana":"こばいえんさいくば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市椿井町8-1他","lat":34.680666,"lng":135.82665278,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積31㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0021","desc":"木造，平屋建になる製墨施設の一つで，規模の割に立ちは高い。膠と油煙を練り合わせたものを計量して型入れする作業所として造られ，南側に通路を置き，北側に細工部屋を設ける。外壁は真壁造で内法上を漆喰壁とし，注連縄を張って特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000469"},{"id":"00000471","register_sub_id":"101","register_pk":"101461","name":"古梅園仕上げ作業所","kana":"こばいえんしあげさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町６他","lat":34.68058531,"lng":135.8273879,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造平屋建，瓦葺，建築面積88㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0023","desc":"事務所の南端部の背後にあって，棟を直交させて建つ細長い東西棟建物。元の事務所で，現在は製品の仕上げ作業所として使用する。北側１間は通路で，南側に製品包装等の作業室や事務室を配する。屋敷地の南を限る建物としてもしられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000471"},{"id":"00000476","register_sub_id":"101","register_pk":"101466","name":"古梅園主屋北塀","kana":"こばいえんしゅおくきたべい","category":"産業2次","subcategory":"その他工作物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.6808358,"lng":135.82736217,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造，瓦葺，延長9.5m","structure_material":"木造","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0028","desc":"主屋の落ち棟と離れ座敷間に敷設された大壁造の高塀で，敷地の北端部を限る路地に接して建つ。漆喰仕上げの軒下間で立ち上げた板貼りとする軽快な意匠になり，落ち棟や離れ座敷の妻側とも一体的な造作になり，町並み景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000476"},{"id":"00000472","register_sub_id":"101","register_pk":"101462","name":"古梅園商品蔵","kana":"こばいえんしょうひんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７他","lat":34.68059534,"lng":135.8271617,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"土蔵造2階建一部平屋建，瓦葺，建築面積64㎡","structure_material":"土蔵造2階建一部平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0024","desc":"仕上げ作業所の西側にあり，渡り廊下を挟んで並び建つ土蔵造の一連の建物。東の東西棟がつし２階になり西の南北棟がこれに接続する形となるが隔壁はなく，内部は一体として使用される。外観の構えは他の土蔵と同じで腰板貼り，軒蛇腹付の標準作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000472"},{"id":"00000462","register_sub_id":"101","register_pk":"101452","name":"古梅園食堂・脱衣室・灰替所","kana":"こばいえんしょくどう・だついしつ・はいがえしょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68070646,"lng":135.82690702,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建，瓦葺，建築面積43㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0014","desc":"磨き作業所に接して建つつし２階付の建物。 南面の庇を吹き放しの通路とし，従業員用の食堂や脱衣室を配する。つし２階は，元は灰替所として利用したが現在は倉庫とする。 大壁造，腰板貼りのこの建物は，製墨の工程を知る上で貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000462"},{"id":"00000460","register_sub_id":"101","register_pk":"101450","name":"古梅園製墨説明所","kana":"こばいえんせいぼくせつめいしょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68071749,"lng":135.82704494,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積15㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0012","desc":"敷地のほぼ中央西側にある製墨諸施設への入口部分に位置する。 規模は小さいが立ちは高い切妻造，平入の平屋建の建物で，元は来客や商談用の施設であった。 現在は，見学等来訪者に製墨行程を説明する施設として使用され，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000460"},{"id":"00000470","register_sub_id":"101","register_pk":"101460","name":"古梅園台所","kana":"こばいえんだいどころ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68066094,"lng":135.8274194,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造平屋建，瓦葺，建築面積48㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0022","desc":"木造，平屋建で，主屋の南側に落ち棟形式で接続するが，主屋境は土壁となり機能は分離している。元は製墨職人の食事所であった。内部は南側が広敷を置き，北側は土間で作業用軒道が東西に貫通する。店舗や事務棟の表と内部を区画する役割を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000470"},{"id":"00000464","register_sub_id":"101","register_pk":"101454","name":"古梅園銅壺場","kana":"こばいえんどうこば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68073068,"lng":135.82674061,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積35㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0016","desc":"風呂場の西側に建つ梁間の長い大壁造の建物で，膠を溶かす釜屋がある。 内部は土間で，小屋組を見せる。 南端部は通路とし北側に煉瓦造の釜２基を据え付け，脇に煉瓦蔵の角煙突が附属する。漆喰仕上げとする西妻の大壁は，ひときわ目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000464"},{"id":"00000475","register_sub_id":"101","register_pk":"101465","name":"古梅園東北土塀","kana":"こばいえんとうほくどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68084001,"lng":135.82752287,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造，瓦葺，延長17.0m","structure_material":"木造","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0027","desc":"敷地の東北端に建つ屋根付の土塀で，高塀とし店舗と主屋を矩折れで繋ぐ。東面には瀟洒な出入りを設ける。柱は１間おきに立て腰に板壁を貼る丁寧な造りとなる。表通りに面し，商家の表構えや町並みに調和するように計画されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000475"},{"id":"00000467","register_sub_id":"101","register_pk":"101457","name":"古梅園西灰替倉（西乾燥倉）","kana":"こばいえんにしはいがえぐら（にしかんそうぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町8-2他","lat":34.68070461,"lng":135.82651694,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建，瓦葺，建築面積47㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0019","desc":"敷地西端に建つ大壁造，つし２階付の建物。型入れ後の墨を自然乾燥されるための施設で，東面に出入口の庇が付く。南妻側は高板塀が附属する。西側の路地面は，１階の窓枠を含む腰板貼りとし，漆喰壁のつし２階の小窓とともに変化に富む外観となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000467"},{"id":"00000468","register_sub_id":"101","register_pk":"101458","name":"古梅園灰置き場兼編み場","kana":"こばいえんはいおきばけんあみば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市椿井町8-2他","lat":34.68064462,"lng":135.82652452,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建，瓦葺，建築面積21㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0020","desc":"敷地西南端に建つ真壁造の建物。東面中央に出入り口を開けて２階には小窓を設ける。正面の外壁は軒下まで縦板貼としている。型入れ後の墨を自然乾燥させる時に用いる木灰を乾燥させ，また墨を稲藁で編み付ける作業を行う小規模な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000468"},{"id":"00000463","register_sub_id":"101","register_pk":"101453","name":"古梅園風呂場","kana":"こばいえんふろば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68071197,"lng":135.82682979,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積25㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0015","desc":"製墨従業員のための施設で，南半は通路で北側を浴室とする。浴室は，中央の南北通路を挟んで東方に洗いの浴槽が４基，西方に上がり湯の浴槽１基を配し，棟に気抜きの小屋根を設ける。浴槽内部の改装はあるが，浴槽の配置は古式を保つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000463"},{"id":"00000461","register_sub_id":"101","register_pk":"101451","name":"古梅園磨き作業所兼倉庫","kana":"こばいえんみがきさぎょうじょけんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68076714,"lng":135.82697322,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建，瓦葺，建築面積164㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0013","desc":"コの字型の大壁造，２階建の重厚な構えの建物。元は墨型等を納める倉庫であったが，現在は磨き作業所や車庫，倉庫等として使用する。南翼屋は，敷地の東方から続く作業用の軌道レールが貫通し，北翼屋は敷地境にあり路地への出入口が設けられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000461"},{"id":"00004023","register_sub_id":"101","register_pk":"105013","name":"堀井家住宅粉挽小屋","kana":"ほりいけじゅうたくこなびきごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県桜井市穴師1-1","lat":34.54224,"lng":135.853455,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"29 － 0086","desc":"主屋の南妻側に建つ木造平屋建で，屋根は切妻造，鉄板葺とする。街路側に面した東妻面に水路を引き込み，そこに設置した水車の動力によって，油絞り，精米のほか，三輪素麺の原材料などを製粉していた。簡素な建物であるが，当地域の生業の有様を伝える施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004023"},{"id":"00014510","register_sub_id":"101","register_pk":"513924","name":"瑞穂酢（大西家住宅）内蔵及び北築地塀","kana":"みずほす（おおにしけじゅうたく）うちぐらおよびきたついじべい","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52616667,"lng":135.81047778,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"内蔵 木造2階建、瓦葺、建築面積19㎡ 北築地塀 土塀、瓦葺、延長8.6m","structure_material":"内蔵 木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0341","desc":"主屋北西の北側通り沿いに建つ貴重品や什器類等を収納する土蔵で、蔵前を介して主屋と接続する。切妻造瓦葺の置き屋根で、軒と壁を共に漆喰塗込とし、腰は板張。醸造施設群や主屋建替に先駆けて建設された。東側の築地塀とともに屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014510"},{"id":"00014509","register_sub_id":"101","register_pk":"513923","name":"瑞穂酢（大西家住宅）主屋","kana":"みずほす（おおにしけじゅうたく）おもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.5261,"lng":135.81056667,"geo_status":"db","era":"大正前期／昭和38年・同43年・同57年・令和元年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積228㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0340","desc":"耳成山の北の集落で食酢醸造業を営む旧家の主屋。北側通り沿いの門屋の奥に建つ、切妻造平入桟瓦葺、三列六間取の農家型平面で北側に式台玄関を構え、東半土間の南側で広敷を張り出す。通し柱を多用する構法を取り入れ、良材を用い贅を尽くした大規模な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014509"},{"id":"00014512","register_sub_id":"101","register_pk":"513926","name":"瑞穂酢（大西家住宅）北蔵","kana":"みずほす（おおにしけじゅうたく）きたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52623333,"lng":135.81025833,"geo_status":"db","era":"明治中期／昭和後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0343","desc":"敷地北西部、通りに北面して建つ酢蔵で、当家の食酢製造の起点となった建物。二階建、切妻造妻入桟瓦葺、南及び東面に下屋を付属する。内部は大空間で直径二・五メートルの大きな杉樽を並べ酢を熟成する。当地の伝統産業を支える施設で地域を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014512"},{"id":"00014515","register_sub_id":"101","register_pk":"513929","name":"瑞穂酢（大西家住宅）旧麹室及び築地塀","kana":"みずほす（おおにしけじゅうたく）きゅうこうじむろおよびついじべい","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52589444,"lng":135.81038611,"geo_status":"db","era":"大正前期／昭和中期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"麹室 木造平屋建、瓦葺、建築面積28㎡ 築地塀 土塀、瓦葺、総延長17m","structure_material":"麹室 木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0346","desc":"南蔵南の亀甲形切石積に建つ東西棟の旧麹室と、鬼門の空き地を取り囲む築地塀。麹室は食酢醸造用の麹を管理する施設で、土蔵造平屋建、切妻造桟瓦葺で北・西面に下屋を付し、建物内に入れ子状の木製麹室を組む。敷地西側に並ぶ食酢製造施設群の一角を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014515"},{"id":"00014518","register_sub_id":"101","register_pk":"513932","name":"瑞穂酢（大西家住宅）旧仕込み場","kana":"みずほす（おおにしけじゅうたく）きゅうしこみじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52597222,"lng":135.81066389,"geo_status":"db","era":"大正前期／昭和中期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0349","desc":"酢醸造元の敷地東寄り、主屋南東に西面して建つ南北棟の旧仕込み場。切妻造桟瓦葺の平屋建で、北側の井戸に掛かる部分が凹んだ平面とする。外壁は漆喰塗、腰を焼杉竪板張とし、現在は倉庫として用いる。洗米等を行った食酢製造施設で、建物群の一角を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014518"},{"id":"00014517","register_sub_id":"101","register_pk":"513931","name":"瑞穂酢（大西家住宅）旧充填場","kana":"みずほす（おおにしけじゅうたく）きゅうじゅうてんじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52598333,"lng":135.81049722,"geo_status":"db","era":"大正前期／昭和中期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0348","desc":"酢醸造元の敷地中央、主屋の南に建つ南北棟の旧充填場で食酢製造の一工程を担う。切妻造桟瓦葺の平屋建で、北東部に詰所を張り出す。外壁は漆喰塗で腰を焼杉竪板張。現在は酒の仕込み蔵として用いる。敷地に建ち並ぶ食酢製造関連施設群の一角を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014517"},{"id":"00014511","register_sub_id":"101","register_pk":"513925","name":"瑞穂酢（大西家住宅）旧味噌蔵","kana":"みずほす（おおにしけじゅうたく）きゅうみそぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52615,"lng":135.81068889,"geo_status":"db","era":"大正前期／昭和後期・平成19年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0342","desc":"敷地北東隅に西面して建つ旧味噌蔵と伝える土蔵で、北側通り沿いに妻面をみせる。土蔵造平屋建、切妻造桟瓦葺で壁は軒まで漆喰塗込として腰を焼杉竪板張、西側に隣接する門屋の東端が接続する。内蔵、門屋とともに北側通りに面し屋敷構えの正面を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014511"},{"id":"00014516","register_sub_id":"101","register_pk":"513930","name":"瑞穂酢（大西家住宅）米蔵","kana":"みずほす（おおにしけじゅうたく）こめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52588889,"lng":135.81055278,"geo_status":"db","era":"大正前期／昭和中期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積179㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0347","desc":"主屋の南側、旧敷地境石積に建つ長大な米蔵。元は門扉の付いた長屋門で、中央の通路を残す。土蔵造二階建、切妻造桟瓦葺で北側に庇を付す。食酢材料の米等の保管庫であったが、現在は材料及び資材倉庫とする。敷地南側に並ぶ食酢製造施設群の一角を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014516"},{"id":"00014513","register_sub_id":"101","register_pk":"513927","name":"瑞穂酢（大西家住宅）中蔵","kana":"みずほす（おおにしけじゅうたく）なかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52613611,"lng":135.81037222,"geo_status":"db","era":"明治後期／昭和後期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0344","desc":"北蔵南東方に建つ南北棟の酢蔵。軒高の高い切妻造桟瓦葺で東に下屋を付し、外壁は軒まで漆喰塗込、腰を焼杉竪板張とする。かつてはもろみの圧搾場で、北西隅に北蔵、南は南蔵と接続し内部は一連の空間とする。敷地西側に並ぶ食酢製造施設群の一角を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014513"},{"id":"00014514","register_sub_id":"101","register_pk":"513928","name":"瑞穂酢（大西家住宅）南蔵","kana":"みずほす（おおにしけじゅうたく）みなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52600556,"lng":135.81036944,"geo_status":"db","era":"大正前期／昭和後期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋一部2階建、瓦葺、建築面積143㎡","structure_material":"木造平屋一部2階建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0345","desc":"中蔵の南に連なる南北棟の酢蔵。軒の高い切妻造桟瓦葺、東に下屋を設けて一体の空間とし、南に土蔵造材料庫を設け、東側下屋を戸前とする。酒槽を備え醪の圧搾をおこなう施設で中蔵と一連の内部空間とする。敷地西側に並ぶ食酢製造施設群の一角を占める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014514"},{"id":"00014519","register_sub_id":"101","register_pk":"513933","name":"瑞穂酢（大西家住宅）門屋及び中門","kana":"みずほす（おおにしけじゅうたく）もんやおよびちゅうもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県橿原市中町267-1他","lat":34.52618333,"lng":135.81061667,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"門屋 木造平屋建、瓦葺、建築面積29㎡ 中門 木造、瓦葺、間口3.9m","structure_material":"門屋 木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0350","desc":"敷地北側の通りに開く長屋門。中央に門扉を構え、西を出格子付四畳半居室、東を物置とし、真壁造腰板大和張で、ガラス戸を用いるなど近代的な意匠とする。中門は主屋の座敷庭を区画し、式台玄関への入口で、筬欄間を備え、扉や腰板の框に精緻な仕事をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014519"},{"id":"00010221","register_sub_id":"101","register_pk":"198054","name":"吉田蚊帳店舗","kana":"よしだかちょうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県奈良市芝新屋町1-1","lat":34.677132,"lng":135.830843,"geo_status":"db","era":"江戸末期／昭和中期・昭和47頃・平成10頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積97㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"29 － 0210","desc":"主屋の北に並び、切妻造桟瓦葺とする。漆喰大壁造の土蔵風外観で、正面一階は洗出し、北側面は竪板張とする。一階北半は床と間仕切を撤去し、南半はもと土間で、東寄りに床を張る。二階北東の六畳は裏庭側に縁を設ける。奈良町の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010221"},{"id":"00012231","register_sub_id":"101","register_pk":"353031","name":"伊勢屋北蔵","kana":"いせやきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県御坊市薗744","lat":33.885786,"lng":135.154822,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造及び木造2階一部平屋建、瓦葺、建築面積205㎡","structure_material":"土蔵造及び木造2階一部平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"30-229","desc":"御坊市街南西の小竹八幡神社東方、伊勢屋の主屋南東に位置する。桁行三間半、梁間二間半の生活用具庫と桁行五間半、梁間四間半の作業場が南北に接続する。作業場内部は、柱を減らして空間を確保する。酒蔵施設に欠かせない大規模土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012231"},{"id":"00012232","register_sub_id":"101","register_pk":"353032","name":"伊勢屋南蔵","kana":"いせやみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県御坊市薗744","lat":33.885445,"lng":135.154884,"geo_status":"db","era":"大正期／昭和前期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造及び木造2階一部平屋建、瓦葺、建築面積386㎡","structure_material":"土蔵造及び木造2階一部平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"30-230","desc":"敷地の南東隅に北蔵と連続して建つ。主体部は桁行一四間半、梁間六間で、桁行四間の増築部を接続して北蔵とつなぐ。二階は独立柱を桁行方向に牛梁でつなぎ、牛梁間に架けた梁から束を立てて小屋を組む。壮観な梁組が当地の酒造業の歴史を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012232"},{"id":"00015227","register_sub_id":"101","register_pk":"530651","name":"井澗家住宅線香水車小屋","kana":"いたにけじゅうたくせんこうすいしゃごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県西牟婁郡すさみ町周参見1046","lat":33.57790833,"lng":135.49324167,"geo_status":"db","era":"大正後期／昭和16年増築、同50年頃改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、鉄板葺、建築面積179㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0388","desc":"太間川・熊野古道大辺路沿いに位置する、線香材料の杉葉等を製粉する水車小屋。平屋建切妻造鉄板葺。中央に石積水路を通して大型水車を設置し、左右二室の作業場に横杵と縦杵を併用し、計一六挺の石臼を据える。紀伊半島の線香製造業を伝える貴重な水車小屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015227"},{"id":"00005655","register_sub_id":"101","register_pk":"106643","name":"高垣酒造仕込蔵","kana":"たかがきしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町小川1465","lat":34.0783485,"lng":135.2798429,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積351㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0097","desc":"主屋の北西方に東西棟で建つ。桁行１０間，梁間６間規模，切妻造，桟瓦葺の２階建酒蔵で，南面全面には３間幅の下屋を設ける。内部は２列４本の柱を建て，外部は腰高の目板羽目とする。北面には規則的に開口をとり，道路沿いに造り酒屋特有の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005655"},{"id":"00005656","register_sub_id":"101","register_pk":"106644","name":"高垣酒造貯蔵庫","kana":"たかがきしゅぞうちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県有田郡有田川町小川1465","lat":34.0783539,"lng":135.2802021,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積363㎡、釜場及び煙突付","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0098","desc":"仕込蔵の東に続いて建つ。桁行１１間，梁間５間，切妻造，桟瓦葺の２階建酒蔵で，南面西寄りには釜場を突出させ，東寄りは下屋を設けて壜場とする。内部は棟通りに柱を建て，地棟に登梁を交叉させる。北面の景観要素であるとともに，釜場煙突が目印となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005656"},{"id":"00013164","register_sub_id":"101","register_pk":"368393","name":"田島漆店旧工場玄関棟","kana":"たじまうるしてんきゅうこうじょうげんかんとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県海南市船尾167","lat":34.15979722,"lng":135.206075,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0267","desc":"漆器産地の黒江に隣接する船尾地区にあり、敷地西端南寄りに西面して建つ。木造平屋建で、正面外壁は腰をモルタル洗出し仕上、他を色モルタル仕上とし、内部はコンクリート土間の一室、小屋組は鉄骨トラス組とする。表玄関として旧漆工場の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013164"},{"id":"00013166","register_sub_id":"101","register_pk":"368395","name":"田島漆店旧工場商品蔵","kana":"たじまうるしてんきゅうこうじょうしょうひんくら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県海南市船尾167","lat":34.15974167,"lng":135.206075,"geo_status":"db","era":"大正11年／昭和28年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積50㎡","structure_material":"煉瓦造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0269","desc":"玄関棟の南、敷地南西隅に北面して建つ。煉瓦造平屋建、切妻造桟瓦葺で、内外の壁面はモルタル塗とする。外壁の四隅に柱形を付け、鉢巻を回すなどモダンな外観である。漆製品出荷前の保管庫として、玄関棟、主屋とともに街路の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013166"},{"id":"00013165","register_sub_id":"101","register_pk":"368394","name":"田島漆店旧工場食堂","kana":"たじまうるしてんきゅうこうじょうしょくどう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市船尾167","lat":34.1598,"lng":135.20617222,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、金属板葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0268","desc":"玄関棟に接続して東側に建つ。木造平屋建で、切妻造金属板葺の屋根の一部を採光のため切上げる。内部は北側を床上部、南側を詰場へ続く通路の土間部とする。床上部は西から食堂二室、台所、風呂を並べる。附属施設として漆工場の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013165"},{"id":"00013167","register_sub_id":"101","register_pk":"368396","name":"田島漆店旧工場新蔵","kana":"たじまうるしてんきゅうこうじょうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市船尾166","lat":34.16,"lng":135.206125,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積101㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0270","desc":"敷地の北西隅に西面して建ち、土蔵造二階建、切妻造桟瓦葺で、西面に下屋を付す。外壁は上部を漆喰塗、腰を竪板張とする。内部は一、二階とも一室で、小屋組はキングポストトラス組とする。一階は以前は生漆の保管庫で、旧漆工場の構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013167"},{"id":"00013168","register_sub_id":"101","register_pk":"368397","name":"田島漆店旧工場詰場","kana":"たじまうるしてんきゅうこうじょうつめば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市船尾170","lat":34.15979444,"lng":135.20637222,"geo_status":"db","era":"昭和2年／昭和33年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"煉瓦造平屋建、スレート葺、建築面積218㎡","structure_material":"煉瓦造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0271","desc":"敷地南東隅に食堂に接続して建ち、煉瓦造平屋建、切妻造である。内部は主室と前室からなり、前室西側の出入口は食堂の通路に続く。主室の小屋組は、山形鋼をリベット留した鉄骨トラス組とする。漆製造の基幹施設として漆工場の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013168"},{"id":"00005652","register_sub_id":"101","register_pk":"106640","name":"初桜酒造囲蔵","kana":"はつさくらしゅぞういぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町中飯降85","lat":34.30355889,"lng":135.53322442,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積288㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0094","desc":"仕込蔵の東に接して南北棟で建つ。桁行１６間，梁間４間半規模，切妻造，桟瓦葺の木造２階建で，梁間を１間半と３間に分ける位置に柱を建てる。外部は大壁で腰高の竪板張とする。東面の長大な酒蔵の景観は酒造りの盛んな時期の当地の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005652"},{"id":"00005651","register_sub_id":"101","register_pk":"106639","name":"初桜酒造仕込蔵","kana":"はつさくらしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町中飯降85","lat":34.30351359,"lng":135.53313962,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積376㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0093","desc":"主屋の北方に南北棟で建つ。桁行１６間，梁間６間規模，北を入母屋造，南を切妻造とした桟瓦葺で，内部は中央部に床を張り２階建とする。外部は大壁で腰を竪板張とする。敷地内を東西に抜ける町道に入母屋造，漆喰塗，連子窓付きの特徴ある北妻面をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005651"},{"id":"00010231","register_sub_id":"101","register_pk":"198064","name":"堀河屋野村作業蔵","kana":"ほりかわやのむらさぎょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗字新町743","lat":33.885613,"lng":135.154995,"geo_status":"db","era":"江戸後期／昭和前期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造一部コンクリート造平屋建、瓦葺、建築面積127㎡、煙突付","structure_material":"木造一部コンクリート造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0198","desc":"第二仕込蔵の南側に、第一仕込蔵と対面して建つ。もろみを絞り出して生醤油の加熱や瓶詰等を行う作業場で、桁行六間、梁間四間の本屋北側に梁間一間の庇、東には煉瓦造の煙突を付け、南西にはコンクリート造のムロを張出す。醤油醸造所の景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010231"},{"id":"00010229","register_sub_id":"101","register_pk":"198062","name":"堀河屋野村第一仕込蔵","kana":"ほりかわやのむらだいいちしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗字新町743他","lat":33.88562,"lng":135.155111,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0196","desc":"土蔵の南隣に南北棟で建ち、西面に戸口を開く。桁行五間半、梁間四間で、半間毎に柱を立て、土壁を塗る。棟通中央に棟柱を立て、両妻の天秤梁から地棟木を渡して登梁を架ける。内壁は中塗仕上とし、木部にも麹菌が付着する。醤油のもろみを熟成させるための蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010229"},{"id":"00010230","register_sub_id":"101","register_pk":"198063","name":"堀河屋野村第二仕込蔵","kana":"ほりかわやのむらだいにしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県御坊市薗字新町743","lat":33.885731,"lng":135.154939,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0197","desc":"主屋背面側西寄りに南北棟で建ち、東面に戸口を開く。桁行五間、梁間四間で、南西側の一角にコンクリート造のムロを張出す。小屋組はキングポストトラスで方杖を併用する。壁は内部を荒壁仕上、外部を竪板張とする。内部に多数の木桶を置き、仕込みに用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010230"},{"id":"00010227","register_sub_id":"101","register_pk":"198060","name":"堀河屋野村店舗兼主屋","kana":"ほりかわやのむらてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗字新町743他","lat":33.88597,"lng":135.15492,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0194","desc":"新町通りに北面して建つ。木造平屋建で、本瓦を葺く。軒高が低く、座敷部分を出格子とし、木部にベンガラを塗る。床上部は二列六室構成でアガリトと呼ばれる板床を土間に張出す、江戸末期における当地の町家の典型的平面になる。上質で地方的特色を示す近世町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010227"},{"id":"00010228","register_sub_id":"101","register_pk":"198061","name":"堀河屋野村土蔵","kana":"ほりかわやのむらどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県御坊市薗字新町743他","lat":33.885745,"lng":135.15509,"geo_status":"db","era":"江戸末期／昭和28頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"30 － 0195","desc":"敷地ほぼ中央に東西棟で、西面して建つ。桁行四間、梁間三間、土蔵造二階建、切妻造本瓦葺で、西妻を戸口として、重厚に塗込めた庇を付ける。蔵の中央には七寸角の柱を立てて牛梁を受ける。醸造関係の道具や家財道具を収納するために建てられた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010228"},{"id":"00012576","register_sub_id":"101","register_pk":"367871","name":"小川文齋家住宅主屋","kana":"おがわぶんさいけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市東山区五条橋東六丁目502他","lat":34.992432,"lng":135.77771,"geo_status":"geocoded","era":"江戸末期／大正8年頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"26 － 0576","desc":"五条通に南面する表屋造の町家。表屋は土間主体の空間で、正面を出桁造とし、二階西側に出格子、東側に太い額縁の格子窓を設ける。裏の居住棟は東に土間、西に2列2室を配し、西列奥の座敷に床と違棚を備える。製陶業で発展した五条坂の風情を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012576"},{"id":"00012577","register_sub_id":"101","register_pk":"367872","name":"小川文齋家住宅土蔵","kana":"おがわぶんさいけじゅうたくどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市東山区五条橋東六丁目502他","lat":34.992432,"lng":135.77771,"geo_status":"geocoded","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積13㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"26 － 0577","desc":"主屋北西隅に接続し、東面して建つ。土蔵造二階建、南北棟の置屋根式の切妻造、外壁は漆喰塗の基部洗出し仕上で、中段に水切一段を廻す。鉢巻はなく、二階南妻に庇付の小窓を開く。二間四方と小ぶりながら丁寧な仕上で、町家の裏庭空間に趣を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012577"},{"id":"00012578","register_sub_id":"101","register_pk":"367873","name":"小川文齋家住宅登り窯","kana":"おがわぶんさいけじゅうたくのぼりがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区五条橋東六丁目502他","lat":34.992432,"lng":135.77771,"geo_status":"geocoded","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"煉瓦造、奥行11m、幅5m、煙突付","structure_material":"煉瓦造","registered":"2018.11.02(平成30.11.02)","register_no":"26 － 0578","desc":"敷地北辺の東上りの地形を生かして東西方向に築いた六室の連房式登り窯で、西面に焚口を開く。幅5メートル全長11メートルの規模で、耐火煉瓦を主材とし、東北隅に煉瓦煙突を立てる。市街化著しい五条坂にあって製陶業の繁栄を偲ばせる貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012578"},{"id":"00001718","register_sub_id":"101","register_pk":"102708","name":"河井寬次郎記念館（旧河井寬次郎邸）登り窯","kana":"かわいかんじろうきねんかん（きゅうかわいかんじろうてい）のぼりがま","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区馬町通大和大路東入鐘鋳町569他","lat":34.99338824,"lng":135.77472059,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"煉瓦造、奥行15m、幅4.8m","structure_material":"煉瓦造","registered":"2000.04.28(平成12.04.28)","register_no":"26 － 0064","desc":"屋敷地東端に位置するレンガ造の登り窯で、木造平屋建の上屋が架かる。築造沿革は明らかでないが、大正９年に清水六兵衛から譲り受けた後、９室であった窯を８室に改めている。五条坂地区の京焼・清水焼の登り窯遺構として現存する数少ないもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001718"},{"id":"00001434","register_sub_id":"101","register_pk":"102424","name":"神崎コンクリート株式会社旧煉瓦窯（旧京都竹村丹後製窯所煉瓦窯）","kana":"かんざきこんくりーとかぶしきがいしゃきゅうれんががま（きゅうきょうとたけむらたんごせいようしょれんががま）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府舞鶴市字西神崎918","lat":35.514393,"lng":135.292511,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"上屋付煉瓦造、長径45m、短径9m、大煙突1基及び小煙突11基附属","structure_material":"上屋付煉瓦造","registered":"1999.11.18(平成11.11.18)","register_no":"26 － 0057","desc":"明治３０年建設の登り窯を，大正末期にホフマン式輪窯に改造したもの。長径45ｍ，短径９ｍの楕円形輪釜で，内法高さ1.8ｍ，幅2.8ｍのトンネルヴォールトがドーナツ状に巡り，高さ２４ｍの大煙突１基と各焼成室ごとに設けた小煙突11基を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001434"},{"id":"00005625","register_sub_id":"101","register_pk":"106613","name":"旧上田恒次家住宅登窯","kana":"きゅううえだつねじけじゅうたくのぼりがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岩倉木野町170","lat":35.07208056,"lng":135.77788686,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"煉瓦造、面積14㎡、上屋付","structure_material":"煉瓦造","registered":"2006.08.03(平成18.08.03)","register_no":"26 － 0212","desc":"主屋南東方に位置する。登窯は面積１４㎡，煉瓦造で，焼成室を南北に４室並べ，南端に半円形の炊口を設ける。上屋は柱６本を２列に並べて南北棟，桟瓦葺の切妻屋根をかけ，南側に下屋をおろす。主屋と共に，昭和初期の陶芸家居宅の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005625"},{"id":"00002416","register_sub_id":"101","register_pk":"103406","name":"旧並河靖之邸窯場","kana":"きゅうなみかわやすゆきていかまば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区三条通北裏白川筋東入堀池町384、385、388","lat":35.00987551,"lng":135.78153729,"geo_status":"db","era":"明治35頃／明治44改造","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"26 － 0093","desc":"工房の南東に突出して設けられる。入母屋造，桟瓦葺の屋根は緩く起り，腰高に焼板を張るなど瀟洒な外観をもつ。内装は洋室に改装されているが，板戸建の横長窓，漆喰塗込の天井など，窯場当時の仕様が残る。当家の歴史を知る上で欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002416"},{"id":"00002415","register_sub_id":"101","register_pk":"103405","name":"旧並河靖之邸工房","kana":"きゅうなみかわやすゆきていこうぼう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区三条通北裏白川筋東入堀池町384、385、388","lat":35.009941,"lng":135.781509,"geo_status":"db","era":"明治35頃／明治44改造","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"26 － 0092","desc":"主屋の東に建つ入母屋造，桟瓦葺の平屋。もと工房として建てられたが，その後住居として改装された。４畳半の座敷と洋風の部屋の２間からなり，南東に窯場が接続する。多くの棚や物入を造り，天井などに変化を付けるなど，変化に富んだ意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002415"},{"id":"00015028","register_sub_id":"101","register_pk":"529306","name":"京都大学東南アジア地域研究研究所図書室本館（旧京都織物株式会社本社事務所）","kana":"きょうとだいがくとうなんあじあちいきけんきゅうけんきゅうじょとしょしつほんかん（きゅうきょうとおりものかぶしきかいしゃほんしゃじむしょ）","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区吉田下阿達町46","lat":35.02108611,"lng":135.77267778,"geo_status":"db","era":"明治22年／昭和46年・平成21年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積410㎡","structure_material":"煉瓦造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"26 - 0670","desc":"京都大学吉田キャンパス内に位置する旧織物工場の事務所。並列する煉瓦造二階建切妻造の東西棟２棟を南北棟で繋ぎ、全体にＨ形平面。南北棟は中央に半円アーチの通路と窓を開けたゲート的な建物で、内部階段などに往事を留める。貴重な煉瓦造の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015028"},{"id":"00002052","register_sub_id":"101","register_pk":"103042","name":"キンシ正宗堀野記念館（旧堀野家本宅）天明蔵","kana":"きんしまさむねほりのきねんかん（きゅうほりのけほんたく）てんめいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市中京区堺町通二条上る亀屋町172","lat":35.01412207,"lng":135.76281872,"geo_status":"db","era":"元治元以前","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"26 － 0075","desc":"もと酒蔵で，主屋の西北方奥，敷地の西辺に沿って建つ。桁行５間半，梁行４間規模，南北棟，切妻造，本瓦葺，平入のやや大型の２階建土蔵で，中央に棟持柱を置いて棟を支持する構造に古式が認められる。北側はレストランに改修され利活用が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002052"},{"id":"00009188","register_sub_id":"101","register_pk":"164741","name":"日本写真印刷本館","kana":"にほんしゃしんいんさつほんかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区壬生花井町3番地","lat":35.00398574,"lng":135.74058247,"geo_status":"db","era":"明治39年／昭和50年頃・平成20年改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積346㎡","structure_material":"煉瓦造2階建","registered":"2012.02.23(平成24.02.23)","register_no":"26 - 0395","desc":"煉瓦造2階建、建築面積346平方メートル、屋根飾り付きのマンサード屋根、外壁は石造風にモルタルで仕上げ、アーチ窓を並べる。正面中央にポーチを設け、コリント式オーダーの円柱を用いる。明治期における優れた意匠を持つ煉瓦造の事務所建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009188"},{"id":"00016516","register_sub_id":"101","register_pk":"574878","name":"藤井絞店舗兼主屋","kana":"ふじいしぼりてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区新町通六角下る六角町365","lat":35.01003333,"lng":135.75140556,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0711","desc":"新町通りに東面して建つ絞染製造卸の店舗兼主屋。２階建切妻造平入桟瓦葺で表屋造の形式。１階は出格子構えで腰は御影石貼、北端に二階まで袖壁を立上げる。土間の絞染乾燥室など生業を示し、二階の主座敷は端正なつくり。豪壮な袖壁が目を惹く近代の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016516"},{"id":"00016517","register_sub_id":"101","register_pk":"574879","name":"藤井絞土蔵","kana":"ふじいしぼりどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区新町通六角下る六角町365","lat":35.01003333,"lng":135.75140556,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"26 - 0712","desc":"主屋の西に廊下で接続する家財蔵。土蔵造2階建切妻造桟瓦葺で外壁漆喰塗仕上、軒に鉢巻を廻らし、東面窓に銅板葺庇を付す。内部は各階板敷の一室で、小屋組は太い地棟に登梁を架ける。戸口は外に鉄製両開戸、内に鉄製引戸を建てるなど厳重なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016517"},{"id":"00009788","register_sub_id":"101","register_pk":"195617","name":"松本酒造吟醸酒蔵","kana":"まつもとしゅぞうぎんじょうしゅぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市伏見区横大路三栖大黒町2他","lat":34.93361842,"lng":135.75434712,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0433","desc":"大黒蔵の北側で、酒蔵ホールに並び建つ。木造平屋建、桁行一一メートル梁間七・三メートル、切妻造桟瓦葺で、東妻を戸口とする。小屋は洋小屋を組む。外壁は竪板張及び下見板張で、妻壁は斜めに板を張り、中央に亀甲形の換気口を設けてアクセントとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009788"},{"id":"00009787","register_sub_id":"101","register_pk":"195616","name":"松本酒造酒蔵ホール","kana":"まつもとしゅぞうさかぐらほーる","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市伏見区横大路三栖大黒町2他","lat":34.93362793,"lng":135.75418056,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積141㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0432","desc":"大黒蔵北側の河畔に東西棟で建つ。土蔵造二階建、桁行一九・二メートル梁間七・三メートル、切妻造桟瓦葺で、南面東寄りを戸口とし、小屋は洋小屋を組む。外壁は軒下まで黒色の竪板張とし、窓を等間隔に並べて大黒蔵と外観を揃え、良質な河岸景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009787"},{"id":"00007236","register_sub_id":"101","register_pk":"108218","name":"松本酒造正門","kana":"まつもとしゅぞうせいもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市伏見区恵美酒町938他","lat":34.93334964,"lng":135.75511738,"geo_status":"db","era":"江戸前期／明治期移築・昭和29頃移築改修","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0321","desc":"通りに東面して建つ四脚門。切妻造本瓦葺で、礎盤上に粽付柱を建て、三斗組とし、中備に蟇股を入れる。妻は虹梁大瓶束で、軒は一軒疎垂木。建仁寺塔頭正傳院にあったと伝え、改造があるものの木鼻ほか細部意匠は近世初頭に遡り、植物彫刻も秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007236"},{"id":"00009786","register_sub_id":"101","register_pk":"195615","name":"松本酒造大黒蔵","kana":"まつもとしゅぞうだいこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市伏見区横大路三栖大黒町5-2他","lat":34.93336738,"lng":135.75428942,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積1323㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0431","desc":"敷地西側の河畔に南北棟で建ち、土蔵造二階建、切妻造桟瓦葺である。桁行四〇メートルの土蔵三棟を東西に並べた構成で、小屋は和小屋と洋小屋を併用する。外壁は軒下まで竪板張とし、庇付窓を等間隔に並べる。量感ある大型土蔵が伏見の河岸景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009786"},{"id":"00007235","register_sub_id":"101","register_pk":"108217","name":"松本酒造万暁院","kana":"まつもとしゅぞうまんぎょういん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市伏見区恵美酒町938他","lat":34.933224,"lng":135.754929,"geo_status":"db","era":"昭和29頃","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積255㎡、塀付","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"26 － 0320","desc":"庭園の北側に、南に客間部と東に居間部の２棟を雁行型に並べ、西北に茶室や玄関を配して繋ぐ。いずれも入母屋造本瓦葺で庇をまわす。玄関は穏やかな唐破風屋根で、銅板葺とする。客座敷には座敷飾りを備え、入側は瓦四半敷。良質な近代和風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007235"},{"id":"00009791","register_sub_id":"101","register_pk":"195620","name":"松本酒造煉瓦煙突","kana":"まつもとしゅぞうれんがえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市伏見区横大路三栖大黒町7-1","lat":34.93317733,"lng":135.75413549,"geo_status":"db","era":"明治後期／平成12改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、高さ18m","structure_material":"煉瓦造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0436","desc":"大黒蔵と煉瓦煙突の間に建つ。煉瓦造、イギリス積で、基部の平面は直径二・二メートルの八角形とし、高さは一八メートルを測る。腰部に装飾的な帯状部を設け、現在は全長をアングル材等で補強している。大黒蔵や煉瓦倉庫とともに、河岸の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009791"},{"id":"00009789","register_sub_id":"101","register_pk":"195618","name":"松本酒造煉瓦倉庫","kana":"まつもとしゅぞうれんがそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市伏見区横大路三栖大黒町7-1","lat":34.93311546,"lng":135.75424257,"geo_status":"db","era":"明治後期／平成23改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造平屋建、瓦葺、建築面積117㎡","structure_material":"煉瓦造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0434","desc":"大黒蔵の南側に東西棟で建ち、煉瓦造平屋建、切妻造桟瓦葺である。両妻面はパラペットを積上げ、丸窓を穿つ。戸口や周囲の縦長窓は欠円アーチとし、キーストーンをモルタル塗で表す。内部は一室で洋小屋を組む。煉瓦煙突や大黒蔵とともに往時の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009789"},{"id":"00000891","register_sub_id":"101","register_pk":"101881","name":"小川酒造旧仕込蔵","kana":"おがわしゅぞうきゅうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市河原町1969","lat":35.42930185,"lng":133.81203512,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造２階建，瓦葺，建築面積237㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"31 － 0031","desc":"敷地背面の鉢屋川に面して建つ。現在は貯蔵庫となっており，鉢屋川側に出入口を設けている。キングポストトラスの洋小屋を持ち，長大な壁面と赤瓦が印象的な倉庫建築で，鉢屋川の水運連絡の様子を今日に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000891"},{"id":"00000894","register_sub_id":"101","register_pk":"101884","name":"小川酒造三階蔵","kana":"おがわしゅぞうさんかいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市河原町1969","lat":35.4294604,"lng":133.81198726,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造３階建，瓦葺，建築面積62㎡","structure_material":"土蔵造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"31 － 0034","desc":"二階蔵の北側，主屋との間に二階蔵に平行して建つ。現状では１階を漬物蔵，２，３階を布団置き場に使う。２階蔵を床上げして３階蔵とした形で，これは水害対策のためと考えられる。地域の気候風土にあわせた建物技術を物語る建物として貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000894"},{"id":"00000889","register_sub_id":"101","register_pk":"101879","name":"小川酒造主屋","kana":"おがわしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市河原町1969","lat":35.42969672,"lng":133.8119005,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造２階建，瓦葺，建築面積360㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"31 － 0029","desc":"河原町通りに面して建つ。南北に建物を貫通する通り土間の西側に２列６間取りの店舗と居室，東側に応接間と台所を配する。応接間部分はコリント式のオーダーを配するなど洋風の意匠になる。和風に洋風の接客空間を並立させた大正期建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000889"},{"id":"00000895","register_sub_id":"101","register_pk":"101885","name":"小川酒造道具蔵","kana":"おがわしゅぞうどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市河原町1969","lat":35.42940057,"lng":133.81185264,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造２階建，瓦葺，建築面積75㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"31 － 0035","desc":"敷地のほぼ中央に建つ。２階蔵，３階蔵が平入であるのに対して，配置の関係から妻入の平面を持つのが特徴。屋根は寄棟である。入口は数段の階段を上がる形となっているのは，３階蔵等と同じく水害対策のためと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000895"},{"id":"00000893","register_sub_id":"101","register_pk":"101883","name":"小川酒造二階蔵","kana":"おがわしゅぞうにかいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県倉吉市河原町1969","lat":35.42939459,"lng":133.81204409,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造２階建，瓦葺，建築面積52㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"31 － 0033","desc":"ビン詰場に面して建つ。土蔵造二階建で，二重梁の和小屋を持つ。東面には下屋を設け蔵前とし，床面を若干上げ，基部を石貼り風に見せている。酒造の機能上欠くことのできない施設で，屋敷構えのの主要な構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000893"},{"id":"00000890","register_sub_id":"101","register_pk":"101880","name":"小川酒造ビン詰場","kana":"おがわしゅぞうびんづめば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市河原町1969","lat":35.42951125,"lng":133.81211888,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積218㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"31 － 0030","desc":"主屋の背面側，トオリニワを抜けた位置に建つ。木造平屋の酒蔵で二重梁の和小屋の構造になる。西側作業スペースに面して下屋を架けている。同時期に建てられた農業倉庫との相関も伺える倉庫建築の標準作である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000890"},{"id":"00000892","register_sub_id":"101","register_pk":"101882","name":"小川酒造槽場","kana":"おがわしゅぞうふなば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市河原町1969","lat":35.42923903,"lng":133.81185563,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造２階建，瓦葺，建築面積77㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"31 － 0032","desc":"鉢屋川沿いに旧仕込蔵と連続して建つ。三重梁の和小屋には滑車が設けられている。かつては鉢屋川の水力を利用するための水車が設けられていたが，そのための水路，煉瓦積みの壁体が残る。水力利用の様子を今日に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000892"},{"id":"00002308","register_sub_id":"101","register_pk":"103298","name":"旧高田酒造醸造蔵一","kana":"きゅうたかだしゅぞうじょうぞうぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市新町2-2381-1","lat":35.43233865,"lng":133.82251,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積110㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"31 － 0051","desc":"主屋などの建つ宅地の背後，玉川の北の敷地に建つ。現在所有者が異なるが近年まで高田酒造の醸造用の蔵であった。平屋，土蔵造，屋根は石州瓦葺，壁は中塗仕上げで，腰部は焼板張とする。玉川沿いの歴史的景観を形成する重要な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002308"},{"id":"00002309","register_sub_id":"101","register_pk":"103299","name":"旧高田酒造醸造蔵二","kana":"きゅうたかだしゅぞうじょうぞうぐらに","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県倉吉市新町2-2381-1","lat":35.43230794,"lng":133.82276877,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積57㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"31 － 0052","desc":"醸造蔵一の東に続き，玉川沿いの小道に面して建つ。梁間（２間半）は醸造蔵一と同一だが桁行は約半分（６間）で，両蔵の境は大きな開口部を設け，一連に使えるようになっている。外壁を真壁とし半間毎に柱を見せ，高窓を配し，変化に富んだ外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002309"},{"id":"00004401","register_sub_id":"101","register_pk":"105391","name":"東門脇家住宅旧酒蔵","kana":"ひがしかどわきけきゅうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.48399599,"lng":133.46603572,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"31 － 0081","desc":"明治期より営まれた酒造業の施設で，敷地奥の北方にある。桁行４間梁間３間半，土蔵造２階建，切妻造，桟瓦葺で，南面には幅広の下屋庇を設け，１階に戸口，２階に窓を設ける。外壁は漆喰塗で，１階部分は板で覆う。往時の生業の一端を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004401"},{"id":"00004402","register_sub_id":"101","register_pk":"105392","name":"東門脇家住宅旧麹室","kana":"ひがしかどわきけじゅうたくきゅうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.48402758,"lng":133.46615289,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"31 － 0082","desc":"明治期より営まれた酒造業の施設で，敷地奥の北方にある。桁行４間半梁間３間，平屋建，切妻造で，南と東に下屋庇を設け，屋根は桟瓦葺で，南面には幅広の下屋庇を設ける。下は板壁と板戸，上は漆喰壁とする。簡素だが，往時の生業の一端を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004402"},{"id":"00008350","register_sub_id":"101","register_pk":"133992","name":"華泉酒造場旧衣装蔵","kana":"かせんしゅぞうじょうきゅういしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ221","lat":34.46949925,"lng":131.77519741,"geo_status":"db","era":"江戸末期／平成8年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0142","desc":"主屋の南側に東西棟で建つ。桁行９．５ｍ梁間３．９ｍの土蔵造２階建。切妻造で桟瓦葺とする。壁を漆喰仕上げとし、北面に出入り口を設ける。通り側は腰を海鼠壁とし、窓を穿ち、銅製開戸を吊るなど、道具蔵と相似する外観をつくり、風格のある構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008350"},{"id":"00008348","register_sub_id":"101","register_pk":"133990","name":"華泉酒造場店舗兼主屋","kana":"かせんしゅぞうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ221","lat":34.46951772,"lng":131.77531346,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積303㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0140","desc":"通りに西面する町家。間口１１ｍの木造２階建で、北側面に十畳の座敷、背面に台所などを付設する。切妻造で正面に下屋庇を付け、桟瓦で葺く。２階は大壁で、虫籠窓を開け、両端に袖ウダツを付け、１階には出格子などを構える。商家らしい雰囲気をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008348"},{"id":"00008349","register_sub_id":"101","register_pk":"133991","name":"華泉酒造場道具蔵","kana":"かせんしゅぞうじょうどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ221","lat":34.46959684,"lng":131.77523698,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0141","desc":"主屋の北側に東西棟で建つ。桁行６．８ｍ梁間３．９ｍの土蔵造２階建。切妻造妻入で桟瓦葺とする。自然石を並べ基礎をつくり、壁を漆喰仕上げとし、東面に出入口を設ける。通り側は腰を海鼠壁とし、上部に窓を穿ち、銅製開戸を吊る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008349"},{"id":"00008351","register_sub_id":"101","register_pk":"133993","name":"華泉酒造場中の蔵","kana":"かせんしゅぞうじょうなかのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ221","lat":34.46943332,"lng":131.77555347,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積191㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0143","desc":"主屋の東方、作業場を介して続く。東西棟の切妻造桟瓦葺。梁間６．５ｍで、桁行が３０ｍに及ぶ長大な平屋建土蔵。内部は土間で、東西二室に分け、酒樽を置く。基礎を石積とし、外壁は漆喰仕上げで、腰に竪板を張る。老舗酒造場の佇まいを伝える大規模醸造蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008351"},{"id":"00008352","register_sub_id":"101","register_pk":"133994","name":"華泉酒造場東の蔵","kana":"かせんしゅぞうじょうひがしのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ221","lat":34.46940694,"lng":131.77574337,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積144㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0144","desc":"敷地東端に位置し、小路に面する。南北棟の土蔵造２階建で、南面に下屋を設け、南北１５ｍ東西９．３ｍの規模に及ぶ。北面は入母屋造、南面は切妻造、桟瓦を葺く。石積基礎上に建ち、板を高く張り、上部を漆喰仕上げとする。小路の町並に落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008352"},{"id":"00012980","register_sub_id":"101","register_pk":"368059","name":"旧槙原製鉄場角炉","kana":"きゅうまきはらせいてつじょうかくろ","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県仁多郡奥出雲町上阿井1325-6","lat":35.12033333,"lng":132.94377778,"geo_status":"db","era":"昭和10年／平成4年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"煉瓦造、高さ10m","structure_material":"煉瓦造","registered":"2019.09.10(令和1.09.10)","register_no":"32 － 201","desc":"町南部のたたら角炉伝承館にある銑鉄用溶鉱炉。炉高10・3メートル、長方形平面の煉瓦積で、四隅と外周9箇所を鉄骨で補強する。長辺中ほどの表裏に投入口、短辺基部の表裏に出銑口と排滓口を設ける。山陰地方における近代製鉄技術の実態を示す貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012980"},{"id":"00009374","register_sub_id":"101","register_pk":"194167","name":"財間酒造場仕込蔵","kana":"ざいましゅぞうじょうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県鹿足郡津和野町中座ロ34","lat":34.45421219,"lng":131.76931447,"geo_status":"db","era":"大正13年／昭和中期・平成15年頃改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積316㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"32 － 0164","desc":"敷地東側、東蔵の北隣に平行して東西棟で建つ。切妻造桟瓦葺、桁行二七・六メートル梁間八・五六メートル、漆喰仕上げの外壁に、腰には竪板を張る。二階には東蔵に向けて渡廊下が設置される。外壁に穿つ窓を千鳥に配し、軽快な印象になる大型の酒蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009374"},{"id":"00009371","register_sub_id":"101","register_pk":"194164","name":"財間酒造場新宅","kana":"ざいましゅぞうじょうしんたく","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県鹿足郡津和野町中座ロ34","lat":34.45397424,"lng":131.76884333,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積102㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"32 － 0161","desc":"敷地南西隅に建つ。木造平屋建、切妻造桟瓦葺、建築面積一〇二平方メートル。玄関及び前室、客間、座敷などを略田字形に配し、旧廿日市街道に沿って離れを張出す。斜面地に建つため棟を段違いとするなど複雑な屋根構成をもち、特徴的な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009371"},{"id":"00009370","register_sub_id":"101","register_pk":"194163","name":"財間酒造場店舗兼主屋","kana":"ざいましゅぞうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町中座ロ34","lat":34.45409798,"lng":131.76884333,"geo_status":"db","era":"江戸後期／明治中期・昭和54年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積266㎡、煙突付","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"32 － 0160","desc":"旧山陰道に面して建つ。木造平屋建、切妻造桟瓦葺、建築面積二六六平方メートル。正面中央に玄関、左手に事務室及び店舗部、右手に住居部を配する。店舗のほぼ中央に煉瓦煙突を建てる。山間部に所在する大規模な老舗造酒屋の中心建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009370"},{"id":"00009373","register_sub_id":"101","register_pk":"194166","name":"財間酒造場東蔵","kana":"ざいましゅぞうじょうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町中座ロ34","lat":34.45407894,"lng":131.76913363,"geo_status":"db","era":"江戸後期／大正4年・昭和54年・平成15年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積236㎡","structure_material":"土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"32 － 0163","desc":"店舗兼主屋の店舗部後方に接続する。桁行二七・六メートル梁間八・六メートル。切妻造桟瓦葺。外壁は漆喰仕上げとし、腰は、妻側は低く、平側は高く竪板を張る。二階床直上に蒸し米を冷ますための腰窓を設ける。主屋と一連で造酒屋の歴史的景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009373"},{"id":"00009372","register_sub_id":"101","register_pk":"194165","name":"財間酒造場舟蔵及び百石蔵","kana":"ざいましゅぞうじょうふねくらおよびひゃっこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町中座ロ34","lat":34.45441682,"lng":131.76887665,"geo_status":"db","era":"舟蔵 江戸後期／大正期増築・昭和中期改修 百石蔵 大正期／大正期増築・昭和中期改修","year":1751,"year_source":"db","year_min":1751,"year_max":1751,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積423㎡","structure_material":"土蔵造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"32 － 0162","desc":"旧山陰道に面し、主屋の北側に舟蔵、百石蔵と連ねて建つ。土蔵造平屋建、切妻造桟瓦葺、建築面積四二三平方メートル、北妻と東面南寄りに出入口を開ける。外壁漆喰塗、腰を竪板張とし、等間隔に窓を穿つ。長大な蔵で、造酒屋らしい景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009372"},{"id":"00011798","register_sub_id":"101","register_pk":"210814","name":"酒持田本店旧蔵","kana":"さけもちだほんてんきゅうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県出雲市平田町字片原町785-1","lat":35.437398,"lng":132.820856,"geo_status":"db","era":"明治10年頃／大正期・昭和期増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積493㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"32-0184","desc":"主屋の北奥に建つ。梁間四間、桁行五間、入母屋造の土蔵に増改築がなされ大屋根を架ける。内部は貯蔵庫、槽場及び倉庫から成り、一部に二階床を張る。酒造施設の中核をなす貯蔵施設であり、敷地景観を特徴付ける大型の建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011798"},{"id":"00011799","register_sub_id":"101","register_pk":"210815","name":"酒持田本店検査場","kana":"さけもちだほんてんけんさば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県出雲市平田町字片原町785-1","lat":35.437244,"lng":132.820796,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、鋼板葺、建築面積43㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"32-0185","desc":"主屋の北で旧蔵に接続する。桁行七・九メートル、梁間五・五メートルで、一階は試験室二室とし、二階は一室の休憩室とする。外壁は下見板張で、出入口にはアーチ型の庇を付ける。洋風意匠とされることの多い酒造業の検査場の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011799"},{"id":"00011797","register_sub_id":"101","register_pk":"210813","name":"酒持田本店店舗兼主屋","kana":"さけもちだほんてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市平田町字片原町785","lat":35.437108,"lng":132.820941,"geo_status":"db","era":"明治10年頃／大正初期・昭和3年増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積351㎡、塀付","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"32-0183","desc":"宍道湖西の平田町中心部に建つ。切妻造桟瓦葺で、南面する。通り土間を挟み西に一列三室の店舗、東に二列四室の居室を並べ座敷二間を張り出し、二階は三列三室。正面は平格子を構え伝統的な意匠とするが、座敷廻りや洋間など近代的な要素も見られる大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011797"},{"id":"00012803","register_sub_id":"101","register_pk":"367706","name":"酒持田本店土蔵","kana":"さけもちだほんてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市平田町字片原町810","lat":35.44215389,"lng":132.81780694,"geo_status":"db","era":"明治後期／昭和47年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階地下1階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階地下1階建","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 197","desc":"向座敷の東隣に北面して建つ。土蔵造二階建、切妻造桟瓦葺妻入で、正面に下屋を付す。外壁は漆喰塗で鉢巻三段を廻し、正面の腰を海鼠壁とする。内部は上下階とも板敷で運河に面する背面側を懸造状につくり地下室を設ける。商家町の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012803"},{"id":"00012802","register_sub_id":"101","register_pk":"367705","name":"酒持田本店向座敷","kana":"さけもちだほんてんむこうざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県出雲市平田町字片原町810","lat":35.44215389,"lng":132.81780694,"geo_status":"db","era":"昭和8年／平成22年・同25年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 196","desc":"市東部の平田町中心部の商家。向座敷は街道を挟んで主屋と向き合い、北面して建つ。切妻造桟瓦葺、建ちの高い総二階建で、背面を運河に面し、中央部に運河に抜ける通路（カケダシ）を設ける。内部に改変があるが外観や平面構成に伝統形式をよく留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012802"},{"id":"00007313","register_sub_id":"101","register_pk":"108295","name":"下森酒造場煙突","kana":"したもりしゅぞうじょうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和中","pref":"島根県","address":"島根県鹿足郡津和野町左鐙字立山ノ麓992","lat":34.49296922,"lng":131.87423648,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造、高さ19m","structure_material":"鉄筋コンクリート造","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0078","desc":"店舗兼主屋の西、旧酒蔵の作業場の南に位置する。鉄筋コンクリート造。基礎部直径１．２ｍで、高さ１９ｍに及ぶ。作業場内に設けられた、酒米を蒸す煉瓦造の竈の排煙のために建設された。石州赤瓦が葺かれる建物群の中に高く聳え、ランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007313"},{"id":"00007314","register_sub_id":"101","register_pk":"108296","name":"下森酒造場旧米蔵","kana":"したもりしゅぞうじょうきゅうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町左鐙字立山ノ麓992","lat":34.49290351,"lng":131.87423648,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積47㎡","structure_material":"土蔵造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0079","desc":"店舗兼主屋の西南に東西棟で建つ。桁行９．２ｍ梁間５．１ｍ規模で、切妻造桟瓦葺。東正面に庇、北面中央に瓦の水切りを設け、それぞれを出入口とする。腰モルタル塗、上部漆喰仕上げで、正面と南面に窓を穿つ。東正面上部にある諫鼓鶏の鏝細工が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007314"},{"id":"00007312","register_sub_id":"101","register_pk":"108294","name":"下森酒造場旧酒蔵","kana":"したもりしゅぞうじょうきゅうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町左鐙字立山ノ麓992","lat":34.49298597,"lng":131.8741843,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積444㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0077","desc":"店舗兼主屋の西に、作業場を介して建つ。切妻造の酒蔵庫を中心に、南北に屋根を葺き降ろし、南面西端に切妻屋根を突き出し、麹室を設け、西面には南北の切妻屋根を付設する。当初は荒壁。中央の酒蔵庫が古く、度重なる増築により複雑な屋根形態が形成された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007312"},{"id":"00007315","register_sub_id":"101","register_pk":"108297","name":"下森酒造場旧精米所","kana":"したもりしゅぞうじょうきゅうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町左鐙字立山ノ麓992","lat":34.49289139,"lng":131.87416556,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0080","desc":"旧米蔵の西に接して建つ。旧米蔵より一段低い切妻造桟瓦葺。桁行７．９ｍ梁間５．１ｍ規模の木造平屋建で、内部は東寄りに中２階を設ける。白漆喰仕上げの真壁造で、腰に竪板を張る。旧米蔵と一連で通りに面し、落ち着きのある街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007315"},{"id":"00007310","register_sub_id":"101","register_pk":"108292","name":"下森酒造場店舗兼主屋","kana":"したもりしゅぞうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町左鐙字立山ノ麓992","lat":34.49299841,"lng":131.87438708,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積164㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0075","desc":"横道川沿いの通り北側に占める敷地の中央に、南面して建つ。桁行１５ｍ梁間９．８ｍ、入母屋造で下屋庇をまわし、正面中央に入母屋屋根を突き出す。内部は西側の土間を店舗とし、東に六間取の床上部を設ける。座敷のトコや違棚などに良質な意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007310"},{"id":"00007311","register_sub_id":"101","register_pk":"108293","name":"下森酒造場土蔵","kana":"したもりしゅぞうじょうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町左鐙字立山ノ麓992","lat":34.49308273,"lng":131.87466053,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積27㎡","structure_material":"土蔵造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0076","desc":"店舗兼主屋の東北に位置する。東西棟の切妻造桟瓦葺で、西面に桟瓦葺庇を設け、戸口を開ける。桁行６．１ｍ梁間４．４ｍ規模の土蔵造平屋建。石積基礎とし、壁は白漆喰仕上げ、鉢巻を一段まわす。石州赤瓦と白漆喰壁が強いコントラストを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007311"},{"id":"00007316","register_sub_id":"101","register_pk":"108298","name":"下森酒造場門","kana":"したもりしゅぞうじょうもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町左鐙字立山ノ麓992","lat":34.49289244,"lng":131.87438956,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口5.2m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0081","desc":"店舗兼主屋の正面、通りに南面して建つ。棟門で、中央に両開板戸を吊り、東に潜戸を設け、背面に控柱を建てる。切妻造桟瓦葺で、棟を青海波とする。柱上に冠木を通し、一材から作り出した男梁・女梁を架し、軒は一軒疎垂木。重厚で風格を備えた門構えである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007316"},{"id":"00000478","register_sub_id":"101","register_pk":"101468","name":"鳥上木炭銑工場角炉施設","kana":"とりかみもくたんせんこうじょうかくろしせつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県仁多郡奥出雲町大呂529","lat":35.19212858,"lng":133.13047696,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造及び鉄造角炉2基，木造2階建覆屋付属","structure_material":"煉瓦造及び鉄造角炉2基","registered":"1998.01.16(平成10.01.16)","register_no":"32 － 0009","desc":"製鉄用の角炉２基に覆屋をかけた構成になる。この施設での製鉄は，大正７年に創業，以後数度の改良を経て，昭和４０年まで続いた。角炉は，煉瓦造の１号炉が創業時，鉄製の２号炉がしょうわ２７年の建設。大正期の地場産業を象徴する産業施設として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000478"},{"id":"00008347","register_sub_id":"101","register_pk":"133989","name":"橋本酒造場表門","kana":"はしもとしゅぞうじょうおもてもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ218","lat":34.46928826,"lng":131.77502598,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口1.7m、左右袖塀付","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0139","desc":"主屋と道具蔵の間に、通りに面して建つ。間口１．７ｍの棟門で、左右に袖塀を付ける。本柱上、冠木を載せ、男梁を前後に出し、軒桁を支持する。軒天井を張り、一軒疎垂木。切妻造で、桟瓦を葺く。袖塀は腰モルタル、上部漆喰仕上げで桟瓦葺。屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008347"},{"id":"00008345","register_sub_id":"101","register_pk":"133987","name":"橋本酒造場店舗兼主屋","kana":"はしもとしゅぞうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ218","lat":34.46921705,"lng":131.77509983,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積350㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0137","desc":"通りに西面する間口１４ｍの平入町家で、側背面に座敷や仏間、浴室などを付設する。切妻造で桟瓦を葺き、正面に下屋庇を付ける。木造つし２階建。上屋部分に袖ウダツや虫籠窓、格子、１階に子持格子などを構える。重厚な表構えになる大規模な商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008345"},{"id":"00008346","register_sub_id":"101","register_pk":"133988","name":"橋本酒造場道具蔵","kana":"はしもとしゅぞうじょうどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ218","lat":34.46932254,"lng":131.7750629,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0138","desc":"庭を挟んで、主屋北側に位置する。桁行５．６ｍ梁間４．７ｍの土蔵造２階建。切妻造で桟瓦葺、南面に鉄板葺庇を付ける。自然石積基礎上、漆喰仕上げとし、通り側は腰を海鼠壁とし、上部に銅製の開戸を吊る窓を開ける。通りに妻を見せ、表構えに変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008346"},{"id":"00013631","register_sub_id":"101","register_pk":"505000","name":"藤代酒店客殿","kana":"ふじしろさけてんきゃくでん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県江津市都野津町2283-14他","lat":34.98689722,"lng":132.18931944,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"32 － 0207","desc":"前面道路から前庭をはさみ主屋南脇に建つ。平屋建入母屋造で石州赤瓦を葺く。中央の座敷、東の次の間からなり前庭側に広縁、背面側に便所、浴室を配する。座敷の床構えは違い棚、書院を備えた端正な意匠を持つ。周囲の庭とともに良好な屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013631"},{"id":"00013630","register_sub_id":"101","register_pk":"504999","name":"藤代酒店店舗兼主屋","kana":"ふじしろさけてんてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市都野津町2283-16他","lat":34.98698333,"lng":132.18934444,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"32 － 0206","desc":"都野津の駅前通りに西面して建つ。つし二階建切妻造桟瓦葺平入で、下屋を三方に廻らす。通り土間沿いにミセや事務室をおき、上手は座敷や居間等の二列四室構成とする。奥に台所を突出させる。石州赤瓦や二階窓脇の瓢箪鏝絵などに地域の町家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013630"},{"id":"00013632","register_sub_id":"101","register_pk":"505001","name":"藤代酒店土蔵","kana":"ふじしろさけてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市都野津町2283-続1","lat":34.98685,"lng":132.18941111,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"32 － 0208","desc":"客殿の東に接続し北面して建つ。東西棟とし土蔵造二階建切妻造で石州赤瓦を葺く。北面の戸前には庇を差し掛ける。破風の拝みに色漆喰で紐と房を鏝絵で飾り、妻は藤の字をかたどる。内部は一階は東西二室とし、二階は一室である。屋敷構えの一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013632"},{"id":"00013633","register_sub_id":"101","register_pk":"505002","name":"藤代酒店旧酒蔵（酒蔵館）","kana":"ふじしろさけてんもとさかぐら（さかぐらかん）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県江津市都野津町2283他","lat":34.98705,"lng":132.18956111,"geo_status":"db","era":"明治後期／平成14年・同28年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積222㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"32 － 0209","desc":"主屋北に建ち、土間で接続する。東西棟で二階建切妻造とし石州赤瓦を葺く。北東隅を戸前とし、漆喰仕上で腰は板張とする。醸造蔵であったが規模を縮小し、一階の一部を展示室、他を二階とともに居室とした。主屋等とともに都野津の酒造の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013633"},{"id":"00008344","register_sub_id":"101","register_pk":"133986","name":"古橋酒造場旧衣装蔵","kana":"ふるはししゅぞうじょうきゅういしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ196他","lat":34.46873703,"lng":131.77490202,"geo_status":"db","era":"大正10年頃／平成15年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0136","desc":"主屋の東南、貯蔵蔵の西に位置する。東西棟の切妻造で、桟瓦で葺く。桁行４．６ｍ梁間４．０ｍの土蔵造２階建。庭側の北面に出入口を設け、庇を付け、上部に窓を穿つ。切石基礎に建ち、腰を海鼠壁、上部を漆喰仕上げとする。庭園を意識したデザインである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008344"},{"id":"00008341","register_sub_id":"101","register_pk":"133983","name":"古橋酒造場作業場","kana":"ふるはししゅぞうじょうさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ196他","lat":34.46883461,"lng":131.77509455,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積165㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0133","desc":"主屋の東側、北側通り沿いに続く土蔵造２階建。桁行２４ｍ梁間７．０ｍ、切妻造桟瓦葺。石積基礎を造り、外壁を高く下見板張、鉢巻を漆喰仕上げとし、重厚な街路景観を創出する。１階は作業室と貯蔵室、２階には畳敷の部屋や酵母室を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008341"},{"id":"00008342","register_sub_id":"101","register_pk":"133984","name":"古橋酒造場仕込蔵","kana":"ふるはししゅぞうじょうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ196他","lat":34.46876604,"lng":131.77535566,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積301㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0134","desc":"作業場の東から敷地東端に延びる、桁行２８ｍ梁間最大１２ｍの大規模な２階建土蔵。入母屋造桟瓦葺。切石基礎に建ち、腰竪板張の漆喰仕上げとし、二段に窓を開け、鉄扉を吊る。東面には大きく破風を設け、白漆喰で塗り込める。酒造場らしい敷地構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008342"},{"id":"00008343","register_sub_id":"101","register_pk":"133985","name":"古橋酒造場貯蔵蔵","kana":"ふるはししゅぞうじょうちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ196他","lat":34.46867109,"lng":131.77501015,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積197㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0135","desc":"敷地南辺の中央に位置する。東西棟の切妻造桟瓦葺で、西端に越屋根を設ける。桁行１９ｍ梁間１０ｍの土蔵造平屋建。腰をモルタル仕上げや板張とする漆喰仕上げで、鉄格子窓を要所に穿つ。梁や桁など太い軸組の和小屋により、広い内部空間を実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008343"},{"id":"00008340","register_sub_id":"101","register_pk":"133982","name":"古橋酒造場店舗兼主屋","kana":"ふるはししゅぞうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ196他","lat":34.46885044,"lng":131.77482553,"geo_status":"db","era":"大正10年頃／昭和30年増築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積310㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0132","desc":"通りに西面する間口１３ｍの木造２階建の町家。モルタル吹付け仕上げの洋館と、昭和増築の座敷を付設する。北入母屋南切妻造桟瓦葺で、側面を大壁造、正面を真壁造とする。２階の内法を高くし、正面に子持格子、両端に袖ウダツを付け、豪壮な正面構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008340"},{"id":"00001942","register_sub_id":"101","register_pk":"102932","name":"倉敷市立磯崎眠亀記念館","kana":"くらしきしりついそざきみんききねんかん","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市茶屋町195","lat":34.57779059,"lng":133.82257338,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造2階建、瓦葺、建築面積257㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"33 － 0052","desc":"織物産業界で活躍した実業家磯崎眠亀の住宅兼作業場。金比羅往来の中継地点茶屋町に建つ。木造２階建，入母屋造本瓦葺で屋根にむくりをつける。物資輸送用に内部に設けたスロープ・吹抜け，回転と横滑りにより開閉する雨戸などに，眠亀の創意が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001942"},{"id":"00001015","register_sub_id":"101","register_pk":"102005","name":"倉敷紡績記念館","kana":"くらしきぼうせききねんかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市本町1207","lat":34.59540774,"lng":133.77302182,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造一部煉瓦造２階建，瓦葺，建築面積701㎡","structure_material":"木造一部煉瓦造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"33 － 0025","desc":"倉敷紡績創業時の遺構で，敷地の西北方（かっての正門脇）に位置する。材料倉庫（綿花蔵）として建てられたもので，腰を板貼りとした伝統的な土蔵造りの外観を呈する。後に２棟をつないでコの字型平面とし，増築部との境に煉瓦壁を建ち上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001015"},{"id":"00001016","register_sub_id":"101","register_pk":"102006","name":"児島虎次郎記念館","kana":"こじまとらじろうきねんかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市本町1160","lat":34.59557387,"lng":133.7727277,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造２階建，瓦葺，建築面積792㎡","structure_material":"煉瓦造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"33 － 0026","desc":"倉敷紡績工場の製品倉庫として建てられた。工場敷地の西北隅に位置するコの字型平面，５庫前の煉瓦造倉庫で，入口廻りの大仰な額縁意匠が印象的。小屋組は木造トラスで，倉敷紡績記念館のトラスよりもより洗練されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001016"},{"id":"00012036","register_sub_id":"101","register_pk":"210977","name":"田中酒造場仕込蔵","kana":"たなかしゅぞうじょうしこみくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県美作市古町字屋敷1655他","lat":35.121401,"lng":134.32555,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積237㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-289","desc":"敷地東面南寄りに建つ南北棟の蔵。木造二階建、桟瓦葺、桁行二一・一メートル、梁間一一・三メートルで、北半のみ二階床を張る。一階南端部は槽場、二階北端部は麹室とし、他は醸造樽等を置く。敷地東側の景観を作ると共に、酒造の中核をなす蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012036"},{"id":"00012033","register_sub_id":"101","register_pk":"210974","name":"田中酒造場主屋","kana":"たなかしゅぞうじょうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県美作市古町字屋敷1655他","lat":35.121383,"lng":134.325097,"geo_status":"db","era":"明治18年頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積242㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-286","desc":"因幡街道の宿場町である古町の中心部に建つ。木造二階建、切妻造桟瓦葺で、土間に面してミセを配し、その南に式台玄関等床上部を三列九室で配する。外壁二階部分は漆喰塗で、下部に海鼠壁を配すなど、意匠を凝らす。街道沿いの景観を今に伝える主屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012033"},{"id":"00012037","register_sub_id":"101","register_pk":"210978","name":"田中酒造場貯蔵蔵","kana":"たなかしゅぞうじょうちょぞうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県美作市古町字屋敷1655他","lat":35.121388,"lng":134.325447,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積269㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-290","desc":"仕込蔵の西側に壁を接して建つ南北棟の蔵。木造平屋建、切妻造桟瓦葺で、桁行二一・一メートル、梁間八・三メートルの西面南寄りに、釜場、会召場等を張り出す。床は叩きで、天井を高くとる。仕込蔵と共に酒造業の中核をなす建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012037"},{"id":"00012035","register_sub_id":"101","register_pk":"210976","name":"田中酒造場本蔵","kana":"たなかしゅぞうじょうほんくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県美作市古町字屋敷1655他","lat":35.121324,"lng":134.325255,"geo_status":"db","era":"明治18年頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-288","desc":"主屋の南東方、敷地南端中央部に位置する。土蔵造二階建、桟瓦葺で、北面中央と西面北寄りに扉口を開く。南北面に庇を設け、二階外壁は漆喰塗下部海鼠壁、一階外壁は板張もしくは土壁とする。酒造業の作業場の南方を画し、敷地内外の景観を形成する土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012035"},{"id":"00012034","register_sub_id":"101","register_pk":"210975","name":"田中酒造場店蔵","kana":"たなかしゅぞうじょうみせくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県美作市古町字屋敷1655他","lat":35.121514,"lng":134.325044,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-287","desc":"主屋の北隣に、街路に面し棟を平行させて建つ。土蔵造二階建、桟瓦葺で、外壁は軒まで漆喰塗籠とし、一階腰部と二階下部を海鼠壁とし、四隅は上部まで海鼠壁を立ち上げる。入口は主屋との間の狭い空間に設ける。街路景観を特徴付ける土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012034"},{"id":"00006416","register_sub_id":"101","register_pk":"107399","name":"備中屋高祖酒造井戸及び洗い場","kana":"びっちゅうやこうそしゅぞういどおよびあらいば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市牛窓町牛窓3097-1","lat":34.61492976,"lng":134.16615228,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"井戸 石造、面積1.1㎡、洗い場 コンクリート造、面積8.8㎡","structure_material":"井戸 石造","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0166","desc":"敷地のほぼ中央、圧搾蔵の東方に位置する醸造用の井戸。円形で、径１．２ｍ。井筒は石積で、井戸枠は切石積にモルタル塗とする。洗い場は井戸の北に位置し、東西４ｍ、南北２．２ｍ。わずかに縁を立ち上げてモルタル塗とする。酒造の工程を示す遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006416"},{"id":"00006417","register_sub_id":"101","register_pk":"107400","name":"備中屋高祖酒造煙突","kana":"びっちゅうやこうそしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県瀬戸内市牛窓町牛窓3097-1","lat":34.61489468,"lng":134.16614939,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"煉瓦造、高さ15m","structure_material":"煉瓦造","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0167","desc":"敷地のほぼ中央、洗い場の北に位置する、蒸米用竈の煙突。正方形平面の煉瓦造で、基底部は１．２ｍ角、高さ約１５ｍ。煉瓦はイギリス積とし、帯鉄で補強している。上部の東面と西面に醸造銘柄「千寿」の文字を記す。牛窓港の「赤煙突」として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006417"},{"id":"00006413","register_sub_id":"101","register_pk":"107396","name":"備中屋高祖酒造主屋","kana":"びっちゅうやこうそしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県瀬戸内市牛窓町牛窓3097-1","lat":34.614811,"lng":134.1661499,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積170㎡、板塀付","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0163","desc":"北東角地の敷地で、南側道路に面して建つ木造２階建。入母屋造本瓦葺で、四周に下屋庇がつく。正面１階は出格子とし、２階は海鼠壁に黒漆喰塗とする。内部は東に土間、西に８畳座敷など６室を配す。小庭を板塀が囲む。酒造家の風格のある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006413"},{"id":"00003705","register_sub_id":"101","register_pk":"104695","name":"丸本酒造井戸及び石垣","kana":"まるもとしゅぞういどおよびいしがき","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.5645436,"lng":133.58928267,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造井戸、面積1.8㎡、木造上屋付、石垣延長30m","structure_material":"石造井戸","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0076","desc":"屋敷北端部の水場に位置する。井戸は石造井桁組で井筒を築き，１間四方，切妻造，本瓦葺の上屋をかける。井戸南東方の一段下がった田地境には，切石積の石垣を折れ曲がり延長３０ｍ築き法面を固める。屋号「清水屋」のもととなった醸造業には欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003705"},{"id":"00003699","register_sub_id":"101","register_pk":"104689","name":"丸本酒造釜場","kana":"まるもとしゅぞうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.563732,"lng":133.589066,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0070","desc":"敷地南西端，西蔵南妻面に接して建つ酒米蒸し用の施設。敷地形状に合わせて台形平面を呈し，切妻造，桟瓦葺で，屋根中央やや西寄りに換気のための越屋根を備える。小屋組にトラスを用いるが，その他は伝統的な意匠になり，酒造業施設に相応しい外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003699"},{"id":"00003697","register_sub_id":"101","register_pk":"104687","name":"丸本酒造店","kana":"まるもとしゅぞうてん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56388993,"lng":133.58914022,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積63㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0068","desc":"屋敷南面に開く進入路の西脇に建つ。２階建で南正面に下屋を付属し，屋根は桟瓦葺で，東面入母屋造，西面は西蔵に接続する。１階は土間と帳場からなる店舗とし，２階に座敷を配する。簡素だがたちの高い外観は屋敷南面の外観を整える主要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003697"},{"id":"00003698","register_sub_id":"101","register_pk":"104688","name":"丸本酒造店脇門・塀及び石段","kana":"まるもとしゅぞうてんわきもん・へいおよびいしだん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56380593,"lng":133.58916944,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造、間口1.8m、塀延長12m、石段面積16㎡","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0069","desc":"店の南方に位置し，西半は切石積石垣上の東・南・西３方に塀を回し，東面に脇門を開き，東半の店出入口前には切石積石段を配す。門は本瓦葺の棟門形式で，塀は桟瓦葺，腰簓子下見張とする。川に面して一段高く築いた店正面の構えを形成する主要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003698"},{"id":"00003701","register_sub_id":"101","register_pk":"104691","name":"丸本酒造取合廊下","kana":"まるもとしゅぞうとりあいろうか","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56394664,"lng":133.58907251,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0072","desc":"店背後から座敷屋に至る間にあり，西蔵東側面に接して建つ。柱または桁でトラス組を支え，切妻造，桟瓦葺の屋根をかけ，吹き放しの蔵前荷捌き場となる。簡略な建物だが，撥形平面を呈し，西蔵出入口前に庇を葺き降ろすなど，変化に富んだ外観，架構をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003701"},{"id":"00003700","register_sub_id":"101","register_pk":"104690","name":"丸本酒造西蔵","kana":"まるもとしゅぞうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56385539,"lng":133.58904723,"geo_status":"db","era":"大正初期／昭和初期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積432㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0071","desc":"敷地西辺を限る位置に建つ仕込蔵。２階建，切妻造，桟瓦葺，小屋トラス組の土蔵２棟を東西に並置した形式で，東棟北には蔵人部屋を付属する。大きめの軒蛇腹を回し，漆喰塗壁面の随所に小窓を明けた独特の外観は，屋敷西・南面の景観を構成する主要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003700"},{"id":"00003703","register_sub_id":"101","register_pk":"104693","name":"丸本酒造東囲蔵","kana":"まるもとしゅぞうひがしいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56436254,"lng":133.58936754,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積170㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0074","desc":"東蔵の東に隣接する物置用の蔵。桁行３０ｍ，梁間６ｍの細長い平面で，柱，梁などの軸部は細い丸太材で構成し，小屋はトラス組とし，切妻造，桟瓦葺の屋根を架ける。外回りは大壁とするが，軒等は塗り込めない。東蔵とともに屋敷東辺の景観形成の要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003703"},{"id":"00003702","register_sub_id":"101","register_pk":"104692","name":"丸本酒造東蔵","kana":"まるもとしゅぞうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56432829,"lng":133.58930092,"geo_status":"db","era":"大正2／昭和初期増築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積747㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0073","desc":"座敷屋東方に位置する仕込蔵。梁間がほぼ等しい東西棟を並置し，東棟の北に旧麹室を接続する。２階建，土蔵造で，切妻造，桟瓦葺屋根を並べ，軸部はもとより垂木，根太も丸太を用いる。簡素だが高台に建つ大型の蔵で，屋敷北東部の景観形成上欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003702"},{"id":"00003704","register_sub_id":"101","register_pk":"104694","name":"丸本酒造南蔵","kana":"まるもとしゅぞうみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56397654,"lng":133.58942015,"geo_status":"db","era":"大正初期／昭和初期増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積313㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0075","desc":"敷地南辺を限る道に沿ってへの字に折れて配された蔵で，西半を貯米場，東半を精米所としていた。土蔵造，２階建で，小屋をトラス組とし，屋根切妻造，桟瓦葺とする。長大な壁面に小窓を規則的に並べた外観は，周囲の田園風景と相俟って独特の景観を形づくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003704"},{"id":"00014942","register_sub_id":"101","register_pk":"519202","name":"山成酒造内蔵","kana":"やまなりしゅぞううちぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県井原市芳井町簗瀬字見瀬側23","lat":34.62305,"lng":133.43791667,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積31㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0363","desc":"敷地北面中央に建つ家財蔵。２階建切妻造妻入桟瓦葺の東西棟で、離れ座敷と縁で接続する。外壁は漆喰仕上で水切を一段廻らし、腰はモルタル洗出仕上。各階南北２室で1階は板敷、２階は畳敷で竿縁天井を張る。小規模ながら通りに面し歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014942"},{"id":"00014943","register_sub_id":"101","register_pk":"519203","name":"山成酒造蔵","kana":"やまなりしゅぞうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県井原市芳井町簗瀬字見瀬側23","lat":34.62294722,"lng":133.43826389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0364","desc":"敷地南東隅に建つ米蔵及び家財蔵。切妻造桟瓦葺南北棟。外壁は軒まで塗込めて漆喰塗仕上、一、二階の腰は海鼠壁とする。内部は東西２室に仕切り、北寄りは土間で上部吹抜とした米蔵、南寄りは２階建で各階板敷の家財蔵。通りに面して歴史的景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014943"},{"id":"00014940","register_sub_id":"101","register_pk":"519200","name":"山成酒造店舗兼主屋","kana":"やまなりしゅぞうてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県井原市芳井町簗瀬字見瀬側23","lat":34.62296389,"lng":133.43815278,"geo_status":"db","era":"明治15年／平成4年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0361","desc":"小田川西岸の集落角地に位置する造り酒屋の店舗兼主屋。敷地南東に位置し、東面する２階建切妻造平入桟瓦葺。外壁は漆喰塗で二階腰に海鼠壁を廻らす。中央北寄りは石敷の通り土間とし、北は帳場と洋室、南は瓶詰場と吹抜の倉庫を配す。間口長大な店舗兼主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014940"},{"id":"00014945","register_sub_id":"101","register_pk":"519205","name":"山成酒造西仕込蔵","kana":"やまなりしゅぞうにししこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県井原市芳井町簗瀬字見瀬側23","lat":34.62282778,"lng":133.43788333,"geo_status":"db","era":"明治前期／昭和中期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積262㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0366","desc":"敷地西端に建つ酒の仕込蔵。２階建切妻造桟瓦葺の南北棟の南に増築棟を延ばし、全体で長大な外観を呈する。外壁は漆喰塗仕上で腰は縦板張とする。中央西寄りの麹室以外は間仕切を設けず広い作業場とする。増築による大規模な姿が造り酒屋の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014945"},{"id":"00014941","register_sub_id":"101","register_pk":"519201","name":"山成酒造離れ座敷","kana":"やまなりしゅぞうはなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県井原市芳井町簗瀬字見瀬側23","lat":34.62309722,"lng":133.43805278,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0362","desc":"敷地北東隅に建つ離れ座敷。平屋建寄棟造、屋根を桟瓦葺とし南と東に下屋を廻らす。間取りは東西二室とし、東室は北辺に床と違棚を備えた座敷で、西室は北辺に仏壇と押入を構えた仏間とし、南と東に縁を廻らし中庭を望む。敷地北東隅の景観をつくる離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014941"},{"id":"00014944","register_sub_id":"101","register_pk":"519204","name":"山成酒造東仕込蔵","kana":"やまなりしゅぞうひがししこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県井原市芳井町簗瀬字見瀬側23","lat":34.622825,"lng":133.43799167,"geo_status":"db","era":"明治前期／大正後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積254㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0365","desc":"店舗兼主屋の西に建つ仕込蔵。二階建切妻造桟瓦葺の南北棟で、北妻の西寄りに試験室を張り出す。外壁は漆喰塗仕上で腰をモルタル塗仕上とする。１階は広大な土間で中央上部を吹抜として、貯蔵タンクを並べる。大規模な切妻屋根が造り酒屋の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014944"},{"id":"00015380","register_sub_id":"101","register_pk":"532504","name":"大藤家住宅釜場","kana":"おおとうけじゅうたくかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市高屋町白市1058-2","lat":34.45548889,"lng":132.82304167,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0319","desc":"主屋の北西に位置する釜場。平屋建切妻造平入桟瓦葺の東西棟で南面東寄りを吹放ちとする。内部は東側から酒粕切場・釜場、薪置場など並べ、いずれも土間で上部にキングポスト・トラスの小屋組を現す。醸造用の半地下の釜場などを残し、酒造業の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015380"},{"id":"00013328","register_sub_id":"101","register_pk":"366317","name":"金光酒造井戸小屋","kana":"かねみつしゅぞういどごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市黒瀬町乃美尾字東門前1364-2","lat":34.33524722,"lng":132.69190278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0270","desc":"敷地の南東に位置し、主屋から東に延びる門及び塀に接続して東西棟で建つ。木造平屋建、切妻造桟瓦葺で、四隅に柱を立て、南面のみ白漆喰塗の真壁とし、他は吹放しとする。中央に石造で井桁を組んだ井戸を配す。酒造りに欠かせない水を供給する施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013328"},{"id":"00013330","register_sub_id":"101","register_pk":"366319","name":"金光酒造煙突","kana":"かねみつしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市黒瀬町乃美尾字東門前1364-2","lat":34.33545833,"lng":132.69191667,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、高さ12m","structure_material":"煉瓦造","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0272","desc":"包装所の北東に建つ煉瓦造の煙突。基部は外法が一辺約１・５メートルの正方形平面で、イギリス積みとする。高さは約１２メートルで、頂部は煉瓦を持出して帯状に装飾し、鉄骨で補強を施している。遠方からもよく見え、地域のシンボルとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013330"},{"id":"00013326","register_sub_id":"101","register_pk":"366315","name":"金光酒造仕込蔵","kana":"かねみつしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市黒瀬町乃美尾字東門前1364-2","lat":34.33551111,"lng":132.691675,"geo_status":"db","era":"明治前期／明治後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積409㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0268","desc":"敷地の北西に位置し、主屋と貯蔵蔵の間に建つ。土蔵造二階建で、北を上にしたＴ字形に棟を配し、南北棟の東側に下屋を付す。東西棟は寄棟造、南北棟は切妻造で、屋根は桟瓦葺、外壁は白漆喰塗。一階で仕込みを行い、二階は物置。醸造施設の主要な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013326"},{"id":"00013327","register_sub_id":"101","register_pk":"366316","name":"金光酒造貯蔵蔵","kana":"かねみつしゅぞうちょぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市黒瀬町乃美尾字東門前1364-2","lat":34.33555833,"lng":132.69186111,"geo_status":"db","era":"明治後期／大正後期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積315㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0269","desc":"敷地北端に位置し、仕込蔵に接して建ち、桁行３９メートルと長大である。土蔵造二階建、切妻造桟瓦葺で、東棟と落棟の西棟からなる。内部は一階を土間、二階を板敷とし、西棟の一階に貯蔵タンクが並ぶ。周囲からよく見え、酒造場の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013327"},{"id":"00013323","register_sub_id":"101","register_pk":"366312","name":"金光酒造離れ","kana":"かねみつしゅぞうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市黒瀬町乃美尾字東門前1364-2","lat":34.33508611,"lng":132.69172778,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0265","desc":"敷地中央に東面して建つ主屋の南側に、渡廊下を介し東西棟で建つ。木造平屋建、入母屋造桟瓦葺で、床、棚、書院を備えた八畳と西の六畳を縁と廊下で囲み、西端に風呂、便所、女中部屋を配す。磨き丸太の縁桁など数寄屋意匠を取入れた造酒家の離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013323"},{"id":"00013324","register_sub_id":"101","register_pk":"366313","name":"金光酒造瓶詰所","kana":"かねみつしゅぞうびんづめしょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市黒瀬町乃美尾字東門前1364-2","lat":34.33538056,"lng":132.69160833,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0266","desc":"敷地中央西端で、仕込蔵の南に接続し南北棟で建つ。木造二階建、切妻造桟瓦葺で、東面に下屋を付す。外壁は白漆喰塗の大壁で、一階の土間に瓶詰機を置き、二階には六畳間が二室、東西に並ぶ。住宅の一部を瓶詰所に転用した、醸造施設の一部を構成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013324"},{"id":"00013325","register_sub_id":"101","register_pk":"366314","name":"金光酒造包装所","kana":"かねみつしゅぞうほうそうじょ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市黒瀬町乃美尾字東門前1364-2","lat":34.33541389,"lng":132.69186389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0267","desc":"敷地中央北寄りで、北西部が仕込蔵に接続して東西棟で建つ。土蔵造二階建、切妻造桟瓦葺で、外壁は白漆喰塗、東妻面に三段の水切瓦を付す。一階は土間で包装所とし、二階は板敷で物置とする。家財蔵を包装所として転用し、醸造施設の一部を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013325"},{"id":"00013329","register_sub_id":"101","register_pk":"366318","name":"金光酒造門及び塀","kana":"かねみつしゅぞうもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市黒瀬町乃美尾字東門前1364-2","lat":34.33525,"lng":132.69184167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.9m 塀 木造、瓦葺、総延長5.6m","structure_material":"門 木造","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0271","desc":"敷地の南東に位置し、主屋から東に延びる。全長７・６メートルで、中央に一間薬医門を置く。門は本柱に五平の冠木を載せ、二重梁で切妻造桟瓦葺の屋根を受ける。両側の塀は柱から腕木を出して桁を受け、桟瓦葺の屋根を載せる。庭を仕切り、表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013329"},{"id":"00011193","register_sub_id":"101","register_pk":"205300","name":"賀茂泉酒造煙突","kana":"かもいずみしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条上市町953-3","lat":34.429143,"lng":132.749322,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ18m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0186","desc":"中蔵及び東蔵の東に立つ煉瓦造煙突。角型で、基部が一辺一・六メートル、高さ一七・七メートルとなる。煙突の上部には蛇腹の装飾を備える。他の西条の煉瓦造煙突と同様、煉瓦をイギリス積とする。使用は停止されたが、象徴的な景観として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011193"},{"id":"00011186","register_sub_id":"101","register_pk":"205293","name":"賀茂泉酒造新座敷","kana":"かもいずみしゅぞうしんざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"広島県","address":"広島県東広島市西条上市町944他","lat":34.429517,"lng":132.748866,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積229㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0179","desc":"店舗兼主屋の西側に接続して建つ。南には重森三玲作の庭が広がり、そちらへの眺望を意識して広い縁を廻らす。東寄りに東西続きの三室を、西寄りに南北続きの二室を配し、それぞれ数寄屋意匠を凝らした座敷飾や天井を持ち、接客を意識した建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011186"},{"id":"00011190","register_sub_id":"101","register_pk":"205297","name":"賀茂泉酒造通路棟","kana":"かもいずみしゅぞうつうろとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条上市町944他","lat":34.42933,"lng":132.749079,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積159㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0183","desc":"店舗兼主屋の南辺東端と、中蔵及び東蔵の北辺とを結び、西辺は火蔵と接続する南北棟の建物。土蔵造二階建で、現在は各土蔵と店舗兼主屋を繋ぎ、商品倉庫として用いられているが、当初は酒蔵として建てられたとみられる。賀茂泉酒造創業時期の状況を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011190"},{"id":"00011185","register_sub_id":"101","register_pk":"205292","name":"賀茂泉酒造店舗兼主屋","kana":"かもいずみしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条上市町944他","lat":34.429571,"lng":132.749017,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積179㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0178","desc":"通りに北面して建つ。平面は、東に土間を通し、西に二列六室の室を並べる。西列中室を仏間、奥室を一〇畳の主座敷とし、本格的な座敷飾を備える。正面側には二階を設ける。正面外観は開口部の縦格子を基調とし、二階には袖壁を設けて伝統的な町家の趣となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011185"},{"id":"00011187","register_sub_id":"101","register_pk":"205294","name":"賀茂泉酒造土蔵","kana":"かもいずみしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条上市町944他","lat":34.429611,"lng":132.748787,"geo_status":"db","era":"明治後期／昭和28頃移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0180","desc":"新座敷の北西に接続して建つ内蔵。もとは主屋の西に接して建っていたというが、新座敷建設時に現在地へ曳家された。一階東面に鉄格子付の窓を二つ並べるほかは窓を持たない閉鎖的な空間となる。北面には水切瓦を一列入れて、外観上の特徴とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011187"},{"id":"00011192","register_sub_id":"101","register_pk":"205299","name":"賀茂泉酒造中蔵及び東蔵","kana":"かもいずみしゅぞうなかぐらおよびひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条上市町944他","lat":34.429165,"lng":132.74914,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積324㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0185","desc":"通路棟の南に接続して建つ。一階の通路を挟んで東を東蔵、西を中蔵と呼ぶが、東西棟の一棟である。土蔵造二階建で、外壁は白漆喰塗の大壁とする。窓には漆喰塗込の格子を立て、東妻側には水切瓦を入れる。赤瓦を葺く規模の大きな酒蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011192"},{"id":"00011191","register_sub_id":"101","register_pk":"205298","name":"賀茂泉酒造火蔵","kana":"かもいずみしゅぞうひぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条上市町944他","lat":34.429273,"lng":132.748921,"geo_status":"db","era":"大正後期／昭和30・同63頃改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積355㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0184","desc":"通路棟の西に接続する二階建土蔵。北東棟と南西棟の二棟を包摂して東西棟の一棟となったもの。重森三玲が新座敷に作庭した後、その指示に従って海鼠壁を貼る改修を行い、庭園の背景として調和させた。酒造のみならず、庭園空間の構成要素となる土蔵である","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011191"},{"id":"00011189","register_sub_id":"101","register_pk":"205296","name":"賀茂泉酒造前蔵","kana":"かもいずみしゅぞうまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条上市町641-1","lat":34.429784,"lng":132.749062,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積199㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0182","desc":"店舗兼主屋から通りを挟んだ北側に南面して建つ。二階建の土蔵で、小屋組はキングポストトラスとする。外壁は白漆喰で、腰は水平に瓦を貼る海鼠壁とし、妻側上部には水切瓦を入れる。店舗兼主屋や門及び塀とともに酒蔵の建ち並ぶ旧西国街道の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011189"},{"id":"00011188","register_sub_id":"101","register_pk":"205295","name":"賀茂泉酒造門及び塀","kana":"かもいずみしゅぞうもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"広島県","address":"広島県東広島市西条上市町944","lat":34.42962895,"lng":132.74885194,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"門 木造、瓦葺、間口2.7m 塀 木造、瓦葺、延長15m","structure_material":"門 木造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0181","desc":"敷地北辺を画す門及び塀で、店舗兼主屋から土蔵までを繋ぎ、新座敷の玄関前に門を開く。門は薬医門形式で切妻造桟瓦葺とする。塀は真壁造として、通りに面した側は、下部に板を張り、上部を鼠漆喰で仕上げる。いずれも赤瓦を葺いて、通りの景観を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011188"},{"id":"00011820","register_sub_id":"101","register_pk":"210836","name":"賀茂鶴酒造一号蔵井戸","kana":"かもつるしゅぞういちごうぐらいど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町708-1","lat":34.430157,"lng":132.74533,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、面積3.2㎡","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0231","desc":"敷地の南東隅に位置する。上部は切石積、六角形平面の井戸桁、下部は円形の石組とする。賀茂鶴酒造創業時からの井戸であり、酒造を中心とした西条の町並み景観を特徴付けるのみならず、その歴史を今に伝える井戸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011820"},{"id":"00011818","register_sub_id":"101","register_pk":"210834","name":"賀茂鶴酒造一号蔵北土蔵","kana":"かもつるしゅぞういちごうぐらきたどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町708","lat":34.430245,"lng":132.74545,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0229","desc":"一号蔵東棟の南に西面して建つ。土蔵造二階建、妻入で、屋根は桟瓦葺。桁行七・六メートル、梁間四・一メートルで、外部は軒まで塗籠、内部は横板張とする。一・二階とも板敷で、小屋は京呂の和小屋とする。西棟に面し、賀茂鶴創業の地の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011818"},{"id":"00011816","register_sub_id":"101","register_pk":"210832","name":"賀茂鶴酒造一号蔵西棟","kana":"かもつるしゅぞういちごうぐらにしとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町708","lat":34.430414,"lng":132.745329,"geo_status":"db","era":"明治前期／大正期・昭和前期増築、平成28年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積528㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0227","desc":"賀茂鶴酒造創業の地に建つ。敷地の西側全長に渡り、北側で矩折に東に延びる。土蔵造二階建、切妻造で、赤瓦の桟瓦葺とする。南北棟部分は増築年代に応じて小屋材等が異なり、中央部分より南がトラスで、他は和小屋で組む。長大な立面で、地区の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011816"},{"id":"00011817","register_sub_id":"101","register_pk":"210833","name":"賀茂鶴酒造一号蔵東棟","kana":"かもつるしゅぞういちごうぐらひがしとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町708","lat":34.430376,"lng":132.745478,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積175㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0228","desc":"西棟に対面する。土蔵造二階建、切妻造で、屋根は赤瓦の桟瓦葺とする。桁行二三メートル、梁間七・六メートルの規模で、漆喰塗の壁が外部を大壁、内部を真壁とする。京呂の和小屋で、八角材を多用する。一階は土間で、内法が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011817"},{"id":"00011819","register_sub_id":"101","register_pk":"210835","name":"賀茂鶴酒造一号蔵南土蔵","kana":"かもつるしゅぞういちごうぐらみなみどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町708","lat":34.430183,"lng":132.745428,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積41㎡","structure_material":"土蔵造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0230","desc":"一号蔵北土蔵の南に西面して建つ。切妻造妻入で、屋根は桟瓦葺。桁行七・七メートル、梁間五・三メートルの規模を有し、北土蔵とほぼ共通する意匠であるが若干規模が大きい。小屋は和小屋を組む。北土蔵と並んで妻面を見せ、地域の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011819"},{"id":"00011803","register_sub_id":"101","register_pk":"210819","name":"賀茂鶴酒造研究室棟","kana":"かもつるしゅぞうけんきゅうしつとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町甲694-2他","lat":34.43046,"lng":132.746323,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0214","desc":"本社事務所の東、二号蔵の前面側に建つ。木造平屋建、寄棟造桟瓦葺で、桁行九・三メートル、梁間三・六メートルの規模。内部は東西二室に区画し、それぞれに起り破風をかける扉口を開く。外壁は下見板張。酒造業の近代化を示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011803"},{"id":"00011809","register_sub_id":"101","register_pk":"210825","name":"賀茂鶴酒造三号蔵","kana":"かもつるしゅぞうさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町574-1他","lat":34.431036,"lng":132.74645,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積918㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0220","desc":"二号蔵東西棟の背面西端に接して建つ。矩手に伸びる平面を有する規模の大きな二階建土蔵で、建築面積九一八平方メートル、屋根は切妻造桟瓦葺である。外壁は腰板張上部漆喰塗。一階は南北棟の北に通路を通すが、二階は全体を一室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011809"},{"id":"00011810","register_sub_id":"101","register_pk":"210826","name":"賀茂鶴酒造三号蔵煙突","kana":"かもつるしゅぞうさんごうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町574-1","lat":34.430792,"lng":132.746354,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"煉瓦造、面積3.6㎡","structure_material":"煉瓦造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0221","desc":"三号蔵の西に建ち、基部は釜場の建物内部に取り込まれている。基底部は一辺一・九メートル、高さは二三・四メートルで、イギリス積。最上部は蛇腹状に張り出す。上部には「賀茂鶴第三醸造場」の文字を補強鉄骨に貼り、地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011810"},{"id":"00011808","register_sub_id":"101","register_pk":"210824","name":"賀茂鶴酒造二号蔵煙突","kana":"かもつるしゅぞうにごうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町694-2","lat":34.430576,"lng":132.746274,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、面積2.1㎡","structure_material":"煉瓦造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0219","desc":"二号蔵東西棟の西に建つ。正方形平面の煉瓦造煙突で、基底部は一辺一・四メートル、高さは一四メートルで、イギリス積。最上部は蛇腹状に張り出し、アクセントとする。上部には「賀茂鶴」の文字を貼り、酒造の町西条らしい景観を作り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011808"},{"id":"00011804","register_sub_id":"101","register_pk":"210820","name":"賀茂鶴酒造二号蔵東西棟","kana":"かもつるしゅぞうにごうぐらとうざいとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町甲694-2他","lat":34.430623,"lng":132.746505,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積723㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0215","desc":"賀茂鶴酒造の中核をなす酒造蔵の一つ。東西棟の土蔵造二階建、平入で、屋根は桟瓦葺であるが、下屋の一部には本瓦を用いる。小屋組はトラス。正面外壁は基礎石の上に腰を海鼠壁とし、上部は白漆喰塗。格子窓を多く配し、特徴的な外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011804"},{"id":"00011805","register_sub_id":"101","register_pk":"210821","name":"賀茂鶴酒造二号蔵南北棟","kana":"かもつるしゅぞうにごうぐらなんぼくとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町574-1他","lat":34.430814,"lng":132.746679,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積625㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0216","desc":"二号蔵東西棟の背面東端に接して建つ。二階建土蔵で、桁行一五間、梁間六間の西面に三間の下屋を付す。外壁は基礎石上に腰海鼠壁、上部白漆喰塗。半間幅の窓を多く開き、それぞれ三本の塗籠格子を付す。扉口の周囲にも海鼠壁を廻し、大きな壁面を巧みにまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011805"},{"id":"00011807","register_sub_id":"101","register_pk":"210823","name":"賀茂鶴酒造二号蔵西井戸","kana":"かもつるしゅぞうにごうぐらにしいど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町694-2","lat":34.430591,"lng":132.746249,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、面積2.6㎡","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0218","desc":"二号蔵東西棟の南西角にほぼ接する位置にある井戸。現在は建屋の中に取り込まれている。上部の井戸桁は桁厚一九センチメートルの切石を積んだ六角平面で、高さは四〇センチメートル。酒造業に欠かせない施設で、二号蔵の主たる井戸としての機能を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011807"},{"id":"00011806","register_sub_id":"101","register_pk":"210822","name":"賀茂鶴酒造二号蔵東井戸","kana":"かもつるしゅぞうにごうぐらひがしいど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町694-2","lat":34.430443,"lng":132.74669,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、面積1.7㎡","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0217","desc":"二号蔵東西棟の南東方、敷地の南東隅に位置する。石造の井戸で、自然石を円形平面に積み、上部には切石井戸桁を設ける。酒造業にとって重要な意義を持つ施設で、酒造のまち西条の景観に欠くことができない要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011806"},{"id":"00011814","register_sub_id":"101","register_pk":"210830","name":"賀茂鶴酒造八号蔵煙突","kana":"かもつるしゅぞうはちごうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町577-1","lat":34.430902,"lng":132.74705,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、面積2.4㎡","structure_material":"煉瓦造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0225","desc":"二号蔵の東方に位置する八号蔵に附属する煉瓦造煙突。基底部は一辺一・六メートル、高さは一六・九メートルで、イギリス積。四周に補強鉄骨を巻き、梯子を設ける。最上部は蛇腹状に張り出す。上部には三面に「賀茂鶴」の文字を貼る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011814"},{"id":"00011802","register_sub_id":"101","register_pk":"210818","name":"賀茂鶴酒造本社事務所","kana":"かもつるしゅぞうほんしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町甲694-2他","lat":34.430522,"lng":132.746162,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0213","desc":"西条の中心地、旧本陣の隣地に建つ。木造二階建の洋館で、寄棟造妻入、桟瓦葺。内部は一階を事務室、二階を応接室等とする。基礎石二段の上に外壁下見板張とし、上下窓を密に配す。酒造業の近代性を表す建物として、地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011802"},{"id":"00011811","register_sub_id":"101","register_pk":"210827","name":"賀茂鶴酒造四号蔵","kana":"かもつるしゅぞうよんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町574-1他","lat":34.431428,"lng":132.746506,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積1099㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0222","desc":"敷地北端側、三号蔵の北側に建つ。矩手に伸びる平面で、南北棟の西面に三間の下屋が付く。外壁は基礎石上に腰海鼠壁、上部白漆喰塗。下屋北寄りには釜屋の煙出しが設けられる。長大な屋根面を見せ、酒造業の興隆を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011811"},{"id":"00011812","register_sub_id":"101","register_pk":"210828","name":"賀茂鶴酒造四号蔵井戸","kana":"かもつるしゅぞうよんごうぐらいど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町574-1","lat":34.431412,"lng":132.746316,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造、面積3.4㎡","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0223","desc":"四号蔵の西側外部に造られた井戸。上部は桁厚一九センチメートルの切石を六角形に積み、高さは三一センチメートル。地表より下は円形平面の石積とする。上部には井戸屋形をかける。酒造業に欠かせない施設であり、西条の景観を特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011812"},{"id":"00011813","register_sub_id":"101","register_pk":"210829","name":"賀茂鶴酒造四号蔵煙突","kana":"かもつるしゅぞうよんごうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町574-1","lat":34.43132,"lng":132.746327,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、面積3.2㎡","structure_material":"煉瓦造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0224","desc":"四号蔵の西にほぼ接して建つ。基底部は一辺一・八メートル、高さは二二メートルで、イギリス積。最上部は蛇腹状に張り出す。上部には「賀茂鶴第四醸造場」の文字を補強鉄骨に貼る。酒造業の煙突が立ち並ぶ西条を象徴するランドマークの一つとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011813"},{"id":"00011556","register_sub_id":"101","register_pk":"210491","name":"旧万寿之井酒造酒造蔵","kana":"きゅうますのいしゅぞうしゅぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県三次市三次町1144-1","lat":34.81712694,"lng":132.84634611,"geo_status":"db","era":"明治前期／昭和前期増改築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積298㎡、煙突付","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"34-0206","desc":"西城川の右岸に位置し、長大な立面を見せる酒造蔵。桁行三一メートル、梁間九・八メートルで、煙突が附属する。後補の南四間分は一階を検査室と培養室、二階を麹室とし、北側は一階を仕込蔵、二階を酒母蔵とする。河港として栄えていた三次の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011556"},{"id":"00011200","register_sub_id":"101","register_pk":"205307","name":"亀齢酒造一号蔵","kana":"きれいしゅぞういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町666","lat":34.430262,"lng":132.746494,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積642㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0193","desc":"中心敷地の東辺北寄りに南北棟を建て、さらに北辺に沿って東西棟を接続した矩折れの平面を持つ。南北棟は桁行三四メートルで土蔵造二階建、西面に下屋を付す。東西棟は桁行一七メートルの土蔵造二階建、西端を半切妻とする。外壁の白漆喰に赤瓦が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011200"},{"id":"00011201","register_sub_id":"101","register_pk":"205308","name":"亀齢酒造一号蔵煙突","kana":"きれいしゅぞういちごうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町666","lat":34.43008,"lng":132.746288,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ24m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0194","desc":"中心敷地の中央に建つ。煉瓦造の角型煙突で、基底部は一辺が一・九メートルとなる。高さは二四メートル。煉瓦は西条の煉瓦造煙突でよくみられるイギリス積とする。上部には蛇腹を付けて装飾を施す。街中に屹立する煙突の一本で、酒造りの町を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011201"},{"id":"00011203","register_sub_id":"101","register_pk":"205310","name":"亀齢酒造五号蔵","kana":"きれいしゅぞうごごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町693-1他","lat":34.430498,"lng":132.747004,"geo_status":"db","era":"大正期／昭和39頃増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積597㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0196","desc":"中心敷地から道を挟んで北東の敷地に構える土蔵。中央棟は東西棟の二階建で、東を切妻、西を入母屋造とする。中央棟を増築する形で、敷地いっぱいに北棟を並行して建てる。北棟は白漆喰の外壁に、腰には簓子下見を張って、街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011203"},{"id":"00011204","register_sub_id":"101","register_pk":"205311","name":"亀齢酒造七号蔵煙突","kana":"きれいしゅぞうななごうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和中","pref":"広島県","address":"広島県東広島市西条本町614-1","lat":34.431118,"lng":132.747856,"geo_status":"db","era":"昭和30頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"煉瓦造、高さ20m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0197","desc":"中心敷地から一五〇メートルほど北東の敷地に建つ七号蔵に附属する煙突。戦後の一時期、ここで醤油醸造が行われており、その施設の一部と伝わる。基部の直径が一・七メートル、高さ一九・五メートルで、西条地区に唯一残る円形の煉瓦造煙突となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011204"},{"id":"00011202","register_sub_id":"101","register_pk":"205309","name":"亀齢酒造門柱","kana":"きれいしゅぞうもんちゅう","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"広島県","address":"広島県東広島市西条本町666","lat":34.429832,"lng":132.74628,"geo_status":"db","era":"昭和30頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"石造、間口5.4m、脇柱付","structure_material":"石造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0195","desc":"洋館の東脇、敷地南辺の中央に開く門。洋館の曳家にあわせて立てたという。花崗岩製の門柱で、西側の柱には金属製表札を嵌める。一辺八二センチメートル、高さ二・五メートル。表面を瘤出しとして仕上げ、隅を唐戸面のように取って立体感を出し、表構えを作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011202"},{"id":"00011199","register_sub_id":"101","register_pk":"205306","name":"亀齢酒造洋館","kana":"きれいしゅぞうようかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町666","lat":34.429837,"lng":132.746192,"geo_status":"db","era":"大正期／昭和30頃移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0192","desc":"敷地の南辺西寄りに接道して建つ。北は事務所と接続する。屋根は半切妻の桟瓦葺とする。平屋建の洋風建物で、内部は一室の応接間として用いられる。天井は蜀江文様形の格天井とする。窓は上げ下げ窓とする。洋風建物を併設した西条の造酒屋の典型例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011199"},{"id":"00012041","register_sub_id":"101","register_pk":"210982","name":"小島屋土蔵","kana":"こじまやどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県東広島市西条本町708-2","lat":34.430131,"lng":132.745622,"geo_status":"db","era":"天保7年（1836）／平成28年改修","year":1836,"year_source":"db","year_min":1836,"year_max":1836,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"34 - 0242","desc":"白牡丹、賀茂鶴等造酒屋が集中する西条中心地に位置する。窓の鉄格子銘から年代が明らかで、地域に現存する土蔵の中では最古のもの。土蔵造二階建、置屋根形式の桟瓦葺で、外壁は基礎石上に竪板を高く張り、上部漆喰塗とする。西条の景観を特徴付ける蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012041"},{"id":"00015512","register_sub_id":"101","register_pk":"533527","name":"後藤鉱泉所店舗兼工場","kana":"ごとうこうせんしょてんぽけんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市向島町字則永755-2他","lat":34.40038611,"lng":133.204075,"geo_status":"db","era":"大正15年／昭和10年・同27年増築、同31年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階一部平屋建、瓦葺一部鉄板葺、建築面積321㎡","structure_material":"木造2階一部平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"34 - 0323","desc":"向島にあるラムネなどの飲料製造販売所。敷地西側は工場及び倉庫を配し、東側は通りに面して店舗を増築し、全体に複雑な屋根構成とする。店舗は建ちの高い外観で外壁モルタル塗に目地を切って石造風。工場に製造機器を残すなど町の賑わいを伝える店舗兼工場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015512"},{"id":"00011209","register_sub_id":"101","register_pk":"205316","name":"西條鶴醸造酒宝蔵煙突","kana":"さいじょうつるじょうぞうしゅほうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町706-1","lat":34.430139,"lng":132.745513,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ19m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0202","desc":"敷地中央、角屋の西側に位置する。方形の煉瓦造煙突で、基部の一辺一・七メートル、高さ一九メートル。醸造蔵の南に位置する釜場から煙道を介してこの煙突に排出される。醸造業が集中し、煙突が数多く残る西条の景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011209"},{"id":"00011208","register_sub_id":"101","register_pk":"205315","name":"西條鶴醸造酒宝蔵仕込蔵","kana":"さいじょうつるじょうぞうしゅほうぐらしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町707-2","lat":34.430407,"lng":132.745656,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積221㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0201","desc":"敷地背面寄りの酒宝蔵と呼ばれる一連の蔵のうち、北寄りに建つ。桁行一〇間梁間六間で、やや不整形の平面とする土蔵造赤瓦葺。小屋組はトラスで、東半の一部を吹き抜けとする。壁は漆喰塗で背面側は腰下見板張、内部は真壁とする。格子窓が並ぶ外壁が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011208"},{"id":"00011207","register_sub_id":"101","register_pk":"205314","name":"西條鶴醸造酒宝蔵醸造蔵","kana":"さいじょうつるじょうぞうしゅほうぐらじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町707-2","lat":34.430308,"lng":132.74563,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積153㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0200","desc":"敷地背面寄りの酒宝蔵と呼ばれる一連の蔵のうち、南寄りに建つ。桁行一〇間、梁間四間半で、土蔵造二階建、切妻造平入の赤瓦葺。壁は漆喰塗で外側を大壁、内部は真壁とする。小屋組はトラスで、東半のみ二階板床を張る。敷地の中で醸造機能の中核をなす建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011207"},{"id":"00011206","register_sub_id":"101","register_pk":"205313","name":"西條鶴醸造角屋","kana":"さいじょうつるじょうぞうつのや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町706-1","lat":34.430113,"lng":132.745618,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階一部3階建、スレート葺、建築面積85㎡、井戸付","structure_material":"木造2階一部3階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0199","desc":"店舗兼主屋の背面に接して建つ。一階は主に土間とし、二階に居室を配す。南寄りには望楼状の三階を設け、室内は洋風意匠でまとめる。内部に「天保井水」と称される井戸を備える。屋根周りもスレート葺とするなど、敷地内の意匠上のハイライトとなる建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011206"},{"id":"00011205","register_sub_id":"101","register_pk":"205312","name":"西條鶴醸造店舗兼主屋","kana":"さいじょうつるじょうぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町706-1","lat":34.42995,"lng":132.745596,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0198","desc":"南北に細長い敷地の南西端に接道して建つ店舗兼主屋。正面西側には跳ね上げ式の大戸を介して土間を通し、東側に居室五室を並べる。正面から二室目の四畳半を居室への上り口とし、背面側の八畳座敷には床廻りには銘木を用いるなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011205"},{"id":"00011210","register_sub_id":"101","register_pk":"205317","name":"山陽鶴酒造黒松一号蔵","kana":"さんようつるしゅぞうくろまついちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条岡町792他","lat":34.429624,"lng":132.740851,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積207㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0203","desc":"敷地の南寄りに建つ。切妻造平入の大規模な土蔵造二階建で、桁行六間、梁間五間の主体部に、西面と南面に下屋が取り付く。外壁は下見板張りで、小屋はトラス。屋根は桟瓦葺である。広大な赤瓦の屋根面と妻面で、西条の景観を形作る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011210"},{"id":"00011212","register_sub_id":"101","register_pk":"205319","name":"山陽鶴酒造黒松三号蔵","kana":"さんようつるしゅぞうくろまつさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条岡町795-8他","lat":34.429728,"lng":132.740858,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0205","desc":"黒松二号蔵の東側に、やや軸を振って建つ。桁行五間、梁間四間の二階建土蔵造で、全面に二階床を張るが、階段を設けず、二階には二号蔵から出入りする。外壁は下見板張、内壁は漆喰塗真壁とする。街路に面した下見板張りが往時の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011212"},{"id":"00011211","register_sub_id":"101","register_pk":"205318","name":"山陽鶴酒造黒松二号蔵","kana":"さんようつるしゅぞうくろまつにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条岡町792他","lat":34.429743,"lng":132.740758,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積179㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0204","desc":"黒松一号蔵の背面に妻を接して建つ。土蔵造二階建、桁行一〇間、梁間五間で、南北棟の長方形平面である。内部は南半のみ二階床を張り、北側は吹き抜けとする。小屋組はトラスで、陸梁と合掌材には丸太材を用いる。長大な屋根面が地区の景観を特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011211"},{"id":"00008576","register_sub_id":"101","register_pk":"134972","name":"三楽荘茶室","kana":"さんらくそうちゃしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町東城字上町345-1他","lat":34.89946482,"lng":133.27170569,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0109","desc":"離れ北西角に廊下を介して建つ。桁行四・一メートル梁間二・四メートル、木造平屋建、西面入母屋造桟瓦葺である。西半を二畳茶室として、茶室北面の西側に地袋、東側に棚を備える。東半は前室及び廊下とする。庭園に面する南・西面を大きく開放した近代茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008576"},{"id":"00008577","register_sub_id":"101","register_pk":"134973","name":"三楽荘土蔵","kana":"さんらくそうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県庄原市東城町東城字上町345-1他","lat":34.89931026,"lng":133.2715463,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0110","desc":"敷地西寄りに建ち、桁行六・九メートル梁間四・九メートル、土蔵造二階建、切妻造桟瓦葺である。内部は一階を土間、二階を居室とする。外部は漆喰塗で腰を竪板張とし、一階上部の水切り瓦と二階両妻の山型の水切り瓦が特徴的で、敷地背面の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008577"},{"id":"00008575","register_sub_id":"101","register_pk":"134971","name":"三楽荘離れ","kana":"さんらくそうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県庄原市東城町東城字上町345-1他","lat":34.89945758,"lng":133.27180471,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積124㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0108","desc":"主屋の北側に建ち前後に庭を配する。桁行一三メートル梁間九・九メートル、木造二階建、入母屋造桟瓦葺で、一階周囲の屋根を下屋とする。東面は二階に木瓜形の格子窓を穿ち、庭園に面する西面は開放的なつくりとする。内部意匠も優秀な接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008575"},{"id":"00008574","register_sub_id":"101","register_pk":"134970","name":"三楽荘本館","kana":"さんらくそうほんかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県庄原市東城町東城字上町345-1他","lat":34.89929577,"lng":133.27179988,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積282㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0107","desc":"角地に東を正面して建ち、桁行一八メートル梁間一七メートル、木造二階建。入母屋造桟瓦葺で、両妻に小破風を重ねる複雑な屋根をつくる。一階は正面に出格子をたて、二階は出桁造の軒まで黒漆喰で塗り込め、虫籠窓を穿つ。重厚で、風格のある大型町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008574"},{"id":"00008578","register_sub_id":"101","register_pk":"134974","name":"三楽荘門及び塀","kana":"さんらくそうもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町東城字上町345-1他","lat":34.89947207,"lng":133.27192305,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、延長13m","structure_material":"門 木造","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0111","desc":"敷地の東辺、離れ前面に建つ門と塀である。門は一間腕木門、切妻造桟瓦葺で、方立をたてて板戸を吊る。塀は、延長一三メートル、両下造桟瓦葺で、腰に幅広の欅板を横張し、上部を土壁とする。いずれも欅の良材が用いられ、格調のある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008578"},{"id":"00013650","register_sub_id":"101","register_pk":"505019","name":"酔心山根本店事務所","kana":"すいしんやまねほんてんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県三原市東町一丁目353-2","lat":34.40156944,"lng":133.09065833,"geo_status":"db","era":"明治35年／昭和5年増築・平成18年移築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階建、瓦葺、建築面積266㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0290","desc":"旧山陽道に北面して建つ二階建、切妻造平入、本瓦葺で、長大な間口の町家。一階は間口中央を戸口とし、西端部を格子戸とするほかは格子窓で、二階は虫篭窓を四箇所開ける。外壁は軒まで塗込めて黒漆喰塗で重厚に仕上げる。旧山陽道沿いの景観を形成する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013650"},{"id":"00013651","register_sub_id":"101","register_pk":"505020","name":"酔心山根本店土蔵","kana":"すいしんやまねほんてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市東町一丁目353-2","lat":34.40158889,"lng":133.0905,"geo_status":"db","era":"昭和5年／平成18年移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0291","desc":"事務所西脇に建つ南北棟で二階建、切妻造妻入、本瓦葺の土蔵。通りに面した北妻面の一・二階に鉄扉付の窓を穿ち、外壁は漆喰塗で鉢巻を廻し、腰を海鼠壁とする。内部は改修し、事務所の一部として使用する。事務所棟と一体で旧山陽道沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013651"},{"id":"00011825","register_sub_id":"101","register_pk":"210841","name":"白牡丹酒造延宝蔵井戸","kana":"はくぼたんしゅぞうえんぽうぐらいど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県東広島市西条本町709-1","lat":34.430241,"lng":132.745135,"geo_status":"db","era":"江戸中期／昭和中期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"石造、面積2.7㎡","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0236","desc":"南端棟の南東方に位置する。井戸本体は切石積六角平面の井戸桁を設ける。井戸桁の一辺は九七センチメートルの規模。井戸屋形は背面側を壁状に積み、正面には左右に二本柱を配し、石造屋根をかける。重厚な井戸屋形が、酒造業のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011825"},{"id":"00011826","register_sub_id":"101","register_pk":"210842","name":"白牡丹酒造延宝蔵煙突","kana":"はくぼたんしゅぞうえんぽうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町709-1","lat":34.430117,"lng":132.745106,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"煉瓦造、面積3.7㎡","structure_material":"煉瓦造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0237","desc":"南端蔵の東に建つ。基底部は一辺一・九メートル、高さは二五メートルで、イギリス積。最上部は蛇腹状に張り出す。上部には「ハクボタン」の文字を貼る。当地のレンガ蔵煙突の中でも高いもので、酒造で栄える当地を象徴する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011826"},{"id":"00011823","register_sub_id":"101","register_pk":"210839","name":"白牡丹酒造延宝蔵南端棟","kana":"はくぼたんしゅぞうえんぽうぐらなんたんとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県東広島市西条本町709","lat":34.430249,"lng":132.744995,"geo_status":"db","era":"江戸中期／江戸後期・昭和中期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、瓦葺、建築面積115㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0234","desc":"白牡丹延宝蔵の西側を画す。桁行一〇間、梁間三間、総二階建の土蔵造で、内部は一階を一室、二階を二室とする。小屋は登梁。街路側は石垣上に腰海鼠壁、上部白漆喰塗で、水切瓦を二列通して小窓を多く設ける。軒は塗籠で、特徴的な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011823"},{"id":"00011824","register_sub_id":"101","register_pk":"210840","name":"白牡丹酒造延宝蔵北端棟","kana":"はくぼたんしゅぞうえんぽうぐらほくたんとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県東広島市西条本町709","lat":34.430249,"lng":132.744995,"geo_status":"db","era":"明治前期／昭和34年増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積505㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0235","desc":"南端棟の北に続き、矩手に東に伸びる総二階建土蔵。南北棟部分一階は醸造場とし、二階には麹室などを配す。後補の東西棟部分も一階西寄りは醸造場とし、東寄りには上下階とも従業員の詰所、研究室などを配す。腰板張上部漆喰塗で、水切瓦を通す外観も印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011824"},{"id":"00011829","register_sub_id":"101","register_pk":"210845","name":"白牡丹酒造天保蔵井戸","kana":"はくぼたんしゅぞうてんぽうぐらいど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県東広島市西条本町879","lat":34.429596,"lng":132.745426,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、面積1.1㎡","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0240","desc":"仕込蔵の北方、主屋背面側に位置する。地表上は六角平面の切石積井戸桁で、一辺六六センチメートル。高さは五七センチメートル。かつては井戸屋形に覆われていたと伝えられる。正面には「天保井」の刻銘を持ち。酒造業を象徴する施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011829"},{"id":"00011830","register_sub_id":"101","register_pk":"210846","name":"白牡丹酒造天保蔵煙突","kana":"はくぼたんしゅぞうてんぽうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町879","lat":34.429504,"lng":132.745359,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"煉瓦造、面積2.8㎡","structure_material":"煉瓦造","registered":"2017.06.28(平成29.06.28)","register_no":"34-0241","desc":"仕込蔵の西北方に建つ。基底部は一辺一・七メートル、高さは二一メートルで、イギリス積。上部には「白牡丹」の文字を貼る。煙突が建ち並ぶ西条の中でもひときわ高い煙突で、酒造のまち西条の象徴として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011830"},{"id":"00011827","register_sub_id":"101","register_pk":"210843","name":"白牡丹酒造天保蔵仕込蔵","kana":"はくぼたんしゅぞうてんぽうぐらしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町879","lat":34.42931,"lng":132.745444,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積307㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0238","desc":"天保蔵の敷地中程に建つ仕込蔵。桁行二四メートル、梁間一三メートルの大規模な土蔵蔵二階建で、切妻造赤瓦葺。一階は土間で醸造タンクを並べ、二階は物置とする。三間毎に棟柱を建て、八角材の牛梁を支える。外壁は腰板張で、上部は軒まで塗籠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011827"},{"id":"00011828","register_sub_id":"101","register_pk":"210844","name":"白牡丹酒造天保蔵精米所","kana":"はくぼたんしゅぞうてんぽうぐらせいまいじょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条本町879","lat":34.429045,"lng":132.745156,"geo_status":"db","era":"明治後期／昭和36年頃増改築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積121㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0239","desc":"天保蔵南端部に建つ。切妻造桟瓦葺の二階建土蔵。桁行一五メートル、梁間五・七メートルの北側に下屋を付す。外壁は腰板張上部漆喰塗で、妻面には水切瓦を付す。小屋はトラスで、下屋北面は試験室にふさわしい腰板張上部ガラス窓として近代的な様相を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011828"},{"id":"00011172","register_sub_id":"101","register_pk":"205279","name":"福美人酒造一号蔵","kana":"ふくびじんしゅぞういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.43074,"lng":132.747759,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積694㎡","structure_material":"土蔵造2階一部平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0165","desc":"恵比寿蔵と呼ばれる中心敷地の主たる酒蔵。敷地中央北寄りに東西棟で建つ。桁行二〇メートル二階建土蔵の東棟と、桁行二三メートル二階建土蔵の西棟を平屋建の中央棟で繋いだ平面となる。造酒屋の中心建物として、計約四七メートルの桁行を測る大型の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011172"},{"id":"00011179","register_sub_id":"101","register_pk":"205286","name":"福美人酒造恵比寿蔵煙突","kana":"ふくびじんしゅぞうえびすぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430604,"lng":132.747886,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ24m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0172","desc":"恵比寿蔵と呼ばれる中心敷地の中央に建つ煉瓦造煙突。高さ約二四メートル。基部では一辺が約二メートルの角型で、最上部には蛇腹の装飾を施す。煉瓦をイギリス積で積み上げ、周囲の赤瓦と呼応して、土蔵の白壁に映える西条独特の造酒屋の景観を作り上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011179"},{"id":"00011181","register_sub_id":"101","register_pk":"205288","name":"福美人酒造三号蔵","kana":"ふくびじんしゅぞうさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条末広町28-1","lat":34.431642,"lng":132.748739,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積785㎡、井戸付","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0174","desc":"大黒蔵と呼ばれる敷地中央に東西棟で建つ。土蔵造二階建、切妻造桟瓦葺の屋根に赤瓦を葺く。南面に下屋を付し、井戸を備える。一階を土間とし、二階には後設の天井を張る。桁行五八メートルで、東西に二分した長大な平面を持つ。創業後の拡張の過程を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011181"},{"id":"00011184","register_sub_id":"101","register_pk":"205291","name":"福美人酒造三号蔵煙突","kana":"ふくびじんしゅぞうさんごうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条末広町28-1","lat":34.431582,"lng":132.748945,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、高さ27m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0177","desc":"大黒蔵と呼ばれる敷地の中央、三号蔵の南に附属して建つ。基部で一辺二・二メートルをはかる角型のイギリス積煉瓦造煙突で、高さは二七メートルになる。安芸津町で焼いた煉瓦を用いたという伝えがあり、西条に現存する煉瓦造煙突では最も高いものとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011184"},{"id":"00011171","register_sub_id":"101","register_pk":"205278","name":"福美人酒造事務所","kana":"ふくびじんしゅぞうじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430432,"lng":132.747739,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階一部平屋建、瓦葺、建築面積147㎡","structure_material":"木造2階一部平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0164","desc":"恵比寿蔵と呼ばれる中心となる敷地の南面出入口西脇に建つ。二階建で外壁を横板張とした洋風外観を持つ建物で、一階をカウンターと執務室を備えた事務室、二階を和室とする。大正期における西条の造酒屋では典型的となった出入口脇の洋風事務空間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011171"},{"id":"00011177","register_sub_id":"101","register_pk":"205284","name":"福美人酒造従業員寮","kana":"ふくびじんしゅぞうじゅうぎょういんりょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430642,"lng":132.747244,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0170","desc":"福神寮の西側に連続して建つ。東西棟の二階建とする。外壁は下見板張を基調とする。一階には畳敷の更衣室と土間、二階には従業員宿舎を置く。仕込み蔵に隣接して、季節労働者としての杜氏や蔵人らが起居する生活空間を残している点で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011177"},{"id":"00011175","register_sub_id":"101","register_pk":"205282","name":"福美人酒造昭和蔵","kana":"ふくびじんしゅぞうしょうわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430854,"lng":132.748041,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、スレート葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0168","desc":"恵比寿蔵と呼ばれる中心敷地の北東隅、背戸蔵から並んで東側に東西棟で建つ。平屋建で、小屋組はキングポストトラスを組む。切妻造の屋根を架ける。内部に大型のタンクを並べるため、窓を軒下の高い位置に開ける。背戸蔵と並んで通りの景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011175"},{"id":"00011173","register_sub_id":"101","register_pk":"205280","name":"福美人酒造背戸蔵","kana":"ふくびじんしゅぞうせとぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430828,"lng":132.747698,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建一部平屋建、スレート葺、建築面積209㎡","structure_material":"木造2階建一部平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0166","desc":"恵比寿蔵と呼ばれる中心敷地の北辺に構える土蔵で、一号蔵の背面に位置する。東西棟で、桁行二六メートル平屋建の東棟と、桁行一一メートル二階建の西棟からなる。一号蔵を拡張するように東棟が、続いて西棟が増築されたとみられ、敷地北側の街路景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011173"},{"id":"00011174","register_sub_id":"101","register_pk":"205281","name":"福美人酒造二号蔵","kana":"ふくびじんしゅぞうにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430612,"lng":132.748076,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積410㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0167","desc":"恵比寿蔵と呼ばれる中心敷地の東辺に構える土蔵。南北棟の土蔵造二階建で、屋根には赤瓦を葺く。小屋組は、和小屋の多い西条では希少な、キングポストトラスを組む。白漆喰を基調とした長大な外壁が造酒屋の建ち並ぶ西条の町並みの一画を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011174"},{"id":"00011178","register_sub_id":"101","register_pk":"205285","name":"福美人酒造瓶詰場","kana":"ふくびじんしゅぞうびんづめじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430445,"lng":132.747277,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0171","desc":"事務所の西側に箱詰場を介して建つ。東西棟の切妻造平屋建で、赤瓦を葺く。外壁は軒下まで塗込めて土蔵風に見せるが、窓ガラスを多用して、明るい作業空間を実現する。衛生に配慮して鏡天井を張り、内部は板壁とする。漆喰壁に窓が連続する外観が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011178"},{"id":"00011176","register_sub_id":"101","register_pk":"205283","name":"福美人酒造福神寮","kana":"ふくびじんしゅぞうふくじんりょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430684,"lng":132.747381,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0169","desc":"一号蔵の西側に並んで建ち、西には従業員寮が接続する。東西棟の二階建で、通りに面した北側には敷地形状にあわせた台形平面の下屋をかけて平屋建を張り出す。三叉路の突き当りに位置することから、黒色に塗られた下見板が白壁の土蔵群にアクセントをつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011176"},{"id":"00011180","register_sub_id":"101","register_pk":"205287","name":"福美人酒造門柱","kana":"ふくびじんしゅぞうもんちゅう","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町691","lat":34.430438,"lng":132.747902,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造、間口6.1m","structure_material":"石造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0173","desc":"恵比寿蔵と呼ばれる中心敷地の南辺中央に開く門。間口五・六メートルで、石柱二本を立てる。石柱は花崗岩製で、一辺八二センチメートルの方形で、高さ二・〇メートル。隅を面取し、表面には曲線の彫りを施して装飾とする。酒造所の表構えを成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011180"},{"id":"00011182","register_sub_id":"101","register_pk":"205289","name":"福美人酒造四号蔵北棟","kana":"ふくびじんしゅぞうよんごうぐらきたとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条末広町28-1","lat":34.431817,"lng":132.749145,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、スレート葺、建築面積406㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0175","desc":"大黒蔵と呼ばれる敷地の東側北寄りに南北棟で建つ。土蔵造二階建、切妻造。小屋はキングポストトラスを組む。西面には二重梁で下屋をかける。北面には板壁を張り、窓には漆喰塗込の格子を嵌めて堅固に見せる。敷地いっぱいに酒蔵が建ち並ぶ独特な景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011182"},{"id":"00011183","register_sub_id":"101","register_pk":"205290","name":"福美人酒造四号蔵南棟","kana":"ふくびじんしゅぞうよんごうぐらみなみとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県東広島市西条末広町28-1","lat":34.431555,"lng":132.749224,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、スレート葺、建築面積369㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0176","desc":"大黒蔵と呼ばれる敷地の東側南寄りに南北棟で建つ。土蔵造二階建、切妻造。小屋は登梁形式とする。桁行二八メートルで、西面には下屋を付す。現状では外壁に鉄板を張るが、もとは漆喰塗とみられる。窓には小庇を付け、外観上のアクセントとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011183"},{"id":"00015242","register_sub_id":"101","register_pk":"530666","name":"ヤマモトロックマシン（旧山本鉄工所）旧研究室棟","kana":"やまもとろっくましん(きゅうやまもとてっこうしょ)きゅうけんきゅうしつとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町東城字下町36他","lat":34.89456389,"lng":133.27258056,"geo_status":"db","era":"昭和前期／令和5年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"34 - 0311","desc":"事務所兼主屋の東に位置する旧研究開発棟。切妻造平入桟瓦葺東西棟で、側廻りに上部半円アーチの縦長窓を開け、外壁モルタル掻落仕上。内部中央は板敷の研究室で、北と南の土間通路沿いにそれぞれ戸口と窓を開ける。削岩機製造の起点となった洋風の研究室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015242"},{"id":"00015241","register_sub_id":"101","register_pk":"530665","name":"ヤマモトロックマシン（旧山本鉄工所）旧本社事務所兼主屋","kana":"やまもとろっくましん(きゅうやまもとてっこうしょ)きゅうほんしゃじむしょけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町東城字下町36他","lat":34.89456111,"lng":133.27239167,"geo_status":"db","era":"昭和前期／昭和中期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積259㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"34 - 0310","desc":"東城の新町筋に西面して建つ削岩機製造会社の事務所兼主屋。2階建片寄棟造桟瓦葺で外壁モルタル掻落仕上、腰を石貼。二階に出窓を張出し、丸窓など幾何学的意匠で飾る。正面側は事務所に改修し、背面側に和室の居住部を残す。独特な外観が通りの景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015241"},{"id":"00010994","register_sub_id":"101","register_pk":"208964","name":"ヤマモトロックマシン（旧山本鉄工所）仕上げ工場","kana":"やまもとろっくましん（きゅうやまもとてっこうしょ）しあげこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町東城字下町6-3他","lat":34.894754,"lng":133.273444,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積417㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"34 - 0158","desc":"第一工場の東方に並行して建つ。桁行三八メートルで、小屋にはクイーンポストトラスを架け、越屋根を設ける。南妻面には上部を欠円アーチ形とした窓を設け、東西面には上下窓を並べて洋風意匠とする。洋風意匠で採光を工夫した戦前期地方工場建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010994"},{"id":"00010997","register_sub_id":"101","register_pk":"208967","name":"ヤマモトロックマシン（旧山本鉄工所）自治寮家族棟","kana":"やまもとろっくましん（きゅうやまもとてっこうしょ）じちりょうかぞくとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町川西字新丁416-1他","lat":34.892973,"lng":133.27241,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造3階建、瓦葺、建築面積314㎡","structure_material":"木造3階建","registered":"2016.02.25(平成28.02.25)","register_no":"34-0161","desc":"工場群から道を挟んで南に自治寮施設群が残る。家族棟は西寄りに南北棟で建つ。木造三階建で、屋根を半切妻とし、ドーマー窓を載せて洋風外観とする。内部は片廊下とし一・二階を和室の居室、三階は一室の会議室とする。職住分離した近代産業社会の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010997"},{"id":"00010999","register_sub_id":"101","register_pk":"208969","name":"ヤマモトロックマシン（旧山本鉄工所）自治寮食堂・娯楽室棟","kana":"やまもとろっくましん（きゅうやまもとてっこうしょ）じちりょうしょくどう・ごらくしつとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町川西字新丁416-1他","lat":34.893209,"lng":133.272623,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積281㎡","structure_material":"木造2階一部平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"34-0163","desc":"家族棟と独身棟の間に建つ。木造二階建で南北棟の食堂及び娯楽室に、平屋建で東西棟の炊事場及び炊事夫部屋が附属する。一階食堂、二階娯楽室とも一室の大空間とし、プレス成型された鋼製の天井板を張る。戦前期における自治寮の生活の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010999"},{"id":"00010998","register_sub_id":"101","register_pk":"208968","name":"ヤマモトロックマシン（旧山本鉄工所）自治寮独身棟","kana":"やまもとろっくましん（きゅうやまもとてっこうしょ）じちりょうどくしんとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町川西字新丁416-1他","lat":34.892982,"lng":133.27299,"geo_status":"db","era":"昭和16頃","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積407㎡、地下室付","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"34-0162","desc":"敷地東側に南北棟で建つ。木造二階建で、屋根を半切妻とし、桁行五九メートルの長大な平面を持つ。西に片廊下を通し、東に押入付の一〇畳居室を並べる。廊下、居室とも開口を広くとる。戦中から高度成長期にかけての第二次産業を支えた職員住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010998"},{"id":"00010995","register_sub_id":"101","register_pk":"208965","name":"ヤマモトロックマシン（旧山本鉄工所）青年学校","kana":"やまもとろっくましん（きゅうやまもとてっこうしょ）せいねんがっこう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町川西字新丁426-4他","lat":34.894273,"lng":133.273377,"geo_status":"db","era":"昭和13頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積309㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"34-0159","desc":"敷地南寄りに建つ。木造二階建で、屋根は半切妻とする。一階を一室の倉庫、二階を学校として使った。二階は、中廊下を通して左右に三室ずつ並べ、四学年分の教室を設ける。製造現場で中心的な役割を果たした養成工に、教育を行っていたことを示す遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010995"},{"id":"00010992","register_sub_id":"101","register_pk":"208962","name":"ヤマモトロックマシン（旧山本鉄工所）第一工場","kana":"やまもとろっくましん（きゅうやまもとてっこうしょ）だいいちこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町東城字下町6-3他","lat":34.894911,"lng":133.273185,"geo_status":"db","era":"昭和9／昭和13改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積1421㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"34 - 0156","desc":"中国山地に開けた市街地に敷地を構える。削岩機製造で発展した。第一工場は中心となる木造建築。桁行七八メートルと長大で、採光のため梁間を三スパンに分けて中央を高め、さらに越屋根を設けて工夫する。効率的な作業空間の実現により、機能美を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010992"},{"id":"00010993","register_sub_id":"101","register_pk":"208963","name":"ヤマモトロックマシン（旧山本鉄工所）第二工場","kana":"やまもとろっくましん（きゅうやまもとてっこうしょ）だいにこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町東城字下町6-3他","lat":34.895345,"lng":133.27313,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積521㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"34 - 0157","desc":"第一工場の北方に直交して建つ。桁行約四四メートルで、小屋にはキングポストトラスを架け、越屋根を設ける。南面と両側面には上下窓を並べて採光する。外壁はモルタル仕上げとし、腰には洗出し仕上げを施す。第一工場とともに工場の中核をなす建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010993"},{"id":"00010996","register_sub_id":"101","register_pk":"208966","name":"ヤマモトロックマシン（旧山本鉄工所）便所棟","kana":"やまもとろっくましん（きゅうやまもとてっこうしょ）べんじょとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県庄原市東城町東城字下町6-3他","lat":34.895128,"lng":133.272981,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"34-0160","desc":"第一工場の西方に並行して建つ。従業員用の便所として建てられた。西に大便所、東に小便所と手洗いを並べる。耐寒のためガラス窓を二重にしたり、建設当初より水洗式としたりするなど、当時、先端の技術を集め、衛生的に配慮して建てられたことを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010996"},{"id":"00002093","register_sub_id":"101","register_pk":"103083","name":"小野田セメント山手倶楽部","kana":"おのだせめんとやまてくらぶ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県山陽小野田市大字小野田字小屋ノ尾6094","lat":33.98051959,"lng":131.18181204,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積305㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"35 － 0038","desc":"小野田セメントのゲストハウスで，４代社長笠井真三が欧州から持ち帰った型枠により製造したコンクリート・ブロックを以て築造。ブロック外面の仕上げを江戸切りとし，車寄と西面ベランダにトスカナ式の柱を配する。会社の製品見本を兼ねた記念的建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002093"},{"id":"00015384","register_sub_id":"101","register_pk":"532508","name":"旧案野酒場座敷","kana":"きゅうあんのさかばざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県山口市徳地島地字下土井ノ内272-2他","lat":34.16235278,"lng":131.70201389,"geo_status":"db","era":"明治前期／明治後期増築、昭和5年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"35 - 0134","desc":"主屋の南東に位置し、前庭を配する離座敷。２階建切妻造桟瓦葺で２階外壁を大壁とし軒まで塗込める。１階は続き間座敷を配し、西室は床を構えた座敷、東室は次の間で神棚を備え、天井板を矢筈状に張った凝ったつくり。土蔵造風の重厚な外観が特徴的な離座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015384"},{"id":"00015385","register_sub_id":"101","register_pk":"532509","name":"旧案野酒場酒造場","kana":"きゅうあんのさかばしゅぞうじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県山口市徳地島地字下土井ノ内272-2他","lat":34.16243889,"lng":131.70205278,"geo_status":"db","era":"明治前期／昭和5年頃増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺、建築面積457㎡","structure_material":"木造平屋一部2階建","registered":"2025.03.13(令和7.03.13)","register_no":"35 - 0135","desc":"主屋の東に位置し、酒の仕込など行う作業場。平屋建切妻造桟瓦葺で東端部を二階建とする。外壁漆喰塗仕上で腰を竪板張。内部１階は土間で和小屋を現し、かつて西を仕込場、麹室、東を搾り場や瓶洗場などに使用。桁行長大な酒造場で、酒づくりの歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015385"},{"id":"00015383","register_sub_id":"101","register_pk":"532507","name":"旧案野酒場店舗兼主屋","kana":"きゅうあんのさかばてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"山口県","address":"山口県山口市徳地島地字下土井ノ内272-2他","lat":34.16236944,"lng":131.70186667,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"35 - 0133","desc":"山間を流れる島地川西岸に位置する旧酒造業の店舗兼主屋。通りに西面して建つ２階建入母屋造妻入桟瓦葺で一階北に通路を通し、南に土間と和室、南西に洋室を配す。建ちの高い外観で、土間に酒の枡売用カウンターなどを残し、昭和戦後の酒場の賑わいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015383"},{"id":"00015386","register_sub_id":"101","register_pk":"532510","name":"旧案野酒場門及び塀","kana":"きゅうあんのさかばもんおよびへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県山口市徳地島地字下土井ノ内272-2","lat":34.16230556,"lng":131.701875,"geo_status":"db","era":"明治前期／昭和30年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、総延長9.9m","structure_material":"門 木造","registered":"2025.03.13(令和7.03.13)","register_no":"35 - 0136","desc":"主屋の南に位置する門及び塀。門は通りに西面する一間腕木門桟瓦葺で、両開きの板扉を建てる。塀は総延長9・9メートルで南寄りに潜戸を開ける。繰型付き持送で腕木を支え、屋根桟瓦葺。外壁漆喰塗で腰を簓子下見板張とし、旧家の屋敷構えを整える門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015386"},{"id":"00001294","register_sub_id":"101","register_pk":"102284","name":"旧野村家住宅主屋（山口ふるさと伝承総合センターまなび館）","kana":"きゅうのむらけじゅうたくしゅおく（やまぐちふるさとでんしょうそうごうせんたーまなびかん）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県山口市大字下竪小路12","lat":34.18362004,"lng":131.47855386,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造２階建，瓦葺，建築面積272㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"35 － 0025","desc":"造り酒屋の店舗兼住宅としてつくられた平入，土蔵造，２階建の間口の比較的に広い町家。通り土間に沿って２列３室計６室の部屋を並べた構成で，梁や差鴨居に太い松材を用いた重厚な意匠を持つ。現在は展示及び貸室として利用され市民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001294"},{"id":"00003135","register_sub_id":"101","register_pk":"104125","name":"大谷焼大西窯石垣","kana":"おおたにやきおおにしがまいしがき","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県鳴門市大麻町大谷字山田17地先","lat":34.16413359,"lng":134.53815093,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、延長50m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"36 － 0042","desc":"登窯と収納庫との間の斜面地を割石を用いたＬ字形の石積擁壁で２段に造成し，登窯への搬入および焼成品の搬出作業等のための平場を提供する。登窯に南方に位置し，登窯と収納庫とともに窯元の屋敷景観を構成する主要素のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003135"},{"id":"00003132","register_sub_id":"101","register_pk":"104122","name":"大谷焼大西窯登窯","kana":"おおたにやきおおにしがまのぼりがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県鳴門市大麻町大谷字山田16地先","lat":34.16423605,"lng":134.5381519,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"煉瓦造、奥行30m、幅9.0m","structure_material":"煉瓦造","registered":"2003.01.31(平成15.01.31)","register_no":"36 － 0039","desc":"大谷川右岸西方の山裾斜面に建つ。旧藩窯である元山窯登窯の北方に位置し，東端を焚口として奥行７．５ｍ，幅３ｍの房室を西方へ８房連ね全長約３０ｍ，幅９ｍ，高３ｍ規模とする。大谷焼登窯中北端の窯で，作業場等とともに窯元景観を構成する主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003132"},{"id":"00002982","register_sub_id":"101","register_pk":"103972","name":"大谷焼元山窯（旧納田丈五郎窯）","kana":"おおたにやきもとやまがま（きゅうのうだじょうごろうがま）","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県鳴門市大麻町大谷字山田甲18地先","lat":34.16395425,"lng":134.53768156,"geo_status":"db","era":"明治3／明治後期改造","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"煉瓦造、奥行27m、幅6.8m","structure_material":"煉瓦造","registered":"2002.08.21(平成14.08.21)","register_no":"36 － 0032","desc":"民陶開祖納田窯４代目丈五郎が建設し，明治後期田村基蔵が継承。大谷川右岸の西方山麓裾に位置する。５．６ｍ×２．８ｍ高２ｍ規模の室を８房連ね，最下段に焚き口，最上段に煙突を配し，全長約２７ｍとする登窯で，藍瓶等大型製陶の焼成窯形式を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002982"},{"id":"00003131","register_sub_id":"101","register_pk":"104121","name":"大谷焼森窯登窯","kana":"おおたにやきもりがまのぼりがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県鳴門市大麻町大谷字井利ノ肩22","lat":34.16090645,"lng":134.54150155,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、奥行40m、幅15m","structure_material":"煉瓦造","registered":"2003.01.31(平成15.01.31)","register_no":"36 － 0038","desc":"平地に傾斜地を造成して築かれた登窯。全長約２８ｍ規模で，奥行約７．４ｍ，幅約２．８ｍの房室を８房連ねる。吉野川支流の大谷川左岸沿いに位置し，道路に面する間口４０ｍ高１０ｍ規模の擁壁とともに類例のない景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003131"},{"id":"00001299","register_sub_id":"101","register_pk":"102289","name":"勢玉煙突","kana":"せいぎょくえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県徳島市福島1-4-9","lat":34.071953,"lng":134.56309976,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造，高さ10m","structure_material":"煉瓦造","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0021","desc":"勢玉創業時に建設された施設のひとつ。事務所の東北に位置する煉瓦造，方形断面の煙突。現在上部をモルタルで補修されており，比較的にせいが低いため町の中では目立たない存在となっているが，酒造業を営んだ家のシンボル的な施設として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001299"},{"id":"00001298","register_sub_id":"101","register_pk":"102288","name":"勢玉事務所棟","kana":"せいぎょくじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県徳島市福島1-4-9","lat":34.07190221,"lng":134.56298734,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造２階建，瓦葺，建築面積45㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0020","desc":"西側を走る道路に面して建つ２階建，平入の町家。酒蔵Ａの西に位置する。比較的に簡素な意匠になるが，第２次世界大戦による火災で数多くの木造建築が失われた福島地区の中で，現存する数少ない町家のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001298"},{"id":"00001296","register_sub_id":"101","register_pk":"102286","name":"勢玉酒蔵Ａ","kana":"せいぎょくしゅぞうえー","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県徳島市福島1-4-9","lat":34.07186424,"lng":134.56326704,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造２階建，瓦葺，建築面積188㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0018","desc":"株式会社勢玉は，地元出身の勢井種蔵が明治３５年に創業を始めた造り酒屋で，市内西方の市街地に位置する。酒蔵Ａは，東西に道路が走る敷地の東南隅にある。道路に面して妻をみせた形の比較的に規模の大きな土蔵で，ひときわ目立つ木造建築となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001296"},{"id":"00001297","register_sub_id":"101","register_pk":"102287","name":"勢玉酒蔵Ｂ","kana":"せいぎょくしゅぞうびー","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県徳島市福島1-4-9","lat":34.07197996,"lng":134.56332328,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積85㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0019","desc":"酒蔵Ａとともに創業時につくられたと伝える蔵で，酒蔵Ａの北に建つ。東側を走る道路に平側をみせて建ち，道路側は腰を押縁の板張りとするなど酒蔵Ａと意匠をあわせ，屋敷地側には作業空間として広い庇を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001297"},{"id":"00001301","register_sub_id":"101","register_pk":"102291","name":"高橋家住宅藍寝床（東納屋）","kana":"たかはしけじゅうたくあいねどこ（ひがしなや）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県徳島市南矢三町2-5-22","lat":34.082584,"lng":134.525406,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造２階建，瓦葺，建築面積121㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0023","desc":"主屋の南東，屋敷地の南東隅に建つ藍製造のために用いた建物。２階建，瓦葺の主体部の南と西に広い作業用の庇を設けた形。外壁に下見板を貼った建物で，一部の外壁に近年の改造がみられるが，藍製造農家の屋敷構えを示す主要建物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001301"},{"id":"00001303","register_sub_id":"101","register_pk":"102293","name":"高橋家住宅蔵","kana":"たかはしけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県徳島市南矢三町2-5-22","lat":34.08285897,"lng":134.52522531,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建，瓦葺，建築面積60㎡","structure_material":"土蔵造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0025","desc":"主屋の北方，屋敷地の北西隅境に建つ２階建，瓦葺，平入の長大な土蔵。藍の製造用に使われた土蔵で，石積みの高い基礎，小さく数の少ない窓，外側の腰下にある板張りなど外観の構成・意匠は西納屋と非常によく似ている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001303"},{"id":"00001302","register_sub_id":"101","register_pk":"102292","name":"高橋家住宅西納屋","kana":"たかはしけじゅうたくにしなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県徳島市南矢三町2-5-22","lat":34.082638,"lng":134.525146,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建，瓦葺，建築面積58㎡","structure_material":"土蔵造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"36 － 0024","desc":"主屋の南西，屋敷地の西側境に建つ。２階建，瓦葺の長大な土蔵造の建物で，藍製造に用いられた。石積みの基礎を高くつくり，小規模な窓をわずかに開くだけの外観に，藍製造施設としての特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001302"},{"id":"00013197","register_sub_id":"101","register_pk":"368421","name":"中和商店煙突","kana":"なかわしょうてんえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市池田町サラダ1755","lat":34.02820833,"lng":133.81047222,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"煉瓦造、高さ9.4m","structure_material":"煉瓦造","registered":"2019.12.05(令和1.12.05)","register_no":"36 － 0205","desc":"酒造蔵の東側に建つ、酒造蔵附属の煙突で、釜場の蒸気を排出する。高さ９・４メートル、基底部１・３メートル角の煉瓦造で、頂部に向けて窄まる。煉瓦はイギリス積で、山形鋼と丸鋼の枠で補強する。周囲から良く見え、地区のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013197"},{"id":"00013195","register_sub_id":"101","register_pk":"368419","name":"中和商店仕込蔵","kana":"なかわしょうてんしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県三好市池田町サラダ1756-2他","lat":34.02835833,"lng":133.81041944,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積282㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"36 － 0203","desc":"敷地北端に建ち、南面西半が酒造蔵と接する。木造平屋建、切妻造桟瓦葺で、規模が大きい。内部は一室で、コンクリートの土間にタンクが並ぶ。小屋組は丸太を水平や斜めに組み、方杖で固めた独特なもので、大空間を造りだす。醸造業に必要不可欠な施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013195"},{"id":"00013193","register_sub_id":"101","register_pk":"368417","name":"中和商店事務所","kana":"なかわしょうてんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市池田町サラダ1755他","lat":34.02811667,"lng":133.81006389,"geo_status":"db","era":"大正後期／昭和32年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階一部平屋建、スレート葺一部瓦葺、建築面積140㎡","structure_material":"木造2階一部平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"36 － 0201","desc":"池田町の杉尾通りに西面して建つ。事務所棟は木造二階建の北に、平屋建の南北棟が接続し、背面に住居棟が続く。外壁は正面一階をスクラッチタイル張、他はモルタル刷毛引仕上とする。内部は事務所棟が洋風、住居棟が和風で、戦後市街地の街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013193"},{"id":"00013194","register_sub_id":"101","register_pk":null,"name":"中和商店酒造蔵","kana":"なかわしょうてんしゅぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県三好市池田町サラダ1755他","lat":34.0282,"lng":133.81033611,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積499㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"36 － 0202","desc":"敷地中央、事務所の東側に建つ、木造二階建、切妻造桟瓦葺の酒造蔵。Ｌ字形平面の中央に貯蔵庫、南東隅に麹室を置く。さらに東側に下屋を下し洗場、釜場とし、西側に瓶詰室が附属し、事務所と接する。醸造業の基幹施設で、酒蔵の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013194"},{"id":"00013196","register_sub_id":"101","register_pk":"368420","name":"中和商店杜氏宿舎","kana":"なかわしょうてんとうじしゅくしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県三好市池田町サラダ1755他","lat":34.02817222,"lng":133.81054444,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"36 － 0204","desc":"敷地東端に建ち、西面南半が酒造蔵と接する杜氏の宿舎。木造二階建、切妻造桟瓦葺で、一階は南側にオクドを据えた土間のダイドコロを置き、北側に板間と畳敷四室を配す。土間の南西に便所を突出し、二階は板間と八畳の二室とする。酒蔵を構成する附属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013196"},{"id":"00008378","register_sub_id":"101","register_pk":"134020","name":"百年蔵煙突","kana":"ひゃくねんぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市池田町川崎宮ノ前156-6","lat":33.96675419,"lng":133.77467756,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造、高さ9.6m","structure_material":"煉瓦造","registered":"2010.09.10(平成22.09.10)","register_no":"36 － 0083","desc":"旧酒蔵の北に位置する煉瓦造の煙突。基礎部分で方０．９０ｍで、上方に逓減し、上端で方０．６４ｍとなる。高さ９．６ｍを測る。長手積とし、上部に二段に帯状の突起をつくる。「義士心」と銘柄名が記され、往時を偲ばせる。地域のシンボルとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008378"},{"id":"00008377","register_sub_id":"101","register_pk":"134019","name":"百年蔵旧酒蔵","kana":"ひゃくねんぐらきゅうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県三好市池田町川崎宮ノ前156-6","lat":33.96662717,"lng":133.77467756,"geo_status":"db","era":"大正11年／平成15年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積437㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"36 － 0082","desc":"吉野川と祖谷川が合流する川崎集落に所在する。桁行３０ｍ梁間９．９ｍの大規模な木造２階建で、北面に梁間４．９ｍの下屋を付ける。切妻造桟瓦葺。真壁造で漆喰仕上げとし、要所に窓を穿つ。内部は半間毎に柱をたて、貫を現さず、上昇感のある空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008377"},{"id":"00002987","register_sub_id":"101","register_pk":"103977","name":"本家松浦酒造場精米蔵","kana":"ほんけまつうらしゅぞうじょうせいまいぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県鳴門市大麻町池谷字大石10","lat":34.15900691,"lng":134.537506,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"36 － 0037","desc":"三棟構え酒蔵の北方，撫養街道を隔てた向かいの敷地に東西棟で建つ。桁行１０間，梁間２間規模，切妻造で，南面に１間半幅の下屋を差し出し，ともに本瓦葺とする。棟には越屋根を２箇所載せ，南面には漆喰鏝絵で「銘酒」「鳴門鯛精米所」を描く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002987"},{"id":"00002985","register_sub_id":"101","register_pk":"103975","name":"本家松浦酒造場仲酒蔵","kana":"ほんけまつうらしゅぞうじょうなかさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県鳴門市大麻町池谷字柳ノ本19","lat":34.15872995,"lng":134.53748148,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積223㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"36 － 0035","desc":"東酒蔵の西に並び建つ。桁行１１間，梁間５間規模，南北棟，切妻造，本瓦葺の２階建酒蔵で，南方は釜屋が取り付く。北妻面は，東酒蔵と同様，石土台，目板張の腰，漆喰大壁に小窓と水切りを配したつくりとし，撫養街道沿いに展開する酒蔵景観の主要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002985"},{"id":"00002983","register_sub_id":"101","register_pk":"103973","name":"本家松浦酒造場長屋門","kana":"ほんけまつうらしゅぞうじょうながやもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県鳴門市大麻町池谷字柳ノ本19","lat":34.158772,"lng":134.537704,"geo_status":"db","era":"江戸後期／明治後期改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積54㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"36 － 0033","desc":"撫養街道に北面して建つ。桁行４間半，梁行３間規模，東西棟，切妻造，本瓦葺の２階建で，西端を間口１間半の門とする。東妻面は上部を漆喰壁の大壁，階下を煉瓦壁とし，北東隅に雲形状の袖壁を付けるなど防火的なつくりとする点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002983"},{"id":"00002986","register_sub_id":"101","register_pk":"103976","name":"本家松浦酒造場西酒蔵","kana":"ほんけまつうらしゅぞうじょうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県鳴門市大麻町池谷字柳ノ本19","lat":34.1587166,"lng":134.53734482,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積248㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"36 － 0036","desc":"仲酒蔵の西に並び建つ。桁行１２間，梁間４間規模，南北棟，切妻造，本瓦葺の２階建とし，東桁面には下屋を差し掛けて仲酒蔵と連絡する。撫養街道からやや奥まって建つが，東酒蔵・仲酒蔵とともに「阿波の灘」と称された鳴門の酒蔵景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002986"},{"id":"00002984","register_sub_id":"101","register_pk":"103974","name":"本家松浦酒造場東酒蔵","kana":"ほんけまつうらしゅぞうじょうひがしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県鳴門市大麻町池谷字柳ノ本19","lat":34.15872169,"lng":134.53757304,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"36 － 0034","desc":"長屋門の西隣に位置する南北棟，切妻造，本瓦葺の２階建酒蔵で，東桁行面に下屋を差掛け南端に出入口を設ける。桁行８間，梁行６間規模で，砂岩系の土台石の上に建ち，腰は目板張，上部は漆喰大壁に鉄格子付き小窓と水切りを配した北妻面を撫養街道に見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002984"},{"id":"00005378","register_sub_id":"101","register_pk":"106366","name":"綾菊酒造（旧泉谷酒造場）仲酒蔵","kana":"あやきくしゅぞう（きゅういずみやしゅぞうじょう）なかさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡綾川町山田下字桜本3393-1","lat":34.22298879,"lng":133.94738562,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積318㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0304","desc":"綾川に平行する東西路に南妻面を見せて建つ。桁行３４ｍで，梁間７．５ｍの規模。南北棟で南方を入母屋造，桟瓦葺，棟を高めた北方を切妻造，本瓦葺とし，西面に下屋を差し掛け，小屋組はキングポストトラス。南妻に酒銘を漆喰で描くなど，周囲で目立つ存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005378"},{"id":"00005380","register_sub_id":"101","register_pk":"106368","name":"綾菊酒造（旧泉谷酒造場）離れ座敷","kana":"あやきくしゅぞう（きゅういずみやしゅぞうじょう）はなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡綾川町山田下字桜本3393-1","lat":34.22273765,"lng":133.94752818,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0306","desc":"東酒蔵の東南方に位置する。酒造場の接待用座敷で，事務所の東方に接続して東西棟で建つ。桁行２間半，梁行３間規模，寄棟造，桟瓦葺の木造平屋建で，南面の軒先を一段落とした錣葺とする。内部９畳の小規模施設であるが，酒造場の往時の様子を今に伝え貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005380"},{"id":"00005379","register_sub_id":"101","register_pk":"106367","name":"綾菊酒造（旧泉谷酒造場）東酒蔵","kana":"あやきくしゅぞう（きゅういずみやしゅぞうじょう）ひがしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県綾歌郡綾川町山田下字桜本3393-1","lat":34.22294521,"lng":133.94751476,"geo_status":"db","era":"明治後期／昭和初期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積472㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0305","desc":"仲酒蔵の東側に並列して南北棟で建つ。土蔵造２階建，切妻造，本瓦葺，妻入で，屋根東面を葺下ろして桁行２９ｍ，梁間１４．２ｍ規模とし，綾川寄りの北方に切妻造，桟瓦葺，落棟の酒蔵を延ばして，北面は縦板張，妻を漆喰塗とし，４つの小窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005379"},{"id":"00005381","register_sub_id":"101","register_pk":"106369","name":"綾菊酒造西酒蔵","kana":"あやきくしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"香川県","address":"香川県綾歌郡綾川町山田下字桜本3393-1","lat":34.22300466,"lng":133.94724214,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積474㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0307","desc":"仲酒蔵に並列して南北棟で建つ。桁行１６ｍ，梁間１３ｍ規模，切妻造，桟瓦葺の２階建酒蔵の南方に，棟を高くした桁行１９ｍ，梁間１４ｍ，切妻造，赤色桟瓦葺の酒蔵を繋げる。国道に面する西面南方部は２段の窓を設けた縦板張の外装をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005381"},{"id":"00000273","register_sub_id":"101","register_pk":"101263","name":"大川酒店","kana":"おおかわさけてん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市上吉田町三丁目１０５２－１、１０５３、１０５４","lat":34.2287467,"lng":133.78201641,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建，瓦葺，建築面積182㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"37 － 0008","desc":"道に面して建つ２階建て平入の酒造業を営んだ家の店舗兼主屋。２階部を黒漆喰塗りとして，正面に大正12年から製造している酒の銘柄を描く。２階の立ちが高く，屋根にむくりを付けた重厚な外観から，旧家を思わせる佇まいの酒店として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000273"},{"id":"00004039","register_sub_id":"101","register_pk":"105029","name":"大森醤油醸造所麹庫","kana":"おおもりしょうゆじょうぞうしょこうじこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3272-1","lat":34.5449189,"lng":134.28342796,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺及びスレート葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0204","desc":"醸造所敷地西南隅に位置し，石垣基礎の上に南北棟で建つ。桁行４間半梁間３間，切妻造，桟瓦葺，内部２室の麹室で，外周は２重壁に造り，室の天井は竹簀の子とする。外観は腰を縦板張，上部を白漆喰塗壁とし，天井懐にあたる高い位置に温度調整の窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004039"},{"id":"00004041","register_sub_id":"101","register_pk":"105031","name":"大森醤油醸造所仕込蔵","kana":"おおもりしょうゆじょうぞうしょしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3272-1","lat":34.544979,"lng":134.28367528,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、スレート葺、建築面積148㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0206","desc":"槽場の東方に南北棟，２棟並びで建つ。ともに桁行は５間半，梁間は西庫が４間，東庫が３間で，切妻造，スレート葺（もと瓦葺）とする。内部は中央に柱を建てて二重梁式とし，外観は腰縦板張で上部に横連子窓を配する。醸造所の核となる施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004041"},{"id":"00004040","register_sub_id":"101","register_pk":"105030","name":"大森醤油醸造所槽場及び操作場","kana":"おおもりしょうゆじょうぞうしょふなばおよびそうさば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3272-1","lat":34.54493066,"lng":134.28352234,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0205","desc":"麹庫の東方に位置し，東西棟で建つ。桁行５間梁間３間規模，切妻造，桟瓦葺で，北面に桁行５間梁間１間半のもと釜場を添わす。内部小屋組は登り梁式で，外観は腰縦板張とし，上部に「いわく窓」と呼ばれる横連子窓を配し，北面は湾曲した庇持送りを用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004040"},{"id":"00003612","register_sub_id":"101","register_pk":"104602","name":"かめびし赤門","kana":"かめびしあかもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22872507,"lng":134.40353069,"geo_status":"db","era":"江戸末期／昭和初期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、間口1.8m、土塀付属","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0169","desc":"敷地北辺のほぼ中央，十三号蔵の西妻面に接して建つ。間口４．５ｍ奥行５．７ｍ規模，入母屋造，本瓦葺の門で，西北端に北塀が取り付く。東面は十三号蔵により切られた形になっており，もとは天保１４年（１８４３）築の長屋門を改造したものとみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003612"},{"id":"00003603","register_sub_id":"101","register_pk":"104593","name":"かめびし一号蔵","kana":"かめびしいちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22833055,"lng":134.40319972,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0160","desc":"敷地の西南角に位置し，主屋の南方に南北棟で建つ。桁行１２ｍ梁間５ｍ規模，切妻造，本瓦葺の平屋建土蔵。もとは醤油原料の大豆貯蔵庫で，北西端に接して通用門を開く。腰は海鼠壁仕上げで，主屋，蔵と同様にべんがら色に塗り廻して独特の街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003603"},{"id":"00003614","register_sub_id":"101","register_pk":"104604","name":"かめびし五号蔵","kana":"かめびしごごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.22876462,"lng":134.40309748,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0171","desc":"西敷地の東北隅に位置し，圧搾場の北に接して東西棟で建つ。桁行１３．６ｍ梁間６ｍ規模，切妻造，本瓦葺の諸味蔵で，通りに面する東妻面と北面はモルタル壁をべんがら色に塗り，かめびし特有のべんがら色通り景観の演出に一役買っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003614"},{"id":"00003611","register_sub_id":"101","register_pk":"104601","name":"かめびし作業場","kana":"かめびしさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22857387,"lng":134.40348562,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造3階建、瓦葺、建築面積105㎡","structure_material":"木造3階建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0168","desc":"主屋（事務室・展示室）の東方，離れ座敷（資材置場）の北方に建つ。桁行１５ｍ梁間７ｍ規模，切妻造，桟瓦葺の木造２階建で，東端を３階建とする。もとは２階は醤油殺菌加熱場として使用され，３階部は空気抜きの役割をもったとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003611"},{"id":"00003605","register_sub_id":"101","register_pk":"104595","name":"かめびし三号蔵","kana":"かめびしさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22827517,"lng":134.40367576,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0162","desc":"仕込み部屋の東方，敷地の東南隅に位置し，敷地東辺に沿って南北棟で建つ。桁行１１ｍ梁間７．７ｍ規模，切妻蔵，本瓦葺の平屋建で，諸味貯蔵庫として使われているが，屋根に越屋根をあげていることから，もとは釜場であったとみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003605"},{"id":"00003604","register_sub_id":"101","register_pk":"104594","name":"かめびし仕込み部屋","kana":"かめびししこみべや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22831631,"lng":134.40338272,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0161","desc":"一号蔵の東方に位置し，敷地南辺に沿って東西棟で建つ。桁行２４ｍ梁間７．５ｍ規模，切妻造，桟瓦葺の平屋建土蔵で，内部には二重壁，中二階の麹室５部屋を設ける。温度調節用の小窓など，筵を用いた麹づくりのための造作が随所にみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003604"},{"id":"00003607","register_sub_id":"101","register_pk":"104597","name":"かめびし十一号蔵","kana":"かめびしじゅういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22858605,"lng":134.40368427,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0164","desc":"十号蔵の北方に位置し，敷地東辺に沿って南北棟で建つ。桁行９．８ｍ梁間５．２ｍ規模，切妻造，本瓦葺の平屋建で，岡田家の記録にある文化４年（１８０７）５月上棟の「二の倉」に比定されている。かめびし創業期の歴史を伝える醤油蔵のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003607"},{"id":"00003606","register_sub_id":"101","register_pk":"104596","name":"かめびし十号蔵","kana":"かめびしじゅうごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22854377,"lng":134.403687,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0163","desc":"三号蔵の北方，もと離れ座敷（資材置場）の東方に位置し，敷地東辺のほぼ中央に東西棟で建つ。桁行１１．５ｍ梁間６．２ｍ規模，切妻造，本瓦葺の平屋建で，諸味貯蔵庫として使われているが，内部は天井が高く，もとは醤油醸造蔵とみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003606"},{"id":"00003609","register_sub_id":"101","register_pk":"104599","name":"かめびし十三号蔵","kana":"かめびしじゅうさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22869814,"lng":134.40365283,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0166","desc":"十二号蔵の北西方に位置し，敷地北辺の東寄りに東西棟で建つ。桁行１０ｍ梁間５ｍ規模，切妻造，本瓦葺の平屋建で，屋根に越屋根を載せる。腰を海鼠壁，上部をべんがら色に塗り，主屋前の通りから北へ廻り込む通り景観の端部を納める役割を果たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003609"},{"id":"00003608","register_sub_id":"101","register_pk":"104598","name":"かめびし十二号蔵","kana":"かめびしじゅうにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.2286384,"lng":134.40368665,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0165","desc":"敷地東辺の北寄りに位置し，十一号蔵の北妻面に接して南北棟で建つ。桁行７．４ｍ梁間６ｍ規模で，東側屋根面が長い招き造としている点に特徴がある。外装はもと焼杉の縦板張で，東桁行面に水切瓦を付けて変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003608"},{"id":"00003610","register_sub_id":"101","register_pk":"104600","name":"かめびし十四号蔵","kana":"かめびしじゅうよんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22843042,"lng":134.40368772,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0167","desc":"三号蔵と十号蔵の間に位置し，敷地東辺に沿って南北棟で建つ。桁行９．８ｍ梁間５．２ｍ規模，切妻造，本瓦葺の平屋建で，岡田家の記録にある享和２年（１８０１）４月上棟の「五間倉」に比定されている。かめびし創業期の歴史を伝える醤油蔵のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003610"},{"id":"00003616","register_sub_id":"101","register_pk":"104606","name":"かめびし七号蔵","kana":"かめびしななごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.2288019,"lng":134.402786,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、鉄板葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0173","desc":"西敷地の北西隅に位置し，西敷地北辺に沿って東西棟で建つ。桁行１６ｍ梁間１０．２ｍ規模，切妻造，鉄板葺の平屋建で，通り沿いの北面上部には５つの窓を開ける。年代ものの諸味貯蔵庫として使用され，内部には１６個の丸桶と３個の角桶を収容する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003616"},{"id":"00003617","register_sub_id":"101","register_pk":"104607","name":"かめびし八号蔵","kana":"かめびしはちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.22867117,"lng":134.40272572,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0174","desc":"西敷地の西辺沿いに位置する。花崗石基礎に建つ南北棟，切妻造，本瓦葺，桁行２０．８ｍ梁間６．８ｍの比較的長大な諸味蔵で，内部には２０個のコンクリート製内側板張の角桶を据える。七号蔵とともに西敷地における醤油醸造施設の中核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003617"},{"id":"00002999","register_sub_id":"101","register_pk":"103989","name":"川鶴酒造鶴鳴舘（旧瓶詰蔵）","kana":"かわつるしゅぞうかくめいかん（きゅうびんづめぐら）","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町1032-1","lat":34.126812,"lng":133.708649,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0124","desc":"明治蔵の西南方に位置し，東西棟で建つ。桁行１４ｍ，梁間１０ｍ規模，切妻造，桟瓦葺の平屋建で，北面中央に大戸口を，南面には３尺角の小窓を４箇所開ける。南側敷地南辺における醸造所景観の主要素になる。現在はコンサート会場等として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002999"},{"id":"00002995","register_sub_id":"101","register_pk":"103985","name":"川鶴酒造麹蔵","kana":"かわつるしゅぞうこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町836","lat":34.1276995,"lng":133.70827767,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、スレート葺、建築面積180㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0120","desc":"西酒蔵の東方に同じ軒高９ｍ，南北棟で並び建つ。桁行２０ｍ，梁間９ｍ規模，切妻造２階建で，２階に麹室を造り，現在も麹室として利用されている。北妻面は西酒蔵と一体となり，醸造場北面の景観を構成する上で欠くことのできない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002995"},{"id":"00002994","register_sub_id":"101","register_pk":"103984","name":"川鶴酒造西酒蔵","kana":"かわつるしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町836","lat":34.127789,"lng":133.708221,"geo_status":"db","era":"大正7／昭和10頃増築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積400㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0119","desc":"財田川に並行する阿波街道の北側敷地に南北棟で建つ。北方は仕込蔵で桁行１３間と規模が大きく，地棟墨書から年代が知られ，糟場となる南方は室戸台風後の再建になる。規則的に小窓を配した長大な西桁行面は観音寺市街方面からの格好のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002994"},{"id":"00002996","register_sub_id":"101","register_pk":"103986","name":"川鶴酒造濾過蔵","kana":"かわつるしゅぞうろかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町836","lat":34.12757875,"lng":133.70805912,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、スレート葺、建築面積308㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0121","desc":"麹蔵の東方に位置し，麹室とは棟を直交させた東西棟で建つ。桁行２２ｍ，梁間１４ｍ規模，切妻造２階建で，麹蔵と軒高を揃える。北面は腰を杉板張，上部を漆喰壁とし，小庇付きと鉄戸付きの小窓を２段に配置する。醸造所北面を構成する主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002996"},{"id":"00004655","register_sub_id":"101","register_pk":"105645","name":"キッコ石石井家住宅醤油蔵","kana":"きっこいしいしいけじゅうたくしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲262","lat":34.47624914,"lng":134.32176921,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積219㎡、井戸及び洗い場付","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0247","desc":"住宅屋敷地の南方，石垣擁壁下に位置する。桁行１４ｍ梁間１０ｍ規模，南北棟，切妻造，桟瓦葺の諸味蔵の東に，梁間６ｍで東面に下屋庇を差し掛けた醤油蔵を並べる。東面下屋中央部には石造井戸と洗い場が付属する。醤油醸造場の中心となる施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004655"},{"id":"00004654","register_sub_id":"101","register_pk":"105644","name":"キッコ石石井家住宅納屋","kana":"きっこいしいしいけじゅうたくなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲255","lat":34.47629993,"lng":134.321671,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0246","desc":"土蔵下から南へ下る小路に東妻面を見せて建つ。石積基礎に建つ東西棟，切妻造，桟瓦葺，妻入の木造平屋建で，平面規模は桁行２間半梁間２間。外壁は土壁を表した素朴な建物であるが，屋敷地南方の醤油醸造場敷地の一画を構成する要素になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004654"},{"id":"00010358","register_sub_id":"101","register_pk":"199130","name":"旧鎌田醤油大門","kana":"きゅうかまだしょうゆおおもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県坂出市本町1-3542-2","lat":34.314901,"lng":133.853626,"geo_status":"db","era":"明治前期／昭和30年頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0398","desc":"敷地東に門を開く。桁行三間梁間三間、切妻造本瓦葺で、棟通りよりやや前寄りに五平の柱を立てて門口とする。両開きの大扉及び両脇の片開潜戸は八双や乳金物、四葉金物で豪壮に飾る。長屋門風の構えだが、両側面を開放とし、小屋組を表すなど特異な形式の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010358"},{"id":"00010357","register_sub_id":"101","register_pk":"199129","name":"旧鎌田醤油本店","kana":"きゅうかまだしょうゆほんみせ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県坂出市本町1-3541-7他","lat":34.315046,"lng":133.853433,"geo_status":"db","era":"江戸末期／平成16年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積211㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0397","desc":"商店街の通りに北面する醤油商本店。建ちの高い二階建で入母屋造本瓦葺とし、背面に切妻造の屋根を突出す。表側外壁は大壁黒漆喰塗で格子窓を並べる。一階は中央が幅二間の通り土間で西をミセとし、二階には接客用の座敷を設ける。近世商家の佇まいを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010357"},{"id":"00002835","register_sub_id":"101","register_pk":"103825","name":"京宝亭佃煮販売処店舗（旧黒島伝九郎醤油醸造場醤油蔵）","kana":"きょうほうていつくだにはんばいどころてんぽ（きゅうくろしまでんくろうしょうゆじょうぞうじょうしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2126","lat":34.46468,"lng":134.318512,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造平屋建、杉皮及びスレート葺、建築面積110㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0103","desc":"小豆島内海湾沿いに南北に走る主要地方道坂手港線の浜側に南北棟で東面して建つ。もと「伝九郎」醤油醸造場の醤油蔵で，昭和２３年から佃煮製造所となり，現在は桁行１１ｍ，梁間１０ｍ規模に切縮められて佃煮販売所の店舗として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002835"},{"id":"00002836","register_sub_id":"101","register_pk":"103826","name":"京宝亭佃煮販売処西棟（旧黒島伝九郎醤油醸造場醤油蔵）","kana":"きょうほうていつくだにはんばいどころにしとう（きゅうくろしまでんくろうしょうゆじょうぞうじょうしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2126","lat":34.46471,"lng":134.318375,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積133㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0104","desc":"販売処店舗の西方浜側に東西棟で建つ。桁行１４．８ｍ，梁間９ｍ規模，桟瓦葺，切妻造の平屋建土蔵で，花崗石の基礎に建ち，屋根に煙出しの越屋根を載せる。店舗棟とともに佃煮製造草創期ゆかりの建造物で，小豆島「醤の里」の景観形成要素のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002836"},{"id":"00004436","register_sub_id":"101","register_pk":"105426","name":"金大醤油醤油蔵","kana":"きんだいしょうゆしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲833","lat":34.47645204,"lng":134.319244,"geo_status":"db","era":"昭和2／昭和9増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺一部スレート葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0227","desc":"高さの異なる切妻造，平屋建を２棟並べた形式で，主屋西側に近接して建つ。低い部分が当初で，鋸屋根風の部分は増築。諸味蔵との取合いは下屋で処理している。複雑な外観であるが，桟瓦葺，縦板壁で統一されており，醸造施設らしい景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004436"},{"id":"00004437","register_sub_id":"101","register_pk":"105427","name":"金大醤油諸味蔵","kana":"きんだいしょうゆもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲833","lat":34.47646859,"lng":134.31906504,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積99㎡","structure_material":"土蔵造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0228","desc":"敷地西側にあり，細長い切妻造，平屋建を２棟並べた形式である。北側は桁行２２ｍ，南側は増築部でひとまわり小さい。街路に面した北側は，壁面上半に大振りな開口部を規則的に並べる。桟瓦葺，縦板壁で統一されており，醸造施設の景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004437"},{"id":"00003139","register_sub_id":"101","register_pk":"104129","name":"金両北諸味蔵","kana":"きんりょうきたもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.47697266,"lng":134.318039,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積777㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0132","desc":"内海湾馬木港の東方，馬木川左岸南方の台形状敷地の北西隅に東西棟で建つ。桁行８０ｍ規模，切妻造，桟瓦葺の醤油蔵で，高い腰を板張り，上部の窓部を漆喰塗とした長大な北面を馬木川沿いの道路に見せる。敷地北半を占める醤油醸造部の中心的建造物になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003139"},{"id":"00003140","register_sub_id":"101","register_pk":"104130","name":"金両醤油蔵","kana":"きんりょうしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.476852,"lng":134.318268,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積217㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0133","desc":"北諸味蔵の東半の南方に並び建つ。桁行２２ｍ規模，東西棟，切妻造，桟瓦葺の平屋建で，棟のほぼ全長に亘って越屋根をあげている点に特徴がある。小屋はキングポストトラスとする。もと麹原料混合場及び機械場で，西半を醤油販売処として活用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003140"},{"id":"00004027","register_sub_id":"101","register_pk":"105017","name":"香龍北川家住宅酒蔵","kana":"こうりゅうきたがわけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県高松市円座町字永井979-1","lat":34.28922084,"lng":134.01388654,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積491㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0192","desc":"主屋の背後に位置し，東西棟で建つ。桁行２０間梁間６間規模，切妻造，桟瓦葺，平入の仕込蔵の南面西寄に，桁行７間梁間３間，東西棟，切妻造，桟瓦葺の麹室を添わす。酒造場の核となる施設で，仕込蔵の２階の一部には酒母造場を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004027"},{"id":"00002840","register_sub_id":"101","register_pk":"103830","name":"左海醤油工業醤油蔵","kana":"さかいしょうゆこうぎょうしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2121-1","lat":34.46464564,"lng":134.31897426,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積277㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0108","desc":"左海醤油丘工場の中核的施設になり，主要地方道の東側，道路に沿って南北棟で建つ。桁行１７ｍ，梁間１１ｍ規模，桟瓦葺，切妻造の南に桁行９ｍ，梁行１０ｍ規模の切妻造を繋げる。道路を隔てたもと浜工場の醤油蔵と向き合い醤油醸造盛期の活況を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002840"},{"id":"00002841","register_sub_id":"101","register_pk":"103831","name":"左海醤油工業水圧式蓄量機小屋","kana":"さかいしょうゆこうぎょうすいあつしきちくりょうきごや","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2121-1","lat":34.46503313,"lng":134.31870758,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、杉皮葺、建築面積5.8㎡、水圧式畜量機付","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0109","desc":"醤油蔵の北方，主要地方道沿いに南北棟で建つ。桁行及び梁間２．４ｍ規模の切妻造の小屋で，コンクリート製５段の井籠組を外周柱のガイドレールに沿って上下させる蓄量機を内部に装置する。諸味圧搾機の動力装置で，醤油醸造の近代化を物語る遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002841"},{"id":"00001735","register_sub_id":"101","register_pk":"102725","name":"四国村土佐の楮蒸し小屋","kana":"しこくむらとさのこうぞむしごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県高松市屋島中町126-2","lat":34.345791,"lng":134.10993779,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、茅葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0035","desc":"もと高知県高岡郡檮原町越智面に所在した。土佐紙の原料である楮や三椏を蒸すための小屋。内部に石で窯を築き、蓋として釜にかぶせる大桶を上げ下げする装置をもつ。寄棟造、茅葺で、外壁をも茅で葺いている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001735"},{"id":"00003147","register_sub_id":"101","register_pk":"104137","name":"島醸諸味蔵","kana":"しまじょうもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町西村字久徳甲250-2","lat":34.47659852,"lng":134.2913867,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積922㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0140","desc":"内海湾の北方，清水海岸沿いに走る国道に面する工場地の西方に建つ。もと丸金醤油清水工場の醤油蔵で，桁行９４ｍ規模の南北棟，切妻造，桟瓦葺とする。内部は諸味桶を４列に並べる。「古式本醸造諸味蔵」の看板を掲げ，他の近代的な醸造施設と対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003147"},{"id":"00003137","register_sub_id":"101","register_pk":"104127","name":"正金醤油西諸味蔵","kana":"しょうきんしょうゆにしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町石井甲230-1","lat":34.476292,"lng":134.320389,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積215㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0130","desc":"内海湾馬木港東方に位置し，馬木川に直交する道路に南妻面を見せて建つ。もと金両醤油創業時の醤油蔵で，桁行１０間梁間５間規模とし内部に４列３２個の諸味桶を並べる。南北棟，切妻造，桟瓦葺の平屋建で，南面を杉板張りとして小路の街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003137"},{"id":"00003138","register_sub_id":"101","register_pk":"104128","name":"正金醤油東諸味蔵","kana":"しょうきんしょうゆひがしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町石井甲230-1","lat":34.47641,"lng":134.320633,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0131","desc":"西諸味蔵の東方，敷地東辺沿い道路に東妻面を見せて建つ。西諸味蔵と同様，もと金両醤油創業時の醤油蔵で，規模はやや小さく内部には４列２４個の諸味桶を容れる。東西棟，切妻造，桟瓦葺の平屋建で，杉板張りの東妻面に敷地形状に合わせた下屋を張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003138"},{"id":"00004671","register_sub_id":"101","register_pk":"105661","name":"正金藤井家住宅物置","kana":"しょうきんふじいけじゅうたくものおき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲813-1","lat":34.47533086,"lng":134.32070828,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0263","desc":"主屋の南方に位置し，敷地東南隅に東西棟で建つ。切妻造，桟瓦葺の木造平屋建で，南北両面に下屋を差し掛け，南下屋の東端を隅切りとする。外部は腰焼杉縦板張，上部白漆喰塗で，境に水切を入れる。白壁部に穿たれた円形小窓が特徴ある外観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004671"},{"id":"00003328","register_sub_id":"101","register_pk":"104318","name":"小豆島馬越醤油煙突","kana":"しょうどしまうまごえしょうゆえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.521538,"lng":134.210892,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造、高さ15m","structure_material":"煉瓦造","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0155","desc":"敷地のほぼ中央，製成場の北にある。角形平面で煉瓦造イギリス積の煙突で，頂部は上下二段に蛇腹を廻し，その間に屋号を飾る。高１５ｍの規模を有し，周辺の眺望上，際だった存在となっており，また製成場と連絡した近代醸造施設の景観もつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003328"},{"id":"00003325","register_sub_id":"101","register_pk":"104315","name":"小豆島馬越醤油北諸味蔵","kana":"しょうどしまうまごえしょうゆきたもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.521984,"lng":134.210983,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積368㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0152","desc":"海岸寄りに建ち，醤油醸造の創業期の建築と考えられている。東西に長大な木造・平屋建，切妻造・桟瓦葺で西端部を棟違いにする。側廻りは腰まで切石積で，真壁造の外壁を縦板で覆う。内部は棟通りに中柱を立て，水平梁と登梁を組み，整然と木桶を配している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003325"},{"id":"00003324","register_sub_id":"101","register_pk":"104314","name":"小豆島馬越醤油製成場","kana":"しょうどしまうまごえしょうゆせいせいじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.52133257,"lng":134.2108742,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積400㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0151","desc":"醸造会社の設立時に建てられた中心施設。東西に長大な木造・平屋建で，切妻造・桟瓦葺の中央部を高く立ち上げ，南・北・西の各面に下屋を廻す。内部は柱や梁などに瓜剥状の大径材を用いて高大な空間をつくりだしている。近代における大規模な醸造施設の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003324"},{"id":"00003327","register_sub_id":"101","register_pk":"104317","name":"小豆島馬越醤油道具蔵","kana":"しょうどしまうまごえしょうゆどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.521564,"lng":134.210464,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積42㎡","structure_material":"土蔵造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0154","desc":"製成場の北西，海岸寄りに建つ。土蔵造・平屋建で，東西棟の切妻造・本瓦葺で，北側面西端に出入口を設け，庇をつける。漆喰塗の外壁は縦板張で覆う。北諸味蔵と同じく醤油醸造の創業期の建築と考えられており，江戸末期の醸造施設の様相を伝えるものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003327"},{"id":"00003326","register_sub_id":"101","register_pk":"104316","name":"小豆島馬越醤油南諸味蔵","kana":"しょうどしまうまごえしょうゆみなみもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.52189041,"lng":134.21099686,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積300㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0153","desc":"北諸味蔵の南に並んで建ち，記録から明治３４年上棟と判明する。東西に長大な木造・平屋建，切妻造・桟瓦葺で，北諸味蔵より桁行規模は少し短い。側廻りは真壁造の外壁を縦板で覆う。架構は棟通りの中柱や各梁などに大径材を用い，伝統的手法を踏襲している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003326"},{"id":"00004641","register_sub_id":"101","register_pk":"105631","name":"小豆島食品（旧岡醤油醸造所）事務所","kana":"しょうどしましょくひん（きゅうおかしょうゆじょうぞうしょ）じむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町草壁本町字下川西493-1","lat":34.4810489,"lng":134.30409366,"geo_status":"db","era":"明治中期／昭和2増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺及びスレート葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0233","desc":"醤油佃煮蔵の東方，別当川沿いに南北棟で建つ。桁行２間半梁間２間規模，片入母屋造，桟瓦葺の木造平屋建で，西面に下屋を差し掛け，北面には切妻造，スレート葺の木造平屋建を増築。もと蔵人部屋で，現在は事務所として使用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004641"},{"id":"00004640","register_sub_id":"101","register_pk":"105630","name":"小豆島食品（旧岡醤油醸造所）醤油佃煮蔵","kana":"しょうどしましょくひん（きゅうおかしょうゆじょうぞうしょ）しょうゆつくだにぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町草壁本町字下川西493-1","lat":34.481075,"lng":134.303909,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積401㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0232","desc":"内海湾に注ぐ別当川右岸に接する敷地の西方に東西棟，２棟並びで建つ。北棟は桁行２５ｍ梁間９ｍ規模，南棟は桁行２０ｍ梁間８ｍ規模，ともに切妻造，桟瓦葺で，北棟には棟中央に煙出しの越屋根を上げる。醤油醸造所の中心的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004640"},{"id":"00004430","register_sub_id":"101","register_pk":"105420","name":"高橋商店北醤油蔵","kana":"たかはししょうてんきたしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47926275,"lng":134.31538656,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積218㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0221","desc":"桁行２２ｍの大規模な醸造蔵で，主屋の後方にある。木造平屋建，外壁は漆喰塗を縦板で覆い，整然と小窓を並べる。屋根は切妻造，桟瓦葺で，越屋根を設け，西端は棟を下げる。登梁を併用した和小屋により，高大な内部空間をつくる。伝統的な形式の醸造施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004430"},{"id":"00004431","register_sub_id":"101","register_pk":"105421","name":"高橋商店隅土蔵","kana":"たかはししょうてんすみどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47916256,"lng":134.31521154,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、スレート葺、建築面積49㎡、脇門付","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0222","desc":"敷地北西隅にあり，現在は物置としている。乱石積の基礎に建つ土蔵造２階建で，太い側柱を立て強固に固める。屋根は切妻造，波形スレート葺で，外壁は縦板で覆い，軒鉢巻の漆喰は現す。離れ屋との間には，切妻造の脇門を設ける。屋敷後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004431"},{"id":"00004429","register_sub_id":"101","register_pk":"105419","name":"高橋商店長屋門（旧製麹室）","kana":"たかはししょうてんながやもん（きゅうせいきくしつ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47895863,"lng":134.31553375,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0220","desc":"主屋の南方にある。木造平屋建，切妻造，桟瓦葺で，東端は棟を下げ，中央東寄りに門口を開き，西側はもと麹室としていた。外壁は漆喰塗，腰を縦板で覆い，門口廻りに換気用の丸窓を設ける。桁行２６ｍの長大な長屋門で，豪壮な屋敷正面の構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004429"},{"id":"00004433","register_sub_id":"101","register_pk":"105423","name":"高橋商店東醤油蔵","kana":"たかはししょうてんひがししょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47923739,"lng":134.31582678,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0224","desc":"主屋東方，南醤油蔵の北に並ぶ。桁行１２ｍ規模の木造平屋建，切妻造，本瓦葺，平入で，外壁は漆喰塗，街路側を縦板で覆い，軒に鉢巻をつける。内部は桁行中央に間仕切を設け，曲梁を用いた和小屋と登梁を併用して高い空間をつくる。醸造業に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004433"},{"id":"00004432","register_sub_id":"101","register_pk":"105422","name":"高橋商店南醤油蔵","kana":"たかはししょうてんみなみしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47911539,"lng":134.31586112,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0223","desc":"主屋東方にあり，もと樽の製作場としていた。桁行１８ｍ，木造平屋建，外壁は漆喰塗，腰を縦板で覆い，整然と小窓を並べる。屋根は切妻造，桟瓦葺で，中央を和小屋，両端を登梁式とし，高い内部空間をつくる。伝統的な形式で，醸造施設の構成の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004432"},{"id":"00002838","register_sub_id":"101","register_pk":"103828","name":"宝食品北佃煮原料蔵（旧左海醤油醸造所醤油蔵）","kana":"たからしょくひんきたつくだにげんりょうぐら（きゅうさかいしょうゆじょうぞうしょしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2121-1","lat":34.46502455,"lng":134.318832,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦及びスレート葺、建築面積276㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0106","desc":"主要地方道坂手港線の東側，山側に位置する左海醤油丘工場の敷地北方に西妻面を道路に見せて東西棟で建つ。桁行１７．６ｍ，梁間１０ｍ規模，桟瓦葺，切妻造の山側に桁行１１ｍ規模を延長する。杉板縦張の外壁上部に連子窓を並べた醤油蔵特有の外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002838"},{"id":"00002837","register_sub_id":"101","register_pk":"103827","name":"宝食品昆布蔵（旧左海醤油醸造所醤油蔵）","kana":"たからしょくひんこんぶぐら（きゅうさかいしょうゆじょうぞうしょしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字芦の浦2217-28","lat":34.464973,"lng":134.318527,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、瓦葺、建築面積408㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0105","desc":"主要地方道坂手港線の浜側に道路に沿って南北棟で建つ。桁行４０ｍ，梁間１０ｍ規模，桟瓦葺，切妻造で，現在は佃煮原料の貯蔵蔵として利用されているが，北妻面の「分銅・山サ」の屋号が由来を伝える。道路沿いに展開する「醤の里」景観の主要な構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002837"},{"id":"00002839","register_sub_id":"101","register_pk":"103829","name":"宝食品南佃煮原料蔵（旧左海醤油醸造所醤油蔵）","kana":"たからしょくひんみなみつくだにげんりょうぐら（きゅうさかいしょうゆじょうぞうしょしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2121-1","lat":34.464882,"lng":134.318771,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積242㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0107","desc":"左海醤油丘工場敷地南方に東西棟で建つ。桁行２２ｍ，梁間１１ｍ規模，桟瓦葺，切妻造で，東妻面は半切妻状に納める。敷地南辺沿いを流れる水路の花崗石の石積護岸を基礎とし，外壁は杉板張とする。「醤の里」景観の形成に貢献している建造物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002839"},{"id":"00010360","register_sub_id":"101","register_pk":"199132","name":"淡翁荘黒門","kana":"たんおうそうくろもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県坂出市本町1-3541-6","lat":34.31510095,"lng":133.85321609,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、間口2.4m、左右袖塀付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0400","desc":"淡翁荘主屋の北正面に建つ。一間一戸薬医門、切妻造本瓦葺で、五平の本柱を間口二・四二メートルで立て、欄間を盲連子とした両開き桟唐戸を吊り込む。両脇には瓦を載せた鉄筋コンクリート造の塀を矩折れにのばす。淡翁荘の表門として商店街側の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010360"},{"id":"00010359","register_sub_id":"101","register_pk":"199131","name":"淡翁荘主屋","kana":"たんおうそうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県坂出市本町1-3541-3他","lat":34.31494,"lng":133.853221,"geo_status":"db","era":"昭和11年／平成16年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積148㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0399","desc":"本店の西に建つ、もと鎌田醤油社長宅。外観は陸屋根、タイル張とした幾何学的で端正な意匠だが、内部は一階に上質な和風座敷、二階に暖炉を設えた本格的な洋室を配する。戦前期モダニズムの影響が認められ、県内の鉄筋コンクリート造住宅として最初期の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010359"},{"id":"00005039","register_sub_id":"101","register_pk":"106029","name":"丸尾醸造所原料蔵及び作業場","kana":"まるおじょうぞうしょげんりょうぐらおよびさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県仲多度郡琴平町榎井字籏岡94","lat":34.19153928,"lng":133.82904642,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0285","desc":"東主屋店舗部の南方に建つ作業場と，作業場の東側に並び建つ原料蔵で，ともに南北棟，切妻造，桟瓦葺の屋根をもち，小屋組は木造キングポストトラス。原料蔵は桁行１０間，梁間４間で，北方がもと米蔵で，南方が麹蔵となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005039"},{"id":"00005040","register_sub_id":"101","register_pk":"106030","name":"丸尾醸造所西味噌蔵","kana":"まるおじょうぞうしょにしみそぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県仲多度郡琴平町榎井字籏岡90-3","lat":34.19130552,"lng":133.82909018,"geo_status":"db","era":"大正中期／昭和初期増築","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積248㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0286","desc":"小路を隔てた南敷地に位置し，北妻面を小路に見せて建つ。もと醤油諸味蔵で，桁行７間，梁間５間規模，南北棟，切妻造，桟瓦葺の２棟が並び建つ。東側は和小屋，西側は洋小屋である。北敷地の原料蔵とともに小路に醸造所特有の景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005040"},{"id":"00000101","register_sub_id":"101","register_pk":"101091","name":"マルキン記念館（旧醤油醸造工場）","kana":"まるきんきねんかん（きゅうしょうゆじょうぞうこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲1850","lat":34.46698415,"lng":134.3192158,"geo_status":"db","era":"明治41～42","year":1908,"year_source":"converted","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1083㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"37 － 0002","desc":"小豆島に建つ醤油醸造のための工場施設を転用した記念館。マルキンの印を妻に書き上部に明かり取り窓をとる外観に特徴があり，江戸時代後期以来醤油醸造で栄えた小豆島において，往時の景観を知る上で欠くことのできない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000101"},{"id":"00001957","register_sub_id":"101","register_pk":"102947","name":"マルキン醤油第五号発酵蔵","kana":"まるきんしょうゆだいごごうはっこうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲1850","lat":34.466995,"lng":134.32077,"geo_status":"db","era":"明治41～42","year":1908,"year_source":"converted","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積698㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"37 － 0056","desc":"第二号発酵蔵の西に並んで建ち，桁行が約２５メートル短いが構造形式は共通する。醤油天然醸造の工程を見せるため内部を公開しており，記念館として欠くことのできない建物であるとともに，工場施設の往時の景観を知る上で重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001957"},{"id":"00001956","register_sub_id":"101","register_pk":"102946","name":"マルキン醤油第四号発酵蔵","kana":"まるきんしょうゆだいよんごうはっこうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲1850","lat":34.46700231,"lng":134.320892,"geo_status":"db","era":"明治41～42","year":1908,"year_source":"converted","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積952㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"37 － 0055","desc":"桁行約９４メートルに及ぶ長大な醸造蔵で，工場の東辺を区切る位置に建つ。白壁に開けられた風通し窓が柱間一間毎に並ぶ外観に特徴があり，江戸時代後期以来醤油醸造で栄えた小豆島において，往時の景観を知る上で欠くことのできない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001956"},{"id":"00000102","register_sub_id":"101","register_pk":"101092","name":"マルキン醤油発酵蔵","kana":"まるきんしょうゆはっこうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲1850","lat":34.46649219,"lng":134.32027084,"geo_status":"db","era":"明治41～42","year":1908,"year_source":"converted","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1462㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"37 － 0003","desc":"小豆島に建つ醤油醸造のための土蔵造の蔵。板を張った長大な妻を道路に面してみせる外観に特徴があり，記念館とともに江戸時代後期以来醤油醸造で栄えた小豆島において，往時の景観を知る上で欠くことのできない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000102"},{"id":"00003004","register_sub_id":"101","register_pk":"103994","name":"三谷製糖羽根さぬき本舗旧牛舎","kana":"みたにせいとうはねさぬきほんぽきゅうぎゅうしゃ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県東かがわ市馬宿156-6","lat":34.215431,"lng":134.419769,"geo_status":"db","era":"大正期／昭和初期移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0129","desc":"主屋西側敷地に東西棟で建つ。砂糖黍締車を引き回す牛の畜舎として建設。桁行１２ｍ，梁間４．５ｍ規模，切妻造，本瓦葺で，南北両面に下屋を差出し，北西部に角屋を張出す。板張の簡素な牛舎であるが，往事の和三盆の製造事情を物語る施設として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003004"},{"id":"00003003","register_sub_id":"101","register_pk":"103993","name":"三谷製糖羽根さぬき本舗砂糖釜屋","kana":"みたにせいとうはねさぬきほんぽさとうかまや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県東かがわ市馬宿156-5","lat":34.215226,"lng":134.41976776,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0128","desc":"主屋押し場玄関の南に取り付き，南北棟で建つ。桁行６ｍ，梁間５ｍ，切妻造，桟瓦葺の平屋建で，屋根上に煙出の越屋根と煉瓦煙突を建ち上げた釜屋ならではの外観を呈する。内部は，東半に大釜３連と小釜１基の煉瓦造竈を配置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003003"},{"id":"00003002","register_sub_id":"101","register_pk":"103992","name":"三谷製糖羽根さぬき本舗主屋（押し場）","kana":"みたにせいとうはねさぬきほんぽしゅおく（おしば）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県東かがわ市馬宿156-5","lat":34.21531949,"lng":134.41978163,"geo_status":"db","era":"大正期／昭和25頃増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0127","desc":"阿讃国境大坂越峠下，菜切川左岸河口近くに位置し，阿讃街道から奥まったところに敷地を構える。南北棟，切妻造の２階建で，東面は下屋を差掛けてつし２階風に見せ，南方は平屋建として入母屋造とする。階下中央部は「押し場」で，天秤形状の圧搾機を並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003002"},{"id":"00004033","register_sub_id":"101","register_pk":"105023","name":"元屋商店西醤油蔵及び東諸味蔵","kana":"もとやしょうてんにししょうゆぐらおよびひがしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町字城甲660-2","lat":34.4855688,"lng":134.18313865,"geo_status":"db","era":"明治初期／明治後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積319㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0198","desc":"主屋の北方に位置し東西棟で建つ。桁行１４間梁間４間，切妻造，桟瓦葺の東諸味蔵の東方桁行８間分は，明治１３年の家相図の醤油蔵に一致する。棟を高くした西方の桁行５間梁間５間規模の西醤油蔵とともに全長１９間の長大な醤油醸造蔵を敷地北辺に形づくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004033"},{"id":"00002834","register_sub_id":"101","register_pk":"103824","name":"ヤマサン醤油洗い場","kana":"やまさんしょうゆあらいば","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.4765311,"lng":134.3203208,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"石造、面積28㎡及び10㎡、井戸付","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0102","desc":"醤油原料の洗い場で，花崗石を用いた井戸，花崗石敷の洗い場，排水溝から成る。東麹室西前面の作業広場南北に対として２箇所設置されており，北方は６．５ｍ×４．３ｍ，南方は３．６ｍ×２．８ｍ規模を有し，醤油醸造場特有の作業空間をつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002834"},{"id":"00003623","register_sub_id":"101","register_pk":"104613","name":"ヤマサン醤油桶場","kana":"やまさんしょうゆおけば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47662073,"lng":134.32001817,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0180","desc":"槽場の西方に位置し，北醤油蔵の西妻面に接し，醸造場敷地北西辺に沿って建つ。桁行１５ｍ梁間６ｍ規模，切妻造，桟瓦葺の平屋建で，菱形平面とする点に特徴があり，醸造場側の南桁行面には下屋を差し掛けて錣屋根風にみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003623"},{"id":"00002832","register_sub_id":"101","register_pk":"103822","name":"ヤマサン醤油北醤油蔵","kana":"やまさんしょうゆきたしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47671828,"lng":134.32002921,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積546㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0100","desc":"醸造場敷地の北方に位置し，東西棟で建つ。桁行３０間，梁間５間規模，切妻造の長大な醤油醸造蔵で，内部梁間中央に１列の柱を建てる。現在は倉庫として利用されているが，かっては醸造用木桶１００基ほどが設置されていたと伝える。醤油醸造の中核的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002832"},{"id":"00003621","register_sub_id":"101","register_pk":"104611","name":"ヤマサン醤油米蔵","kana":"やまさんしょうゆこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47659549,"lng":134.32038835,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0178","desc":"三階建工場の東方に位置し，ボイラー室と棟を並べて建つ。桁行８ｍ梁間３ｍ規模，南北棟，切妻造，桟瓦葺の平屋建で，南妻面の東寄りに庇付きの戸口を設け，北妻面の上部には小さな円形換気孔２口を開ける。洗い場などともに醸造場東側部を構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003621"},{"id":"00002831","register_sub_id":"101","register_pk":"103821","name":"ヤマサン醤油三階建醤油醸造工場","kana":"やまさんしょうゆさんかいだてしょうゆじょうぞうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47657631,"lng":134.32016548,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造3階建、瓦葺、建築面積56㎡","structure_material":"木造3階建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0099","desc":"醤油醸造場部のほぼ中央に位置する。桁行４間，梁間３間半規模，東西棟，桟瓦葺，切妻造の木造３階建で，小屋組はキングポストトラス，外壁は焼板縦張とする。他の醸造施設や住宅部よりひときわ高く，ヤマサン醤油のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002831"},{"id":"00003620","register_sub_id":"101","register_pk":"104610","name":"ヤマサン醤油仕込み場及びボイラー室","kana":"やまさんしょうゆしこみばおよびぼいらーしつ","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47651231,"lng":134.3200959,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積224㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0177","desc":"三階建工場の西面と南面に取り付くかたちで建つ。西から取り付く仕込み場は東西棟，切妻造，桟瓦葺の平屋建で，南桁行面に下屋を差し掛けて梁行１１ｍ規模とし，ボイラー室の屋根には換気のための越屋根を備える。小屋組はキングポストトラスを組む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003620"},{"id":"00005367","register_sub_id":"101","register_pk":"106355","name":"ヤマサン醤油製麹長屋門及び納屋","kana":"やまさんしょうゆせいきくながやもんおよびなや","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町馬木字内浜甲182-1","lat":34.47623086,"lng":134.31976466,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積92㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0300","desc":"醤油醸造所及び醸造所主住宅の道路向いの敷地に建つ。道路沿いのへの字平面の平屋建納屋の東につし２階の長屋門が繋がる構成で，長屋門の西端に間口１間半規模の門口を開ける。長屋門の東方を麹室とし，南面に下屋庇を差し掛ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005367"},{"id":"00003622","register_sub_id":"101","register_pk":"104612","name":"ヤマサン醤油操作場","kana":"やまさんしょうゆそうさば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47648449,"lng":134.32044763,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0179","desc":"米蔵の南方，東麹室の西方に位置し，米蔵とは洗い場を介して向き合う。桁行南辺１１ｍ北辺１０ｍの台形平面で，梁間９ｍ規模。東西棟，切妻造，桟瓦葺の平屋建で，北面と西面に戸口を開け，屋根中央に越屋根を上げる。麹室に近接したもと釜場とみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003622"},{"id":"00002833","register_sub_id":"101","register_pk":"103823","name":"ヤマサン醤油東麹蔵","kana":"やまさんしょうゆひがしこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47660897,"lng":134.32034538,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、瓦葺、建築面積241㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0101","desc":"北醤油蔵の南方，３階建工場の東方に作業広場を挟んで南北棟で建つ。桁行１５間規模で，内部は５室の麹室に分けられ，西面に１間幅の下屋を設けて戸前とする。北妻面には温度調節のため小窓を２箇所開ける。醤油醸造に欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002833"},{"id":"00003619","register_sub_id":"101","register_pk":"104609","name":"ヤマサン醤油槽場","kana":"やまさんしょうゆふなば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47651607,"lng":134.31975564,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積245㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0176","desc":"醤油醸造元住宅屋敷地の北方に位置する醸造場敷地の北寄り，三階建工場と北醤油蔵の間に東西棟で建つ。桁行２５ｍ梁間１０ｍ規模の切妻造，桟瓦葺で，屋根西端近くに越屋根を載せる。内部は，柱や牛梁，地棟，束など丸太材による架構をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003619"},{"id":"00002464","register_sub_id":"101","register_pk":"103454","name":"山田家（旧清酒源氏正宗醸造元）煙突","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）えんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35340664,"lng":134.12971056,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、高さ18m","structure_material":"煉瓦造","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0080","desc":"主屋の北東方に建つ。高さ１８ｍ程の煉瓦造，イギリス積の角形煙突で，現在は独立して建ち，中程までをモルタル塗仕上げとする。上部には煉瓦を薄く刎ねだしてバンドを，頂部には歯飾状コーニスを造り出す。南面に「源氏正宗醸造元」の文字を書き記す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002464"},{"id":"00002462","register_sub_id":"101","register_pk":"103452","name":"山田家（旧清酒源氏正宗醸造元）北酒蔵","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）きたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35331,"lng":134.129822,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0078","desc":"主屋の東南方に位置し，南酒蔵の北方に接続して建つ。南北棟，切妻造，桟瓦葺，平入のもと酒蔵で，内部は南酒蔵と同様に食事室として活用されている。東面は下見板張の簡素な造りであるが，北方の煉瓦造煙突とともに造り酒屋の面影をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002462"},{"id":"00002459","register_sub_id":"101","register_pk":"103449","name":"山田家（旧清酒源氏正宗醸造元）主屋","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）しゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35327462,"lng":134.12960973,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積284㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0075","desc":"四国霊場８５番札所八栗寺参道から７０ｍ程入った屋敷地のほぼ中央に南面して建つ。明治になって酒造業に転じた名家の居宅部で，桁行１４間と規模が大きく，入母屋造，本瓦葺，虫籠窓を開けたつし２階建とする。現在は「山田家」の屋号で讃岐うどん店を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002459"},{"id":"00002461","register_sub_id":"101","register_pk":"103451","name":"山田家（旧清酒源氏正宗醸造元）南酒蔵","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）みなみさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35318536,"lng":134.12988759,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造平屋建、瓦葺、建築面積102㎡","structure_material":"土蔵造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0077","desc":"長屋門の東方に，南妻面を外周道路側に見せて建つ。南北棟，切妻造，桟瓦葺，平入のもと酒蔵で，西面に下屋を差し掛けて蔵前をとる。南面は腰部を板張，上部を白壁に仕上げ，東面は下見板張とする。内部は近年の改造により食事室に改められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002461"},{"id":"00003149","register_sub_id":"101","register_pk":"104139","name":"ヤマヒサ北諸味蔵","kana":"やまひさきたもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町安田字新開甲243-1","lat":34.48102366,"lng":134.31399276,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0142","desc":"西諸味蔵の北西に位置し，南に双棟構えの南諸味蔵を接続させる。桁行１２間梁間５間規模，南北棟，切妻造，桟瓦葺の平屋建醤油蔵で，昭和７年創業時の施設。外観は西諸味蔵と同様の杉板張りとし北妻面に「山久」の屋号を印す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003149"},{"id":"00003148","register_sub_id":"101","register_pk":"104138","name":"ヤマヒサ西諸味蔵","kana":"やまひさにしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字新開甲243-1","lat":34.48087859,"lng":134.31382959,"geo_status":"db","era":"明治33／昭和24移築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0141","desc":"内海湾安田港の北方，内海郵便局東方の変形四叉路に南妻面を見せて建つ。桁行１０間梁間５間規模，南北棟，切妻造，桟瓦葺の平屋建醤油蔵で，東面に下屋を差掛ける。明治の醤油蔵を昭和２４年移築したもので，外観は当地の醤油蔵と同様に杉板張りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003148"},{"id":"00004036","register_sub_id":"101","register_pk":"105026","name":"やまひら醤油諸味蔵","kana":"やまひらしょうゆもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3260","lat":34.54558362,"lng":134.28384472,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0201","desc":"大部港に北面する敷地の東北端に位置し東西棟で建つ。北面桁行２間半，南面桁行４間，梁間５間半の台形平面とした切妻造，桟瓦葺の醤油蔵で，小屋組はキングポストトラスとする。外装は腰を高い縦板張，上部を真壁造として街頭の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004036"},{"id":"00004667","register_sub_id":"101","register_pk":"105657","name":"山吉醤油圧搾場及び仕込場","kana":"やまよししょうゆあっさくばおよびしこみば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字今坂甲710","lat":34.47536811,"lng":134.32465559,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺及びスレート葺、建築面積324㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0259","desc":"諸味蔵の東に平行し２棟並びで建つ。圧搾場は桁行１８ｍ梁間１０ｍ規模，切妻造，波形スレート葺，仕込場は桁行１４ｍ梁間８ｍ規模，切妻造，桟瓦葺で，ともに煙出しの越屋根を載せ，仕込場の東面に下屋庇を差し掛ける。諸味蔵とともに醤油醸造場の中心施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004667"},{"id":"00004669","register_sub_id":"101","register_pk":"105659","name":"山吉醤油釜屋","kana":"やまよししょうゆかまば","category":"産業2次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字今坂甲709-2","lat":34.47551,"lng":134.32463166,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡、煙突付","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0261","desc":"原料蔵の東方，水路を隔てた圧搾場及び仕込場の北方に位置し，東西棟で建つ。桁行１８ｍ梁間６ｍ規模，切妻造，桟瓦葺の木造平屋建で，棟の中央西寄りに煙出しを載せ，煙出し西側に煉瓦造煙突を突き出す。煙突は高さ１５ｍで，山吉醤油のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004669"},{"id":"00004668","register_sub_id":"101","register_pk":"105658","name":"山吉醤油原料蔵及び帳場","kana":"やまよししょうゆげんりょうぐらおよびちょうば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字今坂甲709-2","lat":34.475517,"lng":134.32449155,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0260","desc":"水路を隔てた諸味蔵の北方に位置し，南北棟で建つ。桁行８．２ｍ梁間７．７ｍ規模，切妻造，桟瓦葺の木造２階建で，東面に下屋庇を添わす。外部は諸味蔵と同様に，腰焼杉縦板張，上部白漆喰塗とし，諸味蔵とともに醤油醸造所特有の景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004668"},{"id":"00004666","register_sub_id":"101","register_pk":"105656","name":"山吉醤油諸味蔵","kana":"やまよししょうゆもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字今坂甲710","lat":34.4753388,"lng":134.32447634,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0258","desc":"屋敷地を横断する水路の南方，離れ屋の北方に南北棟で建つ。桁行２４ｍ梁間１０ｍ規模，切妻造，桟瓦葺の木造平屋建で，南半には諸味桶を据え，北半は瓶詰場とする。外部は腰焼杉縦板張，上部白漆喰塗とし，南半には高窓を並べ，北半の棟には煙出しを上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004666"},{"id":"00003626","register_sub_id":"101","register_pk":"104616","name":"ヤマロク醤油西諸味蔵","kana":"やまろくしょうゆにしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字空条甲1607","lat":34.48630104,"lng":134.32109093,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺及びスレート葺、建築面積131㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0183","desc":"東諸味蔵の西に接して建つ。桁行１５．５ｍ梁間７．３ｍ規模，南北棟，切妻造，波形スレート葺で，北妻面に桁行３．６ｍの下屋を差し掛けて蔵前をとる。東諸味蔵とともに２棟並びの妻面をみせ，醸造場敷地南辺道路沿いに独特の醤油蔵景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003626"},{"id":"00003625","register_sub_id":"101","register_pk":"104615","name":"ヤマロク醤油東諸味蔵","kana":"やまろくしょうゆひがしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字空条甲1607","lat":34.48627186,"lng":134.3211908,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、スレート葺、建築面積85㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0182","desc":"内海湾に南流する安田大川の東方に位置する醸造場敷地の東寄りに建つ。桁行１０．４ｍ梁間８．２ｍ規模であるが，桁行は２／３ほどに切り縮められている。南北棟の切妻造で，南妻面を東西道路にみせ，簡素な虫籠窓を２箇所に開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003625"},{"id":"00002699","register_sub_id":"101","register_pk":"103689","name":"旭醤油醸造場","kana":"あさひしょうゆじょうぞうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県宇和島市吉田町東小路甲112","lat":33.27932723,"lng":132.53997712,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造平屋建、瓦葺、建築面積113㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0026","desc":"町中心部の街路の角地に建つ。瘤出仕上の花崗岩基礎の上に，切妻造平入，土蔵造躯体を立上げ，正面に格子を嵌めた横長の窓と，瀟洒な鉄製持送り付の小庇を設ける。店舗部分には醤油の量売りに用いたタイル張の流しを残す。大正期の街路景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002699"},{"id":"00002182","register_sub_id":"101","register_pk":"103172","name":"梅錦山川主屋","kana":"うめにしきやまかわしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市金田町金川14","lat":33.98914992,"lng":133.59390661,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0013","desc":"川之江から高知に抜ける旧道に西面して建つ。造り酒屋の店舗兼住宅主屋で，ほぼ南半をシモテ，北半をカミテとする。入母屋造，本瓦葺，つし２階風の重厚かつ長大な構えを旧道からややひいた位置に展開し，仕込蔵とともに地区のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002182"},{"id":"00004055","register_sub_id":"101","register_pk":"105045","name":"梅美人酒造釜場及び煙突","kana":"うめびじんしゅぞうかまばおよびえんとつ","category":"産業2次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県八幡浜市1557-2","lat":33.46540086,"lng":132.42571594,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0056","desc":"事務所の西方に位置し，東西棟で建つ。切妻造，桟瓦葺で，小屋組はキングポストトラスとし，換気用の越屋根を上げる。西妻面の南寄りには正方形断面の煉瓦造煙突を建ち上げ，南面に「ウメビジンホン店」を表す。港からの格好のランドマークになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004055"},{"id":"00004056","register_sub_id":"101","register_pk":"105046","name":"梅美人酒造醸造場","kana":"うめびじんしゅぞうじょうぞうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県八幡浜市1557-2","lat":33.46548993,"lng":132.42584589,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積767㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0057","desc":"敷地西辺沿いの南北棟の仕込蔵と，釜場北面に沿う東西棟の貯蔵蔵とがＴ字形の棟構成をつくる。仕込蔵内部の２階北方には麹室がつくられ，貯蔵蔵の１階北西隅を槽場に充てる。ともに創業以来の施設で，醸造場の核となる建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004056"},{"id":"00005202","register_sub_id":"101","register_pk":"106192","name":"遠登志橋","kana":"おとしばし","category":"産業2次","subcategory":"土木構造物","type_guess":"橋","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県新居浜市立川町620-1地先","lat":33.89079217,"lng":133.31142796,"geo_status":"db","era":"明治38／平成4改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"鋼製単アーチ橋、橋長48m、幅員2.4m","structure_material":"鋼製単アーチ橋","registered":"2005.12.26(平成17.12.26)","register_no":"38 － 0066","desc":"市内山間部を南北に貫流する国領川水系小女郎川に架かる。坑水路兼道路橋として別子鉱山内に築かれた橋長４８ｍ，スパン３７ｍの鋼製スパンドレルブレースト単アーチ橋。アーチにはⅠ型鋼を用い両端をピン支承で固定する。わが国現存最古級の鋼製アーチ橋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005202"},{"id":"00013463","register_sub_id":"101","register_pk":"368559","name":"旧住友化学工業株式会社幹部社宅","kana":"きゅうすみともかがくこうぎょうかぶしきがいしゃかんぶしゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1896-1","lat":33.94914167,"lng":133.26093056,"geo_status":"db","era":"昭和10年／平成30年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積275㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0147","desc":"新居浜市北西部に位置する住友山田社宅の西部に建つ。木造平屋建、瓦葺で、外壁は下見板張とする。東寄りは北東隅を玄関、南東隅を洋室の応接間とし、その西側は、南を客間、北を居間、台所等とする。中央の畳廊下で、公用と私用の空間を分けた幹部の社宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013463"},{"id":"00013465","register_sub_id":"101","register_pk":"368561","name":"旧住友共同電力株式会社監査役社宅","kana":"きゅうすみともきょうどうでんりょくかぶしきがいしゃかんさやくしゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1857-1","lat":33.94968889,"lng":133.26005556,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積173㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0149","desc":"新居浜市北西部に位置する住友山田社宅の西部に建つ。木造平屋建、桟瓦葺で、外壁は吹付塗装とする。東端中央を玄関、南に応接室、西に床、棚付の客間を配す。北側中央は内玄関で、西半を私用空間とする。東半を客用、西半を私用に分けた企業監査役の社宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013465"},{"id":"00013464","register_sub_id":"101","register_pk":"368560","name":"旧住友共同電力株式会社幹部社宅","kana":"きゅうすみともきょうどうでんりょくかぶしきがいしゃかんぶしゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1900","lat":33.94944444,"lng":133.26012778,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積295㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0148","desc":"新居浜市北西部に位置する住友山田社宅の西部に建つ。木造平屋建、桟瓦葺で、外壁は竪羽目板張、上部小壁を漆喰塗仕上とする。北東隅を玄関、ホールを介し南に洋室の応接間、その西側に１０畳と６畳の客間を配す。東半を客用、西半を私用に分けた幹部社宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013464"},{"id":"00013459","register_sub_id":"101","register_pk":"368544","name":"旧住友鉱業株式会社別子鉱業所長社宅応接棟","kana":"きゅうすみともこうぎょうかぶしきがいしゃべっしこうぎょうしょちょうしゃたくおうせつとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1903-1","lat":33.9498,"lng":133.26123333,"geo_status":"db","era":"昭和12年／平成30年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0143","desc":"主屋北面西寄に渡廊下で接続して建つ。木造平屋建、切妻造桟瓦葺で、東面に入母屋屋根を二段突出して玄関とする。外壁は真壁漆喰塗で、腰は下見板張。内部は東半に玄関、渡廊下等を、西半に洋風の応接室、広縁を配す。主屋と一連で、端正な造りを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013459"},{"id":"00013458","register_sub_id":"101","register_pk":"368543","name":"旧住友鉱業株式会社別子鉱業所長社宅主屋","kana":"きゅうすみともこうぎょうかぶしきがいしゃべっしこうぎょうしょちょうしゃたくおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1903-1","lat":33.94968889,"lng":133.26133056,"geo_status":"db","era":"昭和12年／平成30年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0142","desc":"市北西部の住友山田社宅西部にある敷地中央に北面して建つ。横長の入母屋造桟瓦葺で、棟東端南北面に千鳥破風を、南面に下屋を付す。内部は雁行した廊下を通し、南側に床付座敷等の居室を、北側に玄関、家政部を並べる。華美さを抑えた端正かつ上質な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013458"},{"id":"00013460","register_sub_id":"101","register_pk":"368545","name":"旧住友鉱業株式会社別子鉱業所長社宅茶室","kana":"きゅうすみともこうぎょうかぶしきがいしゃべっしこうぎょうしょちょうしゃたくちゃしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1903-1","lat":33.94961111,"lng":133.26148333,"geo_status":"db","era":"昭和12年／平成30年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0144","desc":"主屋南東に接続し、切妻造桟瓦葺の水回り及び前室部と、南端の切妻造桟瓦葺で三方に下屋を廻した茶室からなる。茶室は８畳の座敷で、南、西面に縁を廻す。東面の床は、一間半幅の地袋の上に床柱を立てて明障子を開くなど、自由な造作を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013460"},{"id":"00013462","register_sub_id":"101","register_pk":"368558","name":"旧住友別子鉱山株式会社外国人技師西社宅","kana":"きゅうすみともべっしこうざんかぶしきがいしゃがいこくじんぎしにししゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1900","lat":33.94976667,"lng":133.26046389,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺、建築面積130㎡","structure_material":"木造2階建一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0146","desc":"東社宅の西側に建つ。木造2階建、切妻造桟瓦葺で、南に寄棟造のサンルームを突出し、西に片流屋根の家政部を付す。外壁は下見板張。東社宅に類似したＬ字型居室配置の平面を成すが、やや小振りにつくる。会社の業態転換に伴う外国人技師招聘の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013462"},{"id":"00013461","register_sub_id":"101","register_pk":"368557","name":"旧住友別子鉱山株式会社外国人技師東社宅","kana":"きゅうすみともべっしこうざんかぶしきがいしゃがいこくじんぎしひがししゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1900","lat":33.94994722,"lng":133.26077222,"geo_status":"db","era":"昭和5年／昭和前期・同中期増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺、建築面積196㎡","structure_material":"木造2階建一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0145","desc":"市北西部の住友山田社宅西部にある。木造2階建、寄棟造桟瓦葺で、南に突出した寄棟造のサンルームは掃出窓で開放的につくり、西に平屋建の家政部を付す。外壁は下見板張。内部は上下階共南東の大部屋を中心にＬ字型に３室配す。洋風意匠で端正にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013461"},{"id":"00014113","register_sub_id":"101","register_pk":"508373","name":"旧二宮製材所事務所兼主屋","kana":"きゅうにのみやせいざいしょじむしょけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県喜多郡内子町小田360","lat":33.57066667,"lng":132.80420556,"geo_status":"db","era":"昭和17年／同40年代改修","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0162","desc":"内子町東部の山間の町に位置する林業家の町家。通りに東面する入母屋造平入桟瓦葺。北に土間、南は東半を一室の事務所、西半は三室続き座敷とする。北に炊事場棟、南に浴室・便所棟を突出する。二階は建ちを押さえつつ四方に出桁で軒を持出し、豪壮にみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014113"},{"id":"00003721","register_sub_id":"101","register_pk":"104711","name":"旧三崎精錬所焼窯","kana":"きゅうみさきせいれんしょやきかま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県西宇和郡伊方町佐田乙2085","lat":33.36306339,"lng":132.10361684,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、建築面積496㎡","structure_material":"石造","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0050","desc":"町南部，宇和海に面する山の斜面に築かれる。荒吹と呼ばれる銅の製錬作業に用いられる窯が，煙道と共に斜面の上方向に直線状に横３列，曲線状に２列配され，各焚口を緑泥変岩を用いて直径０．９ｍ程のアーチでつくる。銅製錬の近代化を知る上で貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003721"},{"id":"00004059","register_sub_id":"101","register_pk":"105049","name":"佐々木酒造煉瓦煙突","kana":"ささきしゅぞうれんがえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県伊予郡砥部町総津785","lat":33.62829135,"lng":132.79807098,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、高さ20m","structure_material":"煉瓦造","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0060","desc":"主屋南西に位置する醸造蔵の南端に建つ。基部は煉瓦長手６枚半四方で，緩やかなカーブを描いて逓減し，煉瓦の持ち出し技法により特徴的な柱頭飾り風の頂部をつくる。高さ２０ｍ規模で，国道からも容易く確認することができ，地区の目印的存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004059"},{"id":"00012070","register_sub_id":"101","register_pk":"211011","name":"正木本店会所場・釜場・煙突","kana":"まさきほんてんかいしょば・かまば・えんとつ","category":"産業2次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228444,"lng":132.706724,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"会所・窯場 木造平屋建、瓦葺、建築面積145㎡ 煙突 煉瓦造、高さ14m","structure_material":"会所・窯場 木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"38-121","desc":"貯蔵庫と仕込庫の入隅に建つ。貯蔵庫西面で釜場が接し、北に一二畳半の会所場を張り出し、全体に切妻造の屋根を大きく架ける。釜場内に建つ煙突は、一辺一・八メートルの正方形平面をもつ煉瓦造で高さ一四メートルあり、酒造場に相応しい景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012070"},{"id":"00012069","register_sub_id":"101","register_pk":"211010","name":"正木本店生酒庫","kana":"まさきほんてんきしゅこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228354,"lng":132.706434,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積225㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"38-120","desc":"仕込庫の北に東西棟で平行する。桁行一三・五間、梁間四間、平屋建で、東に梁間二間の検査室を張り出す。屋根は切妻造、桟瓦葺とする。小屋組はキングポストトラスとし、筋交や方杖で補強し、広い梁間を構成する。安定した採光を確保するため北面に窓を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012069"},{"id":"00012068","register_sub_id":"101","register_pk":"211009","name":"正木本店仕込庫","kana":"まさきほんてんしこみこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228396,"lng":132.706553,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積274㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"38-119","desc":"貯蔵庫の西に東西棟で直交する。桁行一二間、梁間六間、二階建で、屋根は切妻造、桟瓦葺とする。内部は、一室で、一階階高は四メートルあり、中央二列に直径二七センチメートルで磨き丸太のままのスギ材の柱を二間毎に立て二階床組を支える大規模な仕込庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012068"},{"id":"00012067","register_sub_id":"101","register_pk":"211008","name":"正木本店貯蔵庫","kana":"まさきほんてんちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228528,"lng":132.706784,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋一部2階建、瓦葺、建築面積266㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"38-118","desc":"店舗部の北に続く貯蔵庫。梁間四間で、桁行一一間半の平屋建部と桁行四間の二階建部からなり、いずれも切妻造、桟瓦葺である。内部は一室で鉄骨の梁を用いて小屋組を造る。外壁は漆喰塗腰板張で、塗込の格子窓を要所に穿ち、街路からの景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012067"},{"id":"00012066","register_sub_id":"101","register_pk":"211007","name":"正木本店店舗兼主屋","kana":"まさきほんてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228444,"lng":132.706998,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積324㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"38-117","desc":"松丸街道沿いに南面する。店舗部は切妻造で、正面一階に格子を構え、二階は塗込め窓を連続し、内部は土間吹抜けに豪壮な梁組をみせる。座敷部は入母屋造で下屋庇を廻らし、内部に三室を並べる。異なる意匠の外観を巧みに連ね、街道沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012066"},{"id":"00011424","register_sub_id":"101","register_pk":"209261","name":"水口酒造店舗兼主屋","kana":"みなくちしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県松山市道後喜多町975","lat":33.851371,"lng":132.782633,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積260㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"38－0114","desc":"道後温泉の近傍で、通りに北面して建つ造酒屋の店舗兼主屋。右土間とし、床上部の正面側には帳場を構える。二階には二四畳半の大広間を備え、小屋組はこの大広間直上のみトラス、ほかを和小屋とする。柱と貫を現しとした外観が、町並みの風情を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011424"},{"id":"00010522","register_sub_id":"101","register_pk":"199462","name":"旧浜口家住宅主屋","kana":"きゅうはまぐちけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高岡郡佐川町字西町甲1472-1","lat":33.498824,"lng":133.288242,"geo_status":"db","era":"明治初期／大正6・平成25改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積217㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"39 － 0279","desc":"酒造業を営んだ旧家の主屋。吹抜の通り土間の左右に部屋を並べ、東奧に八畳の座敷を配する。土間まわりは網代の壁や天井を用い、座敷の違棚には梅鉢紋入りの精緻な飾金具を飾る。正面は長屋門を思わせる重厚な外観に出格子を並べ、通りの歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010522"},{"id":"00006723","register_sub_id":"101","register_pk":"107706","name":"豊永染物店蔵","kana":"とよながそめものてんくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸郡安田町大字安田1899","lat":33.43939519,"lng":133.98272076,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0233","desc":"安田川に東面する敷地の東寄りに建つ。桁行２間半梁間２間の土蔵造２階建、南北棟で、西に下屋をつけて蔵前とする。屋根は切妻造で、左桟瓦と右桟瓦を用いる。外壁は土佐漆喰塗で妻面に３段の水切り瓦を見せ、腰を板張とする。川辺景観の要素として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006723"},{"id":"00006724","register_sub_id":"101","register_pk":"107707","name":"豊永染物店土塀","kana":"とよながそめものてんどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡安田町大字安田1899","lat":33.43953081,"lng":133.98263942,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"練塀、瓦葺、延長14m","structure_material":"練塀","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0234","desc":"敷地北辺を限る塀。もと水路であった道に沿って彎曲し、延長１４ｍを測る。人頭大の石を赤土で積んだ練塀で、基底幅０．６ｍ。総高１．６ｍで、道の東下り勾配に合わせ、中途で１段低く造る。上部は桟瓦葺とする。伝統的な工法により特色ある景観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006724"},{"id":"00003734","register_sub_id":"101","register_pk":"104724","name":"濱川家住宅蔵","kana":"はまかわけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県安芸郡田野町字西町1880-1","lat":33.42759695,"lng":134.01006443,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積193㎡","structure_material":"土蔵造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0091","desc":"田野町中心地に位置し，敷地南寄りに東妻面を道路に見せて建つ。桁行１０間梁間３間，東西棟，切妻造，桟瓦葺で，北面に切妻造の入口部と下屋を差し掛ける。軒下の高い位置に窓を並べ，当地方特有の土佐漆喰塗壁に水切瓦を廻して長大な壁面をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003734"},{"id":"00010521","register_sub_id":"101","register_pk":"202577","name":"濵川商店酒蔵","kana":"はまかわしょうてんさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡田野町字橋本西2150-1","lat":33.426222,"lng":134.008261,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積347㎡、煉瓦造煙突付","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"39 － 0278","desc":"川に面して建つ土蔵造二階建、切妻造桟瓦葺で片面下屋付の大規模な酒蔵。一階を仕込蔵、二階を麹室及び酒母室とする。下屋には倉庫と大竈、煉瓦煙突を据え、日本酒の工程一式を一棟に収める。川側は換気用窓を並べ、多段に廻らせる水切が土佐の蔵の特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010521"},{"id":"00001966","register_sub_id":"101","register_pk":"102956","name":"濱田家住宅（旧増田屋）蔵","kana":"はまだけじゅうたく（きゅうますだや）くら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡奈半利町乙1751","lat":33.42609703,"lng":134.02220691,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0016","desc":"大蔵と並び建つ桁行約１４ｍ，梁行約４ｍ規模の長い土蔵で，桁行約７．２ｍ分の北蔵と，棟を落とした南蔵から成り，北蔵と南蔵との間を蔵前とし，東面に一体的な下屋を付ける。北蔵は，置屋根型式で，北と東面は水切瓦をつけるなど整った意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001966"},{"id":"00001964","register_sub_id":"101","register_pk":"102954","name":"濱田家住宅（旧増田屋）主屋","kana":"はまだけじゅうたく（きゅうますだや）しゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡奈半利町乙1751","lat":33.42587505,"lng":134.02215464,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積167㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0014","desc":"旧道の一等地に建つ寛政７年（１７９５）創業の造り酒屋と質屋を営んだ商家。間口約１０ｍ，奥行約１５ｍ規模，切妻造，桟瓦葺，２階建，平入で，正面に下屋庇を付ける。西妻面及び正面２階に水切瓦を付けるなど奈半利における商家建築の代表的事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001964"},{"id":"00001961","register_sub_id":"101","register_pk":"102951","name":"藤村製絲株式会社石塀","kana":"ふじむらせいしかぶしきがいしゃいしべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙2630","lat":33.42825636,"lng":134.02484907,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"石造、延長35m","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0011","desc":"敷地の西辺を限る丸石練塀。５０ｃｍ厚，高さ２．２ｍで，南部は玉石，北部は半割面を見せ，頂部に桟瓦葺の小屋根を載せる。土佐地方特有の「いしぐろ」の系統を引くが，基礎を間知積風，コーナーを切石積とするなど近代の手法も採り入れられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001961"},{"id":"00001958","register_sub_id":"101","register_pk":"102948","name":"藤村製絲株式会社西蔵","kana":"ふじむらせいしかぶしきがいしゃにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙2630","lat":33.42847711,"lng":134.02506502,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積190㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0008","desc":"奈半利川河口左岸に位置し，捕鯨や林業で栄えた奈半利の実業家である藤村米太郎が興した製糸工場の繭蔵で，敷地の西北隅に建つ。桁行約１６ｍ，梁間約１０ｍ規模の東西棟，切妻造，桟瓦葺，平入２階建土蔵で，妻面には当地方特有の水切瓦を５段に付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001958"},{"id":"00004072","register_sub_id":"101","register_pk":"105062","name":"松岡家住宅北酒蔵","kana":"まつおかけじゅうたくきたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53207699,"lng":133.35195645,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積128㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0140","desc":"槽場の北側に接し敷地奥に位置する。桁行８間梁間４間の規模を有する，土蔵造２階建，東西棟，切妻造，桟瓦葺，平入の土蔵で，他の酒蔵と同様に左瓦を用いる。外装は土壁で，北側の腰を羽目板付きの板張とし，基部には石を据える。屋敷内で最大規模の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004072"},{"id":"00004074","register_sub_id":"101","register_pk":"105064","name":"松岡家住宅西酒蔵","kana":"まつおかけじゅうたくにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53190429,"lng":133.35185808,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積98㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0142","desc":"屋敷地の西端に位置する。南北棟，切妻造，桟瓦葺で，東酒蔵と並び建ち，東酒蔵内部から平側の入口に導かれる。桁行７間梁間４間規模の平屋建で，外周壁はバットレス付きのＲＣ造壁とする。酒蔵構造の発展過程を物語る遺構。他の酒蔵同様左瓦を使用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004074"},{"id":"00004073","register_sub_id":"101","register_pk":"105063","name":"松岡家住宅東酒蔵","kana":"まつおかけじゅうたくひがしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53190747,"lng":133.3519805,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0141","desc":"槽場の正面西側で槽場とＬ字型に接続する。桁行５間梁間３間半の土蔵造平屋建，桟瓦葺で，南北棟の切妻造，平入とし，前面に下屋を１間張り出し，内部北半を西酒蔵への通路に供する。外装は土佐漆喰塗，一部板張。醸造所敷地を取り囲む主要構成要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004073"},{"id":"00004071","register_sub_id":"101","register_pk":"105061","name":"松岡家住宅槽場","kana":"まつおかけじゅうたくふなば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53198262,"lng":133.35199927,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積189㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0139","desc":"主屋の西側に位置し，東西棟で建つ。桁行８間梁間３間の木造２階建，切妻造，桟瓦葺，平入で，南面に下屋を張り出す。内部の東側を槽場とし，西側の３間四方に麹室を造る。外装は正面を土佐漆喰塗，妻面を土壁とする。屋根に左瓦を用いるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004071"},{"id":"00003473","register_sub_id":"101","register_pk":"104463","name":"松尾酒造北酒蔵","kana":"まつおしゅぞうきたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.60376405,"lng":133.68030197,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積107㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0076","desc":"主屋の南方に位置し，敷地東辺に沿って南北棟で建つ。桁行８間，梁間３間規模，切妻造，桟瓦葺の２階建土蔵で，麹室として建設。 外観は，妻破風を縦板張で覆い，１階を縦板張，２階を白漆喰塗壁とし，東側道路に造り酒屋特有の酒蔵景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003473"},{"id":"00003474","register_sub_id":"101","register_pk":"104464","name":"松尾酒造西酒蔵","kana":"まつおしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.6035681,"lng":133.68022092,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積113㎡","structure_material":"土蔵造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0077","desc":"北酒蔵の西南方に位置し，東西棟で建つ。桁行８間，梁間４間，切妻造，桟瓦葺の平屋建土蔵で，仕込蔵として建設。現在は「松翁酒造りとくらしの資料室」とする。外装は白漆喰塗で，土佐特有の水切り瓦を２段に廻しているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003474"},{"id":"00003475","register_sub_id":"101","register_pk":"104465","name":"松尾酒造南酒蔵","kana":"まつおしゅぞうみなみさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.60360325,"lng":133.6803709,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0078","desc":"北酒蔵の南方，西酒蔵の東南方に位置し，東妻面を道路にみせて東西棟で建つ。桁行５間，梁間３間規模，切妻造，桟瓦葺の２階建土蔵で，貯蔵蔵として建設。東面は北酒蔵と同様に腰を縦板張，妻破風を縦板張で覆い，南面には水切り瓦を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003475"},{"id":"00004184","register_sub_id":"101","register_pk":"105174","name":"陽和工房登窯","kana":"ようわこうぼうのぼりがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市井ノ口乙3472","lat":33.53688582,"lng":133.91277974,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"煉瓦造、奥行20m、幅7m","structure_material":"煉瓦造","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0149","desc":"文化文政頃より始まった内原野焼という陶器窯元の施設。緩やかな斜面に築かれた全長２０ｍ，幅７ｍ，６房からなる連房式登窯で，粘土でかたちづくり，内外に焼粘土塊を張付けて整える。江戸後期の数少ない登窯として，地域の産業史を物語る稀少な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004184"},{"id":"00008597","register_sub_id":"101","register_pk":"134993","name":"石蔵酒造事務所兼主屋","kana":"いしくらしゅぞうじむしょけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市博多区堅粕1-3-6","lat":33.59871415,"lng":130.41750613,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積204㎡、煙突付","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0061","desc":"通りの北側に位置する。間口一八メートルの二階建町家で、桁行に西から土間、事務室、居室の三部分に分かれ、屋根も入母屋と切妻の複雑な構成となる。一階に平格子、二階に漆喰仕上げの大壁に銅板貼の両開戸を設けるなど、意匠性豊かな表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008597"},{"id":"00008598","register_sub_id":"101","register_pk":"134994","name":"石蔵酒造主倉","kana":"いしくらしゅぞうしゅぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県福岡市博多区堅粕1-3-6","lat":33.59886456,"lng":130.41765654,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積974㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0062","desc":"事務所兼主屋の北に位置する。東西棟の切妻造桟瓦葺で、南・北面全面に下屋を付設。桁行三九メートル、梁間は併せて二六メートルに及ぶ。妻面は下見板張とし、鉢巻などを漆喰で仕上げる。二階建で、トラス組が豊かな内部空間をつくる。大規模な酒造倉の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008598"},{"id":"00008599","register_sub_id":"101","register_pk":"134995","name":"石蔵酒造西倉及び旧精米所","kana":"いしくらしゅぞうにしくらおよびきゅうせいまいじょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市博多区堅粕1-3-6","lat":33.59908264,"lng":130.41743093,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積429㎡、渡廊下、煙突及び釜場付","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0063","desc":"敷地の西隅に位置する。通り沿いの旧精米所とその北の西倉からなり、事務所への渡り廊下を付設する。いずれも切妻造桟瓦葺で、西面妻は下見板張、南面は腰高に下見板を張り、上部漆喰仕上げ。下見板の黒色と漆喰の白の鮮やかな対比が趣ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008599"},{"id":"00013895","register_sub_id":"101","register_pk":"507853","name":"浦野醤油醸造元主屋","kana":"うらのしょうゆじょうぞうもとおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県豊前市大字八屋1341-1","lat":33.61696111,"lng":131.117375,"geo_status":"db","era":"明治40年／昭和49年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積217㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"40 － 0187","desc":"中津街道八屋宿の中心部に所在する二階建入母屋造妻入桟瓦葺の商家。二階は観音開き扉や隅石積の漆喰塗で意匠を凝らし、一階は雨戸を備えた開放的な間口としてミセを構え、下手は通り土間、上手は前庭に面した座敷とする。街道宿の面影を伝える豪壮な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013895"},{"id":"00013896","register_sub_id":"101","register_pk":"507854","name":"浦野醤油醸造元塀","kana":"うらのしょうゆじょうぞうもとへい","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県豊前市大字八屋1341-1","lat":33.61706389,"lng":131.11746111,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長4.8m、潜門付","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"40 － 0188","desc":"主屋正面の北角から通りに沿って北に延びる桟瓦葺の塀で、通りと前庭を区切る。延長四・八メートルで、一間毎に柱を立て南から第二間に両開き板戸の門を構える。ほかは漆喰塗真壁として欄間を開け、腰はモルタル塗。主屋と一連で旧街道宿場町の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013896"},{"id":"00010704","register_sub_id":"101","register_pk":"201278","name":"勝屋酒造煙突","kana":"かつやしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県宗像市赤間4-957","lat":33.80478611,"lng":130.58929448,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造、高さ13m","structure_material":"煉瓦造","registered":"2015.08.04(平成27.08.04)","register_no":"40－0133","desc":"店舗兼主屋の後方西寄りに位置する煉瓦造の煙突である。基底部は一辺一・〇メートルの正六角形平面で、高さ一三メートルを測る。躯体はイギリス積を基本として頂部とその下方に蛇腹を廻らし、隅部に山形鋼を添えて補強する。酒造場らしいランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010704"},{"id":"00010703","register_sub_id":"101","register_pk":"201277","name":"勝屋酒造店舗兼主屋","kana":"かつやしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県宗像市赤間4-957","lat":33.80476873,"lng":130.58937583,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積190㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0132","desc":"旧唐津街道に面し、前面に下屋を通す。外壁は漆喰塗込めで両隅に隅石を表す。上下階の前面に格子をたて、下屋の軒を繰形付の腕木で持ち出す。右手に通り土間を配して左手を二列の居室とし、もとミセの事務室や座敷を配する。宿場の面影を伝える造酒屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010703"},{"id":"00010706","register_sub_id":"101","register_pk":"201280","name":"寒北斗酒造安政の蔵","kana":"かんほくとしゅぞうあんせいのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県嘉麻市大隈町字入地1036-1他","lat":33.547489,"lng":130.743946,"geo_status":"db","era":"安政4年（1857）／明治前期改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積199㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0135","desc":"主屋後方に建つ、桁行二二メートル梁間七メートルの長大な土蔵造二階建で、切妻造桟瓦葺である。平側に出入口を開けて下屋を設ける。一階は無柱の大空間を確保し、小屋組は、管柱上の小梁で受ける丑梁に登り梁を架けて組む。建築年代の明らかな幕末の酒蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010706"},{"id":"00010707","register_sub_id":"101","register_pk":"201281","name":"寒北斗酒造仕込蔵","kana":"かんほくとしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県嘉麻市大隈町字入地1036-1他","lat":33.547527,"lng":130.744226,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積272㎡","structure_material":"土蔵造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0136","desc":"敷地南東隅に建つ仕込蔵。桁行二〇メートル梁間一四メートルと大規模で、切妻造桟瓦葺である。外壁は漆喰塗で腰に竪板を張り、窓を千鳥に配して表情を創る。キングポストトラスを採用して無柱の大空間を実現し、近代的発展を示す酒蔵で、街路景観にも寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010707"},{"id":"00010705","register_sub_id":"101","register_pk":"201279","name":"寒北斗酒造店舗兼主屋","kana":"かんほくとしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県嘉麻市大隈町字入地1036-1他","lat":33.547661,"lng":130.743841,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積404㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0134","desc":"秋月街道沿いの造酒屋。入母屋造妻入の外部を鼠漆喰で塗込め、重厚な外観を見せる。左手を広い土間、右手に事務所や中の間等を並べ、さらに右側面の前後に角座敷を張出して中庭を囲み、発展的平面を示す。上質な客間をもつ幕末の酒造所施設として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010705"},{"id":"00010702","register_sub_id":"101","register_pk":"201276","name":"旧出光家住宅主屋","kana":"きゅういでみつけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県宗像市赤間4-888","lat":33.805828,"lng":130.590347,"geo_status":"db","era":"明治26年／昭和中期改修","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0131","desc":"旧唐津街道に面する町家で、左手の土間部は屋根を落棟とする。中央の通り土間の右手にミセ、中の間などを並べ、中の間は吹抜けとして上部に高欄を飾る。旧の土間は広く、藍甕が据えられていた。正面柱筋に摺上戸を残すなど、赤間宿の町家の形態をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010702"},{"id":"00014976","register_sub_id":"101","register_pk":"519236","name":"旧國武合名会社倉庫","kana":"きゅうくにたけごうめいがいしゃそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市日吉町字三丁目117-1","lat":33.31588889,"lng":130.51609444,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木骨煉瓦造2階建、瓦葺、建築面積134㎡","structure_material":"木骨煉瓦造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0222","desc":"久留米旧城下に位置する久留米絣の旧商品庫。二階建切妻造平入桟瓦葺。外壁を鉱滓煉瓦の小口積とする木骨煉瓦造で中央西寄りにアーチの入口を開け、正面に鉄扉を吊る。内部は各階板敷で和小屋を現す。正面アーチに社標を掲げ、地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014976"},{"id":"00014975","register_sub_id":"101","register_pk":"519235","name":"旧國武合名会社綿糸部店舗及び倉庫","kana":"きゅうくにたけごうめいがいしゃめんしぶてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県久留米市日吉町字二丁目71-4","lat":33.31609722,"lng":130.51568333,"geo_status":"db","era":"大正11年／昭和前期、平成27年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造一部木骨煉瓦造2階建、瓦葺、建築面積151㎡","structure_material":"木造一部木骨煉瓦造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0221","desc":"久留米旧城下に位置する久留米絣製造販売業の旧店舗及び倉庫。角地に建つ木造二階建入母屋造桟瓦葺南北棟で北に木骨煉瓦造東西棟の倉庫を接続する。旧店舗は西と南に腕木を重ねた出桁庇を廻らす豪壮な外観とし、旧倉庫は西妻に社標を掲げてアクセントとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014975"},{"id":"00006661","register_sub_id":"101","register_pk":"107644","name":"旧上妻家住宅（津屋崎千軒民俗館藍の家）井戸屋形","kana":"きゅうこうづまけじゅうたく（つやざきせんげんみんぞくかんあいのいえ）いどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎4-935","lat":33.78940048,"lng":130.46308431,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、桧皮葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"40 － 0058","desc":"主屋の東背面、裏庭の中央に位置する。井戸枠は方１．０ｍの人造石研出し仕上げで、四隅に内転びの柱を立て、六角屋根を架ける。屋根は檜皮で葺き、竹で押さえる。西面と北面に壁があり、それぞれ円形と方形の下地窓を開く。数寄屋風意匠をもつ遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006661"},{"id":"00006660","register_sub_id":"101","register_pk":"107643","name":"旧上妻家住宅（津屋崎千軒民俗館藍の家）主屋","kana":"きゅうこうづまけじゅうたく（つやざきせんげんみんぞくかんあいのいえ）しゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎4-935","lat":33.789452,"lng":130.463028,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"40 － 0057","desc":"通りに西面する木造２階建の平入町家。桁行６間梁間４間半の切妻造桟瓦葺で、表裏に庇が付き、背面に渡廊下で便所が接続。正面中央の戸口の両脇を格子で飾る。２階壁は白漆喰塗で、窓枠を塗り出す。内部は南が土間で北に喰違いに５室を配す。明治期町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006660"},{"id":"00006286","register_sub_id":"101","register_pk":"107270","name":"旧サッポロビール九州工場組合棟","kana":"きゅうさっぽろびーるきゅうしゅうこうじょうくみあいとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区大里本町3-6-103他","lat":33.905949,"lng":130.931732,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積108㎡","structure_material":"煉瓦造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"40 － 0048","desc":"醸造棟の北側に近接して建つ。桁行１２ｍ，梁間９ｍ規模で，煉瓦造平屋建，切妻造，鉄板葺とする。床を地盤面より１．７ｍ高くつくる。北面に扉口を開き，周囲にアーチ窓を開く。柱形を外に見せ，要に石材を使い，妻壁にパラペットを立上げ，重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006286"},{"id":"00006284","register_sub_id":"101","register_pk":"107268","name":"旧サッポロビール九州工場事務所棟","kana":"きゅうさっぽろびーるきゅうしゅうこうじょうじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区大里本町3-6-104","lat":33.906219,"lng":130.931763,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積232㎡、塔屋付","structure_material":"煉瓦造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"40 － 0046","desc":"関門海峡沿いの国道１９９号東側敷地に西面して建つ。桁行１９ｍ，梁間１４ｍで，煉瓦造２階建とする。正面中央玄関部を突出させ塔状に３階高まで立ち上げ，１・２階共に左右対称の意匠として中心性を強調する。鉱滓煉瓦を使用し，細部意匠にも工夫がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006284"},{"id":"00006285","register_sub_id":"101","register_pk":"107269","name":"旧サッポロビール九州工場醸造棟","kana":"きゅうさっぽろびーるきゅうしゅうこうじょうじょうぞうとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区大里本町3-6-103他","lat":33.905724,"lng":130.931366,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建・3階建・4階建及び7階建、鉄板葺，建築面積1180㎡","structure_material":"煉瓦造2階建・3階建・4階建及び7階建","registered":"2007.07.31(平成19.07.31)","register_no":"40 － 0047","desc":"事務所棟の南側に建つ。南北５５ｍ，東西２７ｍの規模の煉瓦造で，２階建，３階建，４階建，７階建の建物をほぼコの字状に連結して並べ，周囲にアーチ窓を開く。ビールの製造工程に従って高さの異なる建物が組み合わされ，大規模な特徴のある多様な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006285"},{"id":"00006287","register_sub_id":"101","register_pk":"107271","name":"旧サッポロビール九州工場倉庫","kana":"きゅうさっぽろびーるきゅうしゅうこうじょうそうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区大里本町3-6-103他","lat":33.90649037,"lng":130.93141798,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積1050㎡","structure_material":"煉瓦造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"40 － 0049","desc":"事務所棟の道路を隔てて西側に建つ。桁行３３ｍ，梁間２９ｍの規模で，煉瓦造２階建，切妻造，鉄板葺を並列に２連に並べる。妻面に扉口を開き，上部を円形窓としていた。小屋組はクイーンポスト形式で，倉庫の大空間を確保している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006287"},{"id":"00014977","register_sub_id":"101","register_pk":"519237","name":"九州建具木工所倉庫","kana":"きゅうしゅうたてぐもっこうじょそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津124他","lat":33.20634167,"lng":130.37070556,"geo_status":"db","era":"昭和31年／平成元年頃改修","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積308㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0223","desc":"木工業で繁栄した筑後川河口の小保に建つ木工所の倉庫。切妻造妻入で正面二階中央に四連の縦長窓を開け、前面に迫出しパラペットを立上げる。小屋組は対束間の母屋を束で受けた変則的なクイーンポスト・トラス。モダンな外観が戦後の木工業の繁栄を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014977"},{"id":"00006467","register_sub_id":"101","register_pk":"107450","name":"旧三井田川鉱業所伊田竪坑第一煙突","kana":"きゅうみついたがわこうぎょうしょいだたてこうだいいちえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県田川市大字伊田2734-1","lat":33.64033218,"lng":130.81515919,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造、高さ45m","structure_material":"煉瓦造","registered":"2007.10.02(平成19.10.02)","register_no":"40 － 0052","desc":"竪坑櫓より約１２０ｍ南方に位置する。旧汽罐場に付属する高さ４５ｍ（１５０尺）の煉瓦造円形煙突で、全体をイギリス積で精緻に築き、基部には半円アーチ形の煙道を一部残す。現存する明治期の煉瓦煙突として最大級の規模を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006467"},{"id":"00006491","register_sub_id":"101","register_pk":"107474","name":"旧三井田川鉱業所伊田竪坑第二煙突","kana":"きゅうみついたがわこうぎょうしょいだたてこうだいにえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県田川市大字伊田2734-1","lat":33.64039073,"lng":130.8150041,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造、高さ45m","structure_material":"煉瓦造","registered":"2007.10.02(平成19.10.02)","register_no":"40 － 0053","desc":"第一煙突から約２５ｍ西に位置する。旧汽罐場に付属する高さ４５ｍ（１５０尺）の煉瓦造煙突で、全体をイギリス積で築き、基部を八角形断面、他の部分を円形断面とする。竪坑、第一煙突と共に「炭鉱節」に謡われた構造物として知られ、筑豊の繁栄の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006491"},{"id":"00006466","register_sub_id":"101","register_pk":"107449","name":"旧三井田川鉱業所伊田竪坑櫓","kana":"きゅうみついたがわこうぎょうしょいだたてこうやぐら","category":"産業2次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県田川市大字伊田2734-1","lat":33.64146314,"lng":130.814993,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"鉄骨造、高さ28m","structure_material":"鉄骨造","registered":"2007.10.02(平成19.10.02)","register_no":"40 － 0051","desc":"市のほぼ中心部に位置する旧鉱山施設。Ⅰ形鋼を用いた４本の鋼柱等からなる鋼構造体の頂部に、２基の大型ヘッドシーブを据え付けて総高２８ｍとし、西側にはバックステイを添える。筑豊に残る唯一の鋼製櫓で、現存する明治期の竪坑櫓として最大級の規模を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006466"},{"id":"00010528","register_sub_id":"101","register_pk":"199468","name":"ジョーキュウ醤油裏座敷","kana":"じょーきゅうしょうゆうらざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-1","lat":33.587894,"lng":130.394971,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0120","desc":"敷地西辺、表座敷の北側に建つ。木造二階建で一階の三方に下屋の廊下を廻らし、上下階とも座敷二室を配する。一階の座敷飾は平書院の手前に略三角形の棚板を付けて付書院風に見せ、また床脇の地袋、天袋を台形平面とするなど昭和期らしい凝った意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010528"},{"id":"00010533","register_sub_id":"101","register_pk":"199473","name":"ジョーキュウ醤油煙突","kana":"じょーきゅうしょうゆえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-4","lat":33.587874,"lng":130.395294,"geo_status":"db","era":"大正4／平成17改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造、高さ9.5m、面積2.5㎡","structure_material":"煉瓦造","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0125","desc":"敷地南東の火入れ場に残る煉瓦造煙突。底部は一辺六七センチメートルの八角形平面で基礎を二段に迫り出し、高さ九・五メートルである。躯体はイギリス積で、久留米の荒木窯業の施工と伝わる。震災で高さを減じているが醸造所を象徴する施設として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010533"},{"id":"00010527","register_sub_id":"101","register_pk":"199467","name":"ジョーキュウ醤油表座敷","kana":"じょーきゅうしょうゆおもてざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-1","lat":33.5878,"lng":130.395006,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積44㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0119","desc":"敷地南西隅に位置する木造二階建、切妻造桟瓦葺の接客用座敷で、南北に下屋を設けて縁とする。上下階とも二室の座敷からなり、一階の南室を八畳主室として座敷飾を備え、二階北室は窓辺に高欄を設ける。醸造所の一隅を占める、良質な接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010527"},{"id":"00010530","register_sub_id":"101","register_pk":"199470","name":"ジョーキュウ醤油米蔵","kana":"じょーきゅうしょうゆこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-3","lat":33.587974,"lng":130.395026,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0122","desc":"納戸蔵の東、敷地の中央に建つ二階建土蔵。南北棟で、南の中庭に向けて銅板葺の庇を付けた出入口を設ける。内部の壁は板張、小屋組は登梁形式として、二階の南北に窓をあける。現在は醤油醸造に使用する道具類を納めており、醸造所の敷地景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010530"},{"id":"00010531","register_sub_id":"101","register_pk":"199471","name":"ジョーキュウ醤油仕込蔵","kana":"じょーきゅうしょうゆしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-3","lat":33.587985,"lng":130.39509,"geo_status":"db","era":"文久2(1862)","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積123㎡","structure_material":"土蔵造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0123","desc":"敷地の中央、米蔵の東側に南北棟で建つ大型の土蔵で、切妻造桟瓦葺である。建ちの高い平屋建で、南半部には仕込み桶の上から作業ができるよう仮設的な床を張る。和小屋の小屋組の下に天井を張る。仕込蔵の特徴をよく備えた、醤油醸造所を象徴する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010531"},{"id":"00002098","register_sub_id":"101","register_pk":"103088","name":"鶴味噌並倉北棟","kana":"つるみそなみくらきたとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県柳川市三橋町江曲216","lat":33.1607939,"lng":130.40921087,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積62㎡","structure_material":"煉瓦造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"40 － 0016","desc":"三橋町と柳川市との境を流れる掘割に沿って建つ。煉瓦造平屋建，切妻造桟瓦葺の旧麹室で，鋸歯飾りをあしらった胴蛇腹，妻面に円形換気窓を設ける。中棟との間に設けた庇部に，妻面に合わせて煉瓦壁を延ばし，半円アーチ形の開口部を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002098"},{"id":"00002099","register_sub_id":"101","register_pk":"103089","name":"鶴味噌並倉中棟","kana":"つるみそなみくらなかとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県柳川市三橋町江曲216","lat":33.16074311,"lng":130.40921404,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"煉瓦造平屋建、瓦葺、建築面積45㎡","structure_material":"煉瓦造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"40 － 0017","desc":"３棟の内，煉瓦造蔵として最初に建てられたと伝わる。妻面を木造横板貼とし，フランス積の壁面に北・南棟で模される櫛形アーチ開口部を２箇所設ける。登梁を中柱で支えた和小屋を載せる。他棟と類似しつつ，微妙に変化をもつ外観が水辺景観を豊かにしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002099"},{"id":"00002100","register_sub_id":"101","register_pk":"103090","name":"鶴味噌並倉南棟","kana":"つるみそなみくらみなみとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県柳川市三橋町江曲216","lat":33.16068712,"lng":130.40921548,"geo_status":"db","era":"明治39頃／大正7増築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積70㎡","structure_material":"煉瓦造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"40 － 0018","desc":"北棟と類似した外観。キングポストトラスの小屋組を載せ，小規模な切妻屋根を冠す中棟との間隙に煉瓦壁を築き，鋸歯飾りの胴蛇腹によって主棟との連続性を持つ。３棟の煉瓦妻面が掘割に面する並倉は，水郷柳川の歴史的景観形成に大きく寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002100"},{"id":"00010699","register_sub_id":"101","register_pk":"201273","name":"松岡家住宅玄関門","kana":"まつおかけじゅうたくげんかんもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2","lat":33.423175,"lng":130.583249,"geo_status":"db","era":"嘉永3年（1850）／大正12年頃移築","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"40－0128","desc":"主屋の入母屋玄関の前方に、西向きに構える門。間口二・二メートル、一間薬医門、切妻造桟瓦葺である。軸部はクスノキを主材とし、冠木上に矩形の梁を三筋渡して疎垂木の軒を受ける。左右にのびる煉瓦塀とともに、風格のある庭空間を創出する表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010699"},{"id":"00010697","register_sub_id":"101","register_pk":"201271","name":"松岡家住宅主屋","kana":"まつおかけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2","lat":33.423235,"lng":130.583306,"geo_status":"db","era":"大正12年／昭和50年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積380㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0126","desc":"南面する主体部は建ちの高い入母屋造妻入で正面に入母屋玄関を構える。西端の土間の高い吹抜けでは幾重にも組上げた力感ある梁組を現すなど重厚な軸組になる。また東側に張出す十五畳の広間は銘木を用いて上質な造作としており、当地の大型民家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010697"},{"id":"00010698","register_sub_id":"101","register_pk":"201272","name":"松岡家住宅倉庫","kana":"まつおかけじゅうたくそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2","lat":33.423382,"lng":130.583334,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0127","desc":"主屋後方に張出す配膳室に接続して東西棟で建つ。桁行一四メートル梁間四メートル、切妻造桟瓦葺で、東寄りに換気用の越屋根を設ける。外壁は真壁漆喰塗で腰に竪板を張り、内部東寄りで二室に仕切る。従業員の食堂などに使われた建物で酒造場の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010698"},{"id":"00010701","register_sub_id":"101","register_pk":"201275","name":"松岡家住宅塀","kana":"まつおかけじゅうたくへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2他","lat":33.42311,"lng":130.58317,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"煉瓦造、総延長89m","structure_material":"煉瓦造","registered":"2015.08.04(平成27.08.04)","register_no":"40－0130","desc":"主屋の前庭を囲み、敷地南面に折曲がりにのびる煉瓦塀で総延長八九メートルを測る。江戸切仕上げの花崗岩積基礎の上に鉱滓煉瓦をイギリス積とし、頂部に軒蛇腹三段積と屋根二段積を施す。特に敷地南西隅は円弧状平面として技巧的に仕上げ集落景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010701"},{"id":"00010700","register_sub_id":"101","register_pk":"201274","name":"松岡家住宅門柱","kana":"まつおかけじゅうたくもんちゅう","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2他","lat":33.423146,"lng":130.583163,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"石造門柱2基、間口4.5m","structure_material":"石造門柱2基","registered":"2015.08.04(平成27.08.04)","register_no":"40－0129","desc":"主屋南東隅西側の通路入口に位置し、花崗岩製の門柱一対を間口四・五メートルに立てる。石柱は一辺四五センチメートル、高さ三・五メートルの江戸切仕上げとし、柱天に帯状の飾りを付ける。酒造場への入口をなしていた門柱で、往時の敷地景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010700"},{"id":"00013667","register_sub_id":"101","register_pk":"504611","name":"吉原家住宅主屋及び角座敷","kana":"よしはらけじゅうたくおもやおよびつのざしき","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津107-2-2他","lat":33.20572778,"lng":130.37113889,"geo_status":"db","era":"主屋 江戸後期、角座敷 天保9年(1838)／昭和中期以前・同63年・平成6年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積333㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0183","desc":"大川市小保の旧街道沿いに東面して建つ。主屋は二階建切妻造桟瓦葺妻入で、四周に庇を廻し正面に下屋を付す。漆喰を軒先まで塗込め、内部は北を土間、南を床上部とする。南に平屋建切妻造の角座敷を接続し玄関を付す。小保の町並を代表する大型町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013667"},{"id":"00013668","register_sub_id":"101","register_pk":"504612","name":"吉原家住宅煉瓦塀","kana":"よしはらけじゅうたくれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津107-2-2他","lat":33.20575833,"lng":130.37121111,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、延長6.3m","structure_material":"煉瓦造","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0184","desc":"主屋の東南角から通りに沿って南に延びる煉瓦造の塀。延長六メートルで、高さ二メートルの規模である。煉瓦は平目地として、頂部は軒蛇腹で飾り、煉瓦で屋根を造る。主屋の東南の腰壁にも煉瓦が積まれて一連の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013668"},{"id":"00009862","register_sub_id":"101","register_pk":"195691","name":"天吹酒造旧蔵人用炊事場煙突","kana":"あまぶきしゅぞうきゅうくらびとようすいじばえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32670159,"lng":130.4574745,"geo_status":"db","era":"明治後期／昭和後期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、高さ7.3m","structure_material":"煉瓦造","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0091","desc":"主屋北面東寄りに建つ煉瓦煙突で、イギリス積とする。基部の平面は一・二メートル角で、高さは七・三メートルである。腰部に帯状の迫出しを設け、東面基部に欠円アーチの焚き口を作る。もと従業員賄い用の釜屋に附属していた煙突で、蔵元の生活様態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009862"},{"id":"00009863","register_sub_id":"101","register_pk":"195692","name":"天吹酒造旧酒造蔵煙突","kana":"あまぶきしゅぞうきゅうしゅぞうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字村副2290-1","lat":33.32633754,"lng":130.45760001,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ11m","structure_material":"煉瓦造","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0092","desc":"貯蔵庫（旧白米倉庫）の北側に建つ煉瓦煙突。煉瓦造、イギリス積で、基部の平面は直径一・四メートルの六角形とし、高さは一一メートルを測る。腰部と頂部に装飾的な帯状部を設け、東面基部に欠円アーチの焚き口を作る。酒造場を象徴する煉瓦煙突である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009863"},{"id":"00009858","register_sub_id":"101","register_pk":"195687","name":"天吹酒造仕込蔵","kana":"あまぶきしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32714893,"lng":130.45749472,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積665㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0087","desc":"主屋後方に南北棟で建つ。桁行三九メートル梁間一七メートル、土蔵造二階建、妻入、桟瓦葺で、南北面に下屋を設ける。外壁は軒先まで漆喰塗込めとし、腰を竪板張とする。内部柱に太い丸太を使い、小屋は登り梁と和小屋を併用する。雄大な規模の仕込蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009858"},{"id":"00009855","register_sub_id":"101","register_pk":"195684","name":"天吹酒造主屋","kana":"あまぶきしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32663021,"lng":130.45745189,"geo_status":"db","era":"明治中期／明治34改修、大正期増築、昭和後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部3階建、瓦葺、建築面積315㎡","structure_material":"木造2階一部3階建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0084","desc":"北側敷地の南端に南面し、木造二階一部三階建、入母屋造桟瓦葺で、外壁は漆喰塗とする。内部は中央に土間を通し、東半に既存の土蔵を取込み、事務所や応接間を配する。西半の床上部は東西二列に仏間や座敷などの居室を並べる。伝統的な住宅形式を伝る主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009855"},{"id":"00009859","register_sub_id":"101","register_pk":"195688","name":"天吹酒造地下貯蔵庫","kana":"あまぶきしゅぞうちかちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32715369,"lng":130.45727105,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"鉄筋コンクリート造平屋建、建築面積477㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0088","desc":"北側敷地北西の斜面地に東西棟で建ち、東妻の入口は地上に開くが、西側は地中となる。桁行三〇メートル梁間一六メートル、鉄筋コンクリート造平屋建で、内部は南北二室に区分され、各々東妻に出入口を設ける。現在も冷蔵庫として使用されている貯蔵施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009859"},{"id":"00009857","register_sub_id":"101","register_pk":"195686","name":"天吹酒造貯蔵庫（旧麹室）","kana":"あまぶきしゅぞうちょぞうこ（きゅうこうじむろ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.3267468,"lng":130.45755897,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造及び木造平屋建、瓦葺、建築面積78㎡","structure_material":"煉瓦造及び木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0086","desc":"主屋北東側に東西棟で建つ。桁行一六メートル梁間五メートル、南面煉瓦造、北面木造、平屋建、切妻造桟瓦葺で、西妻面を戸口として瓦庇を付す。南面は煉瓦壁を現し、北面竪板張とする。内部は一室で小屋は和小屋を組む。特異な軸部構成の貯蔵庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009857"},{"id":"00009860","register_sub_id":"101","register_pk":"195689","name":"天吹酒造貯蔵庫（旧白米倉庫）","kana":"あまぶきしゅぞうちょぞうこ（きゅうはくまいそうこ）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32623522,"lng":130.45760894,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積113㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0089","desc":"南側敷地の北寄りに南北棟で建つ。桁行一四メートル梁間六・一メートル、土蔵造平屋建、切妻造桟瓦葺で、西面に吹放しの下屋を設ける。外壁漆喰塗で、腰は東面を海鼠壁、西面は竪板張とする。内部は一室で小屋は和小屋を組む。田園風景に白壁が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009860"},{"id":"00009856","register_sub_id":"101","register_pk":"195685","name":"天吹酒造離れ座敷","kana":"あまぶきしゅぞうはなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32677298,"lng":130.45733292,"geo_status":"db","era":"大正期／昭和中期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0085","desc":"主屋北西部に接続する。木造平屋建、入母屋造桟瓦葺で、周囲に下屋を廻らす。八畳主室の北側にトコ、床脇、付書院を備え、南東に縁を配す。南側に張出す二畳の小間にも小振りの座敷飾を設け、円窓を穿つ。開放的な室内構成で、造作も瀟洒な離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009856"},{"id":"00009861","register_sub_id":"101","register_pk":"195690","name":"天吹酒造瓶詰工場（旧仕込蔵）","kana":"あまぶきしゅぞうびんづめこうじょう（きゅうしこみぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32598776,"lng":130.45762797,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積561㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0090","desc":"南側敷地の南端に南北棟で建つ。桁行四〇メートル梁間一四メートル、木造二階建、切妻造桟瓦葺で、北面を下屋とする。外壁漆喰塗で腰高に竪板を張り、軒下に高窓を並べる。小屋は登り梁と和小屋を併用する。酒造場の表構えを引き立てる大規模建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009861"},{"id":"00005677","register_sub_id":"101","register_pk":"106665","name":"飯盛酒造一号蔵及び二号蔵","kana":"いいもりしゅぞういちごうぐらおよびにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09204848,"lng":130.11393641,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積365㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0061","desc":"敷地の南辺に沿って土蔵造２階建の一号蔵が建ち，東の麹室との間を木造平屋建，片流れ屋根の二号蔵が繋ぐ。一号蔵は桁行１０間，梁間６間の切妻造桟瓦葺で，外壁を竪羽目板張で覆う。小屋組は束立の和小屋である。二号蔵は台形平面でトラス小屋組とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005677"},{"id":"00005680","register_sub_id":"101","register_pk":"106668","name":"飯盛酒造煙突","kana":"いいもりしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09231045,"lng":130.11408841,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造、高さ9m","structure_material":"煉瓦造","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0064","desc":"主屋の東側，釜場の北側に位置する。主屋土間の外壁に沿うように建つ煉瓦造煙突である。一辺約１．５ｍの正方形で，高さ約９ｍ。鉄製の補強枠が取り付けられている。飯盛家が取得する以前の醸造銘柄「玉の香」の文字が北面に残る。酒蔵通りを象徴する遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005680"},{"id":"00005679","register_sub_id":"101","register_pk":"106667","name":"飯盛酒造麹室","kana":"いいもりしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09212174,"lng":130.11408445,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"煉瓦造平屋建、瓦葺、建築面積49㎡","structure_material":"煉瓦造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0063","desc":"敷地の南東角に位置する煉瓦造平屋建である。三号蔵の南面に接続し，敷地形状に合わせて西面がやや開いた台形平面を持つ。桁行４間，梁間３間規模の南北棟で，切妻造，桟瓦葺の洋風トラス小屋組の木造屋根を架ける。敷地東側の景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005679"},{"id":"00005678","register_sub_id":"101","register_pk":"106666","name":"飯盛酒造三号蔵","kana":"いいもりしゅぞうさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09222062,"lng":130.11401812,"geo_status":"db","era":"大正末期／昭和初期増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造2階建、瓦葺、建築面積151㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0062","desc":"敷地の東辺，主屋土間の裏手に建つ土蔵造２階建である。南に麹室が接続する。桁行５間，梁間は４間で西側に２間幅を葺下ろした切妻造，桟瓦葺とする。小屋組は束立の和小屋である。槽場及び瓶詰め場として使われた。西側に下屋で検査室と休憩所を増築した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005678"},{"id":"00014124","register_sub_id":"101","register_pk":"508384","name":"旧枝梅酒造店舗兼主屋","kana":"きゅうえだうめしゅぞうてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市八戸一丁目124-2","lat":33.24737222,"lng":130.27799167,"geo_status":"db","era":"江戸末期／平成30年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積200㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0126","desc":"旧長崎街道に南面する造り酒屋の町家。二階建寄棟造桟瓦葺平入で背後に棟を延ばし、全体にコの字の屋根とする。正面は下屋を付し、ニ階は軒まで塗込める。内部は東を土間、西を二列五室とする。佐賀特有のくど造の様相を伝え、建ちが低く全体に古式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014124"},{"id":"00004190","register_sub_id":"101","register_pk":"105180","name":"旧杵島炭鉱大鶴鉱業所第二坑口","kana":"きゅうきしまたんこうおおづるこうぎょうしょだいにこうぐち","category":"産業2次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県唐津市肥前町大字入野甲1-3","lat":33.45078328,"lng":129.83470219,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"コンクリート造及び煉瓦造、間口7.0m","structure_material":"コンクリート造及び煉瓦造","registered":"2004.06.09(平成16.06.09)","register_no":"41 － 0044","desc":"石炭搬出のため建造された。コンクリート造で，坑門と約７ｍの坑道からなる。坑門は両端部を柱型とし，凸状頂部にはコーニスをつけ，中央に直径約４ｍの半円形坑口を開き，表面は洗い出し仕上げとする。田園地帯にあって，炭鉱施設の一端を今に伝える構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004190"},{"id":"00004473","register_sub_id":"101","register_pk":"105463","name":"呉竹酒造一番蔵","kana":"くれたけしゅぞういちばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2751","lat":33.092224,"lng":130.117355,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積483㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0050","desc":"主屋の東に棟を並べて建つ。南北棟，入母屋造，桟瓦葺，妻入の２階建酒蔵で，桁行９間梁間８間規模。中央を作業場とし，主屋寄りの西側に米洗所・釜場などを配し，東面に東西棟の精米所と南北棟の麹室を付属する。改造はあるが，酒造場の中核となる施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004473"},{"id":"00004474","register_sub_id":"101","register_pk":"105464","name":"呉竹酒造東の蔵","kana":"くれたけしゅぞうひがしのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2751","lat":33.09242747,"lng":130.11735287,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積591㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0051","desc":"主屋及び一番蔵の北方に位置し，敷地北辺道路に沿って東西棟で建つ。桁行１８間梁間７間規模，切妻造，桟瓦葺，平入の２階建仕込蔵で，西側を貯蔵庫と分析試験室，東側を槽場に充てる。北面外部は高い腰部を縦板張，上部を白漆喰塗として小窓を３段に開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004474"},{"id":"00013768","register_sub_id":"101","register_pk":"505333","name":"光栄菊酒造洗い場及び釜場","kana":"こうえいぎくしゅぞうあらいばおよびかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29938889,"lng":130.22613333,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 115","desc":"通り蔵の北に軸を振って接続する。木造平家建切妻造桟瓦葺で南北棟の洗い場と釜場を東西に並べ、南北に谷樋を通す。西面に開口を多くとり、洗い場の屋根に採光窓を設ける。釜場の大釜は土間を掘込んで据え、外部の煙突に接続する。酒造施設の一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013768"},{"id":"00013772","register_sub_id":"101","register_pk":"505341","name":"光栄菊酒造煙突","kana":"こうえいぎくしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29938333,"lng":130.22624167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、高さ11m","structure_material":"煉瓦造","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 119","desc":"釜場の東に位置。一・七メートル四方、高さ一・六メートルの煉瓦造基壇上に総高約一一メートルを煉瓦造イギリス積で積む。上方に向けて先細りし、最上部の煙口に四段の繰形を付ける。四方の隅部は鉄枠で補強する。地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013772"},{"id":"00013771","register_sub_id":"101","register_pk":"505339","name":"光栄菊酒造旧麹室","kana":"こうえいぎくしゅぞうきゅうこうじむろおよびつうろ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.2991,"lng":130.22648333,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 118","desc":"本蔵の東、ムロマエの南面に接続。木造平屋建切妻造桟瓦葺で、水路石積上に御影石の布基礎を廻し、高さ三メートルまで煉瓦積の壁を木造軸組の外面に化粧で現す。上部は竪板張で南面上部に開口を開ける。小屋組はキングポストトラス。敷地南東の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013771"},{"id":"00013767","register_sub_id":"101","register_pk":"505331","name":"光栄菊酒造通り蔵及び本蔵","kana":"こうえいぎくしゅぞうとおりぐらおよびほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29919444,"lng":130.22626389,"geo_status":"db","era":"通り蔵 大正9年／昭和11年改修、本蔵 昭和2年／昭和11年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積955㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 114","desc":"小城市の旧街道に面する酒造施設。木造二階建半切妻造桟瓦葺で南北棟の通り蔵と本蔵を東西に並べ、南端で接続してコの字形平面をなす。本蔵北に下屋付属。各蔵とも二列の独立柱を立て、吹抜の接続部は豪壮な小屋組をみせる。南面の大屋根が景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013767"},{"id":"00013770","register_sub_id":"101","register_pk":"505337","name":"光栄菊酒造ムロマエ","kana":"こうえいぎくしゅぞうむろまえ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29920833,"lng":130.22647778,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 117","desc":"本蔵の東、モトクラの南面に接続。木造平屋建両下造桟瓦葺。外部は腰を竪板張とし、上部は現在下見板張とするが旧は漆喰仕上。布基礎の上に煉瓦を数段積み柱を立てる。内部は二階の床組を一部残し小屋組は二重梁和小屋。施設内最古で酒造施設の歴史上重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013770"},{"id":"00013769","register_sub_id":"101","register_pk":"505335","name":"光栄菊酒造モトクラ","kana":"こうえいぎくしゅぞうもとくら","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29935,"lng":130.22645556,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 116","desc":"本蔵東面北端に接続。木造平屋建北面半切妻造南面切妻造で桟瓦葺。御影石の布基礎、土台上に柱を立て、外壁は竪板張。北・東面は一間毎に掃出窓を設け北面上部に水切庇付きの開口を開く。内部は二階の床組を残し小屋組は二重梁和小屋。敷地北東の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013769"},{"id":"00002717","register_sub_id":"101","register_pk":"103707","name":"小柳酒造煙突","kana":"こやなぎしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29874649,"lng":130.20257123,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"煉瓦造、高さ17m","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0032","desc":"釜場南妻面西端の前に建つ。１．８ｍ角，高さ１６．５ｍ，上にいくほどすぼまる形態のイギリス積煉瓦造煙突で，頂部はバンドを廻しモルタル塗仕上げとする。昭和西蔵の棟高をはるかに越え，周囲に造り酒屋の存在を知らしめる格好のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002717"},{"id":"00002716","register_sub_id":"101","register_pk":"103706","name":"小柳酒造釜場","kana":"こやなぎしゅぞうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29881342,"lng":130.2026424,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0031","desc":"昭和西蔵の東に接して建つ。桁行１１ｍ，梁間９ｍ規模，南北棟，桟瓦葺，切妻造の平屋建で，棟中央に換気用の越屋根を載せる。外壁は縦羽目を主とし，南妻には繊細なキングポストトラスの架構を見せて東蔵北妻面とは対照的な表情を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002716"},{"id":"00002725","register_sub_id":"101","register_pk":"103715","name":"小柳酒造検査室","kana":"こやなぎしゅぞうけんさしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1、904-1","lat":33.29867319,"lng":130.20248844,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0040","desc":"昭和西蔵の南方に建つ。桁行５．４ｍ，梁間３．６規模，東西棟，桟瓦葺，切妻造の木造平屋建で，東妻に入口を設ける。外観は，下見板張りとし，南，東，北の３面に引違いガラス窓を建込む。昭和初期酒税検査の様子の一端を窺い知ることのできる施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002725"},{"id":"00002722","register_sub_id":"101","register_pk":"103712","name":"小柳酒造麹室","kana":"こやなぎしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29890586,"lng":130.20226149,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0037","desc":"敷地の西北隅部に位置する。桁行１１ｍ，梁間６．５ｍ規模で，東西棟，切妻造，桟瓦葺とする。木造，平屋建で，外観は縦羽目板張とするが，入口のある正面妻側は梁下までイギリス積の煉瓦壁とする特異な造りとなる。造り酒屋にとって欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002722"},{"id":"00002714","register_sub_id":"101","register_pk":"103704","name":"小柳酒造昭和西蔵","kana":"こやなぎしゅぞうしょうわにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.298889,"lng":130.202438,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積431㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0029","desc":"主屋の西方，水路を隔てた醸造場敷地のほぼ中央に建つ。桁行３４ｍ，梁間１３ｍ規模の２階建大蔵で，腰を高い煉瓦積，外壁を簓子下見風とし，屋根は南北棟の桟瓦葺，寄棟造で南北の妻面を半切妻状に納める特徴的な外観を呈する。醸造場施設の中核的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002714"},{"id":"00002715","register_sub_id":"101","register_pk":"103705","name":"小柳酒造昭和東蔵","kana":"こやなぎしゅぞうしょうわひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29901349,"lng":130.20260926,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0030","desc":"昭和西蔵の東に並び建つ。桁行１４ｍ，梁間８ｍ規模，南北棟，桟瓦葺，切妻造の２階建で，内部は西壁を西蔵と共有し，西・南壁に出入口を設ける。外観は，腰を煉瓦積，外壁を押縁間隔の広い下見板張として洋風に見せるなど水路沿いに特色ある景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002715"},{"id":"00002718","register_sub_id":"101","register_pk":"103708","name":"小柳酒造西貯水槽","kana":"こやなぎしゅぞうにしちょすいそう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29875437,"lng":130.20259251,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"煉瓦造、建築面積4.8㎡","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0033","desc":"煙突の東面及び釜場南面に接して建つ。１．７ｍ×２．８ｍの長方形平面で，高さ４．５ｍ。煉瓦造柱脚の上に水槽を築き，頂部に生子鉄板による南北棟の招き屋根を架ける。水槽部には現在２条の開き止め鉄棒を廻している。醸造施設の近代化を示す遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002718"},{"id":"00002719","register_sub_id":"101","register_pk":"103709","name":"小柳酒造東貯水槽","kana":"こやなぎしゅぞうひがしちょすいそう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29876884,"lng":130.20265816,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"煉瓦造、建築面積4㎡","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0034","desc":"西貯水槽の東方に位置し，釜場南面に接して建つ。２．５ｍ×１．６ｍの長方形平面で，高さ４．４ｍ。６本の煉瓦造柱脚の上部をアーチで繋いで水槽の支持体とし，頂部には釜場南面から生子鉄板の片流れ屋根を架ける。煙突，西貯水槽などと同様に外構の主要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002719"},{"id":"00002721","register_sub_id":"101","register_pk":"103711","name":"小柳酒造ビン詰場","kana":"こやなぎしゅぞうびんづめじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29890444,"lng":130.20265363,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0036","desc":"昭和西蔵の東，昭和東蔵の南，釜場の北に位置する。桁行１０ｍ，梁間９ｍ規模で，南北棟，切妻造，桟瓦葺とし，小屋は二重梁，外部の西面は縦羽目張りとする。簡素なつくりであるが，造り酒屋における最終工程を物語る施設として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002721"},{"id":"00002720","register_sub_id":"101","register_pk":"103710","name":"小柳酒造ポンプ小屋","kana":"こやなぎしゅぞうぽんぷごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29867933,"lng":130.20261344,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"煉瓦造、建築面積5.3㎡","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0035","desc":"東貯水槽の南方に位置する。平面規模は１．８ｍ×３ｍで，東・南・西の３面に厚１枚の煉瓦造壁を築き，北面は欠円アーチを間口一杯に架けて入口とする。煉瓦は鉱滓煉瓦で，屋根は陸屋根に造る。大正１５年着手の昭和蔵・釜場などの一連の改良施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002720"},{"id":"00002723","register_sub_id":"101","register_pk":"103713","name":"小柳酒造ムロマエ","kana":"こやなぎしゅぞうむろまえ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29891956,"lng":130.20235198,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0038","desc":"麹室東妻面から昭和西蔵西面に向けて屋根を架け室前空間を造る。桁行７ｍ，梁間６ｍ規模の東西棟，桟瓦葺，切妻造で，南面には桟瓦葺の土庇を付けて東寄りに入口を設ける。麹室，酒母室とともに敷地西北隅部を形成して醸造施設特有の佇まいを醸しだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002723"},{"id":"00003480","register_sub_id":"101","register_pk":"104470","name":"天山酒造旧精米所立型水車及び水路","kana":"てんざんしゅぞうきゅうせいまいしょたてがたすいしゃおよびすいろ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町大字岩蔵1520","lat":33.31197924,"lng":130.19260173,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"コンクリート造水路延長57m、水車よりなる","structure_material":"コンクリート造水路延長57m","registered":"2003.07.01(平成15.07.01)","register_no":"41 － 0043","desc":"敷地北端に位置する旧精米所に祇園川から取水する用水路を引き入れて水車を回す。水車は鉄製の立軸型水車で，精米機の動力源となる。水車精米時代の遺構であり，酒造システムの近代化過程の一面を物語る遺産として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003480"},{"id":"00003479","register_sub_id":"101","register_pk":"104469","name":"天山酒造昭和蔵","kana":"てんざんしゅぞうしょうわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町大字岩蔵1520","lat":33.31158487,"lng":130.19337955,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積1253㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"41 － 0042","desc":"大正蔵の東側に平行して建つ。桁行３０間，梁間７間規模で，南妻面に桁行７間，梁間４間の麹室が取り付く。北寄り桁行１２間分は多久からの移設であるが，外観上は大正蔵と同様に両妻を半寄棟形とし，腰縦板張，２段窓の長大な桁行面を東側道路沿いに見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003479"},{"id":"00003478","register_sub_id":"101","register_pk":"104468","name":"天山酒造明治蔵及び大正蔵","kana":"てんざんしゅぞうめいじぐらおよびたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県小城市小城町大字岩蔵1520","lat":33.31143449,"lng":130.19325841,"geo_status":"db","era":"明治初期／大正初期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階一部平屋建、瓦及びスレート葺、建築面積1716㎡","structure_material":"土蔵造2階一部平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"41 － 0041","desc":"桁行８間，梁間３間，三重梁構造の明治蔵の北及び東に大正蔵がＵ字状に増築され，全体として桁行３０間，梁行１２間の大規模酒蔵となる。腰を縦板張，上部白漆喰塗壁に水切り瓦付きの窓を２段に配置し，妻を半寄棟に納めるなど特徴ある北面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003478"},{"id":"00015266","register_sub_id":"101","register_pk":"530690","name":"戸上電機製作所本館","kana":"とがみでんきせいさくしょほんかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県佐賀市大財北町385-1他","lat":33.26370278,"lng":130.30405,"geo_status":"db","era":"大正14年／昭和13年・同30年代増築、令和5年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階一部3階建、鉄板葺、建築面積518㎡","structure_material":"木造2階一部3階建","registered":"2024.12.03(令和6.12.03)","register_no":"41 - 0135","desc":"ＪＲ佐賀駅東方の市街地に位置する、配電部品製造業の本社屋。木造三階建で南正面の玄関から上へ、四本の付柱が増築の三階を越えて伸びる。一・二階は矩形窓、三階はアーチ窓を開ける。外壁は磁器タイル貼。佐賀の電気産業の発展を伝える象徴的な事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015266"},{"id":"00005684","register_sub_id":"101","register_pk":"106672","name":"中島酒造場麹室","kana":"なかしましゅぞうじょうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.09202004,"lng":130.11531116,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積37㎡","structure_material":"土蔵造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0068","desc":"仕込蔵の東に南妻を揃えて建つ。桁行３間半，梁間３間規模の土蔵造平屋建で，切妻造，桟瓦葺とする。外壁の腰部には煉瓦を張り，仕込蔵側の西面はモルタル仕上げとして南端に出入口を設けている。南面に仕込蔵と一連の瓦葺庇をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005684"},{"id":"00005682","register_sub_id":"101","register_pk":"106670","name":"中島酒造場仕込蔵","kana":"なかしましゅぞうじょうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.09210027,"lng":130.11516712,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積409㎡、煙突付","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0066","desc":"主屋の南背後，釜場に接続して建つ土蔵造２階建，切妻造，桟瓦葺の南北棟２棟で，西棟が桁行１１間半，梁間４間半，東棟が桁行１１間，梁間４間で，２棟の間の壁を撤去して使用している。南面には東の麹室と一連で瓦葺庇がつく。西棟の南北に煉瓦造煙突が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005682"},{"id":"00005685","register_sub_id":"101","register_pk":"106673","name":"中島酒造場土蔵","kana":"なかしましゅぞうじょうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.0927035,"lng":130.11515923,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積203㎡","structure_material":"土蔵造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0069","desc":"多良往還を挟んで主屋の向いに建つ土蔵造平屋建で，切妻造，桟瓦葺とする。街路からやや後退して建つ。南妻に戸口を設け瓦葺庇を架ける。桁行１０間半，梁間３間の南北棟，桁行４間半，梁間３間半の南北棟，桁行３間半，梁間３間半の東西棟の３棟が連続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005685"},{"id":"00005683","register_sub_id":"101","register_pk":"106671","name":"中島酒造場西蔵","kana":"なかしましゅぞうじょうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.09212563,"lng":130.11499095,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0067","desc":"主屋の南，仕込蔵の西に並んで建つ土蔵造２階建の貯蔵庫。桁行６間，梁間６間の南北棟で，屋根は切妻造，桟瓦葺とする。外壁は白漆喰塗で，西壁の腰部を煉瓦貼とし，一部鉄板で覆っている。小屋組は束立の和小屋である。浜川側からの景観の一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005683"},{"id":"00004468","register_sub_id":"101","register_pk":"105458","name":"富久千代酒造一号蔵","kana":"ふくちよしゅぞういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市浜町1254-1","lat":33.09375397,"lng":130.11439492,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積522㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0045","desc":"敷地西側のほぼ中央に東西棟で建つ。桁行１４間梁間８間規模，寄棟造，桟瓦葺の２階建酒蔵で，南面に２間半幅の下屋を付ける。内部は，１階が仕込蔵で，西側を槽場，２階を倉庫，下屋を製品倉庫に充てる。外壁は縦板張とし，敷地西辺の酒蔵景観の中核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004468"},{"id":"00004470","register_sub_id":"101","register_pk":"105460","name":"富久千代酒造麹室","kana":"ふくちよしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市浜町1254-1","lat":33.09398149,"lng":130.114487,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0047","desc":"敷地西北隅，一号蔵の北方に位置し，敷地西辺に沿って南北棟で建つ。桁行８間梁間３間規模，切妻造，桟瓦葺の木造平屋建で，内部には麹室を２室設け，東面に下屋を差し掛ける。西側街路沿い酒蔵景観の形成要素で，外壁は他の酒蔵同様に焼杉の縦板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004470"},{"id":"00004469","register_sub_id":"101","register_pk":"105459","name":"富久千代酒造精米所","kana":"ふくちよしゅぞうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市浜町1254-1","lat":33.09372,"lng":130.11479107,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0046","desc":"一号蔵東妻面北寄りに西妻面を接して建つ。東西棟，切妻造，桟瓦葺の木造平屋建で，桁行９間半梁間３間の平面規模とし，小屋組は登り梁と二重梁を交互に架ける。外壁は一号蔵と同様に焼杉縦板張とする。造り酒屋の酒造場に欠くことのできない施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004469"},{"id":"00000230","register_sub_id":"101","register_pk":"101220","name":"村岡総本舗羊羹資料館","kana":"むらおかそうほんぽようかんしりょうかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町861","lat":33.30135525,"lng":130.20428018,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建，建築面積72㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"41 － 0002","desc":"砂糖貯蔵庫として建てられ、昭和59年の改装によって資料館となった。躯体は木造で、寄棟の屋根、和小屋の小屋組とも完全な和風建築であるが、ファサードは煉瓦とタイルによる洋風の意匠となっており、その特徴的な外観で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000230"},{"id":"00005671","register_sub_id":"101","register_pk":"106659","name":"矢野酒造旧精米所","kana":"やのしゅぞうきゅうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11293918,"lng":130.0937481,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0055","desc":"街路に面して主屋の南に並ぶ木造平屋建の東西棟。桁行９間，梁間３間の切妻造，桟瓦葺で，屋根西寄りに越屋根を載せる。正面に瓦葺庇がつく。外壁は白漆喰塗で，正面の妻壁は下見板張とする。内部は天井を張らずに小屋組を現しとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005671"},{"id":"00005675","register_sub_id":"101","register_pk":"106663","name":"矢野酒造麹室","kana":"やのしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11283736,"lng":130.09294443,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"煉瓦造及び木造平屋建、瓦葺、建築面積81㎡","structure_material":"煉瓦造及び木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0059","desc":"敷地の西端，西蔵の南に接続する煉瓦造及び木造平屋建。桁行６間，梁間３間の南北棟で，煉瓦壁の上部に竪羽目板張の壁を立ち上げ，切妻造桟瓦葺の屋根を架けている。内部は北から２間位置に間仕切を設けて前室とし，内壁は煉瓦壁にモルタルを塗る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005675"},{"id":"00005673","register_sub_id":"101","register_pk":"106661","name":"矢野酒造中蔵","kana":"やのしゅぞうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11315926,"lng":130.09318816,"geo_status":"db","era":"明治39／昭和20代増築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積389㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0057","desc":"東蔵の西に並んで建つ木造２階建。桁行１４間，梁間６間，切妻造桟瓦葺の南北棟で，東蔵と戸口で接続している。仕込蔵として建設されたが，現在は貯蔵庫として用いられている。昭和２０年代に南端２間を増築した。外壁は白漆喰塗で南側妻壁に鉄板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005673"},{"id":"00005674","register_sub_id":"101","register_pk":"106662","name":"矢野酒造西蔵","kana":"やのしゅぞうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11319045,"lng":130.09305116,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積204㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0058","desc":"敷地の西端，中蔵の西に並んで建つ木造２階建。桁行９間，梁間３間の切妻造，桟瓦葺の南北棟で，外壁を鉄板張とする。東側外壁は撤去され，中蔵と壁を共有する。南側に接続する桁行５間の貯蔵庫は２階が蔵人部屋であった。敷地西からの景観の主要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005674"},{"id":"00005672","register_sub_id":"101","register_pk":"106660","name":"矢野酒造東蔵","kana":"やのしゅぞうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11312926,"lng":130.09333145,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積281㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0056","desc":"敷地のほぼ中央，離れの西に位置する木造２階建。桁行１１間，梁間５間，切妻造，桟瓦葺の南北棟で，仕込蔵として建設され，現在は製品庫である。東面戸口の北側に検査室と分析室が付属。外壁は白漆喰塗で，腰を下見板張とする。小屋組は束立ちの和小屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005672"},{"id":"00005386","register_sub_id":"101","register_pk":"106374","name":"今里酒造洗い場","kana":"いまざとしゅぞうあらいば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13667773,"lng":129.89645004,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、鉄板葺、建築面積266㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0054","desc":"本蔵及び中蔵の北方に位置し東西棟で建つ。桁行１１間，梁間４間規模の切妻造，平屋建で，西に試験室を張り出し，南面から本蔵及び中蔵の北面に下屋を架ける。小屋組はキングポストトラスで，棟に煙出しを設ける。酒造場の発展を物語る施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005386"},{"id":"00005385","register_sub_id":"101","register_pk":"106373","name":"今里酒造新蔵","kana":"いまざとしゅぞうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷641","lat":33.13644963,"lng":129.89623214,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積491㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0053","desc":"中蔵の西に接して南北棟で建つ。酒蔵の解体材を用いて建設と伝える。桁行１８間，梁間６間規模の総２階建で，棟通り３間毎に丸柱を建て，４重梁の小屋を組む。当酒造場では最も規模が大きく，建ちも高く，他の切妻造と異なり寄棟造であることで際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005385"},{"id":"00005387","register_sub_id":"101","register_pk":"106375","name":"今里酒造製品置き場","kana":"いまざとしゅぞうせいひんおきば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13635625,"lng":129.89634859,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0055","desc":"中蔵の南妻面及び新蔵東面南寄りに接して建つ。桁行５間，梁間３間規模，南北棟の切妻造２階建で，東面に下屋を差し掛ける。もと玄米置き場で，２階北側の１５畳半は杜氏部屋とする。小規模な建造物ではあるが，酒造場に欠くことのできない施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005387"},{"id":"00005384","register_sub_id":"101","register_pk":"106372","name":"今里酒造中蔵","kana":"いまざとしゅぞうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13651777,"lng":129.89637634,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0052","desc":"本蔵の西に並列して建つ。桁行１２間梁間４間半規模の切妻造２階建で，小屋組は二重梁と登り梁を交互に用い，東側の本蔵との間の２間幅の通路は東面の屋根を葺き下ろす。本蔵とともに創業時に近い酒造施設で，明治１２年の大火でも焼失を免れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005384"},{"id":"00005383","register_sub_id":"101","register_pk":"106371","name":"今里酒造本蔵","kana":"いまざとしゅぞうほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13651625,"lng":129.896515,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積283㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0051","desc":"店舗土間の北端部を蔵前とし，土間北方に接して南北棟で建つ。桁行１２間，梁間６間，切妻造の酒蔵で，中央部に２階を設ける。小屋組は２間毎に二重梁を架け，その間に登り梁を入れる。酒造場の中心施設で，主屋，中蔵とともに川沿いに雄大な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005383"},{"id":"00002733","register_sub_id":"101","register_pk":"103723","name":"梅ヶ枝酒造旧北蔵","kana":"うめがえしゅぞうきゅうきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.090057,"lng":129.815048,"geo_status":"db","era":"明治期／昭和35頃移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積147㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0018","desc":"住居（離れ）の北方に建つ。もと精米所で，移築前は貯蔵蔵の北方に所在した。桁行１９．７ｍ，梁間６．７ｍ規模，切妻造，桟瓦葺の２階建で，南東部に桁行７．９ｍ，幅１．９ｍの張り出しを設ける。規模が大きく，梅ヶ枝酒造発展期を物語る遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002733"},{"id":"00002731","register_sub_id":"101","register_pk":"103721","name":"梅ヶ枝酒造旧仕込蔵","kana":"うめがえしゅぞうきゅうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.08992,"lng":129.814514,"geo_status":"db","era":"江戸末期／明治後期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積264㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0016","desc":"敷地の西南隅部に位置し，「旧むろ」の西に接して建つ。桁行１８ｍ，梁間１１．９ｍ規模，東西棟，桟瓦葺，切妻造の平屋建で，北西部を２度にわたり増築し，内部では間内柱と和小屋をブレースで補強している。規模が大きく，造り酒屋の中核的施設になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002731"},{"id":"00002730","register_sub_id":"101","register_pk":"103720","name":"梅ヶ枝酒造旧むろ","kana":"うめがえしゅぞうきゅうむろ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.089828,"lng":129.814682,"geo_status":"db","era":"江戸末期／明治後期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"煉瓦及び木造平屋建、瓦葺、建築面積74㎡","structure_material":"煉瓦及び木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0015","desc":"瓶詰所２階建部の西に建つ。桁行８．３ｍ，梁間８．９ｍ規模の東西棟，桟瓦葺，切妻造建家の内部に特徴ある積み方の煉瓦造ムロを造る。外観上では，西に隣接する旧仕込蔵の屋根と一体化されており，南面に造り酒屋特有の路地的佇まいをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002730"},{"id":"00002732","register_sub_id":"101","register_pk":"103722","name":"梅ヶ枝酒造貯蔵蔵","kana":"うめがえしゅぞうちょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.090027,"lng":129.814743,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦及び土蔵造2階建、瓦葺、建築面積141㎡","structure_material":"煉瓦及び土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0017","desc":"主屋の西方，旧仕込蔵の北方に建つ。桁行１８．３ｍ，梁間７．７ｍ規模，東西棟，桟瓦葺，切妻造，２階建で，腰高までのイギリス積煉瓦造基礎の上に木軸を組む。両妻面に入口を設け，１階西端部に酒絞り器を据えて槽場とする。中心的醸造施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002732"},{"id":"00002729","register_sub_id":"101","register_pk":"103719","name":"梅ヶ枝酒造瓶詰所","kana":"うめがえしゅぞうびんづめじょ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.089775,"lng":129.814789,"geo_status":"db","era":"江戸末期／明治後期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積125㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0014","desc":"主屋南面下屋部（もと釜場）の南方に位置する。桁行９．４ｍ梁間６．４ｍ，南北棟，切妻造の平屋建部と，桁行１１．５ｍ梁間５．６ｍ，東西棟，切妻造の総２階建部とがＬ字形に繋がる。１階はともに土間になっており，現在は出荷の作業場に充てられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002729"},{"id":"00007412","register_sub_id":"101","register_pk":"108394","name":"加藤酒造井戸","kana":"かとうしゅぞういど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.852177,"lng":130.331329,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、面積1.5㎡","structure_material":"石造","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0075","desc":"主屋の通りニワの後方、敷地のほぼ中央に位置する。厚さ０．１８ｍの地元産の凝灰岩を、方１．２ｍ高さ０．４５ｍに相欠で組む。内部は直径１．０ｍで円筒状に堀り、深さは１０ｍを測る。酒醸造に使ったと伝える井戸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007412"},{"id":"00007415","register_sub_id":"101","register_pk":"108397","name":"加藤酒造裏土塀","kana":"かとうしゅぞううらどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.85206749,"lng":130.33120243,"geo_status":"db","era":"明治前期／大正期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土塀、瓦葺、延長37m","structure_material":"土塀","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0078","desc":"主屋背面の上便所西南隅から西へ延び、隅切りとする西南角で敷地形状にあわせて北に折れる。延長３７ｍ、高さ２．４ｍで、西面の塀は低くする。いずれも石積の上を土塀とする。頂部に桟瓦を葺き、漆喰で塗り固める。東端には石積の高さに通用口を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007415"},{"id":"00007414","register_sub_id":"101","register_pk":"108396","name":"加藤酒造表土塀","kana":"かとうしゅぞうおもてどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.85233607,"lng":130.33123196,"geo_status":"db","era":"大正期／昭和40頃改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土塀、瓦葺、延長16m","structure_material":"土塀","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0077","desc":"門の西から通り沿いに西へ延び、敷地西北角で南に折れる。折曲り延長１６ｍ、高さ２．４～３．４ｍ。石積上を土塀とし、頂部に桟瓦を葺き、漆喰で塗り固める。石積は高さ１．３～１．７ｍで切込み矧ぎとする。伝統的な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007414"},{"id":"00007411","register_sub_id":"101","register_pk":"108393","name":"加藤酒造店舗兼主屋","kana":"かとうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.852219,"lng":130.331421,"geo_status":"db","era":"明治前期／明治後期・大正期・昭和前期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積266㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0074","desc":"通りに北面する規模の大きい平入町家。入母屋造桟瓦葺の木造つし２階建で、西半部の棟を少し高くし、背面東寄りに角屋を付ける。内部は西寄りの土間と床上部からなり、上質なつくりになる座敷飾りを備える座敷や仏間など３室を東端に並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007411"},{"id":"00007413","register_sub_id":"101","register_pk":"108395","name":"加藤酒造門","kana":"かとうしゅぞうもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.85228989,"lng":130.33130761,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0076","desc":"主屋の西、通りに北面して建つ一間薬医門。切石礎石に本柱を建て、冠木、男梁を架す。軒は一軒疎垂木。切妻造桟瓦葺で、棟は熨斗積とし、漆喰で塗り固める。間口２．５ｍで、両開の板戸を吊る。比較的規模の大きい門で、主屋とともに表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007413"},{"id":"00009681","register_sub_id":"101","register_pk":"194677","name":"旧佐世保鎮守府武庫預兵器庫","kana":"きゅうさせぼちんじゅふぶこあずかりへいきこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県佐世保市立神町23","lat":33.166577,"lng":129.70774536,"geo_status":"db","era":"明治32／明治36増築","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"煉瓦造2階建、スレート葺、建築面積646㎡","structure_material":"煉瓦造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"42 － 0105","desc":"佐世保港立神地区に建つ煉瓦造二階建、切妻造スレート葺。桁行三六メートル梁間九メートルの南棟の北壁を共有して同規模の北棟を増築。壁体は煉瓦二枚半積で腰と軒に蛇腹を廻らす。戸口と窓は鉄製両開扉付。小屋組はキングポストトラス。重厚な趣の倉庫建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009681"},{"id":"00009243","register_sub_id":"101","register_pk":"164796","name":"旧福幸製陶所絵書座","kana":"きゅうふっこうせいとうしょえかきざ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷字西ノ前2185-2他","lat":33.14080427,"lng":129.90766462,"geo_status":"db","era":"昭和元年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積213㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"東西棟で建ち、木造平屋建、桁行23メートル梁間7.7メートル、切妻造桟瓦葺で、南面に事務所を張出す。小屋をトラス組とする内部を、成形した陶磁器の乾燥と、絵付けを行う作業場として使用した。波佐見焼を代表する製陶工場を構成する工場建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009243"},{"id":"00009242","register_sub_id":"101","register_pk":"164795","name":"旧福幸製陶所細工場","kana":"きゅうふっこうせいとうしょさいくば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷字西ノ前2185-2他","lat":33.14101842,"lng":129.90781333,"geo_status":"db","era":"昭和元年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積309㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"東西棟で建ち、木造平屋建、桁行32.6メートル梁間7.7メートル、切妻造桟瓦葺で、南面に下屋を通す。小屋をトラス組とし、開放的な内部を粘土置場や陶磁器の成形などの作業場に用いた。昭和初期における製陶工場の様相を今に留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009242"},{"id":"00009241","register_sub_id":"101","register_pk":"164794","name":"旧福幸製陶所事務所","kana":"きゅうふっこうせいとうしょじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷字西ノ前2185-2他","lat":33.14114917,"lng":129.90756944,"geo_status":"db","era":"昭和元年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積124㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"通りに面し、木造平屋1部2階建、建築面積124平方メートル、切妻造桟瓦葺で、北側にもと事務所玄関であった切妻の張出しを設け、南面を下屋につくる。外壁は下見板張でペンキ塗とし、ガラス窓を連続させる。昭和初期の事務所建築で、街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009241"},{"id":"00009680","register_sub_id":"101","register_pk":"194676","name":"佐世保重工業二五〇トン起重機","kana":"させぼじゅうこうぎょうにひゃくごじゅっとんきじゅうき","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県佐世保市立神町22","lat":33.16479389,"lng":129.70754824,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄骨造、高さ62m","structure_material":"鉄骨造","registered":"2013.06.21(平成25.06.21)","register_no":"42 － 0104","desc":"佐世保港の係船池に建つ鉄骨造ハンマーヘッド型起重機。全高六二メートル、主塔高四一メートル、腕長八一メートルを測る。英国サー・ウィリアム・アロル社製造、電動機はウェスティングハウス社製。当時国内最大の揚重能力を誇り、近代佐世保の港湾景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009680"},{"id":"00010076","register_sub_id":"101","register_pk":"196223","name":"マルイチ葬祭斎場（旧小林家住宅酒蔵）","kana":"まるいちそうさいさいじょう（きゅうこばやしけじゅうたくさかぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県島原市弁天町1-7118-6","lat":32.78432927,"lng":130.37261987,"geo_status":"db","era":"明治末期／昭和前期移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造3階建、瓦葺、建築面積580㎡","structure_material":"土蔵造3階建","registered":"2014.04.25(平成26.04.25)","register_no":"42 － 0108","desc":"南北棟の切妻造で、桁行一四間梁間六間、土蔵造三階建の主体部の東面に、一階と二階で二段階に下屋を設け、三段屋根の外観を呈する。棟高約一四メートルに及ぶ大規模な土蔵建築で、国道に面して雄大な外観を見せており、島原の街路景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010076"},{"id":"00003334","register_sub_id":"101","register_pk":"104324","name":"三菱重工業長崎造船所ハンマーヘッド型起重機","kana":"みつびしじゅうこうぎょうながさきぞうせんしょはんまーへっどがたきじゅうき","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市飽の浦町1-1","lat":32.74203651,"lng":129.85890705,"geo_status":"db","era":"明治42／昭和36移設","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"鉄骨造、高さ62m","structure_material":"鉄骨造","registered":"2003.03.18(平成15.03.18)","register_no":"42 － 0020","desc":"長崎港に面する岸壁上に位置する。吊上能力１５０トン，高約６１ｍ，ジブ長約７３ｍ，英国マザーウェル・ブリッジ社製の大規模な起重機で，主柱間約１２ｍ四方とし，全体をトラスで組み上げる。造船技術の近代化を支え，近代長崎の港湾景観を代表する構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003334"},{"id":"00003487","register_sub_id":"101","register_pk":"104477","name":"宮崎商店煙突","kana":"みやざきしょうてんえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市上の町897","lat":32.79037255,"lng":130.36859979,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造、高さ12m","structure_material":"煉瓦造","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0028","desc":"店舗背面の旧釜場の北方，焼酎蔵の北寄り東側に隣接する旧麹室の南方に建つ。円形平面の煉瓦造煙突で，高さ約１２ｍ規模。頂部にリング状の持出しを２筋付けてトスカナ式円柱を思わせる。造り酒屋に付き物の工作物であるが，上の町のシンボル的存在でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003487"},{"id":"00003486","register_sub_id":"101","register_pk":"104476","name":"宮崎商店焼酎蔵","kana":"みやざきしょうてんしょうちゅうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県島原市上の町897","lat":32.79035131,"lng":130.36852524,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積197㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0027","desc":"店舗の西方，敷地の南寄りに南北棟で建つ。桁行９間，梁間４間規模，切妻造，桟瓦葺，平入の２階建酒蔵で，棟梁は店舗と同じ「荒木輝美雄」であることが棟札から判明する。緩やかな坂道の中途に南妻面を見せて建ち，城方から島原街道を望む際の目印となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003486"},{"id":"00010901","register_sub_id":"101","register_pk":"201736","name":"菊の城本舗店舗兼主屋","kana":"きくのしろほんぽてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県菊池市隈府字町95-2他","lat":32.98292,"lng":130.806953,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積305㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"43 ‐ 0149","desc":"市街地の街路屈曲部に南面する造酒屋で、下階は広いミセと居間など、上階は上質な座敷飾をもつ接客空間を配する。建ちの高い二階建、入母屋造で正面に庇を通して出格子を設け、東端の平屋建はデンティルを飾り、洋風外観とする。街路景観の核となる酒造施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010901"},{"id":"00016457","register_sub_id":"101","register_pk":"536524","name":"旧隈府冷蔵製氷工場","kana":"きゅうわいふれいぞうせいひょうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県菊池市隈府字南田775-1他","lat":32.98044444,"lng":130.80956111,"geo_status":"db","era":"昭和5年頃／昭和前期・同29年増築、令和2年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積439㎡","structure_material":"煉瓦造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0215","desc":"隈府の中心部に位置する旧製氷工場。敷地の中央部に建つ、煉瓦造平屋建切妻造桟瓦葺東西棟で、東端部の北と南に鉱滓煉瓦造平屋建桟瓦葺の倉庫を増築し、全体Ｔ字形平面とする。通りに面する北東部は半切妻造屋根とし壁面に記す工場名が操業時の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016457"},{"id":"00016458","register_sub_id":"101","register_pk":"536525","name":"旧隈府冷蔵倉庫（旧飲料水工場）","kana":"きゅうわいふれいぞうそうこ（きゅういんりょうすいこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県菊池市隈府字南田775-10","lat":32.98034722,"lng":130.80970278,"geo_status":"db","era":"昭和中期／令和2年改修","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"煉瓦造平屋建、瓦葺、建築面積73㎡","structure_material":"煉瓦造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0216","desc":"製氷工場の南に位置する旧飲料水工場。鉱滓煉瓦造平屋建切妻造桟瓦葺の東西棟で、西に戸口を設ける。内部は一室の土間で鋼板天井張、小屋組はキングポスト・トラス。かつて冷凍冷蔵庫や冷凍タンクを配し、製氷工場と一体で地域の繁栄を伝える旧飲料水工場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016458"},{"id":"00004302","register_sub_id":"101","register_pk":"105292","name":"熊本学園大学産業資料館（旧熊本紡績電気室）","kana":"くまもとがくえんだいがくさんぎょうしりょうかん（きゅうくまもとぼうせきでんきしつ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市大江2-1903-2","lat":32.80363644,"lng":130.72665566,"geo_status":"db","era":"明治27／平成15移築","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"鉄筋コンクリート造及び煉瓦造平屋建、瓦葺、建築面積118㎡","structure_material":"鉄筋コンクリート造及び煉瓦造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"43 － 0072","desc":"ＪＲ熊本駅近くにあった紡績工場施設。イギリス積の煉瓦造，平屋建で，木造キングポストトラスの小屋組として，切妻造屋根を架ける。移築時に鉄筋コンクリート造で補強，当初壁は平側・妻側各１面となったが，隅の柱型や軒蛇腹の造形に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004302"},{"id":"00014125","register_sub_id":"101","register_pk":"508385","name":"通潤酒造店舗及び主屋","kana":"つうじゅんしゅぞうてんぽおよびおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県上益城郡山都町浜町字新町54-1他","lat":32.68491111,"lng":130.98744167,"geo_status":"db","era":"明治前期／昭和10年代・同30年代後半・平成30年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積327㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"43 - 0185","desc":"日向往還浜町宿に位置し通りに面する町家。寄棟造の店舗背後に棟を直交させて主屋を接続し正面に妻を見せる。下屋中央を切上げ戸口とし、二階は虫籠窓を開ける。内部は中央に通路を通し、東は店舗等、西は事務所奥に主屋居室を設ける。宿場最大規模の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014125"},{"id":"00014986","register_sub_id":"101","register_pk":"519246","name":"長谷川家住宅主屋","kana":"はせがわけじゅうたくおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市小川町小川字下苅萱112","lat":32.585575,"lng":130.70483056,"geo_status":"db","era":"明治16年／大正8年・昭和2年頃増築、同50年頃改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積183㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"43 - 0202","desc":"砂川右岸に位置し製糸業を営んだ商家の主屋。２階建切妻造平入桟瓦葺で通りに北面し、北西に角屋を延ばす。一階は東を土間、西に四室を並べ、二階にも四室を配す。かつては一階西下手の板間を荷造所、二階を女子寮として使用し、地域の製糸業の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014986"},{"id":"00006459","register_sub_id":"101","register_pk":"107442","name":"浜田醤油旧圧搾機室","kana":"はまだしょうゆきゅうあっさくきしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.77723376,"lng":130.63573342,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造平屋建、瓦葺、建築面積69㎡","structure_material":"土蔵造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0097","desc":"敷地北辺、三番蔵と旧原料倉庫の間に建つ。桁行６間、梁間３間、土蔵造平屋建、桟瓦葺。腰は下見板張とし、屋根の棟通りには採光窓を設ける。長大な土蔵の壁が連続する景観の中間で、通りに妻壁を見せて建ち、街路景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006459"},{"id":"00006461","register_sub_id":"101","register_pk":"107444","name":"浜田醤油旧石室","kana":"はまだしょうゆきゅういしむろ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.77709121,"lng":130.63563997,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造平屋建、建築面積63㎡","structure_material":"石造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0099","desc":"敷地南辺の中央付近に建ち、建築面積６３㎡、石造、平屋建である。石を積み上げ、外部をモルタル塗とし、内部を２室に間仕切る。現在は倉庫だが、もとは麹室で、温湿度を一定に保つため密閉性を高めている。醸造業創始時の醸造工程の一端を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006461"},{"id":"00006460","register_sub_id":"101","register_pk":"107443","name":"浜田醤油旧原料倉庫","kana":"はまだしょうゆきゅうげんりょうそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.777233,"lng":130.63562807,"geo_status":"db","era":"明治初期／大正期改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積120㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0098","desc":"旧圧搾機室の西側に建つ、桁行５間半、梁間５間、土蔵造２階建。切妻造桟瓦葺。外観は白漆喰仕上げで、腰を下見板張とし、外壁の中段に水切り瓦をつける。酒屋の建物と機械室を接続、改造して穀物倉庫としたもので、業務拡張時の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006460"},{"id":"00006464","register_sub_id":"101","register_pk":"107447","name":"浜田醤油給水塔","kana":"はまだしょうゆきゅうすいとう","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"昭和中","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.77711886,"lng":130.63539814,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"煉瓦造、高さ7m、門柱2基付","structure_material":"煉瓦造","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0100","desc":"敷地南面西寄りに建つ、幅２ｍ、奥行２ｍ、高さ７ｍの煉瓦造給水塔である。塔内部のポンプで地下水を汲み上げ、使用している。外壁の煉瓦は長手積で、接続する煉瓦塀と一体的に建設されている。煙突と併せて、旧白川沿いの景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006464"},{"id":"00006458","register_sub_id":"101","register_pk":"107441","name":"浜田醤油三番蔵","kana":"はまだしょうゆさんばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.777248,"lng":130.635925,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積218㎡","structure_material":"土蔵造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0096","desc":"敷地の東北角、店舗の北隣に建つ。桁行１２間、梁間４間、土蔵造平屋建、切妻造桟瓦葺。正面の海鼠壁を店舗と一連にして調和させるが、平入の店舗に対して、三番蔵は妻入で大きな妻壁を見せ、街路景観に変化を与える。醸造業創始時の面影を伝える大型の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006458"},{"id":"00014550","register_sub_id":"101","register_pk":"513964","name":"街蔵石倉（旧緑屋石倉）","kana":"まちくらいしくら（きゅうみどりやいしくら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県人吉市紺屋町41-1","lat":32.21449722,"lng":130.76030278,"geo_status":"db","era":"明治35年頃／昭和16年頃移築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積148㎡","structure_material":"石造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"43 - 0198","desc":"旧城下の市街地に所在する味噌醸造や原材料保管に用いた石倉。寄棟造妻入桟瓦葺で、西側を換気採光のため改修。壁は切石布積江戸切仕上、小屋組はキングポスト・トラスとする。近代に人吉地方の溶結凝灰岩を用い、数多く建築された石倉の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014550"},{"id":"00014551","register_sub_id":"101","register_pk":"513965","name":"街蔵麴室（旧緑屋麹室棟）","kana":"まちくらこうじむろ（きゅうみどりやこうじむろとう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市紺屋町41-1","lat":32.21448056,"lng":130.76012778,"geo_status":"db","era":"昭和16年頃／同41年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造一部コンクリートブロック造平屋建、瓦葺、建築面積64㎡","structure_material":"木造一部コンクリートブロック造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"43 - 0199","desc":"旧城下の市街地に所在する味噌醸造元の麹室棟。切妻造桟瓦葺で南側軒を高く招き屋根として越屋根を備える。外壁は北半をコンクリートブロック布積、南半を開放とする。内部は元は北東側桁行４間、梁間２間を麹室とした。石倉と一体で味噌作りの景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014551"},{"id":"00004303","register_sub_id":"101","register_pk":"105293","name":"マミフラワーデザイン熊本教室花峰館（旧鐘淵紡績熊本工場診療所）","kana":"まみーふらわーでざいんくまもときょうしつかほうかん（きゅうかねがふちぼうせきくまもとこうじょうしんりょうじょ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市河内町岳字茶碗山1844-356、365","lat":32.810703,"lng":130.644196,"geo_status":"db","era":"明治44／平成15移築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"43 － 0073","desc":"ＪＲ熊本駅近くにあった紡績工場の診療所施設。木造平屋建，寄棟造，桟瓦葺，平入で，正面中央に切妻造鉄板葺の玄関を突出する。煉瓦造の布基礎で，外壁は腰縦板張，中央下見板張，上部ハーフティンバー風に扱い，内外とも瀟洒な洋風意匠でよく纏まっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004303"},{"id":"00010539","register_sub_id":"101","register_pk":"199478","name":"荒木家住宅勝手蔵","kana":"あらきけじゅうたくかってぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県玖珠郡玖珠町大字森938","lat":33.300556,"lng":131.158778,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"44 － 0208","desc":"主屋の奥座敷後方に東西棟で建つ。桁行六・九メートル梁間四・九メートル、土蔵造二階建、切妻造桟瓦葺。外壁漆喰塗で鉢巻を廻らし、腰は陶板を用いた海鼠壁とする。東妻を戸口として掛子塗戸を開き、小屋は和小屋である。特異な色合いの腰壁が目を引く土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010539"},{"id":"00010538","register_sub_id":"101","register_pk":"199477","name":"荒木家住宅酒蔵","kana":"あらきけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県玖珠郡玖珠町大字森938","lat":33.300766,"lng":131.158767,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積121㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"44 － 0207","desc":"主屋の北西方に南北棟で建ち、桁行一八メートル規模の土蔵造二階建で、切妻造桟瓦葺である。東面戸口に庇を付け、外壁漆喰塗で開口部廻りは丸みを帯びた縁取りとする。小屋は洋小屋を組む。正面階境の水切と二階窓の庇に瓦を並べて、表情をもたせた大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010538"},{"id":"00010537","register_sub_id":"101","register_pk":"199476","name":"荒木家住宅主屋","kana":"あらきけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県玖珠郡玖珠町大字森938他","lat":33.30057,"lng":131.158935,"geo_status":"db","era":"大正11／昭和50代・平成19改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積235㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"44 － 0206","desc":"森城下の街路に東面して建つ。上下階とも出桁造で二階は軒先まで塗込め、屋根北端に載せた唐破風造の小室に布袋像を置く。一階は北寄りを広い通り土間、南側前面をミセ、奥に四室を配し南奥を主座敷とする。材工共に上質で、旧城下町に彩りを添える近代建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010537"},{"id":"00003174","register_sub_id":"101","register_pk":"104164","name":"井上家住宅酒蔵","kana":"いのうえけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.376652,"lng":130.892563,"geo_status":"db","era":"弘化4","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積108㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0085","desc":"門の東側にある２階建，切妻造，桟瓦葺の大規模な土蔵。外観は漆喰壁と腰に海鼠瓦を張る。入口は北側に２個所あり，東半は什器等を収める道具蔵の性格を持つ。内部は板張りで小屋は水平梁と登梁を１間毎に交互にかける構造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003174"},{"id":"00011229","register_sub_id":"101","register_pk":"205336","name":"井上酒造煙突","kana":"いのうえしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和中","pref":"大分県","address":"大分県日田市大字大肥字堂迫2299-1","lat":33.361329,"lng":130.878866,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"煉瓦造、高さ18m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"44 - 0222","desc":"敷地西奥に位置する煉瓦造の煙突。基底部は一・四メートル角、高さは約一八メートルである。基部にはアーチ状開口部が設けられ、煉瓦をイギリス積としている。市内に三基残る大型煉瓦造煙突の一つで、酒造業らしい地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011229"},{"id":"00011227","register_sub_id":"101","register_pk":"205334","name":"井上酒造店舗兼主屋","kana":"いのうえしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市大字大肥字堂迫2299-1","lat":33.361115,"lng":130.879059,"geo_status":"db","era":"大正3／昭和18改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積454㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"44 - 0220","desc":"井上準之助の生家として知られる造酒屋。店舗兼主屋は入母屋屋根の式台玄関を備えた大規模なもので、店に用いる広い土間と、整った座敷を並べる床上部からなる。当初茅葺平屋建であったが、戦前期に二階を増築して瓦葺とし、家業の隆盛に伴う発展を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011227"},{"id":"00011228","register_sub_id":"101","register_pk":"205335","name":"井上酒造木造蔵","kana":"いのうえしゅぞうもくぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県日田市大字大肥字寺田2219-1他","lat":33.361606,"lng":130.879149,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積373㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"44 - 0221","desc":"当初は仕込蔵として建設された。屋根は半切妻とし、外壁は漆喰壁として腰に竪板を張る。小屋組はクイーンポストトラスを架け、下弦材に約一六メートルの一丁材を用いて大スパンを飛ばす。地元大工らが大空間を実現するため、近代構法を取り入れたことを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011228"},{"id":"00001160","register_sub_id":"101","register_pk":"102150","name":"太田缶詰工場石倉","kana":"おおたかんづめこうじょういしぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県大分市大字白木336","lat":33.24293179,"lng":131.87462129,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造平屋建，瓦葺，建築面積106㎡","structure_material":"石造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"44 － 0043","desc":"主屋棟の北側に建つ外壁廻りを石造とした大型の倉で、軒廻りや妻壁は漆喰仕上げとし正面（南面）は左右の出入口のみの閉鎖的な外観になる。建築年代は、主屋などよりわずかに遅れたといわれる。開口部及び内装は工場として改修されたが、外観の保存はよい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001160"},{"id":"00001158","register_sub_id":"101","register_pk":"102148","name":"太田缶詰工場主屋","kana":"おおたかんづめこうじょうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字白木332","lat":33.24265928,"lng":131.87413976,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造２階建，瓦葺，建築面積401㎡","structure_material":"木造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"44 － 0041","desc":"工場の中心をなす建物で、木造２階建、寄棟造の主体部及び北寄り背後に接続する角屋からなる。主体部の１階平面は、南半部を接客用の座敷や和室が連なる居住部分とし、北半部に工場事務室を併設する。玄関部分を洋風につくるなど、特徴的な意匠で知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001158"},{"id":"00001159","register_sub_id":"101","register_pk":"102149","name":"太田缶詰工場土蔵","kana":"おおたかんづめこうじょうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字白木336","lat":33.24293179,"lng":131.87462129,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積41㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"44 － 0042","desc":"水産物加工と雑貨販売を家業とした初代が、明治２３年に缶詰の本格的な生産をはじめ、明治４１年には現在地に新工場を建て操業を開始した。土蔵は、切妻造、２階建で、外壁を漆喰仕上げとし、腰下を板貼りとする標準的な造りになり、全体的に保存も良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001159"},{"id":"00007332","register_sub_id":"101","register_pk":"108314","name":"可兒醤油店舗兼主屋","kana":"かにしょうゆてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字本町218-1他","lat":33.11934034,"lng":131.79850628,"geo_status":"db","era":"明治10／大正後期改修","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積193㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0147","desc":"通りに北面する平入町家。正面６間半奥行５間半規模、切妻造桟瓦葺で、正・背面に下屋庇を設け、背面には片流屋根を直角に付設。漆喰仕上げの大壁で、２階には虫籠窓４ヶ所を開ける。１階を土間床のミセ、２階を居室とする。臼杵における大規模な商家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007332"},{"id":"00007333","register_sub_id":"101","register_pk":"108315","name":"可兒醤油西店舗","kana":"かにしょうゆにしてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県臼杵市大字臼杵字本町218-1他","lat":33.119492,"lng":131.79837,"geo_status":"db","era":"江戸末期／大正後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0148","desc":"店舗兼主屋の西に隣接して建つ。正面３間半奥行６間、切妻造桟瓦葺で、正・背面に下屋庇を付ける。大壁造の漆喰仕上げで、２階に虫籠窓３ヶ所を開ける。店舗兼主屋と同じ正面構えで伝統的な街路景観を形成するが、棟高や軒まわり、窓の大きさに違いを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007333"},{"id":"00000503","register_sub_id":"101","register_pk":"101493","name":"萱島酒造井戸屋形","kana":"かやしましゅぞういどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52527637,"lng":131.72556579,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積12㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0029","desc":"仕込み蔵の西側に位置する立ちの割には間口がやや広めの井戸屋形で，切妻の屋根をかける。中央に醸造に必要な清水を汲む切石組の井戸がある。小規模な建屋であるが，開放とする南面妻側の入り口には注連縄を張って，日頃から丁寧に管理されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000503"},{"id":"00000504","register_sub_id":"101","register_pk":"101494","name":"萱島酒造裏門","kana":"かやしましゅぞううらもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52517446,"lng":131.72562447,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造及び木造，瓦葺","structure_material":"煉瓦造及び木造","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0030","desc":"醸造所の裏手にある門で，煉瓦造の親柱一対が保存される。鉄製の門扉は後補のもの。仕込み蔵の南側に付設する下屋に接するように建ち，切妻の瓦屋根が付くほかシャッターも付設されている等改造があるが，醸造所の歴史を知る上で意味ある門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000504"},{"id":"00000499","register_sub_id":"101","register_pk":"101489","name":"萱島酒造煙突","kana":"かやしましゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.5250324,"lng":131.7258005,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造，高さ17m","structure_material":"煉瓦造","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0025","desc":"ムロマエの北側に隣接する平面八角形の煉瓦蔵煙突で，高さ２０ｍある。排煙口の意匠や煙道に付加された帯金具がアクセントとなっている。遠方からも望見され，古くから醸造所を象徴する工作物として付近の目印となっており広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000499"},{"id":"00000495","register_sub_id":"101","register_pk":"101485","name":"萱島酒造北蔵","kana":"かやしましゅぞうきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52535357,"lng":131.72599814,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積220㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0021","desc":"仕込み蔵の東側にあり，棟を直行して建つ木造平屋建の建物。他の建物と異なり，内部に棹縁天井をはった丁寧奈造りになる。間口４間半に対して奥行き１３間と長い。近年，東妻に別棟が附属したが，本体部は保存がよい。製品置場（瓶詰め）として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000495"},{"id":"00000500","register_sub_id":"101","register_pk":"101490","name":"萱島酒造旧麹室","kana":"かやしましゅぞうきゅうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52492122,"lng":131.72573873,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積40㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0026","desc":"旧ムロマエの南に建つ建物で，間口４間，梁間３間の木造平屋建になる。中蔵とは棟を平行にし，外壁は周囲を板貼とする。南妻側の上部に気抜きの小窓が付き，意匠上のアクセントとなる。現在は，吟醸酒を長期保存するための施設として使われている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000500"},{"id":"00000498","register_sub_id":"101","register_pk":"101488","name":"萱島酒造旧ムロマエ","kana":"かやしましゅぞうきゅうむろまえ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.5249799,"lng":131.72580358,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積79㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0024","desc":"敷地の南側に位置する木造平屋建の麹を冷やすための蔵造の建物。桁行５間，梁間４間半の規模になり，中蔵とは棟を直交して建つ。小屋組は和小屋とし，外壁は漆喰仕上げとする。醸造所で最も古い建物で，歴史を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000498"},{"id":"00000496","register_sub_id":"101","register_pk":"101486","name":"萱島酒造米蔵","kana":"かやしましゅぞうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52511887,"lng":131.72610314,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積171㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0022","desc":"土蔵造２階建の蔵で，漆喰仕上げの簡素な造りになる。外壁は２階窓まで延びる縦板を貼る。窓は，外側に簡素な枠をつけたもので板戸片引きとする。県道に面して建ち，煉瓦蔵の煙突とともに萱島酒造を象徴する建物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000496"},{"id":"00000494","register_sub_id":"101","register_pk":"101484","name":"萱島酒造仕込み蔵","kana":"かやしましゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52538446,"lng":131.72574182,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建，瓦葺，建築面積1123㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0020","desc":"萱島酒造は明治６年の創業で親子４代にわたる醸造所である。仕込み蔵は，木造２階建，寄棟造，瓦葺の大規模な倉庫建築で，内部は１，２階とも板床で，小屋はトラス組とする。敷地の奥手に建つが，風格ある大屋根は外部からも望見でき，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000494"},{"id":"00000501","register_sub_id":"101","register_pk":"101491","name":"萱島酒造中蔵（搾り場）","kana":"かやしましゅぞうなかぐら（しぼりば）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52509416,"lng":131.72572638,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建，瓦葺，建築面積687㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0027","desc":"間口４間，奥行２６間の長大な木造２階建，寄棟造の建物で，棟を南北に向ける。小屋組は，単純なキングポストトラスで，左右の束は挟み束とする。醸造所の建築群のなかで，仕込み蔵とともに外壁を板貼りとする壮大な外観は，ひときわ目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000501"},{"id":"00000505","register_sub_id":"101","register_pk":"132558","name":"萱島酒造木塀","kana":"かやしましゅぞうもくべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52477916,"lng":131.72583447,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"屋根塀，鉄板葺，延長65m","structure_material":"屋根塀","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0031","desc":"敷地の南側を限る塀で，腰下を煉瓦積としその上に木造の屋根塀を載せた構造になる。木造屋根塀の部分は，一間毎に柱を立て貫を渡し，その上下２段に間渡しを渡す簡素なもので，屋根は鉄板葺とする。明治以来の醸造所の繁栄の様子を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000505"},{"id":"00000497","register_sub_id":"101","register_pk":"101487","name":"萱島酒造門口倉庫","kana":"かやしましゅぞうもんぐちそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.5250324,"lng":131.72610006,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積50㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0023","desc":"米蔵に接続して建つ平屋建の倉庫兼門屋とする建物。米蔵側の一間半が間口で、門扉はシャッターに代わる。倉庫部分は，間口３間，梁間２間と小規模で，真壁造に腰板を貼る簡素な造りとなる。居宅と一体の醸造所を構成する付属的な施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000497"},{"id":"00000502","register_sub_id":"101","register_pk":"101492","name":"萱島酒造冷蔵蔵（旧醸造所）","kana":"かやしましゅぞうれいぞうぐら（きゅうじょうぞうしょ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.5250849,"lng":131.72561211,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積198㎡","structure_material":"土蔵造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0028","desc":"西蔵の西側に建つ。間口５間半，奥行１１間の平屋建の建物。醸造所の中で最も古い建物として知られ，昭和４年から冷蔵庫として使用している。内部は，籾殻を詰めた二重の板壁に改修し保温性を高めている。醸造工程を知る上で意義深い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000502"},{"id":"00000278","register_sub_id":"101","register_pk":"101268","name":"小手川酒造蔵","kana":"こてがわしゅぞうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県臼杵市大字臼杵字浜町538","lat":33.12068836,"lng":131.79702087,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建，瓦葺，建築面積368㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"44 － 0008","desc":"主屋の北に並んで建つ蔵。道に面して妻を見せる奥行の長い大規模な蔵で，醸造場として用いられている。正面妻の２階窓の上部に水切り瓦を付け，腰を海鼠壁で飾る等の，伝統的な技法による装飾に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000278"},{"id":"00000277","register_sub_id":"101","register_pk":"101267","name":"小手川酒造主屋","kana":"こてがわしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県臼杵市大字臼杵字浜町538","lat":33.12054988,"lng":131.79702087,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建，瓦葺，建築面積256㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"44 － 0007","desc":"広い間口をもつ大規模な二階建て平入の町家で，二階の外壁を白漆喰の大壁造とする。醸造業が盛んで漆喰塗り大壁の町家が多く残る臼杵の町並のなかで，とくに規模が大きく建設年代が古い建築のひとつとしてよく知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000277"},{"id":"00002467","register_sub_id":"101","register_pk":"103457","name":"英国館","kana":"えいこくかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県西臼杵郡日之影町大字見立2107-8","lat":32.78772684,"lng":131.45497232,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、鉄板葺、建築面積350㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"45 － 0010","desc":"神戸の貿易商ハンター（範多範三郎）により経営された見立鉱山の外国人技師クラブ兼ハンター別荘として建設。木造平屋建，下見板張，鉄板葺切妻屋根で，横長の連続窓を配したモダニズム建築になり，地元では「レーモンド様式」の建築として名がとおっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002467"},{"id":"00012670","register_sub_id":"101","register_pk":"367964","name":"古澤醸造一号蔵","kana":"ふるさわじょうぞういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"明治25年頃／平成15年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積132㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0101","desc":"敷地東南隅に建つ。土蔵造二階建、南北棟の切妻造で、西北二面に戸口を開く。柱を一間毎に立て、筋交を襷状に入れて固める。二階床組は大径梁を用い、小屋組はキングポストトラスである。焼酎の仕込を行う長大な土蔵で、敷地内醸造施設の中核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012670"},{"id":"00012672","register_sub_id":"101","register_pk":"367966","name":"古澤醸造表門及び塀","kana":"ふるさわじょうぞうおもてもんおよびへい","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"表門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、総延長18m","structure_material":"表門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0103","desc":"店舗兼主屋の正面南側に接続し、座敷棟の前庭と街路を区切る門塀。表門は街路から後退し、西面して建つ切妻造桟瓦葺の腕木門。塀は真壁造、漆喰塗の腰縦板張で、表門北側に額縁付の格子窓、南側に変形格子窓を並べる。街路沿いの歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012672"},{"id":"00012668","register_sub_id":"101","register_pk":"367962","name":"古澤醸造麹室・検定室及び作業場","kana":"ふるさわじょうぞうこうじむろ・けんていしつおよびさぎょうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"明治25年頃／昭和30年頃増築、昭和36年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺、建築面積116㎡","structure_material":"土蔵造及び木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0099","desc":"敷地中央に南北棟で建つ。土蔵造の麹室・作業場と木造の検定室からなり、切妻屋根をかける。麹室は内壁と天井を板張として、板裏に籾殻を詰め、西面二箇所、東面一箇所に採光の硝子窓、天井に換気口一箇所を設ける。伝統的な醸造業に欠かせない施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012668"},{"id":"00012667","register_sub_id":"101","register_pk":"367961","name":"古澤醸造店舗兼主屋","kana":"ふるさわじょうぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"大正2年頃／大正12年頃増築、平成15年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積245㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0098","desc":"大堂津中心部の街路に西面して建つ。寄棟造二階建の一階正面は黒漆喰塗大壁で、戸袋も塗込めた重厚なつくりとする。南側は入母屋造平屋建の座敷棟で正面北端に玄関を構え、創意ある意匠の座敷や便所、浴室を配する。醸造業で栄えた町の様相を伝える大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012667"},{"id":"00012671","register_sub_id":"101","register_pk":"367965","name":"古澤醸造二号蔵","kana":"ふるさわじょうぞうにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":33.29920833,"lng":130.22647778,"geo_status":"db","era":"明治後期／昭和50年代・平成15年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0102","desc":"一号蔵の北側、敷地北面に建つ。土蔵造二階建、東西棟の切妻造で、南面に戸口を開く。太い柱を半間毎に立てて貫で固め、大径梁で二階床組をつくる。小屋組はキングポストトラスである。一号蔵と同様の焼酎の仕込蔵で、敷地内醸造施設の中核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012671"},{"id":"00012669","register_sub_id":"101","register_pk":"367963","name":"古澤醸造瓶詰操作場","kana":"ふるさわじょうぞうびんづめそうさじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0100","desc":"店舗兼主屋背面に南面して建つ。土蔵造平屋建、切妻造桟瓦葺で、柱を半間毎に立て、小屋組を和小屋とする。外壁は漆喰塗の腰モルタル塗で、戸口上部のペディメントなど意匠を凝らす。醸造業の近代化を示す建物で、敷地内醸造施設のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012669"},{"id":"00013905","register_sub_id":"101","register_pk":"507863","name":"宮田本店石蔵","kana":"みやたほんてんいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4737-1他","lat":31.55575,"lng":131.37972222,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積261㎡、袖塀及び門柱付","structure_material":"石造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"45 － 0111","desc":"日向灘に近い大堂津の通り沿いに建つ醤油蔵。切石積に寄棟造桟瓦葺の屋根を載せ、前方に切石積の袖塀と門柱を設ける。正面に欠円アーチの出入口を二連並べ、内部は一室で石造の仕込用タンクを据える。小屋はトラス。醸造の盛んな大堂津の歴史的風致を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013905"},{"id":"00006956","register_sub_id":"101","register_pk":"107938","name":"九州電力大田発電所本館","kana":"きゅうしゅうでんりょくおおたはつでんしょほんかん","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県日置市伊集院町大田字管田3109-1","lat":31.63293776,"lng":130.36798864,"geo_status":"db","era":"明治41／昭和28改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積188㎡、塔屋付","structure_material":"石造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"46 － 0061","desc":"神之川の中流左岸に位置する水力発電所施設。桁行１５ｍ梁間１２ｍ規模の石造平屋建で、南隅部に八角形塔屋を張り出し、妻面には島津家の家紋をあしらう特徴的な外観。鹿児島の近代化に貢献した島津家の経営に係る鉱山に関連する施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006956"},{"id":"00002346","register_sub_id":"101","register_pk":"103336","name":"白金酒造石蔵","kana":"しらかねしゅぞういしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市脇元1943-1","lat":31.70117808,"lng":130.61433241,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"石造、瓦葺、建築面積222㎡","structure_material":"石造","registered":"2001.08.28(平成13.08.28)","register_no":"46 － 0010","desc":"明治２年創業の造り酒屋の仕込蔵。ＪＲ日豊本線重富駅の南方，国道１０号線に西面して建つ。切妻造，桟瓦葺，もと平入の木骨石造蔵で，県内に数多く残る凝灰岩系石蔵のひとつであるが，石目地を極力薄くして精巧に積みあげている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002346"},{"id":"00006561","register_sub_id":"101","register_pk":"107544","name":"丁子屋石蔵","kana":"ちょうじやいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県南さつま市加世田唐仁原6026","lat":31.42684222,"lng":130.29519051,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造平屋建、瓦葺、建築面積65㎡","structure_material":"石造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0040","desc":"道路に面して建つ。桁行１０ｍ，梁間６ｍの規模で，石造平屋建，切妻造，瓦葺，妻入とする。内部を１室とし，小屋組は陸梁の中央に束を立て，梁端部近くから登梁を架け，凝灰岩の切石は成，厚み共に１尺で，堅牢な外観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006561"},{"id":"00005212","register_sub_id":"101","register_pk":"106202","name":"旧東洋製糖北大東出張所","kana":"きゅうとうようせいとうきただいとうしゅっちょうじょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港29-1","lat":25.95424454,"lng":131.28637095,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造一部鉄筋コンクリート造平屋建、建築面積712㎡","structure_material":"石造一部鉄筋コンクリート造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"47 － 0008","desc":"海を望む島西北部の高台に建つ。建物の角をコンクリートで固め，壁面を石灰岩の布積で築いた凹形平面の建築物で，玄関ポーチにはＲＣ造の列柱を配する。事務所と売店を収容した燐鉱事業の拠点となった施設で，北大東島の近代産業繁栄の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005212"},{"id":"00005800","register_sub_id":"101","register_pk":"106788","name":"旧東洋製糖燐鉱石貯蔵庫","kana":"きゅうとうようせいとうりんこうせきちょぞうこ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港81-11","lat":25.954002,"lng":131.28511,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造及び鉄筋コンクリート造、面積2358㎡","structure_material":"石造及び鉄筋コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"47 － 0022","desc":"島西北部の高台に位置する。島内で採掘した燐鉱石を，集約的に貯蔵するために築かれた施設。延長約４０ｍの石造壁体に，４本の軌道用鉄筋コンクリート造トンネルが貫通するつくり。石灰岩を，乱積により巧みに積み上げた大規模な石造壁体が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005800"},{"id":"00005801","register_sub_id":"101","register_pk":"106789","name":"旧東洋製糖燐鉱石積荷桟橋","kana":"きゅうとうようせいとうりんこうせきつみにさんばし","category":"産業2次","subcategory":"土木構造物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港地先","lat":25.953951,"lng":131.284134,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造、延長18m","structure_material":"鉄筋コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"47 － 0023","desc":"燐鉱石貯蔵庫より約５０ｍ西方に位置する。石灰岩よりなる岸壁から突き出た延長１８ｍの鉄筋コンクリート造構造物で，天端に２列の溝を設けて，２本の軌道を引き込むつくりとする。燐鉱採掘関連施設のひとつで，北大東島の近代産業繁栄の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005801"},{"id":"00009694","register_sub_id":"101","register_pk":"194690","name":"旧西中共同製糖場煙突","kana":"きゅうにしなかきょうどうせいとうじょうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県宮古島市城辺字西里添西底原621-6","lat":24.75545111,"lng":125.36269701,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"煉瓦造、高さ13m","structure_material":"煉瓦造","registered":"2013.06.21(平成25.06.21)","register_no":"47 － 0081","desc":"サトウキビ畑の中に建つ煉瓦煙突。基部の平面は二・七メートル角で、高さは一三メートル、煉瓦造、イギリス積で、東西面の基部に欠円アーチの煙道を残す。宮古島の伝統産業である製糖業を象徴する煙突で、県内でも希少な昭和前期の製糖工場の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009694"}];
